## 1. Habit model

```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completedDates: Set<String>

    init(id: UUID = UUID(), name: String, completedDates: Set<String> = []) {
        self.id = id
        self.name = name
        self.completedDates = completedDates
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        completedDates.contains(Habit.dateString(from: date))
    }

    mutating func toggleCompletion(for date: Date = Date()) {
        let key = Habit.dateString(from: date)
        if completedDates.contains(key) {
            completedDates.remove(key)
        } else {
            completedDates.insert(key)
        }
    }

    func currentStreak() -> Int {
        var streak = 0
        let calendar = Calendar.current
        var date = Date()

        while completedDates.contains(Habit.dateString(from: date)) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: date) else {
                break
            }
            date = previousDay
        }

        return streak
    }

    static func dateString(from date: Date) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        formatter.timeZone = TimeZone.current
        return formatter.string(from: date)
    }
}
```

## 2. View model

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let storageKey = "habits_storage_key"

    init() {
        loadHabits()
    }

    func addHabit(name: String) {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        habits.append(Habit(name: trimmed))
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleHabitCompletion(_ habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index].toggleCompletion(for: Date())
    }

    private func saveHabits() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: storageKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: storageKey) else { return }
        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
        }
    }
}
```

