Below is a minimal native iOS habit-tracking app written in Swift using SwiftUI and SwiftData. It supports:

- Creating habits
- Marking a habit as completed for today
- Viewing streak count
- Deleting habits

If you want, I can next expand this into a fuller app with reminders, calendar history, categories, widgets, and iCloud sync.

```swift
import SwiftUI
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completionDates: [Date]

    init(name: String, createdAt: Date = Date(), completionDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completionDates.contains { calendar.isDateInToday($0) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let index = completionDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }

    func streak(calendar: Calendar = .current) -> Int {
        let normalizedDates = Set(completionDates.map { calendar.startOfDay(for: $0) })
        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        while normalizedDates.contains(currentDay) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDay) else { break }
            currentDay = previousDay
        }

        return streak
    }
}

@main
struct HabitTrackerApp: App {
    var body: some Scene {
        WindowGroup {
            HabitListView()
        }
        .modelContainer(for: Habit.self)
    }
}

struct HabitListView: View {
    @Environment(\.modelContext) private var modelContext
    @Query(sort: \Habit.createdAt, order: .reverse) private var habits: [Habit]
    @State private var newHabitName = ""

    var body: some View {
        NavigationStack {
            VStack(spacing: 16) {
                HStack {
                    TextField("Enter habit name", text: $newHabitName)
                        .textFieldStyle(.roundedBorder)

                    Button("Add") {
                        addHabit()
                    }
                    .buttonStyle(.borderedProminent)
                    .disabled(newHabitName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
                .padding(.horizontal)

                if habits.isEmpty {
                    ContentUnavailableView(
                        "No Habits Yet",
                        systemImage: "checklist",
                        description: Text("Add your first habit to get started.")
                    )
                } else {
                    List {
                        ForEach(habits) { habit in
                            HabitRowView(habit: habit)
                        }
                        .onDelete(perform: deleteHabits)
                    }
                }
            }
            .navigationTitle("Habit Tracker")
        }
    }

    private func addHabit() {
        let trimmed = newHabitName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }

        let habit = Habit(name: trimmed)
        modelContext.insert(habit)
        newHabitName = ""
    }

    private func deleteHabits(at offsets: IndexSet) {
        for index in offsets {
            modelContext.delete(habits[index])
        }
    }
}

struct HabitRowView: View {
    @Bindable var habit: Habit

    var body: some View {
        HStack {
            VStack(alignment: .leading, spacing: 4) {
                Text(habit.name)
                    .font(.headline)

                Text("Streak: \(habit.streak()) day\(habit.streak() == 1 ? "" : "s")")
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            Button {
                habit.toggleToday()
            } label: {
                Image(systemName: habit.isCompletedToday() ? "checkmark.circle.fill" : "circle")
                    .font(.title2)
                    .foregroundStyle(habit.isCompletedToday() ? .green : .gray)
            }
            .buttonStyle(.plain)
        }
        .padding(.vertical, 4)
    }
}
```

