Below is a complete SwiftUI app for a native iOS habit tracker using SwiftData. Paste into a new Xcode project (iOS App, SwiftUI, SwiftData enabled) and run.

```swift
import SwiftUI
import SwiftData

@Model
final class Habit {
    var name: String
    var details: String
    var createdAt: Date
    var completions: [HabitCompletion]

    init(name: String, details: String = "", createdAt: Date = .now) {
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.completions = []
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { calendar.isDate($0.date, inSameDayAs: date) }
    }

    func toggleCompletion(on date: Date, context: ModelContext, calendar: Calendar = .current) {
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            context.delete(existing)
        } else {
            let completion = HabitCompletion(date: date, habit: self)
            completions.append(completion)
            context.insert(completion)
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        var streak = 0
        var date = calendar.startOfDay(for: .now)

        while isCompleted(on: date, calendar: calendar) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else { break }
            date = previous
        }

        return streak
    }
}

@Model
final class HabitCompletion {
    var date: Date
    var habit: Habit?

    init(date: Date, habit: Habit? = nil) {
        self.date = date
        self.habit = habit
    }
}

@main
struct HabitTrackerApp: App {
    var body: some Scene {
        WindowGroup {
            HabitListView()
        }
        .modelContainer(for: [Habit.self, HabitCompletion.self])
    }
}

struct HabitListView: View {
    @Environment(\.modelContext) private var context
    @Query(sort: \Habit.createdAt) private var habits: [Habit]
    @State private var showingAddHabit = false

    var body: some View {
        NavigationStack {
            List {
                if habits.isEmpty {
                    ContentUnavailableView(
                        "No Habits Yet",
                        systemImage: "checklist",
                        description: Text("Tap the + button to create your first habit.")
                    )
                } else {
                    ForEach(habits) { habit in
                        NavigationLink(value: habit) {
                            HabitRowView(habit: habit)
                        }
                    }
                    .onDelete(perform: deleteHabits)
                }
            }
            .navigationTitle("Habits")
            .navigationDestination(for: Habit.self) { habit in
                HabitDetailView(habit: habit)
            }
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    EditButton()
                }
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        showingAddHabit = true
                    } label: {
                        Image(systemName: "plus")
                    }
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView()
            }
        }
    }

    private func deleteHabits(at offsets: IndexSet) {
        for index in offsets {
            context.delete(habits[index])
        }
    }
}

struct HabitRowView: View {
    @Environment(\.modelContext) private var context
    let habit: Habit

    var body: some View {
        HStack {
            Button {
                habit.toggleCompletion(on: .now, context: context)
            } label: {
                Image(systemName: habit.isCompleted(on: .now) ? "checkmark.circle.fill" : "circle")
                    .font(.title2)
                    .foregroundStyle(habit.isCompleted(on: .now) ? .green : .secondary)
            }
            .buttonStyle(.plain)

            VStack(alignment: .leading, spacing: 4) {
                Text(habit.name)
                    .font(.headline)

                if !habit.details.isEmpty {
                    Text(habit.details)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }

                Text("Streak: \(habit.currentStreak()) day\(habit.currentStreak() == 1 ? "" : "s")")
                    .font(.caption)
                    .foregroundStyle(.orange)
            }

            Spacer()
        }
        .padding(.vertical, 4)
    }
}

struct HabitDetailView: View {
    @Environment(\.modelContext) private var context
    let habit: Habit

    var body: some View {
        List {
            Section("Details") {
                LabeledContent("Name", value: habit.name)

                if !habit.details.isEmpty {
                    VStack(alignment: .leading, spacing: 6) {
                        Text("Notes")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        Text(habit.details)
                    }
                }

                LabeledContent("Current Streak", value: "\(habit.currentStreak())")
                LabeledContent("Completed Today", value: habit.isCompleted(on: .now) ? "Yes" : "No")
            }

            Section("Actions") {
                Button(habit.isCompleted(on: .now) ? "Mark Incomplete Today" : "Mark Complete Today") {
                    habit.toggleCompletion(on: .now, context: context)
                }
            }

            Section("Recent Completions") {
                let sorted = habit.completions.sorted { $0.date > $1.date }

                if sorted.isEmpty {
                    Text("No completions yet")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(sorted.prefix(30)) { completion in
                        Text(completion.date.formatted(date: .abbreviated, time: .omitted))
                    }
                }
            }
        }
        .navigationTitle(habit.name)
        .navigationBarTitleDisplayMode(.inline)
    }
}

struct AddHabitView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var context

    @State private var name = ""
    @State private var details = ""

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit Info") {
                    TextField("Habit name", text: $name)
                    TextField("Details or notes", text: $details, axis: .vertical)
                        .lineLimit(3...6)
                }
            }
            .navigationTitle("New Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        let habit = Habit(name: name.trimmingCharacters(in: .whitespacesAndNewlines),
                                          details: details.trimmingCharacters(in: .whitespacesAndNewlines))
                        context.insert(habit)
                        dismiss()
                    }
                    .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
    }
}
```

