## 2. `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var detail: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        detail: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completedDates.contains { calendar.isDateInToday($0) }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let normalized = Set(completedDates.map { calendar.startOfDay(for: $0) })
        guard !normalized.isEmpty else { return 0 }

        var streak = 0
        var date = calendar.startOfDay(for: Date())

        while normalized.contains(date) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else {
                break
            }
            date = previous
        }

        return streak
    }

    func totalCompletions() -> Int {
        let calendar = Calendar.current
        let normalized = Set(completedDates.map { calendar.startOfDay(for: $0) })
        return normalized.count
    }
}
```

