## 3. `HabitStore.swift`

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            save()
        }
    }

    private let storageKey = "habit_tracker_habits"

    init() {
        load()
    }

    func addHabit(name: String, detail: String) {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedDetail = detail.trimmingCharacters(in: .whitespacesAndNewlines)

        guard !trimmedName.isEmpty else { return }

        let habit = Habit(name: trimmedName, detail: trimmedDetail)
        habits.append(habit)
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleTodayCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if habits[index].completedDates.contains(where: { calendar.isDate($0, inSameDayAs: today) }) {
            habits[index].completedDates.removeAll { calendar.isDate($0, inSameDayAs: today) }
        } else {
            habits[index].completedDates.append(today)
        }
    }

    private func save() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: storageKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func load() {
        guard let data = UserDefaults.standard.data(forKey: storageKey) else { return }

        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
            habits = []
        }
    }
}
```

