# 2. Habit model

## `Models/Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completedDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let uniqueDays = uniqueCompletionDays(calendar: calendar).sorted(by: >)
        guard !uniqueDays.isEmpty else { return 0 }

        let today = calendar.startOfDay(for: Date())
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!

        var streak = 0
        var expectedDate: Date?

        if calendar.isDate(uniqueDays[0], inSameDayAs: today) {
            expectedDate = today
        } else if calendar.isDate(uniqueDays[0], inSameDayAs: yesterday) {
            expectedDate = yesterday
        } else {
            return 0
        }

        for day in uniqueDays {
            guard let expected = expectedDate else { break }

            if calendar.isDate(day, inSameDayAs: expected) {
                streak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expected)
            } else if day < expected {
                break
            }
        }

        return streak
    }

    private func uniqueCompletionDays(calendar: Calendar) -> [Date] {
        let normalized = completedDates.map { calendar.startOfDay(for: $0) }
        return Array(Set(normalized))
    }
}
```

