## `ViewModels/HabitStore.swift`

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let habitsKey = "saved_habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String, details: String) {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedDetails = details.trimmingCharacters(in: .whitespacesAndNewlines)

        guard !trimmedName.isEmpty else { return }

        let newHabit = Habit(name: trimmedName, details: trimmedDetails)
        habits.append(newHabit)
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleCompletion(for habit: Habit, on date: Date = Date(), calendar: Calendar = .current) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let isAlreadyCompleted = habits[index].completedDates.contains {
            calendar.isDate($0, inSameDayAs: date)
        }

        if isAlreadyCompleted {
            habits[index].completedDates.removeAll {
                calendar.isDate($0, inSameDayAs: date)
            }
        } else {
            habits[index].completedDates.append(date)
        }
    }

    private func saveHabits() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: habitsKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: habitsKey) else { return }

        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
            habits = []
        }
    }
}
```

