## `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var notes: String
    var createdAt: Date
    var completions: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        notes: String = "",
        createdAt: Date = Date(),
        completions: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.notes = notes
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompletedToday(calendar: Calendar = .current) -> Bool {
        completions.contains { calendar.isDateInToday($0) }
    }

    func toggleToday(calendar: Calendar = .current) {
        if let index = completions.firstIndex(where: { calendar.isDateInToday($0) }) {
            completions.remove(at: index)
        } else {
            completions.append(Date())
        }
    }

    func currentStreak(calendar: Calendar = .current) -> Int {
        let normalizedDays = Set(
            completions.map { calendar.startOfDay(for: $0) }
        )

        guard !normalizedDays.isEmpty else { return 0 }

        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while normalizedDays.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else {
                break
            }
            day = previous
        }

        return streak
    }
}
```

