### 2. `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completedDates: [String]

    init(id: UUID = UUID(), name: String, completedDates: [String] = []) {
        self.id = id
        self.name = name
        self.completedDates = completedDates
    }

    func isCompletedToday() -> Bool {
        completedDates.contains(Self.todayString())
    }

    func streak() -> Int {
        let formatter = Self.dateFormatter
        let calendar = Calendar.current
        let dates = completedDates.compactMap { formatter.date(from: $0) }.sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        let completedSet = Set(completedDates)

        while true {
            let key = formatter.string(from: currentDate)
            if completedSet.contains(key) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
                currentDate = previous
            } else {
                break
            }
        }

        return streak
    }

    static func todayString() -> String {
        dateFormatter.string(from: Date())
    }

    static let dateFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter
    }()
}
```

