package com.example.bankingapp.data

import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.TransactionType
import com.example.bankingapp.model.User
import kotlinx.coroutines.delay

class BankingRepository {

    private val fakeUser = User(
        username = "demo",
        fullName = "Alex Johnson"
    )

    private var fakeAccount = Account(
        id = "ACC-1001",
        accountName = "Checking Account",
        balance = 2450.75,
        currency = "USD"
    )

    private val fakeTransactions = mutableListOf(
        Transaction("T1", "Coffee Shop", -4.50, "2026-09-10", TransactionType.DEBIT),
        Transaction("T2", "Payroll Deposit", 1500.00, "2026-09-09", TransactionType.CREDIT),
        Transaction("T3", "Electric Bill", -120.99, "2026-09-07", TransactionType.DEBIT),
        Transaction("T4", "Grocery Store", -86.42, "2026-09-06", TransactionType.DEBIT)
    )

    suspend fun login(username: String, password: String): Result<User> {
        delay(800)
        return if (username == "demo" && password == "password123") {
            Result.success(fakeUser)
        } else {
            Result.failure(Exception("Invalid credentials"))
        }
    }

    suspend fun getAccount(): Account {
        delay(300)
        return fakeAccount
    }

    suspend fun getTransactions(): List<Transaction> {
        delay(300)
        return fakeTransactions.toList()
    }

    suspend fun transfer(amount: Double, recipient: String): Result<Unit> {
        delay(700)

        if (recipient.isBlank()) {
            return Result.failure(Exception("Recipient is required"))
        }

        if (amount <= 0) {
            return Result.failure(Exception("Amount must be greater than zero"))
        }

        if (amount > fakeAccount.balance) {
            return Result.failure(Exception("Insufficient funds"))
        }

        fakeAccount = fakeAccount.copy(balance = fakeAccount.balance - amount)
        fakeTransactions.add(
            0,
            Transaction(
                id = "T${System.currentTimeMillis()}",
                title = "Transfer to $recipient",
                amount = -amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )

        return Result.success(Unit)
    }
}
