## 4. `viewmodel/BankingViewModel.kt`

```kotlin
package com.example.bankingapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.BankingRepository
import com.example.bankingapp.model.Account
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.User
import kotlinx.coroutines.launch

sealed class ScreenState {
    object Login : ScreenState()
    object Dashboard : ScreenState()
    object Transfer : ScreenState()
}

class BankingViewModel : ViewModel() {

    private val repository = BankingRepository()

    var screenState by mutableStateOf<ScreenState>(ScreenState.Login)
        private set

    var isLoading by mutableStateOf(false)
        private set

    var loginError by mutableStateOf<String?>(null)
        private set

    var transferMessage by mutableStateOf<String?>(null)
        private set

    var currentUser by mutableStateOf<User?>(null)
        private set

    var account by mutableStateOf<Account?>(null)
        private set

    var transactions by mutableStateOf<List<Transaction>>(emptyList())
        private set

    fun login(username: String, password: String) {
        isLoading = true
        loginError = null

        viewModelScope.launch {
            val result = repository.login(username, password)
            isLoading = false

            result.onSuccess { user ->
                currentUser = user
                loadDashboard()
                screenState = ScreenState.Dashboard
            }.onFailure {
                loginError = it.message
            }
        }
    }

    fun loadDashboard() {
        viewModelScope.launch {
            account = repository.getAccount()
            transactions = repository.getTransactions()
        }
    }

    fun goToTransfer() {
        transferMessage = null
        screenState = ScreenState.Transfer
    }

    fun goToDashboard() {
        transferMessage = null
        screenState = ScreenState.Dashboard
        loadDashboard()
    }

    fun transfer(amountText: String, recipient: String) {
        val amount = amountText.toDoubleOrNull()
        if (amount == null) {
            transferMessage = "Enter a valid amount"
            return
        }

        isLoading = true
        transferMessage = null

        viewModelScope.launch {
            val result = repository.transfer(amount, recipient)
            isLoading = false

            result.onSuccess {
                transferMessage = "Transfer successful"
                loadDashboard()
                screenState = ScreenState.Dashboard
            }.onFailure {
                transferMessage = it.message
            }
        }
    }

    fun logout() {
        currentUser = null
        account = null
        transactions = emptyList()
        loginError = null
        transferMessage = null
        screenState = ScreenState.Login
    }
}
```

