            currency = "USD"
        )
    )

    private val transactions = mutableListOf(
        TransactionItem(
            id = "t1",
            accountId = "1",
            title = "Coffee Shop",
            amount = -5.75,
            date = "2026-09-10",
            type = TransactionType.DEBIT
        ),
        TransactionItem(
            id = "t2",
            accountId = "1",
            title = "Payroll",
            amount = 2200.00,
            date = "2026-09-09",
            type = TransactionType.CREDIT
        ),
        TransactionItem(
            id = "t3",
            accountId = "2",
            title = "Interest",
            amount = 15.20,
            date = "2026-09-08",
            type = TransactionType.CREDIT
        )
    )

    fun login(username: String, password: String): Boolean {
        val success = username.isNotBlank() && password == "password123"
        if (success) {
            loggedInUser = User(username)
        }
        return success
    }

    fun logout() {
        loggedInUser = null
    }

    fun getCurrentUser(): User? = loggedInUser

    fun getAccounts(): List<Account> = accounts.toList()

    fun getTransactionsForAccount(accountId: String): List<TransactionItem> {
        return transactions.filter { it.accountId == accountId }
    }

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Result<Unit> {
        if (fromAccountId == toAccountId) {
            return Result.failure(IllegalArgumentException("Cannot transfer to the same account"))
        }
        if (amount <= 0.0) {
            return Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }

        val fromIndex = accounts.indexOfFirst { it.id == fromAccountId }
        val toIndex = accounts.indexOfFirst { it.id == toAccountId }

        if (fromIndex == -1 || toIndex == -1) {
            return Result.failure(IllegalArgumentException("Account not found"))
        }

        val from = accounts[fromIndex]
        val to = accounts[toIndex]

        if (from.balance < amount) {
            return Result.failure(IllegalArgumentException("Insufficient funds"))
        }

        accounts[fromIndex] = from.copy(balance = from.balance - amount)
        accounts[toIndex] = to.copy(balance = to.balance + amount)

        transactions.add(
            0,
            TransactionItem(
                id = "t_from_${System.currentTimeMillis()}",
                accountId = fromAccountId,
                title = "Transfer to ${to.name}",
                amount = -amount,
                date = "2026-09-16",
                type = TransactionType.DEBIT
            )
        )
        transactions.add(
            0,
            TransactionItem(
                id = "t_to_${System.currentTimeMillis()}",
                accountId = toAccountId,
                title = "Transfer from ${from.name}",
                amount = amount,
                date = "2026-09-16",
                type = TransactionType.CREDIT
            )
        )

        return Result.success(Unit)
    }
}
