package com.example.bankingapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.TransactionItem
import com.example.bankingapp.data.repository.FakeBankRepository

class BankViewModel : ViewModel() {

    private val repository = FakeBankRepository()

    var isLoggedIn by mutableStateOf(false)
        private set

    var loginError by mutableStateOf<String?>(null)
        private set

    var accounts by mutableStateOf<List<Account>>(emptyList())
        private set

    var selectedAccountId by mutableStateOf<String?>(null)
        private set

    var transactions by mutableStateOf<List<TransactionItem>>(emptyList())
        private set

    var transferMessage by mutableStateOf<String?>(null)
        private set

    fun login(username: String, password: String) {
        val success = repository.login(username, password)
        if (success) {
            isLoggedIn = true
            loginError = null
            loadAccounts()
        } else {
            loginError = "Invalid username or password"
        }
    }

    fun logout() {
        repository.logout()
        isLoggedIn = false
        accounts = emptyList()
        transactions = emptyList()
        selectedAccountId = null
    }

    fun loadAccounts() {
        accounts = repository.getAccounts()
        if (selectedAccountId == null && accounts.isNotEmpty()) {
            selectAccount(accounts.first().id)
        }
    }

    fun selectAccount(accountId: String) {
        selectedAccountId = accountId
        transactions = repository.getTransactionsForAccount(accountId)
    }

    fun transfer(fromAccountId: String, toAccountId: String, amountText: String) {
        val amount = amountText.toDoubleOrNull()
        if (amount == null) {
            transferMessage = "Enter a valid amount"
            return
        }

        val result = repository.transfer(fromAccountId, toAccountId, amount)
        result.onSuccess {
            transferMessage = "Transfer successful"
            loadAccounts()
            selectAccount(fromAccountId)
        }.onFailure {
            transferMessage = it.message
        }
    }

    fun clearTransferMessage() {
        transferMessage = null
    }
}
