package com.example.bankingapp.ui.navigation

import androidx.compose.runtime.Composable
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.bankingapp.ui.screens.DashboardScreen
import com.example.bankingapp.ui.screens.LoginScreen
import com.example.bankingapp.ui.screens.TransferScreen
import com.example.bankingapp.viewmodel.BankViewModel

object Routes {
    const val LOGIN = "login"
    const val DASHBOARD = "dashboard"
    const val TRANSFER = "transfer"
}

@Composable
fun AppNav(viewModel: BankViewModel) {
    val navController = rememberNavController()
    val startDestination = if (viewModel.isLoggedIn) Routes.DASHBOARD else Routes.LOGIN

    NavHost(navController = navController, startDestination = startDestination) {
        composable(Routes.LOGIN) {
            LoginScreen(
                error = viewModel.loginError,
                onLogin = { username, password ->
                    viewModel.login(username, password)
                    if (viewModel.isLoggedIn) {
                        navController.navigate(Routes.DASHBOARD) {
                            popUpTo(Routes.LOGIN) { inclusive = true }
                        }
                    }
                }
            )
        }

        composable(Routes.DASHBOARD) {
            DashboardScreen(
                accounts = viewModel.accounts,
                selectedAccountId = viewModel.selectedAccountId,
                transactions = viewModel.transactions,
                onSelectAccount = viewModel::selectAccount,
                onTransferClick = {
                    navController.navigate(Routes.TRANSFER)
                },
                onLogout = {
                    viewModel.logout()
                    navController.navigate(Routes.LOGIN) {
                        popUpTo(Routes.DASHBOARD) { inclusive = true }
                    }
                }
            )
        }

        composable(Routes.TRANSFER) {
            TransferScreen(
                accounts = viewModel.accounts,
                message = viewModel.transferMessage,
                onTransfer = { fromId, toId, amount ->
                    viewModel.transfer(fromId, toId, amount)
                },
                onDismissMessage = viewModel::clearTransferMessage,
                onBack = {
                    navController.popBackStack()
                }
            )
        }
    }
}
