```kotlin
package com.example.bankingapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.repository.BankingRepository

class BankingViewModel(
    private val repository: BankingRepository = BankingRepository()
) : ViewModel() {

    var accounts by mutableStateOf<List<Account>>(emptyList())
        private set

    var selectedAccount by mutableStateOf<Account?>(null)
        private set

    var transactions by mutableStateOf<List<Transaction>>(emptyList())
        private set

    var transferMessage by mutableStateOf<String?>(null)
        private set

    var transferError by mutableStateOf<String?>(null)
        private set

    init {
        loadAccounts()
    }

    fun loadAccounts() {
        accounts = repository.getAccounts()
        if (accounts.isNotEmpty()) {
            selectAccount(accounts.first())
        }
    }

    fun selectAccount(account: Account) {
        selectedAccount = account
        transactions = repository.getTransactions(account.id)
    }

    fun transfer(toAccountNumber: String, amount: Double) {
        val fromAccount = selectedAccount ?: run {
            transferError = "No account selected"
            return
        }

        transferMessage = null
        transferError = null

        val result = repository.transfer(
            fromAccountId = fromAccount.id,
            toAccountNumber = toAccountNumber,
            amount = amount
        )

        result.onSuccess {
            transferMessage = it
        }.onFailure {
            transferError = it.message
        }
    }

    fun clearTransferStatus() {
        transferMessage = null
        transferError = null
    }
}
