package com.example.bankingapp

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel

data class Transaction(
    val type: String,
    val amount: Double,
    val description: String
)

class BankViewModel : ViewModel() {
    var isLoggedIn by mutableStateOf(false)
        private set

    var username by mutableStateOf("")
        private set

    var balance by mutableStateOf(1250.00)
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction("Deposit", 1500.00, "Initial deposit"),
            Transaction("Withdrawal", 250.00, "Groceries")
        )
    )
        private set

    fun login(inputUsername: String, inputPassword: String): Boolean {
        val success = inputUsername.isNotBlank() && inputPassword == "password"
        if (success) {
            username = inputUsername
            isLoggedIn = true
        }
        return success
    }

    fun transfer(recipient: String, amountText: String): String {
        val amount = amountText.toDoubleOrNull()
            ?: return "Invalid amount"

        if (recipient.isBlank()) return "Recipient required"
        if (amount <= 0) return "Amount must be greater than zero"
        if (amount > balance) return "Insufficient funds"

        balance -= amount
        transactions = listOf(
            Transaction("Transfer", amount, "Sent to $recipient")
        ) + transactions

        return "Transfer successful"
    }

    fun logout() {
        isLoggedIn = false
        username = ""
    }
}
