## src/surveyService.ts

```ts
import { getDb } from './db';
import { Survey } from './models';

export function listSurveys(): Survey[] {
  const db = getDb();
  return db.getAllSync<Survey>('SELECT * FROM surveys ORDER BY updatedAt DESC');
}

export function saveSurvey(input: Omit<Survey, 'updatedAt' | 'synced'>) {
  const db = getDb();
  const updatedAt = Date.now();

  db.withTransactionSync(() => {
    db.runSync(
      `
      INSERT INTO surveys (id, title, location, notes, updatedAt, synced)
      VALUES (?, ?, ?, ?, ?, 0)
      ON CONFLICT(id) DO UPDATE SET
        title = excluded.title,
        location = excluded.location,
        notes = excluded.notes,
        updatedAt = excluded.updatedAt,
        synced = 0
      `,
      [input.id, input.title, input.location, input.notes, updatedAt]
    );

    db.runSync(
      `
      INSERT INTO outbox (entityId, operation, payload, createdAt)
      VALUES (?, 'upsert', ?, ?)
      `,
      [input.id, JSON.stringify({ ...input, updatedAt, synced: 0 }), updatedAt]
    );
  });
}

export function deleteSurvey(id: string) {
  const db = getDb();
  const createdAt = Date.now();

  db.withTransactionSync(() => {
    db.runSync(`DELETE FROM surveys WHERE id = ?`, [id]);
    db.runSync(
      `
      INSERT INTO outbox (entityId, operation, payload, createdAt)
      VALUES (?, 'delete', ?, ?)
      `,
      [id, JSON.stringify({ id }), createdAt]
    );
  });
}

export function markSurveySynced(id: string) {
  const db = getDb();
  db.runSync(`UPDATE surveys SET synced = 1 WHERE id = ?`, [id]);
}

export function upsertLocalSurveyFromRemote(survey: Survey) {
  const db = getDb();
  const existing = db.getFirstSync<Survey>(
    `SELECT * FROM surveys WHERE id = ?`,
    [survey.id]
  );

  if (!existing || existing.updatedAt <= survey.updatedAt) {
    db.runSync(
      `
      INSERT INTO surveys (id, title, location, notes, updatedAt, synced)
      VALUES (?, ?, ?, ?, ?, 1)
      ON CONFLICT(id) DO UPDATE SET
        title = excluded.title,
        location = excluded.location,
        notes = excluded.notes,
        updatedAt = excluded.updatedAt,
        synced = 1
      `,
      [survey.id, survey.title, survey.location, survey.notes, survey.updatedAt]
    );
  }
}
