## src/syncService.ts

```ts
import NetInfo from '@react-native-community/netinfo';
import { getDb } from './db';
import { OutboxItem } from './models';
import {
  deleteSurveyOnServer,
  fetchRemoteSurveys,
  pushSurveyToServer
} from './api';
import {
  markSurveySynced,
  upsertLocalSurveyFromRemote
} from './surveyService';

let syncing = false;

export async function syncIfOnline() {
  if (syncing) return;

  const state = await NetInfo.fetch();
  if (!state.isConnected) return;

  syncing = true;

  try {
    await flushOutbox();
    await pullRemote();
  } finally {
    syncing = false;
  }
}

async function flushOutbox() {
  const db = getDb();
  const items = db.getAllSync<OutboxItem>(
    `SELECT * FROM outbox ORDER BY createdAt ASC`
  );

  for (const item of items) {
    if (item.operation === 'upsert') {
      const survey = JSON.parse(item.payload);
      await pushSurveyToServer(survey);
      markSurveySynced(item.entityId);
    } else if (item.operation === 'delete') {
      await deleteSurveyOnServer(item.entityId);
    }

    db.runSync(`DELETE FROM outbox WHERE id = ?`, [item.id]);
  }
}

async function pullRemote() {
  const remoteSurveys = await fetchRemoteSurveys();
  for (const survey of remoteSurveys) {
    upsertLocalSurveyFromRemote(survey);
  }
}
```

