## App.tsx

```tsx
import React, { useEffect, useState } from 'react';
import {
  Button,
  FlatList,
  SafeAreaView,
  Text,
  TextInput,
  View
} from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { initDb } from './src/db';
import { listSurveys, saveSurvey, deleteSurvey } from './src/surveyService';
import { syncIfOnline } from './src/syncService';
import { Survey } from './src/models';

function generateId() {
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

export default function App() {
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [online, setOnline] = useState(false);

  function refresh() {
    setSurveys(listSurveys());
  }

  useEffect(() => {
    initDb();
    refresh();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const isOnline = !!state.isConnected;
      setOnline(isOnline);
      if (isOnline) {
        syncIfOnline().then(refresh).catch(console.error);
      }
    });

    const timer = setInterval(() => {
      syncIfOnline().then(refresh).catch(console.error);
    }, 10000);

    return () => {
      unsubscribe();
      clearInterval(timer);
    };
  }, []);

  function addSurvey() {
    if (!title.trim() || !location.trim()) return;

    saveSurvey({
      id: generateId(),
      title: title.trim(),
      location: location.trim(),
      notes: notes.trim()
    });

    setTitle('');
    setLocation('');
    setNotes('');
    refresh();
  }

  function removeSurvey(id: string) {
    deleteSurvey(id);
    refresh();
    syncIfOnline().then(refresh).catch(console.error);
  }

  return (
    <SafeAreaView style={{ flex: 1, padding: 16, gap: 12 }}>
      <Text style={{ fontSize: 24, fontWeight: '600' }}>
        Field Survey App
      </Text>
      <Text>Status: {online ? 'Online' : 'Offline'}</Text>

      <View style={{ gap: 8 }}>
        <TextInput
          placeholder="Survey title"
          value={title}
          onChangeText={setTitle}
          style={{ borderWidth: 1, padding: 10, borderRadius: 6 }}
        />
        <TextInput
          placeholder="Location"
          value={location}
          onChangeText={setLocation}
          style={{ borderWidth: 1, padding: 10, borderRadius: 6 }}
        />
        <TextInput
          placeholder="Notes"
          value={notes}
          onChangeText={setNotes}
          multiline
          style={{ borderWidth: 1, padding: 10, borderRadius: 6, minHeight: 80 }}
        />
        <Button title="Save Survey" onPress={addSurvey} />
        <Button
          title="Manual Sync"
          onPress={() => syncIfOnline().then(refresh).catch(console.error)}
        />
      </View>

      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View
            style={{
              padding: 12,
              borderWidth: 1,
              borderRadius: 8,
              marginTop: 10
            }}
          >
            <Text style={{ fontWeight: '700' }}>{item.title}</Text>
            <Text>{item.location}</Text>
            <Text>{item.notes}</Text>
            <Text>
              {item.synced ? 'Synced' : 'Pending sync'} · {new Date(item.updatedAt).toLocaleString()}
            </Text>
            <Button title="Delete" onPress={() => removeSurvey(item.id)} />
          </View>
        )}
      />
    </SafeAreaView>
  );
}
