import { getDb } from "./sqlite";
import { Survey, SyncQueueItem, QueueOperationType } from "../models/survey";

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await getDb();
  return await db.getAllAsync<Survey>(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );
}

export async function getPendingSurveys(): Promise<Survey[]> {
  const db = await getDb();
  return await db.getAllAsync<Survey>(
    `SELECT * FROM surveys WHERE syncStatus IN ('pending', 'failed')`
  );
}

export async function upsertSurvey(survey: Survey): Promise<void> {
  const db = await getDb();
  await db.runAsync(
    `INSERT OR REPLACE INTO surveys
      (id, title, notes, latitude, longitude, createdAt, updatedAt, deletedAt, syncStatus, version)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.notes,
      survey.latitude,
      survey.longitude,
      survey.createdAt,
      survey.updatedAt,
      survey.deletedAt,
      survey.syncStatus,
      survey.version
    ]
  );
}

export async function markSurveySynced(id: string, version: number): Promise<void> {
  const db = await getDb();
  await db.runAsync(
    `UPDATE surveys SET syncStatus = 'synced', version = ?, updatedAt = updatedAt WHERE id = ?`,
    [version, id]
  );
}

export async function markSurveyFailed(id: string): Promise<void> {
  const db = await getDb();
  await db.runAsync(`UPDATE surveys SET syncStatus = 'failed' WHERE id = ?`, [id]);
}

export async function enqueueSyncOperation(
  entityId: string,
  operation: QueueOperationType,
  payload: object
): Promise<void> {
  const db = await getDb();
  await db.runAsync(
    `INSERT INTO sync_queue
      (entityType, entityId, operation, payload, createdAt, retryCount, lastError)
     VALUES (?, ?, ?, ?, ?, 0, NULL)`,
    [
      "survey",
      entityId,
      operation,
      JSON.stringify(payload),
      new Date().toISOString()
    ]
  );
}

export async function getSyncQueue(): Promise<SyncQueueItem[]> {
  const db = await getDb();
  return await db.getAllAsync<SyncQueueItem>(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );
}

export async function removeQueueItem(id: number): Promise<void> {
  const db = await getDb();
  await db.runAsync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function incrementQueueRetry(id: number, error: string): Promise<void> {
  const db = await getDb();
  await db.runAsync(
    `UPDATE sync_queue
     SET retryCount = retryCount + 1, lastError = ?
     WHERE id = ?`,
    [error, id]
  );
}
