# src/services/sync.ts

```ts
import { getSyncQueue, incrementQueueRetry, markSurveyFailed, markSurveySynced, removeQueueItem } from "../db/repositories";
import { pushSurveyToServer } from "./api";
import { isOnline } from "./network";
import { Survey } from "../models/survey";

let syncInProgress = false;

export async function syncPendingData(): Promise<void> {
  if (syncInProgress) return;

  const online = await isOnline();
  if (!online) return;

  syncInProgress = true;

  try {
    const queue = await getSyncQueue();

    for (const item of queue) {
      try {
        if (item.entityType === "survey") {
          const survey = JSON.parse(item.payload) as Survey;
          const result = await pushSurveyToServer(survey);
          await markSurveySynced(survey.id, result.version);
          await removeQueueItem(item.id);
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Unknown sync error";
        await incrementQueueRetry(item.id, message);
        await markSurveyFailed(item.entityId);
      }
    }
  } finally {
    syncInProgress = false;
  }
}
```

