# Recommended next step: deduplicate queue entries

If a survey is edited 5 times offline, you don’t want 5 redundant sync entries in many cases.  
A better approach is:
- keep a single pending queue item per entity
- replace payload with newest state

Example improvement:

```ts
export async function enqueueOrReplaceSyncOperation(
  entityId: string,
  operation: QueueOperationType,
  payload: object
): Promise<void> {
  const db = await getDb();

  const existing = await db.getFirstAsync<{ id: number }>(
    `SELECT id FROM sync_queue WHERE entityId = ? AND entityType = 'survey'`,
    [entityId]
  );

  if (existing?.id) {
    await db.runAsync(
      `UPDATE sync_queue
       SET operation = ?, payload = ?, createdAt = ?, lastError = NULL
       WHERE id = ?`,
      [operation, JSON.stringify(payload), new Date().toISOString(), existing.id]
    );
  } else {
    await db.runAsync(
      `INSERT INTO sync_queue
        (entityType, entityId, operation, payload, createdAt, retryCount, lastError)
       VALUES (?, ?, ?, ?, ?, 0, NULL)`,
      ["survey", entityId, operation, JSON.stringify(payload), new Date().toISOString()]
    );
  }
}
```

