```dart
class SurveyRecord {
  final String id;
  final String title;
  final String notes;
  final double latitude;
  final double longitude;
  final int updatedAt;
  final bool deleted;
  final bool dirty;

  SurveyRecord({
    required this.id,
    required this.title,
    required this.notes,
    required this.latitude,
    required this.longitude,
    required this.updatedAt,
    required this.deleted,
    required this.dirty,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'title': title,
      'notes': notes,
      'latitude': latitude,
      'longitude': longitude,
      'updatedAt': updatedAt,
      'deleted': deleted ? 1 : 0,
      'dirty': dirty ? 1 : 0,
    };
  }

  factory SurveyRecord.fromMap(Map<String, dynamic> map) {
    return SurveyRecord(
      id: map['id'],
      title: map['title'],
      notes: map['notes'],
      latitude: (map['latitude'] as num).toDouble(),
      longitude: (map['longitude'] as num).toDouble(),
      updatedAt: map['updatedAt'],
      deleted: map['deleted'] == 1 || map['deleted'] == true,
      dirty: map['dirty'] == 1 || map['dirty'] == true,
    );
  }

  SurveyRecord copyWith({
    String? id,
    String? title,
    String? notes,
    double? latitude,
    double? longitude,
    int? updatedAt,
    bool? deleted,
    bool? dirty,
  }) {
    return SurveyRecord(
      id: id ?? this.id,
      title: title ?? this.title,
      notes: notes ?? this.notes,
      latitude: latitude ?? this.latitude,
      longitude: longitude ?? this.longitude,
      updatedAt: updatedAt ?? this.updatedAt,
      deleted: deleted ?? this.deleted,
      dirty: dirty ?? this.dirty,
    );
  }
}
