## `lib/services/db_service.dart`

```dart
import 'dart:convert';
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import '../models/survey_record.dart';
import '../models/sync_item.dart';

class DbService {
  static final DbService instance = DbService._internal();
  static Database? _db;

  DbService._internal();

  Future<Database> get database async {
    if (_db != null) return _db!;
    _db = await _initDb();
    return _db!;
  }

  Future<Database> _initDb() async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'field_survey.db');

    return openDatabase(
      path,
      version: 1,
      onCreate: (db, version) async {
        await db.execute('''
          CREATE TABLE surveys (
            id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            notes TEXT NOT NULL,
            latitude REAL NOT NULL,
            longitude REAL NOT NULL,
            updatedAt INTEGER NOT NULL,
            deleted INTEGER NOT NULL,
            dirty INTEGER NOT NULL
          )
        ''');

        await db.execute('''
          CREATE TABLE sync_queue (
            localId INTEGER PRIMARY KEY AUTOINCREMENT,
            entityId TEXT NOT NULL,
            action TEXT NOT NULL,
            payload TEXT NOT NULL,
            createdAt INTEGER NOT NULL,
            synced INTEGER NOT NULL
          )
        ''');
      },
    );
  }

  Future<List<SurveyRecord>> getSurveys() async {
    final db = await database;
    final rows = await db.query(
      'surveys',
      where: 'deleted = ?',
      whereArgs: [0],
      orderBy: 'updatedAt DESC',
    );
    return rows.map((e) => SurveyRecord.fromMap(e)).toList();
  }

  Future<SurveyRecord?> getSurveyById(String id) async {
    final db = await database;
    final rows = await db.query('surveys', where: 'id = ?', whereArgs: [id], limit: 1);
    if (rows.isEmpty) return null;
    return SurveyRecord.fromMap(rows.first);
  }

  Future<void> upsertSurvey(SurveyRecord survey) async {
    final db = await database;
    await db.insert(
      'surveys',
      survey.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  Future<void> saveLocalChange(SurveyRecord survey, String action) async {
    final db = await database;
    await upsertSurvey(survey.copyWith(dirty: true));

    await db.insert('sync_queue', {
      'entityId': survey.id,
      'action': action,
      'payload': jsonEncode(survey.toMap()),
      'createdAt': DateTime.now().millisecondsSinceEpoch,
      'synced': 0,
    });
  }

  Future<List<SyncItem>> getPendingSyncItems() async {
    final db = await database;
    final rows = await db.query(
      'sync_queue',
      where: 'synced = ?',
      whereArgs: [0],
      orderBy: 'createdAt ASC',
    );
    return rows.map((e) => SyncItem.fromMap(e)).toList();
  }

  Future<void> markSyncItemSynced(int localId) async {
    final db = await database;
    await db.update(
      'sync_queue',
      {'synced': 1},
      where: 'localId = ?',
      whereArgs: [localId],
    );
  }

  Future<void> markSurveyClean(String id) async {
    final db = await database;
    await db.update(
      'surveys',
      {'dirty': 0},
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  Future<void> applyServerRecords(List<SurveyRecord> records) async {
    final db = await database;
    final batch = db.batch();

    for (final record in records) {
      batch.insert(
        'surveys',
        record.copyWith(dirty: false).toMap(),
        conflictAlgorithm: ConflictAlgorithm.replace,
      );
    }

    await batch.commit(noResult: true);
  }
}
```

