import 'dart:convert';
import 'package:http/http.dart' as http;
import '../models/survey_record.dart';

class ApiService {
  final String baseUrl;

  ApiService({required this.baseUrl});

  Future<bool> pushChange(Map<String, dynamic> body) async {
    final response = await http.post(
      Uri.parse('$baseUrl/sync/push'),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(body),
    );
    return response.statusCode == 200;
  }

  Future<List<SurveyRecord>> pullRecords(int since) async {
    final response = await http.get(Uri.parse('$baseUrl/sync/pull?since=$since'));

    if (response.statusCode != 200) {
      throw Exception('Failed to pull records');
    }

    final decoded = jsonDecode(response.body) as List<dynamic>;
    return decoded
        .map((e) => SurveyRecord.fromMap(Map<String, dynamic>.from(e)))
        .toList();
  }
}
