## `lib/services/sync_service.dart`

```dart
import 'dart:convert';
import '../models/survey_record.dart';
import 'db_service.dart';
import 'api_service.dart';

class SyncService {
  final DbService db;
  final ApiService api;

  SyncService({
    required this.db,
    required this.api,
  });

  Future<void> sync() async {
    final pending = await db.getPendingSyncItems();

    for (final item in pending) {
      final ok = await api.pushChange({
        'entityId': item.entityId,
        'action': item.action,
        'payload': jsonDecode(item.payload),
      });

      if (ok) {
        if (item.localId != null) {
          await db.markSyncItemSynced(item.localId!);
        }
        await db.markSurveyClean(item.entityId);
      }
    }

    final records = await api.pullRecords(0);
    await db.applyServerRecords(records);
  }

  Future<void> createOrUpdateSurvey(SurveyRecord survey, {required bool isNew}) async {
    await db.saveLocalChange(survey, isNew ? 'create' : 'update');
  }

  Future<void> deleteSurvey(SurveyRecord survey) async {
    final deletedSurvey = survey.copyWith(
      deleted: true,
      dirty: true,
      updatedAt: DateTime.now().millisecondsSinceEpoch,
    );
    await db.saveLocalChange(deletedSurvey, 'delete');
  }
}
```

