## `sync-server/server.js`

```javascript
const express = require('express');

const app = express();
app.use(express.json());

const records = new Map();

app.post('/sync/push', (req, res) => {
  const { entityId, action, payload } = req.body;

  if (!entityId || !action || !payload) {
    return res.status(400).json({ error: 'Invalid request' });
  }

  const existing = records.get(entityId);

  if (!existing || payload.updatedAt >= existing.updatedAt) {
    if (action === 'delete') {
      records.set(entityId, {
        ...payload,
        deleted: true,
      });
    } else {
      records.set(entityId, payload);
    }
  }

  return res.json({ ok: true });
});

app.get('/sync/pull', (req, res) => {
  const since = Number(req.query.since || 0);

  const result = Array.from(records.values()).filter(
    (r) => r.updatedAt >= since
  );

  res.json(result);
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

