import db from './db';
import { SurveyRecord, SyncStatus } from './types';

export function getAllSurveys(): SurveyRecord[] {
  const rows = db.getAllSync('SELECT * FROM surveys ORDER BY updatedAt DESC');
  return rows as SurveyRecord[];
}

export function getPendingSurveys(): SurveyRecord[] {
  const rows = db.getAllSync(
    `SELECT * FROM surveys WHERE syncStatus IN ('pending', 'failed') ORDER BY updatedAt ASC`
  );
  return rows as SurveyRecord[];
}

export function saveSurvey(record: SurveyRecord) {
  db.runSync(
    `INSERT OR REPLACE INTO surveys (id, title, notes, latitude, longitude, updatedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [
      record.id,
      record.title,
      record.notes,
      record.latitude,
      record.longitude,
      record.updatedAt,
      record.syncStatus,
    ]
  );
}

export function updateSurveySyncStatus(id: string, syncStatus: SyncStatus) {
  db.runSync(`UPDATE surveys SET syncStatus = ? WHERE id = ?`, [syncStatus, id]);
}
