## `client/sync.ts`

```ts
import { getPendingSurveys, updateSurveySyncStatus } from './surveyRepo';
import { syncSurveys } from './api';

let syncInProgress = false;

export async function runSync() {
  if (syncInProgress) return;
  syncInProgress = true;

  try {
    const pending = getPendingSurveys();
    if (pending.length === 0) return;

    const result = await syncSurveys(pending);

    const syncedIds: string[] = result.syncedIds ?? [];
    for (const id of syncedIds) {
      updateSurveySyncStatus(id, 'synced');
    }
  } catch (err) {
    const pending = getPendingSurveys();
    for (const record of pending) {
      updateSurveySyncStatus(record.id, 'failed');
    }
    console.error('Sync error:', err);
  } finally {
    syncInProgress = false;
  }
}
```

