# Backend implementation

## `server/src/index.ts`

```ts
import express from 'express';
import cors from 'cors';

type SurveyRecord = {
  id: string;
  title: string;
  notes: string;
  latitude: number | null;
  longitude: number | null;
  updatedAt: string;
  syncStatus: 'pending' | 'synced' | 'failed';
};

const app = express();
app.use(cors());
app.use(express.json());

const store = new Map<string, SurveyRecord>();

app.get('/health', (_req, res) => {
  res.json({ ok: true });
});

app.post('/sync', (req, res) => {
  const records: SurveyRecord[] = req.body.records ?? [];

  const syncedIds: string[] = [];

  for (const record of records) {
    const existing = store.get(record.id);

    if (!existing || new Date(record.updatedAt) >= new Date(existing.updatedAt)) {
      store.set(record.id, {
        ...record,
        syncStatus: 'synced',
      });
    }

    syncedIds.push(record.id);
  }

  res.json({
    syncedIds,
    totalStored: store.size
  });
});

app.get('/surveys', (_req, res) => {
  res.json(Array.from(store.values()));
});

const port = 3000;
app.listen(port, () => {
  console.log(`Sync server listening on port ${port}`);
});
```

