import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import '../models/survey_record.dart';

class LocalDbService {
  static final LocalDbService instance = LocalDbService._init();
  static Database? _database;

  LocalDbService._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDB('survey.db');
    return _database!;
  }

  Future<Database> _initDB(String filePath) async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, filePath);

    return await openDatabase(
      path,
      version: 1,
      onCreate: _createDB,
    );
  }

  Future _createDB(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        notes TEXT NOT NULL,
        latitude REAL NOT NULL,
        longitude REAL NOT NULL,
        createdAt TEXT NOT NULL,
        synced INTEGER NOT NULL
      )
    ''');
  }

  Future<void> insertSurvey(SurveyRecord record) async {
    final db = await instance.database;
    await db.insert(
      'surveys',
      record.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  Future<List<SurveyRecord>> getAllSurveys() async {
    final db = await instance.database;
    final maps = await db.query('surveys', orderBy: 'createdAt DESC');
    return maps.map((e) => SurveyRecord.fromMap(e)).toList();
  }

  Future<List<SurveyRecord>> getUnsyncedSurveys() async {
    final db = await instance.database;
    final maps = await db.query('surveys', where: 'synced = ?', whereArgs: [0]);
    return maps.map((e) => SurveyRecord.fromMap(e)).toList();
  }

  Future<void> markAsSynced(String id) async {
    final db = await instance.database;
    await db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}
