```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import '../models/survey_record.dart';
import 'local_db.dart';

class SyncService {
  final String apiUrl = 'https://YOUR_API_ENDPOINT/surveys';

  Future<void> syncUnsyncedRecords() async {
    final unsynced = await LocalDbService.instance.getUnsyncedSurveys();

    for (final record in unsynced) {
      final success = await _sendToServer(record);
      if (success) {
        await LocalDbService.instance.markAsSynced(record.id);
      }
    }
  }

  Future<bool> _sendToServer(SurveyRecord record) async {
    try {
      final response = await http.post(
        Uri.parse(apiUrl),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode(record.toMap()),
      );

      return response.statusCode == 200 || response.statusCode == 201;
    } catch (_) {
      return false;
    }
  }
}
