# 3) Repository: save locally first, enqueue sync

## `lib/services/survey_repository.dart`

```dart
import 'dart:convert';

import 'package:uuid/uuid.dart';
import '../db/app_db.dart';
import '../models/survey.dart';
import '../models/sync_item.dart';

class SurveyRepository {
  final _db = AppDb.instance;
  final _uuid = const Uuid();

  Future<List<Survey>> getAllSurveys() async {
    final db = await _db.database;
    final rows = await db.query('surveys', orderBy: 'updated_at DESC');
    return rows.map((r) => Survey.fromMap(r)).toList();
  }

  Future<Survey> createSurvey({
    required String title,
    required String notes,
    required double latitude,
    required double longitude,
  }) async {
    final survey = Survey(
      id: _uuid.v4(),
      title: title,
      notes: notes,
      latitude: latitude,
      longitude: longitude,
      status: 'active',
      updatedAt: DateTime.now().millisecondsSinceEpoch,
      synced: false,
    );

    final db = await _db.database;
    await db.insert('surveys', survey.toMap());

    await _enqueueSync(
      entityType: 'survey',
      entityId: survey.id,
      operation: 'upsert',
      payload: jsonEncode(survey.toJson()),
    );

    return survey;
  }

  Future<void> updateSurvey(Survey survey) async {
    final updated = Survey(
      id: survey.id,
      title: survey.title,
      notes: survey.notes,
      latitude: survey.latitude,
      longitude: survey.longitude,
      status: survey.status,
      updatedAt: DateTime.now().millisecondsSinceEpoch,
      synced: false,
    );

    final db = await _db.database;
    await db.update(
      'surveys',
      updated.toMap(),
      where: 'id = ?',
      whereArgs: [updated.id],
    );

    await _enqueueSync(
      entityType: 'survey',
      entityId: updated.id,
      operation: 'upsert',
      payload: jsonEncode(updated.toJson()),
    );
  }

  Future<void> deleteSurvey(String id) async {
    final db = await _db.database;
    await db.delete('surveys', where: 'id = ?', whereArgs: [id]);

    await _enqueueSync(
      entityType: 'survey',
      entityId: id,
      operation: 'delete',
      payload: jsonEncode({'id': id}),
    );
  }

  Future<void> markSynced(String id) async {
    final db = await _db.database;
    await db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  Future<void> _enqueueSync({
    required String entityType,
    required String entityId,
    required String operation,
    required String payload,
  }) async {
    final db = await _db.database;

    final item = SyncItem(
      entityType: entityType,
      entityId: entityId,
      operation: operation,
      payload: payload,
      createdAt: DateTime.now().millisecondsSinceEpoch,
      retryCount: 0,
    );

    await db.insert('sync_queue', item.toMap());
  }
}
