# 5) Sync service

This processes queued changes in order and retries later if sync fails.

## `lib/services/sync_service.dart`

```dart
import 'dart:convert';
import 'package:http/http.dart' as http;

import '../db/app_db.dart';
import '../models/sync_item.dart';
import 'survey_repository.dart';

class SyncService {
  final String baseUrl;
  final SurveyRepository repository;

  bool _isSyncing = false;

  SyncService({
    required this.baseUrl,
    required this.repository,
  });

  Future<void> syncPending() async {
    if (_isSyncing) return;
    _isSyncing = true;

    try {
      final db = await AppDb.instance.database;
      final rows = await db.query('sync_queue', orderBy: 'created_at ASC');
      final items = rows.map((r) => SyncItem.fromMap(r)).toList();

      for (final item in items) {
        try {
          final success = await _sendItem(item);
          if (success) {
            await db.delete(
              'sync_queue',
              where: 'id = ?',
              whereArgs: [item.localId],
            );

            if (item.entityType == 'survey' && item.operation == 'upsert') {
              await repository.markSynced(item.entityId);
            }
          } else {
            await _incrementRetry(item);
            break;
          }
        } catch (_) {
          await _incrementRetry(item);
          break;
        }
      }
    } finally {
      _isSyncing = false;
    }
  }

  Future<bool> _sendItem(SyncItem item) async {
    if (item.entityType == 'survey' && item.operation == 'upsert') {
      final response = await http.post(
        Uri.parse('$baseUrl/sync/surveys'),
        headers: {'Content-Type': 'application/json'},
        body: item.payload,
      );
      return response.statusCode >= 200 && response.statusCode < 300;
    }

    if (item.entityType == 'survey' && item.operation == 'delete') {
      final data = jsonDecode(item.payload);
      final response = await http.delete(
        Uri.parse('$baseUrl/surveys/${data['id']}'),
      );
      return response.statusCode >= 200 && response.statusCode < 300;
    }

    return false;
  }

  Future<void> _incrementRetry(SyncItem item) async {
    final db = await AppDb.instance.database;
    await db.update(
      'sync_queue',
      {'retry_count': item.retryCount + 1},
      where: 'id = ?',
      whereArgs: [item.localId],
    );
  }
}
```

