# 8) Minimal backend for syncing

You need some server endpoint that accepts upserts/deletes. Here is a very small Node/Express example.

## `server.js`

```javascript
const express = require('express');
const app = express();
app.use(express.json());

const surveys = new Map();

app.post('/sync/surveys', (req, res) => {
  const survey = req.body;

  if (!survey.id || !survey.title) {
    return res.status(400).json({ error: 'Invalid survey payload' });
  }

  const existing = surveys.get(survey.id);

  if (!existing || survey.updatedAt >= existing.updatedAt) {
    surveys.set(survey.id, survey);
  }

  return res.status(200).json({ ok: true, survey: surveys.get(survey.id) });
});

app.delete('/surveys/:id', (req, res) => {
  surveys.delete(req.params.id);
  return res.status(200).json({ ok: true });
});

app.get('/surveys', (req, res) => {
  return res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log('Sync server listening on http://localhost:3000');
});
```

