import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final db = await AppDatabase.instance.database;
  runApp(MyApp(database: db));
}

class MyApp extends StatelessWidget {
  final Database database;
  const MyApp({super.key, required this.database});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Offline Survey',
      theme: ThemeData(useMaterial3: true, colorSchemeSeed: Colors.green),
      home: SurveyHomePage(database: database),
    );
  }
}

class SurveyRecord {
  final int? id;
  final String siteName;
  final String observer;
  final double latitude;
  final double longitude;
  final String notes;
  final int synced;

  SurveyRecord({
    this.id,
    required this.siteName,
    required this.observer,
    required this.latitude,
    required this.longitude,
    required this.notes,
    required this.synced,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'site_name': siteName,
      'observer': observer,
      'latitude': latitude,
      'longitude': longitude,
      'notes': notes,
      'synced': synced,
    };
  }

  factory SurveyRecord.fromMap(Map<String, dynamic> map) {
    return SurveyRecord(
      id: map['id'],
      siteName: map['site_name'],
      observer: map['observer'],
      latitude: map['latitude'],
      longitude: map['longitude'],
      notes: map['notes'],
      synced: map['synced'],
    );
  }
}

class AppDatabase {
  static final AppDatabase instance = AppDatabase._init();
  static Database? _database;

  AppDatabase._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDB('survey.db');
    return _database!;
  }

  Future<Database> _initDB(String filePath) async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, filePath);

    return openDatabase(
      path,
      version: 1,
      onCreate: (db, version) async {
        await db.execute('''
          CREATE TABLE surveys (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            site_name TEXT NOT NULL,
            observer TEXT NOT NULL,
            latitude REAL NOT NULL,
            longitude REAL NOT NULL,
            notes TEXT NOT NULL,
            synced INTEGER NOT NULL DEFAULT 0
          )
        ''');
      },
    );
  }

  Future<int> insertSurvey(SurveyRecord record) async {
    final db = await database;
    return db.insert('surveys', record.toMap());
  }

  Future<List<SurveyRecord>> getAllSurveys() async {
    final db = await database;
    final maps = await db.query('surveys', orderBy: 'id DESC');
    return maps.map((e) => SurveyRecord.fromMap(e)).toList();
  }

  Future<List<SurveyRecord>> getUnsyncedSurveys() async {
    final db = await database;
    final maps = await db.query('surveys', where: 'synced = ?', whereArgs: [0]);
    return maps.map((e) => SurveyRecord.fromMap(e)).toList();
  }

  Future<void> markSynced(int id) async {
    final db = await database;
    await db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}

class SyncService {
  static const String apiUrl = 'https://example.com/api/surveys';

  static Future<void> syncUnsyncedRecords() async {
    final unsynced = await AppDatabase.instance.getUnsyncedSurveys();

    for (final record in unsynced) {
      try {
        final response = await http.post(
          Uri.parse(apiUrl),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'id': record.id,
            'site_name': record.siteName,
            'observer': record.observer,
            'latitude': record.latitude,
            'longitude': record.longitude,
            'notes': record.notes,
          }),
        );

        if (response.statusCode == 200 || response.statusCode == 201) {
          await AppDatabase.instance.markSynced(record.id!);
        }
      } catch (_) {
        // Still offline or server unreachable; ignore for now
      }
    }
  }
}

class SurveyHomePage extends StatefulWidget {
  final Database database;
  const SurveyHomePage({super.key, required this.database});

  @override
  State<SurveyHomePage> createState() => _SurveyHomePageState();
}

class _SurveyHomePageState extends State<SurveyHomePage> {
  final _siteController = TextEditingController();
  final _observerController = TextEditingController();
  final _latController = TextEditingController();
  final _lngController = TextEditingController();
  final _notesController = TextEditingController();

  List<SurveyRecord> _records = [];
  String _connectionStatus = 'Unknown';

  @override
  void initState() {
    super.initState();
    _loadRecords();
    _listenToConnectivity();
  }

  void _listenToConnectivity() {
    Connectivity().onConnectivityChanged.listen((result) async {
      final online = result != ConnectivityResult.none;
      setState(() {
        _connectionStatus = online ? 'Online' : 'Offline';
      });

      if (online) {
        await SyncService.syncUnsyncedRecords();
        await _loadRecords();
      }
    });

    Connectivity().checkConnectivity().then((result) {
      final online = result != ConnectivityResult.none;
      setState(() {
        _connectionStatus = online ? 'Online' : 'Offline';
      });
    });
  }

  Future<void> _loadRecords() async {
    final records = await AppDatabase.instance.getAllSurveys();
    setState(() {
      _records = records;
    });
  }

  Future<void> _saveSurvey() async {
    final site = _siteController.text.trim();
    final observer = _observerController.text.trim();
    final lat = double.tryParse(_latController.text.trim());
    final lng = double.tryParse(_lngController.text.trim());
    final notes = _notesController.text.trim();

    if (site.isEmpty || observer.isEmpty || lat == null || lng == null || notes.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please fill all fields correctly')),
      );
      return;
    }

    final record = SurveyRecord(
      siteName: site,
      observer: observer,
      latitude: lat,
      longitude: lng,
      notes: notes,
      synced: 0,
    );

    await AppDatabase.instance.insertSurvey(record);
    _siteController.clear();
    _observerController.clear();
    _latController.clear();
    _lngController.clear();
    _notesController.clear();

    await _loadRecords();

    if (_connectionStatus == 'Online') {
      await SyncService.syncUnsyncedRecords();
      await _loadRecords();
    }
  }

  @override
  void dispose() {
    _siteController.dispose();
    _observerController.dispose();
    _latController.dispose();
    _lngController.dispose();
    _notesController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final online = _connectionStatus == 'Online';

    return Scaffold(
      appBar: AppBar(
        title: const Text('Field Survey'),
        actions: [
          Padding(
            padding: const EdgeInsets.all(12),
            child: Center(
              child: Text(
                online ? 'Online' : 'Offline',
                style: TextStyle(
                  color: online ? Colors.green.shade900 : Colors.red.shade900,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            TextField(
              controller: _siteController,
              decoration: const InputDecoration(labelText: 'Site Name'),
            ),
            TextField(
              controller: _observerController,
              decoration: const InputDecoration(labelText: 'Observer'),
            ),
            TextField(
              controller: _latController,
              keyboardType: TextInputType.number,
              decoration: const InputDecoration(labelText: 'Latitude'),
            ),
            TextField(
              controller: _lngController,
              keyboardType: TextInputType.number,
              decoration: const InputDecoration(labelText: 'Longitude'),
            ),
            TextField(
              controller: _notesController,
              decoration: const InputDecoration(labelText: 'Notes'),
            ),
            const SizedBox(height: 12),
            Row(
              children: [
                ElevatedButton(
                  onPressed: _saveSurvey,
                  child: const Text('Save Survey'),
                ),
                const SizedBox(width: 12),
                OutlinedButton(
                  onPressed: () async {
                    await SyncService.syncUnsyncedRecords();
                    await _loadRecords();
                  },
                  child: const Text('Sync Now'),
                ),
              ],
            ),
            const SizedBox(height: 16),
            const Divider(),
            const Align(
              alignment: Alignment.centerLeft,
              child: Text(
                'Saved Surveys',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
              ),
            ),
            const SizedBox(height: 8),
            Expanded(
              child: _records.isEmpty
                  ? const Center(child: Text('No surveys yet'))
                  : ListView.builder(
                      itemCount: _records.length,
                      itemBuilder: (context, index) {
                        final r = _records[index];
                        return Card(
                          child: ListTile(
                            title: Text(r.siteName),
                            subtitle: Text(
                              'Observer: ${r.observer}\n'
                              'Lat/Lng: ${r.latitude}, ${r.longitude}\n'
                              'Notes: ${r.notes}',
                            ),
                            isThreeLine: true,
                            trailing: Icon(
                              r.synced == 1 ? Icons.cloud_done : Icons.cloud_off,
                              color: r.synced == 1 ? Colors.green : Colors.orange,
                            ),
                          ),
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }
}
