class SyncService {
  static Future<void> syncPendingRecords() async {
    final unsynced = await DatabaseHelper.instance.getUnsyncedSurveys();

    for (final record in unsynced) {
      final success = await _sendToServer(record);
      if (success && record.id != null) {
        await DatabaseHelper.instance.markAsSynced(record.id!);
      }
    }
  }

  static Future<bool> _sendToServer(SurveyRecord record) async {
    try {
      final response = await http.post(
        Uri.parse('https://jsonplaceholder.typicode.com/posts'),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({
          'siteName': record.siteName,
          'notes': record.notes,
          'latitude': record.latitude,
          'longitude': record.longitude,
        }),
      );

      return response.statusCode == 201;
    } catch (_) {
      return false;
    }
  }
}

class SurveyHomePage extends StatefulWidget {
  const SurveyHomePage({super.key});

  @override
  State<SurveyHomePage> createState() => _SurveyHomePageState();
}

class _SurveyHomePageState extends State<SurveyHomePage> {
  final _siteController = TextEditingController();
  final _notesController = TextEditingController();
  List<SurveyRecord> _records = [];
  String _status = 'Unknown';

  @override
  void initState() {
    super.initState();
    _loadRecords();
    _listenConnectivity();
  }

  Future<void> _loadRecords() async {
    final records = await DatabaseHelper.instance.getAllSurveys();
    setState(() {
      _records = records;
    });
  }

  void _listenConnectivity() {
    Connectivity().onConnectivityChanged.listen((result) async {
      final connected = result != ConnectivityResult.none;
      setState(() {
        _status = connected ? 'Online' : 'Offline';
      });

      if (connected) {
        await SyncService.syncPendingRecords();
        await _loadRecords();
      }
    });

    Connectivity().checkConnectivity().then((result) {
      setState(() {
        _status = result == ConnectivityResult.none ? 'Offline' : 'Online';
      });
    });
  }

  Future<void> _addSurvey() async {
    if (_siteController.text.isEmpty || _notesController.text.isEmpty) return;

    final record = SurveyRecord(
      siteName: _siteController.text,
      notes: _notesController.text,
      latitude: 0.0,
      longitude: 0.0,
      synced: 0,
    );

    await DatabaseHelper.instance.insertSurvey(record);

    _siteController.clear();
    _notesController.clear();

    await _loadRecords();

    if (_status == 'Online') {
      await SyncService.syncPendingRecords();
      await _loadRecords();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Offline Field Survey'),
        actions: [
          Padding(
            padding: const EdgeInsets.all(12),
            child: Center(child: Text(_status)),
          )
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            TextField(
              controller: _siteController,
              decoration: const InputDecoration(labelText: 'Site Name'),
            ),
            TextField(
              controller: _notesController,
              decoration: const InputDecoration(labelText: 'Notes'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: _addSurvey,
              child: const Text('Save Survey'),
            ),
            const SizedBox(height: 16),
            const Divider(),
            const Text(
              'Saved Records',
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
            ),
            Expanded(
              child: ListView.builder(
                itemCount: _records.length,
                itemBuilder: (context, index) {
                  final r = _records[index];
                  return ListTile(
                    title: Text(r.siteName),
                    subtitle: Text('${r.notes}\n(${r.latitude}, ${r.longitude})'),
                    isThreeLine: true,
                    trailing: Icon(
                      r.synced == 1 ? Icons.cloud_done : Icons.cloud_off,
                      color: r.synced == 1 ? Colors.green : Colors.orange,
                    ),
                  );
                },
              ),
            )
          ],
        ),
      ),
    );
  }
}
