import 'dart:async';
import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await DatabaseService.instance.init();
  runApp(const SurveyApp());
}

class SurveyApp extends StatelessWidget {
  const SurveyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Offline Survey App',
      theme: ThemeData(useMaterial3: true, colorSchemeSeed: Colors.green),
      home: const SurveyHomePage(),
    );
  }
}

class SurveyRecord {
  final int? id;
  final String siteName;
  final String observer;
  final String notes;
  final double latitude;
  final double longitude;
  final int synced; // 0 = no, 1 = yes

  SurveyRecord({
    this.id,
    required this.siteName,
    required this.observer,
    required this.notes,
    required this.latitude,
    required this.longitude,
    required this.synced,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'site_name': siteName,
      'observer': observer,
      'notes': notes,
      'latitude': latitude,
      'longitude': longitude,
      'synced': synced,
    };
  }

  factory SurveyRecord.fromMap(Map<String, dynamic> map) {
    return SurveyRecord(
      id: map['id'],
      siteName: map['site_name'],
      observer: map['observer'],
      notes: map['notes'],
      latitude: map['latitude'],
      longitude: map['longitude'],
      synced: map['synced'],
    );
  }
}

class DatabaseService {
  DatabaseService._private();
  static final DatabaseService instance = DatabaseService._private();

  Database? _db;

  Future<void> init() async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'survey_app.db');

    _db = await openDatabase(
      path,
      version: 1,
      onCreate: (db, version) async {
        await db.execute('''
          CREATE TABLE surveys (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            site_name TEXT NOT NULL,
            observer TEXT NOT NULL,
            notes TEXT NOT NULL,
            latitude REAL NOT NULL,
            longitude REAL NOT NULL,
            synced INTEGER NOT NULL DEFAULT 0
          )
        ''');
      },
    );
  }

  Future<int> insertSurvey(SurveyRecord record) async {
    return await _db!.insert('surveys', record.toMap());
  }

  Future<List<SurveyRecord>> getAllSurveys() async {
    final rows = await _db!.query('surveys', orderBy: 'id DESC');
    return rows.map((r) => SurveyRecord.fromMap(r)).toList();
  }

  Future<List<SurveyRecord>> getUnsyncedSurveys() async {
    final rows = await _db!.query('surveys', where: 'synced = ?', whereArgs: [0]);
    return rows.map((r) => SurveyRecord.fromMap(r)).toList();
  }

  Future<void> markSynced(int id) async {
    await _db!.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}

class SyncService {
  static const String endpoint = 'https://example.com/api/surveys';

  static Future<void> syncPending() async {
    final pending = await DatabaseService.instance.getUnsyncedSurveys();

    for (final survey in pending) {
      try {
        final response = await http.post(
          Uri.parse(endpoint),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'id': survey.id,
            'siteName': survey.siteName,
            'observer': survey.observer,
            'notes': survey.notes,
            'latitude': survey.latitude,
            'longitude': survey.longitude,
          }),
        );

        if (response.statusCode == 200 || response.statusCode == 201) {
          await DatabaseService.instance.markSynced(survey.id!);
        }
      } catch (_) {
        // Stay unsynced; retry later
      }
    }
  }
}

class SurveyHomePage extends StatefulWidget {
  const SurveyHomePage({super.key});

  @override
  State<SurveyHomePage> createState() => _SurveyHomePageState();
}

class _SurveyHomePageState extends State<SurveyHomePage> {
  final _siteController = TextEditingController();
  final _observerController = TextEditingController();
  final _notesController = TextEditingController();
  final _latController = TextEditingController();
  final _lngController = TextEditingController();

  List<SurveyRecord> _surveys = [];
  String _status = 'Checking connectivity...';
  StreamSubscription<List<ConnectivityResult>>? _connectivitySubscription;

  @override
  void initState() {
    super.initState();
    _loadSurveys();
    _watchConnectivity();
  }

  Future<void> _loadSurveys() async {
    final records = await DatabaseService.instance.getAllSurveys();
    setState(() {
      _surveys = records;
    });
  }

  void _watchConnectivity() {
    _connectivitySubscription =
        Connectivity().onConnectivityChanged.listen((results) async {
      final connected = results.any((r) => r != ConnectivityResult.none);

      setState(() {
        _status = connected ? 'Online - syncing...' : 'Offline';
      });

      if (connected) {
        await SyncService.syncPending();
        await _loadSurveys();
        setState(() {
          _status = 'Online - sync complete';
        });
      }
    });
  }

  Future<void> _addSurvey() async {
    final site = _siteController.text.trim();
    final observer = _observerController.text.trim();
    final notes = _notesController.text.trim();
    final lat = double.tryParse(_latController.text.trim());
    final lng = double.tryParse(_lngController.text.trim());

    if (site.isEmpty || observer.isEmpty || notes.isEmpty || lat == null || lng == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please complete all fields')),
      );
      return;
    }

    await DatabaseService.instance.insertSurvey(
      SurveyRecord(
        siteName: site,
        observer: observer,
        notes: notes,
        latitude: lat,
        longitude: lng,
        synced: 0,
      ),
    );

    _siteController.clear();
    _observerController.clear();
    _notesController.clear();
    _latController.clear();
    _lngController.clear();

    await _loadSurveys();

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Survey saved locally')),
    );
  }

  @override
  void dispose() {
    _siteController.dispose();
    _observerController.dispose();
    _notesController.dispose();
    _latController.dispose();
    _lngController.dispose();
    _connectivitySubscription?.cancel();
    super.dispose();
  }

  Widget _buildForm() {
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: Column(
          children: [
            TextField(
              controller: _siteController,
              decoration: const InputDecoration(labelText: 'Site Name'),
            ),
            TextField(
              controller: _observerController,
              decoration: const InputDecoration(labelText: 'Observer'),
            ),
            TextField(
              controller: _notesController,
              decoration: const InputDecoration(labelText: 'Notes'),
            ),
            TextField(
              controller: _latController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Latitude'),
            ),
            TextField(
              controller: _lngController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Longitude'),
            ),
            const SizedBox(height: 12),
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: _addSurvey,
                child: const Text('Save Survey Offline'),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSurveyList() {
    return Expanded(
      child: ListView.builder(
        itemCount: _surveys.length,
        itemBuilder: (context, index) {
          final s = _surveys[index];
          return ListTile(
            title: Text(s.siteName),
            subtitle: Text(
              '${s.observer} • ${s.latitude}, ${s.longitude}\n${s.notes}',
            ),
            isThreeLine: true,
            trailing: Icon(
              s.synced == 1 ? Icons.cloud_done : Icons.cloud_off,
              color: s.synced == 1 ? Colors.green : Colors.orange,
            ),
          );
        },
      ),
    );
  }

  Future<void> _manualSync() async {
    setState(() {
      _status = 'Manual sync in progress...';
    });
    await SyncService.syncPending();
    await _loadSurveys();
    setState(() {
      _status = 'Manual sync complete';
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Offline Field Survey'),
        actions: [
          IconButton(
            onPressed: _manualSync,
            icon: const Icon(Icons.sync),
          )
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(12),
        child: Column(
          children: [
            Text(_status, style: const TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 12),
            _buildForm(),
            const SizedBox(height: 12),
            const Align(
              alignment: Alignment.centerLeft,
              child: Text(
                'Saved Surveys',
                style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
              ),
            ),
            _buildSurveyList(),
          ],
        ),
      ),
    );
  }
}
