import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import 'survey.dart';

class AppDatabase {
  static final AppDatabase instance = AppDatabase._init();
  static Database? _database;

  AppDatabase._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDB('surveys.db');
    return _database!;
  }

  Future<Database> _initDB(String filePath) async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, filePath);

    return await openDatabase(
      path,
      version: 1,
      onCreate: _createDB,
    );
  }

  Future _createDB(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        notes TEXT NOT NULL,
        latitude REAL NOT NULL,
        longitude REAL NOT NULL,
        synced INTEGER NOT NULL DEFAULT 0
      )
    ''');
  }

  Future<int> insertSurvey(Survey survey) async {
    final db = await instance.database;
    return db.insert('surveys', survey.toMap());
  }

  Future<List<Survey>> getAllSurveys() async {
    final db = await instance.database;
    final result = await db.query('surveys', orderBy: 'id DESC');
    return result.map((e) => Survey.fromMap(e)).toList();
  }

  Future<List<Survey>> getUnsyncedSurveys() async {
    final db = await instance.database;
    final result = await db.query(
      'surveys',
      where: 'synced = ?',
      whereArgs: [0],
      orderBy: 'id ASC',
    );
    return result.map((e) => Survey.fromMap(e)).toList();
  }

  Future<int> markSynced(int id) async {
    final db = await instance.database;
    return db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}
