            ),
            const SizedBox(height: 12),
            Row(
              children: [
                ElevatedButton(
                  onPressed: addSurvey,
                  child: const Text('Save Offline'),
                ),
                const SizedBox(width: 12),
                ElevatedButton(
                  onPressed: () async {
