# 2. App code

Replace `App.tsx` with:

```tsx
import React, { useEffect, useState } from 'react';
import {
  Alert,
  Button,
  FlatList,
  SafeAreaView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';

type SurveyRecord = {
  id: string;
  siteName: string;
  observation: string;
  createdAt: string;
  synced: boolean;
};

const STORAGE_KEY = 'survey_records';

export default function App() {
  const [siteName, setSiteName] = useState('');
  const [observation, setObservation] = useState('');
  const [records, setRecords] = useState<SurveyRecord[]>([]);
  const [isOnline, setIsOnline] = useState<boolean>(false);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    loadRecords();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!state.isConnected;
      setIsOnline(online);

      if (online) {
        syncUnsyncedRecords();
      }
    });

    return () => unsubscribe();
  }, []);

  const loadRecords = async () => {
    try {
      const json = await AsyncStorage.getItem(STORAGE_KEY);
      if (json) {
        setRecords(JSON.parse(json));
      }
    } catch (error) {
      console.error('Failed to load records', error);
    }
  };

  const saveRecords = async (updatedRecords: SurveyRecord[]) => {
    try {
      setRecords(updatedRecords);
      await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(updatedRecords));
    } catch (error) {
      console.error('Failed to save records', error);
    }
  };

  const addRecord = async () => {
    if (!siteName.trim() || !observation.trim()) {
      Alert.alert('Validation', 'Please enter both site name and observation.');
      return;
    }

    const newRecord: SurveyRecord = {
      id: Date.now().toString(),
      siteName,
      observation,
      createdAt: new Date().toISOString(),
      synced: false,
    };

    const updated = [newRecord, ...records];
    await saveRecords(updated);

    setSiteName('');
    setObservation('');
  };

  const syncUnsyncedRecords = async () => {
    if (isSyncing) return;

    const unsynced = records.filter((r) => !r.synced);
    if (unsynced.length === 0) return;

    setIsSyncing(true);

    try {
      const syncedIds: string[] = [];

      for (const record of unsynced) {
        const success = await mockUpload(record);
        if (success) {
          syncedIds.push(record.id);
        }
      }

      if (syncedIds.length > 0) {
        const updated = records.map((r) =>
          syncedIds.includes(r.id) ? { ...r, synced: true } : r
        );
        await saveRecords(updated);
      }
    } catch (error) {
      console.error('Sync failed', error);
    } finally {
      setIsSyncing(false);
    }
  };

  const mockUpload = async (record: SurveyRecord): Promise<boolean> => {
    console.log('Uploading record to server:', record);

    await new Promise((resolve) => setTimeout(resolve, 500));

    return true;
  };

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Offline Field Survey</Text>
      <Text style={styles.status}>
        Status: {isOnline ? 'Online' : 'Offline'} {isSyncing ? '(Syncing...)' : ''}
      </Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Site name"
          value={siteName}
          onChangeText={setSiteName}
        />
        <TextInput
          style={[styles.input, styles.multiline]}
          placeholder="Observation"
          value={observation}
          onChangeText={setObservation}
          multiline
        />
        <Button title="Save Survey Record" onPress={addRecord} />
        <View style={{ height: 8 }} />
        <Button title="Sync Now" onPress={syncUnsyncedRecords} />
      </View>

      <FlatList
        data={records}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={styles.record}>
            <Text style={styles.recordTitle}>{item.siteName}</Text>
            <Text>{item.observation}</Text>
            <Text style={styles.meta}>{item.createdAt}</Text>
            <Text style={[styles.syncBadge, item.synced ? styles.synced : styles.unsynced]}>
              {item.synced ? 'Synced' : 'Pending Sync'}
            </Text>
          </View>
        )}
        ListEmptyComponent={<Text>No survey records yet.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
    marginTop: 40,
  },
  title: {
    fontSize: 24,
