import { Chat, Notification, User } from "./types";
import { v4 as uuid } from "uuid";

export const users: User[] = [];
export const chats: Chat[] = [];
export const notifications: Notification[] = [];

export function createUser(username: string, password: string): User {
  const user: User = {
    id: uuid(),
    username,
    password,
    isPremium: false,
    balance: 0
  };
  users.push(user);
  return user;
}

export function findUserByUsername(username: string) {
  return users.find((u) => u.username === username);
}

export function findUserById(id: string) {
  return users.find((u) => u.id === id);
}

export function createChat(participantIds: string[]): Chat {
  const chat: Chat = {
    id: uuid(),
    participantIds,
    messages: []
  };
  chats.push(chat);
  return chat;
}

export function findChatById(chatId: string) {
  return chats.find((c) => c.id === chatId);
}

export function addNotification(
  userId: string,
  type: "message" | "payment" | "system",
  content: string
) {
  const notification = {
    id: uuid(),
    userId,
    type,
    content,
    createdAt: Date.now(),
    read: false
  };
  notifications.push(notification);
  return notification;
}

export function getUserNotifications(userId: string) {
  return notifications.filter((n) => n.userId === userId);
}
