## src/routes.ts

```ts
import express from "express";
import { v4 as uuid } from "uuid";
import { authMiddleware, AuthedRequest, signToken } from "./auth";
import {
  addNotification,
  createChat,
  createUser,
  findChatById,
  findUserById,
  findUserByUsername,
  getUserNotifications
} from "./store";
import { createPremiumCheckoutSession } from "./monetization";

export function createRoutes(io: any) {
  const router = express.Router();

  router.post("/register", (req, res) => {
    const { username, password } = req.body;
    if (!username || !password) {
      return res.status(400).json({ error: "username and password required" });
    }

    if (findUserByUsername(username)) {
      return res.status(409).json({ error: "username already exists" });
    }

    const user = createUser(username, password);
    const token = signToken(user.id);

    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        isPremium: user.isPremium
      }
    });
  });

  router.post("/login", (req, res) => {
    const { username, password } = req.body;
    const user = findUserByUsername(username);

    if (!user || user.password !== password) {
      return res.status(401).json({ error: "invalid credentials" });
    }

    const token = signToken(user.id);
    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        isPremium: user.isPremium
      }
    });
  });

  router.post("/chats", authMiddleware, (req: AuthedRequest, res) => {
    const { participantIds } = req.body;
    const userId = req.user!.userId;

    const allParticipants = Array.from(new Set([userId, ...(participantIds || [])]));
    const chat = createChat(allParticipants);

    res.json(chat);
  });

  router.get("/chats/:chatId", authMiddleware, (req: AuthedRequest, res) => {
    const chat = findChatById(req.params.chatId);
    const userId = req.user!.userId;

    if (!chat) return res.status(404).json({ error: "chat not found" });
    if (!chat.participantIds.includes(userId)) {
      return res.status(403).json({ error: "forbidden" });
    }

    res.json(chat);
  });

  router.post("/chats/:chatId/messages", authMiddleware, (req: AuthedRequest, res) => {
    const { content } = req.body;
    const userId = req.user!.userId;
    const chat = findChatById(req.params.chatId);

    if (!chat) return res.status(404).json({ error: "chat not found" });
    if (!chat.participantIds.includes(userId)) {
      return res.status(403).json({ error: "forbidden" });
    }

    const message = {
      id: uuid(),
      chatId: chat.id,
      senderId: userId,
      content,
      createdAt: Date.now()
    };

    chat.messages.push(message);

    for (const participantId of chat.participantIds) {
      if (participantId !== userId) {
        const notification = addNotification(
          participantId,
          "message",
          `New message in chat ${chat.id}`
        );

        io.to(`user:${participantId}`).emit("notification", notification);
      }
    }

    io.to(`chat:${chat.id}`).emit("message", message);

    res.json(message);
  });

  router.get("/notifications", authMiddleware, (req: AuthedRequest, res) => {
    const userId = req.user!.userId;
    res.json(getUserNotifications(userId));
  });

  router.post("/billing/checkout/premium", authMiddleware, async (req: AuthedRequest, res) => {
    try {
      const session = await createPremiumCheckoutSession(req.user!.userId);
      res.json({ url: session.url });
    } catch (error) {
      res.status(500).json({ error: "failed to create checkout session" });
    }
  });

  router.post("/billing/mock/confirm-premium", authMiddleware, (req: AuthedRequest, res) => {
    const user = findUserById(req.user!.userId);
    if (!user) return res.status(404).json({ error: "user not found" });

    user.isPremium = true;

    const notification = addNotification(
      user.id,
      "payment",
      "Premium activated successfully"
    );

    io.to(`user:${user.id}`).emit("notification", notification);

    res.json({ success: true, isPremium: true });
  });

  return router;
}
```

