## src/sockets.ts

```ts
import { Server, Socket } from "socket.io";
import jwt from "jsonwebtoken";
import { findChatById } from "./store";

const JWT_SECRET = process.env.JWT_SECRET || "fallback-secret";

export function setupSockets(io: Server) {
  io.use((socket, next) => {
    const token =
      socket.handshake.auth?.token || socket.handshake.headers.authorization;

    if (!token) return next(new Error("Unauthorized"));

    const cleanToken = String(token).replace("Bearer ", "");

    try {
      const payload = jwt.verify(cleanToken, JWT_SECRET) as { userId: string };
      (socket as Socket & { userId: string }).userId = payload.userId;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket: Socket) => {
    const userId = (socket as Socket & { userId: string }).userId;

    socket.join(`user:${userId}`);

    socket.on("join_chat", (chatId: string) => {
      const chat = findChatById(chatId);
      if (!chat) return;
      if (!chat.participantIds.includes(userId)) return;

      socket.join(`chat:${chatId}`);
      socket.emit("joined_chat", chatId);
    });

    socket.on("leave_chat", (chatId: string) => {
      socket.leave(`chat:${chatId}`);
      socket.emit("left_chat", chatId);
    });

    socket.on("typing", (chatId: string) => {
      const chat = findChatById(chatId);
      if (!chat) return;
      if (!chat.participantIds.includes(userId)) return;

      socket.to(`chat:${chatId}`).emit("typing", {
        chatId,
        userId
      });
    });

    socket.on("disconnect", () => {
      // Handle presence updates in a real application
    });
  });
}
