import { Router } from "express";
import { v4 as uuid } from "uuid";
import { requireAuth, AuthedRequest } from "../middleware/auth";
import { db } from "../data/store";
import { createNotification, sendPushNotification } from "../services/notificationService";

const router = Router();

router.get("/", requireAuth, (req: AuthedRequest, res) => {
  const items = Array.from(db.conversations.values())
    .filter((c) => c.memberIds.includes(req.user!.id))
    .map((c) => ({
      ...c,
      messages: c.messageIds
        .map((id) => db.messages.get(id))
        .filter(Boolean)
    }));

  res.json(items);
});

router.post("/:conversationId/messages", requireAuth, async (req: AuthedRequest, res) => {
  const { conversationId } = req.params;
  const { text } = req.body || {};

  const conversation = db.conversations.get(conversationId);
  if (!conversation) return res.status(404).json({ error: "Conversation not found" });
  if (!conversation.memberIds.includes(req.user!.id)) {
    return res.status(403).json({ error: "Not a member of this conversation" });
  }

  const message = {
    id: uuid(),
    conversationId,
    senderId: req.user!.id,
    text,
    createdAt: Date.now()
  };

  db.messages.set(message.id, message);
  conversation.messageIds.push(message.id);
  db.conversations.set(conversation.id, conversation);

  const recipients = conversation.memberIds.filter((id) => id !== req.user!.id);
  for (const userId of recipients) {
    createNotification(userId, "message", "New message", text);
    await sendPushNotification(userId, "New message", text);
  }

  res.json(message);
});

export default router;
```

