## `apps/server/src/socket/index.ts`
```ts
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { config } from "../config";
import { db } from "../data/store";
import { createNotification, sendPushNotification } from "../services/notificationService";
import { v4 as uuid } from "uuid";

export function setupSocket(io: Server) {
  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, config.jwtSecret) as {
        sub: string;
        username: string;
      };

      socket.data.user = {
        id: payload.sub,
        username: payload.username
      };

      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.data.user.id as string;
    socket.join(`user:${userId}`);

    socket.on("conversation:join", (conversationId: string) => {
      const conversation = db.conversations.get(conversationId);
      if (!conversation) return;
      if (!conversation.memberIds.includes(userId)) return;

      socket.join(`conversation:${conversationId}`);
    });

    socket.on("message:send", async (payload: { conversationId: string; text: string }) => {
      const conversation = db.conversations.get(payload.conversationId);
      if (!conversation) return;
      if (!conversation.memberIds.includes(userId)) return;

      const message = {
        id: uuid(),
        conversationId: payload.conversationId,
        senderId: userId,
        text: payload.text,
        createdAt: Date.now()
      };

      db.messages.set(message.id, message);
      conversation.messageIds.push(message.id);
      db.conversations.set(conversation.id, conversation);

      io.to(`conversation:${payload.conversationId}`).emit("message:new", message);

      const recipients = conversation.memberIds.filter((id) => id !== userId);
      for (const recipientId of recipients) {
        const notification = createNotification(
          recipientId,
          "message",
          "New message",
          payload.text
        );

        io.to(`user:${recipientId}`).emit("notification:new", notification);
        await sendPushNotification(recipientId, "New message", payload.text);
      }
    });
  });
}
```

