import React, { useEffect, useState } from "react";
import { View, Text, Button, FlatList, TouchableOpacity, Alert } from "react-native";
import { api } from "../api";
import { store } from "../store";
import { getSocket } from "../socket";

type Conversation = {
  id: string;
  memberIds: string[];
  messages: {
    id: string;
    senderId: string;
    text: string;
    createdAt: number;
  }[];
};

export function ConversationsScreen({
  onOpenConversation,
  onOpenMonetization
}: {
  onOpenConversation: (conversation: Conversation) => void;
  onOpenMonetization: () => void;
}) {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);

  async function load() {
    const result = await api<Conversation[]>("/conversations");
    setConversations(result);

    const notif = await api<any[]>("/users/notifications");
    setNotifications(notif);
  }

  useEffect(() => {
    load().catch(console.error);

    const socket = getSocket();
    socket?.on("notification:new", (n) => {
      setNotifications((prev) => [n, ...prev]);
      Alert.alert(n.title, n.body);
    });

    socket?.on("message:new", () => {
      load().catch(console.error);
    });

    return () => {
      socket?.off("notification:new");
      socket?.off("message:new");
    };
  }, []);

  return (
    <View style={{ flex: 1, padding: 16, gap: 12 }}>
      <Text style={{ fontSize: 24, fontWeight: "600" }}>
        Hi, {store.user?.username}
      </Text>
      <Text>Premium: {store.user?.premium ? "Yes" : "No"}</Text>
      <Button title="Upgrade / Monetization" onPress={onOpenMonetization} />
      <Text style={{ fontSize: 18, marginTop: 8 }}>Conversations</Text>

