import React, { useEffect, useState } from "react";
import { View, Text, TextInput, Button, FlatList } from "react-native";
import { getSocket } from "../socket";
import { store } from "../store";

type Message = {
  id: string;
  conversationId: string;
  senderId: string;
  text: string;
  createdAt: number;
};

export function ChatScreen({
  conversation,
  onBack
}: {
  conversation: {
    id: string;
    messages: Message[];
  };
  onBack: () => void;
}) {
  const [messages, setMessages] = useState<Message[]>(conversation.messages || []);
  const [text, setText] = useState("");

  useEffect(() => {
    const socket = getSocket();
    socket?.emit("conversation:join", conversation.id);

    const onNewMessage = (message: Message) => {
      if (message.conversationId === conversation.id) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket?.on("message:new", onNewMessage);

    return () => {
      socket?.off("message:new", onNewMessage);
    };
  }, [conversation.id]);

  function sendMessage() {
    if (!text.trim()) return;
    const socket = getSocket();
    socket?.emit("message:send", {
      conversationId: conversation.id,
      text
    });
    setText("");
  }

  return (
    <View style={{ flex: 1, padding: 16 }}>
      <Button title="Back" onPress={onBack} />
      <Text style={{ fontSize: 20, fontWeight: "600", marginVertical: 12 }}>
        Chat
      </Text>

      <FlatList
        style={{ flex: 1 }}
        data={messages}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={{ paddingVertical: 8 }}>
            <Text style={{ fontWeight: item.senderId === store.user?.id ? "700" : "400" }}>
              {item.senderId === store.user?.id ? "You" : "Them"}
            </Text>
            <Text>{item.text}</Text>
          </View>
        )}
      />

      <TextInput
        value={text}
        onChangeText={setText}
        placeholder="Type a message"
        style={{ borderWidth: 1, borderRadius: 8, padding: 12, marginBottom: 8 }}
      />
      <Button title="Send" onPress={sendMessage} />
    </View>
  );
}
