import { Message, Notification, Presence, Session, User } from "./models";

export const db = {
  users: [] as User[],
  sessions: [] as Session[],
  messages: [] as Message[],
  notifications: [] as Notification[],
  presence: new Map<string, Presence>()
};

export function getConversation(userA: string, userB: string) {
  return db.messages
    .filter(
      (m) =>
        (m.fromUserId === userA && m.toUserId === userB) ||
        (m.fromUserId === userB && m.toUserId === userA)
    )
    .sort((a, b) => a.createdAt - b.createdAt);
}
