  const sender = req.user!;
  const { toUserId, text } = req.body as {
    toUserId?: string;
    text?: string;
  };

  if (!toUserId || !text?.trim()) {
    return res.status(400).json({ error: "toUserId and text required" });
  }

  const recipient = db.users.find((u) => u.id === toUserId);
  if (!recipient) {
    return res.status(404).json({ error: "recipient not found" });
  }

  const message = {
    id: uuid(),
    fromUserId: sender.id,
    toUserId,
    text: text.trim(),
    createdAt: Date.now(),
    premium: sender.premium
  };

  db.messages.push(message);

  const notification = {
    id: uuid(),
    userId: recipient.id,
    type: "message" as const,
    title: `New message from ${sender.username}${sender.premium ? " ⭐" : ""}`,
    body: text.trim(),
    createdAt: Date.now(),
    read: false
  };

  db.notifications.push(notification);

  emitMessageToUser(recipient.id, message);
  emitNotificationToUser(recipient.id, notification);

  res.json(message);
});

