# 9) `src/socket.ts`

```ts
import { Server } from "socket.io";
import { getUserByToken } from "./auth";
import { db } from "./store";

let io: Server;

const onlineSockets = new Map<string, Set<string>>();

export function initSocket(server: any) {
  io = new Server(server, {
    cors: {
      origin: "*"
    }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token as string | undefined;
    const user = getUserByToken(token);
    if (!user) return next(new Error("Unauthorized"));
    (socket as any).user = user;
    next();
  });

  io.on("connection", (socket) => {
    const user = (socket as any).user;

    if (!onlineSockets.has(user.id)) {
      onlineSockets.set(user.id, new Set());
    }
    onlineSockets.get(user.id)!.add(socket.id);

    db.presence.set(user.id, {
      userId: user.id,
      online: true,
      lastSeenAt: Date.now()
    });

    io.emit("presence:update", {
      userId: user.id,
      online: true,
      lastSeenAt: Date.now()
    });

    socket.on("message:send", (payload: { toUserId: string; text: string }) => {
      const recipient = db.users.find((u) => u.id === payload.toUserId);
      if (!recipient || !payload.text?.trim()) return;

      const message = {
        id: cryptoRandomId(),
        fromUserId: user.id,
        toUserId: recipient.id,
        text: payload.text.trim(),
        createdAt: Date.now(),
        premium: user.premium
      };

      db.messages.push(message);

      const notification = {
        id: cryptoRandomId(),
        userId: recipient.id,
        type: "message" as const,
        title: `New message from ${user.username}${user.premium ? " ⭐" : ""}`,
        body: payload.text.trim(),
        createdAt: Date.now(),
        read: false
      };

      db.notifications.push(notification);

      emitMessageToUser(recipient.id, message);
      emitNotificationToUser(recipient.id, notification);

      socket.emit("message:sent", message);
    });

    socket.on("disconnect", () => {
      const sockets = onlineSockets.get(user.id);
      if (sockets) {
        sockets.delete(socket.id);
        if (sockets.size === 0) {
          onlineSockets.delete(user.id);
          db.presence.set(user.id, {
            userId: user.id,
            online: false,
            lastSeenAt: Date.now()
          });

          io.emit("presence:update", {
            userId: user.id,
            online: false,
            lastSeenAt: Date.now()
          });
        }
      }
    });
  });

  return io;
}

export function emitNotificationToUser(userId: string, notification: any) {
  if (!io) return;
  io.emit(`notification:${userId}`, notification);
}

export function emitMessageToUser(userId: string, message: any) {
  if (!io) return;
  io.emit(`message:${userId}`, message);
}

function cryptoRandomId() {
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}
