## server/src/index.ts

```ts
import 'dotenv/config';
import express from 'express';
import cors from 'cors';
import http from 'http';
import { Server } from 'socket.io';
import { v4 as uuid } from 'uuid';
import { authMiddleware, signToken } from './auth';
import { messages, onlineUsers, users, usersByUsername } from './store';
import { Message, User } from './types';
import { stripe } from './payments';
import { sendPushNotification } from './notifications';

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: '*'
  }
});

const PORT = Number(process.env.PORT || 4000);

app.get('/health', (_req, res) => {
  res.json({ ok: true });
});

app.post('/auth/signup', (req, res) => {
  const { username, password } = req.body as { username?: string; password?: string };

  if (!username || !password) {
    return res.status(400).json({ error: 'username and password required' });
  }

  if (usersByUsername.has(username)) {
    return res.status(409).json({ error: 'username already exists' });
  }

  const user: User = {
    id: uuid(),
    username,
    password,
    premium: false,
    createdAt: Date.now()
  };

  users.set(user.id, user);
  usersByUsername.set(user.username, user);

  const token = signToken({ userId: user.id, username: user.username });
  return res.json({
    token,
    user: {
      id: user.id,
      username: user.username,
      premium: user.premium
    }
  });
});

app.post('/auth/login', (req, res) => {
  const { username, password } = req.body as { username?: string; password?: string };

  if (!username || !password) {
    return res.status(400).json({ error: 'username and password required' });
  }

  const user = usersByUsername.get(username);
  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'invalid credentials' });
  }

  const token = signToken({ userId: user.id, username: user.username });
  return res.json({
    token,
    user: {
      id: user.id,
      username: user.username,
      premium: user.premium
    }
  });
});

app.get('/users', authMiddleware, (req, res) => {
  const currentUserId = req.user!.userId;
  const list = [...users.values()]
    .filter((u) => u.id !== currentUserId)
    .map((u) => ({
      id: u.id,
      username: u.username,
      premium: u.premium,
      online: onlineUsers.has(u.id)
    }));

  res.json({ users: list });
});

app.get('/messages/:otherUserId', authMiddleware, (req, res) => {
  const currentUserId = req.user!.userId;
  const { otherUserId } = req.params;

  const convo = messages.filter(
    (m) =>
      (m.fromUserId === currentUserId && m.toUserId === otherUserId) ||
      (m.fromUserId === otherUserId && m.toUserId === currentUserId)
  );

  res.json({ messages: convo });
});

app.post('/messages', authMiddleware, async (req, res) => {
  const currentUserId = req.user!.userId;
  const { toUserId, text } = req.body as { toUserId?: string; text?: string };

  if (!toUserId || !text?.trim()) {
    return res.status(400).json({ error: 'toUserId and text required' });
  }

  const recipient = users.get(toUserId);
  if (!recipient) {
    return res.status(404).json({ error: 'recipient not found' });
  }

  const msg: Message = {
    id: uuid(),
    fromUserId: currentUserId,
    toUserId,
    text: text.trim(),
    createdAt: Date.now(),
    delivered: false,
    read: false
  };

  messages.push(msg);

  const recipientSocketId = onlineUsers.get(toUserId);
  if (recipientSocketId) {
    io.to(recipientSocketId).emit('message:new', msg);
    msg.delivered = true;
  } else if (recipient.pushToken) {
    const sender = users.get(currentUserId);
    await sendPushNotification(
      recipient.pushToken,
      `New message from ${sender?.username ?? 'Someone'}`,
      msg.text
    );
  }

  res.json({ message: msg });
});

app.post('/messages/:messageId/read', authMiddleware, (req, res) => {
  const currentUserId = req.user!.userId;
  const msg = messages.find((m) => m.id === req.params.messageId);

  if (!msg) {
    return res.status(404).json({ error: 'message not found' });
  }

  if (msg.toUserId !== currentUserId) {
    return res.status(403).json({ error: 'not allowed' });
  }

  msg.read = true;

  const senderSocketId = onlineUsers.get(msg.fromUserId);
  if (senderSocketId) {
    io.to(senderSocketId).emit('message:read', { messageId: msg.id });
  }

  res.json({ ok: true });
});

app.post('/notifications/register-push', authMiddleware, (req, res) => {
  const currentUserId = req.user!.userId;
  const { pushToken } = req.body as { pushToken?: string };

  const user = users.get(currentUserId);
  if (!user) {
    return res.status(404).json({ error: 'user not found' });
  }

  user.pushToken = pushToken;
  res.json({ ok: true });
});

app.post('/monetization/create-payment-intent', authMiddleware, async (req, res) => {
  try {
    const paymentIntent = await stripe.paymentIntents.create({
      amount: 499,
      currency: 'usd',
      automatic_payment_methods: { enabled: true },
      metadata: {
        type: 'premium_upgrade',
        userId: req.user!.userId
      }
    });

    res.json({
      clientSecret: paymentIntent.client_secret
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'payment intent failed' });
  }
});

app.post('/monetization/activate-premium', authMiddleware, (req, res) => {
  // MVP shortcut.
  // In production, validate Stripe webhook before enabling premium.
  const user = users.get(req.user!.userId);
  if (!user) {
    return res.status(404).json({ error: 'user not found' });
  }

  user.premium = true;
  res.json({ ok: true, premium: true });
});

io.on('connection', (socket) => {
  socket.on('auth:identify', ({ token }: { token: string }) => {
    try {
      const payload = JSON.parse(
        Buffer.from(token.split('.')[1], 'base64').toString()
      ) as { userId: string; username: string };

      onlineUsers.set(payload.userId, socket.id);
      socket.data.userId = payload.userId;

      io.emit('presence:update', {
        userId: payload.userId,
        online: true
      });
    } catch {
      socket.disconnect();
    }
  });

  socket.on('message:send', async ({ toUserId, text }: { toUserId: string; text: string }) => {
    const fromUserId = socket.data.userId as string | undefined;
    if (!fromUserId || !toUserId || !text?.trim()) return;

    const msg: Message = {
      id: uuid(),
      fromUserId,
      toUserId,
      text: text.trim(),
      createdAt: Date.now(),
      delivered: false,
      read: false
    };

    messages.push(msg);

    const recipientSocketId = onlineUsers.get(toUserId);
    if (recipientSocketId) {
      io.to(recipientSocketId).emit('message:new', msg);
      msg.delivered = true;
    } else {
      const recipient = users.get(toUserId);
      const sender = users.get(fromUserId);
      if (recipient?.pushToken) {
        await sendPushNotification(
          recipient.pushToken,
          `New message from ${sender?.username ?? 'Someone'}`,
          msg.text
        );
      }
    }

    socket.emit('message:sent', msg);
  });

  socket.on('disconnect', () => {
    const userId = socket.data.userId as string | undefined;
    if (userId) {
      onlineUsers.delete(userId);
      io.emit('presence:update', { userId, online: false });
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

