  Text,
  TextInput,
  TouchableOpacity,
  View
} from 'react-native';
import { io, Socket } from 'socket.io-client';
import * as Notifications from 'expo-notifications';

const API_URL = 'http://localhost:4000';
const SOCKET_URL = 'http://localhost:4000';

type AppUser = {
  id: string;
  username: string;
  premium: boolean;
};

type UserListItem = {
  id: string;
  username: string;
  premium: boolean;
  online: boolean;
};

type Message = {
  id: string;
  fromUserId: string;
  toUserId: string;
  text: string;
  createdAt: number;
  delivered: boolean;
  read: boolean;
};

export default function App() {
  const [token, setToken] = useState<string>('');
  const [me, setMe] = useState<AppUser | null>(null);
  const [username, setUsername] = useState('alice');
  const [password, setPassword] = useState('password');
  const [users, setUsers] = useState<UserListItem[]>([]);
  const [selectedUser, setSelectedUser] = useState<UserListItem | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState('');
  const [socket, setSocket] = useState<Socket | null>(null);

  const authHeaders = useMemo(
    () => ({
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`
    }),
    [token]
  );

  async function signup() {
    const res = await fetch(`${API_URL}/auth/signup`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    const data = await res.json();
    if (!res.ok) return Alert.alert('Signup failed', data.error || 'Unknown error');
    setToken(data.token);
    setMe(data.user);
  }

  async function login() {
    const res = await fetch(`${API_URL}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    const data = await res.json();
    if (!res.ok) return Alert.alert('Login failed', data.error || 'Unknown error');
    setToken(data.token);
    setMe(data.user);
  }

  async function loadUsers() {
    const res = await fetch(`${API_URL}/users`, { headers: authHeaders });
    const data = await res.json();
    if (res.ok) setUsers(data.users);
  }

  async function loadMessages(otherUserId: string) {
    const res = await fetch(`${API_URL}/messages/${otherUserId}`, { headers: authHeaders });
    const data = await res.json();
    if (res.ok) setMessages(data.messages);
  }

  async function sendMessageHttp() {
    if (!selectedUser || !draft.trim()) return;
    const res = await fetch(`${API_URL}/messages`, {
      method: 'POST',
      headers: authHeaders,
      body: JSON.stringify({
        toUserId: selectedUser.id,
        text: draft
      })
    });
    const data = await res.json();
    if (!res.ok) return Alert.alert('Send failed', data.error || 'Unknown error');
    setMessages((prev) => [...prev, data.message]);
    setDraft('');
  }

  async function registerPushToken() {
    const perms = await Notifications.requestPermissionsAsync();
    if (!perms.granted && !perms.ios?.status) return;

    const tokenResult = await Notifications.getExpoPushTokenAsync();
    await fetch(`${API_URL}/notifications/register-push`, {
      method: 'POST',
      headers: authHeaders,
      body: JSON.stringify({ pushToken: tokenResult.data })
    });
  }

  async function buyPremium() {
    const res = await fetch(`${API_URL}/monetization/create-payment-intent`, {
      method: 'POST',
      headers: authHeaders
    });
    const data = await res.json();
    if (!res.ok) return Alert.alert('Payment error', data.error || 'Unknown error');

    // MVP simplification:
    // skip payment sheet wiring and simulate successful unlock afterwards.
    const activateRes = await fetch(`${API_URL}/monetization/activate-premium`, {
      method: 'POST',
      headers: authHeaders
    });
    const activateData = await activateRes.json();
    if (activateRes.ok) {
      setMe((prev) => (prev ? { ...prev, premium: activateData.premium } : prev));
      Alert.alert('Success', 'Premium activated');
    }
  }

  useEffect(() => {
    if (!token) return;

    loadUsers();
    registerPushToken();

    const s = io(SOCKET_URL, { transports: ['websocket'] });
    s.on('connect', () => {
      s.emit('auth:identify', { token });
    });

    s.on('message:new', (msg: Message) => {
      if (
        selectedUser &&
        (msg.fromUserId === selectedUser.id || msg.toUserId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
      loadUsers();
    });

    s.on('message:sent', (msg: Message) => {
      if (
        selectedUser &&
        (msg.fromUserId === selectedUser.id || msg.toUserId === selectedUser.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    s.on('presence:update', ({ userId, online }: { userId: string; online: boolean }) => {
      setUsers((prev) =>
        prev.map((u) => (u.id === userId ? { ...u, online } : u))
      );
    });

    setSocket(s);
    return () => s.disconnect();
  }, [token, selectedUser?.id]);

  if (!me) {
    return (
      <SafeAreaView style={{ flex: 1, padding: 20, gap: 12 }}>
        <Text style={{ fontSize: 28, fontWeight: '700' }}>Social Messaging</Text>
        <TextInput
          placeholder="Username"
          value={username}
          onChangeText={setUsername}
          style={{ borderWidth: 1, padding: 12, borderRadius: 8 }}
        />
        <TextInput
          placeholder="Password"
          secureTextEntry
          value={password}
          onChangeText={setPassword}
          style={{ borderWidth: 1, padding: 12, borderRadius: 8 }}
        />
        <Button title="Sign Up" onPress={signup} />
        <Button title="Log In" onPress={login} />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={{ flex: 1, padding: 16 }}>
      <Text style={{ fontSize: 22, fontWeight: '700' }}>
        Hi {me.username} {me.premium ? '⭐' : ''}
      </Text>

      <View style={{ marginVertical: 10 }}>
        <Button title={me.premium ? 'Premium Active' : 'Buy Premium $4.99'} onPress={buyPremium} />
      </View>

      {!selectedUser ? (
        <View style={{ flex: 1 }}>
          <Button title="Refresh Users" onPress={loadUsers} />
          <FlatList
            data={users}
            keyExtractor={(item) => item.id}
            renderItem={({ item }) => (
              <TouchableOpacity
                onPress={() => {
                  setSelectedUser(item);
                  loadMessages(item.id);
                }}
                style={{
                  padding: 14,
                  borderBottomWidth: 1,
                  borderColor: '#ddd'
                }}
              >
                <Text style={{ fontSize: 18 }}>
                  {item.username} {item.online ? '🟢' : '⚪️'} {item.premium ? '⭐' : ''}
                </Text>
              </TouchableOpacity>
            )}
          />
        </View>
      ) : (
        <View style={{ flex: 1 }}>
          <Button title={`Back to users`} onPress={() => setSelectedUser(null)} />
          <Text style={{ fontSize: 20, marginVertical: 8 }}>
            Chat with {selectedUser.username}
          </Text>

          <FlatList
            style={{ flex: 1 }}
            data={messages}
            keyExtractor={(item) => item.id}
            renderItem={({ item }) => {
              const mine = item.fromUserId === me.id;
              return (
                <View
                  style={{
                    alignSelf: mine ? 'flex-end' : 'flex-start',
                    backgroundColor: mine ? '#cce5ff' : '#eee',
                    marginVertical: 4,
                    padding: 10,
                    borderRadius: 10,
                    maxWidth: '80%'
                  }}
                >
                  <Text>{item.text}</Text>
                  <Text style={{ fontSize: 10, marginTop: 4 }}>
                    {item.delivered ? 'Delivered' : 'Sent'}
                  </Text>
                </View>
              );
            }}
          />

          <TextInput
            placeholder="Type a message"
            value={draft}
            onChangeText={setDraft}
            style={{
              borderWidth: 1,
              borderRadius: 8,
              padding: 12,
              marginVertical: 8
            }}
          />

          <Button
            title="Send via Realtime Socket"
            onPress={() => {
              if (!selectedUser || !draft.trim() || !socket) return;
              socket.emit('message:send', {
                toUserId: selectedUser.id,
                text: draft
              });
              setDraft('');
            }}
          />

          <View style={{ height: 8 }} />
          <Button title="Send via HTTP" onPress={sendMessageHttp} />
        </View>
      )}
    </SafeAreaView>
  );
}
```

