## `server/src/store.ts`

```ts
import { Conversation, Message, User } from "./types";

export const users: User[] = [];
export const conversations: Conversation[] = [];
export const messages: Message[] = [];

export function findUserByUsername(username: string) {
  return users.find((u) => u.username.toLowerCase() === username.toLowerCase());
}

export function findUserById(id: string) {
  return users.find((u) => u.id === id);
}

export function getConversationById(id: string) {
  return conversations.find((c) => c.id === id);
}

export function getUserConversations(userId: string) {
  return conversations
    .filter((c) => c.participantIds.includes(userId))
    .sort((a, b) => b.lastMessageAt - a.lastMessageAt);
}

export function getConversationMessages(conversationId: string) {
  return messages
    .filter((m) => m.conversationId === conversationId)
    .sort((a, b) => a.createdAt - b.createdAt);
}
```

## `server/src/auth.ts`

```ts
import jwt from "jsonwebtoken";
import { Request, Response, NextFunction } from "express";
import { AuthenticatedRequestUser } from "./types";

const JWT_SECRET = process.env.JWT_SECRET || "dev_secret_change_me";

export function signToken(user: AuthenticatedRequestUser) {
  return jwt.sign(user, JWT_SECRET, { expiresIn: "7d" });
}

export type AuthedRequest = Request & {
  user?: AuthenticatedRequestUser;
};

export function authMiddleware(
  req: AuthedRequest,
  res: Response,
  next: NextFunction
) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Missing bearer token" });
  }

  const token = authHeader.replace("Bearer ", "");
  try {
    const decoded = jwt.verify(token, JWT_SECRET) as AuthenticatedRequestUser;
    req.user = decoded;
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}
```

