## `server/src/index.ts`

```ts
import "dotenv/config";
import express from "express";
import cors from "cors";
import bcrypt from "bcryptjs";
import { createServer } from "http";
import { Server } from "socket.io";
import { v4 as uuid } from "uuid";
import { authMiddleware, AuthedRequest, signToken } from "./auth";
import {
  conversations,
  findUserById,
  findUserByUsername,
  getConversationById,
  getConversationMessages,
  getUserConversations,
  messages,
  users
} from "./store";
import { stripe } from "./stripe";

const app = express();
const httpServer = createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(httpServer, {
  cors: {
    origin: "*"
  }
});

const onlineUsers = new Map<string, string>();

app.get("/health", (_, res) => {
  res.json({ ok: true });
});

app.post("/auth/register", async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "username and password required" });
  }

  if (findUserByUsername(username)) {
    return res.status(409).json({ error: "username already exists" });
  }

  const passwordHash = await bcrypt.hash(password, 10);
  const user = {
    id: uuid(),
    username,
    passwordHash,
    isPremium: false
  };

  users.push(user);

  const token = signToken({ id: user.id, username: user.username });

  return res.json({
    token,
    user: { id: user.id, username: user.username, isPremium: user.isPremium }
  });
});

app.post("/auth/login", async (req, res) => {
  const { username, password } = req.body;

  const user = findUserByUsername(username);
  if (!user) {
    return res.status(401).json({ error: "invalid credentials" });
  }

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) {
    return res.status(401).json({ error: "invalid credentials" });
  }

  const token = signToken({ id: user.id, username: user.username });

  return res.json({
    token,
    user: { id: user.id, username: user.username, isPremium: user.isPremium }
  });
});

app.post("/me/push-token", authMiddleware, (req: AuthedRequest, res) => {
  const user = findUserById(req.user!.id);
  if (!user) return res.status(404).json({ error: "user not found" });

  user.expoPushToken = req.body.expoPushToken;
  res.json({ ok: true });
});

app.get("/conversations", authMiddleware, (req: AuthedRequest, res) => {
  const userConversations = getUserConversations(req.user!.id).map((c) => ({
    ...c,
    messages: getConversationMessages(c.id)
  }));
  res.json(userConversations);
});

app.post("/conversations", authMiddleware, (req: AuthedRequest, res) => {
  const { participantUsername } = req.body;
  const otherUser = findUserByUsername(participantUsername);

  if (!otherUser) {
    return res.status(404).json({ error: "user not found" });
  }

  const existing = conversations.find(
    (c) =>
      c.participantIds.length === 2 &&
      c.participantIds.includes(req.user!.id) &&
      c.participantIds.includes(otherUser.id)
  );

  if (existing) return res.json(existing);

  const conversation = {
    id: uuid(),
    participantIds: [req.user!.id, otherUser.id],
    lastMessageAt: Date.now()
  };

  conversations.push(conversation);
  return res.json(conversation);
});

app.get(
  "/conversations/:conversationId/messages",
  authMiddleware,
  (req: AuthedRequest, res) => {
    const conversation = getConversationById(req.params.conversationId);
    if (!conversation) return res.status(404).json({ error: "not found" });

    if (!conversation.participantIds.includes(req.user!.id)) {
      return res.status(403).json({ error: "forbidden" });
    }

    res.json(getConversationMessages(conversation.id));
  }
);

app.post(
  "/conversations/:conversationId/messages",
  authMiddleware,
  async (req: AuthedRequest, res) => {
    const conversation = getConversationById(req.params.conversationId);
    if (!conversation) return res.status(404).json({ error: "not found" });

    if (!conversation.participantIds.includes(req.user!.id)) {
      return res.status(403).json({ error: "forbidden" });
    }

    const sender = findUserById(req.user!.id);
    if (!sender) return res.status(404).json({ error: "sender not found" });

    const { text } = req.body;
    if (!text?.trim()) {
      return res.status(400).json({ error: "text required" });
    }

    if (!sender.isPremium && text.length > 300) {
      return res
        .status(402)
        .json({ error: "premium required for messages over 300 characters" });
    }

    const message = {
      id: uuid(),
      conversationId: conversation.id,
      senderId: sender.id,
      text,
      createdAt: Date.now()
    };

    messages.push(message);
    conversation.lastMessageAt = message.createdAt;

    io.to(conversation.id).emit("message:new", message);

    res.json(message);
  }
);

app.post(
  "/billing/create-checkout-session",
  authMiddleware,
  async (req: AuthedRequest, res) => {
    try {
      if (!process.env.STRIPE_SECRET_KEY || !process.env.STRIPE_PRICE_ID) {
        return res.status(500).json({ error: "stripe not configured" });
      }

      const session = await stripe.checkout.sessions.create({
        mode: "subscription",
        line_items: [
          {
            price: process.env.STRIPE_PRICE_ID,
            quantity: 1
          }
        ],
        success_url: `${process.env.CLIENT_SUCCESS_URL}?success=true`,
        cancel_url: `${process.env.CLIENT_CANCEL_URL}?canceled=true`,
        metadata: {
          userId: req.user!.id
        }
      });

      res.json({ url: session.url });
    } catch (e) {
      console.error(e);
      res.status(500).json({ error: "failed to create checkout session" });
    }
  }
);

app.post("/billing/mock-upgrade", authMiddleware, (req: AuthedRequest, res) => {
  const user = findUserById(req.user!.id);
  if (!user) return res.status(404).json({ error: "user not found" });

  user.isPremium = true;
  res.json({ ok: true, isPremium: true });
});

io.use((socket, next) => {
  const { userId } = socket.handshake.auth;
  if (!userId) return next(new Error("unauthorized"));
  socket.data.userId = userId;
  next();
});

io.on("connection", (socket) => {
  const userId = socket.data.userId as string;
  onlineUsers.set(userId, socket.id);

  const userConversations = getUserConversations(userId);
  userConversations.forEach((c) => socket.join(c.id));

  socket.on("join:conversation", (conversationId: string) => {
    socket.join(conversationId);
  });

  socket.on("disconnect", () => {
    onlineUsers.delete(userId);
  });
});

const PORT = process.env.PORT || 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

