const API_URL = "http://localhost:4000";

let authToken: string | null = null;

export function setToken(token: string) {
  authToken = token;
}

async function request(path: string, options: RequestInit = {}) {
  const res = await fetch(`${API_URL}${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(authToken ? { Authorization: `Bearer ${authToken}` } : {}),
      ...(options.headers || {})
    }
  });

  const data = await res.json();
  if (!res.ok) throw new Error(data.error || "request failed");
  return data;
}

export const api = {
  register: (username: string, password: string) =>
    request("/auth/register", {
      method: "POST",
      body: JSON.stringify({ username, password })
    }),

  login: (username: string, password: string) =>
    request("/auth/login", {
      method: "POST",
      body: JSON.stringify({ username, password })
    }),

  getConversations: () => request("/conversations"),

  createConversation: (participantUsername: string) =>
    request("/conversations", {
      method: "POST",
      body: JSON.stringify({ participantUsername })
    }),

  getMessages: (conversationId: string) =>
    request(`/conversations/${conversationId}/messages`),

  sendMessage: (conversationId: string, text: string) =>
    request(`/conversations/${conversationId}/messages`, {
      method: "POST",
      body: JSON.stringify({ text })
    }),

  registerPushToken: (expoPushToken: string) =>
    request("/me/push-token", {
      method: "POST",
      body: JSON.stringify({ expoPushToken })
    }),

  createCheckoutSession: () =>
    request("/billing/create-checkout-session", {
      method: "POST"
    }),

  mockUpgrade: () =>
    request("/billing/mock-upgrade", {
      method: "POST"
    })
};
