```tsx
import React, { useEffect, useState } from "react";
import {
  Alert,
  Button,
  FlatList,
  SafeAreaView,
  Text,
  TextInput,
  TouchableOpacity,
  View
} from "react-native";
import * as Notifications from "expo-notifications";
import * as Device from "expo-device";
import { api, setToken } from "./api";
import { connectSocket, getSocket } from "./socket";

type User = {
  id: string;
  username: string;
  isPremium: boolean;
};

type Conversation = {
  id: string;
  participantIds: string[];
  lastMessageAt: number;
  messages?: Message[];
};

type Message = {
  id: string;
  conversationId: string;
  senderId: string;
  text: string;
  createdAt: number;
};

Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: false,
    shouldSetBadge: false
  })
});

async function registerForPushNotificationsAsync() {
  if (!Device.isDevice) return null;

  const { status: existingStatus } = await Notifications.getPermissionsAsync();
  let finalStatus = existingStatus;

  if (existingStatus !== "granted") {
    const { status } = await Notifications.requestPermissionsAsync();
    finalStatus = status;
  }

  if (finalStatus !== "granted") return null;

  const token = await Notifications.getExpoPushTokenAsync();
  return token.data;
}

export default function App() {
  const [mode, setMode] = useState<"auth" | "chats" | "chat" | "premium">(
    "auth"
  );
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [participantUsername, setParticipantUsername] = useState("");
  const [text, setText] = useState("");
  const [me, setMe] = useState<User | null>(null);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);

  async function afterAuth(token: string, user: User) {
    setToken(token);
    setMe(user);

    const expoPushToken = await registerForPushNotificationsAsync();
    if (expoPushToken) {
      await api.registerPushToken(expoPushToken);
    }

    const socket = connectSocket(user.id);
    socket.on("message:new", async (message: Message) => {
      if (selectedConversation?.id === message.conversationId) {
        setMessages((prev) => [...prev, message]);
      } else {
        await Notifications.scheduleNotificationAsync({
          content: {
            title: "New message",
            body: message.text
          },
          trigger: null
        });
      }
    });

    await loadConversations();
    setMode("chats");
  }

  async function loadConversations() {
    const data = await api.getConversations();
    setConversations(data);
  }

  async function loadMessages(conversation: Conversation) {
    const data = await api.getMessages(conversation.id);
    setSelectedConversation(conversation);
    setMessages(data);
    getSocket()?.emit("join:conversation", conversation.id);
    setMode("chat");
  }

  async function handleRegister() {
    try {
      const result = await api.register(username, password);
      await afterAuth(result.token, result.user);
    } catch (e: any) {
      Alert.alert("Register failed", e.message);
    }
  }

  async function handleLogin() {
    try {
      const result = await api.login(username, password);
      await afterAuth(result.token, result.user);
    } catch (e: any) {
      Alert.alert("Login failed", e.message);
    }
  }

  async function handleCreateConversation() {
    try {
      await api.createConversation(participantUsername);
      setParticipantUsername("");
      await loadConversations();
    } catch (e: any) {
      Alert.alert("Create conversation failed", e.message);
    }
  }

  async function handleSendMessage() {
    if (!selectedConversation) return;
    try {
      const message = await api.sendMessage(selectedConversation.id, text);
      setMessages((prev) => [...prev, message]);
      setText("");
    } catch (e: any) {
      Alert.alert("Send failed", e.message);
    }
  }

  async function handleUpgrade() {
    try {
      await api.mockUpgrade();
      setMe((prev) => (prev ? { ...prev, isPremium: true } : prev));
      Alert.alert("Upgraded", "Premium unlocked");
    } catch (e: any) {
      Alert.alert("Upgrade failed", e.message);
    }
  }

  if (mode === "auth") {
    return (
      <SafeAreaView style={{ flex: 1, padding: 20, gap: 12 }}>
        <Text style={{ fontSize: 28, fontWeight: "700" }}>Social Messenger</Text>
        <TextInput
          placeholder="Username"
          value={username}
          onChangeText={setUsername}
          style={{ borderWidth: 1, padding: 12 }}
        />
        <TextInput
          placeholder="Password"
          value={password}
          onChangeText={setPassword}
          secureTextEntry
          style={{ borderWidth: 1, padding: 12 }}
        />
        <Button title="Register" onPress={handleRegister} />
        <Button title="Login" onPress={handleLogin} />
      </SafeAreaView>
    );
  }

  if (mode === "premium") {
    return (
      <SafeAreaView style={{ flex: 1, padding: 20, gap: 12 }}>
        <Text style={{ fontSize: 24, fontWeight: "700" }}>Premium</Text>
        <Text>Unlock longer messages and premium features.</Text>
        <Button title="Mock Upgrade" onPress={handleUpgrade} />
        <Button title="Back" onPress={() => setMode("chats")} />
      </SafeAreaView>
    );
  }

  if (mode === "chat" && selectedConversation) {
    return (
      <SafeAreaView style={{ flex: 1, padding: 20 }}>
        <Button title="Back" onPress={() => setMode("chats")} />
        <FlatList
          data={messages}
          keyExtractor={(item) => item.id}
          renderItem={({ item }) => (
            <View
              style={{
                padding: 10,
                marginVertical: 4,
                backgroundColor:
                  item.senderId === me?.id ? "#DCF8C6" : "#EEE",
                alignSelf: item.senderId === me?.id ? "flex-end" : "flex-start",
                borderRadius: 8,
                maxWidth: "80%"
              }}
            >
              <Text>{item.text}</Text>
            </View>
          )}
        />
        <TextInput
          placeholder={
            me?.isPremium
              ? "Type a message"
              : "Type a message (premium for >300 chars)"
          }
          value={text}
          onChangeText={setText}
          style={{ borderWidth: 1, padding: 12, marginVertical: 8 }}
        />
        <Button title="Send" onPress={handleSendMessage} />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={{ flex: 1, padding: 20, gap: 10 }}>
      <Text style={{ fontSize: 24, fontWeight: "700" }}>
        Welcome, {me?.username}
      </Text>
      <Text>Premium: {me?.isPremium ? "Yes" : "No"}</Text>
      <Button title="Premium" onPress={() => setMode("premium")} />

      <TextInput
        placeholder="Start chat with username"
        value={participantUsername}
        onChangeText={setParticipantUsername}
        style={{ borderWidth: 1, padding: 12 }}
      />
      <Button title="Create Conversation" onPress={handleCreateConversation} />

      <FlatList
        data={conversations}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <TouchableOpacity
            onPress={() => loadMessages(item)}
            style={{ padding: 14, borderBottomWidth: 1 }}
          >
            <Text>Conversation: {item.id}</Text>
            <Text>
              Messages: {item.messages?.length ?? 0}
            </Text>
          </TouchableOpacity>
        )}
      />
    </SafeAreaView>
  );
}
