import express from "express";
import http from "http";
import cors from "cors";
import dotenv from "dotenv";
import { Server } from "socket.io";
import Stripe from "stripe";

dotenv.config();

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

const PORT = process.env.PORT || 4000;
const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY || "";

const stripe = new Stripe(STRIPE_SECRET_KEY, {
  apiVersion: "2024-06-20"
});

type ChatMessage = {
  id: string;
  user: string;
  text: string;
  createdAt: string;
};

const messages: ChatMessage[] = [];
const pushTokens = new Map<string, string>();

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.get("/messages", (_req, res) => {
  res.json(messages);
});

app.post("/register-push-token", (req, res) => {
  const { username, token } = req.body as { username?: string; token?: string };

  if (!username || !token) {
    return res.status(400).json({ error: "username and token are required" });
  }

  pushTokens.set(username, token);
  return res.json({ success: true });
});

app.post("/create-payment-intent", async (req, res) => {
  try {
    const { amount = 499, currency = "usd" } = req.body;

    const paymentIntent = await stripe.paymentIntents.create({
      amount,
      currency,
      automatic_payment_methods: { enabled: true }
    });

    res.json({
      clientSecret: paymentIntent.client_secret
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

io.on("connection", (socket) => {
  socket.on("join", (username: string) => {
    socket.data.username = username;
    socket.emit("messages:init", messages);
  });

  socket.on("message:send", async (payload: { text: string }) => {
    const user = socket.data.username || "Anonymous";
    const text = payload?.text?.trim();

    if (!text) return;

    const msg: ChatMessage = {
      id: Math.random().toString(36).slice(2),
      user,
      text,
      createdAt: new Date().toISOString()
    };

    messages.push(msg);
    io.emit("message:new", msg);

    // Placeholder for real push dispatch
    // In production you would call Expo's push API or FCM/APNs here for offline users
  });

  socket.on("disconnect", () => {
    // no-op
  });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

