import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  SafeAreaView,
  View,
  Text,
  TextInput,
  TouchableOpacity,
  FlatList,
  StyleSheet,
  Alert
} from "react-native";
import { io, Socket } from "socket.io-client";
import * as Notifications from "expo-notifications";
import * as Device from "expo-device";
import { StripeProvider, useStripe } from "@stripe/stripe-react-native";

const SERVER_URL = "http://YOUR_LOCAL_IP:4000";

type ChatMessage = {
  id: string;
  user: string;
  text: string;
  createdAt: string;
};

Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldPlaySound: true,
    shouldSetBadge: false,
    shouldShowAlert: true
  })
});

async function registerForPushNotificationsAsync() {
  if (!Device.isDevice) return null;

  const { status: existingStatus } = await Notifications.getPermissionsAsync();
  let finalStatus = existingStatus;

  if (existingStatus !== "granted") {
    const { status } = await Notifications.requestPermissionsAsync();
    finalStatus = status;
  }

  if (finalStatus !== "granted") {
    return null;
  }

  const token = await Notifications.getExpoPushTokenAsync();
  return token.data;
}

function ChatScreen() {
  const [username, setUsername] = useState("");
  const [joined, setJoined] = useState(false);
  const [text, setText] = useState("");
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const socketRef = useRef<Socket | null>(null);
  const { initPaymentSheet, presentPaymentSheet } = useStripe();

  const canJoin = useMemo(() => username.trim().length > 0, [username]);

  useEffect(() => {
    return () => {
      socketRef.current?.disconnect();
    };
  }, []);

  const joinChat = async () => {
    const socket = io(SERVER_URL, {
      transports: ["websocket"]
    });

    socketRef.current = socket;

    socket.on("connect", () => {
      socket.emit("join", username);
      setJoined(true);
    });

    socket.on("messages:init", (initialMessages: ChatMessage[]) => {
      setMessages(initialMessages);
    });

    socket.on("message:new", (msg: ChatMessage) => {
      setMessages((prev) => [...prev, msg]);
    });

    const expoToken = await registerForPushNotificationsAsync();
    if (expoToken) {
      await fetch(`${SERVER_URL}/register-push-token`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          username,
          token: expoToken
        })
      });
    }
  };

  const sendMessage = () => {
    if (!text.trim()) return;
    socketRef.current?.emit("message:send", { text });
    setText("");
  };

  const buyCoins = async () => {
    try {
      const res = await fetch(`${SERVER_URL}/create-payment-intent`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          amount: 499,
          currency: "usd"
        })
      });

      const data = await res.json();

      const init = await initPaymentSheet({
        merchantDisplayName: "Social Messaging App",
        paymentIntentClientSecret: data.clientSecret
      });

      if (init.error) {
        Alert.alert("Payment error", init.error.message);
        return;
      }

      const present = await presentPaymentSheet();

      if (present.error) {
        Alert.alert("Payment failed", present.error.message);
      } else {
        Alert.alert("Success", "Coins purchased successfully");
      }
    } catch (e: any) {
      Alert.alert("Error", e.message);
    }
  };

  if (!joined) {
    return (
      <SafeAreaView style={styles.container}>
        <Text style={styles.title}>Social Messaging</Text>
        <TextInput
          value={username}
          onChangeText={setUsername}
          placeholder="Enter username"
          style={styles.input}
        />
        <TouchableOpacity
          style={[styles.button, !canJoin && styles.buttonDisabled]}
          disabled={!canJoin}
          onPress={joinChat}
        >
          <Text style={styles.buttonText}>Join Chat</Text>
        </TouchableOpacity>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Global Chat</Text>

      <TouchableOpacity style={styles.coinsButton} onPress={buyCoins}>
        <Text style={styles.buttonText}>Buy Coins ($4.99)</Text>
      </TouchableOpacity>

      <FlatList
        style={styles.list}
        data={messages}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={styles.messageCard}>
            <Text style={styles.messageUser}>{item.user}</Text>
            <Text>{item.text}</Text>
          </View>
        )}
      />

      <View style={styles.composer}>
        <TextInput
          value={text}
          onChangeText={setText}
          placeholder="Type a message"
          style={[styles.input, styles.composerInput]}
        />
        <TouchableOpacity style={styles.sendButton} onPress={sendMessage}>
          <Text style={styles.buttonText}>Send</Text>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
}

export default function App() {
  return (
    <StripeProvider publishableKey="pk_test_your_key_here">
      <ChatScreen />
    </StripeProvider>
  );
}

