  container: {
    flex: 1,
    backgroundColor: "#fff",
    padding: 16
  },
  title: {
    fontSize: 28,
    fontWeight: "700",
    marginBottom: 16
  },
  input: {
    borderWidth: 1,
    borderColor: "#ddd",
    borderRadius: 10,
    padding: 12,
    marginBottom: 12
  },
  button: {
    backgroundColor: "#2563eb",
    padding: 14,
    borderRadius: 10,
    alignItems: "center"
  },
  coinsButton: {
    backgroundColor: "#16a34a",
    padding: 12,
