```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuid } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

type User = {
  username: string;
  premium: boolean;
};

type Message = {
  id: string;
  from: string;
  to?: string;
  room?: string;
  content: string;
  createdAt: number;
  premiumOnly?: boolean;
};

const users = new Map<string, User>(); // token -> user
const onlineUsers = new Map<string, string>(); // username -> socketId
const publicMessages: Message[] = [];
const directMessages: Message[] = [];

function authMiddleware(req: express.Request, res: express.Response, next: express.NextFunction) {
  const token = req.headers.authorization?.replace("Bearer ", "");
  if (!token || !users.has(token)) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  (req as any).user = users.get(token);
  (req as any).token = token;
  next();
}

app.get("/", (_req, res) => {
  res.json({ ok: true, service: "social messaging api" });
});

// Demo login/signup
app.post("/auth/login", (req, res) => {
  const { username } = req.body as { username?: string };
  if (!username || username.trim().length < 2) {
    return res.status(400).json({ error: "Username too short" });
  }

  const token = uuid();
  users.set(token, { username: username.trim(), premium: false });

  res.json({
    token,
    user: users.get(token)
  });
});

// Get current user
app.get("/me", authMiddleware, (req, res) => {
  res.json({ user: (req as any).user });
});

// Public room history
app.get("/messages/public", authMiddleware, (_req, res) => {
  res.json(publicMessages);
});

// Direct message history for current user
app.get("/messages/direct", authMiddleware, (req, res) => {
  const currentUser = (req as any).user as User;
  const myMessages = directMessages.filter(
    m => m.from === currentUser.username || m.to === currentUser.username
  );
  res.json(myMessages);
});

// Mock purchase endpoint
app.post("/purchase/premium", authMiddleware, (req, res) => {
  const token = (req as any).token as string;
  const user = users.get(token)!;
  user.premium = true;
  users.set(token, user);

  res.json({
    success: true,
    message: "Premium unlocked",
    user
  });
});

// Premium-only feature
app.post("/messages/premium-broadcast", authMiddleware, (req, res) => {
  const user = (req as any).user as User;
  if (!user.premium) {
    return res.status(403).json({ error: "Premium required" });
  }

  const { content } = req.body as { content?: string };
  if (!content?.trim()) {
    return res.status(400).json({ error: "Content required" });
  }

  const msg: Message = {
    id: uuid(),
    from: user.username,
    room: "public",
    content: content.trim(),
    createdAt: Date.now(),
    premiumOnly: true
  };

  publicMessages.push(msg);
  io.emit("message:public", msg);
  io.emit("notification", {
    id: uuid(),
    type: "premium_broadcast",
    text: `${user.username} sent a premium broadcast`
  });

  res.json(msg);
});

io.on("connection", socket => {
  const username = socket.handshake.auth.username as string | undefined;

  if (!username) {
    socket.disconnect();
    return;
  }

  onlineUsers.set(username, socket.id);
  io.emit("presence:update", Array.from(onlineUsers.keys()));

  socket.on("join:public", () => {
    socket.join("public");
  });

  socket.on("message:public", (payload: { from: string; content: string }) => {
    if (!payload?.from || !payload?.content?.trim()) return;

    const msg: Message = {
      id: uuid(),
      from: payload.from,
      room: "public",
      content: payload.content.trim(),
      createdAt: Date.now()
    };

    publicMessages.push(msg);
    io.to("public").emit("message:public", msg);
    io.emit("notification", {
      id: uuid(),
      type: "public_message",
      text: `${payload.from} posted in public room`
    });
  });

  socket.on("message:direct", (payload: { from: string; to: string; content: string }) => {
    if (!payload?.from || !payload?.to || !payload?.content?.trim()) return;

    const msg: Message = {
      id: uuid(),
      from: payload.from,
      to: payload.to,
      content: payload.content.trim(),
      createdAt: Date.now()
    };

    directMessages.push(msg);

    const toSocketId = onlineUsers.get(payload.to);
    const fromSocketId = onlineUsers.get(payload.from);

    if (toSocketId) io.to(toSocketId).emit("message:direct", msg);
    if (fromSocketId) io.to(fromSocketId).emit("message:direct", msg);

    if (toSocketId) {
      io.to(toSocketId).emit("notification", {
        id: uuid(),
        type: "direct_message",
        text: `New direct message from ${payload.from}`
      });
    }
  });

  socket.on("disconnect", () => {
    for (const [name, id] of onlineUsers.entries()) {
      if (id === socket.id) {
        onlineUsers.delete(name);
        break;
      }
    }
    io.emit("presence:update", Array.from(onlineUsers.keys()));
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

