## `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

const API_URL = "http://localhost:4000";

type User = {
  username: string;
  premium: boolean;
};

type Message = {
  id: string;
  from: string;
  to?: string;
  room?: string;
  content: string;
  createdAt: number;
  premiumOnly?: boolean;
};

type NotificationItem = {
  id: string;
  type: string;
  text: string;
};

export default function App() {
  const [usernameInput, setUsernameInput] = useState("");
  const [token, setToken] = useState<string | null>(localStorage.getItem("token"));
  const [user, setUser] = useState<User | null>(null);

  const [publicMessages, setPublicMessages] = useState<Message[]>([]);
  const [directMessages, setDirectMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [onlineUsers, setOnlineUsers] = useState<string[]>([]);

  const [publicText, setPublicText] = useState("");
  const [dmTo, setDmTo] = useState("");
  const [dmText, setDmText] = useState("");
  const [premiumText, setPremiumText] = useState("");

  const socket: Socket | null = useMemo(() => {
    if (!user) return null;
    return io(API_URL, {
      auth: { username: user.username }
    });
  }, [user]);

  useEffect(() => {
    if (token) {
      fetch(`${API_URL}/me`, {
        headers: { Authorization: `Bearer ${token}` }
      })
        .then(r => {
          if (!r.ok) throw new Error("Unauthorized");
          return r.json();
        })
        .then(data => setUser(data.user))
        .catch(() => {
          localStorage.removeItem("token");
          setToken(null);
          setUser(null);
        });
    }
  }, [token]);

  useEffect(() => {
    if (!token || !user) return;

    fetch(`${API_URL}/messages/public`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(setPublicMessages);

    fetch(`${API_URL}/messages/direct`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(setDirectMessages);
  }, [token, user]);

  useEffect(() => {
    if (!socket) return;

    socket.emit("join:public");

    socket.on("message:public", (msg: Message) => {
      setPublicMessages(prev => [...prev, msg]);
    });

    socket.on("message:direct", (msg: Message) => {
      setDirectMessages(prev => [...prev, msg]);
    });

    socket.on("notification", (n: NotificationItem) => {
      setNotifications(prev => [n, ...prev].slice(0, 20));
    });

    socket.on("presence:update", (users: string[]) => {
      setOnlineUsers(users);
    });

    return () => {
      socket.disconnect();
    };
  }, [socket]);

  async function login() {
    const res = await fetch(`${API_URL}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: usernameInput })
    });
    const data = await res.json();
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    }
  }

  function sendPublicMessage() {
    if (!socket || !user || !publicText.trim()) return;
    socket.emit("message:public", {
      from: user.username,
      content: publicText
    });
    setPublicText("");
  }

  function sendDirectMessage() {
    if (!socket || !user || !dmTo.trim() || !dmText.trim()) return;
    socket.emit("message:direct", {
      from: user.username,
      to: dmTo.trim(),
      content: dmText.trim()
    });
    setDmText("");
  }

  async function buyPremium() {
    if (!token) return;
    const res = await fetch(`${API_URL}/purchase/premium`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`
      }
    });
    const data = await res.json();
    setUser(data.user);
  }

  async function sendPremiumBroadcast() {
    if (!token || !premiumText.trim()) return;

    const res = await fetch(`${API_URL}/messages/premium-broadcast`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ content: premiumText })
    });

    const data = await res.json();

    if (res.ok) {
      setPremiumText("");
      setPublicMessages(prev => [...prev, data]);
    } else {
      alert(data.error || "Failed");
    }
  }

  function logout() {
    localStorage.removeItem("token");
    setToken(null);
    setUser(null);
    setPublicMessages([]);
    setDirectMessages([]);
    setNotifications([]);
    setOnlineUsers([]);
  }

  if (!user) {
    return (
      <div style={{ padding: 24, fontFamily: "Arial, sans-serif" }}>
        <h1>Social Messaging App</h1>
        <p>Login with a username:</p>
        <input
          value={usernameInput}
          onChange={e => setUsernameInput(e.target.value)}
          placeholder="Username"
        />
        <button onClick={login} style={{ marginLeft: 8 }}>
          Login
        </button>
      </div>
    );
  }

  return (
    <div style={{ fontFamily: "Arial, sans-serif", padding: 20 }}>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <div>
          <h1>Social Messaging App</h1>
          <p>
            Logged in as <strong>{user.username}</strong>{" "}
            {user.premium ? "👑 Premium" : ""}
          </p>
        </div>
        <div>
          {!user.premium && <button onClick={buyPremium}>Buy Premium</button>}
          <button onClick={logout} style={{ marginLeft: 8 }}>
            Logout
          </button>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 300px", gap: 20 }}>
        <div>
          <h2>Public Room</h2>
          <div
            style={{
              border: "1px solid #ccc",
              minHeight: 250,
              padding: 10,
              marginBottom: 10,
              overflowY: "auto"
            }}
          >
            {publicMessages.map(msg => (
              <div key={msg.id} style={{ marginBottom: 8 }}>
                <strong>{msg.from}</strong>: {msg.content}{" "}
                {msg.premiumOnly && <span style={{ color: "purple" }}>[Premium]</span>}
              </div>
            ))}
          </div>
          <input
            value={publicText}
            onChange={e => setPublicText(e.target.value)}
            placeholder="Write public message"
          />
          <button onClick={sendPublicMessage} style={{ marginLeft: 8 }}>
            Send
          </button>

          <h3 style={{ marginTop: 20 }}>Premium Broadcast</h3>
          <input
            value={premiumText}
            onChange={e => setPremiumText(e.target.value)}
            placeholder="Premium announcement"
          />
          <button onClick={sendPremiumBroadcast} style={{ marginLeft: 8 }}>
            Broadcast
          </button>
        </div>

        <div>
          <h2>Direct Messages</h2>
          <div
            style={{
              border: "1px solid #ccc",
              minHeight: 250,
              padding: 10,
              marginBottom: 10,
              overflowY: "auto"
            }}
          >
            {directMessages.map(msg => (
              <div key={msg.id} style={{ marginBottom: 8 }}>
                <strong>{msg.from}</strong>
                {msg.to ? ` → ${msg.to}` : ""}: {msg.content}
              </div>
            ))}
          </div>

          <input
            value={dmTo}
            onChange={e => setDmTo(e.target.value)}
            placeholder="Recipient username"
          />
          <input
            value={dmText}
            onChange={e => setDmText(e.target.value)}
            placeholder="Message"
            style={{ marginLeft: 8 }}
          />
          <button onClick={sendDirectMessage} style={{ marginLeft: 8 }}>
            Send DM
          </button>
        </div>

        <div>
          <h2>Notifications</h2>
          <div style={{ border: "1px solid #ccc", padding: 10, minHeight: 120 }}>
            {notifications.map(n => (
              <div key={n.id} style={{ marginBottom: 8 }}>
                {n.text}
              </div>
            ))}
          </div>

          <h2 style={{ marginTop: 20 }}>Online Users</h2>
          <div style={{ border: "1px solid #ccc", padding: 10, minHeight: 120 }}>
            {onlineUsers.map(name => (
              <div key={name}>{name}</div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
```

