```ts
import express from "express";
import http from "http";
import cors from "cors";
import dotenv from "dotenv";
import { Server } from "socket.io";
import Stripe from "stripe";

dotenv.config();

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL || "http://localhost:5173",
    methods: ["GET", "POST"]
  }
});

const stripeKey = process.env.STRIPE_SECRET_KEY || "";
const stripe = new Stripe(stripeKey);

app.use(cors({ origin: process.env.CLIENT_URL || "http://localhost:5173" }));
app.use(express.json());

type Message = {
  id: string;
  user: string;
  text: string;
  createdAt: number;
};

const messages: Message[] = [];
const onlineUsers = new Set<string>();

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.get("/messages", (_req, res) => {
  res.json(messages);
});

app.post("/create-checkout-session", async (req, res) => {
  try {
    const { username } = req.body as { username?: string };

    if (!stripeKey) {
      return res.status(500).json({ error: "Stripe key not configured" });
    }

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Membership",
              description: `Premium upgrade for ${username || "user"}`
            },
            unit_amount: 499
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}?paid=true`,
      cancel_url: `${process.env.CLIENT_URL}?paid=false`
    });

    res.json({ url: session.url });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: "Failed to create checkout session" });
  }
});

io.on("connection", (socket) => {
  let currentUser = "";

  socket.on("join", (username: string) => {
    currentUser = username;
    onlineUsers.add(username);

    socket.emit("init", {
      messages,
      onlineUsers: Array.from(onlineUsers)
    });

    io.emit("notification", {
      type: "user_joined",
      message: `${username} joined`
    });

    io.emit("online_users", Array.from(onlineUsers));
  });

  socket.on("send_message", (text: string) => {
    if (!currentUser || !text.trim()) return;

    const message: Message = {
      id: `${Date.now()}-${Math.random()}`,
      user: currentUser,
      text: text.trim(),
      createdAt: Date.now()
    };

    messages.push(message);
    io.emit("new_message", message);
    io.emit("notification", {
      type: "new_message",
      message: `${currentUser} sent a message`
    });
  });

  socket.on("disconnect", () => {
    if (currentUser) {
      onlineUsers.delete(currentUser);

      io.emit("notification", {
        type: "user_left",
        message: `${currentUser} left`
      });

      io.emit("online_users", Array.from(onlineUsers));
    }
  });
});

const port = Number(process.env.PORT) || 4000;
server.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});
```

