```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type Message = {
  id: string;
  user: string;
  text: string;
  createdAt: number;
};

type Notification = {
  type: string;
  message: string;
};

const SERVER_URL = "http://localhost:4000";

export default function App() {
  const [username, setUsername] = useState("");
  const [joined, setJoined] = useState(false);
  const [messageInput, setMessageInput] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [onlineUsers, setOnlineUsers] = useState<string[]>([]);

  const socket: Socket = useMemo(() => io(SERVER_URL, { autoConnect: false }), []);

  useEffect(() => {
    socket.on("init", (data: { messages: Message[]; onlineUsers: string[] }) => {
      setMessages(data.messages);
      setOnlineUsers(data.onlineUsers);
    });

    socket.on("new_message", (message: Message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on("notification", (notification: Notification) => {
      setNotifications((prev) => [notification, ...prev].slice(0, 20));
    });

    socket.on("online_users", (users: string[]) => {
      setOnlineUsers(users);
    });

    return () => {
      socket.disconnect();
    };
  }, [socket]);

  const joinChat = () => {
    if (!username.trim()) return;
    socket.connect();
    socket.emit("join", username.trim());
    setJoined(true);
  };

  const sendMessage = () => {
    if (!messageInput.trim()) return;
    socket.emit("send_message", messageInput);
    setMessageInput("");
  };

  const upgradeToPremium = async () => {
    const res = await fetch(`${SERVER_URL}/create-checkout-session`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ username })
    });

    const data = await res.json();
    if (data.url) {
      window.location.href = data.url;
    } else {
      alert("Failed to start payment flow");
    }
  };

  return (
    <div style={{ fontFamily: "Arial, sans-serif", maxWidth: 900, margin: "0 auto", padding: 24 }}>
      <h1>Social Messaging App</h1>

      {!joined ? (
        <div style={{ display: "flex", gap: 8 }}>
          <input
            placeholder="Enter username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <button onClick={joinChat}>Join</button>
        </div>
      ) : (
        <>
          <div style={{ marginBottom: 16 }}>
            <strong>Logged in as:</strong> {username}
          </div>

          <button onClick={upgradeToPremium} style={{ marginBottom: 16 }}>
            Upgrade to Premium ($4.99)
          </button>

          <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 20 }}>
            <div>
              <h2>Chat</h2>
              <div
                style={{
                  border: "1px solid #ccc",
                  height: 300,
                  overflowY: "auto",
                  padding: 12,
                  marginBottom: 12
                }}
              >
                {messages.map((msg) => (
                  <div key={msg.id} style={{ marginBottom: 10 }}>
                    <strong>{msg.user}:</strong> {msg.text}
                  </div>
                ))}
              </div>

              <div style={{ display: "flex", gap: 8 }}>
                <input
                  style={{ flex: 1 }}
                  placeholder="Type a message"
                  value={messageInput}
                  onChange={(e) => setMessageInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") sendMessage();
                  }}
                />
                <button onClick={sendMessage}>Send</button>
              </div>
            </div>

            <div>
              <h2>Online Users</h2>
              <ul>
                {onlineUsers.map((user) => (
                  <li key={user}>{user}</li>
                ))}
              </ul>

              <h2>Notifications</h2>
              <ul>
                {notifications.map((n, index) => (
                  <li key={index}>
                    [{n.type}] {n.message}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </>
      )}
    </div>
  );
}
