```ts
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";
import { v4 as uuid } from "uuid";

const app = express();
const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: "*"
  }
});

app.use(cors());
app.use(express.json());

type User = {
  id: string;
  username: string;
  premium: boolean;
};

type Message = {
  id: string;
  from: string;
  to: string;
  text: string;
  createdAt: number;
};

const users: User[] = [];
const messages: Message[] = [];

// Map userId -> socketId
const connectedUsers = new Map<string, string>();

app.get("/", (_req, res) => {
  res.json({ ok: true, service: "social messaging api" });
});

// Register/login a user
app.post("/login", (req, res) => {
  const { username } = req.body as { username?: string };

  if (!username || !username.trim()) {
    return res.status(400).json({ error: "username is required" });
  }

  let user = users.find((u) => u.username === username);
  if (!user) {
    user = {
      id: uuid(),
      username: username.trim(),
      premium: false
    };
    users.push(user);
  }

  res.json(user);
});

// List all users
app.get("/users", (_req, res) => {
  res.json(users);
});

// Send a message
app.post("/messages", (req, res) => {
  const { from, to, text } = req.body as {
    from?: string;
    to?: string;
    text?: string;
  };

  if (!from || !to || !text?.trim()) {
    return res.status(400).json({ error: "from, to, text are required" });
  }

  const sender = users.find((u) => u.id === from);
  const recipient = users.find((u) => u.id === to);

  if (!sender || !recipient) {
    return res.status(404).json({ error: "user not found" });
  }

  const message: Message = {
    id: uuid(),
    from,
    to,
    text: text.trim(),
    createdAt: Date.now()
  };

  messages.push(message);

  const recipientSocketId = connectedUsers.get(to);
  if (recipientSocketId) {
    io.to(recipientSocketId).emit("new_message", {
      message,
      fromUsername: sender.username
    });
  }

  res.json(message);
});

// Get conversation between 2 users
app.get("/messages", (req, res) => {
  const from = req.query.from as string;
  const to = req.query.to as string;

  if (!from || !to) {
    return res.status(400).json({ error: "from and to query params are required" });
  }

  const convo = messages.filter(
    (m) =>
      (m.from === from && m.to === to) ||
      (m.from === to && m.to === from)
  );

  res.json(convo);
});

// Simulated premium purchase
app.post("/purchase/premium", (req, res) => {
  const { userId } = req.body as { userId?: string };

  if (!userId) {
    return res.status(400).json({ error: "userId is required" });
  }

  const user = users.find((u) => u.id === userId);
  if (!user) {
    return res.status(404).json({ error: "user not found" });
  }

  user.premium = true;

  const socketId = connectedUsers.get(userId);
  if (socketId) {
    io.to(socketId).emit("premium_activated", {
      premium: true
    });
  }

  res.json({
    success: true,
    premium: true,
    message: "Premium activated"
  });
});

io.on("connection", (socket) => {
  socket.on("identify", (userId: string) => {
    connectedUsers.set(userId, socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of connectedUsers.entries()) {
      if (socketId === socket.id) {
        connectedUsers.delete(userId);
        break;
      }
    }
  });
});

const PORT = 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

