## `client/app.js`

```js
const API_URL = "http://localhost:4000";
const socket = io(API_URL);

let currentUser = null;
let users = [];

const usernameInput = document.getElementById("usernameInput");
const loginBtn = document.getElementById("loginBtn");
const currentUserEl = document.getElementById("currentUser");
const refreshUsersBtn = document.getElementById("refreshUsersBtn");
const usersList = document.getElementById("usersList");
const recipientSelect = document.getElementById("recipientSelect");
const messagesEl = document.getElementById("messages");
const messageInput = document.getElementById("messageInput");
const sendBtn = document.getElementById("sendBtn");
const buyPremiumBtn = document.getElementById("buyPremiumBtn");
const premiumStatus = document.getElementById("premiumStatus");
const notifications = document.getElementById("notifications");

function notify(text) {
  const div = document.createElement("div");
  div.className = "notification";
  div.textContent = text;
  notifications.prepend(div);
}

async function login() {
  const username = usernameInput.value.trim();
  if (!username) return alert("Enter a username");

  const res = await fetch(`${API_URL}/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username })
  });

  currentUser = await res.json();
  currentUserEl.textContent = `Logged in as ${currentUser.username} (${currentUser.id})`;
  premiumStatus.textContent = `Premium: ${currentUser.premium}`;
  socket.emit("identify", currentUser.id);

  await loadUsers();
}

async function loadUsers() {
  const res = await fetch(`${API_URL}/users`);
  users = await res.json();

  usersList.innerHTML = "";
  recipientSelect.innerHTML = "";

  users
    .filter((u) => !currentUser || u.id !== currentUser.id)
    .forEach((user) => {
      const li = document.createElement("li");
      li.textContent = `${user.username} | premium: ${user.premium}`;
      usersList.appendChild(li);

      const option = document.createElement("option");
      option.value = user.id;
      option.textContent = user.username;
      recipientSelect.appendChild(option);
    });
}

async function sendMessage() {
  if (!currentUser) return alert("Login first");

  const to = recipientSelect.value;
  const text = messageInput.value.trim();

  if (!to || !text) return alert("Choose recipient and message");

  await fetch(`${API_URL}/messages`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      from: currentUser.id,
      to,
      text
    })
  });

  messageInput.value = "";
  await loadConversation();
}

async function loadConversation() {
  if (!currentUser) return;
  const to = recipientSelect.value;
  if (!to) return;

  const res = await fetch(`${API_URL}/messages?from=${currentUser.id}&to=${to}`);
  const msgs = await res.json();

  messagesEl.innerHTML = "";

  msgs.forEach((msg) => {
    const div = document.createElement("div");
    div.className = msg.from === currentUser.id ? "message mine" : "message theirs";
    div.textContent = msg.text;
    messagesEl.appendChild(div);
  });
}

async function buyPremium() {
  if (!currentUser) return alert("Login first");

  const res = await fetch(`${API_URL}/purchase/premium`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ userId: currentUser.id })
  });

  const data = await res.json();
  if (data.success) {
    currentUser.premium = true;
    premiumStatus.textContent = "Premium: true";
    notify("Premium activated successfully");
    await loadUsers();
  }
}

socket.on("new_message", async (payload) => {
  notify(`New message from ${payload.fromUsername}: ${payload.message.text}`);
  await loadConversation();
});

socket.on("premium_activated", () => {
  premiumStatus.textContent = "Premium: true";
  notify("Realtime update: your premium is active");
});

loginBtn.addEventListener("click", login);
refreshUsersBtn.addEventListener("click", loadUsers);
sendBtn.addEventListener("click", sendMessage);
buyPremiumBtn.addEventListener("click", buyPremium);
recipientSelect.addEventListener("change", loadConversation);
```

