## `server/src/index.ts`

```ts
import express from "express";
import http from "http";
import cors from "cors";
import dotenv from "dotenv";
import { Server } from "socket.io";
import Stripe from "stripe";

dotenv.config();

const app = express();
const server = http.createServer(app);

const PORT = Number(process.env.PORT || 4000);
const CLIENT_URL = process.env.CLIENT_URL || "http://localhost:5173";
const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY || "";

const stripe = new Stripe(STRIPE_SECRET_KEY);

app.use(cors({ origin: CLIENT_URL }));
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

type User = {
  username: string;
  socketId: string;
  premium: boolean;
};

type Message = {
  id: string;
  from: string;
  to: string;
  content: string;
  createdAt: string;
};

const users = new Map<string, User>();
const messages: Message[] = [];

function broadcastUsers() {
  io.emit(
    "users:list",
    Array.from(users.values()).map((u) => ({
      username: u.username,
      premium: u.premium
    }))
  );
}

io.on("connection", (socket) => {
  socket.on("user:join", (username: string) => {
    if (!username || typeof username !== "string") return;

    users.set(username, {
      username,
      socketId: socket.id,
      premium: false
    });

    socket.data.username = username;

    socket.emit("message:history", messages.filter(
      (m) => m.from === username || m.to === username
    ));

    broadcastUsers();

    socket.emit("notification", {
      type: "system",
      message: `Welcome, ${username}!`
    });
  });

  socket.on("message:send", ({ to, content }: { to: string; content: string }) => {
    const from = socket.data.username as string | undefined;
    if (!from || !to || !content) return;

    const msg: Message = {
      id: crypto.randomUUID(),
      from,
      to,
      content,
      createdAt: new Date().toISOString()
    };

    messages.push(msg);

    socket.emit("message:new", msg);

    const recipient = users.get(to);
    if (recipient) {
      io.to(recipient.socketId).emit("message:new", msg);
      io.to(recipient.socketId).emit("notification", {
        type: "message",
        message: `New message from ${from}`
      });
    }
  });

  socket.on("disconnect", () => {
    const username = socket.data.username as string | undefined;
    if (username) {
      users.delete(username);
      broadcastUsers();
    }
  });
});

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.post("/create-checkout-session", async (req, res) => {
  try {
    const { username } = req.body as { username?: string };

    if (!username || !users.has(username)) {
      return res.status(400).json({ error: "Invalid username" });
    }

    if (!STRIPE_SECRET_KEY) {
      return res.status(400).json({
        error: "Stripe not configured. Add STRIPE_SECRET_KEY in server/.env"
      });
    }

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Upgrade"
            },
            unit_amount: 499
          },
          quantity: 1
        }
      ],
      success_url: `${CLIENT_URL}?premium=success&username=${encodeURIComponent(username)}`,
      cancel_url: `${CLIENT_URL}?premium=cancel`
    });

    res.json({ url: session.url });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: "Failed to create checkout session" });
  }
});

app.post("/premium/confirm", (req, res) => {
  const { username } = req.body as { username?: string };
  if (!username) return res.status(400).json({ error: "Missing username" });

  const user = users.get(username);
  if (!user) return res.status(404).json({ error: "User not found" });

  user.premium = true;
  users.set(username, user);

  io.to(user.socketId).emit("notification", {
    type: "premium",
    message: "Premium unlocked!"
  });

  broadcastUsers();

  res.json({ success: true });
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

