```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type User = {
  username: string;
  premium: boolean;
};

type Message = {
  id: string;
  from: string;
  to: string;
  content: string;
  createdAt: string;
};

type Notification = {
  type: string;
  message: string;
};

const API_URL = "http://localhost:4000";

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [username, setUsername] = useState("");
  const [joined, setJoined] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [selectedUser, setSelectedUser] = useState("");
  const [messageText, setMessageText] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    const s = io(API_URL);
    setSocket(s);

    s.on("users:list", (list: User[]) => setUsers(list));
    s.on("message:history", (history: Message[]) => setMessages(history));
    s.on("message:new", (msg: Message) => {
      setMessages((prev) => [...prev, msg]);
    });
    s.on("notification", (notification: Notification) => {
      setNotifications((prev) => [notification, ...prev].slice(0, 10));
    });

    return () => {
      s.disconnect();
    };
  }, []);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const premium = params.get("premium");
    const premiumUser = params.get("username");

    if (premium === "success" && premiumUser) {
      fetch(`${API_URL}/premium/confirm`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ username: premiumUser })
      }).catch(console.error);
    }
  }, []);

  const visibleMessages = useMemo(() => {
    if (!selectedUser) return [];
    return messages.filter(
      (m) =>
        (m.from === username && m.to === selectedUser) ||
        (m.from === selectedUser && m.to === username)
    );
  }, [messages, selectedUser, username]);

  function join() {
    if (!socket || !username.trim()) return;
    socket.emit("user:join", username.trim());
    setJoined(true);
  }

  function sendMessage() {
    if (!socket || !selectedUser || !messageText.trim()) return;
    socket.emit("message:send", {
      to: selectedUser,
      content: messageText.trim()
    });
    setMessageText("");
  }

  async function unlockPremium() {
    const res = await fetch(`${API_URL}/create-checkout-session`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ username })
    });

    const data = await res.json();
    if (data.url) {
      window.location.href = data.url;
    } else {
      alert(data.error || "Failed to start checkout");
    }
  }

  if (!joined) {
    return (
      <div style={{ padding: 24, fontFamily: "Arial" }}>
        <h1>Social Messaging App</h1>
        <input
          placeholder="Enter username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          style={{ padding: 8, marginRight: 8 }}
        />
        <button onClick={join}>Join</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "Arial" }}>
      <aside style={{ width: 250, borderRight: "1px solid #ddd", padding: 16 }}>
        <h3>{username}</h3>
        <button onClick={unlockPremium} style={{ marginBottom: 16 }}>
          Unlock Premium
        </button>

        <h4>Users</h4>
        {users
          .filter((u) => u.username !== username)
          .map((u) => (
            <div key={u.username} style={{ marginBottom: 8 }}>
              <button
                onClick={() => setSelectedUser(u.username)}
                style={{
                  width: "100%",
                  padding: 8,
                  background: selectedUser === u.username ? "#def" : "#f5f5f5",
                  border: "1px solid #ccc",
                  cursor: "pointer"
                }}
              >
                {u.username} {u.premium ? "⭐" : ""}
              </button>
            </div>
          ))}

        <h4>Notifications</h4>
        <div>
          {notifications.map((n, idx) => (
            <div
              key={idx}
              style={{
                background: "#fafafa",
                border: "1px solid #eee",
                padding: 8,
                marginBottom: 8
              }}
            >
              <strong>{n.type}</strong>: {n.message}
            </div>
          ))}
        </div>
      </aside>

      <main style={{ flex: 1, padding: 16, display: "flex", flexDirection: "column" }}>
        <h2>Chat {selectedUser ? `with ${selectedUser}` : ""}</h2>

        <div
          style={{
            flex: 1,
            border: "1px solid #ddd",
            padding: 16,
            marginBottom: 16,
            overflowY: "auto"
          }}
        >
          {!selectedUser && <p>Select a user to start chatting.</p>}
          {visibleMessages.map((m) => (
            <div key={m.id} style={{ marginBottom: 12 }}>
              <strong>{m.from}</strong>: {m.content}
              <div style={{ fontSize: 12, color: "#666" }}>{m.createdAt}</div>
            </div>
          ))}
        </div>

        <div style={{ display: "flex", gap: 8 }}>
          <input
            value={messageText}
            onChange={(e) => setMessageText(e.target.value)}
            placeholder="Type a message"
            style={{ flex: 1, padding: 8 }}
            disabled={!selectedUser}
          />
          <button onClick={sendMessage} disabled={!selectedUser}>
            Send
          </button>
        </div>
      </main>
    </div>
  );
}
```

