# 2) `server.ts`

```ts
import express from "express";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static("public"));

type User = {
  username: string;
  premium: boolean;
};

type Message = {
  from: string;
  to: string;
  text: string;
  timestamp: number;
};

const users = new Map<string, User>();
const onlineUsers = new Map<string, string>(); // username -> socketId
const messages: Message[] = [];

/**
 * Health check
 */
app.get("/api/health", (_req, res) => {
  res.json({ ok: true });
});

/**
 * Register/login a simple user by username
 */
app.post("/api/login", (req, res) => {
  const { username } = req.body;

  if (!username || typeof username !== "string") {
    return res.status(400).json({ error: "username required" });
  }

  if (!users.has(username)) {
    users.set(username, { username, premium: false });
  }

  return res.json({
    user: users.get(username)
  });
});

/**
 * Get all users
 */
app.get("/api/users", (_req, res) => {
  res.json({
    users: Array.from(users.values()).map((u) => ({
      ...u,
      online: onlineUsers.has(u.username)
    }))
  });
});

/**
 * Get messages between two users
 */
app.get("/api/messages", (req, res) => {
  const from = String(req.query.from || "");
  const to = String(req.query.to || "");

  const thread = messages.filter(
    (m) =>
      (m.from === from && m.to === to) ||
      (m.from === to && m.to === from)
  );

  res.json({ messages: thread });
});

/**
 * Fake premium purchase endpoint
 * In production this would validate app store receipts / payment provider webhooks
 */
app.post("/api/purchase/premium", (req, res) => {
  const { username } = req.body;

  const user = users.get(username);
  if (!user) {
    return res.status(404).json({ error: "user not found" });
  }

  user.premium = true;
  users.set(username, user);

  const socketId = onlineUsers.get(username);
  if (socketId) {
    io.to(socketId).emit("premium:activated", {
      message: "Premium activated!"
    });
  }

  return res.json({
    success: true,
    user
  });
});

io.on("connection", (socket) => {
  console.log("socket connected", socket.id);

  socket.on("user:online", ({ username }) => {
    if (!username) return;
    onlineUsers.set(username, socket.id);
    socket.data.username = username;

    io.emit("presence:update", {
      usernames: Array.from(onlineUsers.keys())
    });
  });

  socket.on("message:send", ({ from, to, text }) => {
    if (!from || !to || !text) return;

    const sender = users.get(from);
    const recipient = users.get(to);

    if (!sender || !recipient) return;

    // Example monetization rule:
    // Non-premium users can send only messages <= 120 chars
    if (!sender.premium && text.length > 120) {
      io.to(socket.id).emit("message:error", {
        error: "Upgrade to Premium to send longer messages."
      });
      return;
    }

    const message: Message = {
      from,
      to,
      text,
      timestamp: Date.now()
    };

    messages.push(message);

    // Send to sender
    io.to(socket.id).emit("message:received", message);

    // Send to recipient if online
    const recipientSocketId = onlineUsers.get(to);
    if (recipientSocketId) {
      io.to(recipientSocketId).emit("message:received", message);
      io.to(recipientSocketId).emit("notification", {
        type: "new_message",
        title: `New message from ${from}`,
        body: text
      });
    }
  });

  socket.on("disconnect", () => {
    const username = socket.data.username;
    if (username) {
      onlineUsers.delete(username);
      io.emit("presence:update", {
        usernames: Array.from(onlineUsers.keys())
      });
    }
    console.log("socket disconnected", socket.id);
  });
});

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
