        <div id="me"></div>
        <button onclick="buyPremium()">Upgrade to Premium</button>
      </div>

      <div class="panel">
        <h3>Users</h3>
        <select id="recipient"></select>
        <button onclick="loadUsers()">Refresh Users</button>
        <div id="usersList"></div>
      </div>
    </div>

    <div class="panel">
      <h3>Messages</h3>
      <div id="messages"></div>
      <textarea id="messageText" placeholder="Write a message..."></textarea>
      <button onclick="sendMessage()">Send Message</button>
    </div>

    <div class="panel">
      <h3>Notifications</h3>
      <div id="notifications"></div>
    </div>

    <script src="/socket.io/socket.io.js"></script>
    <script>
      const socket = io();

      let currentUser = null;
      let currentThreadUser = null;

      function renderMe() {
        const me = document.getElementById("me");
        if (!currentUser) {
          me.innerHTML = "";
          return;
        }

        me.innerHTML = `
          Logged in as <strong>${currentUser.username}</strong>
          ${currentUser.premium ? '<span class="premium">(Premium)</span>' : ""}
        `;
      }

      function addNotification(text) {
        const el = document.getElementById("notifications");
        const div = document.createElement("div");
        div.className = "note";
        div.textContent = text;
        el.prepend(div);
      }

      async function login() {
        const username = document.getElementById("username").value.trim();
        if (!username) return alert("Enter username");

        const res = await fetch("/api/login", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ username })
        });

        const data = await res.json();
        currentUser = data.user;
        renderMe();
        socket.emit("user:online", { username: currentUser.username });
        await loadUsers();
      }

      async function loadUsers() {
        const res = await fetch("/api/users");
        const data = await res.json();

        const usersList = document.getElementById("usersList");
        const recipient = document.getElementById("recipient");

        usersList.innerHTML = "";
        recipient.innerHTML = "";

        data.users
          .filter(u => !currentUser || u.username !== currentUser.username)
          .forEach(u => {
            const div = document.createElement("div");
            div.textContent = `${u.username} ${u.online ? "🟢" : "⚪"} ${u.premium ? "(Premium)" : ""}`;
            usersList.appendChild(div);

            const option = document.createElement("option");
            option.value = u.username;
            option.textContent = u.username;
            recipient.appendChild(option);
          });

        if (recipient.value) {
          currentThreadUser = recipient.value;
          await loadMessages();
        }
      }

      async function loadMessages() {
        if (!currentUser) return;
        const recipient = document.getElementById("recipient").value;
        currentThreadUser = recipient;
        if (!recipient) return;

        const res = await fetch(
          `/api/messages?from=${encodeURIComponent(currentUser.username)}&to=${encodeURIComponent(recipient)}`
        );
        const data = await res.json();

        const messages = document.getElementById("messages");
        messages.innerHTML = "";

        data.messages.forEach(m => {
          appendMessage(m);
        });
      }

      function appendMessage(m) {
        const messages = document.getElementById("messages");
        const div = document.createElement("div");
        div.className = "msg";
        div.textContent = `[${new Date(m.timestamp).toLocaleTimeString()}] ${m.from} -> ${m.to}: ${m.text}`;
        messages.appendChild(div);
        messages.scrollTop = messages.scrollHeight;
      }

      function sendMessage() {
        if (!currentUser) return alert("Login first");
        const to = document.getElementById("recipient").value;
        const text = document.getElementById("messageText").value.trim();

        if (!to) return alert("Choose a recipient");
        if (!text) return alert("Enter a message");

        socket.emit("message:send", {
          from: currentUser.username,
          to,
          text
        });

        document.getElementById("messageText").value = "";
      }

      async function buyPremium() {
        if (!currentUser) return alert("Login first");

        const res = await fetch("/api/purchase/premium", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ username: currentUser.username })
        });

        const data = await res.json();
        currentUser = data.user;
        renderMe();
        addNotification("Premium purchase successful.");
        await loadUsers();
      }

      socket.on("message:received", (message) => {
        if (!currentUser) return;

        const activeRecipient = document.getElementById("recipient").value;
        const relevant =
          (message.from === currentUser.username && message.to === activeRecipient) ||
          (message.from === activeRecipient && message.to === currentUser.username);

        if (relevant) {
          appendMessage(message);
        }
      });

      socket.on("notification", (n) => {
        addNotification(`${n.title}: ${n.body}`);
      });

      socket.on("message:error", (err) => {
        addNotification(`Error: ${err.error}`);
      });

      socket.on("premium:activated", (msg) => {
        addNotification(msg.message);
      });

      socket.on("presence:update", () => {
        loadUsers();
      });

      document.getElementById("recipient").addEventListener("change", loadMessages);
    </script>
  </body>
</html>
