        <h2 style="margin-top:0;">Control Form</h2>
        <form id="controlForm" novalidate>
          <div class="field">
            <label for="labelInput">Annotation Label</label>
            <input id="labelInput" name="label" type="text" placeholder="e.g. Traffic surge" />
            <div class="error" id="labelError"></div>
          </div>

          <div class="field">
            <label for="thresholdInput">Alert Threshold</label>
            <input id="thresholdInput" name="threshold" type="number" min="0" max="200" value="80" />
            <div class="error" id="thresholdError"></div>
          </div>

          <div class="field">
            <label for="categoryInput">Category</label>
            <select id="categoryInput" name="category">
              <option value="info">Info</option>
              <option value="good">Good</option>
              <option value="warn">Warning</option>
            </select>
          </div>

          <div class="field">
            <label for="notesInput">Notes</label>
            <textarea id="notesInput" name="notes" rows="4" placeholder="Optional notes"></textarea>
          </div>

          <div class="row">
            <button type="submit" class="primary">Add Annotation</button>
          </div>
        </form>

        <h3 style="margin-bottom:10px;">Event Log</h3>
        <div id="log" class="log"></div>
      </div>
