  <script>
    const chartCanvas = document.getElementById('chart');
    const ctx = chartCanvas.getContext('2d');

    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const countValueEl = document.getElementById('countValue');
    const statusTextEl = document.getElementById('statusText');

    const pauseBtn = document.getElementById('pauseBtn');
    const resumeBtn = document.getElementById('resumeBtn');
    const resetBtn = document.getElementById('resetBtn');
    const addSpikeBtn = document.getElementById('addSpikeBtn');

    const controlForm = document.getElementById('controlForm');
    const labelInput = document.getElementById('labelInput');
    const thresholdInput = document.getElementById('thresholdInput');
    const categoryInput = document.getElementById('categoryInput');
    const notesInput = document.getElementById('notesInput');

    const labelError = document.getElementById('labelError');
    const thresholdError = document.getElementById('thresholdError');
    const logEl = document.getElementById('log');

    let data = [];
    let annotations = [];
    let running = true;
    let alertThreshold = 80;
    const maxPoints = 40;

    function addLog(message, category = 'info') {
      const item = document.createElement('div');
      item.className = 'log-item';
      const time = new Date().toLocaleTimeString();
      item.innerHTML = `<span class="badge ${category}">${category.toUpperCase()}</span>${message}<div class="subtle" style="margin-top:6px;">${time}</div>`;
      logEl.prepend(item);

      while (logEl.children.length > 12) {
        logEl.removeChild(logEl.lastChild);
      }
    }

    function randomValue(base = 50, variance = 20) {
      return Math.max(0, Math.round(base + (Math.random() - 0.5) * variance * 2));
    }

    function pushData(value = randomValue()) {
      const point = {
        time: new Date(),
        value
      };
      data.push(point);
      if (data.length > maxPoints) data.shift();

      if (value >= alertThreshold) {
        addLog(`Threshold exceeded with value ${value}`, 'warn');
      }
    }

    function computeStats() {
      if (!data.length) {
        return { current: 0, avg: 0, peak: 0, count: 0 };
      }
      const values = data.map(d => d.value);
      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);
      return {
        current,
        avg: avg.toFixed(1),
        peak,
        count: values.length
      };
    }

    function updateKPIs() {
      const stats = computeStats();
      currentValueEl.textContent = stats.current;
      avgValueEl.textContent = stats.avg;
      peakValueEl.textContent = stats.peak;
      countValueEl.textContent = stats.count;
    }

    function drawChart() {
      const { width, height } = chartCanvas;
      ctx.clearRect(0, 0, width, height);

      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, width, height);

      // grid
      ctx.strokeStyle = 'rgba(148,163,184,0.15)';
      ctx.lineWidth = 1;
      const rows = 5;
      const cols = 8;

      for (let i = 0; i <= rows; i++) {
        const y = (height / rows) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      for (let i = 0; i <= cols; i++) {
        const x = (width / cols) * i;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }

      // threshold line
      const maxY = 120;
      const thresholdY = height - (alertThreshold / maxY) * height;
      ctx.strokeStyle = 'rgba(245,158,11,0.9)';
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(0, thresholdY);
      ctx.lineTo(width, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = '#fcd34d';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Threshold ${alertThreshold}`, 8, Math.max(14, thresholdY - 6));

      if (data.length < 2) return;

      const stepX = width / (maxPoints - 1);

      // area
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = index * stepX;
        const y = height - (point.value / maxY) * height;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo((data.length - 1) * stepX, height);
      ctx.lineTo(0, height);
      ctx.closePath();
      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, 'rgba(56,189,248,0.35)');
      gradient.addColorStop(1, 'rgba(56,189,248,0.02)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // line
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = index * stepX;
        const y = height - (point.value / maxY) * height;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.stroke();

      // points
      data.forEach((point, index) => {
        const x = index * stepX;
        const y = height - (point.value / maxY) * height;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = point.value >= alertThreshold ? '#f59e0b' : '#22c55e';
        ctx.fill();
      });

      // annotations
      annotations.forEach(annotation => {
        if (annotation.index < 0 || annotation.index >= data.length) return;
        const x = annotation.index * stepX;
        const y = height - (data[annotation.index].value / maxY) * height;

        ctx.beginPath();
        ctx.moveTo(x, y - 18);
        ctx.lineTo(x, y);
        ctx.strokeStyle = '#e5e7eb';
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.fillStyle = '#e5e7eb';
        ctx.font = '12px sans-serif';
        ctx.fillText(annotation.label, Math.min(x + 6, width - 120), Math.max(14, y - 22));
      });
    }

    function render() {
      updateKPIs();
      drawChart();
    }

    function tick() {
      if (running) {
        pushData();
        render();
      }
    }

    function validateForm() {
      let valid = true;
      labelError.textContent = '';
      thresholdError.textContent = '';

      if (!labelInput.value.trim()) {
        labelError.textContent = 'Please enter an annotation label.';
        valid = false;
      }

      const threshold = Number(thresholdInput.value);
      if (Number.isNaN(threshold) || threshold < 0 || threshold > 200) {
        thresholdError.textContent = 'Threshold must be a number between 0 and 200.';
        valid = false;
      }

      return valid;
    }

    controlForm.addEventListener('submit', (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      alertThreshold = Number(thresholdInput.value);

      const label = labelInput.value.trim();
      const category = categoryInput.value;
      const notes = notesInput.value.trim();

      annotations.push({
        label,
        index: Math.max(0, data.length - 1)
      });

      addLog(
        `Annotation added: "${label}"${notes ? ` — ${notes}` : ''}`,
        category
      );

      labelInput.value = '';
      notesInput.value = '';
      render();
    });

    pauseBtn.addEventListener('click', () => {
      running = false;
      statusTextEl.textContent = 'Paused';
      addLog('Live updates paused', 'info');
    });

    resumeBtn.addEventListener('click', () => {
      running = true;
      statusTextEl.textContent = 'Running';
      addLog('Live updates resumed', 'good');
    });

    resetBtn.addEventListener('click', () => {
      data = [];
      annotations = [];
      render();
      addLog('Dashboard data reset', 'warn');
    });

    addSpikeBtn.addEventListener('click', () => {
      const spike = randomValue(100, 15);
      pushData(spike);
      render();
      addLog(`Manual spike injected: ${spike}`, 'warn');
    });

    // Initial seed data
    for (let i = 0; i < 16; i++) {
      pushData(randomValue());
    }
    render();
    addLog('Dashboard initialised', 'good');

    setInterval(tick, 1000);
  </script>
</body>
</html>
