## 3) `server.ts`

```ts
import express from "express";
import path from "path";
import { fileURLToPath } from "url";

const app = express();
const port = 3000;

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

type DataPoint = {
  time: string;
  value: number;
};

type MetricRecord = {
  id: number;
  name: string;
  value: number;
  createdAt: string;
};

let nextId = 1;
let metrics: MetricRecord[] = [];
let liveSeries: DataPoint[] = [];

const sseClients: express.Response[] = [];

function broadcast(event: string, data: unknown) {
  const payload = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  for (const client of sseClients) {
    client.write(payload);
  }
}

function makeRandomPoint(): DataPoint {
  const now = new Date();
  const point = {
    time: now.toLocaleTimeString(),
    value: Math.floor(30 + Math.random() * 70)
  };
  return point;
}

// Seed initial chart data
for (let i = 0; i < 12; i++) {
  liveSeries.push(makeRandomPoint());
}

setInterval(() => {
  const point = makeRandomPoint();
  liveSeries.push(point);
  if (liveSeries.length > 20) {
    liveSeries.shift();
  }
  broadcast("chart-update", point);
}, 2000);

// REST API
app.get("/api/metrics", (_req, res) => {
  res.json(metrics);
});

app.post("/api/metrics", (req, res) => {
  const { name, value } = req.body as { name?: string; value?: number };

  if (!name || typeof name !== "string" || typeof value !== "number" || Number.isNaN(value)) {
    return res.status(400).json({ error: "Invalid payload. Expected { name: string, value: number }" });
  }

  const record: MetricRecord = {
    id: nextId++,
    name: name.trim(),
    value,
    createdAt: new Date().toISOString()
  };

  metrics.unshift(record);
  broadcast("metric-created", record);

  res.status(201).json(record);
});

app.get("/api/chart", (_req, res) => {
  res.json(liveSeries);
});

// SSE endpoint
app.get("/api/events", (req, res) => {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders?.();

  sseClients.push(res);

  res.write(`event: init\ndata: ${JSON.stringify({ ok: true })}\n\n`);

  req.on("close", () => {
    const index = sseClients.indexOf(res);
    if (index >= 0) sseClients.splice(index, 1);
  });
});

app.get("/", (_req, res) => {
  res.sendFile(path.join(__dirname, "public", "index.html"));
});

app.listen(port, () => {
  console.log(`Dashboard running at http://localhost:${port}`);
});
```

