## 6) `public/app.ts`

```ts
type DataPoint = {
  time: string;
  value: number;
};

type MetricRecord = {
  id: number;
  name: string;
  value: number;
  createdAt: string;
};

const chartCanvas = document.getElementById("chart") as HTMLCanvasElement;
const ctx = chartCanvas.getContext("2d")!;
const statusEl = document.getElementById("status") as HTMLSpanElement;
const form = document.getElementById("metric-form") as HTMLFormElement;
const messageEl = document.getElementById("form-message") as HTMLParagraphElement;
const tbody = document.getElementById("metrics-body") as HTMLTableSectionElement;

let chartData: DataPoint[] = [];

function drawChart(data: DataPoint[]) {
  const width = chartCanvas.width;
  const height = chartCanvas.height;
  const padding = 40;

  ctx.clearRect(0, 0, width, height);

  // Background grid
  ctx.strokeStyle = "#334155";
  ctx.lineWidth = 1;

  for (let i = 0; i < 5; i++) {
    const y = padding + ((height - padding * 2) / 4) * i;
    ctx.beginPath();
    ctx.moveTo(padding, y);
    ctx.lineTo(width - padding, y);
    ctx.stroke();
  }

  if (data.length === 0) return;

  const values = data.map(d => d.value);
  const min = Math.min(...values, 0);
  const max = Math.max(...values, 100);
  const xStep = (width - padding * 2) / Math.max(data.length - 1, 1);

  const toY = (value: number) => {
    const ratio = (value - min) / Math.max(max - min, 1);
    return height - padding - ratio * (height - padding * 2);
  };

  // Area fill
  ctx.beginPath();
  data.forEach((point, index) => {
    const x = padding + index * xStep;
    const y = toY(point.value);
    if (index === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.lineTo(padding + (data.length - 1) * xStep, height - padding);
  ctx.lineTo(padding, height - padding);
  ctx.closePath();

  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, "rgba(56, 189, 248, 0.4)");
  gradient.addColorStop(1, "rgba(56, 189, 248, 0.02)");
  ctx.fillStyle = gradient;
  ctx.fill();

  // Line
  ctx.beginPath();
  data.forEach((point, index) => {
    const x = padding + index * xStep;
    const y = toY(point.value);
    if (index === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });

  ctx.strokeStyle = "#38bdf8";
  ctx.lineWidth = 3;
  ctx.stroke();

  // Points
  ctx.fillStyle = "#22c55e";
  data.forEach((point, index) => {
    const x = padding + index * xStep;
    const y = toY(point.value);
    ctx.beginPath();
    ctx.arc(x, y, 4, 0, Math.PI * 2);
    ctx.fill();
  });

  // Labels
  ctx.fillStyle = "#94a3b8";
  ctx.font = "12px Arial";
  ctx.fillText(String(max), 8, padding + 4);
  ctx.fillText(String(min), 8, height - padding);

  const last = data[data.length - 1];
  ctx.fillStyle = "#e5e7eb";
  ctx.fillText(`Latest: ${last.value}`, width - 120, 20);
}

function renderMetrics(metrics: MetricRecord[]) {
  tbody.innerHTML = metrics
    .map(
      metric => `
      <tr>
        <td>${metric.id}</td>
        <td>${escapeHtml(metric.name)}</td>
        <td>${metric.value}</td>
        <td>${new Date(metric.createdAt).toLocaleString()}</td>
      </tr>
    `
    )
    .join("");
}

function prependMetric(metric: MetricRecord) {
  const row = document.createElement("tr");
  row.innerHTML = `
    <td>${metric.id}</td>
    <td>${escapeHtml(metric.name)}</td>
    <td>${metric.value}</td>
    <td>${new Date(metric.createdAt).toLocaleString()}</td>
  `;
  tbody.prepend(row);
}

function escapeHtml(value: string) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

async function loadInitialData() {
  const [chartRes, metricsRes] = await Promise.all([
    fetch("/api/chart"),
    fetch("/api/metrics")
  ]);

  chartData = await chartRes.json();
  const metrics: MetricRecord[] = await metricsRes.json();

  drawChart(chartData);
  renderMetrics(metrics);
}

form.addEventListener("submit", async event => {
  event.preventDefault();
  messageEl.textContent = "Submitting...";

  const formData = new FormData(form);
  const name = String(formData.get("name") || "").trim();
  const value = Number(formData.get("value"));

  if (!name || Number.isNaN(value)) {
    messageEl.textContent = "Please enter a valid name and numeric value.";
    messageEl.style.color = "#ef4444";
    return;
  }

  try {
    const res = await fetch("/api/metrics", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ name, value })
    });

    if (!res.ok) {
      throw new Error("Failed to submit metric");
    }

    form.reset();
    messageEl.textContent = "Metric submitted successfully.";
    messageEl.style.color = "#22c55e";
  } catch {
    messageEl.textContent = "Submission failed.";
    messageEl.style.color = "#ef4444";
  }
});

function connectEvents() {
  const events = new EventSource("/api/events");

  events.addEventListener("open", () => {
    statusEl.textContent = "Live";
    statusEl.style.color = "#22c55e";
  });

  events.addEventListener("error", () => {
    statusEl.textContent = "Reconnecting…";
    statusEl.style.color = "#ef4444";
  });

  events.addEventListener("chart-update", event => {
    const point = JSON.parse((event as MessageEvent).data) as DataPoint;
    chartData.push(point);
    if (chartData.length > 20) chartData.shift();
    drawChart(chartData);
  });

  events.addEventListener("metric-created", event => {
    const metric = JSON.parse((event as MessageEvent).data) as MetricRecord;
    prependMetric(metric);
  });
}

loadInitialData()
  .then(connectEvents)
  .catch(() => {
    statusEl.textContent = "Failed to load";
    statusEl.style.color = "#ef4444";
  });
```

