        <div class="metric-value" id="peakValue">0</div>
        <div class="metric-trend">Highest observed value</div>
      </div>

      <div class="card span-3">
        <div class="metric-label">Status</div>
        <div class="metric-value" id="statusText">Idle</div>
        <div class="metric-trend">
          <span class="pill" id="statusPill">disconnected</span>
        </div>
      </div>

      <div class="card span-8">
        <div class="section-title">Real-Time Visualisation</div>
        <canvas id="chart" width="900" height="320"></canvas>
        <div class="footer-note">The chart updates once per second using simulated live data.</div>
      </div>

      <div class="card span-4">
        <div class="section-title">Configuration Form</div>
        <form id="configForm" novalidate>
          <div class="field">
            <label for="sourceName">Source name</label>
            <input id="sourceName" name="sourceName" type="text" placeholder="e.g. Sensor A" />
            <div class="error" id="sourceNameError"></div>
          </div>

          <div class="field">
            <label for="updateRate">Update rate (ms)</label>
            <input id="updateRate" name="updateRate" type="number" min="200" step="100" value="1000" />
            <div class="error" id="updateRateError"></div>
          </div>

          <div class="field">
            <label for="threshold">Alert threshold</label>
            <input id="threshold" name="threshold" type="number" min="1" max="1000" value="75" />
            <div class="error" id="thresholdError"></div>
          </div>

          <div class="field">
            <label for="theme">Theme accent</label>
            <select id="theme" name="theme">
              <option value="#22c55e">Green</option>
              <option value="#38bdf8">Blue</option>
              <option value="#f59e0b">Amber</option>
              <option value="#ef4444">Red</option>
              <option value="#a78bfa">Violet</option>
            </select>
          </div>

          <div class="field">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="4" placeholder="Optional notes..."></textarea>
          </div>

          <button type="submit" class="primary">Save Configuration</button>
          <div class="success" id="formSuccess"></div>
        </form>
      </div>

      <div class="card span-12">
        <div class="section-title">Event Log</div>
        <div id="eventLog" class="log"></div>
      </div>
    </div>
  </div>

  <script>
    const state = {
      data: [],
      maxPoints: 40,
      timer: null,
      updateRate: 1000,
      threshold: 75,
      sourceName: "Sensor A",
      running: false,
      peak: 0
    };

    const els = {
      currentValue: document.getElementById("currentValue"),
      avgValue: document.getElementById("avgValue"),
      peakValue: document.getElementById("peakValue"),
      currentTrend: document.getElementById("currentTrend"),
      statusText: document.getElementById("statusText"),
      statusPill: document.getElementById("statusPill"),
      chart: document.getElementById("chart"),
      eventLog: document.getElementById("eventLog"),
      startBtn: document.getElementById("startBtn"),
      stopBtn: document.getElementById("stopBtn"),
      resetBtn: document.getElementById("resetBtn"),
      configForm: document.getElementById("configForm"),
      sourceName: document.getElementById("sourceName"),
      updateRate: document.getElementById("updateRate"),
      threshold: document.getElementById("threshold"),
      theme: document.getElementById("theme"),
      notes: document.getElementById("notes"),
      formSuccess: document.getElementById("formSuccess"),
      sourceNameError: document.getElementById("sourceNameError"),
      updateRateError: document.getElementById("updateRateError"),
      thresholdError: document.getElementById("thresholdError")
    };

    function nowTime() {
      return new Date().toLocaleTimeString();
    }

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.innerHTML = `<span class="log-time">${nowTime()}</span>${message}`;
      els.eventLog.prepend(item);

      while (els.eventLog.children.length > 50) {
        els.eventLog.removeChild(els.eventLog.lastChild);
      }
    }

    function setStatus(text, pillText) {
      els.statusText.textContent = text;
      els.statusPill.textContent = pillText;
    }

    function generateDataPoint() {
      const last = state.data.length ? state.data[state.data.length - 1].value : 50;
      const drift = (Math.random() - 0.5) * 20;
      let next = Math.max(0, Math.min(100, last + drift));
      next = Math.round(next * 10) / 10;

      const point = {
        time: nowTime(),
        value: next
      };

      state.data.push(point);
      if (state.data.length > state.maxPoints) state.data.shift();

      state.peak = Math.max(state.peak, next);
      updateMetrics();
      drawChart();

      if (next >= state.threshold) {
        addLog(`⚠️ Threshold exceeded by <strong>${state.sourceName}</strong>: value <strong>${next}</strong> ≥ ${state.threshold}`);
      } else {
        addLog(`📈 New reading from <strong>${state.sourceName}</strong>: ${next}`);
      }
    }

    function updateMetrics() {
      if (!state.data.length) return;

      const current = state.data[state.data.length - 1].value;
      const prev = state.data.length > 1 ? state.data[state.data.length - 2].value : current;
      const avg = state.data.reduce((sum, p) => sum + p.value, 0) / state.data.length;

      els.currentValue.textContent = current.toFixed(1);
      els.avgValue.textContent = avg.toFixed(1);
      els.peakValue.textContent = state.peak.toFixed(1);

      const diff = current - prev;
      if (diff > 0) {
        els.currentTrend.textContent = `▲ Rising by ${diff.toFixed(1)}`;
        els.currentTrend.className = "metric-trend up";
      } else if (diff < 0) {
        els.currentTrend.textContent = `▼ Falling by ${Math.abs(diff).toFixed(1)}`;
        els.currentTrend.className = "metric-trend down";
      } else {
        els.currentTrend.textContent = "No change";
        els.currentTrend.className = "metric-trend";
      }
    }

    function drawChart() {
      const canvas = els.chart;
      const ctx = canvas.getContext("2d");
      const w = canvas.width;
      const h = canvas.height;
      const pad = 36;

      ctx.clearRect(0, 0, w, h);

      // grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = pad + ((h - 2 * pad) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(pad, y);
        ctx.lineTo(w - pad, y);
        ctx.stroke();
      }

      // y labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px Arial";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      for (let i = 0; i <= 5; i++) {
        const value = 100 - i * 20;
        const y = pad + ((h - 2 * pad) / 5) * i;
        ctx.fillText(String(value), pad - 8, y);
      }

      // threshold line
      const thresholdY = h - pad - (state.threshold / 100) * (h - 2 * pad);
      ctx.strokeStyle = "rgba(239, 68, 68, 0.8)";
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(pad, thresholdY);
      ctx.lineTo(w - pad, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = "rgba(239, 68, 68, 0.95)";
      ctx.textAlign = "left";
      ctx.fillText(`Threshold ${state.threshold}`, w - pad - 95, thresholdY - 8);

      if (!state.data.length) return;

      const accent = getComputedStyle(document.documentElement).getPropertyValue("--accent").trim() || "#22c55e";
      const stepX = state.data.length > 1 ? (w - 2 * pad) / (state.data.length - 1) : 0;

      // area
      ctx.beginPath();
      state.data.forEach((p, i) => {
        const x = pad + i * stepX;
        const y = h - pad - (p.value / 100) * (h - 2 * pad);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.lineTo(pad + (state.data.length - 1) * stepX, h - pad);
      ctx.lineTo(pad, h - pad);
      ctx.closePath();

      const grad = ctx.createLinearGradient(0, pad, 0, h - pad);
      grad.addColorStop(0, hexToRgba(accent, 0.35));
      grad.addColorStop(1, hexToRgba(accent, 0.02));
      ctx.fillStyle = grad;
      ctx.fill();

      // line
      ctx.beginPath();
      state.data.forEach((p, i) => {
        const x = pad + i * stepX;
        const y = h - pad - (p.value / 100) * (h - 2 * pad);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = accent;
      ctx.lineWidth = 3;
      ctx.stroke();

      // points
      state.data.forEach((p, i) => {
        const x = pad + i * stepX;
        const y = h - pad - (p.value / 100) * (h - 2 * pad);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fillStyle = "#e5e7eb";
        ctx.fill();
      });

      // x labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "11px Arial";
      ctx.textAlign = "center";
      ctx.textBaseline = "top";

      const labelCount = Math.min(6, state.data.length);
      for (let i = 0; i < labelCount; i++) {
        const idx = Math.floor((i * (state.data.length - 1)) / Math.max(1, labelCount - 1));
        const x = pad + idx * stepX;
        ctx.fillText(state.data[idx].time, x, h - pad + 8);
      }
    }

    function hexToRgba(hex, alpha) {
      const cleaned = hex.replace("#", "");
      const bigint = parseInt(cleaned, 16);
      const r = (bigint >> 16) & 255;
      const g = (bigint >> 8) & 255;
      const b = bigint & 255;
      return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }

    function startStream() {
      if (state.running) return;
      state.running = true;
      setStatus("Live", "connected");
      addLog(`✅ Stream started for <strong>${state.sourceName}</strong> at ${state.updateRate}ms intervals`);
      state.timer = setInterval(generateDataPoint, state.updateRate);
      generateDataPoint();
    }

    function stopStream() {
      if (!state.running) return;
      clearInterval(state.timer);
      state.timer = null;
      state.running = false;
      setStatus("Paused", "disconnected");
      addLog(`⏸️ Stream stopped`);
    }

    function resetDashboard() {
      stopStream();
      state.data = [];
      state.peak = 0;
      els.currentValue.textContent = "0";
      els.avgValue.textContent = "0";
      els.peakValue.textContent = "0";
      els.currentTrend.textContent = "Waiting for data…";
      els.currentTrend.className = "metric-trend";
      setStatus("Idle", "disconnected");
      els.eventLog.innerHTML = "";
      drawChart();
      addLog("🧹 Dashboard reset");
    }

    function clearErrors() {
      els.sourceNameError.textContent = "";
      els.updateRateError.textContent = "";
      els.thresholdError.textContent = "";
      els.formSuccess.textContent = "";
    }

    function validateForm() {
      clearErrors();
      let valid = true;

      const sourceName = els.sourceName.value.trim();
      const updateRate = Number(els.updateRate.value);
      const threshold = Number(els.threshold.value);

      if (!sourceName || sourceName.length < 2) {
        els.sourceNameError.textContent = "Please enter a source name of at least 2 characters.";
        valid = false;
      }

      if (!Number.isFinite(updateRate) || updateRate < 200) {
        els.updateRateError.textContent = "Update rate must be at least 200 ms.";
        valid = false;
      }

      if (!Number.isFinite(threshold) || threshold < 1 || threshold > 100) {
        els.thresholdError.textContent = "Threshold must be between 1 and 100.";
        valid = false;
      }

      return valid;
    }

    els.configForm.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      state.sourceName = els.sourceName.value.trim();
      state.updateRate = Number(els.updateRate.value);
      state.threshold = Number(els.threshold.value);

      document.documentElement.style.setProperty("--accent", els.theme.value);

      const wasRunning = state.running;
      if (wasRunning) {
        clearInterval(state.timer);
        state.timer = setInterval(generateDataPoint, state.updateRate);
      }

      els.formSuccess.textContent = "Configuration saved successfully.";
      addLog(`⚙️ Config updated: source=<strong>${state.sourceName}</strong>, rate=${state.updateRate}ms, threshold=${state.threshold}`);

      drawChart();
    });

    els.startBtn.addEventListener("click", startStream);
    els.stopBtn.addEventListener("click", stopStream);
    els.resetBtn.addEventListener("click", resetDashboard);

    // Seed form defaults
    els.sourceName.value = state.sourceName;
    els.updateRate.value = state.updateRate;
    els.threshold.value = state.threshold;

    // Initial render
    drawChart();
    addLog("Dashboard loaded and ready.");
  </script>
</body>
</html>
