  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');
    const currentValueEl = document.getElementById('currentValue');
    const avgValueEl = document.getElementById('avgValue');
    const peakValueEl = document.getElementById('peakValue');
    const currentTrendEl = document.getElementById('currentTrend');
    const eventCountEl = document.getElementById('eventCount');
    const eventLogEl = document.getElementById('eventLog');
    const thresholdInput = document.getElementById('threshold');
    const maxPointsSelect = document.getElementById('maxPoints');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');
    const connectionStatus = document.getElementById('connectionStatus');
    const eventForm = document.getElementById('eventForm');

    let labels = [];
    let values = [];
    let timer = null;
    let paused = false;
    let eventCount = 0;

    const liveChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Metric',
          data: values,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59,130,246,0.2)',
          fill: true,
          tension: 0.3,
          pointRadius: 3,
          pointBackgroundColor: '#93c5fd'
        }]
      },
      options: {
        responsive: true,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148,163,184,0.15)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148,163,184,0.15)' }
          }
        }
      }
    });

    function formatTime(date) {
      return date.toLocaleTimeString();
    }

    function generateValue() {
      const base = 50;
      const variation = Math.random() * 30;
      const spike = Math.random() > 0.9 ? Math.random() * 40 : 0;
      return Math.round(base + variation + spike);
    }

    function getMaxPoints() {
      return parseInt(maxPointsSelect.value, 10);
    }

    function updateMetrics() {
      if (values.length === 0) return;

      const current = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;
      const peak = Math.max(...values);
      const previous = values.length > 1 ? values[values.length - 2] : current;

      currentValueEl.textContent = current;
      avgValueEl.textContent = avg.toFixed(1);
      peakValueEl.textContent = peak;

      if (current > previous) {
        currentTrendEl.textContent = 'Trending up';
      } else if (current < previous) {
        currentTrendEl.textContent = 'Trending down';
      } else {
        currentTrendEl.textContent = 'No change';
      }
    }

    function addSystemLog(message, type = 'info') {
      const item = document.createElement('div');
      item.className = 'log-item';

      item.innerHTML = `
        <div class="time">${formatTime(new Date())}</div>
        <div class="msg">
          ${message}
          <span class="tag ${type}">${type.toUpperCase()}</span>
        </div>
      `;

      eventLogEl.prepend(item);
    }

    function tick() {
      const value = generateValue();
      const time = formatTime(new Date());
      const threshold = parseFloat(thresholdInput.value || '75');

      labels.push(time);
      values.push(value);

      const maxPoints = getMaxPoints();
      while (labels.length > maxPoints) labels.shift();
      while (values.length > maxPoints) values.shift();

      liveChart.update();
      updateMetrics();

      if (value >= threshold) {
        addSystemLog(`Threshold exceeded: value ${value} crossed ${threshold}`, 'warn');
      }
    }

    function startStream() {
      if (timer) clearInterval(timer);
      timer = setInterval(() => {
        if (!paused) tick();
      }, 1000);
    }

    maxPointsSelect.addEventListener('change', () => {
      const maxPoints = getMaxPoints();
      while (labels.length > maxPoints) labels.shift();
      while (values.length > maxPoints) values.shift();
      liveChart.update();
      updateMetrics();
      addSystemLog(`Visible data points set to ${maxPoints}`, 'info');
    });

    thresholdInput.addEventListener('change', () => {
      addSystemLog(`Alert threshold updated to ${thresholdInput.value}`, 'info');
    });

    resetBtn.addEventListener('click', () => {
      labels = [];
      values = [];
      liveChart.data.labels = labels;
      liveChart.data.datasets[0].data = values;
      liveChart.update();

      currentValueEl.textContent = '0';
      avgValueEl.textContent = '0';
      peakValueEl.textContent = '0';
      currentTrendEl.textContent = 'Waiting for data...';

      addSystemLog('Dashboard data reset', 'info');
    });

    pauseBtn.addEventListener('click', () => {
      paused = !paused;
      pauseBtn.textContent = paused ? 'Resume Stream' : 'Pause Stream';
      connectionStatus.textContent = paused
        ? 'Stream paused'
        : 'Streaming simulated live data';

      addSystemLog(paused ? 'Live stream paused' : 'Live stream resumed', 'info');
    });

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const type = document.getElementById('eventType').value;
      const source = document.getElementById('eventSource').value.trim();
      const message = document.getElementById('eventMessage').value.trim();

      if (!source || !message) {
        addSystemLog('Form validation failed: all fields are required', 'error');
        return;
      }

      const item = document.createElement('div');
      item.className = 'log-item';
      item.innerHTML = `
        <div class="time">${formatTime(new Date())}</div>
        <div class="msg">
          <strong>${source}:</strong> ${message}
          <span class="tag ${type}">${type.toUpperCase()}</span>
        </div>
      `;

      eventLogEl.prepend(item);
      eventCount++;
      eventCountEl.textContent = eventCount;

      eventForm.reset();
    });

    // Initial seed data
    for (let i = 0; i < 8; i++) {
      labels.push(formatTime(new Date(Date.now() - (8000 - i * 1000))));
      values.push(generateValue());
    }
    liveChart.update();
    updateMetrics();
    addSystemLog('Dashboard initialized', 'info');
    startStream();
  </script>
</body>
</html>
