## 2) `server.js`

```javascript
import express from "express";
import path from "path";
import { fileURLToPath } from "url";

const app = express();
const PORT = 3000;

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let metrics = {
  currentValue: 42,
  totalSubmissions: 0,
  averageValue: 42,
  labels: [],
  values: [],
  logs: []
};

const clients = new Set();

function seedData() {
  const now = Date.now();
  metrics.labels = [];
  metrics.values = [];
  for (let i = 9; i >= 0; i--) {
    const timestamp = new Date(now - i * 5000).toLocaleTimeString();
    const value = Math.floor(Math.random() * 100);
    metrics.labels.push(timestamp);
    metrics.values.push(value);
  }
  metrics.currentValue = metrics.values[metrics.values.length - 1];
  metrics.averageValue =
    metrics.values.reduce((a, b) => a + b, 0) / metrics.values.length;
}
seedData();

function broadcast(payload) {
  const data = `data: ${JSON.stringify(payload)}\n\n`;
  for (const res of clients) {
    res.write(data);
  }
}

function recomputeAverage() {
  metrics.averageValue =
    metrics.values.reduce((sum, value) => sum + value, 0) / metrics.values.length;
}

setInterval(() => {
  const value = Math.floor(Math.random() * 100);
  const label = new Date().toLocaleTimeString();

  metrics.currentValue = value;
  metrics.labels.push(label);
  metrics.values.push(value);

  if (metrics.labels.length > 20) metrics.labels.shift();
  if (metrics.values.length > 20) metrics.values.shift();

  recomputeAverage();

  const logEntry = {
    time: label,
    message: `Auto update received: ${value}`
  };

  metrics.logs.unshift(logEntry);
  metrics.logs = metrics.logs.slice(0, 10);

  broadcast({
    type: "metrics",
    metrics
  });
}, 3000);

app.get("/api/metrics", (req, res) => {
  res.json(metrics);
});

app.get("/api/events", (req, res) => {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();

  clients.add(res);

  res.write(`data: ${JSON.stringify({ type: "metrics", metrics })}\n\n`);

  req.on("close", () => {
    clients.delete(res);
  });
});

app.post("/api/submit", (req, res) => {
  const { name, value } = req.body;

  if (!name || typeof value !== "number") {
    return res.status(400).json({ error: "Invalid payload" });
  }

  metrics.totalSubmissions += 1;
  metrics.currentValue = value;
  metrics.labels.push(new Date().toLocaleTimeString());
  metrics.values.push(value);

  if (metrics.labels.length > 20) metrics.labels.shift();
  if (metrics.values.length > 20) metrics.values.shift();

  recomputeAverage();

  const logEntry = {
    time: new Date().toLocaleTimeString(),
    message: `Manual submission from ${name}: ${value}`
  };

  metrics.logs.unshift(logEntry);
  metrics.logs = metrics.logs.slice(0, 10);

  broadcast({
    type: "metrics",
    metrics
  });

  res.json({ success: true, metrics });
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

