## 5) `public/app.js`

```javascript
const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const totalSubmissionsEl = document.getElementById("totalSubmissions");
const eventLogEl = document.getElementById("eventLog");
const form = document.getElementById("dataForm");
const formMessage = document.getElementById("formMessage");

const ctx = document.getElementById("chart").getContext("2d");

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Metric Value",
        data: [],
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.2)",
        fill: true,
        tension: 0.3
      }
    ]
  },
  options: {
    responsive: true,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#334155" }
      },
      y: {
        beginAtZero: true,
        max: 100,
        ticks: { color: "#94a3b8" },
        grid: { color: "#334155" }
      }
    }
  }
});

function render(metrics) {
  currentValueEl.textContent = metrics.currentValue.toFixed(0);
  averageValueEl.textContent = metrics.averageValue.toFixed(2);
  totalSubmissionsEl.textContent = metrics.totalSubmissions.toString();

  chart.data.labels = metrics.labels;
  chart.data.datasets[0].data = metrics.values;
  chart.update();

  eventLogEl.innerHTML = "";
  metrics.logs.forEach((log) => {
    const li = document.createElement("li");
    li.innerHTML = `<small>${log.time}</small> ${log.message}`;
    eventLogEl.appendChild(li);
  });
}

async function loadInitialData() {
  const res = await fetch("/api/metrics");
  const metrics = await res.json();
  render(metrics);
}

function connectEvents() {
  const source = new EventSource("/api/events");

  source.onmessage = (event) => {
    const payload = JSON.parse(event.data);
    if (payload.type === "metrics") {
      render(payload.metrics);
    }
  };

  source.onerror = () => {
    formMessage.textContent = "Live connection interrupted. Retrying...";
  };
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const name = document.getElementById("name").value.trim();
  const value = Number(document.getElementById("value").value);

  formMessage.textContent = "";

  try {
    const res = await fetch("/api/submit", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ name, value })
    });

    if (!res.ok) {
      throw new Error("Submission failed");
    }

    const result = await res.json();
    render(result.metrics);
    formMessage.textContent = "Submission successful.";
    form.reset();
  } catch (err) {
    formMessage.textContent = "Error submitting form.";
  }
});

loadInitialData();
connectEvents();
