## 3) `app.ts`

```ts
type DashboardSettings = {
  username: string;
  threshold: number;
  refreshRate: number;
  alertsEnabled: boolean;
};

type DataPoint = {
  time: Date;
  value: number;
};

class DashboardApp {
  private data: DataPoint[] = [];
  private maxPoints = 50;
  private timerId: number | null = null;
  private isStreaming = true;

  private settings: DashboardSettings = {
    username: "Operator",
    threshold: 75,
    refreshRate: 1000,
    alertsEnabled: true,
  };

  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;

  private currentValueEl = document.getElementById("currentValue") as HTMLSpanElement;
  private averageValueEl = document.getElementById("averageValue") as HTMLSpanElement;
  private maxValueEl = document.getElementById("maxValue") as HTMLSpanElement;
  private thresholdDisplayEl = document.getElementById("thresholdDisplay") as HTMLSpanElement;
  private eventLogEl = document.getElementById("eventLog") as HTMLUListElement;
  private connectionStatusEl = document.getElementById("connectionStatus") as HTMLSpanElement;
  private toggleStreamBtn = document.getElementById("toggleStreamBtn") as HTMLButtonElement;
  private settingsForm = document.getElementById("settingsForm") as HTMLFormElement;

  constructor() {
    this.canvas = document.getElementById("chartCanvas") as HTMLCanvasElement;
    const ctx = this.canvas.getContext("2d");

    if (!ctx) {
      throw new Error("Canvas rendering context not available");
    }

    this.ctx = ctx;

    this.bindEvents();
    this.seedData();
    this.startStream();
    this.renderAll();
    this.logEvent("Dashboard initialized.");
  }

  private bindEvents(): void {
    this.toggleStreamBtn.addEventListener("click", () => {
      this.isStreaming ? this.pauseStream() : this.startStream();
    });

    this.settingsForm.addEventListener("submit", (event) => {
      event.preventDefault();
      this.handleFormSubmit();
    });

    window.addEventListener("resize", () => {
      this.renderChart();
    });
  }

  private seedData(): void {
    for (let i = 0; i < 20; i++) {
      this.data.push({
        time: new Date(Date.now() - (20 - i) * this.settings.refreshRate),
        value: this.generateValue(),
      });
    }
  }

  private generateValue(): number {
    const base = 50;
    const variance = Math.random() * 40 - 20;
    const spike = Math.random() > 0.9 ? Math.random() * 25 : 0;
    return Math.max(0, Math.min(100, Math.round(base + variance + spike)));
  }

  private startStream(): void {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
    }

    this.isStreaming = true;
    this.connectionStatusEl.textContent = "Online";
    this.connectionStatusEl.className = "status online";
    this.toggleStreamBtn.textContent = "Pause Stream";

    this.timerId = window.setInterval(() => {
      this.pushDataPoint();
    }, this.settings.refreshRate);

    this.logEvent("Data stream started.");
  }

  private pauseStream(): void {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
      this.timerId = null;
    }

    this.isStreaming = false;
    this.connectionStatusEl.textContent = "Paused";
    this.connectionStatusEl.className = "status offline";
    this.toggleStreamBtn.textContent = "Resume Stream";

    this.logEvent("Data stream paused.");
  }

  private pushDataPoint(): void {
    const newPoint: DataPoint = {
      time: new Date(),
      value: this.generateValue(),
    };

    this.data.push(newPoint);

    if (this.data.length > this.maxPoints) {
      this.data.shift();
    }

    this.renderAll();

    if (this.settings.alertsEnabled && newPoint.value >= this.settings.threshold) {
      this.logEvent(
        `Alert: value ${newPoint.value} exceeded threshold ${this.settings.threshold}.`,
        true
      );
    }
  }

  private handleFormSubmit(): void {
    const usernameInput = document.getElementById("username") as HTMLInputElement;
    const thresholdInput = document.getElementById("threshold") as HTMLInputElement;
    const refreshRateInput = document.getElementById("refreshRate") as HTMLSelectElement;
    const alertsEnabledInput = document.getElementById("alertsEnabled") as HTMLInputElement;

    const usernameError = document.getElementById("usernameError") as HTMLElement;
    const thresholdError = document.getElementById("thresholdError") as HTMLElement;

    usernameError.textContent = "";
    thresholdError.textContent = "";

    let isValid = true;

    const username = usernameInput.value.trim();
    const threshold = Number(thresholdInput.value);
    const refreshRate = Number(refreshRateInput.value);
    const alertsEnabled = alertsEnabledInput.checked;

    if (username.length < 2) {
      usernameError.textContent = "Name must be at least 2 characters.";
      isValid = false;
    }

    if (Number.isNaN(threshold) || threshold < 0 || threshold > 100) {
      thresholdError.textContent = "Threshold must be between 0 and 100.";
      isValid = false;
    }

    if (!isValid) return;

    this.settings = {
      username,
      threshold,
      refreshRate,
      alertsEnabled,
    };

    this.thresholdDisplayEl.textContent = String(threshold);
    this.logEvent(
      `Settings updated by ${username}: threshold=${threshold}, refresh=${refreshRate}ms, alerts=${alertsEnabled}`
    );

    if (this.isStreaming) {
      this.startStream();
    }

    this.renderAll();
  }

  private renderAll(): void {
    this.renderKpis();
    this.renderChart();
  }

  private renderKpis(): void {
    if (this.data.length === 0) return;

    const values = this.data.map((point) => point.value);
    const current = values[values.length - 1];
    const average = values.reduce((sum, value) => sum + value, 0) / values.length;
    const max = Math.max(...values);

    this.currentValueEl.textContent = current.toFixed(0);
    this.averageValueEl.textContent = average.toFixed(1);
    this.maxValueEl.textContent = max.toFixed(0);
    this.thresholdDisplayEl.textContent = String(this.settings.threshold);
  }

  private renderChart(): void {
    const ctx = this.ctx;
    const { width, height } = this.canvas;

    ctx.clearRect(0, 0, width, height);

    // Background
    ctx.fillStyle = "#0b1220";
    ctx.fillRect(0, 0, width, height);

    // Grid
    ctx.strokeStyle = "#334155";
    ctx.lineWidth = 1;

    for (let i = 0; i <= 5; i++) {
      const y = (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // Threshold line
    const thresholdY = height - (this.settings.threshold / 100) * height;
    ctx.strokeStyle = "#f59e0b";
    ctx.setLineDash([6, 6]);
    ctx.beginPath();
    ctx.moveTo(0, thresholdY);
    ctx.lineTo(width, thresholdY);
    ctx.stroke();
    ctx.setLineDash([]);

    if (this.data.length < 2) return;

    // Data line
    ctx.strokeStyle = "#22c55e";
    ctx.lineWidth = 2;
    ctx.beginPath();

    this.data.forEach((point, index) => {
      const x = (index / (this.maxPoints - 1)) * width;
      const y = height - (point.value / 100) * height;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });

    ctx.stroke();

    // Points
    this.data.forEach((point, index) => {
      const x = (index / (this.maxPoints - 1)) * width;
      const y = height - (point.value / 100) * height;

      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fillStyle =
        point.value >= this.settings.threshold ? "#ef4444" : "#22c55e";
      ctx.fill();
    });
  }

  private logEvent(message: string, isAlert = false): void {
    const li = document.createElement("li");
    li.className = isAlert ? "alert" : "normal";

    const time = new Date().toLocaleTimeString();
    li.textContent = `[${time}] ${message}`;

    this.eventLogEl.prepend(li);

    while (this.eventLogEl.children.length > 30) {
      this.eventLogEl.removeChild(this.eventLogEl.lastChild as Node);
    }
  }
}

document.addEventListener("DOMContentLoaded", () => {
  new DashboardApp();
});
```

