## `app.ts`

```ts
type DashboardSettings = {
  serviceName: string;
  threshold: number;
  refreshRate: number;
  notifications: boolean;
};

type MetricPoint = {
  timestamp: string;
  requestsPerSec: number;
  latency: number;
  errorRate: number;
};

const maxPoints = 20;

let settings: DashboardSettings = {
  serviceName: "api-gateway",
  threshold: 800,
  refreshRate: 1000,
  notifications: true,
};

let intervalId: number | null = null;
const data: MetricPoint[] = [];

const requestsPerSecEl = document.getElementById("requestsPerSec") as HTMLSpanElement;
const latencyEl = document.getElementById("latency") as HTMLSpanElement;
const errorRateEl = document.getElementById("errorRate") as HTMLSpanElement;
const systemStatusEl = document.getElementById("systemStatus") as HTMLSpanElement;
const formMessageEl = document.getElementById("formMessage") as HTMLDivElement;
const eventLogEl = document.getElementById("eventLog") as HTMLUListElement;
const settingsForm = document.getElementById("settingsForm") as HTMLFormElement;
const resetBtn = document.getElementById("resetBtn") as HTMLButtonElement;

const trafficCtx = (document.getElementById("trafficChart") as HTMLCanvasElement).getContext("2d");
const latencyCtx = (document.getElementById("latencyChart") as HTMLCanvasElement).getContext("2d");

if (!trafficCtx || !latencyCtx) {
  throw new Error("Chart canvas context not available.");
}

const trafficChart = new Chart(trafficCtx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Requests/sec",
        data: [],
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.2)",
        tension: 0.3,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#1e293b" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#1e293b" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

const latencyChart = new Chart(latencyCtx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Latency (ms)",
        data: [],
        borderColor: "#f59e0b",
        backgroundColor: "rgba(245, 158, 11, 0.2)",
        tension: 0.3,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#1e293b" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#1e293b" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function nowLabel(): string {
  return new Date().toLocaleTimeString();
}

function simulateMetric(): MetricPoint {
  const requestsPerSec = Math.floor(150 + Math.random() * 100);
  const latency = Math.floor(200 + Math.random() * 900);
  const errorRate = Number((Math.random() * 5).toFixed(2));

  return {
    timestamp: nowLabel(),
    requestsPerSec,
    latency,
    errorRate,
  };
}

function updateStatus(latency: number, errorRate: number): void {
  systemStatusEl.className = "value status";

  if (latency > settings.threshold || errorRate > 3) {
    systemStatusEl.textContent = "Degraded";
    systemStatusEl.classList.add("warn");
  } else if (latency > settings.threshold * 1.5 || errorRate > 4.5) {
    systemStatusEl.textContent = "Critical";
    systemStatusEl.classList.add("bad");
  } else {
    systemStatusEl.textContent = "Healthy";
    systemStatusEl.classList.add("ok");
  }
}

function addLog(message: string): void {
  const item = document.createElement("li");
  item.textContent = `${new Date().toLocaleTimeString()} — ${message}`;
  eventLogEl.prepend(item);

  while (eventLogEl.children.length > 30) {
    eventLogEl.removeChild(eventLogEl.lastElementChild as Node);
  }
}

function renderLatest(point: MetricPoint): void {
  requestsPerSecEl.textContent = point.requestsPerSec.toString();
  latencyEl.textContent = `${point.latency} ms`;
  errorRateEl.textContent = `${point.errorRate}%`;
  updateStatus(point.latency, point.errorRate);
}

function updateCharts(): void {
  const labels = data.map((p) => p.timestamp);

  trafficChart.data.labels = labels;
  trafficChart.data.datasets[0].data = data.map((p) => p.requestsPerSec);

  latencyChart.data.labels = labels;
  latencyChart.data.datasets[0].data = data.map((p) => p.latency);

  trafficChart.update();
  latencyChart.update();
}

function tick(): void {
  const point = simulateMetric();
  data.push(point);

  if (data.length > maxPoints) {
    data.shift();
  }

  renderLatest(point);
  updateCharts();

  if (point.latency > settings.threshold) {
    addLog(`${settings.serviceName} latency exceeded threshold: ${point.latency}ms`);
  } else {
    addLog(`${settings.serviceName} processed ${point.requestsPerSec} req/s`);
  }
}

function startStream(): void {
  if (intervalId !== null) {
    window.clearInterval(intervalId);
  }

  intervalId = window.setInterval(tick, settings.refreshRate);
}

function showMessage(message: string, isError = false): void {
  formMessageEl.textContent = message;
  formMessageEl.style.color = isError ? "#ef4444" : "#22c55e";
}

settingsForm.addEventListener("submit", (event) => {
  event.preventDefault();

  const formData = new FormData(settingsForm);
  const serviceName = String(formData.get("serviceName") || "").trim();
  const threshold = Number(formData.get("threshold"));
  const refreshRate = Number(formData.get("refreshRate"));
  const notifications = formData.get("notifications") === "on";

  if (!serviceName) {
    showMessage("Service name is required.", true);
    return;
  }

  if (Number.isNaN(threshold) || threshold < 50 || threshold > 5000) {
    showMessage("Threshold must be between 50 and 5000.", true);
    return;
  }

  settings = {
    serviceName,
    threshold,
    refreshRate,
    notifications,
  };

  startStream();
  addLog(`Settings updated for ${settings.serviceName}`);
  showMessage("Settings saved successfully.");
});

resetBtn.addEventListener("click", () => {
  settings = {
    serviceName: "api-gateway",
    threshold: 800,
    refreshRate: 1000,
    notifications: true,
  };

  (document.getElementById("serviceName") as HTMLInputElement).value = settings.serviceName;
  (document.getElementById("threshold") as HTMLInputElement).value = String(settings.threshold);
  (document.getElementById("refreshRate") as HTMLSelectElement).value = String(settings.refreshRate);
  (document.getElementById("notifications") as HTMLInputElement).checked = settings.notifications;

  startStream();
  addLog("Settings reset to defaults");
  showMessage("Settings reset.");
});

function initForm(): void {
  (document.getElementById("serviceName") as HTMLInputElement).value = settings.serviceName;
  (document.getElementById("threshold") as HTMLInputElement).value = String(settings.threshold);
  (document.getElementById("refreshRate") as HTMLSelectElement).value = String(settings.refreshRate);
  (document.getElementById("notifications") as HTMLInputElement).checked = settings.notifications;
}

function init(): void {
  initForm();
  for (let i = 0; i < 6; i++) {
    const point = simulateMetric();
    data.push(point);
  }
  renderLatest(data[data.length - 1]);
  updateCharts();
  addLog("Dashboard initialized");
  startStream();
}

init();
