## src/hooks/useRealtimeData.ts

```tsx
import { useEffect, useMemo, useState } from 'react';
import type { DashboardEvent, DataPoint, FormState } from '../types';

const MAX_POINTS = 20;

function makeTimestamp() {
  return new Date().toLocaleTimeString();
}

export function useRealtimeData(settings: FormState) {
  const [data, setData] = useState<DataPoint[]>([]);
  const [events, setEvents] = useState<DashboardEvent[]>([]);
  const [currentValue, setCurrentValue] = useState(50);

  useEffect(() => {
    const interval = setInterval(() => {
      const next = Math.max(
        0,
        Math.min(100, currentValue + (Math.random() * 16 - 8))
      );

      const point: DataPoint = {
        time: makeTimestamp(),
        value: Number(next.toFixed(2))
      };

      setCurrentValue(next);

      setData((prev) => [...prev, point].slice(-MAX_POINTS));

      if (settings.alertsEnabled && next > settings.threshold) {
        setEvents((prev) => [
          {
            id: Date.now(),
            timestamp: makeTimestamp(),
            message: `Alert: value ${next.toFixed(2)} exceeded threshold ${settings.threshold}`
          },
          ...prev
        ].slice(0, 12));
      }
    }, settings.refreshMs);

    return () => clearInterval(interval);
  }, [settings.refreshMs, settings.threshold, settings.alertsEnabled, currentValue]);

  const stats = useMemo(() => {
    if (data.length === 0) {
      return {
        latest: 0,
        average: 0,
        peak: 0
      };
    }

    const latest = data[data.length - 1].value;
    const average =
      data.reduce((sum, point) => sum + point.value, 0) / data.length;
    const peak = Math.max(...data.map((point) => point.value));

    return {
      latest: Number(latest.toFixed(2)),
      average: Number(average.toFixed(2)),
      peak: Number(peak.toFixed(2))
    };
  }, [data]);

  return {
    data,
    events,
    stats
  };
}
```

