    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 16px;
    }

    .stat {
      background: #eef2ff;
      border-radius: 10px;
      padding: 12px;
    }

    .stat-label {
      font-size: 12px;
      color: #6b7280;
    }

