      font: inherit;
    }

    textarea {
      min-height: 90px;
      resize: vertical;
    }

    .event-list {
      margin-top: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      max-height: 300px;
      overflow: auto;
    }

    .event-item {
      padding: 12px;
      background: #f9fafb;
      border-radius: 8px;
      border-left: 4px solid #2563eb;
    }

    .event-title {
      font-weight: 700;
    }

    .event-meta {
      font-size: 12px;
      color: #6b7280;
      margin-top: 4px;
