  </style>
</head>
<body>
  <div id="root"></div>

  <script type="text/babel" data-presets="typescript,react">
    const { useEffect, useRef, useState } = React;

    type DataPoint = {
      time: string;
      value: number;
    };

    type EventNote = {
      id: number;
      title: string;
      description: string;
      createdAt: string;
    };

    function App() {
      const chartRef = useRef<HTMLCanvasElement | null>(null);
      const chartInstanceRef = useRef<any>(null);
      const intervalRef = useRef<number | null>(null);

      const [data, setData] = useState<DataPoint[]>([]);
      const [isRunning, setIsRunning] = useState<boolean>(true);
      const [events, setEvents] = useState<EventNote[]>([]);
      const [title, setTitle] = useState<string>("");
      const [description, setDescription] = useState<string>("");

      const latestValue = data.length ? data[data.length - 1].value : 0;
      const avgValue = data.length
        ? (data.reduce((sum, point) => sum + point.value, 0) / data.length).toFixed(1)
        : "0.0";
      const maxValue = data.length
        ? Math.max(...data.map((d) => d.value))
        : 0;

      const generatePoint = (): DataPoint => {
        const now = new Date();
        return {
          time: now.toLocaleTimeString(),
          value: Math.floor(40 + Math.random() * 60)
        };
      };

      useEffect(() => {
        const initialData = Array.from({ length: 10 }, () => generatePoint());
        setData(initialData);
      }, []);

      useEffect(() => {
        if (!chartRef.current || data.length === 0) return;

        if (chartInstanceRef.current) {
          chartInstanceRef.current.destroy();
        }

        const ctx = chartRef.current.getContext("2d");
        chartInstanceRef.current = new Chart(ctx, {
          type: "line",
          data: {
            labels: data.map((d) => d.time),
            datasets: [
              {
                label: "Live Metric",
                data: data.map((d) => d.value),
                borderColor: "#2563eb",
                backgroundColor: "rgba(37, 99, 235, 0.2)",
                fill: true,
                tension: 0.3
              }
            ]
          },
          options: {
            responsive: true,
            animation: false,
            scales: {
              y: {
                beginAtZero: true
              }
            }
          }
        });

        return () => {
          if (chartInstanceRef.current) {
            chartInstanceRef.current.destroy();
          }
        };
      }, [data]);

      useEffect(() => {
        if (isRunning) {
          intervalRef.current = window.setInterval(() => {
            setData((prev) => {
              const next = [...prev, generatePoint()];
              return next.slice(-20);
            });
          }, 1000);
        }

        return () => {
          if (intervalRef.current) {
            clearInterval(intervalRef.current);
          }
        };
      }, [isRunning]);

      const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!title.trim()) return;

        const newEvent: EventNote = {
          id: Date.now(),
          title: title.trim(),
          description: description.trim(),
          createdAt: new Date().toLocaleString()
        };

        setEvents((prev) => [newEvent, ...prev]);
        setTitle("");
        setDescription("");
      };

      const handleReset = () => {
        setData(Array.from({ length: 10 }, () => generatePoint()));
        setEvents([]);
      };

      return (
        <div className="container">
          <h1>Interactive Real-Time Dashboard</h1>
          <div className="subtitle">
            Live visualisation, real-time updates, and form-based event capture
          </div>

          <div className="stats">
            <div className="stat">
              <div className="stat-label">Latest Value</div>
              <div className="stat-value">{latestValue}</div>
            </div>
            <div className="stat">
              <div className="stat-label">Average</div>
              <div className="stat-value">{avgValue}</div>
            </div>
            <div className="stat">
              <div className="stat-label">Maximum</div>
              <div className="stat-value">{maxValue}</div>
            </div>
          </div>

          <div className="grid">
            <div className="card span-8">
              <h2>Real-Time Data Visualisation</h2>
              <canvas ref={chartRef}></canvas>
              <div className="controls">
                <button
                  className="btn-primary"
                  onClick={() => setIsRunning(true)}
                >
                  Start
                </button>
                <button
                  className="btn-secondary"
                  onClick={() => setIsRunning(false)}
                >
                  Stop
                </button>
                <button
                  className="btn-danger"
                  onClick={handleReset}
                >
                  Reset
                </button>
              </div>
            </div>

            <div className="card span-4">
              <h2>Add Event Note</h2>
              <form onSubmit={handleSubmit}>
                <div>
                  <input
                    type="text"
                    placeholder="Event title"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                  />
                </div>
                <div>
                  <textarea
                    placeholder="Event description"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                  ></textarea>
                </div>
                <button type="submit" className="btn-primary">
                  Save Event
                </button>
              </form>
            </div>

            <div className="card span-12">
              <h2>Submitted Events</h2>
              {events.length === 0 ? (
                <div className="subtitle">No events submitted yet.</div>
              ) : (
                <div className="event-list">
                  {events.map((event) => (
                    <div key={event.id} className="event-item">
                      <div className="event-title">{event.title}</div>
                      <div>{event.description || "No description provided."}</div>
                      <div className="event-meta">{event.createdAt}</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById("root"));
    root.render(<App />);
  </script>
</body>
</html>
```

