      border-radius: 8px;
      border: 1px solid var(--border);
      font-size: 14px;
    }

    input {
      background: #0b1220;
      color: var(--text);
    }

    button {
      background: var(--accent);
      color: #052e16;
      font-weight: bold;
      cursor: pointer;
      border: none;
    }

    button:hover {
      opacity: 0.95;
    }

    .message {
      min-height: 20px;
      font-size: 14px;
    }

