<body>
  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="metrics">
      <div class="metric">
        <div class="metric-label">Latest Value</div>
        <div class="metric-value" id="latestValue">0</div>
      </div>
      <div class="metric">
        <div class="metric-label">Average Value</div>
        <div class="metric-value" id="averageValue">0</div>
      </div>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Data</h2>
        <canvas id="chart" width="600" height="300"></canvas>
      </div>

      <div class="card">
        <h2>Form Handling</h2>
        <form id="settingsForm">
          <div>
            <label for="username">Name</label><br />
            <input id="username" name="username" type="text" placeholder="Enter your name" />
          </div>

          <div>
            <label for="threshold">Alert Threshold</label><br />
            <input id="threshold" name="threshold" type="number" min="0" max="100" placeholder="e.g. 70" />
          </div>

          <button type="submit">Save Settings</button>
          <div id="formMessage" class="message"></div>
        </form>

        <div class="log" id="eventLog"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const latestValueEl = document.getElementById("latestValue");
    const averageValueEl = document.getElementById("averageValue");
    const form = document.getElementById("settingsForm");
    const formMessage = document.getElementById("formMessage");
    const eventLog = document.getElementById("eventLog");

    let threshold = 70;
    let username = "Guest";

    const data = [];
    const maxPoints = 30;

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(item);

      while (eventLog.children.length > 8) {
        eventLog.removeChild(eventLog.lastChild);
      }
    }

    function generateDataPoint() {
      return Math.floor(Math.random() * 100);
    }

    function updateData() {
      const value = generateDataPoint();
      data.push(value);

      if (data.length > maxPoints) {
        data.shift();
      }

      const avg = data.reduce((sum, v) => sum + v, 0) / data.length;

      latestValueEl.textContent = value;
      averageValueEl.textContent = avg.toFixed(1);

      if (value >= threshold) {
        addLog(`${username}: alert triggered at value ${value} (threshold ${threshold})`);
      }

      drawChart();
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const w = canvas.width;
      const h = canvas.height;
      const padding = 30;

      // axes
      ctx.strokeStyle = "#475569";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, h - padding);
      ctx.lineTo(w - padding, h - padding);
      ctx.stroke();

      if (data.length < 2) return;

      const maxValue = 100;
      const minValue = 0;
      const xStep = (w - padding * 2) / (maxPoints - 1);

      // threshold line
      const thresholdY =
        h - padding - ((threshold - minValue) / (maxValue - minValue)) * (h - padding * 2);

      ctx.strokeStyle = "#ef4444";
      ctx.setLineDash([6, 4]);
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(w - padding, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      // line
      ctx.strokeStyle = "#22c55e";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + index * xStep;
        const y =
          h - padding - ((value - minValue) / (maxValue - minValue)) * (h - padding * 2);

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // points
      ctx.fillStyle = "#86efac";
      data.forEach((value, index) => {
        const x = padding + index * xStep;
        const y =
          h - padding - ((value - minValue) / (maxValue - minValue)) * (h - padding * 2);

        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const nameInput = document.getElementById("username").value.trim();
      const thresholdInput = document.getElementById("threshold").value.trim();

      if (!nameInput) {
        formMessage.textContent = "Name is required.";
        formMessage.className = "message error";
        return;
      }

      const parsedThreshold = Number(thresholdInput);

      if (
        thresholdInput === "" ||
        Number.isNaN(parsedThreshold) ||
        parsedThreshold < 0 ||
        parsedThreshold > 100
      ) {
        formMessage.textContent = "Threshold must be a number between 0 and 100.";
        formMessage.className = "message error";
        return;
      }

      username = nameInput;
      threshold = parsedThreshold;

      formMessage.textContent = "Settings saved successfully.";
      formMessage.className = "message success";

      addLog(`${username} updated threshold to ${threshold}`);
      drawChart();
    });

    addLog("Dashboard started");
    for (let i = 0; i < 10; i++) {
      data.push(generateDataPoint());
    }
    drawChart();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
