<body>
  <div class="container">
    <h1>Realtime Dashboard</h1>

    <div class="grid">
      <div class="card">
        <h2>Live Data</h2>
        <canvas id="chart" width="700" height="300"></canvas>

        <div class="metric">
          <span>Latest Value</span>
          <strong id="latestValue">0</strong>
        </div>
        <div class="metric">
          <span>Average</span>
          <strong id="avgValue">0</strong>
        </div>
        <div class="metric">
          <span>Total Points</span>
          <strong id="countValue">0</strong>
        </div>

        <div class="button-row" style="margin-top:12px;">
          <button id="startBtn" class="secondary" type="button">Start Stream</button>
          <button id="stopBtn" class="danger" type="button">Stop Stream</button>
        </div>
      </div>

      <div class="card">
        <h2>Add Data Point</h2>
        <form id="dataForm">
          <div>
            <label for="labelInput">Label</label>
            <input id="labelInput" name="label" type="text" placeholder="e.g. Sensor A" required />
          </div>

          <div>
            <label for="valueInput">Value</label>
            <input id="valueInput" name="value" type="number" step="any" placeholder="e.g. 42" required />
          </div>

          <button type="submit">Submit Data Point</button>
        </form>

        <div id="status" class="status"></div>

        <div class="log" id="log"></div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('chart');
    const ctx = canvas.getContext('2d');

    const latestValueEl = document.getElementById('latestValue');
    const avgValueEl = document.getElementById('avgValue');
    const countValueEl = document.getElementById('countValue');
    const statusEl = document.getElementById('status');
    const logEl = document.getElementById('log');

    const form = document.getElementById('dataForm');
    const labelInput = document.getElementById('labelInput');
    const valueInput = document.getElementById('valueInput');
    const startBtn = document.getElementById('startBtn');
    const stopBtn = document.getElementById('stopBtn');

    const maxPoints = 30;
    const data = [];

    function addLog(message) {
      const entry = document.createElement('div');
      entry.className = 'log-entry';
      entry.textContent = `${new Date().toLocaleTimeString()} - ${message}`;
      logEl.prepend(entry);
    }

    function addPoint(label, value) {
      data.push({ label, value, time: new Date() });
      if (data.length > maxPoints) data.shift();
      updateMetrics();
      drawChart();
      addLog(`Added "${label}" = ${value}`);
    }

    function updateMetrics() {
      if (data.length === 0) {
        latestValueEl.textContent = '0';
        avgValueEl.textContent = '0';
        countValueEl.textContent = '0';
        return;
      }

      const values = data.map(d => d.value);
      const latest = values[values.length - 1];
      const avg = values.reduce((a, b) => a + b, 0) / values.length;

      latestValueEl.textContent = latest.toFixed(2);
      avgValueEl.textContent = avg.toFixed(2);
      countValueEl.textContent = String(data.length);
    }

    function drawChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length === 0) return;

      const values = data.map(d => d.value);
      const min = Math.min(...values, 0);
      const max = Math.max(...values, 100);
      const range = max - min || 1;

      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, i) => {
        const x = (i / Math.max(data.length - 1, 1)) * (w - 40) + 20;
        const y = h - ((point.value - min) / range) * (h - 40) - 20;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      ctx.fillStyle = '#22c55e';
      data.forEach((point, i) => {
        const x = (i / Math.max(data.length - 1, 1)) * (w - 40) + 20;
        const y = h - ((point.value - min) / range) * (h - 40) - 20;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = parseFloat(valueInput.value);

      if (!label) {
        statusEl.textContent = 'Please enter a label.';
        return;
      }

      if (Number.isNaN(value)) {
        statusEl.textContent = 'Please enter a valid numeric value.';
        return;
      }

      addPoint(label, value);
      statusEl.textContent = `Submitted: ${label} = ${value}`;
      form.reset();
      labelInput.focus();
    });

    let intervalId = null;
    let counter = 1;

    function startStream() {
      if (intervalId) return;
      statusEl.textContent = 'Live stream started.';
      addLog('Live stream started');

      intervalId = setInterval(() => {
        const simulatedValue = 20 + Math.random() * 80;
        addPoint(`Auto ${counter++}`, simulatedValue);
      }, 1000);
    }

    function stopStream() {
      if (!intervalId) return;
      clearInterval(intervalId);
      intervalId = null;
      statusEl.textContent = 'Live stream stopped.';
      addLog('Live stream stopped');
    }

    startBtn.addEventListener('click', startStream);
    stopBtn.addEventListener('click', stopStream);

    for (let i = 1; i <= 8; i++) {
      addPoint(`Initial ${i}`, 20 + Math.random() * 80);
    }
  </script>
</body>
</html>
