    const form = document.getElementById('settingsForm');
    const formMessage = document.getElementById('formMessage');
    const toggleButton = document.getElementById('toggleStream');

    let config = {
      labelPrefix: 'Reading',
      intervalMs: 1000,
      maxPoints: 20,
      baseValue: 50,
      variance: 10
    };

    let timer = null;
    let running = true;
    let counter = 0;
    let values = [];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
