      counter++;
      const value = generateValue();
      const label = `${config.labelPrefix} ${counter}`;

      chart.data.labels.push(label);
      chart.data.datasets[0].data.push(value);
      values.push(value);

      if (chart.data.labels.length > config.maxPoints) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
        values.shift();
      }

      chart.update();
      updateStats();
    }

    function startStream() {
      stopStream();
      timer = setInterval(addDataPoint, config.intervalMs);
      running = true;
      toggleButton.textContent = 'Stop';
    }

    function stopStream() {
      if (timer) clearInterval(timer);
      timer = null;
      running = false;
      toggleButton.textContent = 'Start';
    }

    toggleButton.addEventListener('click', () => {
      if (running) {
        stopStream();
      } else {
        startStream();
      }
    });

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(form);

      config.labelPrefix = formData.get('labelPrefix') || 'Reading';
      config.intervalMs = Math.max(100, Number(formData.get('intervalMs')) || 1000);
      config.maxPoints = Math.max(5, Number(formData.get('maxPoints')) || 20);
      config.baseValue = Number(formData.get('baseValue')) || 50;
      config.variance = Number(formData.get('variance')) || 10;

      formMessage.textContent = 'Settings applied successfully.';

      if (running) {
        startStream();
      }

      setTimeout(() => {
        formMessage.textContent = '';
      }, 2000);
    });

    addDataPoint();
    startStream();
  </script>
