  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const thresholdValueEl = document.getElementById("thresholdValue");
    const form = document.getElementById("settingsForm");
    const formError = document.getElementById("formError");
    const eventLog = document.getElementById("eventLog");

    let threshold = 50;
    let refreshRate = 1000;
    let dashboardLabel = "Default Dashboard";
    let timer = null;

    const data = [];
    const maxPoints = 30;

    function log(message) {
      const entry = document.createElement("div");
      entry.className = "log-entry";
      entry.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(entry);
    }

    function generateDataPoint() {
      const value = Math.floor(Math.random() * 100);
      data.push(value);
      if (data.length > maxPoints) data.shift();

      currentValueEl.textContent = value;

      const avg = data.reduce((a, b) => a + b, 0) / data.length;
      averageValueEl.textContent = avg.toFixed(1);

      if (value > threshold) {
        log(`Alert: value ${value} exceeded threshold ${threshold}`);
      }

      drawChart();
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background grid
      ctx.strokeStyle = "#1e293b";
      ctx.lineWidth = 1;
      for (let y = 0; y <= 300; y += 50) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const padding = 20;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;

      // Threshold line
      const thresholdY = canvas.height - padding - (threshold / 100) * chartHeight;
      ctx.strokeStyle = "#ef4444";
      ctx.setLineDash([6, 4]);
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(canvas.width - padding, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);

      // Data line
      ctx.strokeStyle = "#22c55e";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = canvas.height - padding - (value / 100) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#86efac";
      data.forEach((value, index) => {
        const x = padding + (index / (maxPoints - 1)) * chartWidth;
        const y = canvas.height - padding - (value / 100) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function startFeed() {
      if (timer) clearInterval(timer);
      timer = setInterval(generateDataPoint, refreshRate);
      log(`Started real-time feed at ${refreshRate} ms for "${dashboardLabel}"`);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      formError.textContent = "";

      const newThreshold = Number(document.getElementById("threshold").value);
      const newLabel = document.getElementById("label").value.trim();
      const newRefreshRate = Number(document.getElementById("refreshRate").value);

      if (Number.isNaN(newThreshold) || newThreshold < 0 || newThreshold > 100) {
        formError.textContent = "Threshold must be a number between 0 and 100.";
        return;
      }

      if (!newLabel) {
        formError.textContent = "Dashboard label is required.";
        return;
      }

      threshold = newThreshold;
      dashboardLabel = newLabel;
      refreshRate = newRefreshRate;
      thresholdValueEl.textContent = threshold;

      drawChart();
      startFeed();
      log(`Settings updated: label="${dashboardLabel}", threshold=${threshold}, refresh=${refreshRate} ms`);
    });

    // Initial state
    drawChart();
    startFeed();
  </script>
</body>
</html>
```

