    const latestValueEl = document.getElementById("latestValue");
    const averageValueEl = document.getElementById("averageValue");
    const thresholdValueEl = document.getElementById("thresholdValue");
    const form = document.getElementById("controlForm");
    const displayNameInput = document.getElementById("displayName");
    const thresholdInput = document.getElementById("threshold");
    const speedInput = document.getElementById("speed");
    const formError = document.getElementById("formError");
    const eventLog = document.getElementById("eventLog");

    let data = Array.from({ length: 30 }, () => Math.floor(Math.random() * 100));
    let threshold = 50;
    let intervalMs = 1000;
    let timer = null;
    let dashboardName = "Real-Time Dashboard";

    function logEvent(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(item);
    }

    function updateStats() {
      const latest = data[data.length - 1];
      const avg = (data.reduce((a, b) => a + b, 0) / data.length).toFixed(1);

      latestValueEl.textContent = latest;
      averageValueEl.textContent = avg;
      thresholdValueEl.textContent = threshold;
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const w = canvas.width;
      const h = canvas.height;
      const padding = 30;

      ctx.strokeStyle = "#334155";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = padding + ((h - 2 * padding) / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(w - padding, y);
        ctx.stroke();
      }

      const thresholdY = h - padding - (threshold / 100) * (h - 2 * padding);
      ctx.strokeStyle = "#ef4444";
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(w - padding, thresholdY);
      ctx.stroke();

      ctx.strokeStyle = "#22c55e";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1)) * (w - 2 * padding);
        const y = h - padding - (value / 100) * (h - 2 * padding);
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      const latest = data[data.length - 1];
      const x = padding + ((data.length - 1) / (data.length - 1)) * (w - 2 * padding);
      const y = h - padding - (latest / 100) * (h - 2 * padding);

      ctx.fillStyle = latest >= threshold ? "#ef4444" : "#22c55e";
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    }

    function tick() {
      const next = Math.floor(Math.random() * 100);
      data.push(next);
      if (data.length > 30) data.shift();

      updateStats();
      drawChart();

      if (next >= threshold) {
        logEvent(`Alert: value ${next} exceeded threshold ${threshold}`);
      } else {
        logEvent(`Value updated to ${next}`);
      }
    }

    function startTimer() {
      if (timer) clearInterval(timer);
      timer = setInterval(tick, intervalMs);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      formError.textContent = "";

      const name = displayNameInput.value.trim();
      const newThreshold = Number(thresholdInput.value);
      const newSpeed = Number(speedInput.value);

      if (!name) {
        formError.textContent = "Display name is required.";
        return;
      }

      if (Number.isNaN(newThreshold) || newThreshold < 0 || newThreshold > 100) {
        formError.textContent = "Threshold must be between 0 and 100.";
        return;
      }

      dashboardName = name;
      threshold = newThreshold;
      intervalMs = newSpeed;

      document.title = dashboardName;
      document.querySelector("h1").textContent = dashboardName;

      updateStats();
      drawChart();
      startTimer();

      logEvent(`Settings applied: name="${dashboardName}", threshold=${threshold}, speed=${intervalMs}ms`);
      form.reset();
      displayNameInput.value = dashboardName;
      thresholdInput.value = threshold;
      speedInput.value = String(intervalMs);
    });

    displayNameInput.value = dashboardName;
    updateStats();
    drawChart();
    startTimer();
    logEvent("Dashboard started");
  </script>
