### `content.js`
```javascript
(() => {
  const trackerPatterns = [
    /google-analytics\.com/i,
    /googletagmanager\.com/i,
    /doubleclick\.net/i,
    /connect\.facebook\.net/i,
    /facebook\.net/i
  ];

  function isTrackerUrl(url) {
    return trackerPatterns.some(pattern => pattern.test(url));
  }

  function removeTrackingElements(root = document) {
    const elements = root.querySelectorAll('script[src], img[src], iframe[src]');
    for (const el of elements) {
      const src = el.src || "";
      if (src && isTrackerUrl(src)) {
        el.remove();
      }
    }
  }

  const observer = new MutationObserver(mutations => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (!(node instanceof Element)) continue;

        if (
          (node.tagName === "SCRIPT" || node.tagName === "IMG" || node.tagName === "IFRAME") &&
          node.src &&
          isTrackerUrl(node.src)
        ) {
          node.remove();
          continue;
        }

        removeTrackingElements(node);
      }
    }
  });

  if (document.documentElement) {
    removeTrackingElements(document);
    observer.observe(document.documentElement, {
      childList: true,
      subtree: true
    });
  }
})();
```

## Important fix
To load static rules correctly in MV3, it’s better to declare them in the manifest as rulesets instead of fetching them into dynamic rules.

Here is the improved `manifest.json`:

```json
{
  "manifest_version": 3,
  "name": "Privacy Tracker Blocker",
  "version": "1.0.0",
  "description": "Blocks known tracking scripts and requests.",
  "permissions": ["declarativeNetRequest", "storage"],
  "host_permissions": ["<all_urls>"],
  "background": {
    "service_worker": "background.js"
  },
  "declarative_net_request": {
    "rule_resources": [
      {
        "id": "tracker_rules",
        "enabled": true,
        "path": "rules.json"
      }
    ]
  },
  "action": {
    "default_title": "Privacy Tracker Blocker"
  },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "js": ["content.js"],
      "run_at": "document_start"
    }
  ]
}
```

