This toggles the ruleset on and off.

```javascript
const RULESET_ID = "tracker_rules";
const statusEl = document.getElementById("status");
const toggleBtn = document.getElementById("toggleBtn");

async function getEnabledRulesets() {
  if (!chrome.declarativeNetRequest.getEnabledRulesets) {
    return [];
  }
  return await chrome.declarativeNetRequest.getEnabledRulesets();
}

async function refreshUI() {
  const enabled = await getEnabledRulesets();
  const isEnabled = enabled.includes(RULESET_ID);

  statusEl.textContent = isEnabled ? "Protection: ON" : "Protection: OFF";
  toggleBtn.textContent = isEnabled ? "Disable" : "Enable";
}

toggleBtn.addEventListener("click", async () => {
  const enabled = await getEnabledRulesets();
  const isEnabled = enabled.includes(RULESET_ID);

  if (isEnabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      disableRulesetIds: [RULESET_ID]
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID]
    });
  }

  await refreshUI();
});

refreshUI();
