## 2) `rules.js`

This file contains tracker domains and helper functions.

```js
const TRACKER_DOMAINS = [
  "google-analytics.com",
  "googletagmanager.com",
  "doubleclick.net",
  "facebook.net",
  "connect.facebook.net",
  "analytics.twitter.com",
  "ads-twitter.com",
  "snap.licdn.com",
  "linkedin.com",
  "bat.bing.com",
  "hotjar.com",
  "segment.io",
  "segment.com",
  "mixpanel.com",
  "fullstory.com",
  "branch.io",
  "amplitude.com",
  "newrelic.com",
  "scorecardresearch.com",
  "quantserve.com",
  "criteo.com",
  "taboola.com",
  "outbrain.com"
];

const TRACKING_PARAMS = [
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "fbclid",
  "gclid",
  "mc_cid",
  "mc_eid",
  "msclkid"
];

function isTrackerUrl(url) {
  try {
    const u = new URL(url);
    return TRACKER_DOMAINS.some(domain =>
      u.hostname === domain || u.hostname.endsWith("." + domain)
    );
  } catch {
    return false;
  }
}

function stripTrackingParams(url) {
  try {
    const u = new URL(url);
    let changed = false;

    for (const param of TRACKING_PARAMS) {
      if (u.searchParams.has(param)) {
        u.searchParams.delete(param);
        changed = true;
      }
    }

    return { url: u.toString(), changed };
  } catch {
    return { url, changed: false };
  }
}
```

