## 3) `background.js`

This is the core logic. It installs dynamic blocking rules and updates badge counts.

```js
importScripts("rules.js");

const RULE_ID_BASE = 1000;
const STATE_KEY = "enabled";
const BLOCK_COUNT_KEY = "blockCount";

async function getEnabled() {
  const data = await chrome.storage.local.get([STATE_KEY]);
  return data[STATE_KEY] !== false;
}

async function setBadge(count) {
  await chrome.action.setBadgeBackgroundColor({ color: "#b00020" });
  await chrome.action.setBadgeText({ text: count > 0 ? String(count) : "" });
}

async function getBlockCount() {
  const data = await chrome.storage.local.get([BLOCK_COUNT_KEY]);
  return data[BLOCK_COUNT_KEY] || 0;
}

async function incrementBlockCount() {
  const count = (await getBlockCount()) + 1;
  await chrome.storage.local.set({ [BLOCK_COUNT_KEY]: count });
  await setBadge(count);
}

async function resetBlockCount() {
  await chrome.storage.local.set({ [BLOCK_COUNT_KEY]: 0 });
  await setBadge(0);
}

async function buildRules() {
  return TRACKER_DOMAINS.map((domain, index) => ({
    id: RULE_ID_BASE + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "image",
        "sub_frame",
        "ping"
      ]
    }
  }));
}

async function applyRules() {
  const enabled = await getEnabled();
  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existing.map(r => r.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds
  });

  if (!enabled) return;

  const rules = await buildRules();
  await chrome.declarativeNetRequest.updateDynamicRules({
    addRules: rules
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  await chrome.storage.local.set({ [STATE_KEY]: true });
  await resetBlockCount();
  await applyRules();
});

chrome.runtime.onStartup.addListener(async () => {
  await applyRules();
  const count = await getBlockCount();
  await setBadge(count);
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "local" && changes[STATE_KEY]) {
    await applyRules();
  }
});

chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener(async () => {
  await incrementBlockCount();
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "getStatus") {
    chrome.storage.local.get([STATE_KEY, BLOCK_COUNT_KEY]).then(data => {
      sendResponse({
        enabled: data[STATE_KEY] !== false,
        blockCount: data[BLOCK_COUNT_KEY] || 0
      });
    });
    return true;
  }

  if (message?.type === "setEnabled") {
    chrome.storage.local.set({ [STATE_KEY]: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }

  if (message?.type === "resetCount") {
    resetBlockCount().then(() => sendResponse({ ok: true }));
    return true;
  }
});
```

