## 4) `content.js`

This script strips tracking parameters from the current page URL when possible.

```js
(() => {
  const TRACKING_PARAMS = [
    "utm_source",
    "utm_medium",
    "utm_campaign",
    "utm_term",
    "utm_content",
    "fbclid",
    "gclid",
    "mc_cid",
    "mc_eid",
    "msclkid"
  ];

  try {
    const url = new URL(window.location.href);
    let changed = false;

    for (const param of TRACKING_PARAMS) {
      if (url.searchParams.has(param)) {
        url.searchParams.delete(param);
        changed = true;
      }
    }

    if (changed) {
      history.replaceState({}, document.title, url.pathname + url.search + url.hash);
    }
  } catch {}
})();
```

