const DEFAULT_SETTINGS = {
  enabled: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get(["enabled"]);
  if (typeof current.enabled === "undefined") {
    await chrome.storage.sync.set(DEFAULT_SETTINGS);
  }

  await syncRulesetState();
});

chrome.runtime.onStartup?.addListener(async () => {
  await syncRulesetState();
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "sync" && changes.enabled) {
    await syncRulesetState();
  }
});

async function syncRulesetState(): Promise<void> {
  const { enabled } = await chrome.storage.sync.get(["enabled"]);
  const isEnabled = enabled !== false;

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: isEnabled ? ["tracking_rules"] : [],
    disableRulesetIds: isEnabled ? [] : ["tracking_rules"]
  });
}
