const enabledCheckbox = document.getElementById("enabled") as HTMLInputElement;
const statusEl = document.getElementById("status") as HTMLDivElement;
const openOptionsLink = document.getElementById("openOptions") as HTMLAnchorElement;

init().catch(console.error);

async function init(): Promise<void> {
  const { enabled } = await chrome.storage.sync.get(["enabled"]);
  const isEnabled = enabled !== false;

  enabledCheckbox.checked = isEnabled;
  renderStatus(isEnabled);

  enabledCheckbox.addEventListener("change", async () => {
    const next = enabledCheckbox.checked;
    await chrome.storage.sync.set({ enabled: next });
    renderStatus(next);
  });

  openOptionsLink.addEventListener("click", (event) => {
    event.preventDefault();
    chrome.runtime.openOptionsPage();
  });
}

function renderStatus(enabled: boolean): void {
  statusEl.textContent = enabled
    ? "PrivateShield is blocking known tracking endpoints."
    : "PrivateShield is currently disabled.";
}
