chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.sync.get({
    blockingEnabled: true
  });

  await chrome.storage.sync.set({
    blockingEnabled: existing.blockingEnabled
  });

  await updateRulesetState(existing.blockingEnabled);
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "sync" && changes.blockingEnabled) {
    await updateRulesetState(changes.blockingEnabled.newValue);
  }
});

async function updateRulesetState(enabled: boolean): Promise<void> {
  const rulesetId = "ruleset_1";
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [rulesetId],
      disableRulesetIds: []
    });
    chrome.action.setBadgeText({ text: "ON" });
    chrome.action.setBadgeBackgroundColor({ color: "#2e7d32" });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [rulesetId]
    });
    chrome.action.setBadgeText({ text: "OFF" });
    chrome.action.setBadgeBackgroundColor({ color: "#757575" });
  }
}

chrome.action.onClicked.addListener(async () => {
  const { blockingEnabled = true } = await chrome.storage.sync.get("blockingEnabled");
  await chrome.storage.sync.set({ blockingEnabled: !blockingEnabled });
});
