const DEFAULT_SETTINGS = {
  enabled: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.local.get(["enabled"]);
  if (typeof current.enabled !== "boolean") {
    await chrome.storage.local.set(DEFAULT_SETTINGS);
  }
  await updateRulesetState();
});

chrome.runtime.onStartup.addListener(async () => {
  await updateRulesetState();
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "local" && changes.enabled) {
    await updateRulesetState();
  }
});

async function updateRulesetState(): Promise<void> {
  const { enabled = true } = await chrome.storage.local.get(["enabled"]);

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? ["tracker_rules"] : [],
    disableRulesetIds: enabled ? [] : ["tracker_rules"]
  });
}

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message?.type === "get-status") {
    chrome.storage.local.get(["enabled"]).then(({ enabled = true }) => {
      sendResponse({ enabled });
    });
    return true;
  }

  if (message?.type === "set-status") {
    chrome.storage.local.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ success: true, enabled: !!message.enabled });
    });
    return true;
  }
});
