const enabledToggle = document.getElementById("enabledToggle") as HTMLInputElement;
const statusText = document.getElementById("statusText") as HTMLParagraphElement;

async function initialize(): Promise<void> {
  const response = await chrome.runtime.sendMessage({ type: "get-status" });
  const enabled = !!response?.enabled;

  enabledToggle.checked = enabled;
  renderStatus(enabled);
}

function renderStatus(enabled: boolean): void {
  statusText.textContent = enabled
    ? "Protection is enabled."
    : "Protection is disabled.";
}

enabledToggle.addEventListener("change", async () => {
  const enabled = enabledToggle.checked;
  await chrome.runtime.sendMessage({ type: "set-status", enabled });
  renderStatus(enabled);
});

initialize().catch(() => {
  statusText.textContent = "Failed to load status.";
});
