`src/content.ts`
```ts
(() => {
  const disable = <T extends object, K extends keyof T>(obj: T, key: K, value: T[K]) => {
    try {
      Object.defineProperty(obj, key, {
        value,
        configurable: false,
        writable: false
      });
    } catch {
      // ignore
    }
  };

  const noop = () => {};
  const noopString = () => "";

  try {
    if ("sendBeacon" in navigator) {
      disable(navigator, "sendBeacon", (() => false) as typeof navigator.sendBeacon);
    }
  } catch {}

  try {
    const originalFetch = window.fetch;
    disable(window, "fetch", (async (...args: Parameters<typeof fetch>) => {
      const url = String(args[0]);
      const blocked = [
        "google-analytics.com",
        "googletagmanager.com",
        "facebook.com/tr",
        "segment.io",
        "hotjar.com",
        "clarity.ms"
      ].some(domain => url.includes(domain));

      if (blocked) {
        return new Response(null, { status: 204, statusText: "Blocked by Privacy Blocker" });
      }

      return originalFetch(...args);
    }) as typeof fetch);
  } catch {}

  try {
    const OriginalXHR = XMLHttpRequest;
    class BlockableXHR extends OriginalXHR {
      open(method: string, url: string | URL, async?: boolean, username?: string | null, password?: string | null): void {
        const u = String(url);
        const blocked = [
          "google-analytics.com",
          "googletagmanager.com",
          "facebook.com/tr",
          "segment.io",
          "hotjar.com",
          "clarity.ms"
        ].some(domain => u.includes(domain));

        if (blocked) {
          super.open(method, "data:,blocked", async ?? true, username ?? undefined, password ?? undefined);
          return;
        }

        super.open(method, url, async ?? true, username ?? undefined, password ?? undefined);
      }
    }

    // @ts-expect-error override for client-side mitigation
    disable(window, "XMLHttpRequest", BlockableXHR);
  } catch {}

  try {
    // Common analytics globals
    // @ts-expect-error intentional override
    disable(window, "ga", noop);
    // @ts-expect-error intentional override
    disable(window, "gtag", noop);
    // @ts-expect-error intentional override
    disable(window, "fbq", noop);
    // @ts-expect-error intentional override
    disable(window, "hj", noop);
    // @ts-expect-error intentional override
    disable(window, "_paq", []);
    // @ts-expect-error intentional override
    disable(window, "dataLayer", []);
  } catch {}

  try {
    const originalCookieSetter = Document.prototype.__lookupSetter__?.("cookie");
    const originalCookieGetter = Document.prototype.__lookupGetter__?.("cookie");

    if (originalCookieSetter && originalCookieGetter) {
      Object.defineProperty(document, "cookie", {
        configurable: false,
        get() {
          return originalCookieGetter.call(document);
        },
        set(value: string) {
          const suspicious = [
            "_ga=",
            "_gid=",
            "_fbp=",
            "_gcl_au=",
            "_hj"
          ].some(prefix => value.includes(prefix));

          if (!suspicious) {
            originalCookieSetter.call(document, value);
          }
        }
      });
    }
  } catch {}

  void noopString;
})();
