This toggles dynamic rules on/off by enabling/disabling the static ruleset.

```js
const toggleBtn = document.getElementById("toggle");

async function updateUI() {
  const { enabled = true } = await chrome.storage.local.get(["enabled"]);
  toggleBtn.textContent = enabled ? "Enabled - Click to Disable" : "Disabled - Click to Enable";
  toggleBtn.className = enabled ? "enabled" : "disabled";
}

toggleBtn.addEventListener("click", async () => {
  const { enabled = true } = await chrome.storage.local.get(["enabled"]);
  const nextState = !enabled;

  if (nextState) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }

  await chrome.storage.local.set({ enabled: nextState });
  await updateUI();
});

updateUI();
```

