        this.lastX = 0;
        this.lastY = 0;
        this.paused = false;

        this.stocks = [];
        this.stockMap = new Map();

        this.columns = 8;

        this.initData();
        this.resize();
        this.attachEvents();
        this.render();
        this.startMockStream();
      }

      initData() {
