          "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","AMD",
          "NFLX","INTC","ORCL","IBM","CRM","ADBE","QCOM","AVGO",
          "SHOP","UBER","LYFT","SNOW","PLTR","BABA","SAP","SONY",
          "JPM","GS","BAC","WFC","C","MS","V","MA"
        ];

        this.stocks = symbols.map((symbol, i) => {
          const price = 50 + Math.random() * 250;
          const change = (Math.random() - 0.5) * 4;
          return {
            id: i,
            symbol,
            price,
            change,
            volume: Math.floor(100000 + Math.random() * 5000000)
          };
        });

        this.stockMap = new Map(this.stocks.map(s => [s.symbol, s]));
      }

      attachEvents() {
        window.addEventListener("resize", () => this.resize());

        this.canvas.addEventListener("wheel", (e) => {
          e.preventDefault();
          const rect = this.canvas.getBoundingClientRect();
          const mx = e.clientX - rect.left;
          const my = e.clientY - rect.top;

          const worldX = (mx - this.offsetX) / this.zoom;
          const worldY = (my - this.offsetY) / this.zoom;

          const delta = -e.deltaY * 0.001;
          const nextZoom = Math.min(this.maxZoom, Math.max(this.minZoom, this.zoom * (1 + delta)));

          this.zoom = nextZoom;
          this.offsetX = mx - worldX * this.zoom;
          this.offsetY = my - worldY * this.zoom;

          this.render();
        }, { passive: false });

        this.canvas.addEventListener("mousedown", (e) => {
          this.isDragging = true;
          this.lastX = e.clientX;
          this.lastY = e.clientY;
        });

        window.addEventListener("mousemove", (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;

          if (this.isDragging) {
            this.offsetX += e.clientX - this.lastX;
            this.offsetY += e.clientY - this.lastY;
            this.lastX = e.clientX;
            this.lastY = e.clientY;
            this.render();
          } else {
            this.updateTooltip(x, y);
          }
        });

        window.addEventListener("mouseup", () => {
          this.isDragging = false;
        });

        this.canvas.addEventListener("mouseleave", () => {
          this.tooltip.style.display = "none";
        });

        document.getElementById("resetZoom").addEventListener("click", () => {
          this.zoom = 1;
          this.offsetX = 0;
          this.offsetY = 0;
          this.render();
        });

        document.getElementById("pauseBtn").addEventListener("click", (e) => {
          this.paused = !this.paused;
          e.target.textContent = this.paused ? "Resume Updates" : "Pause Updates";
          this.statusEl.textContent = this.paused ? "Updates paused" : "Streaming mock data";
        });

        document.getElementById("cellSize").addEventListener("input", (e) => {
          this.baseCellSize = Number(e.target.value);
          this.render();
        });
      }

      resize() {
        const rect = this.canvas.getBoundingClientRect();
        this.width = rect.width;
        this.height = rect.height;
        this.canvas.width = Math.floor(this.width * this.dpr);
        this.canvas.height = Math.floor(this.height * this.dpr);
        this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
        this.render();
      }

      startMockStream() {
        this.statusEl.textContent = "Streaming mock data";
        setInterval(() => {
          if (this.paused) return;

          const count = 1 + Math.floor(Math.random() * 4);
          for (let i = 0; i < count; i++) {
            const stock = this.stocks[Math.floor(Math.random() * this.stocks.length)];
            const delta = (Math.random() - 0.5) * 2.5;
            stock.price = Math.max(1, stock.price + delta);
            stock.change = Math.max(-12, Math.min(12, stock.change + delta * 0.25));
            stock.volume += Math.floor(Math.random() * 50000);
          }

          this.render();
        }, 500);
      }

      getCellAtScreenPoint(screenX, screenY) {
        const x = (screenX - this.offsetX) / this.zoom;
        const y = (screenY - this.offsetY) / this.zoom;
        const cell = this.baseCellSize;
        const col = Math.floor(x / cell);
        const row = Math.floor(y / cell);
        const index = row * this.columns + col;

        if (col < 0 || row < 0 || col >= this.columns || index >= this.stocks.length) {
          return null;
        }

        return {
          stock: this.stocks[index],
          row,
          col,
          x: col * cell,
          y: row * cell,
          size: cell
        };
      }

      updateTooltip(screenX, screenY) {
        const hit = this.getCellAtScreenPoint(screenX, screenY);
        if (!hit) {
          this.tooltip.style.display = "none";
          return;
        }

        const s = hit.stock;
        this.tooltip.innerHTML = `
          <strong>${s.symbol}</strong><br/>
          Price: $${s.price.toFixed(2)}<br/>
          Change: ${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}%<br/>
          Volume: ${s.volume.toLocaleString()}
        `;
        this.tooltip.style.display = "block";
        this.tooltip.style.left = `${screenX}px`;
        this.tooltip.style.top = `${screenY}px`;
      }

      colorForChange(change) {
        const clamped = Math.max(-10, Math.min(10, change));
        if (clamped >= 0) {
          const t = clamped / 10;
          const r = Math.floor(30 - t * 10);
          const g = Math.floor(80 + t * 175);
          const b = Math.floor(70 + t * 60);
          return `rgb(${r},${g},${b})`;
        } else {
          const t = Math.abs(clamped) / 10;
          const r = Math.floor(120 + t * 135);
          const g = Math.floor(40 + (1 - t) * 40);
          const b = Math.floor(50 + (1 - t) * 30);
          return `rgb(${r},${g},${b})`;
        }
      }

      render() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.width, this.height);

        ctx.save();
        ctx.translate(this.offsetX, this.offsetY);
        ctx.scale(this.zoom, this.zoom);

        const cell = this.baseCellSize;
        const padding = 2;

        this.stocks.forEach((stock, index) => {
          const row = Math.floor(index / this.columns);
          const col = index % this.columns;
          const x = col * cell;
          const y = row * cell;

          ctx.fillStyle = this.colorForChange(stock.change);
          ctx.fillRect(x + padding, y + padding, cell - padding * 2, cell - padding * 2);

          ctx.strokeStyle = "rgba(255,255,255,0.08)";
          ctx.strokeRect(x + padding, y + padding, cell - padding * 2, cell - padding * 2);

          ctx.fillStyle = "rgba(255,255,255,0.95)";
          ctx.font = "bold 12px Arial";
          ctx.fillText(stock.symbol, x + 8, y + 18);

          ctx.font = "11px Arial";
          ctx.fillText(`$${stock.price.toFixed(0)}`, x + 8, y + 34);

          ctx.fillStyle = "rgba(255,255,255,0.9)";
          ctx.fillText(
            `${stock.change >= 0 ? "+" : ""}${stock.change.toFixed(1)}%`,
            x + 8,
            y + 48
          );
        });

        ctx.restore();
      }
    }

    const canvas = document.getElementById("heatmap");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    new StockHeatmap(canvas, tooltip, statusEl);
  </script>
</body>
</html>
