## `main.ts`

```ts
type HeatmapPoint = {
  symbol: string;
  timeIndex: number;
  price: number;
};

type StockSeries = {
  symbol: string;
  prices: number[];
};

class StockHeatmap {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private tooltip: HTMLDivElement;
  private statusEl: HTMLElement;

  private width = 300;
  private height = 150;
  private dpr = window.devicePixelRatio || 1;

  private stocks: StockSeries[] = [];
  private timeSteps = 120;

  // View transform in "world" coordinates
  private offsetX = 60;
  private offsetY = 30;
  private scaleX = 10;
  private scaleY = 24;

  private isDragging = false;
  private lastMouseX = 0;
  private lastMouseY = 0;

  private hoveredCell: { row: number; col: number } | null = null;
  private animationFrameRequested = false;

  constructor(
    canvas: HTMLCanvasElement,
    tooltip: HTMLDivElement,
    statusEl: HTMLElement
  ) {
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("2D canvas context not supported");

    this.canvas = canvas;
    this.ctx = ctx;
    this.tooltip = tooltip;
    this.statusEl = statusEl;

    this.initData();
    this.attachEvents();
    this.resize();
    this.draw();
    this.startRealtimeFeed();
  }

  private initData() {
    const symbols = [
      "AAPL", "MSFT", "GOOG", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC",
      "ORCL", "CRM", "UBER", "SHOP", "SNOW",
      "PLTR", "ADBE", "PYPL", "QCOM", "AVGO"
    ];

    this.stocks = symbols.map((symbol, idx) => {
      const base = 80 + idx * 12 + Math.random() * 20;
      const prices: number[] = [];
      let current = base;
      for (let t = 0; t < this.timeSteps; t++) {
        current += (Math.random() - 0.5) * 3;
        prices.push(Math.max(1, current));
      }
      return { symbol, prices };
    });
  }

  private attachEvents() {
    window.addEventListener("resize", () => this.resize());

    this.canvas.addEventListener("wheel", (e) => this.onWheel(e), { passive: false });

    this.canvas.addEventListener("mousedown", (e) => {
      this.isDragging = true;
      this.lastMouseX = e.clientX;
      this.lastMouseY = e.clientY;
      this.canvas.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      this.isDragging = false;
      this.canvas.classList.remove("dragging");
    });

    window.addEventListener("mousemove", (e) => this.onMouseMove(e));

    this.canvas.addEventListener("mouseleave", () => {
      this.hoveredCell = null;
      this.tooltip.style.display = "none";
      this.requestDraw();
    });
  }

  private resize() {
    const rect = this.canvas.getBoundingClientRect();
    this.width = rect.width;
    this.height = rect.height;
    this.dpr = window.devicePixelRatio || 1;

    this.canvas.width = Math.floor(this.width * this.dpr);
    this.canvas.height = Math.floor(this.height * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);

    this.requestDraw();
  }

  private startRealtimeFeed() {
    this.statusEl.textContent = "Live updates: simulated stream";

    setInterval(() => {
      for (const stock of this.stocks) {
        const last = stock.prices[stock.prices.length - 1];
        const next = Math.max(1, last + (Math.random() - 0.5) * 4);
        stock.prices.push(next);
        if (stock.prices.length > this.timeSteps) {
          stock.prices.shift();
        }
      }
      this.requestDraw();
    }, 700);
  }

  private onWheel(e: WheelEvent) {
    e.preventDefault();

    const rect = this.canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const worldXBefore = (mouseX - this.offsetX) / this.scaleX;
    const worldYBefore = (mouseY - this.offsetY) / this.scaleY;

    const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
    this.scaleX = this.clamp(this.scaleX * zoomFactor, 4, 60);
    this.scaleY = this.clamp(this.scaleY * zoomFactor, 10, 80);

    this.offsetX = mouseX - worldXBefore * this.scaleX;
    this.offsetY = mouseY - worldYBefore * this.scaleY;

    this.requestDraw();
  }

  private onMouseMove(e: MouseEvent) {
    const rect = this.canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    if (this.isDragging) {
      this.offsetX += e.clientX - this.lastMouseX;
      this.offsetY += e.clientY - this.lastMouseY;
      this.lastMouseX = e.clientX;
      this.lastMouseY = e.clientY;
      this.requestDraw();
      return;
    }

    const hit = this.hitTest(mouseX, mouseY);
    this.hoveredCell = hit;

    if (hit) {
      const stock = this.stocks[hit.row];
      const price = stock.prices[hit.col];
      const prev = hit.col > 0 ? stock.prices[hit.col - 1] : price;
      const delta = price - prev;
      const timeLabel = `T-${this.timeSteps - 1 - hit.col}`;

      this.tooltip.innerHTML = `
        <strong>${stock.symbol}</strong><br/>
        Time: ${timeLabel}<br/>
        Price: $${price.toFixed(2)}<br/>
        Δ: <span style="color:${delta >= 0 ? "#22c55e" : "#ef4444"}">
          ${delta >= 0 ? "+" : ""}${delta.toFixed(2)}
        </span>
      `;
      this.tooltip.style.display = "block";
      this.tooltip.style.left = `${mouseX}px`;
      this.tooltip.style.top = `${mouseY}px`;
    } else {
      this.tooltip.style.display = "none";
    }

    this.requestDraw();
  }

  private hitTest(screenX: number, screenY: number): { row: number; col: number } | null {
    const col = Math.floor((screenX - this.offsetX) / this.scaleX);
    const row = Math.floor((screenY - this.offsetY) / this.scaleY);

    if (
      row >= 0 &&
      row < this.stocks.length &&
      col >= 0 &&
      col < this.timeSteps
    ) {
      return { row, col };
    }
    return null;
  }

  private requestDraw() {
    if (this.animationFrameRequested) return;
    this.animationFrameRequested = true;
    requestAnimationFrame(() => {
      this.animationFrameRequested = false;
      this.draw();
    });
  }

  private getGlobalMinMax(): { min: number; max: number } {
    let min = Infinity;
    let max = -Infinity;

    for (const stock of this.stocks) {
      for (const p of stock.prices) {
        if (p < min) min = p;
        if (p > max) max = p;
      }
    }

    return { min, max };
  }

  private colorForValue(value: number, min: number, max: number): string {
    const t = max === min ? 0.5 : (value - min) / (max - min);

    // Blue -> Green -> Red
    if (t < 0.5) {
      const k = t / 0.5;
      return this.lerpColor([59, 130, 246], [34, 197, 94], k);
    } else {
      const k = (t - 0.5) / 0.5;
      return this.lerpColor([34, 197, 94], [239, 68, 68], k);
    }
  }

  private lerpColor(a: number[], b: number[], t: number): string {
    const r = Math.round(a[0] + (b[0] - a[0]) * t);
    const g = Math.round(a[1] + (b[1] - a[1]) * t);
    const bl = Math.round(a[2] + (b[2] - a[2]) * t);
    return `rgb(${r},${g},${bl})`;
  }

  private draw() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);

    this.drawBackground();
    this.drawGrid();
    this.drawAxes();
    this.drawCells();
    this.drawHoverHighlight();
  }

  private drawBackground() {
    const ctx = this.ctx;
    const grad = ctx.createLinearGradient(0, 0, 0, this.height);
    grad.addColorStop(0, "#07111d");
    grad.addColorStop(1, "#030712");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, this.width, this.height);
  }

  private drawGrid() {
    const ctx = this.ctx;
    ctx.save();
    ctx.strokeStyle = "rgba(148, 163, 184, 0.08)";
    ctx.lineWidth = 1;

    // Vertical
    const startCol = Math.max(0, Math.floor((-this.offsetX) / this.scaleX));
    const endCol = Math.min(
      this.timeSteps,
      Math.ceil((this.width - this.offsetX) / this.scaleX)
    );

    for (let c = startCol; c <= endCol; c++) {
      const x = this.offsetX + c * this.scaleX;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, this.height);
      ctx.stroke();
    }

    // Horizontal
    const startRow = Math.max(0, Math.floor((-this.offsetY) / this.scaleY));
    const endRow = Math.min(
      this.stocks.length,
      Math.ceil((this.height - this.offsetY) / this.scaleY)
    );

    for (let r = startRow; r <= endRow; r++) {
      const y = this.offsetY + r * this.scaleY;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(this.width, y);
      ctx.stroke();
    }

    ctx.restore();
  }

  private drawAxes() {
    const ctx = this.ctx;
    ctx.save();
    ctx.fillStyle = "#cbd5e1";
    ctx.font = "12px Arial";
    ctx.textBaseline = "middle";

    // Row labels
    for (let r = 0; r < this.stocks.length; r++) {
      const y = this.offsetY + r * this.scaleY + this.scaleY / 2;
      if (y < -20 || y > this.height + 20) continue;

      ctx.fillStyle = "#94a3b8";
      ctx.fillText(this.stocks[r].symbol, 8, y);
    }

    // Time labels
    ctx.textAlign = "center";
    for (let c = 0; c < this.timeSteps; c += Math.max(1, Math.floor(40 / this.scaleX))) {
      const x = this.offsetX + c * this.scaleX + this.scaleX / 2;
      if (x < -30 || x > this.width + 30) continue;

      ctx.fillStyle = "#64748b";
      ctx.fillText(`${c}`, x, 14);
    }

    ctx.restore();
  }

  private drawCells() {
    const { min, max } = this.getGlobalMinMax();
    const ctx = this.ctx;

    const startCol = Math.max(0, Math.floor((-this.offsetX) / this.scaleX));
    const endCol = Math.min(
      this.timeSteps,
      Math.ceil((this.width - this.offsetX) / this.scaleX)
    );

    const startRow = Math.max(0, Math.floor((-this.offsetY) / this.scaleY));
    const endRow = Math.min(
      this.stocks.length,
      Math.ceil((this.height - this.offsetY) / this.scaleY)
    );

    for (let r = startRow; r < endRow; r++) {
      const stock = this.stocks[r];
      for (let c = startCol; c < endCol; c++) {
        const value = stock.prices[c];
        const x = this.offsetX + c * this.scaleX;
        const y = this.offsetY + r * this.scaleY;

        ctx.fillStyle = this.colorForValue(value, min, max);
        ctx.fillRect(x, y, this.scaleX, this.scaleY);
      }
    }
  }

  private drawHoverHighlight() {
    if (!this.hoveredCell) return;

    const { row, col } = this.hoveredCell;
    const x = this.offsetX + col * this.scaleX;
    const y = this.offsetY + row * this.scaleY;

    const ctx = this.ctx;
    ctx.save();
    ctx.strokeStyle = "#f8fafc";
    ctx.lineWidth = 2;
    ctx.strokeRect(x + 1, y + 1, this.scaleX - 2, this.scaleY - 2);
    ctx.restore();
  }

  private clamp(v: number, min: number, max: number) {
    return Math.max(min, Math.min(max, v));
  }
}

const canvas = document.getElementById("heatmap") as HTMLCanvasElement;
const tooltip = document.getElementById("tooltip") as HTMLDivElement;
const statusEl = document.getElementById("status") as HTMLElement;

new StockHeatmap(canvas, tooltip, statusEl);
