  <script>
    const tickers = [
      "AAPL", "MSFT", "AMZN", "GOOGL", "NVDA",
      "META", "TSLA", "AMD", "NFLX", "INTC",
      "CRM", "ORCL", "SHOP", "UBER", "PYPL"
    ];

    const state = {
      updateIntervalMs: 500,
      volatilityPct: 0.45,
      visibleWindow: 60,
      maxPoints: 180,
      timer: null,
      paused: false,
      step: 0,
      startTime: Date.now(),
      x: [],
      z: [],
      prices: [],
      opens: [],
      userZoomed: false
    };

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(n, min, max) {
      return Math.min(max, Math.max(min, n));
    }

    function formatTime(ts) {
      const d = new Date(ts);
      return d.toLocaleTimeString();
    }

    function seedData() {
      state.step = 0;
      state.startTime = Date.now();
      state.x = [];
      state.prices = tickers.map(() => rand(80, 450));
      state.opens = [...state.prices];
      state.z = tickers.map(() => []);
      state.userZoomed = false;

      for (let i = 0; i < state.visibleWindow; i++) {
        advanceSimulation(false);
      }
    }

    function advanceSimulation(appendX = true) {
      const ts = state.startTime + state.step * state.updateIntervalMs;
      const label = formatTime(ts);

      if (appendX) state.x.push(label);
      else state.x.push(label);

      const vol = state.volatilityPct / 100;
      for (let r = 0; r < tickers.length; r++) {
        const drift = rand(-vol, vol);
        const microTrend = Math.sin((state.step + r * 3) / 18) * vol * 0.15;
        const nextPrice = Math.max(1, state.prices[r] * (1 + drift + microTrend));
        state.prices[r] = nextPrice;

        const pctChange = ((nextPrice - state.opens[r]) / state.opens[r]) * 100;
        state.z[r].push(pctChange);

        if (state.z[r].length > state.maxPoints) {
          state.z[r].shift();
        }
      }

      if (state.x.length > state.maxPoints) {
        state.x.shift();
      }

      state.step++;
    }

    function currentVisibleRange() {
      const len = state.x.length;
      const start = Math.max(0, len - state.visibleWindow);
      return [state.x[start], state.x[len - 1]];
    }

    function buildTrace() {
      return {
        type: "heatmap",
        x: state.x,
        y: tickers,
        z: state.z,
        zmin: -5,
        zmax: 5,
        colorscale: [
          [0.0, "#7f1d1d"],
          [0.18, "#dc2626"],
          [0.5, "#111827"],
          [0.82, "#16a34a"],
          [1.0, "#14532d"]
        ],
        hovertemplate:
          "<b>%{y}</b><br>" +
          "Time: %{x}<br>" +
          "Change: %{z:.2f}%<extra></extra>",
        colorbar: {
          title: "% Change",
          titleside: "right",
          tickfont: { color: "#e5e7eb" },
          titlefont: { color: "#e5e7eb" }
        }
      };
    }

    function buildLayout() {
      return {
        paper_bgcolor: "#111827",
        plot_bgcolor: "#111827",
        font: { color: "#e5e7eb" },
        margin: { l: 80, r: 30, t: 20, b: 50 },
        xaxis: {
          title: "Time",
          gridcolor: "rgba(255,255,255,0.08)",
          zerolinecolor: "rgba(255,255,255,0.12)",
          rangeslider: { visible: false },
          fixedrange: false
        },
        yaxis: {
          title: "Ticker",
          autorange: "reversed",
          gridcolor: "rgba(255,255,255,0.08)",
          fixedrange: false
        },
        dragmode: "pan"
      };
    }

    function buildConfig() {
      return {
        responsive: true,
        scrollZoom: true,
        displayModeBar: true,
        modeBarButtonsToAdd: ["zoom2d", "pan2d", "zoomIn2d", "zoomOut2d", "resetScale2d"],
        displaylogo: false
      };
    }

    async function initChart() {
      seedData();
      await Plotly.newPlot("chart", [buildTrace()], buildLayout(), buildConfig());
      applyAutoWindow();
      bindZoomTracking();
      updateStatus();
    }

    function applyAutoWindow() {
      if (state.userZoomed || state.x.length === 0) return;
      const [start, end] = currentVisibleRange();
      Plotly.relayout("chart", {
        "xaxis.range": [start, end]
      });
    }

    function bindZoomTracking() {
      const chart = document.getElementById("chart");

      chart.on("plotly_relayout", (e) => {
        const zoomKeys = [
          "xaxis.range[0]", "xaxis.range[1]",
          "yaxis.range[0]", "yaxis.range[1]"
        ];

        if (e["xaxis.autorange"] || e["yaxis.autorange"]) {
          state.userZoomed = false;
          return;
        }

        if (zoomKeys.some(k => Object.prototype.hasOwnProperty.call(e, k))) {
          state.userZoomed = true;
        }
      });
    }

    function updateChart() {
      advanceSimulation(true);

      Plotly.react("chart", [buildTrace()], buildLayout(), buildConfig()).then(() => {
        applyAutoWindow();
      });

      updateStatus();
    }

    function updateStatus() {
      document.getElementById("lastUpdate").textContent =
        "Last update: " + new Date().toLocaleTimeString();
      document.getElementById("streamState").textContent =
        state.paused ? "Paused" : "Live";
      document.querySelector(".dot").style.background =
        state.paused ? "#eab308" : "#22c55e";
      document.querySelector(".dot").style.boxShadow =
        state.paused ? "0 0 12px #eab30888" : "0 0 12px #22c55e88";
    }

    function startTimer() {
      stopTimer();
      state.timer = setInterval(() => {
        if (!state.paused) updateChart();
      }, state.updateIntervalMs);
    }

    function stopTimer() {
      if (state.timer) clearInterval(state.timer);
      state.timer = null;
    }

    function resetZoom() {
      state.userZoomed = false;
      Plotly.relayout("chart", {
        "xaxis.autorange": true,
        "yaxis.autorange": "reversed"
      }).then(() => {
        applyAutoWindow();
      });
    }

    document.getElementById("intervalSelect").addEventListener("change", (e) => {
      state.updateIntervalMs = Number(e.target.value);
      startTimer();
    });

    document.getElementById("volatilityRange").addEventListener("input", (e) => {
      state.volatilityPct = Number(e.target.value);
      document.getElementById("volatilityLabel").textContent =
        state.volatilityPct.toFixed(2) + "%";
    });

    document.getElementById("windowSelect").addEventListener("change", (e) => {
      state.visibleWindow = Number(e.target.value);
      state.userZoomed = false;
      applyAutoWindow();
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      state.paused = !state.paused;
      e.target.textContent = state.paused ? "Resume" : "Pause";
      updateStatus();
    });

    document.getElementById("resetZoomBtn").addEventListener("click", resetZoom);

    document.getElementById("regenerateBtn").addEventListener("click", async () => {
      seedData();
      await Plotly.react("chart", [buildTrace()], buildLayout(), buildConfig());
      applyAutoWindow();
      updateStatus();
    });

    window.addEventListener("resize", () => {
      Plotly.Plots.resize("chart");
    });

    initChart();
    startTimer();
  </script>
</body>
