    let baseTime = Date.now();
    let symbols = [];
    let times = [];
    let data = [];
    let priceState = new Map();

    const color = d3.scaleLinear()
      .domain([-5, -2, 0, 2, 5])
      .range(["#8b1e3f", "#ff5c7a", "#7f8cb3", "#56d59f", "#19c37d"])
      .clamp(true);

    const root = svg.append("g");
    const defs = svg.append("defs");

    const plot = root.append("g").attr("class", "plot");
    const gridG = plot.append("g").attr("class", "grid");
    const cellsG = plot.append("g").attr("class", "cells");
    const axesG = root.append("g").attr("class", "axes");
    const xAxisG = axesG.append("g").attr("class", "axis x-axis");
    const yAxisG = axesG.append("g").attr("class", "axis y-axis");

    const clipId = "clip-heatmap";
    defs.append("clipPath")
      .attr("id", clipId)
      .append("rect");

    cellsG.attr("clip-path", `url(#${clipId})`);
    gridG.attr("clip-path", `url(#${clipId})`);

    const overlay = root.append("rect")
      .attr("fill", "transparent")
      .style("cursor", "grab");

    const crosshair = plot.append("g")
      .attr("class", "crosshair")
      .style("display", "none");

    const crossV = crosshair.append("line");
    const crossH = crosshair.append("line");

    function generateSymbols(count) {
      const pool = [
        "AAPL","MSFT","GOOG","AMZN","NVDA","META","TSLA","AMD","NFLX","INTC",
        "ORCL","CRM","PYPL","ADBE","UBER","SHOP","SQ","BABA","SONY","SAP",
        "QCOM","AVGO","CSCO","IBM","TXN","MU","PANW","SNOW","PLTR","ABNB",
        "DIS","PEP","KO","NKE","JPM","GS","V","MA","BAC","WMT",
        "COST","T","VZ","XOM","CVX","PFE","MRK","JNJ","BA","CAT",
        "DE","GE","F","GM","RIVN","LCID","ARM","ASML","TSM","NOW"
      ];
      return pool.slice(0, count);
    }

    function makeTimeBuckets(count) {
      const now = new Date();
      const arr = [];
      for (let i = count - 1; i >= 0; i--) {
        arr.push(new Date(now.getTime() - i * 60 * 1000));
      }
      return arr;
    }

    function initializeData() {
      const symbolCount = +controls.symbolCount.value;
      const bucketCount = +controls.timeBuckets.value;

      symbols = generateSymbols(symbolCount);
      times = makeTimeBuckets(bucketCount);
      data = [];
      priceState = new Map();

      symbols.forEach((symbol, sIdx) => {
        const base = 80 + Math.random() * 320;
        priceState.set(symbol, base);

        times.forEach((time, tIdx) => {
          const drift = (Math.random() - 0.5) * 2.5;
          const pct = Math.max(-5, Math.min(5, drift + Math.sin((tIdx / 6) + sIdx * 0.3) * 1.5));
          const price = base * (1 + pct / 100);

          if (tIdx === bucketCount - 1) {
            priceState.set(symbol, price);
          }

          data.push({
            symbol,
            time: new Date(time),
            pct,
            price
          });
        });
      });
    }

    function rollDataForward() {
      const nextTime = new Date(times[times.length - 1].getTime() + 60 * 1000);
      times = times.slice(1).concat(nextTime);

      const newData = [];
      const latestBySymbol = new Map();

      for (const d of data) {
        if (d.time.getTime() !== dataTimeMin()) {
          newData.push(d);
          latestBySymbol.set(d.symbol, d);
        }
      }

      for (const symbol of symbols) {
        const lastPoint = latestBySymbol.get(symbol);
        const lastPrice = priceState.get(symbol) ?? lastPoint?.price ?? (100 + Math.random() * 100);
        const shock = (Math.random() - 0.5) * 1.8;
        const momentum = (lastPoint?.pct ?? 0) * 0.35;
        const pct = Math.max(-5, Math.min(5, shock + momentum));
        const price = Math.max(1, lastPrice * (1 + pct / 100));

        priceState.set(symbol, price);
        newData.push({
          symbol,
          time: nextTime,
          pct,
          price
        });
      }

      data = newData;
    }

    function dataTimeMin() {
      return d3.min(data, d => d.time.getTime());
    }

    function getDimensions() {
      const rect = svg.node().parentElement.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;
    }

    function render() {
      getDimensions();

      svg.attr("viewBox", `0 0 ${width} ${height}`);
      root.attr("transform", `translate(${margin.left},${margin.top})`);

      overlay
        .attr("x", margin.left)
        .attr("y", margin.top)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      defs.select(`#${clipId} rect`)
        .attr("width", innerWidth)
        .attr("height", innerHeight);

      const xDomain = times.map(d => d.getTime());
      const yDomain = symbols;

      const x0 = d3.scaleBand()
        .domain(xDomain)
        .range([0, innerWidth])
        .paddingInner(0.03)
        .paddingOuter(0.01);

      const y0 = d3.scaleBand()
        .domain(yDomain)
        .range([0, innerHeight])
        .paddingInner(0.04)
        .paddingOuter(0.01);

      const zx = zoomTransform.rescaleX(
        d3.scaleLinear()
          .domain([0, innerWidth])
          .range([0, innerWidth])
      );

      const zy = zoomTransform.rescaleY(
        d3.scaleLinear()
          .domain([0, innerHeight])
          .range([0, innerHeight])
      );

      function cellX(d) {
        return zx(x0(d.time.getTime()));
      }

      function cellY(d) {
        return zy(y0(d.symbol));
      }

      function cellW() {
        return Math.max(0.5, zx(x0.bandwidth()) - zx(0));
      }

      function cellH() {
        return Math.max(0.5, zy(y0.bandwidth()) - zy(0));
      }

      const xAxisScale = d3.scaleTime()
        .domain(d3.extent(times))
        .range([0, innerWidth]);

      const yAxisScale = d3.scalePoint()
        .domain(symbols)
        .range([y0.bandwidth() / 2, innerHeight - y0.bandwidth() / 2]);

      const zxAxis = zoomTransform.rescaleX(xAxisScale);
      const zyAxis = zoomTransform.rescaleY(
        d3.scaleLinear()
          .domain([0, innerHeight])
          .range([0, innerHeight])
      );

      xAxisG
        .attr("transform", `translate(${margin.left},${margin.top + innerHeight})`)
        .call(
          d3.axisBottom(zxAxis)
            .ticks(Math.max(4, Math.floor(innerWidth / 120)))
            .tickFormat(d3.timeFormat("%H:%M"))
        );

      const visibleSymbols = symbols.filter(s => {
        const y = y0(s);
        const yy = zyAxis(y + y0.bandwidth() / 2);
        return yy >= -20 && yy <= innerHeight + 20;
      });

      const yVisibleScale = d3.scalePoint()
        .domain(visibleSymbols)
        .range([
          zyAxis((y0(visibleSymbols[0]) ?? 0) + y0.bandwidth() / 2),
          zyAxis((y0(visibleSymbols[visibleSymbols.length - 1]) ?? innerHeight) + y0.bandwidth() / 2)
        ]);

      yAxisG
        .attr("transform", `translate(${margin.left},${margin.top})`)
        .call(
          d3.axisLeft(yVisibleScale)
            .tickValues(visibleSymbols)
        );

      const xTicks = zxAxis.ticks(Math.max(4, Math.floor(innerWidth / 120)));
      const yTickVals = visibleSymbols;

      gridG.selectAll(".v-grid")
        .data(xTicks, d => +d)
        .join(
          enter => enter.append("line").attr("class", "v-grid"),
          update => update,
          exit => exit.remove()
        )
        .attr("x1", d => xAxisScale(d))
        .attr("x2", d => xAxisScale(d))
        .attr("y1", 0)
        .attr("y2", innerHeight)
        .attr("transform", `translate(${zoomTransform.x},0) scale(${zoomTransform.k},1)`);

      gridG.selectAll(".h-grid")
        .data(yTickVals, d => d)
        .join(
          enter => enter.append("line").attr("class", "h-grid"),
          update => update,
          exit => exit.remove()
        )
        .attr("x1", 0)
        .attr("x2", innerWidth)
        .attr("y1", d => cellY({ symbol: d, time: times[0] }) + cellH() / 2)
        .attr("y2", d => cellY({ symbol: d, time: times[0] }) + cellH() / 2);

      const visibleData = data.filter(d => {
        const x = cellX(d);
        const y = cellY(d);
        return x + cellW() >= 0 && x <= innerWidth && y + cellH() >= 0 && y <= innerHeight;
      });

      visibleCellsEl.textContent = visibleData.length.toLocaleString();

      cellsG.selectAll("rect.cell")
        .data(visibleData, d => `${d.symbol}-${d.time.getTime()}`)
        .join(
          enter => enter.append("rect")
            .attr("class", "cell")
            .on("mousemove", function(event, d) {
              const [mx, my] = d3.pointer(event, svg.node().parentElement);
              tooltip.style.opacity = 1;
              tooltip.style.left = `${mx + 14}px`;
              tooltip.style.top = `${my + 14}px`;
              tooltip.innerHTML = `
                <strong>${d.symbol}</strong><br>
                Time: ${d3.timeFormat("%Y-%m-%d %H:%M")(d.time)}<br>
                Price: $${d.price.toFixed(2)}<br>
                Change: <span style="color:${color(d.pct)}">${d.pct.toFixed(2)}%</span>
              `;
              hoveredValue.textContent = `${d.symbol} ${d.pct.toFixed(2)}%`;

              crosshair.style("display", null);
              crossV
                .attr("x1", cellX(d) + cellW()/2)
                .attr("x2", cellX(d) + cellW()/2)
                .attr("y1", 0)
                .attr("y2", innerHeight);
              crossH
                .attr("x1", 0)
                .attr("x2", innerWidth)
                .attr("y1", cellY(d) + cellH()/2)
                .attr("y2", cellY(d) + cellH()/2);
            })
            .on("mouseleave", function() {
              tooltip.style.opacity = 0;
              hoveredValue.textContent = "—";
              crosshair.style("display", "none");
            }),
          update => update,
          exit => exit.remove()
        )
        .attr("x", d => cellX(d))
        .attr("y", d => cellY(d))
        .attr("width", cellW())
        .attr("height", cellH())
        .attr("fill", d => color(d.pct));

      cellsG.selectAll("rect.cell")
        .append("title")
        .text(d => `${d.symbol} ${d3.timeFormat("%H:%M")(d.time)}  $${d.price.toFixed(2)}  ${d.pct.toFixed(2)}%`);
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .translateExtent([[0, 0], [width, height]])
      .extent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
      .on("zoom", (event) => {
        zoomTransform = event.transform;
        overlay.style("cursor", event.sourceEvent?.type === "mousedown" ? "grabbing" : "grab");
        render();
      });

    svg.call(zoom);

    function startTimer() {
      stopTimer();
      timer = setInterval(() => {
        if (!running) return;
        rollDataForward();
        render();
      }, +controls.tickMs.value);
    }

    function stopTimer() {
      if (timer) clearInterval(timer);
      timer = null;
    }

    function rebuild() {
      controls.symbolCountValue.textContent = controls.symbolCount.value;
      controls.timeBucketsValue.textContent = controls.timeBuckets.value;
      controls.tickMsValue.textContent = `${controls.tickMs.value}ms`;
      initializeData();
      render();
      startTimer();
    }

    controls.symbolCount.addEventListener("input", rebuild);
    controls.timeBuckets.addEventListener("input", rebuild);

    controls.tickMs.addEventListener("input", () => {
      controls.tickMsValue.textContent = `${controls.tickMs.value}ms`;
      startTimer();
    });

    controls.toggleRun.addEventListener("click", () => {
      running = !running;
      controls.toggleRun.textContent = running ? "Pause" : "Resume";
    });

    controls.resetZoom.addEventListener("click", () => {
      svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
    });

    controls.randomize.addEventListener("click", () => {
      initializeData();
      render();
    });

    window.addEventListener("resize", render);

    rebuild();
  </script>
</body>
</html>
```

Below is a complete client‑side implementation using <language>TypeScript</language> and the HTML5 Canvas API. It renders a stock‑style heatmap, supports:

- real‑time updates
- mouse wheel zoom
- click‑drag pan
- hover tooltip
- reset view
- simulated streaming data

You can paste this into a small Vite or plain TypeScript project.

