## 2. `main.ts`

```ts
type StockCell = {
  symbol: string;
  sector: string;
  price: number;
  changePct: number;
  volume: number;
};

type ViewState = {
  scale: number;
  offsetX: number;
  offsetY: number;
};

class StockHeatmap {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private tooltip: HTMLDivElement;
  private statusEl: HTMLElement;
  private dpr = Math.max(1, window.devicePixelRatio || 1);

  private data: StockCell[] = [];
  private sectors = [
    "Tech",
    "Finance",
    "Energy",
    "Healthcare",
    "Retail",
    "Industrial",
  ];

  private animationFrame = 0;

  private view: ViewState = {
    scale: 1,
    offsetX: 0,
    offsetY: 0,
  };

  private readonly minScale = 0.5;
  private readonly maxScale = 4;

  private isDragging = false;
  private lastMouseX = 0;
  private lastMouseY = 0;
  private mouseX = 0;
  private mouseY = 0;

  private hoveredIndex: number | null = null;

  private baseCellWidth = 110;
  private baseCellHeight = 70;
  private gap = 8;
  private headerHeight = 28;

  constructor(
    canvas: HTMLCanvasElement,
    tooltip: HTMLDivElement,
    statusEl: HTMLElement
  ) {
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("Canvas 2D context not supported");

    this.canvas = canvas;
    this.ctx = ctx;
    this.tooltip = tooltip;
    this.statusEl = statusEl;

    this.data = this.generateInitialData(180);

    this.bindEvents();
    this.resize();
    this.centerView();
    this.startRealtimeFeed();
    this.renderLoop();
  }

  private bindEvents() {
    window.addEventListener("resize", this.resize);

    this.canvas.addEventListener("wheel", this.onWheel, { passive: false });
    this.canvas.addEventListener("mousedown", this.onMouseDown);
    window.addEventListener("mousemove", this.onMouseMove);
    window.addEventListener("mouseup", this.onMouseUp);
    this.canvas.addEventListener("mouseleave", this.onMouseLeave);
  }

  private resize = () => {
    const rect = this.canvas.getBoundingClientRect();
    this.dpr = Math.max(1, window.devicePixelRatio || 1);

    this.canvas.width = Math.floor(rect.width * this.dpr);
    this.canvas.height = Math.floor(rect.height * this.dpr);

    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.requestRender();
  };

  private centerView() {
    const cols = this.getColumnCount();
    const rows = Math.ceil(this.data.length / cols);

    const contentWidth = cols * (this.baseCellWidth + this.gap) - this.gap;
    const contentHeight =
      rows * (this.baseCellHeight + this.gap) - this.gap + this.headerHeight;

    const rect = this.canvas.getBoundingClientRect();

    this.view.scale = 1;
    this.view.offsetX = Math.max(20, (rect.width - contentWidth) / 2);
    this.view.offsetY = Math.max(20, (rect.height - contentHeight) / 2);
  }

  private getColumnCount() {
    return 12;
  }

  private generateInitialData(count: number): StockCell[] {
    const symbols = [
      "AAPL", "MSFT", "GOOG", "AMZN", "NVDA", "META", "JPM", "BAC", "XOM", "CVX",
      "PFE", "JNJ", "WMT", "COST", "CAT", "BA", "TSLA", "NFLX", "AMD", "INTC",
      "GS", "MS", "UNH", "MRK", "KO", "PEP", "GE", "HON", "DIS", "ORCL"
    ];

    const out: StockCell[] = [];
    for (let i = 0; i < count; i++) {
      const base = symbols[i % symbols.length] + (i >= symbols.length ? i : "");
      out.push({
        symbol: base,
        sector: this.sectors[i % this.sectors.length],
        price: 20 + Math.random() * 480,
        changePct: (Math.random() - 0.5) * 8,
        volume: 100_000 + Math.random() * 20_000_000,
      });
    }
    return out;
  }

  private startRealtimeFeed() {
    this.statusEl.textContent = "Live updates: simulated stream";

    setInterval(() => {
      const updatesPerTick = 8 + Math.floor(Math.random() * 10);

      for (let i = 0; i < updatesPerTick; i++) {
        const idx = Math.floor(Math.random() * this.data.length);
        const item = this.data[idx];

        const drift = (Math.random() - 0.5) * 0.02;
        item.price = Math.max(1, item.price * (1 + drift));

        const changeDrift = (Math.random() - 0.5) * 0.9;
        item.changePct = Math.max(-15, Math.min(15, item.changePct + changeDrift));

        item.volume += Math.random() * 250_000;
      }

      this.requestRender();
    }, 500);
  }

  private onWheel = (e: WheelEvent) => {
    e.preventDefault();

    const rect = this.canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const oldScale = this.view.scale;
    const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
    const newScale = Math.min(this.maxScale, Math.max(this.minScale, oldScale * zoomFactor));

    if (newScale === oldScale) return;

    const worldX = (mouseX - this.view.offsetX) / oldScale;
    const worldY = (mouseY - this.view.offsetY) / oldScale;

    this.view.scale = newScale;
    this.view.offsetX = mouseX - worldX * newScale;
    this.view.offsetY = mouseY - worldY * newScale;

    this.requestRender();
  };

  private onMouseDown = (e: MouseEvent) => {
    this.isDragging = true;
    this.lastMouseX = e.clientX;
    this.lastMouseY = e.clientY;
    this.canvas.classList.add("dragging");
  };

  private onMouseMove = (e: MouseEvent) => {
    const rect = this.canvas.getBoundingClientRect();
    this.mouseX = e.clientX - rect.left;
    this.mouseY = e.clientY - rect.top;

    if (this.isDragging) {
      const dx = e.clientX - this.lastMouseX;
      const dy = e.clientY - this.lastMouseY;
      this.view.offsetX += dx;
      this.view.offsetY += dy;
      this.lastMouseX = e.clientX;
      this.lastMouseY = e.clientY;
      this.hideTooltip();
      this.requestRender();
      return;
    }

    this.updateHover();
  };

  private onMouseUp = () => {
    this.isDragging = false;
    this.canvas.classList.remove("dragging");
  };

  private onMouseLeave = () => {
    this.hoveredIndex = null;
    this.hideTooltip();
    this.requestRender();
  };

  public resetView = () => {
    this.centerView();
    this.requestRender();
  };

  private requestRender() {
    if (!this.animationFrame) {
      this.animationFrame = requestAnimationFrame(() => {
        this.animationFrame = 0;
        this.draw();
      });
    }
  }

  private renderLoop() {
    this.draw();
  }

  private worldToScreen(x: number, y: number) {
    return {
      x: x * this.view.scale + this.view.offsetX,
      y: y * this.view.scale + this.view.offsetY,
    };
  }

  private screenToWorld(x: number, y: number) {
    return {
      x: (x - this.view.offsetX) / this.view.scale,
      y: (y - this.view.offsetY) / this.view.scale,
    };
  }

  private getCellRect(index: number) {
    const cols = this.getColumnCount();
    const col = index % cols;
    const row = Math.floor(index / cols);

    const x = col * (this.baseCellWidth + this.gap);
    const y = row * (this.baseCellHeight + this.gap) + this.headerHeight;

    return {
      x,
      y,
      width: this.baseCellWidth,
      height: this.baseCellHeight,
    };
  }

  private getColor(changePct: number) {
    const capped = Math.max(-10, Math.min(10, changePct));
    const t = (capped + 10) / 20;

    const red = { r: 180, g: 42, b: 42 };
    const neutral = { r: 66, g: 75, b: 102 };
    const green = { r: 29, g: 160, b: 98 };

    const lerp = (a: number, b: number, p: number) => a + (b - a) * p;

    if (t < 0.5) {
      const p = t / 0.5;
      return `rgb(${lerp(red.r, neutral.r, p)}, ${lerp(red.g, neutral.g, p)}, ${lerp(red.b, neutral.b, p)})`;
    } else {
      const p = (t - 0.5) / 0.5;
      return `rgb(${lerp(neutral.r, green.r, p)}, ${lerp(neutral.g, green.g, p)}, ${lerp(neutral.b, green.b, p)})`;
    }
  }

  private updateHover() {
    const p = this.screenToWorld(this.mouseX, this.mouseY);
    let found: number | null = null;

    for (let i = 0; i < this.data.length; i++) {
      const r = this.getCellRect(i);
      const inside =
        p.x >= r.x &&
        p.x <= r.x + r.width &&
        p.y >= r.y &&
        p.y <= r.y + r.height;

      if (inside) {
        found = i;
        break;
      }
    }

    this.hoveredIndex = found;

    if (found !== null) {
      const d = this.data[found];
      this.tooltip.style.display = "block";
      this.tooltip.style.left = `${this.mouseX}px`;
      this.tooltip.style.top = `${this.mouseY}px`;
      this.tooltip.innerHTML = `
        <strong>${d.symbol}</strong><br/>
        Sector: ${d.sector}<br/>
        Price: $${d.price.toFixed(2)}<br/>
        Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%<br/>
        Volume: ${Math.round(d.volume).toLocaleString()}
      `;
    } else {
      this.hideTooltip();
    }

    this.requestRender();
  }

  private hideTooltip() {
    this.tooltip.style.display = "none";
  }

  private draw() {
    const ctx = this.ctx;
    const rect = this.canvas.getBoundingClientRect();

    ctx.clearRect(0, 0, rect.width, rect.height);

    // Background
    const bg = ctx.createLinearGradient(0, 0, 0, rect.height);
    bg.addColorStop(0, "#0b1020");
    bg.addColorStop(1, "#0e1428");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, rect.width, rect.height);

    // World layer
    ctx.save();
    ctx.translate(this.view.offsetX, this.view.offsetY);
    ctx.scale(this.view.scale, this.view.scale);

    // Header
    ctx.fillStyle = "#c8d4f0";
    ctx.font = "bold 16px sans-serif";
    ctx.fillText("Client-side Stock Heatmap", 0, 18);

    for (let i = 0; i < this.data.length; i++) {
      const d = this.data[i];
      const r = this.getCellRect(i);

      ctx.fillStyle = this.getColor(d.changePct);
      ctx.fillRect(r.x, r.y, r.width, r.height);

      ctx.strokeStyle = i === this.hoveredIndex ? "#ffffff" : "rgba(255,255,255,0.12)";
      ctx.lineWidth = i === this.hoveredIndex ? 2 : 1;
      ctx.strokeRect(r.x, r.y, r.width, r.height);

      ctx.fillStyle = "#f7fbff";
      ctx.font = "bold 14px sans-serif";
      ctx.fillText(d.symbol, r.x + 8, r.y + 18);

      ctx.fillStyle = "rgba(247,251,255,0.92)";
      ctx.font = "12px sans-serif";
      ctx.fillText(`$${d.price.toFixed(2)}`, r.x + 8, r.y + 38);

      const changeText = `${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`;
      ctx.fillText(changeText, r.x + 8, r.y + 56);
    }

    ctx.restore();

    // Overlay help text
    ctx.fillStyle = "rgba(230,238,248,0.85)";
    ctx.font = "12px sans-serif";
    ctx.fillText("Wheel: zoom • Drag: pan • Hover: details", 16, rect.height - 16);
  }
}

const canvas = document.getElementById("heatmapCanvas") as HTMLCanvasElement;
const tooltip = document.getElementById("tooltip") as HTMLDivElement;
const statusEl = document.getElementById("status") as HTMLElement;
const resetBtn = document.getElementById("resetBtn") as HTMLButtonElement;

const heatmap = new StockHeatmap(canvas, tooltip, statusEl);
resetBtn.addEventListener("click", heatmap.resetView);
