## `app.ts`

```ts
type StockCell = {
  symbol: string;
  price: number;
  changePct: number;
  volume: number;
  sector: string;
};

type ViewState = {
  scale: number;
  offsetX: number;
  offsetY: number;
};

class StockHeatmap {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private tooltip: HTMLDivElement;
  private resetViewBtn: HTMLButtonElement;

  private stocks: StockCell[] = [];
  private rows = 20;
  private cols = 20;
  private baseCellWidth = 90;
  private baseCellHeight = 60;

  private view: ViewState = {
    scale: 1,
    offsetX: 0,
    offsetY: 0
  };

  private dragging = false;
  private lastMouseX = 0;
  private lastMouseY = 0;
  private hoveredCellIndex: number | null = null;
  private animationFrame = 0;

  constructor() {
    const canvas = document.getElementById("heatmapCanvas") as HTMLCanvasElement | null;
    const tooltip = document.getElementById("tooltip") as HTMLDivElement | null;
    const resetViewBtn = document.getElementById("resetViewBtn") as HTMLButtonElement | null;

    if (!canvas || !tooltip || !resetViewBtn) {
      throw new Error("Missing required DOM elements.");
    }

    const ctx = canvas.getContext("2d");
    if (!ctx) {
      throw new Error("2D canvas context not supported.");
    }

    this.canvas = canvas;
    this.ctx = ctx;
    this.tooltip = tooltip;
    this.resetViewBtn = resetViewBtn;

    this.generateInitialData();
    this.attachEvents();
    this.resizeCanvas();
    this.centerView();
    this.startRealtimeUpdates();
    this.render();
  }

  private generateInitialData() {
    const sectors = ["Tech", "Finance", "Energy", "Healthcare", "Retail", "Industrial"];
    const symbols = this.generateTickerSymbols(this.rows * this.cols);

    this.stocks = symbols.map((symbol, index) => ({
      symbol,
      price: 50 + Math.random() * 450,
      changePct: -5 + Math.random() * 10,
      volume: 100_000 + Math.random() * 5_000_000,
      sector: sectors[index % sectors.length]
    }));
  }

  private generateTickerSymbols(count: number): string[] {
    const result: string[] = [];
    const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    while (result.length < count) {
      const len = 3 + Math.floor(Math.random() * 2);
      let symbol = "";
      for (let i = 0; i < len; i++) {
        symbol += letters[Math.floor(Math.random() * letters.length)];
      }
      result.push(symbol);
    }

    return result;
  }

  private attachEvents() {
    window.addEventListener("resize", this.resizeCanvas);

    this.canvas.addEventListener("mousedown", (e) => {
      this.dragging = true;
      this.lastMouseX = e.clientX;
      this.lastMouseY = e.clientY;
    });

    window.addEventListener("mouseup", () => {
      this.dragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      const rect = this.canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      if (this.dragging) {
        const dx = e.clientX - this.lastMouseX;
        const dy = e.clientY - this.lastMouseY;
        this.view.offsetX += dx;
        this.view.offsetY += dy;
        this.lastMouseX = e.clientX;
        this.lastMouseY = e.clientY;
        this.scheduleRender();
      }

      this.updateHover(mouseX, mouseY, e.clientX, e.clientY);
    });

    this.canvas.addEventListener(
      "wheel",
      (e) => {
        e.preventDefault();

        const rect = this.canvas.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        const worldBefore = this.screenToWorld(mouseX, mouseY);

        const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
        const nextScale = Math.min(4, Math.max(0.4, this.view.scale * zoomFactor));
        this.view.scale = nextScale;

        const worldAfter = this.screenToWorld(mouseX, mouseY);
        this.view.offsetX += (worldAfter.x - worldBefore.x) * this.view.scale;
        this.view.offsetY += (worldAfter.y - worldBefore.y) * this.view.scale;

        this.scheduleRender();
      },
      { passive: false }
    );

    this.canvas.addEventListener("mouseleave", () => {
      this.hoveredCellIndex = null;
      this.tooltip.classList.add("hidden");
      this.scheduleRender();
    });

    this.resetViewBtn.addEventListener("click", () => {
      this.view.scale = 1;
      this.centerView();
      this.scheduleRender();
    });
  }

  private resizeCanvas = () => {
    const dpr = window.devicePixelRatio || 1;
    const rect = this.canvas.parentElement!.getBoundingClientRect();
    this.canvas.width = Math.floor(rect.width * dpr);
    this.canvas.height = Math.floor(rect.height * dpr);
    this.canvas.style.width = `${rect.width}px`;
    this.canvas.style.height = `${rect.height}px`;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.scheduleRender();
  };

  private centerView() {
    const viewportWidth = this.canvas.clientWidth;
    const viewportHeight = this.canvas.clientHeight;
    const heatmapWidth = this.cols * this.baseCellWidth;
    const heatmapHeight = this.rows * this.baseCellHeight;

    this.view.offsetX = (viewportWidth - heatmapWidth * this.view.scale) / 2;
    this.view.offsetY = (viewportHeight - heatmapHeight * this.view.scale) / 2;
  }

  private startRealtimeUpdates() {
    setInterval(() => {
      const updatesPerTick = 8;

      for (let i = 0; i < updatesPerTick; i++) {
        const idx = Math.floor(Math.random() * this.stocks.length);
        const stock = this.stocks[idx];

        const drift = (Math.random() - 0.5) * 0.8;
        stock.changePct = Math.max(-5, Math.min(5, stock.changePct + drift));

        const priceMove = stock.price * (drift / 100);
        stock.price = Math.max(1, stock.price + priceMove);

        const volumeDrift = (Math.random() - 0.2) * 25000;
        stock.volume = Math.max(0, stock.volume + volumeDrift);
      }

      this.scheduleRender();
    }, 700);
  }

  private scheduleRender() {
    if (this.animationFrame) return;
    this.animationFrame = requestAnimationFrame(() => {
      this.animationFrame = 0;
      this.render();
    });
  }

  private screenToWorld(screenX: number, screenY: number) {
    return {
      x: (screenX - this.view.offsetX) / this.view.scale,
      y: (screenY - this.view.offsetY) / this.view.scale
    };
  }

  private updateHover(mouseX: number, mouseY: number, clientX: number, clientY: number) {
    const world = this.screenToWorld(mouseX, mouseY);
    const col = Math.floor(world.x / this.baseCellWidth);
    const row = Math.floor(world.y / this.baseCellHeight);

    if (row >= 0 && row < this.rows && col >= 0 && col < this.cols) {
      const index = row * this.cols + col;
      this.hoveredCellIndex = index;

      const stock = this.stocks[index];
      this.tooltip.innerHTML = `
        <strong>${stock.symbol}</strong><br/>
        Price: $${stock.price.toFixed(2)}<br/>
        Change: ${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%<br/>
        Volume: ${Math.round(stock.volume).toLocaleString()}<br/>
        Sector: ${stock.sector}
      `;
      this.tooltip.style.left = `${clientX}px`;
      this.tooltip.style.top = `${clientY}px`;
      this.tooltip.classList.remove("hidden");
    } else {
      this.hoveredCellIndex = null;
      this.tooltip.classList.add("hidden");
    }

    this.scheduleRender();
  }

  private colorForChange(changePct: number): string {
    const clamped = Math.max(-5, Math.min(5, changePct));

    if (clamped < 0) {
      const t = (clamped + 5) / 5;
      const r = Math.round(185 + (55 - 185) * t);
      const g = Math.round(28 + (65 - 28) * t);
      const b = Math.round(28 + (81 - 28) * t);
      return `rgb(${r}, ${g}, ${b})`;
    } else {
      const t = clamped / 5;
      const r = Math.round(55 + (21 - 55) * t);
      const g = Math.round(65 + (128 - 65) * t);
      const b = Math.round(81 + (61 - 81) * t);
      return `rgb(${r}, ${g}, ${b})`;
    }
  }

  private render() {
    const ctx = this.ctx;
    const width = this.canvas.clientWidth;
    const height = this.canvas.clientHeight;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = "#0b1020";
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    ctx.translate(this.view.offsetX, this.view.offsetY);
    ctx.scale(this.view.scale, this.view.scale);

    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        const index = row * this.cols + col;
        const stock = this.stocks[index];

        const x = col * this.baseCellWidth;
        const y = row * this.baseCellHeight;
        const w = this.baseCellWidth - 2;
        const h = this.baseCellHeight - 2;

        ctx.fillStyle = this.colorForChange(stock.changePct);
        ctx.fillRect(x, y, w, h);

        if (this.hoveredCellIndex === index) {
          ctx.strokeStyle = "#f8fafc";
          ctx.lineWidth = 2 / this.view.scale;
          ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
        }

        const fontSize = Math.max(10, Math.min(16, 13 / this.view.scale + 4));
        ctx.fillStyle = "#f8fafc";
        ctx.font = `600 ${fontSize}px Inter, Arial, sans-serif`;
        ctx.fillText(stock.symbol, x + 8, y + 18);

        ctx.font = `${fontSize - 1}px Inter, Arial, sans-serif`;
        ctx.fillText(`$${stock.price.toFixed(2)}`, x + 8, y + 35);
        ctx.fillText(
          `${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%`,
          x + 8,
          y + 50
        );
      }
    }

    ctx.restore();
  }
}

new StockHeatmap();
```

