## 6) `src/main.ts`

```ts
import * as d3 from "d3";

type Stock = {
  symbol: string;
  sector: string;
  price: number;
  changePct: number;
  volume: number;
};

const sectors = [
  "Technology",
  "Finance",
  "Healthcare",
  "Energy",
  "Consumer",
  "Industrial"
];

const symbols = [
  "AAPL", "MSFT", "GOOG", "AMZN", "NVDA", "META",
  "JPM", "BAC", "GS", "MS", "V", "MA",
  "JNJ", "PFE", "MRK", "ABBV", "LLY", "UNH",
  "XOM", "CVX", "SLB", "COP", "EOG", "MPC",
  "PG", "KO", "PEP", "WMT", "COST", "HD",
  "CAT", "GE", "HON", "UPS", "BA", "DE"
];

function generateInitialStocks(): Stock[] {
  return symbols.map((symbol, i) => ({
    symbol,
    sector: sectors[Math.floor(i / 6)] ?? "Other",
    price: +(50 + Math.random() * 450).toFixed(2),
    changePct: +(Math.random() * 6 - 3).toFixed(2),
    volume: Math.floor(100_000 + Math.random() * 5_000_000)
  }));
}

let stocks = generateInitialStocks();

const chartEl = document.getElementById("chart");
if (!chartEl) {
  throw new Error("Chart container not found");
}

const width = chartEl.clientWidth || window.innerWidth;
const height = chartEl.clientHeight || window.innerHeight - 60;

const svg = d3
  .select("#chart")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .style("display", "block")
  .style("background", "#0b1020");

const rootGroup = svg.append("g");
const contentGroup = rootGroup.append("g");

const tooltip = d3
  .select("#chart")
  .append("div")
  .attr("class", "tooltip")
  .style("opacity", 0);

const colorScale = d3
  .scaleLinear<string>()
  .domain([-5, 0, 5])
  .range(["#b91c1c", "#6b7280", "#15803d"])
  .clamp(true);

const padding = 10;
const cols = 6;

function layoutData(data: Stock[]) {
  const tileWidth = 160;
  const tileHeight = 100;

  return data.map((d, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    return {
      ...d,
      x: padding + col * (tileWidth + padding),
      y: padding + row * (tileHeight + padding),
      width: tileWidth,
      height: tileHeight
    };
  });
}

function render(data: Stock[]) {
  const laidOut = layoutData(data);

  const tiles = contentGroup
    .selectAll<SVGGElement, ReturnType<typeof layoutData>[number]>(".stock-tile")
    .data(laidOut, (d: any) => d.symbol);

  const enter = tiles
    .enter()
    .append("g")
    .attr("class", "stock-tile");

  enter
    .append("rect")
    .attr("class", "tile")
    .attr("rx", 10)
    .attr("ry", 10)
    .attr("width", d => d.width)
    .attr("height", d => d.height)
    .attr("fill", d => colorScale(d.changePct))
    .on("mousemove", function (event, d) {
      tooltip
        .style("opacity", 1)
        .style("left", `${event.offsetX + 12}px`)
        .style("top", `${event.offsetY + 12}px`)
        .html(`
          <div><strong>${d.symbol}</strong></div>
          <div>Sector: ${d.sector}</div>
          <div>Price: $${d.price.toFixed(2)}</div>
          <div>Change: ${d.changePct.toFixed(2)}%</div>
          <div>Volume: ${d.volume.toLocaleString()}</div>
        `);
    })
    .on("mouseleave", () => {
      tooltip.style("opacity", 0);
    });

  enter
    .append("text")
    .attr("class", "tile-label")
    .attr("x", 12)
    .attr("y", 26)
    .text(d => d.symbol);

  enter
    .append("text")
    .attr("class", "tile-subtext")
    .attr("x", 12)
    .attr("y", 48)
    .text(d => `$${d.price.toFixed(2)}`);

  enter
    .append("text")
    .attr("class", "tile-subtext change")
    .attr("x", 12)
    .attr("y", 68)
    .text(d => `${d.changePct.toFixed(2)}%`);

  const merged = enter.merge(tiles as any);

  merged
    .transition()
    .duration(400)
    .attr("transform", d => `translate(${d.x}, ${d.y})`);

  merged
    .select<SVGRectElement>("rect")
    .transition()
    .duration(400)
    .attr("fill", d => colorScale(d.changePct));

  merged
    .select<SVGTextElement>(".tile-subtext")
    .text(d => `$${d.price.toFixed(2)}`);

  merged
    .select<SVGTextElement>("text.change")
    .text(d => `${d.changePct.toFixed(2)}%`);

  tiles.exit().remove();
}

function simulateRealtimeUpdates() {
  setInterval(() => {
    stocks = stocks.map(stock => {
      const drift = (Math.random() - 0.5) * 1.2;
      const nextChange = Math.max(-8, Math.min(8, stock.changePct + drift));
      const priceDelta = stock.price * (drift / 100);

      return {
        ...stock,
        price: +(stock.price + priceDelta).toFixed(2),
        changePct: +nextChange.toFixed(2),
        volume: stock.volume + Math.floor(Math.random() * 50000)
      };
    });

    render(stocks);
  }, 1000);
}

const zoom = d3
  .zoom<SVGSVGElement, unknown>()
  .scaleExtent([0.5, 4])
  .on("zoom", (event) => {
    rootGroup.attr("transform", event.transform.toString());
  });

svg.call(zoom);

function resize() {
  const newWidth = chartEl!.clientWidth;
  const newHeight = chartEl!.clientHeight;
  svg.attr("width", newWidth).attr("height", newHeight);
}

window.addEventListener("resize", resize);

render(stocks);
simulateRealtimeUpdates();
```

