### `StockHeatmap.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import * as d3 from "d3";

type StockCell = {
  symbol: string;
  sector: string;
  row: number;
  col: number;
  price: number;
  changePct: number;
};

const ROWS = 12;
const COLS = 12;
const CELL_SIZE = 45;
const WIDTH = COLS * CELL_SIZE;
const HEIGHT = ROWS * CELL_SIZE;

const SECTORS = [
  "Tech",
  "Finance",
  "Energy",
  "Healthcare",
  "Retail",
  "Industrial",
];

function createInitialData(): StockCell[] {
  const cells: StockCell[] = [];
  let idx = 0;

  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      cells.push({
        symbol: `STK${String(idx + 1).padStart(3, "0")}`,
        sector: SECTORS[idx % SECTORS.length],
        row,
        col,
        price: 50 + Math.random() * 200,
        changePct: (Math.random() - 0.5) * 4,
      });
      idx++;
    }
  }

  return cells;
}

function updateData(prev: StockCell[]): StockCell[] {
  return prev.map((cell) => {
    const drift = (Math.random() - 0.5) * 1.2;
    const nextChange = Math.max(-10, Math.min(10, cell.changePct + drift));
    const nextPrice = Math.max(1, cell.price * (1 + drift / 100));

    return {
      ...cell,
      price: nextPrice,
      changePct: nextChange,
    };
  });
}

export default function StockHeatmap() {
  const [data, setData] = useState<StockCell[]>(createInitialData);
  const [tooltip, setTooltip] = useState<{
    x: number;
    y: number;
    cell: StockCell;
  } | null>(null);

  const svgRef = useRef<SVGSVGElement | null>(null);
  const groupRef = useRef<SVGGElement | null>(null);

  const colorScale = useMemo(() => {
    return d3
      .scaleLinear<string>()
      .domain([-10, 0, 10])
      .range(["#b91c1c", "#f3f4f6", "#15803d"]);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setData((prev) => updateData(prev));
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!svgRef.current || !groupRef.current) return;

    const svg = d3.select(svgRef.current);
    const group = d3.select(groupRef.current);

    const zoom = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.5, 8])
      .translateExtent([
        [-WIDTH, -HEIGHT],
        [WIDTH * 2, HEIGHT * 2],
      ])
      .on("zoom", (event) => {
        group.attr("transform", event.transform.toString());
      });

    svg.call(zoom);
  }, []);

  return (
    <div style={{ position: "relative", width: "fit-content" }}>
      <svg
        ref={svgRef}
        width={900}
        height={650}
        style={{
          border: "1px solid #d1d5db",
          background: "#ffffff",
          cursor: "grab",
        }}
      >
        <g ref={groupRef} transform="translate(40,40)">
          {data.map((cell) => {
            const x = cell.col * CELL_SIZE;
            const y = cell.row * CELL_SIZE;
            const fill = colorScale(cell.changePct);

            return (
              <g key={cell.symbol} transform={`translate(${x},${y})`}>
                <rect
                  width={CELL_SIZE - 2}
                  height={CELL_SIZE - 2}
                  rx={4}
                  fill={fill}
                  stroke="#d1d5db"
                  onMouseMove={(e) => {
                    setTooltip({
                      x: e.clientX + 12,
                      y: e.clientY + 12,
                      cell,
                    });
                  }}
                  onMouseLeave={() => setTooltip(null)}
                />
                <text
                  x={(CELL_SIZE - 2) / 2}
                  y={17}
                  textAnchor="middle"
                  fontSize={10}
                  fontWeight={700}
                  fill="#111827"
                  pointerEvents="none"
                >
                  {cell.symbol}
                </text>
                <text
                  x={(CELL_SIZE - 2) / 2}
                  y={32}
                  textAnchor="middle"
                  fontSize={10}
                  fill="#111827"
                  pointerEvents="none"
                >
                  {cell.changePct >= 0 ? "+" : ""}
                  {cell.changePct.toFixed(2)}%
                </text>
              </g>
            );
          })}
        </g>
      </svg>

      {tooltip && (
        <div
          style={{
            position: "fixed",
            left: tooltip.x,
            top: tooltip.y,
            background: "rgba(17, 24, 39, 0.95)",
            color: "white",
            padding: "8px 10px",
            borderRadius: 6,
            fontSize: 12,
            pointerEvents: "none",
            boxShadow: "0 4px 14px rgba(0,0,0,0.25)",
            whiteSpace: "nowrap",
          }}
        >
          <div><strong>{tooltip.cell.symbol}</strong></div>
          <div>Sector: {tooltip.cell.sector}</div>
          <div>Price: ${tooltip.cell.price.toFixed(2)}</div>
          <div>
            Change: {tooltip.cell.changePct >= 0 ? "+" : ""}
            {tooltip.cell.changePct.toFixed(2)}%
          </div>
        </div>
      )}
    </div>
  );
}
```

