### 1. Replace simulated updates with WebSocket
You could swap the timer with:

```tsx
useEffect(() => {
  const ws = new WebSocket("wss://your-market-data-feed");

  ws.onmessage = (event) => {
    const updates = JSON.parse(event.data) as Array<{
      symbol: string;
      price: number;
      changePct: number;
    }>;

    setData((prev) =>
      prev.map((cell) => {
        const update = updates.find((u) => u.symbol === cell.symbol);
        return update
          ? { ...cell, price: update.price, changePct: update.changePct }
          : cell;
      })
    );
  };

  return () => ws.close();
}, []);
