const container = document.getElementById("chart-container") as HTMLDivElement;
const tooltip = document.getElementById("tooltip") as HTMLDivElement;

const width = container.clientWidth;
const height = container.clientHeight;

svg.attr("viewBox", `0 0 ${width} ${height}`);

const root = svg.append("g");
const gridLayer = root.append("g");

const sectors = [
  "Technology",
  "Finance",
  "Healthcare",
  "Energy",
  "Retail",
  "Industrial",
];

const symbols = [
  "AAPL", "MSFT", "GOOG", "AMZN", "NVDA", "META", "TSLA", "JPM", "BAC", "WFC",
  "XOM", "CVX", "PFE", "JNJ", "UNH", "WMT", "COST", "HD", "CAT", "BA",
  "ORCL", "CRM", "ADBE", "NFLX", "INTC", "AMD", "GS", "MS", "V", "MA",
  "PEP", "KO", "ABBV", "MRK", "DIS", "NKE", "LOW", "TGT", "GE", "MMM"
];

const rows = 5;
const cols = 8;
const cellPadding = 4;

let stocks: StockCell[] = createInitialData();
let currentTransform = d3.zoomIdentity;

function createInitialData(): StockCell[] {
  return symbols.slice(0, rows * cols).map((symbol, index) => {
    const open = randomBetween(80, 500);
    const price = open * randomBetween(0.97, 1.03);
    const changePct = ((price - open) / open) * 100;
    return {
      symbol,
      sector: sectors[index % sectors.length],
      price: round2(price),
      open: round2(open),
      changePct: round2(changePct),
      volume: Math.floor(randomBetween(100_000, 8_000_000)),
      row: Math.floor(index / cols),
      col: index % cols,
    };
  });
}

function randomBetween(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function colorForChange(changePct: number): string {
  const clamped = Math.max(-5, Math.min(5, changePct));
  const scale = d3.scaleLinear<string>()
    .domain([-5, -1, 0, 1, 5])
    .range(["#7f0000", "#d84b4b", "#2b2f45", "#42b883", "#005f34"]);

  return scale(clamped);
}

function render() {
  const innerWidth = width;
  const innerHeight = height;

  const cellWidth = innerWidth / cols;
  const cellHeight = innerHeight / rows;

  const cells = gridLayer
    .selectAll<SVGGElement, StockCell>("g.stock")
    .data(stocks, (d: any) => d.symbol);

  const cellsEnter = cells
    .enter()
    .append("g")
    .attr("class", "stock");

  cellsEnter
    .append("rect")
    .attr("class", "cell")
    .on("mousemove", function (event, d) {
      tooltip.classList.remove("hidden");
      tooltip.style.left = `${event.offsetX + 12}px`;
      tooltip.style.top = `${event.offsetY + 12}px`;

      const changeClass = d.changePct >= 0 ? "positive" : "negative";
      const changeSign = d.changePct >= 0 ? "+" : "";

      tooltip.innerHTML = `
        <div class="ticker">${d.symbol}</div>
        <div>Sector: ${d.sector}</div>
        <div>Price: $${d.price.toFixed(2)}</div>
        <div class="${changeClass}">Change: ${changeSign}${d.changePct.toFixed(2)}%</div>
        <div>Volume: ${d.volume.toLocaleString()}</div>
      `;
    })
    .on("mouseleave", () => {
      tooltip.classList.add("hidden");
    });

  cellsEnter
    .append("text")
    .attr("class", "cell-label");

  const merged = cellsEnter.merge(cells as any);

  merged.attr("transform", d => {
    const x = d.col * cellWidth;
    const y = d.row * cellHeight;
    return `translate(${x}, ${y})`;
  });

  merged.select("rect")
    .attr("width", cellWidth - cellPadding * 2)
    .attr("height", cellHeight - cellPadding * 2)
    .attr("x", cellPadding)
    .attr("y", cellPadding)
    .attr("rx", 8)
    .attr("fill", d => colorForChange(d.changePct));

  merged.select("text")
    .attr("x", cellWidth / 2)
    .attr("y", cellHeight / 2)
    .style("font-size", `${Math.max(10, Math.min(cellWidth, cellHeight) * 0.14)}px`)
    .text(d => `${d.symbol} ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(1)}%`);

  cells.exit().remove();
}

function updatePrices() {
  stocks = stocks.map(stock => {
    const drift = randomBetween(-0.8, 0.8);
    let nextPrice = stock.price * (1 + drift / 100);
    nextPrice = Math.max(5, nextPrice);

    const nextChange = ((nextPrice - stock.open) / stock.open) * 100;

    return {
      ...stock,
      price: round2(nextPrice),
      changePct: round2(nextChange),
      volume: stock.volume + Math.floor(randomBetween(1000, 100000)),
    };
  });

  render();
}

const zoomBehavior = d3.zoom<SVGSVGElement, unknown>()
  .scaleExtent([1, 8])
  .translateExtent([[0, 0], [width * 2, height * 2]])
  .on("zoom", (event) => {
    currentTransform = event.transform;
    root.attr("transform", currentTransform.toString());
  });

svg.call(zoomBehavior);

render();
setInterval(updatePrices, 1000);

window.addEventListener("resize", () => {
  const w = container.clientWidth;
  const h = container.clientHeight;
  svg.attr("viewBox", `0 0 ${w} ${h}`);
  render();
});
```

