### `src/main.ts`
```ts
type StockCell = {
  symbol: string;
  sector: string;
  price: number;
  prevClose: number;
  changePct: number;
};

type ViewState = {
  scale: number;
  offsetX: number;
  offsetY: number;
};

type GridLayout = {
  cols: number;
  rows: number;
  cellWidth: number;
  cellHeight: number;
  gap: number;
};

class StockHeatmapApp {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private tooltip: HTMLDivElement;
  private stats: HTMLSpanElement;
  private rateInput: HTMLInputElement;
  private resetViewBtn: HTMLButtonElement;

  private dpr = Math.max(1, window.devicePixelRatio || 1);
  private width = 0;
  private height = 0;

  private stocks: StockCell[] = [];
  private layout: GridLayout = {
    cols: 20,
    rows: 15,
    cellWidth: 90,
    cellHeight: 48,
    gap: 6
  };

  private view: ViewState = {
    scale: 1,
    offsetX: 20,
    offsetY: 20
  };

  private hoveredIndex: number | null = null;
  private pointer = { x: 0, y: 0 };

  private isDragging = false;
  private dragStart = { x: 0, y: 0 };
  private dragOrigin = { x: 0, y: 0 };

  private animationFrame = 0;
  private lastRender = 0;
  private updatesPerTick = 80;
  private feedHandle = 0;

  constructor() {
    this.canvas = document.getElementById("heatmap") as HTMLCanvasElement;
    this.tooltip = document.getElementById("tooltip") as HTMLDivElement;
    this.stats = document.getElementById("stats") as HTMLSpanElement;
    this.rateInput = document.getElementById("rateInput") as HTMLInputElement;
    this.resetViewBtn = document.getElementById("resetViewBtn") as HTMLButtonElement;

    const ctx = this.canvas.getContext("2d");
    if (!ctx) throw new Error("2D canvas context unavailable");
    this.ctx = ctx;

    this.initData();
    this.bindEvents();
    this.resize();
    this.startFeed();
    this.renderLoop();
  }

  private initData() {
    const sectors = ["Tech", "Finance", "Health", "Energy", "Retail", "Industrial"];
    const total = this.layout.cols * this.layout.rows;

    for (let i = 0; i < total; i++) {
      const base = 20 + Math.random() * 480;
      const prevClose = base;
      const price = base * (1 + (Math.random() - 0.5) * 0.04);

      this.stocks.push({
        symbol: this.makeSymbol(i),
        sector: sectors[i % sectors.length],
        price,
        prevClose,
        changePct: ((price - prevClose) / prevClose) * 100
      });
    }
  }

  private makeSymbol(i: number): string {
    const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const a = letters[(i * 7) % letters.length];
    const b = letters[(i * 11 + 3) % letters.length];
    const c = letters[(i * 13 + 5) % letters.length];
    return `${a}${b}${c}`;
  }

  private bindEvents() {
    window.addEventListener("resize", this.resize);

    this.canvas.addEventListener("pointerdown", this.onPointerDown);
    window.addEventListener("pointermove", this.onPointerMove);
    window.addEventListener("pointerup", this.onPointerUp);
    window.addEventListener("pointercancel", this.onPointerUp);

    this.canvas.addEventListener("wheel", this.onWheel, { passive: false });

    this.rateInput.addEventListener("input", () => {
      this.updatesPerTick = Number(this.rateInput.value);
    });

    this.resetViewBtn.addEventListener("click", () => {
      this.view.scale = 1;
      this.view.offsetX = 20;
      this.view.offsetY = 20;
    });
  }

  private resize = () => {
    const rect = this.canvas.getBoundingClientRect();
    this.width = Math.floor(rect.width);
    this.height = Math.floor(rect.height);

    this.dpr = Math.max(1, window.devicePixelRatio || 1);
    this.canvas.width = Math.floor(this.width * this.dpr);
    this.canvas.height = Math.floor(this.height * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  };

  private startFeed() {
    this.feedHandle = window.setInterval(() => {
      for (let i = 0; i < this.updatesPerTick; i++) {
        const idx = (Math.random() * this.stocks.length) | 0;
        const stock = this.stocks[idx];

        const drift = (Math.random() - 0.5) * 0.012;
        stock.price = Math.max(1, stock.price * (1 + drift));
        stock.changePct = ((stock.price - stock.prevClose) / stock.prevClose) * 100;
      }
    }, 120);
  }

  private renderLoop = (ts = 0) => {
    this.animationFrame = requestAnimationFrame(this.renderLoop);
    const dt = ts - this.lastRender;
    this.lastRender = ts;
    this.render(dt);
  };

  private render(dt: number) {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);

    this.drawBackground();
    this.drawHeatmap();
    this.drawOverlay(dt);
  }

  private drawBackground() {
    const ctx = this.ctx;
    const g = ctx.createLinearGradient(0, 0, 0, this.height);
    g.addColorStop(0, "#0b1020");
    g.addColorStop(1, "#0a0e1a");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, this.width, this.height);
  }

  private drawHeatmap() {
    const ctx = this.ctx;
    const { cols, cellWidth, cellHeight, gap } = this.layout;
    const { scale, offsetX, offsetY } = this.view;

    ctx.save();
    ctx.translate(offsetX, offsetY);
    ctx.scale(scale, scale);

    for (let i = 0; i < this.stocks.length; i++) {
      const col = i % cols;
      const row = (i / cols) | 0;

      const x = col * (cellWidth + gap);
      const y = row * (cellHeight + gap);

      const stock = this.stocks[i];
      const color = this.colorForChange(stock.changePct);

      ctx.fillStyle = color;
      this.roundRect(ctx, x, y, cellWidth, cellHeight, 8);
      ctx.fill();

      if (i === this.hoveredIndex) {
        ctx.strokeStyle = "rgba(255,255,255,0.9)";
        ctx.lineWidth = 2 / scale;
        this.roundRect(ctx, x + 1, y + 1, cellWidth - 2, cellHeight - 2, 8);
        ctx.stroke();
      }

      if (scale > 0.55) {
        ctx.fillStyle = "rgba(255,255,255,0.95)";
        ctx.font = `${12 / Math.max(0.85, 1 / scale)}px sans-serif`;
        ctx.fillText(stock.symbol, x + 8, y + 16);

        ctx.fillStyle = "rgba(255,255,255,0.85)";
        ctx.font = `${11 / Math.max(0.85, 1 / scale)}px sans-serif`;
        ctx.fillText(`$${stock.price.toFixed(2)}`, x + 8, y + 32);

        const change = `${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%`;
        ctx.fillText(change, x + cellWidth - 54, y + 32);
      }
    }

    ctx.restore();
  }

  private drawOverlay(dt: number) {
    this.stats.textContent = `${this.stocks.length} stocks • ${this.updatesPerTick} updates/tick • ${this.view.scale.toFixed(2)}x`;

    const ctx = this.ctx;
    ctx.fillStyle = "rgba(255,255,255,0.6)";
    ctx.font = "12px sans-serif";
    ctx.fillText("Wheel to zoom • Drag to pan • Hover for details", 12, this.height - 12);
  }

  private colorForChange(changePct: number): string {
    const c = Math.max(-8, Math.min(8, changePct));
    if (c >= 0) {
      const t = c / 8;
      const r = Math.round(30 - t * 20);
      const g = Math.round(80 + t * 120);
      const b = Math.round(50 + t * 40);
      return `rgb(${r}, ${g}, ${b})`;
    } else {
      const t = Math.abs(c) / 8;
      const r = Math.round(120 + t * 120);
      const g = Math.round(50 - t * 20);
      const b = Math.round(50 - t * 10);
      return `rgb(${r}, ${g}, ${b})`;
    }
  }

  private onPointerDown = (e: PointerEvent) => {
    this.isDragging = true;
    this.canvas.classList.add("dragging");
    this.dragStart.x = e.clientX;
    this.dragStart.y = e.clientY;
    this.dragOrigin.x = this.view.offsetX;
    this.dragOrigin.y = this.view.offsetY;
    this.canvas.setPointerCapture?.(e.pointerId);
  };

  private onPointerMove = (e: PointerEvent) => {
    const rect = this.canvas.getBoundingClientRect();
    this.pointer.x = e.clientX - rect.left;
    this.pointer.y = e.clientY - rect.top;

    if (this.isDragging) {
      const dx = e.clientX - this.dragStart.x;
      const dy = e.clientY - this.dragStart.y;
      this.view.offsetX = this.dragOrigin.x + dx;
      this.view.offsetY = this.dragOrigin.y + dy;
    }

    this.hoveredIndex = this.hitTest(this.pointer.x, this.pointer.y);
    this.updateTooltip();
  };

  private onPointerUp = (_e: PointerEvent) => {
    this.isDragging = false;
    this.canvas.classList.remove("dragging");
  };

  private onWheel = (e: WheelEvent) => {
    e.preventDefault();

    const rect = this.canvas.getBoundingClientRect();
    const px = e.clientX - rect.left;
    const py = e.clientY - rect.top;

    const zoomFactor = Math.exp(-e.deltaY * 0.0015);
    const newScale = Math.max(0.35, Math.min(4, this.view.scale * zoomFactor));

    const wxBefore = (px - this.view.offsetX) / this.view.scale;
    const wyBefore = (py - this.view.offsetY) / this.view.scale;

    this.view.scale = newScale;
    this.view.offsetX = px - wxBefore * this.view.scale;
    this.view.offsetY = py - wyBefore * this.view.scale;

    this.hoveredIndex = this.hitTest(this.pointer.x, this.pointer.y);
    this.updateTooltip();
  };

  private hitTest(screenX: number, screenY: number): number | null {
    const { cols, rows, cellWidth, cellHeight, gap } = this.layout;
    const wx = (screenX - this.view.offsetX) / this.view.scale;
    const wy = (screenY - this.view.offsetY) / this.view.scale;

    const pitchX = cellWidth + gap;
    const pitchY = cellHeight + gap;

    const col = Math.floor(wx / pitchX);
    const row = Math.floor(wy / pitchY);

    if (col < 0 || row < 0 || col >= cols || row >= rows) return null;

    const localX = wx - col * pitchX;
    const localY = wy - row * pitchY;

    if (localX > cellWidth || localY > cellHeight) return null;

    const idx = row * cols + col;
    return idx >= 0 && idx < this.stocks.length ? idx : null;
  }

  private updateTooltip() {
    if (this.hoveredIndex == null) {
      this.tooltip.classList.add("hidden");
      return;
    }

    const stock = this.stocks[this.hoveredIndex];
    const change = `${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%`;

    this.tooltip.innerHTML = `
      <strong>${stock.symbol}</strong><br/>
      Sector: ${stock.sector}<br/>
      Price: $${stock.price.toFixed(2)}<br/>
      Prev Close: $${stock.prevClose.toFixed(2)}<br/>
      Change: ${change}
    `;

    this.tooltip.style.left = `${this.pointer.x}px`;
    this.tooltip.style.top = `${this.pointer.y}px`;
    this.tooltip.classList.remove("hidden");
  }

  private roundRect(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    w: number,
    h: number,
    r: number
  ) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  destroy() {
    cancelAnimationFrame(this.animationFrame);
    clearInterval(this.feedHandle);
    window.removeEventListener("resize", this.resize);
  }
}

new StockHeatmapApp();
