</head>
<body>
  <div class="toolbar">
    Realtime Stock Price Heatmap — scroll to zoom, drag to pan
  </div>
  <svg id="chart"></svg>

  <script>
    const svg = d3.select("#chart");
    const width = window.innerWidth;
    const height = window.innerHeight - 42;
    svg.attr("width", width).attr("height", height);

    const margin = { top: 30, right: 20, bottom: 40, left: 60 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const gRoot = svg.append("g");
    const g = gRoot.append("g").attr("transform", `translate(${margin.left},${margin.top})`);

    const stocks = [
      "AAPL","MSFT","GOOG","AMZN","TSLA",
      "META","NVDA","NFLX","AMD","INTC"
    ];

    const timeSteps = 30;

    let data = [];
    for (let y = 0; y < stocks.length; y++) {
      for (let x = 0; x < timeSteps; x++) {
        data.push({
          stock: stocks[y],
          time: x,
          value: 100 + Math.random() * 20
        });
      }
    }

    const xScale = d3.scaleBand()
      .domain(d3.range(timeSteps))
      .range([0, innerWidth])
      .padding(0.05);

    const yScale = d3.scaleBand()
      .domain(stocks)
      .range([0, innerHeight])
      .padding(0.05);

    const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
      .domain([120, 95]); // green high, red low

    const xAxis = d3.axisBottom(xScale).tickFormat(d => `T${d}`);
    const yAxis = d3.axisLeft(yScale);

    const xAxisG = g.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${innerHeight})`)
      .call(xAxis);

    const yAxisG = g.append("g")
      .attr("class", "axis")
      .call(yAxis);

    const cellsG = g.append("g");

    function render() {
      const cells = cellsG.selectAll("rect").data(data, d => `${d.stock}-${d.time}`);

      cells.join("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.value))
        .append("title")
        .text(d => `${d.stock} T${d.time}: ${d.value.toFixed(2)}`);
    }

    render();

    function tickUpdate() {
      for (const stock of stocks) {
        data = data.filter(d => !(d.stock === stock && d.time === 0));

        for (const d of data) {
          if (d.stock === stock) d.time -= 1;
        }
      }

      data = data.filter(d => d.time >= 0);

      for (const stock of stocks) {
        const existing = data.filter(d => d.stock === stock);
        const lastVal = existing.length
          ? existing.reduce((a, b) => a.time > b.time ? a : b).value
          : 100;

        const nextVal = Math.max(90, Math.min(125, lastVal + (Math.random() - 0.5) * 6));

        data.push({
          stock,
          time: timeSteps - 1,
          value: nextVal
        });
      }

      render();
    }

    setInterval(tickUpdate, 1000);

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        gRoot.attr("transform", event.transform);
      });

    svg.call(zoom);

    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
```

