```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      background: #0b1020;
      color: #e5e7eb;
      font-family: Arial, sans-serif;
      overflow: hidden;
    }

    #app {
      display: flex;
      flex-direction: column;
      height: 100%;
    }

    #toolbar {
      padding: 10px 14px;
      background: #111827;
      border-bottom: 1px solid #1f2937;
      display: flex;
      gap: 18px;
      align-items: center;
      font-size: 14px;
    }

    #heatmap {
      flex: 1;
      display: block;
      cursor: grab;
      background: #0f172a;
    }

    #heatmap.dragging {
      cursor: grabbing;
    }

    #tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(17, 24, 39, 0.95);
      color: white;
      border: 1px solid #374151;
      border-radius: 6px;
      padding: 8px 10px;
      font-size: 12px;
      white-space: nowrap;
      display: none;
      z-index: 1000;
      box-shadow: 0 6px 20px rgba(0,0,0,0.35);
    }

    .legend {
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .legend-bar {
      width: 140px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #7f1d1d 0%, #dc2626 30%, #1f2937 50%, #16a34a 70%, #14532d 100%);
      border: 1px solid #374151;
    }

    .muted {
      color: #94a3b8;
    }
  </style>
</head>
<body>
  <div id="app">
    <div id="toolbar">
      <strong>Real-Time Stock Heatmap</strong>
      <span class="muted">Wheel = zoom</span>
      <span class="muted">Drag = pan</span>
      <span class="muted">Hover = details</span>
      <span class="legend">
        <span>-5%</span>
        <span class="legend-bar"></span>
        <span>+5%</span>
      </span>
    </div>
    <canvas id="heatmap"></canvas>
    <div id="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    const state = {
      stocks: [],
      cols: 12,
      cellWidth: 120,
      cellHeight: 70,
      gap: 8,
      scale: 1,
      offsetX: 20,
      offsetY: 20,
      minScale: 0.5,
      maxScale: 3,
      isDragging: false,
      dragStartX: 0,
      dragStartY: 0,
      dragOriginX: 0,
      dragOriginY: 0,
      mouseX: 0,
      mouseY: 0,
      hoveredIndex: -1
    };

    const symbols = [
      "AAPL","MSFT","GOOG","AMZN","META","NVDA","TSLA","NFLX","AMD","INTC",
      "ORCL","IBM","CRM","UBER","SHOP","SQ","PYPL","BABA","SONY","V",
      "MA","JPM","GS","BAC","WMT","COST","DIS","KO","PEP","NKE",
      "XOM","CVX","T","VZ","PFE","MRK","ABNB","SNOW","PLTR","ADBE",
      "QCOM","CSCO","AVGO","TXN","ARM","MU","QQQ","SPY"
    ];

    function randomPrice() {
      return +(50 + Math.random() * 450).toFixed(2);
    }

    function randomChange() {
      return +(Math.random() * 10 - 5).toFixed(2);
    }

    function initStocks() {
      state.stocks = symbols.map(symbol => {
        const price = randomPrice();
        const changePct = randomChange();
        return {
          symbol,
          price,
          open: +(price / (1 + changePct / 100)).toFixed(2),
          changePct,
          volume: Math.floor(100000 + Math.random() * 5000000)
        };
      });
    }

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function colorForChange(changePct) {
      const clamped = Math.max(-5, Math.min(5, changePct));
      if (clamped < 0) {
        const t = (clamped + 5) / 5;
        const r = Math.round(lerp(127, 220, t));
        const g = Math.round(lerp(29, 38, t));
        const b = Math.round(lerp(29, 38, t));
        return `rgb(${r},${g},${b})`;
      } else {
        const t = clamped / 5;
        const r = Math.round(lerp(31, 20, t));
        const g = Math.round(lerp(41, 83, t));
        const b = Math.round(lerp(55, 45, t));
        return `rgb(${r},${g},${b})`;
      }
    }

    function strokeForHover(isHovered) {
      return isHovered ? "#f8fafc" : "#334155";
    }

    function getRows() {
      return Math.ceil(state.stocks.length / state.cols);
    }

    function worldToScreen(x, y) {
      return {
        x: x * state.scale + state.offsetX,
        y: y * state.scale + state.offsetY
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - state.offsetX) / state.scale,
        y: (y - state.offsetY) / state.scale
      };
    }

    function getCellRect(index) {
      const col = index % state.cols;
      const row = Math.floor(index / state.cols);
      const x = col * (state.cellWidth + state.gap);
      const y = row * (state.cellHeight + state.gap);
      return { x, y, width: state.cellWidth, height: state.cellHeight };
    }

    function findHoveredIndex(screenX, screenY) {
      const p = screenToWorld(screenX, screenY);
      for (let i = 0; i < state.stocks.length; i++) {
        const r = getCellRect(i);
        if (
          p.x >= r.x && p.x <= r.x + r.width &&
          p.y >= r.y && p.y <= r.y + r.height
        ) {
          return i;
        }
      }
      return -1;
    }

    function drawCell(stock, index) {
      const rect = getCellRect(index);
      const p = worldToScreen(rect.x, rect.y);
      const w = rect.width * state.scale;
      const h = rect.height * state.scale;
      const hovered = index === state.hoveredIndex;

      ctx.fillStyle = colorForChange(stock.changePct);
      ctx.fillRect(p.x, p.y, w, h);

      ctx.strokeStyle = strokeForHover(hovered);
      ctx.lineWidth = hovered ? 2 : 1;
      ctx.strokeRect(p.x, p.y, w, h);

      ctx.save();
      ctx.beginPath();
      ctx.rect(p.x, p.y, w, h);
      ctx.clip();

      const pad = 10 * state.scale;
      ctx.fillStyle = "#f8fafc";
      ctx.font = `${Math.max(10, 15 * state.scale)}px Arial`;
      ctx.fillText(stock.symbol, p.x + pad, p.y + 20 * state.scale);

      ctx.fillStyle = "#e2e8f0";
      ctx.font = `${Math.max(9, 13 * state.scale)}px Arial`;
      ctx.fillText(`$${stock.price.toFixed(2)}`, p.x + pad, p.y + 42 * state.scale);

      ctx.fillStyle = stock.changePct >= 0 ? "#bbf7d0" : "#fecaca";
      const sign = stock.changePct >= 0 ? "+" : "";
      ctx.fillText(`${sign}${stock.changePct.toFixed(2)}%`, p.x + pad, p.y + 60 * state.scale);

      ctx.restore();
    }

    function draw() {
      const rect = canvas.getBoundingClientRect();
      ctx.clearRect(0, 0, rect.width, rect.height);

      const rows = getRows();
      const totalWidth = state.cols * state.cellWidth + (state.cols - 1) * state.gap;
      const totalHeight = rows * state.cellHeight + (rows - 1) * state.gap;

      ctx.save();
      ctx.strokeStyle = "#1e293b";
      ctx.strokeRect(
        state.offsetX - 6,
        state.offsetY - 6,
        totalWidth * state.scale + 12,
        totalHeight * state.scale + 12
      );
      ctx.restore();

      for (let i = 0; i < state.stocks.length; i++) {
        drawCell(state.stocks[i], i);
      }
    }

    function updateTooltip() {
      if (state.hoveredIndex < 0) {
        tooltip.style.display = "none";
        return;
      }

      const stock = state.stocks[state.hoveredIndex];
      tooltip.style.display = "block";
      tooltip.style.left = `${state.mouseX + 14}px`;
      tooltip.style.top = `${state.mouseY + 14}px`;
      tooltip.innerHTML = `
        <div><strong>${stock.symbol}</strong></div>
        <div>Price: $${stock.price.toFixed(2)}</div>
        <div>Open: $${stock.open.toFixed(2)}</div>
        <div>Change: ${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%</div>
        <div>Volume: ${stock.volume.toLocaleString()}</div>
      `;
    }

    function simulateTick() {
      for (const stock of state.stocks) {
        const drift = (Math.random() - 0.5) * 1.2;
        stock.changePct = Math.max(-5, Math.min(5, stock.changePct + drift));
        stock.price = +(stock.open * (1 + stock.changePct / 100)).toFixed(2);
        stock.volume += Math.floor(Math.random() * 50000);
      }
      draw();
      updateTooltip();
    }

    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      state.mouseX = e.clientX;
      state.mouseY = e.clientY;
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      if (state.isDragging) {
        state.offsetX = state.dragOriginX + (e.clientX - state.dragStartX);
        state.offsetY = state.dragOriginY + (e.clientY - state.dragStartY);
      }

      state.hoveredIndex = findHoveredIndex(x, y);
      draw();
      updateTooltip();
    });

    canvas.addEventListener('mousedown', (e) => {
      state.isDragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.dragOriginX = state.offsetX;
      state.dragOriginY = state.offsetY;
      canvas.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      state.isDragging = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('mouseleave', () => {
      if (!state.isDragging) {
        state.hoveredIndex = -1;
        draw();
        updateTooltip();
      }
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.max(state.minScale, Math.min(state.maxScale, state.scale * zoomFactor));

      const worldBefore = screenToWorld(mouseX, mouseY);
      state.scale = newScale;
      state.offsetX = mouseX - worldBefore.x * state.scale;
      state.offsetY = mouseY - worldBefore.y * state.scale;

      state.hoveredIndex = findHoveredIndex(mouseX, mouseY);
      draw();
      updateTooltip();
    }, { passive: false });

    initStocks();
    resize();
    window.addEventListener('resize', resize);
    setInterval(simulateTick, 1000);
  </script>
</body>
</html>
