<body>
  <div class="container">
    <h1>Interactive Real-Time Stock Price Heatmap</h1>
    <div class="chart-wrap" id="chart">
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const container = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");

    const stocks = [
      "AAPL", "MSFT", "GOOG", "AMZN", "NVDA",
      "META", "TSLA", "NFLX", "AMD", "INTC"
    ];

    const timeSteps = 40;
    const data = [];
    let tick = 0;

    function randomChange() {
      return (Math.random() - 0.5) * 4; // -2% to +2%
    }

    function generateInitialData() {
      for (let t = 0; t < timeSteps; t++) {
        for (let s = 0; s < stocks.length; s++) {
          data.push({
            stock: stocks[s],
            time: t,
            change: randomChange()
          });
        }
      }
    }

    generateInitialData();

    const margin = { top: 30, right: 20, bottom: 40, left: 70 };
    const width = container.clientWidth - margin.left - margin.right;
    const height = container.clientHeight - margin.top - margin.bottom;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("viewBox", `0 0 ${container.clientWidth} ${container.clientHeight}`);

    const root = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const heatmapLayer = root.append("g");
    const xAxisG = root.append("g").attr("class", "axis").attr("transform", `translate(0,${height})`);
    const yAxisG = root.append("g").attr("class", "axis");

    const xDomain = d3.range(timeSteps);
    const yDomain = stocks;

    let xScale = d3.scaleBand()
      .domain(xDomain)
      .range([0, width])
      .padding(0.03);

    let yScale = d3.scaleBand()
      .domain(yDomain)
      .range([0, height])
      .padding(0.03);

    const colorScale = d3.scaleLinear()
      .domain([-3, 0, 3])
      .range(["#c0392b", "#f1c40f", "#27ae60"])
      .clamp(true);

    const xAxis = d3.axisBottom(xScale).tickValues(
      xDomain.filter(d => d % 5 === 0)
    );

    const yAxis = d3.axisLeft(yScale);

    xAxisG.call(xAxis);
    yAxisG.call(yAxis);

    function render() {
      const cells = heatmapLayer.selectAll("rect")
        .data(data, d => `${d.stock}-${d.time}`);

      cells.enter()
        .append("rect")
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change))
        .on("mousemove", function(event, d) {
          tooltip.style.display = "block";
          tooltip.style.left = event.offsetX + 15 + "px";
          tooltip.style.top = event.offsetY + 15 + "px";
          tooltip.innerHTML = `
            <strong>${d.stock}</strong><br>
            Time: ${d.time}<br>
            Change: ${d.change.toFixed(2)}%
          `;
        })
        .on("mouseleave", function() {
          tooltip.style.display = "none";
        })
        .merge(cells)
        .transition()
        .duration(300)
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change));

      cells.exit().remove();

      xAxisG.call(xAxis.scale(xScale));
      yAxisG.call(yAxis.scale(yScale));
    }

    render();

    function updateData() {
      tick++;

      // Remove oldest time column
      const minTime = d3.min(data, d => d.time);
      for (let i = data.length - 1; i >= 0; i--) {
        if (data[i].time === minTime) data.splice(i, 1);
      }

      // Shift all remaining time values left
      data.forEach(d => d.time -= 1);

      // Add new latest column
      for (let s = 0; s < stocks.length; s++) {
        data.push({
          stock: stocks[s],
          time: timeSteps - 1,
          change: randomChange()
        });
      }

      render();
    }

    setInterval(updateData, 1000);

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", zoomed);

    svg.call(zoom);

    function zoomed(event) {
      const transform = event.transform;

      const zx = transform.rescaleX(
        d3.scaleLinear()
          .domain([0, timeSteps])
          .range([0, width])
      );

      const zy = transform.rescaleY(
        d3.scaleLinear()
          .domain([0, stocks.length])
          .range([0, height])
      );

      const newX = d3.scaleBand()
        .domain(xDomain)
        .range(xDomain.map(d => zx(d)).concat([zx(timeSteps)]))
        .padding(0.03);

      const newY = d3.scaleBand()
        .domain(yDomain)
        .range(yDomain.map((d, i) => zy(i)).concat([zy(stocks.length)]))
        .padding(0.03);

      xScale = newX;
      yScale = newY;
      render();
    }

    // Simple legend
    const legend = svg.append("g")
      .attr("class", "legend")
      .attr("transform", `translate(${container.clientWidth - 180},20)`);

    const legendData = [
      { label: "-3%", color: "#c0392b" },
      { label: "0%", color: "#f1c40f" },
      { label: "+3%", color: "#27ae60" }
    ];

    legend.selectAll("rect")
      .data(legendData)
      .enter()
      .append("rect")
      .attr("x", (d, i) => i * 50)
      .attr("y", 0)
      .attr("width", 18)
      .attr("height", 18)
      .attr("fill", d => d.color);

    legend.selectAll("text")
      .data(legendData)
      .enter()
      .append("text")
      .attr("x", (d, i) => i * 50 + 22)
      .attr("y", 13)
      .text(d => d.label);
  </script>
</body>
</html>
```

---

## How it works
- Each row is a stock symbol.
- Each column is a recent time slice.
- Each cell color represents a simulated price change:
  - **red** = negative
  - **yellow** = neutral
  - **green** = positive
- Every second:
  - oldest column is removed
  - data shifts left
  - a new column of simulated values is appended
- D3 zoom behavior enables **pan/zoom**.

