<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time Stock Heatmap</title>
  <script src="https://cdn.jsdelivr.net/npm/d3@7"></script>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #0f172a;
      color: #e2e8f0;
      overflow: hidden;
    }

    #toolbar {
      padding: 10px 14px;
      background: #111827;
      border-bottom: 1px solid #334155;
      display: flex;
      gap: 20px;
      align-items: center;
      font-size: 14px;
    }

    #chart {
      width: 100vw;
      height: calc(100vh - 48px);
      display: block;
      cursor: grab;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      background: #020617;
    }

    .cell {
      stroke: #0b1220;
      stroke-width: 1px;
    }

    .label {
      pointer-events: none;
      fill: white;
      font-size: 12px;
      font-weight: bold;
    }

    .sublabel {
      pointer-events: none;
      fill: rgba(255,255,255,0.8);
      font-size: 10px;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      color: #e2e8f0;
      border: 1px solid #475569;
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      display: none;
      white-space: nowrap;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><strong>Real-Time Stock Heatmap</strong></div>
    <div>Zoom: mouse wheel</div>
    <div>Pan: drag</div>
    <div id="status">Live updates: ON</div>
  </div>

  <div id="chart"></div>
  <div id="tooltip" class="tooltip"></div>

  <script>
    const stocks = [
      { symbol: "AAPL", price: 192, change: 0.0, marketCap: 3000 },
      { symbol: "MSFT", price: 418, change: 0.0, marketCap: 2900 },
      { symbol: "GOOGL", price: 176, change: 0.0, marketCap: 2200 },
      { symbol: "AMZN", price: 183, change: 0.0, marketCap: 1900 },
      { symbol: "NVDA", price: 121, change: 0.0, marketCap: 2800 },
      { symbol: "META", price: 502, change: 0.0, marketCap: 1300 },
      { symbol: "TSLA", price: 171, change: 0.0, marketCap: 800 },
      { symbol: "JPM", price: 201, change: 0.0, marketCap: 600 },
      { symbol: "V", price: 275, change: 0.0, marketCap: 550 },
      { symbol: "UNH", price: 489, change: 0.0, marketCap: 500 },
      { symbol: "XOM", price: 114, change: 0.0, marketCap: 470 },
      { symbol: "AVGO", price: 1602, change: 0.0, marketCap: 700 }
    ];

    const chartEl = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");

    const width = chartEl.clientWidth;
    const height = chartEl.clientHeight;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("viewBox", `0 0 ${width} ${height}`);

    const zoomLayer = svg.append("g");
    const heatmapLayer = zoomLayer.append("g");

    const color = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#1e293b", "#16a34a"])
      .clamp(true);

    function buildHierarchy() {
      return {
        name: "market",
        children: stocks.map(s => ({
          name: s.symbol,
          value: s.marketCap,
          price: s.price,
          change: s.change
        }))
      };
    }

    function render() {
      const root = d3.hierarchy(buildHierarchy())
        .sum(d => d.value || 0);

      d3.treemap()
        .size([width, height])
        .paddingInner(4)(root);

      const leaves = root.leaves();

      const cells = heatmapLayer.selectAll("g.cell-group")
        .data(leaves, d => d.data.name);

      const enter = cells.enter()
        .append("g")
        .attr("class", "cell-group");

      enter.append("rect").attr("class", "cell");
      enter.append("text").attr("class", "label");
      enter.append("text").attr("class", "sublabel");

      const merged = enter.merge(cells);

      merged
        .attr("transform", d => `translate(${d.x0},${d.y0})`)
        .on("mousemove", (event, d) => {
          tooltip.style.display = "block";
          tooltip.style.left = (event.pageX + 12) + "px";
          tooltip.style.top = (event.pageY + 12) + "px";
          tooltip.innerHTML = `
            <strong>${d.data.name}</strong><br/>
            Price: $${d.data.price.toFixed(2)}<br/>
            Change: ${d.data.change >= 0 ? "+" : ""}${d.data.change.toFixed(2)}%<br/>
            Market Cap: ${d.data.value}B
          `;
        })
        .on("mouseleave", () => {
          tooltip.style.display = "none";
        });

      merged.select("rect")
        .transition()
        .duration(300)
        .attr("width", d => Math.max(0, d.x1 - d.x0))
        .attr("height", d => Math.max(0, d.y1 - d.y0))
        .attr("fill", d => color(d.data.change));

      merged.select(".label")
        .attr("x", 8)
        .attr("y", 20)
        .text(d => (d.x1 - d.x0 > 60 && d.y1 - d.y0 > 30) ? d.data.name : "");

      merged.select(".sublabel")
        .attr("x", 8)
        .attr("y", 38)
        .text(d => {
          if ((d.x1 - d.x0 > 80) && (d.y1 - d.y0 > 45)) {
            return `${d.data.change >= 0 ? "+" : ""}${d.data.change.toFixed(2)}%`;
          }
          return "";
        });

      cells.exit().remove();
    }

    function updatePrices() {
      stocks.forEach(stock => {
        const delta = (Math.random() - 0.5) * 2.0; // random %
        stock.change = Math.max(-5, Math.min(5, stock.change + delta * 0.3));
        stock.price = Math.max(1, stock.price * (1 + delta / 100));
      });
      render();
    }

    const zoom = d3.zoom()
      .scaleExtent([0.5, 4])
      .on("zoom", (event) => {
        zoomLayer.attr("transform", event.transform);
      });

    svg.call(zoom);

    render();
    setInterval(updatePrices, 1000);

    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
```

## How it works
- Uses a **treemap layout** as the heatmap grid.
- Each stock tile size is based on `marketCap`.
- Tile color reflects `change`:
  - red = down
  - dark neutral = flat
  - green = up
- Prices update every second with simulated random movement.
- D3 zoom behavior enables mouse-wheel zoom and drag pan.

