- Simulated real-time updates
- Zoom with mouse wheel
- Pan by dragging
- Client-side only
- No build step
- Minimal but working

Save this as `index.html` and open it in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Real-Time Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      font-family: Arial, sans-serif;
      background: #0f172a;
      color: #e2e8f0;
      overflow: hidden;
    }

    #app {
      display: flex;
      flex-direction: column;
      height: 100%;
    }

    #toolbar {
      padding: 10px 12px;
      background: #111827;
      border-bottom: 1px solid #1f2937;
      font-size: 14px;
      display: flex;
      gap: 16px;
      align-items: center;
      flex-wrap: wrap;
    }

    #heatmap {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
      background: #020617;
    }

    #heatmap:active {
      cursor: grabbing;
    }

    .legend {
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .legend-bar {
      width: 140px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(to right, #7f1d1d, #1e293b, #14532d);
      border: 1px solid #334155;
    }

    .muted {
      color: #94a3b8;
    }
  </style>
</head>
<body>
  <div id="app">
    <div id="toolbar">
      <strong>Real-Time Stock Heatmap</strong>
      <span class="muted">Wheel = zoom</span>
      <span class="muted">Drag = pan</span>
      <span id="stats"></span>
      <div class="legend">
        <span class="muted">Loss</span>
        <div class="legend-bar"></div>
        <span class="muted">Gain</span>
      </div>
    </div>
    <canvas id="heatmap"></canvas>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const stats = document.getElementById("stats");

    const ROWS = 20;
    const COLS = 20;
    const symbols = [];
    const data = [];

    for (let r = 0; r < ROWS; r++) {
      const row = [];
      for (let c = 0; c < COLS; c++) {
        const symbol = `S${String(r * COLS + c + 1).padStart(3, "0")}`;
        symbols.push(symbol);
        row.push({
          symbol,
          price: 80 + Math.random() * 120,
          change: (Math.random() - 0.5) * 4
        });
      }
      data.push(row);
    }

    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function colorForChange(change) {
      const maxAbs = 5;
      const t = clamp(change / maxAbs, -1, 1);

      if (t < 0) {
        const k = Math.abs(t);
        const r = Math.round(30 + k * 150);
        const g = Math.round(41 - k * 12);
        const b = Math.round(59 - k * 20);
        return `rgb(${r},${g},${b})`;
      } else {
        const r = Math.round(20 - t * 10);
        const g = Math.round(60 + t * 120);
        const b = Math.round(45 + t * 40);
        return `rgb(${r},${g},${b})`;
      }
    }

    function draw() {
      const rect = canvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = "#020617";
      ctx.fillRect(0, 0, width, height);

      const cellW = 90 * scale;
      const cellH = 55 * scale;

      ctx.save();
      ctx.translate(offsetX, offsetY);

      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const x = c * cellW;
          const y = r * cellH;

          if (x + cellW < -offsetX || y + cellH < -offsetY || x > width - offsetX || y > height - offsetY) {
            continue;
          }

          const item = data[r][c];
          ctx.fillStyle = colorForChange(item.change);
          ctx.fillRect(x + 1, y + 1, cellW - 2, cellH - 2);

          ctx.strokeStyle = "rgba(255,255,255,0.08)";
          ctx.strokeRect(x + 0.5, y + 0.5, cellW - 1, cellH - 1);

          if (scale >= 0.6) {
            ctx.fillStyle = "rgba(255,255,255,0.95)";
            ctx.font = `${Math.max(10, 12 * scale)}px Arial`;
            ctx.fillText(item.symbol, x + 8, y + 18);

            ctx.fillStyle = "rgba(255,255,255,0.85)";
            ctx.font = `${Math.max(9, 11 * scale)}px Arial`;
            ctx.fillText(`$${item.price.toFixed(2)}`, x + 8, y + 34);

            const sign = item.change >= 0 ? "+" : "";
            ctx.fillText(`${sign}${item.change.toFixed(2)}%`, x + 8, y + 48);
          }
        }
      }

      ctx.restore();

      const flat = data.flat();
      const avg = flat.reduce((sum, d) => sum + d.change, 0) / flat.length;
      stats.textContent = `Zoom: ${scale.toFixed(2)}x | Avg Change: ${avg >= 0 ? "+" : ""}${avg.toFixed(2)}%`;
    }

    function updatePrices() {
      for (let i = 0; i < 12; i++) {
        const r = Math.floor(Math.random() * ROWS);
        const c = Math.floor(Math.random() * COLS);
        const item = data[r][c];

        const deltaPct = (Math.random() - 0.5) * 0.8;
        item.change = clamp(item.change + deltaPct, -5, 5);
        item.price = Math.max(1, item.price * (1 + deltaPct / 100));
      }
      draw();
    }

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const oldScale = scale;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      scale = clamp(scale * zoomFactor, 0.4, 4);

      const worldX = (mx - offsetX) / oldScale;
      const worldY = (my - offsetY) / oldScale;

      offsetX = mx - worldX * scale;
      offsetY = my - worldY * scale;

      draw();
    }, { passive: false });

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    window.addEventListener("resize", resize);

    resize();
    setInterval(updatePrices, 500);
  </script>
</body>
</html>
```

