## 3) `server.ts`

```ts
import express from "express";
import http from "http";
import { WebSocketServer, WebSocket } from "ws";

type ColumnId = "todo" | "inprogress" | "done";

type Task = {
  id: string;
  title: string;
  description: string;
  column: ColumnId;
};

type State = {
  tasks: Task[];
};

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.json());
app.use(express.static("public"));

const state: State = {
  tasks: [
    {
      id: cryptoRandomId(),
      title: "Design landing page",
      description: "Create first draft of the dashboard",
      column: "todo"
    },
    {
      id: cryptoRandomId(),
      title: "Set up WebSocket sync",
      description: "Enable real-time collaboration",
      column: "inprogress"
    },
    {
      id: cryptoRandomId(),
      title: "Create repo",
      description: "Initialize source control and README",
      column: "done"
    }
  ]
};

app.get("/api/state", (_req, res) => {
  res.json(state);
});

function broadcast(message: unknown) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", payload: state }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "create_task") {
        const task: Task = {
          id: cryptoRandomId(),
          title: msg.payload.title ?? "Untitled task",
          description: msg.payload.description ?? "",
          column: "todo"
        };
        state.tasks.push(task);
        broadcast({ type: "state", payload: state });
      }

      if (msg.type === "move_task") {
        const { taskId, toColumn } = msg.payload as {
          taskId: string;
          toColumn: ColumnId;
        };

        const task = state.tasks.find((t) => t.id === taskId);
        if (task) {
          task.column = toColumn;
          broadcast({ type: "state", payload: state });
        }
      }
    } catch (err) {
      console.error("Invalid message", err);
    }
  });
});

server.listen(3000, () => {
  console.log("App running at http://localhost:3000");
});

function cryptoRandomId() {
  return Math.random().toString(36).slice(2, 10);
}
```

