```js
let state = { tasks: [] };
let draggedTaskId = null;

const socket = new WebSocket(`ws://${location.host}`);

socket.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);
  if (message.type === "state") {
    state = message.payload;
    render();
  }
});

const taskForm = document.getElementById("taskForm");
taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const titleInput = document.getElementById("title");
  const descriptionInput = document.getElementById("description");

  const title = titleInput.value.trim();
  const description = descriptionInput.value.trim();

  if (!title) return;

  socket.send(
    JSON.stringify({
      type: "create_task",
      payload: { title, description }
    })
  );

  titleInput.value = "";
  descriptionInput.value = "";
});

function render() {
  ["todo", "inprogress", "done"].forEach((columnId) => {
    const columnEl = document.getElementById(columnId);
    columnEl.innerHTML = "";

    state.tasks
      .filter((task) => task.column === columnId)
      .forEach((task) => {
        const taskEl = document.createElement("div");
        taskEl.className = "task";
        taskEl.draggable = true;
        taskEl.dataset.taskId = task.id;

        taskEl.innerHTML = `
          <div class="task-title"></div>
          <div class="task-desc"></div>
        `;

        taskEl.querySelector(".task-title").textContent = task.title;
        taskEl.querySelector(".task-desc").textContent = task.description;

        taskEl.addEventListener("dragstart", () => {
          draggedTaskId = task.id;
          taskEl.classList.add("dragging");
        });

        taskEl.addEventListener("dragend", () => {
          draggedTaskId = null;
          taskEl.classList.remove("dragging");
        });

        columnEl.appendChild(taskEl);
      });
  });
}

document.querySelectorAll(".dropzone").forEach((zone) => {
  zone.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  zone.addEventListener("drop", () => {
    if (!draggedTaskId) return;

    socket.send(
      JSON.stringify({
        type: "move_task",
        payload: {
          taskId: draggedTaskId,
          toColumn: zone.id
        }
      })
    );
  });
});
