const http = require("http");
const { WebSocketServer } = require("ws");
const crypto = require("crypto");

const PORT = 3000;

const state = {
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "inprogress", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] },
  ],
  tasks: {},
};

function seedData() {
  const initialTasks = [
    { title: "Design homepage", description: "Create first draft of dashboard UI", columnId: "todo" },
    { title: "Set up API", description: "Create initial endpoints for tasks", columnId: "inprogress" },
    { title: "Deploy preview", description: "Publish staging build", columnId: "done" },
  ];

  for (const t of initialTasks) {
    const id = crypto.randomUUID();
    state.tasks[id] = {
      id,
      title: t.title,
      description: t.description,
    };
    const col = state.columns.find(c => c.id === t.columnId);
    col.taskIds.push(id);
  }
}

seedData();

function broadcast(wss, data) {
  const message = JSON.stringify(data);
  for (const client of wss.clients) {
    if (client.readyState === 1) {
      client.send(message);
    }
  }
}

function sendState(ws) {
  ws.send(JSON.stringify({ type: "state", state }));
}

function moveTask({ taskId, fromColumnId, toColumnId, toIndex }) {
  const fromCol = state.columns.find(c => c.id === fromColumnId);
  const toCol = state.columns.find(c => c.id === toColumnId);

  if (!fromCol || !toCol) return;

  const existingIndex = fromCol.taskIds.indexOf(taskId);
  if (existingIndex === -1) return;

  fromCol.taskIds.splice(existingIndex, 1);

  const safeIndex =
    typeof toIndex === "number" && toIndex >= 0 && toIndex <= toCol.taskIds.length
      ? toIndex
      : toCol.taskIds.length;

  toCol.taskIds.splice(safeIndex, 0, taskId);
}

function reorderTaskWithinColumn({ taskId, columnId, toIndex }) {
  const col = state.columns.find(c => c.id === columnId);
  if (!col) return;

  const fromIndex = col.taskIds.indexOf(taskId);
  if (fromIndex === -1) return;

  col.taskIds.splice(fromIndex, 1);

  const safeIndex =
    typeof toIndex === "number" && toIndex >= 0 && toIndex <= col.taskIds.length
      ? toIndex
      : col.taskIds.length;

  col.taskIds.splice(safeIndex, 0, taskId);
}

