  <script>
    let appState = null;
    let draggedTaskId = null;
    let draggedFromColumnId = null;

    const boardEl = document.getElementById("board");
    const statusEl = document.getElementById("status");
    const taskTitleEl = document.getElementById("taskTitle");
    const taskDescriptionEl = document.getElementById("taskDescription");
    const addTaskBtn = document.getElementById("addTaskBtn");

    const wsProtocol = location.protocol === "https:" ? "wss:" : "ws:";
    const ws = new WebSocket(wsProtocol + "//" + location.host);

    ws.addEventListener("open", () => {
      statusEl.textContent = "Connected for real-time collaboration";
    });

    ws.addEventListener("close", () => {
      statusEl.textContent = "Disconnected";
    });

    ws.addEventListener("message", (event) => {
      const message = JSON.parse(event.data);

      if (message.type === "state") {
        appState = message.state;
        render();
      }
    });

    addTaskBtn.addEventListener("click", () => {
      const title = taskTitleEl.value.trim();
      const description = taskDescriptionEl.value.trim();

      if (!title) return;

      ws.send(JSON.stringify({
        type: "add_task",
        title,
        description,
        columnId: "todo"
      }));

      taskTitleEl.value = "";
      taskDescriptionEl.value = "";
    });

    function render() {
      if (!appState) return;

      boardEl.innerHTML = "";

      for (const column of appState.columns) {
        const columnEl = document.createElement("div");
        columnEl.className = "column";

        const headerEl = document.createElement("div");
        headerEl.className = "column-header";

        const titleEl = document.createElement("div");
        titleEl.className = "column-title";
        titleEl.textContent = column.title;

        const countEl = document.createElement("div");
        countEl.className = "small";
        countEl.textContent = column.taskIds.length + " task" + (column.taskIds.length === 1 ? "" : "s");

        headerEl.appendChild(titleEl);
        headerEl.appendChild(countEl);

        const listEl = document.createElement("div");
        listEl.className = "task-list";
        listEl.dataset.columnId = column.id;

        listEl.addEventListener("dragover", (e) => {
          e.preventDefault();
          listEl.classList.add("drop-target");
        });

        listEl.addEventListener("dragleave", () => {
          listEl.classList.remove("drop-target");
        });

        listEl.addEventListener("drop", (e) => {
          e.preventDefault();
          listEl.classList.remove("drop-target");

          if (!draggedTaskId || !draggedFromColumnId) return;

          const afterElement = getDragAfterElement(listEl, e.clientY);
          let toIndex;

          if (!afterElement) {
            toIndex = listEl.querySelectorAll(".task").length;
          } else {
            toIndex = Number(afterElement.dataset.index);
          }

          if (draggedFromColumnId === column.id) {
            ws.send(JSON.stringify({
              type: "reorder_task",
              taskId: draggedTaskId,
              columnId: column.id,
              toIndex
            }));
          } else {
            ws.send(JSON.stringify({
              type: "move_task",
              taskId: draggedTaskId,
              fromColumnId: draggedFromColumnId,
              toColumnId: column.id,
              toIndex
            }));
          }

          draggedTaskId = null;
          draggedFromColumnId = null;
        });

        column.taskIds.forEach((taskId, index) => {
          const task = appState.tasks[taskId];
          if (!task) return;

          const taskEl = document.createElement("div");
          taskEl.className = "task";
          taskEl.draggable = true;
          taskEl.dataset.taskId = task.id;
          taskEl.dataset.index = index;

          taskEl.innerHTML = \`
            <h3>\${escapeHtml(task.title)}</h3>
            <p>\${escapeHtml(task.description || "")}</p>
          \`;

          taskEl.addEventListener("dragstart", () => {
            draggedTaskId = task.id;
            draggedFromColumnId = column.id;
            taskEl.classList.add("dragging");
          });

          taskEl.addEventListener("dragend", () => {
            taskEl.classList.remove("dragging");
          });

          listEl.appendChild(taskEl);
        });

        columnEl.appendChild(headerEl);
        columnEl.appendChild(listEl);
        boardEl.appendChild(columnEl);
      }
    }

    function getDragAfterElement(container, y) {
      const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

      return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
          return { offset, element: child };
        } else {
          return closest;
        }
      }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }
