  if (req.url === "/") {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(html);
    return;
  }

  res.writeHead(404);
  res.end("Not found");
});

const wss = new WebSocketServer({ server });

wss.on("connection", (ws) => {
  sendState(ws);

  ws.on("message", (raw) => {
    try {
      const message = JSON.parse(raw.toString());

      if (message.type === "add_task") {
        const id = crypto.randomUUID();
        const columnId = message.columnId || "todo";
        const col = state.columns.find(c => c.id === columnId);
        if (!col) return;

        state.tasks[id] = {
          id,
          title: String(message.title || "Untitled Task"),
          description: String(message.description || ""),
        };
        col.taskIds.push(id);

        broadcast(wss, { type: "state", state });
      }

      if (message.type === "move_task") {
        moveTask({
          taskId: message.taskId,
          fromColumnId: message.fromColumnId,
          toColumnId: message.toColumnId,
          toIndex: message.toIndex,
        });

        broadcast(wss, { type: "state", state });
      }

      if (message.type === "reorder_task") {
        reorderTaskWithinColumn({
          taskId: message.taskId,
          columnId: message.columnId,
          toIndex: message.toIndex,
        });

        broadcast(wss, { type: "state", state });
      }
    } catch (err) {
      console.error("Invalid message", err);
    }
  });
});

server.listen(PORT, () => {
  console.log(\`Server running at http://localhost:\${PORT}\`);
});
