          <button type="button" class="secondary" id="seedBtn">Add Sample Tasks</button>
          <button type="button" class="danger" id="clearBtn">Clear Board</button>
        </form>
      </div>
      <div class="toolbar-right">
        <div class="status" id="statusText">Ready</div>
      </div>
    </div>

    <section class="board" id="board">
      <div class="column" data-status="todo">
        <div class="column-header">
          <div class="column-title">To Do</div>
          <div class="count" id="count-todo">0</div>
        </div>
        <div class="task-list" id="todo"></div>
      </div>

      <div class="column" data-status="doing">
        <div class="column-header">
          <div class="column-title">Doing</div>
          <div class="count" id="count-doing">0</div>
        </div>
        <div class="task-list" id="doing"></div>
      </div>

      <div class="column" data-status="done">
        <div class="column-header">
          <div class="column-title">Done</div>
          <div class="count" id="count-done">0</div>
        </div>
        <div class="task-list" id="done"></div>
      </div>
    </section>

    <div class="footer-note">
      Prototype notes: uses localStorage for persistence and BroadcastChannel for same-browser real-time sync.
    </div>
  </main>

  <script>
    const STORAGE_KEY = "pm_board_tasks_v1";
    const CHANNEL_NAME = "pm_board_channel_v1";

    const state = {
      tasks: loadTasks(),
      userId: generateId(),
    };

    const channel = ("BroadcastChannel" in window)
      ? new BroadcastChannel(CHANNEL_NAME)
      : null;

    const statusText = document.getElementById("statusText");
    const taskForm = document.getElementById("taskForm");
    const titleInput = document.getElementById("titleInput");
    const descInput = document.getElementById("descInput");
    const statusInput = document.getElementById("statusInput");
    const seedBtn = document.getElementById("seedBtn");
    const clearBtn = document.getElementById("clearBtn");

    function generateId() {
      return Math.random().toString(36).slice(2) + Date.now().toString(36);
    }

    function now() {
      return new Date().toISOString();
    }

    function loadTasks() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? JSON.parse(raw) : [];
      } catch {
        return [];
      }
    }

    function saveTasks() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state.tasks));
    }

    function setStatus(message) {
      statusText.textContent = message;
    }

    function broadcast(type, payload) {
      if (!channel) return;
      channel.postMessage({
        type,
        payload,
        sourceUserId: state.userId,
        sentAt: now()
      });
    }

    function syncAll() {
      saveTasks();
      render();
      broadcast("SYNC_ALL", { tasks: state.tasks });
    }

    function addTask(title, description, status = "todo") {
      state.tasks.push({
        id: generateId(),
        title: title.trim(),
        description: description.trim(),
        status,
        createdAt: now(),
        updatedAt: now()
      });
      setStatus("Task added");
      syncAll();
    }

    function updateTaskStatus(taskId, newStatus) {
      const task = state.tasks.find(t => t.id === taskId);
      if (!task) return;
      task.status = newStatus;
      task.updatedAt = now();
      setStatus(`Moved "${task.title}" to ${labelForStatus(newStatus)}`);
      syncAll();
    }

    function deleteTask(taskId) {
      const task = state.tasks.find(t => t.id === taskId);
      state.tasks = state.tasks.filter(t => t.id !== taskId);
      setStatus(task ? `Deleted "${task.title}"` : "Task deleted");
      syncAll();
    }

    function labelForStatus(status) {
      return {
        todo: "To Do",
        doing: "Doing",
        done: "Done"
      }[status] || status;
    }

    function escapeHtml(str) {
      return str
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    function render() {
      ["todo", "doing", "done"].forEach(status => {
        const container = document.getElementById(status);
        container.innerHTML = "";

        const tasks = state.tasks
          .filter(task => task.status === status)
          .sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));

        document.getElementById(`count-${status}`).textContent = tasks.length;

        for (const task of tasks) {
          const el = document.createElement("article");
          el.className = "task";
          el.draggable = true;
          el.dataset.taskId = task.id;
          el.innerHTML = `
            <h3>${escapeHtml(task.title)}</h3>
            <p>${escapeHtml(task.description || "No description")}</p>
            <div class="task-meta">
              <span class="badge">Updated: ${new Date(task.updatedAt).toLocaleString()}</span>
              <div class="task-actions">
                <button class="secondary" data-action="edit">Edit</button>
                <button class="danger" data-action="delete">Delete</button>
              </div>
            </div>
          `;

          el.addEventListener("dragstart", onDragStart);
          el.addEventListener("dragend", onDragEnd);

          el.querySelector('[data-action="delete"]').addEventListener("click", () => {
            deleteTask(task.id);
          });

          el.querySelector('[data-action="edit"]').addEventListener("click", () => {
            editTask(task.id);
          });

          container.appendChild(el);
        }
      });
    }

    function editTask(taskId) {
      const task = state.tasks.find(t => t.id === taskId);
      if (!task) return;

      const newTitle = prompt("Edit title:", task.title);
      if (newTitle === null) return;

      const newDescription = prompt("Edit description:", task.description);
      if (newDescription === null) return;

      task.title = newTitle.trim() || task.title;
      task.description = newDescription.trim();
      task.updatedAt = now();

      setStatus(`Updated "${task.title}"`);
      syncAll();
    }

    let draggedTaskId = null;

    function onDragStart(e) {
      draggedTaskId = e.currentTarget.dataset.taskId;
      e.currentTarget.classList.add("dragging");
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", draggedTaskId);
    }

    function onDragEnd(e) {
      e.currentTarget.classList.remove("dragging");
      document.querySelectorAll(".column").forEach(col => col.classList.remove("drag-over"));
    }

    document.querySelectorAll(".column").forEach(column => {
      column.addEventListener("dragover", (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
        column.classList.add("drag-over");
      });

      column.addEventListener("dragleave", () => {
        column.classList.remove("drag-over");
      });

      column.addEventListener("drop", (e) => {
        e.preventDefault();
        column.classList.remove("drag-over");

        const taskId = e.dataTransfer.getData("text/plain") || draggedTaskId;
        const newStatus = column.dataset.status;
        if (taskId && newStatus) {
          updateTaskStatus(taskId, newStatus);
        }
      });
    });

    taskForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const title = titleInput.value.trim();
      const description = descInput.value.trim();
      const status = statusInput.value;

      if (!title) return;

      addTask(title, description, status);
      taskForm.reset();
      statusInput.value = "todo";
      titleInput.focus();
    });

    seedBtn.addEventListener("click", () => {
      if (state.tasks.length > 0 && !confirm("Add sample tasks to existing board?")) return;

      addTask("Design homepage", "Create wireframes and hero section layout", "todo");
      addTask("Implement auth flow", "Set up login, logout, and route protection", "doing");
      addTask("Deploy staging build", "Push latest stable version to staging environment", "done");
      setStatus("Sample tasks added");
    });

    clearBtn.addEventListener("click", () => {
      if (!confirm("Clear all tasks?")) return;
      state.tasks = [];
      setStatus("Board cleared");
      syncAll();
    });

    if (channel) {
      channel.onmessage = (event) => {
        const msg = event.data;
        if (!msg || msg.sourceUserId === state.userId) return;

        if (msg.type === "SYNC_ALL" && msg.payload?.tasks) {
          state.tasks = msg.payload.tasks;
          saveTasks();
          render();
          setStatus("Received real-time update");
        }
      };
    } else {
      setStatus("BroadcastChannel not supported; real-time tab sync disabled");
    }

    window.addEventListener("storage", (event) => {
      if (event.key === STORAGE_KEY) {
        state.tasks = loadTasks();
        render();
        setStatus("Storage sync update received");
      }
    });

    render();
  </script>
</body>
</html>
```

### How to use
1. Save as `index.html`
2. Open in your browser
3. Add tasks and drag them between columns
4. Open the same file in another tab to see live sync updates

### Limitations of this prototype
- Real-time works only across tabs/windows on the same browser/device
- No authentication
- No backend or shared database
- Simple prompt-based editing
- No conflict resolution for simultaneous edits

