import express from "express";
import http from "http";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";

type ColumnId = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  description: string;
};

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.static(path.join(__dirname, "public")));
app.use("/src", express.static(path.join(__dirname, "src")));

let board: BoardState = {
  columns: {
    todo: [
      { id: "1", title: "Set up project", description: "Initialize repository and tooling" },
      { id: "2", title: "Design UI", description: "Create wireframes for board layout" }
    ],
    doing: [
      { id: "3", title: "Build drag and drop", description: "Implement task movement between columns" }
    ],
    done: [
      { id: "4", title: "Define requirements", description: "Gather app requirements" }
    ]
  }
};

function broadcast(data: unknown) {
  const message = JSON.stringify(data);
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  }
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "board_state", payload: board }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "move_task") {
        const { taskId, fromColumn, toColumn, toIndex } = msg.payload as {
          taskId: string;
          fromColumn: ColumnId;
          toColumn: ColumnId;
          toIndex: number;
        };

        const source = board.columns[fromColumn];
        const target = board.columns[toColumn];
        const taskIndex = source.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = source.splice(taskIndex, 1);
        target.splice(toIndex, 0, task);

        broadcast({ type: "board_state", payload: board });
      }

      if (msg.type === "create_task") {
        const { columnId, title, description } = msg.payload as {
          columnId: ColumnId;
          title: string;
          description: string;
        };

        const task: Task = {
          id: Date.now().toString(),
          title,
          description
        };

        board.columns[columnId].push(task);
        broadcast({ type: "board_state", payload: board });
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

app.get("/", (_, res) => {
  res.sendFile(path.join(__dirname, "public", "index.html"));
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
