import React, { useEffect, useMemo, useState } from "react";

type ColumnId = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  description: string;
};

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

type WSMessage =
  | { type: "board_state"; payload: BoardState }
  | {
      type: "move_task";
      payload: {
        taskId: string;
        fromColumn: ColumnId;
        toColumn: ColumnId;
        toIndex: number;
      };
    }
  | {
      type: "create_task";
      payload: {
        columnId: ColumnId;
        title: string;
        description: string;
      };
    };

const columnLabels: Record<ColumnId, string> = {
  todo: "To Do",
  doing: "Doing",
  done: "Done"
};

export function App() {
  const [board, setBoard] = useState<BoardState>({
    columns: { todo: [], doing: [], done: [] }
  });

  const socket = useMemo(() => new WebSocket(`ws://${window.location.host}`), []);

  useEffect(() => {
    socket.onmessage = (event) => {
      const msg: WSMessage = JSON.parse(event.data);
      if (msg.type === "board_state") {
        setBoard(msg.payload);
      }
    };

    return () => socket.close();
  }, [socket]);

  const handleDrop = (
    e: React.DragEvent<HTMLDivElement>,
    toColumn: ColumnId,
    toIndex: number
  ) => {
    e.preventDefault();
    const raw = e.dataTransfer.getData("text/plain");
    const { taskId, fromColumn } = JSON.parse(raw) as {
      taskId: string;
      fromColumn: ColumnId;
    };

    socket.send(
      JSON.stringify({
        type: "move_task",
        payload: { taskId, fromColumn, toColumn, toIndex }
      } satisfies WSMessage)
    );
  };

  const handleCreateTask = (columnId: ColumnId) => {
    const title = prompt("Task title?");
    if (!title) return;
    const description = prompt("Task description?") || "";

    socket.send(
      JSON.stringify({
        type: "create_task",
        payload: { columnId, title, description }
      } satisfies WSMessage)
    );
  };

  return (
    <div className="app">
      <h1>Project Management Board</h1>
      <div className="board">
        {(Object.keys(board.columns) as ColumnId[]).map((columnId) => (
          <div
            key={columnId}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) =>
              handleDrop(e, columnId, board.columns[columnId].length)
            }
          >
            <div className="column-header">
              <h2>{columnLabels[columnId]}</h2>
              <button onClick={() => handleCreateTask(columnId)}>+ Add</button>
            </div>

            <div className="task-list">
              {board.columns[columnId].map((task, index) => (
                <div
                  key={task.id}
                  className="task"
                  draggable
                  onDragStart={(e) => {
                    e.dataTransfer.setData(
                      "text/plain",
                      JSON.stringify({
                        taskId: task.id,
                        fromColumn: columnId
                      })
                    );
                  }}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => {
                    e.stopPropagation();
                    handleDrop(e, columnId, index);
                  }}
                >
                  <h3>{task.title}</h3>
                  <p>{task.description}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
