## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";
import type {
  BoardState,
  ColumnId,
  CreateTaskPayload,
  MoveTaskPayload
} from "./types.js";

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: "*"
  }
});

const board: BoardState = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["t1", "t2"]
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: ["t3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    t1: { id: "t1", title: "Design landing page" },
    t2: { id: "t2", title: "Define sprint backlog" },
    t3: { id: "t3", title: "Set up auth flow" }
  }
};

function moveTask(payload: MoveTaskPayload) {
  const { taskId, fromColumnId, toColumnId, toIndex } = payload;

  const from = board.columns[fromColumnId];
  const to = board.columns[toColumnId];

  from.taskIds = from.taskIds.filter((id) => id !== taskId);

  const clampedIndex = Math.max(0, Math.min(toIndex, to.taskIds.length));
  to.taskIds.splice(clampedIndex, 0, taskId);
}

function createTask(payload: CreateTaskPayload) {
  const id = `t_${Date.now()}_${Math.floor(Math.random() * 10000)}`;
  board.tasks[id] = {
    id,
    title: payload.title,
    description: payload.description
  };
  board.columns[payload.columnId].taskIds.unshift(id);
}

app.get("/board", (_req, res) => {
  res.json(board);
});

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("task:create", (payload: CreateTaskPayload) => {
    createTask(payload);
    io.emit("board:update", board);
  });

  socket.on("task:move", (payload: MoveTaskPayload) => {
    moveTask(payload);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    // no-op
  });
});

const PORT = 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
