```tsx
import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  arrayMove,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { socket } from "./socket";
import type { BoardState, ColumnId, CreateTaskPayload } from "./types";

function App() {
  const [board, setBoard] = useState<BoardState | null>(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  useEffect(() => {
    fetch("http://localhost:4000/board")
      .then((r) => r.json())
      .then(setBoard);

    socket.on("board:init", setBoard);
    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:init", setBoard);
      socket.off("board:update", setBoard);
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columns = useMemo(() => {
    if (!board) return [];
    return (Object.keys(board.columns) as ColumnId[]).map((id) => board.columns[id]);
  }, [board]);

  if (!board) {
    return <div className="loading">Loading board...</div>;
  }

  function findColumnByTaskId(taskId: string): ColumnId | null {
    for (const columnId of Object.keys(board.columns) as ColumnId[]) {
      if (board.columns[columnId].taskIds.includes(taskId)) return columnId;
    }
    return null;
  }

  function handleDragOver(event: DragOverEvent) {
    const { active, over } = event;
    if (!over || !board) return;

    const activeTaskId = String(active.id);
    const overId = String(over.id);

    const fromColumnId = findColumnByTaskId(activeTaskId);
    const overColumnId = (Object.keys(board.columns) as ColumnId[]).includes(overId as ColumnId)
      ? (overId as ColumnId)
      : findColumnByTaskId(overId);

    if (!fromColumnId || !overColumnId) return;
    if (fromColumnId === overColumnId) return;

    const next = structuredClone(board);
    next.columns[fromColumnId].taskIds = next.columns[fromColumnId].taskIds.filter(
      (id) => id !== activeTaskId
    );

    const overTaskIndex = next.columns[overColumnId].taskIds.indexOf(overId);
    const insertIndex = overTaskIndex >= 0 ? overTaskIndex : next.columns[overColumnId].taskIds.length;

    next.columns[overColumnId].taskIds.splice(insertIndex, 0, activeTaskId);
    setBoard(next);
  }

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over || !board) return;

    const activeTaskId = String(active.id);
    const overId = String(over.id);

    const fromColumnId = findColumnByTaskId(activeTaskId);
    const targetColumnId = (Object.keys(board.columns) as ColumnId[]).includes(overId as ColumnId)
      ? (overId as ColumnId)
      : findColumnByTaskId(overId);

    if (!fromColumnId || !targetColumnId) return;

    const next = structuredClone(board);

    if (fromColumnId === targetColumnId) {
      const items = next.columns[fromColumnId].taskIds;
      const oldIndex = items.indexOf(activeTaskId);
      const newIndex = items.indexOf(overId);
      if (oldIndex >= 0 && newIndex >= 0 && oldIndex !== newIndex) {
        next.columns[fromColumnId].taskIds = arrayMove(items, oldIndex, newIndex);
        setBoard(next);
        socket.emit("task:move", {
          taskId: activeTaskId,
          fromColumnId,
          toColumnId: targetColumnId,
          toIndex: newIndex
        });
      }
      return;
    }

    const toIndex = next.columns[targetColumnId].taskIds.indexOf(activeTaskId);
    setBoard(next);
    socket.emit("task:move", {
      taskId: activeTaskId,
      fromColumnId,
      toColumnId: targetColumnId,
      toIndex: toIndex < 0 ? next.columns[targetColumnId].taskIds.length : toIndex
    });
  }

  function addTask(columnId: ColumnId) {
    const title = newTaskTitle.trim();
    if (!title) return;

    const payload: CreateTaskPayload = { columnId, title };
    socket.emit("task:create", payload);
    setNewTaskTitle("");
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
        <div className="creator">
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <button onClick={() => addTask("todo")}>Add to To Do</button>
        </div>
      </header>

      <DndContext sensors={sensors} onDragOver={handleDragOver} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              id={column.id}
              title={column.title}
              tasks={column.taskIds.map((taskId) => board.tasks[taskId])}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function Column({
  id,
  title,
  tasks
}: {
  id: ColumnId;
  title: string;
  tasks: { id: string; title: string }[];
}) {
  return (
    <div className="column" id={id}>
      <h2>{title}</h2>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="taskList">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task }: { task: { id: string; title: string } }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="taskCard" {...attributes} {...listeners}>
      {task.title}
    </div>
  );
}

export default App;
```

