## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { WebSocketServer, WebSocket } from "ws";
import { v4 as uuid } from "uuid";

type Task = {
  id: string;
  title: string;
  description: string;
  columnId: string;
  order: number;
};

type Column = {
  id: string;
  title: string;
  order: number;
};

type Board = {
  id: string;
  name: string;
  columns: Column[];
  tasks: Task[];
};

type ClientMessage =
  | { type: "join_board"; boardId: string }
  | { type: "create_task"; boardId: string; columnId: string; title: string }
  | {
      type: "update_task";
      boardId: string;
      taskId: string;
      patch: Partial<Pick<Task, "title" | "description">>;
    }
  | { type: "delete_task"; boardId: string; taskId: string }
  | {
      type: "move_task";
      boardId: string;
      taskId: string;
      toColumnId: string;
      toIndex: number;
    }
  | { type: "create_board"; name: string };

type ServerMessage =
  | { type: "boards"; boards: Pick<Board, "id" | "name">[] }
  | { type: "board_state"; board: Board }
  | { type: "error"; message: string };

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const wss = new WebSocketServer({ server: httpServer });

const boards = new Map<string, Board>();

function seedBoard(): Board {
  const board: Board = {
    id: uuid(),
    name: "Product Roadmap",
    columns: [
      { id: "todo", title: "To Do", order: 0 },
      { id: "doing", title: "In Progress", order: 1 },
      { id: "done", title: "Done", order: 2 }
    ],
    tasks: [
      {
        id: uuid(),
        title: "Design landing page",
        description: "Create wireframes and hero section",
        columnId: "todo",
        order: 0
      },
      {
        id: uuid(),
        title: "Set up API server",
        description: "Bootstrap Express + WebSocket backend",
        columnId: "doing",
        order: 0
      },
      {
        id: uuid(),
        title: "Project kickoff",
        description: "Align team on scope and milestones",
        columnId: "done",
        order: 0
      }
    ]
  };
  boards.set(board.id, board);
  return board;
}

const initialBoard = seedBoard();

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.get("/boards", (_req, res) => {
  res.json(
    Array.from(boards.values()).map((b) => ({
      id: b.id,
      name: b.name
    }))
  );
});

app.get("/boards/:boardId", (req, res) => {
  const board = boards.get(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

const boardRooms = new Map<string, Set<WebSocket>>();

function send(ws: WebSocket, message: ServerMessage) {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(message));
  }
}

function broadcastBoard(boardId: string) {
  const board = boards.get(boardId);
  if (!board) return;
  const room = boardRooms.get(boardId);
  if (!room) return;

  const payload: ServerMessage = { type: "board_state", board };

  for (const ws of room) {
    send(ws, payload);
  }
}

function broadcastBoardsList() {
  const payload: ServerMessage = {
    type: "boards",
    boards: Array.from(boards.values()).map(({ id, name }) => ({ id, name }))
  };

  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(JSON.stringify(payload));
    }
  }
}

function normalizeTaskOrders(board: Board, columnId: string) {
  const tasks = board.tasks
    .filter((t) => t.columnId === columnId)
    .sort((a, b) => a.order - b.order);

  tasks.forEach((task, index) => {
    task.order = index;
  });
}

function moveTask(board: Board, taskId: string, toColumnId: string, toIndex: number) {
  const task = board.tasks.find((t) => t.id === taskId);
  if (!task) return;

  const fromColumnId = task.columnId;

  const sourceTasks = board.tasks
    .filter((t) => t.columnId === fromColumnId && t.id !== taskId)
    .sort((a, b) => a.order - b.order);

  const targetTasks =
    fromColumnId === toColumnId
      ? sourceTasks
      : board.tasks
          .filter((t) => t.columnId === toColumnId)
          .sort((a, b) => a.order - b.order);

  task.columnId = toColumnId;

  const safeIndex = Math.max(0, Math.min(toIndex, targetTasks.length));
  targetTasks.splice(safeIndex, 0, task);

  targetTasks.forEach((t, i) => {
    t.columnId = toColumnId;
    t.order = i;
  });

  if (fromColumnId !== toColumnId) {
    sourceTasks.forEach((t, i) => {
      t.columnId = fromColumnId;
      t.order = i;
    });
  }
}

wss.on("connection", (ws) => {
  send(ws, {
    type: "boards",
    boards: Array.from(boards.values()).map(({ id, name }) => ({ id, name }))
  });

  let joinedBoardId: string | null = null;

  ws.on("message", (data) => {
    try {
      const msg = JSON.parse(data.toString()) as ClientMessage;

      switch (msg.type) {
        case "join_board": {
          if (!boards.has(msg.boardId)) {
            send(ws, { type: "error", message: "Board not found" });
            return;
          }

          if (joinedBoardId) {
            boardRooms.get(joinedBoardId)?.delete(ws);
          }

          joinedBoardId = msg.boardId;

          if (!boardRooms.has(msg.boardId)) {
            boardRooms.set(msg.boardId, new Set());
          }

          boardRooms.get(msg.boardId)!.add(ws);
          send(ws, { type: "board_state", board: boards.get(msg.boardId)! });
          break;
        }

        case "create_board": {
          const board: Board = {
            id: uuid(),
            name: msg.name.trim() || "Untitled Board",
            columns: [
              { id: "todo", title: "To Do", order: 0 },
              { id: "doing", title: "In Progress", order: 1 },
              { id: "done", title: "Done", order: 2 }
            ],
            tasks: []
          };
          boards.set(board.id, board);
          broadcastBoardsList();
          break;
        }

        case "create_task": {
          const board = boards.get(msg.boardId);
          if (!board) return;

          const order =
            board.tasks.filter((t) => t.columnId === msg.columnId).length;

          board.tasks.push({
            id: uuid(),
            title: msg.title.trim() || "Untitled Task",
            description: "",
            columnId: msg.columnId,
            order
          });

          broadcastBoard(msg.boardId);
          break;
        }

        case "update_task": {
          const board = boards.get(msg.boardId);
          if (!board) return;

          const task = board.tasks.find((t) => t.id === msg.taskId);
          if (!task) return;

          if (typeof msg.patch.title === "string") task.title = msg.patch.title;
          if (typeof msg.patch.description === "string") task.description = msg.patch.description;

          broadcastBoard(msg.boardId);
          break;
        }

        case "delete_task": {
          const board = boards.get(msg.boardId);
          if (!board) return;

          const task = board.tasks.find((t) => t.id === msg.taskId);
          if (!task) return;

          const columnId = task.columnId;

          board.tasks = board.tasks.filter((t) => t.id !== msg.taskId);
          normalizeTaskOrders(board, columnId);

          broadcastBoard(msg.boardId);
          break;
        }

        case "move_task": {
          const board = boards.get(msg.boardId);
          if (!board) return;

          const task = board.tasks.find((t) => t.id === msg.taskId);
          if (!task) return;

          const fromColumnId = task.columnId;
          moveTask(board, msg.taskId, msg.toColumnId, msg.toIndex);
          normalizeTaskOrders(board, fromColumnId);
          normalizeTaskOrders(board, msg.toColumnId);

          broadcastBoard(msg.boardId);
          break;
        }
      }
    } catch {
      send(ws, { type: "error", message: "Invalid message" });
    }
  });

  ws.on("close", () => {
    if (joinedBoardId) {
      boardRooms.get(joinedBoardId)?.delete(ws);
    }
  });
});

const PORT = 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
  console.log(`Seed board ID: ${initialBoard.id}`);
});
```

