```tsx
import { useEffect, useMemo, useRef, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

type Task = {
  id: string;
  title: string;
  description: string;
  columnId: string;
  order: number;
};

type Column = {
  id: string;
  title: string;
  order: number;
};

type Board = {
  id: string;
  name: string;
  columns: Column[];
  tasks: Task[];
};

type ServerMessage =
  | { type: "boards"; boards: { id: string; name: string }[] }
  | { type: "board_state"; board: Board }
  | { type: "error"; message: string };

const API_BASE = "http://localhost:4000";
const WS_URL = "ws://localhost:4000";

function TaskCard({
  task,
  onEdit,
  onDelete
}: {
  task: Task;
  onEdit: (task: Task) => void;
  onDelete: (taskId: string) => void;
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.6 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card">
      <div className="task-drag-handle" {...attributes} {...listeners}>
        ⋮⋮
      </div>
      <div className="task-main">
        <div className="task-title">{task.title}</div>
        {task.description && <div className="task-desc">{task.description}</div>}
      </div>
      <div className="task-actions">
        <button onClick={() => onEdit(task)}>Edit</button>
        <button className="danger" onClick={() => onDelete(task.id)}>Delete</button>
      </div>
    </div>
  );
}

function ColumnView({
  column,
  tasks,
  onAddTask,
  onEditTask,
  onDeleteTask
}: {
  column: Column;
  tasks: Task[];
  onAddTask: (columnId: string) => void;
  onEditTask: (task: Task) => void;
  onDeleteTask: (taskId: string) => void;
}) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
        <button onClick={() => onAddTask(column.id)}>+ Task</button>
      </div>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onEdit={onEditTask}
              onDelete={onDeleteTask}
            />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [boards, setBoards] = useState<{ id: string; name: string }[]>([]);
  const [currentBoardId, setCurrentBoardId] = useState<string>("");
  const [board, setBoard] = useState<Board | null>(null);

  const wsRef = useRef<WebSocket | null>(null);

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetch(`${API_BASE}/boards`)
      .then((res) => res.json())
      .then((data: { id: string; name: string }[]) => {
        setBoards(data);
        if (data[0]) setCurrentBoardId(data[0].id);
      });

    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onmessage = (event) => {
      const message = JSON.parse(event.data) as ServerMessage;

      if (message.type === "boards") {
        setBoards(message.boards);
        if (!currentBoardId && message.boards[0]) {
          setCurrentBoardId(message.boards[0].id);
        }
      } else if (message.type === "board_state") {
        setBoard(message.board);
      } else if (message.type === "error") {
        alert(message.message);
      }
    };

    return () => ws.close();
  }, []);

  useEffect(() => {
    if (!currentBoardId || !wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      const interval = setInterval(() => {
        if (currentBoardId && wsRef.current?.readyState === WebSocket.OPEN) {
          wsRef.current.send(JSON.stringify({ type: "join_board", boardId: currentBoardId }));
          clearInterval(interval);
        }
      }, 200);
      return () => clearInterval(interval);
    }

    wsRef.current.send(JSON.stringify({ type: "join_board", boardId: currentBoardId }));
  }, [currentBoardId]);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result: Record<string, Task[]> = {};
    for (const column of board.columns) {
      result[column.id] = board.tasks
        .filter((t) => t.columnId === column.id)
        .sort((a, b) => a.order - b.order);
    }
    return result;
  }, [board]);

  function send(message: unknown) {
    wsRef.current?.send(JSON.stringify(message));
  }

  function handleAddTask(columnId: string) {
    if (!board) return;
    const title = prompt("Task title?");
    if (!title) return;

    send({
      type: "create_task",
      boardId: board.id,
      columnId,
      title
    });
  }

  function handleEditTask(task: Task) {
    if (!board) return;

    const title = prompt("Edit title", task.title);
    if (title === null) return;

    const description = prompt("Edit description", task.description);
    if (description === null) return;

    send({
      type: "update_task",
      boardId: board.id,
      taskId: task.id,
      patch: { title, description }
    });
  }

  function handleDeleteTask(taskId: string) {
    if (!board) return;
    send({
      type: "delete_task",
      boardId: board.id,
      taskId
    });
  }

  function handleCreateBoard() {
    const name = prompt("Board name?");
    if (!name) return;
    send({ type: "create_board", name });
  }

  function findTask(taskId: string) {
    if (!board) return null;
    return board.tasks.find((t) => t.id === taskId) || null;
  }

  function handleDragEnd(event: DragEndEvent) {
    if (!board) return;

    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const activeTask = findTask(String(active.id));
    const overTask = findTask(String(over.id));
    if (!activeTask) return;

    if (overTask) {
      const destinationTasks = (tasksByColumn[overTask.columnId] || []).sort((a, b) => a.order - b.order);
      const toIndex = destinationTasks.findIndex((t) => t.id === overTask.id);

      send({
        type: "move_task",
        boardId: board.id,
        taskId: activeTask.id,
        toColumnId: overTask.columnId,
        toIndex
      });
    }
  }

  return (
    <div className="app-shell">
      <aside className="sidebar">
        <div className="sidebar-header">
          <h2>Boards</h2>
          <button onClick={handleCreateBoard}>+ Board</button>
        </div>
        <div className="board-list">
          {boards.map((b) => (
            <button
              key={b.id}
              className={`board-item ${b.id === currentBoardId ? "active" : ""}`}
              onClick={() => setCurrentBoardId(b.id)}
            >
              {b.name}
            </button>
          ))}
        </div>
      </aside>

      <main className="main-content">
        <header className="topbar">
          <h1>{board?.name || "Loading..."}</h1>
          <span className="status">● Real-time connected</span>
        </header>

        {board && (
          <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
            <div className="board-grid">
              {board.columns
                .slice()
                .sort((a, b) => a.order - b.order)
                .map((column) => (
                  <ColumnView
                    key={column.id}
                    column={column}
                    tasks={tasksByColumn[column.id] || []}
                    onAddTask={handleAddTask}
                    onEditTask={handleEditTask}
                    onDeleteTask={handleDeleteTask}
                  />
                ))}
            </div>
          </DndContext>
        )}
      </main>
    </div>
  );
}
```

