```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

type ColumnId = "todo" | "inprogress" | "done";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

let board: BoardState = {
  columns: {
    todo: [
      { id: uuidv4(), title: "Set up project repo" },
      { id: uuidv4(), title: "Design board layout" }
    ],
    inprogress: [{ id: uuidv4(), title: "Implement socket server" }],
    done: [{ id: uuidv4(), title: "Define MVP scope" }]
  }
};

app.get("/board", (_req, res) => {
  res.json(board);
});

app.post("/tasks", (req, res) => {
  const { title, description, columnId } = req.body as {
    title: string;
    description?: string;
    columnId: ColumnId;
  };

  if (!title || !columnId || !board.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task input" });
  }

  const task: Task = {
    id: uuidv4(),
    title,
    description
  };

  board.columns[columnId].push(task);
  io.emit("board:update", board);

  res.status(201).json(task);
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:move", (payload: {
    taskId: string;
    sourceColumnId: ColumnId;
    destinationColumnId: ColumnId;
    destinationIndex: number;
  }) => {
    const {
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    } = payload;

    const sourceTasks = board.columns[sourceColumnId];
    const destTasks = board.columns[destinationColumnId];

    const taskIndex = sourceTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = sourceTasks.splice(taskIndex, 1);
    destTasks.splice(destinationIndex, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:create", (payload: {
    title: string;
    description?: string;
    columnId: ColumnId;
  }) => {
    const { title, description, columnId } = payload;
    if (!title || !board.columns[columnId]) return;

    const task: Task = {
      id: uuidv4(),
      title,
      description
    };

    board.columns[columnId].push(task);
    io.emit("board:update", board);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

