import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type ColumnId = "todo" | "inprogress" | "done";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

const socket: Socket = io("http://localhost:4000");

const columnOrder: { id: ColumnId; label: string }[] = [
  { id: "todo", label: "To Do" },
  { id: "inprogress", label: "In Progress" },
  { id: "done", label: "Done" }
];

export default function App() {
  const [board, setBoard] = useState<BoardState>({
    columns: {
      todo: [],
      inprogress: [],
      done: []
    }
  });

  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskColumn, setNewTaskColumn] = useState<ColumnId>("todo");
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);
  const [sourceColumnId, setSourceColumnId] = useState<ColumnId | null>(null);

  useEffect(() => {
    fetch("http://localhost:4000/board")
      .then((res) => res.json())
      .then((data: BoardState) => setBoard(data));

    socket.on("board:update", (updatedBoard: BoardState) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const totalTasks = useMemo(() => {
    return Object.values(board.columns).reduce((sum, tasks) => sum + tasks.length, 0);
  }, [board]);

  const handleCreateTask = () => {
    if (!newTaskTitle.trim()) return;

    socket.emit("task:create", {
      title: newTaskTitle,
      columnId: newTaskColumn
    });

    setNewTaskTitle("");
  };

  const handleDragStart = (taskId: string, columnId: ColumnId) => {
    setDraggedTaskId(taskId);
    setSourceColumnId(columnId);
  };

  const handleDrop = (destinationColumnId: ColumnId, destinationIndex: number) => {
    if (!draggedTaskId || !sourceColumnId) return;

    socket.emit("task:move", {
      taskId: draggedTaskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    });

    setDraggedTaskId(null);
    setSourceColumnId(null);
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
        <p>{totalTasks} tasks total</p>
      </header>

      <section className="task-form">
        <input
          type="text"
          placeholder="New task title"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
        />
        <select
          value={newTaskColumn}
          onChange={(e) => setNewTaskColumn(e.target.value as ColumnId)}
        >
          {columnOrder.map((col) => (
            <option key={col.id} value={col.id}>
              {col.label}
            </option>
          ))}
        </select>
        <button onClick={handleCreateTask}>Add Task</button>
      </section>

      <main className="board">
        {columnOrder.map((column) => (
          <div
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id, board.columns[column.id].length)}
          >
            <h2>{column.label}</h2>
            <div className="task-list">
              {board.columns[column.id].map((task, index) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={() => handleDragStart(task.id, column.id)}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => {
                    e.stopPropagation();
                    handleDrop(column.id, index);
                  }}
                >
                  {task.title}
                </div>
              ))}
            </div>
          </div>
        ))}
      </main>
    </div>
  );
}
```

