```ts
import express from 'express';
import cors from 'cors';
import { WebSocketServer, WebSocket } from 'ws';
import { createServer } from 'http';

type Task = {
  id: string;
  title: string;
  description?: string;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
};

const app = express();
app.use(cors());
app.use(express.json());

const board: BoardState = {
  tasks: {
    'task-1': { id: 'task-1', title: 'Set up project repo' },
    'task-2': { id: 'task-2', title: 'Design board layout' },
    'task-3': { id: 'task-3', title: 'Implement websocket sync' },
    'task-4': { id: 'task-4', title: 'Add drag and drop' }
  },
  columns: {
    backlog: {
      id: 'backlog',
      title: 'Backlog',
      taskIds: ['task-1', 'task-2']
    },
    inprogress: {
      id: 'inprogress',
      title: 'In Progress',
      taskIds: ['task-3']
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: ['task-4']
    }
  },
  columnOrder: ['backlog', 'inprogress', 'done']
};

app.get('/board', (_req, res) => {
  res.json(board);
});

app.post('/tasks', (req, res) => {
  const { title, description, columnId } = req.body as {
    title: string;
    description?: string;
    columnId: string;
  };

  if (!title || !columnId || !board.columns[columnId]) {
    return res.status(400).json({ error: 'Invalid payload' });
  }

  const id = `task-${Date.now()}`;
  board.tasks[id] = { id, title, description };
  board.columns[columnId].taskIds.push(id);

  broadcast({
    type: 'board:update',
    payload: board
  });

  res.status(201).json(board.tasks[id]);
});

app.post('/move', (req, res) => {
  const { taskId, sourceColumnId, targetColumnId, targetIndex } = req.body as {
    taskId: string;
    sourceColumnId: string;
    targetColumnId: string;
    targetIndex: number;
  };

  const source = board.columns[sourceColumnId];
  const target = board.columns[targetColumnId];

  if (!source || !target || !board.tasks[taskId]) {
    return res.status(400).json({ error: 'Invalid move' });
  }

  source.taskIds = source.taskIds.filter(id => id !== taskId);
  target.taskIds.splice(targetIndex, 0, taskId);

  broadcast({
    type: 'board:update',
    payload: board
  });

  res.json({ ok: true });
});

const server = createServer(app);
const wss = new WebSocketServer({ server });

function broadcast(message: unknown) {
  const data = JSON.stringify(message);
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  }
}

wss.on('connection', (ws) => {
  ws.send(JSON.stringify({ type: 'board:init', payload: board }));
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

