## `client/src/App.tsx`
```tsx
import { useEffect, useMemo, useState } from 'react';
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter
} from '@dnd-kit/core';
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { connectBoardSocket, createTask, fetchBoard, moveTask } from './api';
import type { BoardState, Task, WsMessage } from './types';

function TaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, transition } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      {task.title}
    </div>
  );
}

function ColumnView({
  id,
  title,
  tasks
}: {
  id: string;
  title: string;
  tasks: Task[];
}) {
  return (
    <div className="column" data-column-id={id}>
      <h2>{title}</h2>
      <SortableContext items={tasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState<BoardState | null>(null);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetchBoard().then(setBoard).catch(console.error);

    const ws = connectBoardSocket((msg) => {
      const message = msg as WsMessage;
      if (message.type === 'board:init' || message.type === 'board:update') {
        setBoard(message.payload);
      }
    });

    return () => ws.close();
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map(columnId => {
      const column = board.columns[columnId];
      const tasks = column.taskIds.map(taskId => board.tasks[taskId]).filter(Boolean);
      return { ...column, tasks };
    });
  }, [board]);

  async function handleAddTask() {
    if (!newTaskTitle.trim()) return;
    await createTask({
      title: newTaskTitle,
      columnId: 'backlog'
    });
    setNewTaskTitle('');
  }

  async function handleDragEnd(event: DragEndEvent) {
    if (!board) return;
    const { active, over } = event;
    if (!over) return;
    if (active.id === over.id) return;

    let sourceColumnId: string | null = null;
    let targetColumnId: string | null = null;
    let targetIndex = 0;

    for (const columnId of board.columnOrder) {
      const taskIds = board.columns[columnId].taskIds;
      if (taskIds.includes(String(active.id))) sourceColumnId = columnId;
      if (taskIds.includes(String(over.id))) {
        targetColumnId = columnId;
        targetIndex = taskIds.indexOf(String(over.id));
      }
    }

    if (!sourceColumnId || !targetColumnId) return;

    await moveTask({
      taskId: String(active.id),
      sourceColumnId,
      targetColumnId,
      targetIndex
    });
  }

  if (!board) return <div className="app">Loading...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Board</h1>
        <div className="new-task">
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <button onClick={handleAddTask}>Add Task</button>
        </div>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map(column => (
            <ColumnView
              key={column.id}
              id={column.id}
              title={column.title}
              tasks={column.tasks}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

