```ts
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { WebSocketServer, WebSocket } from "ws";
import { v4 as uuid } from "uuid";

type Task = {
  id: string;
  title: string;
  description: string;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type Board = {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
};

type ClientMessage =
  | {
      type: "ADD_TASK";
      columnId: string;
      title: string;
      description?: string;
    }
  | {
      type: "MOVE_TASK";
      taskId: string;
      sourceColumnId: string;
      destinationColumnId: string;
      sourceIndex: number;
      destinationIndex: number;
    }
  | {
      type: "UPDATE_TASK";
      taskId: string;
      title: string;
      description: string;
    }
  | {
      type: "DELETE_TASK";
      taskId: string;
      columnId: string;
    };

type ServerMessage =
  | { type: "INIT"; board: Board }
  | { type: "BOARD_UPDATED"; board: Board };

const app = express();
app.use(cors());
app.use(express.json());

let board: Board = {
  tasks: {},
  columns: {
    todo: { id: "todo", title: "To Do", taskIds: [] },
    doing: { id: "doing", title: "In Progress", taskIds: [] },
    done: { id: "done", title: "Done", taskIds: [] }
  },
  columnOrder: ["todo", "doing", "done"]
};

// Seed data
const seed1 = uuid();
const seed2 = uuid();
board.tasks[seed1] = {
  id: seed1,
  title: "Design landing page",
  description: "Create first revision of project dashboard UI"
};
board.tasks[seed2] = {
  id: seed2,
  title: "Implement WebSocket sync",
  description: "Broadcast board updates to all connected clients"
};
board.columns.todo.taskIds.push(seed1);
board.columns.doing.taskIds.push(seed2);

app.get("/api/board", (_, res) => {
  res.json(board);
});

const server = createServer(app);
const wss = new WebSocketServer({ server });

function broadcast(message: ServerMessage) {
  const payload = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  });
}

function send(ws: WebSocket, message: ServerMessage) {
  ws.send(JSON.stringify(message));
}

wss.on("connection", (ws) => {
  send(ws, { type: "INIT", board });

  ws.on("message", (raw) => {
    const msg = JSON.parse(raw.toString()) as ClientMessage;

    switch (msg.type) {
      case "ADD_TASK": {
        const id = uuid();
        board.tasks[id] = {
          id,
          title: msg.title,
          description: msg.description || ""
        };
        board.columns[msg.columnId].taskIds.push(id);
        break;
      }

      case "MOVE_TASK": {
        const source = board.columns[msg.sourceColumnId];
        const destination = board.columns[msg.destinationColumnId];

        source.taskIds.splice(msg.sourceIndex, 1);
        destination.taskIds.splice(msg.destinationIndex, 0, msg.taskId);
        break;
      }

      case "UPDATE_TASK": {
        const task = board.tasks[msg.taskId];
        if (task) {
          task.title = msg.title;
          task.description = msg.description;
        }
        break;
      }

      case "DELETE_TASK": {
        delete board.tasks[msg.taskId];
        const column = board.columns[msg.columnId];
        column.taskIds = column.taskIds.filter((id) => id !== msg.taskId);
        break;
      }
    }

    broadcast({ type: "BOARD_UPDATED", board });
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

