# 7) Frontend app: `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useRef, useState } from "react";
import type { Board, ClientMessage, Task, ServerMessage } from "./types";

const WS_URL = "ws://localhost:4000";

export default function App() {
  const [board, setBoard] = useState<Board | null>(null);
  const [newTaskTitles, setNewTaskTitles] = useState<Record<string, string>>({});
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const wsRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data) as ServerMessage;
      if (msg.type === "INIT" || msg.type === "BOARD_UPDATED") {
        setBoard(msg.board);
      }
    };

    return () => ws.close();
  }, []);

  function send(message: ClientMessage) {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(message));
    }
  }

  const taskColumnLookup = useMemo(() => {
    if (!board) return {};
    const lookup: Record<string, string> = {};
    for (const columnId of board.columnOrder) {
      for (const taskId of board.columns[columnId].taskIds) {
        lookup[taskId] = columnId;
      }
    }
    return lookup;
  }, [board]);

  function addTask(columnId: string) {
    const title = (newTaskTitles[columnId] || "").trim();
    if (!title) return;
    send({ type: "ADD_TASK", columnId, title, description: "" });
    setNewTaskTitles((prev) => ({ ...prev, [columnId]: "" }));
  }

  function onDragStart(
    event: React.DragEvent<HTMLDivElement>,
    taskId: string,
    sourceColumnId: string,
    sourceIndex: number
  ) {
    event.dataTransfer.setData(
      "application/json",
      JSON.stringify({ taskId, sourceColumnId, sourceIndex })
    );
  }

  function onDrop(
    event: React.DragEvent<HTMLDivElement>,
    destinationColumnId: string,
    destinationIndex: number
  ) {
    event.preventDefault();
    const raw = event.dataTransfer.getData("application/json");
    if (!raw) return;

    const { taskId, sourceColumnId, sourceIndex } = JSON.parse(raw) as {
      taskId: string;
      sourceColumnId: string;
      sourceIndex: number;
    };

    send({
      type: "MOVE_TASK",
      taskId,
      sourceColumnId,
      destinationColumnId,
      sourceIndex,
      destinationIndex
    });
  }

  function saveTask() {
    if (!selectedTask) return;
    send({
      type: "UPDATE_TASK",
      taskId: selectedTask.id,
      title: selectedTask.title,
      description: selectedTask.description
    });
    setSelectedTask(null);
  }

  function deleteTask(taskId: string) {
    const columnId = taskColumnLookup[taskId];
    if (!columnId) return;
    send({ type: "DELETE_TASK", taskId, columnId });
    if (selectedTask?.id === taskId) setSelectedTask(null);
  }

  if (!board) {
    return <div className="loading">Connecting...</div>;
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Board</h1>
        <span className="status">Real-time collaboration enabled</span>
      </header>

      <main className="board">
        {board.columnOrder.map((columnId) => {
          const column = board.columns[columnId];
          const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

          return (
            <section
              key={column.id}
              className="column"
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => onDrop(e, column.id, tasks.length)}
            >
              <div className="column-header">
                <h2>{column.title}</h2>
                <span>{tasks.length}</span>
              </div>

              <div className="task-list">
                {tasks.map((task, index) => (
                  <div
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={(e) => onDragStart(e, task.id, column.id, index)}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={(e) => onDrop(e, column.id, index)}
                    onClick={() => setSelectedTask({ ...task })}
                  >
                    <h3>{task.title}</h3>
                    <p>{task.description || "No description"}</p>
                    <button
                      className="delete-btn"
                      onClick={(e) => {
                        e.stopPropagation();
                        deleteTask(task.id);
                      }}
                    >
                      Delete
                    </button>
                  </div>
                ))}
              </div>

              <div className="add-task">
                <input
                  value={newTaskTitles[column.id] || ""}
                  onChange={(e) =>
                    setNewTaskTitles((prev) => ({
                      ...prev,
                      [column.id]: e.target.value
                    }))
                  }
                  placeholder={`Add task to ${column.title}`}
                />
                <button onClick={() => addTask(column.id)}>Add</button>
              </div>
            </section>
          );
        })}
      </main>

      {selectedTask && (
        <div className="modal-backdrop" onClick={() => setSelectedTask(null)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h2>Edit Task</h2>
            <label>
              Title
              <input
                value={selectedTask.title}
                onChange={(e) =>
                  setSelectedTask({ ...selectedTask, title: e.target.value })
                }
              />
            </label>

            <label>
              Description
              <textarea
                rows={5}
                value={selectedTask.description}
                onChange={(e) =>
                  setSelectedTask({
                    ...selectedTask,
                    description: e.target.value
                  })
                }
              />
            </label>

            <div className="modal-actions">
              <button onClick={() => setSelectedTask(null)}>Cancel</button>
              <button onClick={saveTask}>Save</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
```

