# 2) `server.js`

```javascript
const express = require('express');
const http = require('http');
const path = require('path');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, 'public')));

const board = {
  columns: {
    todo: {
      id: 'todo',
      title: 'To Do',
      taskIds: ['task-1', 'task-2']
    },
    doing: {
      id: 'doing',
      title: 'Doing',
      taskIds: []
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  tasks: {
    'task-1': { id: 'task-1', title: 'Set up project' },
    'task-2': { id: 'task-2', title: 'Design board UI' }
  },
  columnOrder: ['todo', 'doing', 'done']
};

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'init', board }));

  ws.on('message', raw => {
    let msg;
    try {
      msg = JSON.parse(raw);
    } catch {
      return;
    }

    if (msg.type === 'add_task') {
      const id = `task-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
      const title = (msg.title || '').trim();
      const columnId = msg.columnId || 'todo';

      if (!title || !board.columns[columnId]) return;

      board.tasks[id] = { id, title };
      board.columns[columnId].taskIds.push(id);

      broadcast({ type: 'update', board });
    }

    if (msg.type === 'move_task') {
      const { taskId, fromColumnId, toColumnId, toIndex } = msg;

      if (
        !board.tasks[taskId] ||
        !board.columns[fromColumnId] ||
        !board.columns[toColumnId]
      ) return;

      const fromTasks = board.columns[fromColumnId].taskIds;
      const toTasks = board.columns[toColumnId].taskIds;

      const currentIndex = fromTasks.indexOf(taskId);
      if (currentIndex === -1) return;

      fromTasks.splice(currentIndex, 1);

      const safeIndex = Math.max(0, Math.min(toIndex, toTasks.length));
      toTasks.splice(safeIndex, 0, taskId);

      broadcast({ type: 'update', board });
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

