# 5) `public/app.js`

```javascript
const socket = new WebSocket(`ws://${location.host}`);

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

socket.addEventListener('message', event => {
  const msg = JSON.parse(event.data);

  if (msg.type === 'init' || msg.type === 'update') {
    boardState = msg.board;
    renderBoard();
  }
});

document.getElementById('addTaskBtn').addEventListener('click', () => {
  const titleInput = document.getElementById('taskTitle');
  const columnSelect = document.getElementById('taskColumn');

  const title = titleInput.value.trim();
  const columnId = columnSelect.value;

  if (!title) return;

  socket.send(JSON.stringify({
    type: 'add_task',
    title,
    columnId
  }));

  titleInput.value = '';
});

function renderBoard() {
  const board = document.getElementById('board');
  board.innerHTML = '';

  boardState.columnOrder.forEach(columnId => {
    const columnData = boardState.columns[columnId];

    const columnEl = document.createElement('div');
    columnEl.className = 'column';

    const titleEl = document.createElement('h2');
    titleEl.textContent = columnData.title;
    columnEl.appendChild(titleEl);

    const taskListEl = document.createElement('div');
    taskListEl.className = 'task-list';
    taskListEl.dataset.columnId = columnId;

    taskListEl.addEventListener('dragover', e => {
      e.preventDefault();
      taskListEl.classList.add('drag-over');
    });

    taskListEl.addEventListener('dragleave', () => {
      taskListEl.classList.remove('drag-over');
    });

    taskListEl.addEventListener('drop', e => {
      e.preventDefault();
      taskListEl.classList.remove('drag-over');

      if (!draggedTaskId || !draggedFromColumnId) return;

      const toColumnId = taskListEl.dataset.columnId;
      const toIndex = boardState.columns[toColumnId].taskIds.length;

      socket.send(JSON.stringify({
        type: 'move_task',
        taskId: draggedTaskId,
        fromColumnId: draggedFromColumnId,
        toColumnId,
        toIndex
      }));

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    columnData.taskIds.forEach(taskId => {
      const task = boardState.tasks[taskId];

      const taskEl = document.createElement('div');
      taskEl.className = 'task';
      taskEl.draggable = true;
      taskEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;

      taskEl.addEventListener('dragstart', () => {
        draggedTaskId = task.id;
        draggedFromColumnId = columnId;
        taskEl.classList.add('dragging');
      });

      taskEl.addEventListener('dragend', () => {
        taskEl.classList.remove('dragging');
      });

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(taskListEl);
    board.appendChild(columnEl);
  });
}
