import express from "express";
import http from "http";
import { WebSocketServer } from "ws";

type ColumnId = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
};

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.static("public"));

const board: BoardState = {
  columns: {
    todo: [
      { id: "1", title: "Set up project" },
      { id: "2", title: "Create task board UI" }
    ],
    doing: [
      { id: "3", title: "Implement drag and drop" }
    ],
    done: [
      { id: "4", title: "Draft requirements" }
    ]
  }
};

function broadcast(data: unknown) {
  const message = JSON.stringify(data);
  for (const client of wss.clients) {
    if (client.readyState === 1) {
      client.send(message);
    }
  }
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", board }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "moveTask") {
        const { taskId, fromColumn, toColumn } = msg as {
          taskId: string;
          fromColumn: ColumnId;
          toColumn: ColumnId;
        };

        if (fromColumn === toColumn) return;

        const fromTasks = board.columns[fromColumn];
        const toTasks = board.columns[toColumn];

        const index = fromTasks.findIndex((t) => t.id === taskId);
        if (index === -1) return;

        const [task] = fromTasks.splice(index, 1);
        toTasks.push(task);

        broadcast({ type: "state", board });
      }

      if (msg.type === "addTask") {
        const { column, title } = msg as {
          column: ColumnId;
          title: string;
        };

        const trimmed = title.trim();
        if (!trimmed) return;

        board.columns[column].push({
          id: crypto.randomUUID(),
          title: trimmed
        });

        broadcast({ type: "state", board });
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

