# 6) public/client.ts

```ts
type ColumnId = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
};

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

const boardEl = document.getElementById("board") as HTMLDivElement;

let state: BoardState = {
  columns: {
    todo: [],
    doing: [],
    done: []
  }
};

const ws = new WebSocket(`ws://${location.host}`);

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);

  if (msg.type === "state") {
    state = msg.board;
    render();
  }
});

function send(data: unknown) {
  ws.send(JSON.stringify(data));
}

function render() {
  const columns: { id: ColumnId; title: string }[] = [
    { id: "todo", title: "To Do" },
    { id: "doing", title: "Doing" },
    { id: "done", title: "Done" }
  ];

  boardEl.innerHTML = "";

  for (const column of columns) {
    const col = document.createElement("section");
    col.className = "column";
    col.dataset.columnId = column.id;

    col.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list"></div>
      <div class="add-task">
        <input type="text" placeholder="New task..." />
        <button>Add</button>
      </div>
    `;

    const taskList = col.querySelector(".task-list") as HTMLDivElement;

    for (const task of state.columns[column.id]) {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.fromColumn = column.id;

      taskEl.addEventListener("dragstart", () => {
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskList.appendChild(taskEl);
    }

    col.addEventListener("dragover", (e) => {
      e.preventDefault();
      col.classList.add("over");
    });

    col.addEventListener("dragleave", () => {
      col.classList.remove("over");
    });

    col.addEventListener("drop", (e) => {
      e.preventDefault();
      col.classList.remove("over");

      const dragged = document.querySelector(".task.dragging") as HTMLDivElement | null;
      if (!dragged) return;

      const taskId = dragged.dataset.taskId!;
      const fromColumn = dragged.dataset.fromColumn as ColumnId;
      const toColumn = column.id;

      send({
        type: "moveTask",
        taskId,
        fromColumn,
        toColumn
      });
    });

    const input = col.querySelector("input") as HTMLInputElement;
    const button = col.querySelector("button") as HTMLButtonElement;

    const addTask = () => {
      const title = input.value.trim();
      if (!title) return;
      send({
        type: "addTask",
        column: column.id,
        title
      });
      input.value = "";
    };

    button.addEventListener("click", addTask);
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") addTask();
    });

    boardEl.appendChild(col);
  }
}
```

