```ts
import express from "express";
import http from "http";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";

type Status = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  status: Status;
};

type State = {
  tasks: Task[];
};

type ClientMessage =
  | { type: "add_task"; title: string }
  | { type: "move_task"; taskId: string; status: Status };

type ServerMessage =
  | { type: "state"; state: State };

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

const PORT = 3000;

let state: State = {
  tasks: [
    { id: "1", title: "Create wireframe", status: "todo" },
    { id: "2", title: "Build login page", status: "doing" },
    { id: "3", title: "Deploy MVP", status: "done" }
  ]
};

app.use(express.static(path.join(__dirname, "../public")));
app.get("/", (_req, res) => {
  res.sendFile(path.join(__dirname, "../public/index.html"));
});

function broadcastState() {
  const msg: ServerMessage = { type: "state", state };
  const data = JSON.stringify(msg);

  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", state } satisfies ServerMessage));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString()) as ClientMessage;

      if (msg.type === "add_task") {
        const title = msg.title.trim();
        if (!title) return;

        state.tasks.push({
          id: Date.now().toString(),
          title,
          status: "todo"
        });
        broadcastState();
      }

      if (msg.type === "move_task") {
        const task = state.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;

        task.status = msg.status;
        broadcastState();
      }
    } catch (err) {
      console.error("Invalid message", err);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
