## 5) `public/client.ts`
```ts
type Status = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  status: Status;
};

type State = {
  tasks: Task[];
};

type ServerMessage = {
  type: "state";
  state: State;
};

type ClientMessage =
  | { type: "add_task"; title: string }
  | { type: "move_task"; taskId: string; status: Status };

const socket = new WebSocket(`ws://${location.host}`);

const form = document.getElementById("task-form") as HTMLFormElement;
const input = document.getElementById("task-input") as HTMLInputElement;

const columns: Record<Status, HTMLElement> = {
  todo: document.getElementById("todo")!,
  doing: document.getElementById("doing")!,
  done: document.getElementById("done")!
};

let currentState: State = { tasks: [] };

function send(msg: ClientMessage) {
  socket.send(JSON.stringify(msg));
}

function createTaskElement(task: Task): HTMLElement {
  const card = document.createElement("div");
  card.className = "task";
  card.draggable = true;
  card.textContent = task.title;
  card.dataset.taskId = task.id;

  card.addEventListener("dragstart", (e) => {
    e.dataTransfer?.setData("text/plain", task.id);
  });

  return card;
}

function render(state: State) {
  currentState = state;

  (Object.keys(columns) as Status[]).forEach((status) => {
    columns[status].innerHTML = "";
  });

  state.tasks.forEach((task) => {
    columns[task.status].appendChild(createTaskElement(task));
  });
}

(Object.keys(columns) as Status[]).forEach((status) => {
  const column = columns[status];

  column.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("drag-over");
  });

  column.addEventListener("dragleave", () => {
    column.classList.remove("drag-over");
  });

  column.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("drag-over");

    const taskId = e.dataTransfer?.getData("text/plain");
    if (!taskId) return;

    const task = currentState.tasks.find((t) => t.id === taskId);
    if (!task || task.status === status) return;

    send({ type: "move_task", taskId, status });
  });
});

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = input.value.trim();
  if (!title) return;

  send({ type: "add_task", title });
  input.value = "";
});

socket.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data) as ServerMessage;
  if (msg.type === "state") {
    render(msg.state);
  }
});
```

