### `server/server.js`
```js
import { WebSocketServer } from 'ws';
import http from 'http';

const server = http.createServer();
const wss = new WebSocketServer({ server });

let board = {
  columns: {
    todo: {
      id: 'todo',
      title: 'To Do',
      taskIds: ['1', '2']
    },
    doing: {
      id: 'doing',
      title: 'Doing',
      taskIds: []
    },
    done: {
      id: 'done',
      title: 'Done',
      taskIds: []
    }
  },
  tasks: {
    '1': { id: '1', title: 'Set up project' },
    '2': { id: '2', title: 'Build drag-and-drop board' }
  },
  columnOrder: ['todo', 'doing', 'done']
};

function broadcast(data) {
  const message = JSON.stringify(data);
  for (const client of wss.clients) {
    if (client.readyState === 1) {
      client.send(message);
    }
  }
}

wss.on('connection', (ws) => {
  ws.send(JSON.stringify({ type: 'init', board }));

  ws.on('message', (message) => {
    const data = JSON.parse(message.toString());

    if (data.type === 'moveTask') {
      board = data.board;
      broadcast({ type: 'update', board });
    }

    if (data.type === 'addTask') {
      const id = String(Date.now());
      board.tasks[id] = { id, title: data.title };
      board.columns.todo.taskIds.push(id);
      broadcast({ type: 'update', board });
    }
  });
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`WebSocket server running on ws://localhost:${PORT}`);
});
```

