```tsx
import { useEffect, useMemo, useState } from 'react';

type Task = {
  id: string;
  title: string;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type Board = {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
};

export default function App() {
  const [board, setBoard] = useState<Board | null>(null);
  const [newTask, setNewTask] = useState('');
  const ws = useMemo(() => new WebSocket('ws://localhost:3001'), []);

  useEffect(() => {
    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);

      if (data.type === 'init' || data.type === 'update') {
        setBoard(data.board);
      }
    };

    return () => ws.close();
  }, [ws]);

  function addTask() {
    if (!newTask.trim()) return;
    ws.send(JSON.stringify({ type: 'addTask', title: newTask }));
    setNewTask('');
  }

  function onDragStart(taskId: string, sourceColumnId: string) {
    return (event: React.DragEvent) => {
      event.dataTransfer.setData(
        'application/json',
        JSON.stringify({ taskId, sourceColumnId })
      );
    };
  }

  function onDrop(destColumnId: string) {
    return (event: React.DragEvent) => {
      event.preventDefault();

      if (!board) return;

      const raw = event.dataTransfer.getData('application/json');
      if (!raw) return;

      const { taskId, sourceColumnId } = JSON.parse(raw);

      if (sourceColumnId === destColumnId) return;

      const nextBoard: Board = JSON.parse(JSON.stringify(board));

      nextBoard.columns[sourceColumnId].taskIds =
        nextBoard.columns[sourceColumnId].taskIds.filter((id) => id !== taskId);

      nextBoard.columns[destColumnId].taskIds.push(taskId);

      setBoard(nextBoard);
      ws.send(JSON.stringify({ type: 'moveTask', board: nextBoard }));
    };
  }

  function onDragOver(event: React.DragEvent) {
    event.preventDefault();
  }

  if (!board) return <div className="loading">Connecting...</div>;

  return (
    <div className="app">
      <h1>Project Management Board</h1>

      <div className="add-task">
        <input
          value={newTask}
          onChange={(e) => setNewTask(e.target.value)}
          placeholder="New task title"
        />
        <button onClick={addTask}>Add Task</button>
      </div>

      <div className="board">
        {board.columnOrder.map((columnId) => {
          const column = board.columns[columnId];
          const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

          return (
            <div
              key={column.id}
              className="column"
              onDrop={onDrop(column.id)}
              onDragOver={onDragOver}
            >
              <h2>{column.title}</h2>
              {tasks.map((task) => (
                <div
                  key={task.id}
                  className="task"
                  draggable
                  onDragStart={onDragStart(task.id, column.id)}
                >
                  {task.title}
                </div>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );
}
```

