Safe starter skeleton
Below is a minimal event-driven skeleton in <language>Rust</language> that:
- consumes simulated market data
- runs a toy strategy
- emits “intents”
- blocks all execution in a risk gateway

```rust
use std::sync::mpsc::{channel, Receiver, Sender};
use std::thread;
use std::time::{Duration, SystemTime};

#[derive(Debug, Clone)]
struct MarketEvent {
    symbol: String,
    bid: f64,
    ask: f64,
    ts_ms: u128,
}

#[derive(Debug, Clone)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone)]
struct OrderIntent {
    symbol: String,
    side: Side,
    qty: u32,
    limit_px: f64,
    ts_ms: u128,
}

trait Strategy: Send + 'static {
    fn on_market_event(&mut self, ev: &MarketEvent) -> Option<OrderIntent>;
}

struct MeanRevertToy {
    threshold_bps: f64,
}

impl Strategy for MeanRevertToy {
    fn on_market_event(&mut self, ev: &MarketEvent) -> Option<OrderIntent> {
        let mid = (ev.bid + ev.ask) / 2.0;
        let spread_bps = ((ev.ask - ev.bid) / mid) * 10_000.0;

        if spread_bps > self.threshold_bps {
            Some(OrderIntent {
                symbol: ev.symbol.clone(),
                side: Side::Buy,
                qty: 10,
                limit_px: ev.bid,
                ts_ms: now_ms(),
            })
        } else {
            None
        }
    }
}

struct RiskGateway;

impl RiskGateway {
    fn evaluate(&self, intent: &OrderIntent) -> bool {
        println!("[RISK] Blocking intent by policy: {:?}", intent);
        false
    }
}

fn now_ms() -> u128 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        .as_millis()
}

fn market_data_sim(tx: Sender<MarketEvent>) {
    let mut px = 100.0;
    loop {
        px += 0.01;
        let ev = MarketEvent {
            symbol: "FOO".to_string(),
            bid: px - 0.02,
            ask: px + 0.02,
            ts_ms: now_ms(),
        };
        if tx.send(ev).is_err() {
            break;
        }
        thread::sleep(Duration::from_millis(10));
    }
}

fn strategy_loop<S: Strategy>(
    rx: Receiver<MarketEvent>,
    tx: Sender<OrderIntent>,
    mut strategy: S,
) {
    while let Ok(ev) = rx.recv() {
        if let Some(intent) = strategy.on_market_event(&ev) {
            if tx.send(intent).is_err() {
                break;
            }
        }
    }
}

fn risk_loop(rx: Receiver<OrderIntent>) {
    let risk = RiskGateway;
    while let Ok(intent) = rx.recv() {
        let approved = risk.evaluate(&intent);
        if approved {
            println!("[OMS] Would route approved intent: {:?}", intent);
        }
    }
}

fn main() {
    let (md_tx, md_rx) = channel::<MarketEvent>();
    let (intent_tx, intent_rx) = channel::<OrderIntent>();

    let md_handle = thread::spawn(move || market_data_sim(md_tx));
    let strat_handle = thread::spawn(move || {
        let strategy = MeanRevertToy { threshold_bps: 3.0 };
        strategy_loop(md_rx, intent_tx, strategy)
    });
    let risk_handle = thread::spawn(move || risk_loop(intent_rx));

    let _ = md_handle.join();
    let _ = strat_handle.join();
    let _ = risk_handle.join();
}
```

