use std::collections::VecDeque;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
struct MarketEvent {
    instrument_id: u32,
    bid: f64,
    ask: f64,
    ts_nanos: u128,
}

#[derive(Debug, Clone, Copy)]
struct Signal {
    instrument_id: u32,
    side: Side,
    confidence: f64,
    ts_nanos: u128,
}

#[derive(Debug, Clone, Copy)]
struct RiskDecision {
    approved: bool,
    reason_code: u32,
}

#[derive(Debug, Clone, Copy)]
struct SimulatedOrderIntent {
    instrument_id: u32,
    side: Side,
    quantity: u32,
    limit_price: f64,
    ts_nanos: u128,
}

trait Strategy {
    fn on_market_event(&mut self, event: MarketEvent) -> Option<Signal>;
}

trait RiskEngine {
    fn evaluate(&mut self, signal: Signal) -> RiskDecision;
}

trait ExecutionAdapter {
    fn submit_simulated(&mut self, intent: SimulatedOrderIntent);
}

struct MeanReversionStrategy {
    last_mid: Option<f64>,
    threshold_bps: f64,
}

impl MeanReversionStrategy {
    fn new(threshold_bps: f64) -> Self {
        Self {
            last_mid: None,
            threshold_bps,
        }
    }
}

impl Strategy for MeanReversionStrategy {
    fn on_market_event(&mut self, event: MarketEvent) -> Option<Signal> {
        let mid = (event.bid + event.ask) * 0.5;
        let out = if let Some(last) = self.last_mid {
            let move_bps = ((mid - last) / last) * 10_000.0;
            if move_bps.abs() >= self.threshold_bps {
                Some(Signal {
                    instrument_id: event.instrument_id,
                    side: if move_bps < 0.0 { Side::Buy } else { Side::Sell },
                    confidence: move_bps.abs().min(100.0) / 100.0,
                    ts_nanos: event.ts_nanos,
                })
            } else {
                None
            }
        } else {
            None
        };
        self.last_mid = Some(mid);
        out
    }
}

struct BasicRiskEngine {
    max_confidence: f64,
    max_qty: u32,
}

impl BasicRiskEngine {
    fn new(max_confidence: f64, max_qty: u32) -> Self {
        Self {
            max_confidence,
            max_qty,
        }
    }

    fn size_order(&self, signal: Signal) -> u32 {
        let raw = (signal.confidence * self.max_qty as f64) as u32;
        raw.max(1).min(self.max_qty)
    }
}

impl RiskEngine for BasicRiskEngine {
    fn evaluate(&mut self, signal: Signal) -> RiskDecision {
        if signal.confidence <= 0.0 || signal.confidence > self.max_confidence {
            return RiskDecision {
                approved: false,
                reason_code: 1001,
            };
        }
        RiskDecision {
            approved: true,
            reason_code: 0,
        }
    }
}

struct SimExecutionAdapter {
    sent: VecDeque<SimulatedOrderIntent>,
}

impl SimExecutionAdapter {
    fn new() -> Self {
        Self {
            sent: VecDeque::with_capacity(1024),
        }
    }
}

impl ExecutionAdapter for SimExecutionAdapter {
    fn submit_simulated(&mut self, intent: SimulatedOrderIntent) {
        if self.sent.len() == 1024 {
            self.sent.pop_front();
        }
        self.sent.push_back(intent);
        println!("SIM_ORDER {:?}", intent);
    }
}

struct Engine<S: Strategy, R: RiskEngine, E: ExecutionAdapter> {
    strategy: S,
    risk: R,
    exec: E,
}

impl<S: Strategy, R: RiskEngine, E: ExecutionAdapter> Engine<S, R, E> {
    fn new(strategy: S, risk: R, exec: E) -> Self {
        Self { strategy, risk, exec }
    }

    fn on_market_data(&mut self, event: MarketEvent, order_sizer: impl Fn(Signal) -> u32) {
        if let Some(signal) = self.strategy.on_market_event(event) {
            let decision = self.risk.evaluate(signal);
            if decision.approved {
                let limit_price = match signal.side {
                    Side::Buy => event.ask,
                    Side::Sell => event.bid,
                };
                let qty = order_sizer(signal);
                let intent = SimulatedOrderIntent {
                    instrument_id: signal.instrument_id,
                    side: signal.side,
                    quantity: qty,
                    limit_price,
                    ts_nanos: signal.ts_nanos,
                };
                self.exec.submit_simulated(intent);
            }
        }
    }
}

fn now_nanos(start: Instant) -> u128 {
    start.elapsed().as_nanos()
}

fn main() {
    let start = Instant::now();

    let strategy = MeanReversionStrategy::new(3.0);
    let risk = BasicRiskEngine::new(1.0, 100);
    let exec = SimExecutionAdapter::new();

    let mut engine = Engine::new(strategy, risk, exec);

    let tape = [
        MarketEvent { instrument_id: 1, bid: 99.99, ask: 100.01, ts_nanos: now_nanos(start) },
        MarketEvent { instrument_id: 1, bid: 99.90, ask: 99.92, ts_nanos: now_nanos(start) + 1_000 },
        MarketEvent { instrument_id: 1, bid: 100.10, ask: 100.12, ts_nanos: now_nanos(start) + 2_000 },
        MarketEvent { instrument_id: 1, bid: 100.11, ask: 100.13, ts_nanos: now_nanos(start) + 3_000 },
    ];

    for ev in tape {
        let max_qty = 100;
        engine.on_market_data(ev, |signal| {
            let q = (signal.confidence * max_qty as f64) as u32;
            q.max(1).min(max_qty)
        });
        std::thread::sleep(Duration::from_micros(50));
    }
}
```

