```rust
use std::sync::{Arc, Mutex};
use std::collections::VecDeque;

#[derive(Clone, Debug)]
pub struct MarketData {
    pub symbol: String,
    pub bid: f64,
    pub ask: f64,
    pub ts_nanos: u64,
}

#[derive(Clone, Debug)]
pub struct Order {
    pub id: u64,
    pub symbol: String,
    pub side: Side,
    pub qty: u64,
    pub price: f64,
}

#[derive(Clone, Debug)]
pub enum Side {
    Buy,
    Sell,
}

pub trait Strategy: Send {
    fn on_market_data(&mut self, md: &MarketData) -> Option<Order>;
}

pub trait RiskCheck: Send + Sync {
    fn approve(&self, order: &Order) -> bool;
}

pub trait ExecutionSink: Send + Sync {
    fn send(&self, order: &Order);
}

pub struct SimpleStrategy;

impl Strategy for SimpleStrategy {
    fn on_market_data(&mut self, md: &MarketData) -> Option<Order> {
        if md.ask - md.bid < 0.01 {
            Some(Order {
                id: md.ts_nanos,
                symbol: md.symbol.clone(),
                side: Side::Buy,
                qty: 100,
                price: md.ask,
            })
        } else {
            None
        }
    }
}

pub struct MaxQtyRisk {
    pub max_qty: u64,
}

impl RiskCheck for MaxQtyRisk {
    fn approve(&self, order: &Order) -> bool {
        order.qty <= self.max_qty
    }
}

pub struct LoggingExecutionSink;

impl ExecutionSink for LoggingExecutionSink {
    fn send(&self, order: &Order) {
        println!("EXECUTE {:?}", order);
    }
}

pub struct Engine<S: Strategy> {
    strategy: S,
    risk: Arc<dyn RiskCheck>,
    exec: Arc<dyn ExecutionSink>,
    queue: Arc<Mutex<VecDeque<MarketData>>>,
}

impl<S: Strategy> Engine<S> {
    pub fn new(
        strategy: S,
        risk: Arc<dyn RiskCheck>,
        exec: Arc<dyn ExecutionSink>,
    ) -> Self {
        Self {
            strategy,
            risk,
            exec,
            queue: Arc::new(Mutex::new(VecDeque::new())),
        }
    }

    pub fn publish_market_data(&self, md: MarketData) {
        self.queue.lock().unwrap().push_back(md);
    }

    pub fn run_once(&mut self) {
        let maybe_md = self.queue.lock().unwrap().pop_front();
        if let Some(md) = maybe_md {
            if let Some(order) = self.strategy.on_market_data(&md) {
                if self.risk.approve(&order) {
                    self.exec.send(&order);
                }
            }
        }
    }
}

fn main() {
    let risk = Arc::new(MaxQtyRisk { max_qty: 1000 });
    let exec = Arc::new(LoggingExecutionSink);
    let strategy = SimpleStrategy;

    let mut engine = Engine::new(strategy, risk, exec);

    engine.publish_market_data(MarketData {
        symbol: "AAPL".to_string(),
        bid: 189.99,
        ask: 190.00,
        ts_nanos: 1,
    });

    engine.run_once();
}
```

