## `common/tcp_client.h`

```cpp
#pragma once
#include <arpa/inet.h>
#include <unistd.h>
#include <cstring>
#include <string>
#include <iostream>

namespace tp {

class TcpClient {
public:
    TcpClient(const std::string& host, int port) {
        fd_ = socket(AF_INET, SOCK_STREAM, 0);
        if (fd_ < 0) {
            perror("socket");
            return;
        }

        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);
        inet_pton(AF_INET, host.c_str(), &addr.sin_addr);

        if (connect(fd_, (sockaddr*)&addr, sizeof(addr)) < 0) {
            perror("connect");
            close(fd_);
            fd_ = -1;
        }
    }

    ~TcpClient() {
        if (fd_ >= 0) close(fd_);
    }

    bool send_bytes(const void* data, size_t len) {
        if (fd_ < 0) return false;
        return send(fd_, data, len, 0) == (ssize_t)len;
    }

private:
    int fd_{-1};
};

}
