Publishes synthetic market data to the strategy engine.

```cpp
#include "../common/messages.h"
#include "../common/tcp_client.h"
#include "../common/utils.h"
#include <thread>
#include <chrono>
#include <cstring>
#include <iostream>

int main() {
    tp::TcpClient client("127.0.0.1", 9001);

    uint64_t seq = 0;
    while (true) {
        tp::Envelope<tp::MarketDataMsg> msg{};
        msg.header.type = tp::MessageType::MarketData;
        msg.header.length = sizeof(msg.body);

        std::strncpy(msg.body.symbol, "FOO", sizeof(msg.body.symbol));
        msg.body.bid = 100.0 + (seq % 10) * 0.01;
        msg.body.ask = msg.body.bid + 0.02;
        msg.body.ts_ns = tp::now_ns();

        client.send_bytes(&msg, sizeof(msg));
        std::cout << "MD sent bid=" << msg.body.bid << " ask=" << msg.body.ask << std::endl;

        seq++;
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }
}
