## `strategy/main.cpp`

Receives market data and generates simple buy orders.

```cpp
#include "../common/messages.h"
#include "../common/tcp_server.h"
#include "../common/tcp_client.h"
#include "../common/utils.h"
#include <iostream>
#include <cstring>

int main() {
    tp::TcpClient risk_client("127.0.0.1", 9002);
    uint64_t next_order_id = 1;

    tp::TcpServer server(9001, [&](const char* data, size_t len, int) {
        if (len < sizeof(tp::Envelope<tp::MarketDataMsg>)) return;

        auto* msg = reinterpret_cast<const tp::Envelope<tp::MarketDataMsg>*>(data);
        if (msg->header.type != tp::MessageType::MarketData) return;

        std::cout << "Strategy got MD " << msg->body.symbol
                  << " bid=" << msg->body.bid
                  << " ask=" << msg->body.ask << std::endl;

        if (msg->body.ask < 100.05) {
            tp::Envelope<tp::NewOrderMsg> order{};
            order.header.type = tp::MessageType::NewOrder;
            order.header.length = sizeof(order.body);

            order.body.order_id = next_order_id++;
            std::strncpy(order.body.symbol, msg->body.symbol, sizeof(order.body.symbol));
            order.body.side = tp::Side::Buy;
            order.body.price = msg->body.ask;
            order.body.qty = 100;
            order.body.ts_ns = tp::now_ns();

            risk_client.send_bytes(&order, sizeof(order));
            std::cout << "Strategy sent order id=" << order.body.order_id << std::endl;
        }
    });

    server.run();
}
