        er.body.fill_qty = order->body.qty;
        er.body.fill_price = order->body.price;
        er.body.ts_ns = tp::now_ns();

        om_client.send_bytes(&er, sizeof(er));
        pos_client.send_bytes(&er, sizeof(er));

        std::cout << "Execution filled order id=" << er.body.order_id << std::endl;
    });

