    tp::TcpServer server(9005, [&](const char* data, size_t len, int) {
        if (len < sizeof(tp::Envelope<tp::ExecutionReportMsg>)) return;

        auto* er = reinterpret_cast<const tp::Envelope<tp::ExecutionReportMsg>*>(data);
        if (er->header.type != tp::MessageType::ExecutionReport) return;

        if (er->body.status == tp::ExecStatus::Fill) {
            position += er->body.fill_qty;
        }

        std::cout << "Position updated: " << position << std::endl;
    });

    server.run();
}
```

