# 5. `include/event_bus.hpp`

This is a simple in-process queue. Later, replace with a lock-free ring buffer.

```cpp
#pragma once
#include <queue>
#include <mutex>
#include <optional>

template <typename T>
class EventBus {
public:
    void publish(const T& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(event);
    }

    std::optional<T> try_consume() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) return std::nullopt;
        T val = queue_.front();
        queue_.pop();
        return val;
    }

private:
    std::queue<T> queue_;
    std::mutex mutex_;
};
```

