#include "risk.hpp"

bool RiskEngine::approve(const NewOrderRequest& order) {
    auto current = net_positions_[order.instrument_id];

    int64_t proposed = current;
    if (order.side == Side::Buy) {
        proposed += order.qty;
    } else {
        proposed -= order.qty;
    }

    if (proposed > static_cast<int64_t>(max_position_per_instrument_) ||
        proposed < -static_cast<int64_t>(max_position_per_instrument_)) {
        return false;
    }

    return true;
}

void RiskEngine::on_fill(const ExecutionReport& report, Side side, InstrumentId instrument_id) {
    if (report.status != OrderStatus::Filled) return;

    if (side == Side::Buy) {
        net_positions_[instrument_id] += report.filled_qty;
    } else {
        net_positions_[instrument_id] -= report.filled_qty;
    }
}
```

