#include <iostream>
#include <vector>
#include "event_bus.hpp"
#include "market_data.hpp"
#include "strategy.hpp"
#include "risk.hpp"
#include "order_manager.hpp"

int main() {
    EventBus<MarketDataTick> market_data_bus;

    Strategy strategy;
    RiskEngine risk_engine(100);
    ExecutionAdapter execution_adapter;
    OrderManager order_manager(execution_adapter);

    std::vector<MarketDataTick> ticks = {
        {1, 100, 101, 1000, 1000, now_nanos()},
        {1, 100, 102, 1000, 1000, now_nanos()},
        {1, 100, 101, 1000, 1000, now_nanos()},
        {1, 100, 100, 1000, 1000, now_nanos()}
    };

    for (const auto& tick : ticks) {
        market_data_bus.publish(tick);
    }

    while (auto md = market_data_bus.try_consume()) {
        auto maybe_order = strategy.on_market_data(*md);
        if (!maybe_order.has_value()) {
            continue;
        }

        auto order = *maybe_order;

        if (!risk_engine.approve(order)) {
            std::cout << "Order rejected by risk. order_id=" << order.order_id << "\n";
            continue;
        }

        auto report = order_manager.submit(order);

        risk_engine.on_fill(report, order.side, order.instrument_id);

        std::cout
            << "Order " << report.order_id
            << " status=" << static_cast<int>(report.status)
            << " filled_qty=" << report.filled_qty
            << " fill_price=" << report.fill_price
            << "\n";
    }

    return 0;
}
