## `crates/core/src/risk.rs`
```rust
use crate::types::*;
use std::collections::{HashMap, HashSet};

pub struct RiskLimits {
    pub max_order_qty: u64,
    pub allowed_symbols: HashSet<Symbol>,
    pub max_position_abs: i64,
}

pub struct RiskEngine {
    pub limits: RiskLimits,
    pub positions: HashMap<Symbol, i64>,
    pub trading_enabled: bool,
}

impl RiskEngine {
    pub fn check(&self, intent: &OrderIntent) -> Result<(), String> {
        if !self.trading_enabled {
            return Err("trading disabled".into());
        }
        if intent.qty.0 > self.limits.max_order_qty {
            return Err("max order qty exceeded".into());
        }
        if !self.limits.allowed_symbols.contains(&intent.symbol) {
            return Err("symbol not allowed".into());
        }

        let pos = self.positions.get(&intent.symbol).copied().unwrap_or(0);
        let next = match intent.side {
            Side::Buy => pos + intent.qty.0 as i64,
            Side::Sell => pos - intent.qty.0 as i64,
        };
        if next.abs() > self.limits.max_position_abs {
            return Err("position limit exceeded".into());
        }
        Ok(())
    }

    pub fn apply_fill(&mut self, symbol: &Symbol, side: Side, qty: Qty) {
        let entry = self.positions.entry(symbol.clone()).or_insert(0);
        match side {
            Side::Buy => *entry += qty.0 as i64,
            Side::Sell => *entry -= qty.0 as i64,
        }
    }
}
```

