use crate::types::*;
use std::collections::HashMap;

pub struct OrderRecord {
    pub intent: OrderIntent,
    pub status: OrderStatus,
}

pub struct OrderManager {
    next_id: u64,
    pub orders: HashMap<OrderId, OrderRecord>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            next_id: 1,
            orders: HashMap::new(),
        }
    }

    pub fn create(&mut self, intent: OrderIntent) -> OrderId {
        let id = OrderId(self.next_id);
        self.next_id += 1;
        self.orders.insert(id, OrderRecord {
            intent,
            status: OrderStatus::New,
        });
        id
    }

    pub fn update(&mut self, id: OrderId, status: OrderStatus) {
        if let Some(order) = self.orders.get_mut(&id) {
            order.status = status;
        }
    }
}
