            symbol: Symbol("FOO".into()),
            bid: Price(100),
            ask: Price(104),
            ts: Instant::now(),
        },
        MarketTick {
            symbol: Symbol("FOO".into()),
            bid: Price(101),
            ask: Price(102),
            ts: Instant::now(),
        },
    ];

    for tick in ticks {
        if let Some(intent) = strategy.on_tick(&tick) {
            match risk.check(&intent) {
                Ok(()) => {
                    let side = intent.side;
                    let symbol = intent.symbol.clone();
                    let qty = intent.qty;

                    let order_id = om.create(intent.clone());
                    let (_id, status) = SimExchange::send(order_id, &intent);
                    om.update(order_id, status.clone());

                    if let OrderStatus::Filled = status {
                        risk.apply_fill(&symbol, side, qty);
                    }

                    println!("order {:?} -> {:?}", order_id, status);
                }
                Err(e) => {
                    println!("risk rejected order: {}", e);
                }
            }
        }
    }

    println!("final positions: {:?}", risk.positions);
}
