pub struct SimpleStrategy {
    md_rx: Receiver<MarketTick>,
    signal_tx: Sender<StrategySignal>,
}

impl SimpleStrategy {
    pub fn new(md_rx: Receiver<MarketTick>, signal_tx: Sender<StrategySignal>) -> Self {
        Self { md_rx, signal_tx }
    }

    pub fn start(self) {
        thread::spawn(move || {
            for tick in self.md_rx.iter() {
                if tick.bid < Decimal::new(10050, 2) {
                    let _ = self.signal_tx.send(StrategySignal::Buy {
                        symbol: tick.symbol.clone(),
                        qty: Decimal::ONE,
                    });
                } else {
                    let _ = self.signal_tx.send(StrategySignal::Sell {
                        symbol: tick.symbol.clone(),
                        qty: Decimal::ONE,
                    });
                }
            }
        });
    }
}

pub struct SignalOrderTransformer;

impl SignalOrderTransformer {
    pub fn run(signal_rx: Receiver<StrategySignal>, order_tx: Sender<OrderRequest>) {
        thread::spawn(move || {
            for signal in signal_rx.iter() {
                let now = SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap()
                    .as_nanos() as u64;

                let req = match signal {
                    StrategySignal::Buy { symbol, qty } => OrderRequest {
                        id: Uuid::new_v4(),
                        symbol,
                        side: Side::Buy,
                        qty,
                        order_type: OrderType::Market,
                        limit_price: None,
                        ts_nanos: now,
                    },
                    StrategySignal::Sell { symbol, qty } => OrderRequest {
                        id: Uuid::new_v4(),
                        symbol,
                        side: Side::Sell,
                        qty,
                        order_type: OrderType::Market,
                        limit_price: None,
                        ts_nanos: now,
                    },
                };

                let _ = order_tx.send(req);
            }
        });
    }
}
