```rust
use common::{FillEvent, OrderRequest, Position, RiskApprovedOrder, Side};
use crossbeam_channel::{Receiver, Sender};
use dashmap::DashMap;
use rust_decimal::Decimal;
use std::sync::Arc;
use std::thread;

#[derive(Clone)]
pub struct RiskLimits {
    pub max_abs_position: Decimal,
    pub max_order_qty: Decimal,
}

#[derive(Clone)]
pub struct RiskEngine {
    limits: RiskLimits,
    positions: Arc<DashMap<String, Decimal>>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn start_order_checks(
        self,
        order_rx: Receiver<OrderRequest>,
        approved_tx: Sender<RiskApprovedOrder>,
    ) {
        thread::spawn(move || {
            for order in order_rx.iter() {
                if order.qty > self.limits.max_order_qty {
                    continue;
                }

                let current = self
                    .positions
                    .get(&order.symbol)
                    .map(|v| *v)
                    .unwrap_or(Decimal::ZERO);

                let signed_qty = match order.side {
                    Side::Buy => order.qty,
                    Side::Sell => -order.qty,
                };

                let projected = current + signed_qty;
                if projected.abs() > self.limits.max_abs_position {
                    continue;
                }

                let _ = approved_tx.send(RiskApprovedOrder { req: order });
            }
        });
    }

    pub fn start_fill_updates(&self, fill_rx: Receiver<FillEvent>) {
        let positions = self.positions.clone();
        thread::spawn(move || {
            for fill in fill_rx.iter() {
                let mut entry = positions.entry(fill.symbol).or_insert(Decimal::ZERO);
                *entry += fill.qty;
            }
        });
    }

    pub fn snapshot_positions(&self) -> Vec<Position> {
        self.positions
            .iter()
            .map(|kv| Position {
                symbol: kv.key().clone(),
                net_qty: *kv.value(),
            })
            .collect()
    }
}
```

Note: this is very simplified. In production, fills must update signed quantity by side and support:
- accounts
- portfolios
- per-symbol limits
- fat-finger controls
- notional limits
- kill switch
- pre-trade throttles

