use common::{FillEvent, RiskApprovedOrder};
use crossbeam_channel::{Receiver, Sender};
use dashmap::DashMap;
use std::sync::Arc;
use std::thread;
use uuid::Uuid;

#[derive(Debug, Clone)]
pub enum OrderState {
    PendingSend,
    Sent,
    Filled,
    Rejected,
}

#[derive(Clone)]
pub struct OrderManager {
    states: Arc<DashMap<Uuid, OrderState>>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            states: Arc::new(DashMap::new()),
        }
    }

    pub fn start(
        self,
        approved_rx: Receiver<RiskApprovedOrder>,
        gw_tx: Sender<RiskApprovedOrder>,
        fill_rx: Receiver<FillEvent>,
    ) {
        let states1 = self.states.clone();
        thread::spawn(move || {
            for approved in approved_rx.iter() {
                states1.insert(approved.req.id, OrderState::PendingSend);
                let _ = gw_tx.send(approved);
            }
        });

        let states2 = self.states.clone();
        thread::spawn(move || {
            for fill in fill_rx.iter() {
                states2.insert(fill.order_id, OrderState::Filled);
            }
        });
    }
}
```

