# src/book.rs

```rust
use crate::types::*;
use std::cmp::Reverse;
use std::collections::{BTreeMap, HashMap, VecDeque};

#[derive(Debug)]
pub struct OrderBook {
    pub symbol: Symbol,
    bids: BTreeMap<Reverse<Price>, VecDeque<Order>>,
    asks: BTreeMap<Price, VecDeque<Order>>,
    order_index: HashMap<OrderId, (Side, Option<Price>)>,
}

impl OrderBook {
    pub fn new(symbol: Symbol) -> Self {
        Self {
            symbol,
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
            order_index: HashMap::new(),
        }
    }

    pub fn best_bid(&self) -> Option<Price> {
        self.bids.keys().next().map(|p| p.0)
    }

    pub fn best_ask(&self) -> Option<Price> {
        self.asks.keys().next().copied()
    }

    pub fn cancel(&mut self, order_id: OrderId) -> bool {
        let Some((side, price)) = self.order_index.remove(&order_id) else {
            return false;
        };

        match (side, price) {
            (Side::Buy, Some(px)) => {
                if let Some(level) = self.bids.get_mut(&Reverse(px)) {
                    if let Some(pos) = level.iter().position(|o| o.order_id == order_id) {
                        level.remove(pos);
                    }
                    if level.is_empty() {
                        self.bids.remove(&Reverse(px));
                    }
                }
                true
            }
            (Side::Sell, Some(px)) => {
                if let Some(level) = self.asks.get_mut(&px) {
                    if let Some(pos) = level.iter().position(|o| o.order_id == order_id) {
                        level.remove(pos);
                    }
                    if level.is_empty() {
                        self.asks.remove(&px);
                    }
                }
                true
            }
            _ => false,
        }
    }

    pub fn add_and_match(&mut self, mut incoming: Order) -> Vec<Event> {
        let mut events = Vec::new();

        match incoming.side {
            Side::Buy => {
                while incoming.remaining_qty > 0 {
                    let best_ask = match self.asks.keys().next().copied() {
                        Some(px) => px,
                        None => break,
                    };

                    let crosses = match incoming.order_type {
                        OrderType::Market => true,
                        OrderType::Limit => incoming.price.unwrap() >= best_ask,
                    };

                    if !crosses {
                        break;
                    }

                    let mut remove_level = false;

                    if let Some(level) = self.asks.get_mut(&best_ask) {
                        while incoming.remaining_qty > 0 && !level.is_empty() {
                            let resting = level.front_mut().unwrap();
                            let trade_qty = incoming.remaining_qty.min(resting.remaining_qty);
                            incoming.remaining_qty -= trade_qty;
                            resting.remaining_qty -= trade_qty;

                            events.push(Event::Trade {
                                symbol: self.symbol.clone(),
                                buy_order_id: incoming.order_id,
                                sell_order_id: resting.order_id,
                                price: best_ask,
                                qty: trade_qty,
                                ts: incoming.ts,
                            });

                            if resting.remaining_qty == 0 {
                                let filled = level.pop_front().unwrap();
                                self.order_index.remove(&filled.order_id);
                            }
                        }
                        remove_level = level.is_empty();
                    }

                    if remove_level {
                        self.asks.remove(&best_ask);
                    }
                }

                if incoming.remaining_qty > 0 && incoming.order_type == OrderType::Limit {
                    let px = incoming.price.unwrap();
                    self.order_index
                        .insert(incoming.order_id, (Side::Buy, Some(px)));
                    self.bids
                        .entry(Reverse(px))
                        .or_default()
                        .push_back(incoming);
                }
            }
            Side::Sell => {
                while incoming.remaining_qty > 0 {
                    let best_bid = match self.bids.keys().next().map(|x| x.0) {
                        Some(px) => px,
                        None => break,
                    };

                    let crosses = match incoming.order_type {
                        OrderType::Market => true,
                        OrderType::Limit => incoming.price.unwrap() <= best_bid,
                    };

                    if !crosses {
                        break;
                    }

                    let mut remove_level = false;

                    if let Some(level) = self.bids.get_mut(&Reverse(best_bid)) {
                        while incoming.remaining_qty > 0 && !level.is_empty() {
                            let resting = level.front_mut().unwrap();
                            let trade_qty = incoming.remaining_qty.min(resting.remaining_qty);
                            incoming.remaining_qty -= trade_qty;
                            resting.remaining_qty -= trade_qty;

                            events.push(Event::Trade {
                                symbol: self.symbol.clone(),
                                buy_order_id: resting.order_id,
                                sell_order_id: incoming.order_id,
                                price: best_bid,
                                qty: trade_qty,
                                ts: incoming.ts,
                            });

                            if resting.remaining_qty == 0 {
                                let filled = level.pop_front().unwrap();
                                self.order_index.remove(&filled.order_id);
                            }
                        }
                        remove_level = level.is_empty();
                    }

                    if remove_level {
                        self.bids.remove(&Reverse(best_bid));
                    }
                }

                if incoming.remaining_qty > 0 && incoming.order_type == OrderType::Limit {
                    let px = incoming.price.unwrap();
                    self.order_index
                        .insert(incoming.order_id, (Side::Sell, Some(px)));
                    self.asks.entry(px).or_default().push_back(incoming);
                }
            }
        }

        events.push(Event::BookUpdated {
            symbol: self.symbol.clone(),
            best_bid: self.best_bid(),
            best_ask: self.best_ask(),
            ts: incoming.ts,
        });

        events
    }
}
