# src/engine.rs

```rust
use crate::book::OrderBook;
use crate::marketdata::MarketDataBus;
use crate::types::*;
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::mpsc;
use tracing::{info, warn};

pub struct Engine {
    books: DashMap<Symbol, OrderBook>,
    md_bus: MarketDataBus,
}

impl Engine {
    pub fn new(md_bus: MarketDataBus) -> Self {
        Self {
            books: DashMap::new(),
            md_bus,
        }
    }

    pub async fn run(self: Arc<Self>, mut rx: mpsc::Receiver<Command>) {
        while let Some(cmd) = rx.recv().await {
            match cmd {
                Command::New(order) => {
                    let symbol = order.symbol.clone();
                    let mut book = self
                        .books
                        .entry(symbol.clone())
                        .or_insert_with(|| OrderBook::new(symbol.clone()));

                    self.md_bus.publish(Event::OrderAccepted {
                        order_id: order.order_id,
                        symbol: order.symbol.clone(),
                    });

                    let events = book.add_and_match(order);
                    for evt in events {
                        self.md_bus.publish(evt);
                    }
                }
                Command::Cancel {
                    order_id,
                    symbol,
                    ts: _,
                } => {
                    if let Some(mut book) = self.books.get_mut(&symbol) {
                        let cancelled = book.cancel(order_id);
                        if cancelled {
                            self.md_bus.publish(Event::OrderCancelled {
                                order_id,
                                symbol: symbol.clone(),
                            });
                            self.md_bus.publish(Event::BookUpdated {
                                symbol,
                                best_bid: book.best_bid(),
                                best_ask: book.best_ask(),
                                ts: now_nanos(),
                            });
                        } else {
                            warn!("cancel failed: order not found");
                        }
                    } else {
                        warn!("cancel failed: symbol book not found");
                    }
                }
            }
        }
        info!("engine stopped");
    }
}

pub fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
