# src/gateway.rs

```rust
use crate::engine::now_nanos;
use crate::types::*;
use axum::{
    extract::State,
    http::StatusCode,
    routing::{get, post},
    Json, Router,
};
use std::sync::Arc;
use tokio::sync::mpsc;
use uuid::Uuid;

#[derive(Clone)]
pub struct GatewayState {
    pub tx: mpsc::Sender<Command>,
}

pub fn router(state: GatewayState) -> Router {
    Router::new()
        .route("/health", get(health))
        .route("/orders", post(create_order))
        .route("/orders/cancel", post(cancel_order))
        .with_state(Arc::new(state))
}

async fn health() -> &'static str {
    "ok"
}

async fn create_order(
    State(state): State<Arc<GatewayState>>,
    Json(req): Json<NewOrderRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    if req.qty == 0 {
        return Err((StatusCode::BAD_REQUEST, "qty must be > 0".into()));
    }

    if req.order_type == OrderType::Limit && req.price.is_none() {
        return Err((StatusCode::BAD_REQUEST, "limit orders require price".into()));
    }

    let order = Order {
        order_id: Uuid::new_v4(),
        client_id: req.client_id,
        symbol: req.symbol,
        side: req.side,
        qty: req.qty,
        remaining_qty: req.qty,
        order_type: req.order_type,
        price: req.price,
        ts: now_nanos(),
    };

    let order_id = order.order_id;
    state
        .tx
        .send(Command::New(order))
        .await
        .map_err(|_| (StatusCode::INTERNAL_SERVER_ERROR, "engine unavailable".into()))?;

    Ok(Json(serde_json::json!({
        "status": "accepted",
        "order_id": order_id
    })))
}

async fn cancel_order(
    State(state): State<Arc<GatewayState>>,
    Json(req): Json<CancelOrderRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    state
        .tx
        .send(Command::Cancel {
            order_id: req.order_id,
            symbol: req.symbol,
            ts: now_nanos(),
        })
        .await
        .map_err(|_| (StatusCode::INTERNAL_SERVER_ERROR, "engine unavailable".into()))?;

    Ok(Json(serde_json::json!({
        "status": "cancel_requested",
        "order_id": req.order_id
    })))
}
