use crossbeam::channel::{unbounded, Receiver, Sender};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MarketData {
    symbol: String,
    price: f64,
    ts_millis: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Order {
    id: u64,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
    ts_millis: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Fill {
    order_id: u64,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
    ts_millis: u128,
}

fn now_millis() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis()
}

fn market_data_gateway(tx_strategy: Sender<MarketData>) {
    let symbol = "AAPL".to_string();
    let mut price = 100.0;

    loop {
        // simple deterministic "market movement"
        price += if (now_millis() / 1000) % 2 == 0 { -0.5 } else { 0.7 };

        let md = MarketData {
            symbol: symbol.clone(),
            price,
            ts_millis: now_millis(),
        };

        if tx_strategy.send(md).is_err() {
            break;
        }

        thread::sleep(Duration::from_millis(500));
    }
}

fn strategy_engine(rx_md: Receiver<MarketData>, tx_order: Sender<Order>) {
    let mut next_order_id = 1u64;
    let buy_threshold = 99.5;
    let sell_threshold = 101.0;
    let order_qty = 10;

    for md in rx_md.iter() {
        let maybe_side = if md.price <= buy_threshold {
            Some(Side::Buy)
        } else if md.price >= sell_threshold {
            Some(Side::Sell)
        } else {
            None
        };

        if let Some(side) = maybe_side {
            let order = Order {
                id: next_order_id,
                symbol: md.symbol.clone(),
                side,
                qty: order_qty,
                price: md.price,
                ts_millis: now_millis(),
            };
            next_order_id += 1;

            if tx_order.send(order).is_err() {
                break;
            }
        }
    }
}

fn risk_engine(rx_order: Receiver<Order>, tx_approved: Sender<Order>, max_abs_position: i64) {
    let mut positions: HashMap<String, i64> = HashMap::new();

    for order in rx_order.iter() {
        let pos = *positions.get(&order.symbol).unwrap_or(&0);
        let new_pos = match order.side {
            Side::Buy => pos + order.qty as i64,
            Side::Sell => pos - order.qty as i64,
        };

        if new_pos.abs() <= max_abs_position {
            positions.insert(order.symbol.clone(), new_pos);
            if tx_approved.send(order).is_err() {
                break;
            }
        } else {
            eprintln!(
                "[RISK] Rejected order {:?}, projected position {} exceeds limit {}",
                order, new_pos, max_abs_position
            );
        }
    }
}

fn order_manager(rx_approved: Receiver<Order>, tx_fill: Sender<Fill>) {
    for order in rx_approved.iter() {
        // In a real system:
        // - serialize to exchange protocol
        // - send over low-latency socket
        // - await ACK / FILL / REJECT
        // Here we simulate immediate fill.

        let fill = Fill {
            order_id: order.id,
            symbol: order.symbol.clone(),
            side: order.side.clone(),
            qty: order.qty,
            price: order.price,
            ts_millis: now_millis(),
        };

        println!("[ORDER_MANAGER] Sent order: {:?}", order);

        if tx_fill.send(fill).is_err() {
            break;
        }
    }
}

fn portfolio_service(rx_fill: Receiver<Fill>) {
    let mut positions: HashMap<String, i64> = HashMap::new();
    let mut pnl: HashMap<String, f64> = HashMap::new();

    for fill in rx_fill.iter() {
        let pos = positions.entry(fill.symbol.clone()).or_insert(0);
        let sym_pnl = pnl.entry(fill.symbol.clone()).or_insert(0.0);

        match fill.side {
            Side::Buy => {
                *pos += fill.qty as i64;
                *sym_pnl -= fill.price * fill.qty as f64;
            }
            Side::Sell => {
                *pos -= fill.qty as i64;
                *sym_pnl += fill.price * fill.qty as f64;
            }
        }

        println!(
            "[FILL] {:?} | position={} | cash_pnl={:.2}",
            fill, *pos, *sym_pnl
        );
    }
}

fn main() {
    let (tx_md, rx_md) = unbounded::<MarketData>();
    let (tx_order, rx_order) = unbounded::<Order>();
    let (tx_approved, rx_approved) = unbounded::<Order>();
    let (tx_fill, rx_fill) = unbounded::<Fill>();

    let t1 = thread::spawn(move || market_data_gateway(tx_md));
    let t2 = thread::spawn(move || strategy_engine(rx_md, tx_order));
    let t3 = thread::spawn(move || risk_engine(rx_order, tx_approved, 100));
    let t4 = thread::spawn(move || order_manager(rx_approved, tx_fill));
    let t5 = thread::spawn(move || portfolio_service(rx_fill));

    let _ = t1.join();
    let _ = t2.join();
    let _ = t3.join();
    let _ = t4.join();
    let _ = t5.join();
}
