use std::thread;
use std::time::{Duration, SystemTime};
use crossbeam_channel::{unbounded, Receiver, Sender};

#[derive(Debug, Clone)]
struct MarketTick {
    symbol: String,
    bid: f64,
    ask: f64,
    ts: u128,
}

#[derive(Debug, Clone)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone)]
struct Order {
    id: u64,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
    ts: u128,
}

#[derive(Debug, Clone)]
struct Fill {
    order_id: u64,
    symbol: String,
    qty: u64,
    price: f64,
    ts: u128,
}

fn now_micros() -> u128 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        .as_micros()
}

fn market_data_publisher(tx: Sender<MarketTick>) {
    let symbol = "FOO".to_string();
    let mut px = 100.0;

    loop {
        px += 0.01;
        let tick = MarketTick {
            symbol: symbol.clone(),
            bid: px - 0.01,
            ask: px + 0.01,
            ts: now_micros(),
        };

        if tx.send(tick).is_err() {
            break;
        }

        thread::sleep(Duration::from_millis(100));
    }
}

fn strategy_engine(rx: Receiver<MarketTick>, tx: Sender<Order>) {
    let mut next_id = 1u64;

    for tick in rx.iter() {
        if tick.ask < 100.50 {
            let order = Order {
                id: next_id,
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 10,
                price: tick.ask,
                ts: now_micros(),
            };
            next_id += 1;

            if tx.send(order).is_err() {
                break;
            }
        }
    }
}

fn risk_engine(rx: Receiver<Order>, tx: Sender<Order>) {
    let max_order_qty = 100u64;

    for order in rx.iter() {
        if order.qty <= max_order_qty {
            if tx.send(order).is_err() {
                break;
            }
        } else {
            println!("Risk rejected order: {:?}", order);
        }
    }
}

fn order_router(rx: Receiver<Order>, tx: Sender<Fill>) {
    for order in rx.iter() {
        let fill = Fill {
            order_id: order.id,
            symbol: order.symbol.clone(),
            qty: order.qty,
            price: order.price,
            ts: now_micros(),
        };

        if tx.send(fill).is_err() {
            break;
        }
    }
}

fn execution_reporter(rx: Receiver<Fill>) {
    for fill in rx.iter() {
        println!("Fill: {:?}", fill);
    }
}

fn main() {
    let (md_tx, md_rx) = unbounded::<MarketTick>();
    let (order_tx, order_rx) = unbounded::<Order>();
    let (risk_tx, risk_rx) = unbounded::<Order>();
    let (fill_tx, fill_rx) = unbounded::<Fill>();

    let md_handle = thread::spawn(move || market_data_publisher(md_tx));
    let strat_handle = thread::spawn(move || strategy_engine(md_rx, order_tx));
    let risk_handle = thread::spawn(move || risk_engine(order_rx, risk_tx));
    let router_handle = thread::spawn(move || order_router(risk_rx, fill_tx));
    let exec_handle = thread::spawn(move || execution_reporter(fill_rx));

    let _ = md_handle.join();
    let _ = strat_handle.join();
    let _ = risk_handle.join();
    let _ = router_handle.join();
    let _ = exec_handle.join();
}
