```rust
use serde::{Deserialize, Serialize};
use std::cmp::Reverse;
use std::collections::{BTreeMap, VecDeque};
use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "lowercase")]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Order {
    id: u64,
    symbol: String,
    side: Side,
    price: u64,
    qty: u64,
    ts: u64,
}

#[derive(Debug, Serialize, Deserialize)]
struct Execution {
    taker_order_id: u64,
    maker_order_id: u64,
    symbol: String,
    price: u64,
    qty: u64,
}

#[derive(Default)]
struct OrderBook {
    buys: BTreeMap<Reverse<u64>, VecDeque<Order>>,
    sells: BTreeMap<u64, VecDeque<Order>>,
}

impl OrderBook {
    fn add_order(&mut self, mut incoming: Order) -> Vec<Execution> {
        let mut executions = Vec::new();

        match incoming.side {
            Side::Buy => {
                while incoming.qty > 0 {
                    let best_sell_price = match self.sells.keys().next().cloned() {
                        Some(p) => p,
                        None => break,
                    };
                    if best_sell_price > incoming.price {
                        break;
                    }

                    let queue = self.sells.get_mut(&best_sell_price).unwrap();
                    while incoming.qty > 0 && !queue.is_empty() {
                        let maker = queue.front_mut().unwrap();
                        let traded = incoming.qty.min(maker.qty);

                        executions.push(Execution {
                            taker_order_id: incoming.id,
                            maker_order_id: maker.id,
                            symbol: incoming.symbol.clone(),
                            price: maker.price,
                            qty: traded,
                        });

                        incoming.qty -= traded;
                        maker.qty -= traded;

                        if maker.qty == 0 {
                            queue.pop_front();
                        }
                    }

                    if queue.is_empty() {
                        self.sells.remove(&best_sell_price);
                    }
                }

                if incoming.qty > 0 {
                    self.buys
                        .entry(Reverse(incoming.price))
                        .or_default()
                        .push_back(incoming);
                }
            }
            Side::Sell => {
                while incoming.qty > 0 {
                    let best_buy_price = match self.buys.keys().next().cloned() {
                        Some(Reverse(p)) => p,
                        None => break,
                    };
                    if best_buy_price < incoming.price {
                        break;
                    }

                    let queue = self.buys.get_mut(&Reverse(best_buy_price)).unwrap();
                    while incoming.qty > 0 && !queue.is_empty() {
                        let maker = queue.front_mut().unwrap();
                        let traded = incoming.qty.min(maker.qty);

                        executions.push(Execution {
                            taker_order_id: incoming.id,
                            maker_order_id: maker.id,
                            symbol: incoming.symbol.clone(),
                            price: maker.price,
                            qty: traded,
                        });

                        incoming.qty -= traded;
                        maker.qty -= traded;

                        if maker.qty == 0 {
                            queue.pop_front();
                        }
                    }

                    if queue.is_empty() {
                        self.buys.remove(&Reverse(best_buy_price));
                    }
                }

                if incoming.qty > 0 {
                    self.sells.entry(incoming.price).or_default().push_back(incoming);
                }
            }
        }

        executions
    }
}

fn handle_client(stream: TcpStream, books: &mut BTreeMap<String, OrderBook>) {
    let reader = BufReader::new(stream.try_clone().unwrap());
    let mut writer = stream;

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };

        let order: Order = match serde_json::from_str(&line) {
            Ok(o) => o,
            Err(e) => {
                let _ = writeln!(writer, "{{\"error\":\"{}\"}}", e);
                continue;
            }
        };

        let book = books.entry(order.symbol.clone()).or_default();
        let executions = book.add_order(order);

        for exec in executions {
            let msg = serde_json::to_string(&exec).unwrap();
            let _ = writeln!(writer, "{}", msg);
        }

        let _ = writeln!(writer, "{{\"status\":\"accepted\"}}");
    }
}

fn main() {
    let listener = TcpListener::bind("127.0.0.1:9000").expect("bind failed");
    let mut books: BTreeMap<String, OrderBook> = BTreeMap::new();

    println!("matching engine listening on 127.0.0.1:9000");

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => handle_client(stream, &mut books),
            Err(e) => eprintln!("connection error: {}", e),
        }
    }
}
```

