## `gateway/main.go`
```go
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"io"
	"log"
	"net"
	"net/http"
	"time"
)

type Order struct {
	ID     uint64 `json:"id"`
	Symbol string `json:"symbol"`
	Side   string `json:"side"`
	Price  uint64 `json:"price"`
	Qty    uint64 `json:"qty"`
	TS     uint64 `json:"ts"`
}

func submitOrderToEngine(order Order) ([]string, error) {
	conn, err := net.DialTimeout("tcp", "127.0.0.1:9000", 2*time.Second)
	if err != nil {
		return nil, err
	}
	defer conn.Close()

	payload, err := json.Marshal(order)
	if err != nil {
		return nil, err
	}

	_, err = conn.Write(append(payload, '\n'))
	if err != nil {
		return nil, err
	}

	var responses []string
	reader := bufio.NewReader(conn)

	for {
		conn.SetReadDeadline(time.Now().Add(100 * time.Millisecond))
		line, err := reader.ReadBytes('\n')
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				break
			}
			if err == io.EOF {
				break
			}
			return responses, err
		}
		responses = append(responses, string(bytes.TrimSpace(line)))
		if bytes.Contains(line, []byte(`"status":"accepted"`)) {
			break
		}
	}

	return responses, nil
}

func orderHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var order Order
	if err := json.NewDecoder(r.Body).Decode(&order); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	responses, err := submitOrderToEngine(order)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]any{
		"engine_responses": responses,
	})
}

func main() {
	http.HandleFunc("/order", orderHandler)
	log.Println("gateway listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
