    void printBook() const;

private:
    mutable std::mutex mutex_;

    // buy: highest price first
    std::map<double, std::deque<Order>, std::greater<double>> bids_;

    // sell: lowest price first
    std::map<double, std::deque<Order>, std::less<double>> asks_;
