# 4. `order_book.cpp`

```cpp
#include "order_book.hpp"
#include <iostream>

std::vector<Trade> OrderBook::addOrder(const Order& incoming) {
    std::lock_guard<std::mutex> lock(mutex_);

    std::vector<Trade> trades;
    Order order = incoming;

    if (order.side == Side::Buy) {
        while (order.quantity > 0 && !asks_.empty()) {
            auto bestAskIt = asks_.begin();
            double bestAskPrice = bestAskIt->first;

            if (order.price < bestAskPrice) break;

            auto& queue = bestAskIt->second;
            while (order.quantity > 0 && !queue.empty()) {
                Order& resting = queue.front();
                uint32_t matchedQty = std::min(order.quantity, resting.quantity);

                trades.push_back({
                    order.id,
                    resting.id,
                    order.symbol,
                    bestAskPrice,
                    matchedQty
                });

                order.quantity -= matchedQty;
                resting.quantity -= matchedQty;

                if (resting.quantity == 0) {
                    queue.pop_front();
                }
            }

            if (queue.empty()) {
                asks_.erase(bestAskIt);
            }
        }

        if (order.quantity > 0) {
            bids_[order.price].push_back(order);
        }
    } else {
        while (order.quantity > 0 && !bids_.empty()) {
            auto bestBidIt = bids_.begin();
            double bestBidPrice = bestBidIt->first;

            if (order.price > bestBidPrice) break;

            auto& queue = bestBidIt->second;
            while (order.quantity > 0 && !queue.empty()) {
                Order& resting = queue.front();
                uint32_t matchedQty = std::min(order.quantity, resting.quantity);

                trades.push_back({
                    resting.id,
                    order.id,
                    order.symbol,
                    bestBidPrice,
                    matchedQty
                });

                order.quantity -= matchedQty;
                resting.quantity -= matchedQty;

                if (resting.quantity == 0) {
                    queue.pop_front();
                }
            }

            if (queue.empty()) {
                bids_.erase(bestBidIt);
            }
        }

        if (order.quantity > 0) {
            asks_[order.price].push_back(order);
        }
    }

    return trades;
}

void OrderBook::printBook() const {
    std::lock_guard<std::mutex> lock(mutex_);

    std::cout << "\n--- ORDER BOOK ---\n";
    std::cout << "BIDS:\n";
    for (const auto& [price, orders] : bids_) {
        uint32_t totalQty = 0;
        for (const auto& o : orders) totalQty += o.quantity;
        std::cout << price << " -> " << totalQty << "\n";
    }

    std::cout << "ASKS:\n";
    for (const auto& [price, orders] : asks_) {
        uint32_t totalQty = 0;
        for (const auto& o : orders) totalQty += o.quantity;
        std::cout << price << " -> " << totalQty << "\n";
    }
    std::cout << "------------------\n";
}
