# 8. `gateway.cpp`

```cpp
#include "gateway.hpp"
#include <iostream>
#include <sstream>
#include <thread>
#include <vector>
#include <cstring>

#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>

Gateway::Gateway(MatchingEngine& engine) : engine_(engine) {}

void Gateway::handleClient(int clientSock) {
    char buffer[1024] = {0};

    while (true) {
        ssize_t bytesRead = read(clientSock, buffer, sizeof(buffer) - 1);
        if (bytesRead <= 0) break;

        buffer[bytesRead] = '\0';
        std::stringstream ss(buffer);

        // Format:
        // BUY AAPL 150.25 100
        // SELL AAPL 150.20 50
        std::string sideStr, symbol;
        double price;
        uint32_t qty;

        ss >> sideStr >> symbol >> price >> qty;
        if (ss.fail()) {
            std::string err = "ERR Invalid order format\n";
            send(clientSock, err.c_str(), err.size(), 0);
            continue;
        }

        Side side = (sideStr == "BUY") ? Side::Buy : Side::Sell;

        Order order{
            nextOrderId_++,
            symbol,
            side,
            price,
            qty
        };

        auto trades = engine_.submitOrder(order);

        std::stringstream response;
        response << "ACK " << order.id << "\n";

        for (const auto& trade : trades) {
            response << "TRADE "
                     << trade.symbol << " "
                     << trade.price << " "
                     << trade.quantity << " "
                     << "BUY_ID=" << trade.buyOrderId << " "
                     << "SELL_ID=" << trade.sellOrderId << "\n";
        }

        std::string out = response.str();
        send(clientSock, out.c_str(), out.size(), 0);
    }

    close(clientSock);
}

void Gateway::run(uint16_t port) {
    int serverFd = socket(AF_INET, SOCK_STREAM, 0);
    if (serverFd == 0) {
        throw std::runtime_error("socket failed");
    }

    int opt = 1;
    setsockopt(serverFd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    sockaddr_in address{};
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(serverFd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        throw std::runtime_error("bind failed");
    }

    if (listen(serverFd, 16) < 0) {
        throw std::runtime_error("listen failed");
    }

    std::cout << "Gateway listening on port " << port << "\n";

    while (true) {
        sockaddr_in clientAddr{};
        socklen_t clientLen = sizeof(clientAddr);
        int clientSock = accept(serverFd, (struct sockaddr*)&clientAddr, &clientLen);
        if (clientSock < 0) {
            continue;
        }

        std::thread(&Gateway::handleClient, this, clientSock).detach();
    }
}
