```rust
use crossbeam::channel::{unbounded, Receiver, Sender};
use rand::Rng;
use std::collections::HashMap;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
struct MarketData {
    symbol: String,
    price: f64,
    ts: Instant,
}

#[derive(Debug, Clone, PartialEq)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone)]
struct Order {
    id: u64,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
    ts: Instant,
}

#[derive(Debug, Clone)]
struct Fill {
    order_id: u64,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
    ts: Instant,
}

#[derive(Debug, Default, Clone)]
struct Position {
    qty: i64,
    avg_price: f64,
    realized_pnl: f64,
}

impl Position {
    fn apply_fill(&mut self, fill: &Fill) {
        match fill.side {
            Side::Buy => {
                let current_value = self.avg_price * self.qty as f64;
                let fill_value = fill.price * fill.qty as f64;
                self.qty += fill.qty as i64;
                if self.qty != 0 {
                    self.avg_price = (current_value + fill_value) / self.qty as f64;
                }
            }
            Side::Sell => {
                let sell_qty = fill.qty as i64;
                let pnl = (fill.price - self.avg_price) * sell_qty as f64;
                self.realized_pnl += pnl;
                self.qty -= sell_qty;
                if self.qty == 0 {
                    self.avg_price = 0.0;
                }
            }
        }
    }
}

#[derive(Debug)]
struct RiskEngine {
    max_order_qty: u64,
    max_position_abs: i64,
}

impl RiskEngine {
    fn check_order(&self, order: &Order, current_pos: i64) -> bool {
        if order.qty > self.max_order_qty {
            return false;
        }

        let projected = match order.side {
            Side::Buy => current_pos + order.qty as i64,
            Side::Sell => current_pos - order.qty as i64,
        };

        projected.abs() <= self.max_position_abs
    }
}

#[derive(Debug)]
struct Strategy {
    threshold: f64,
    order_qty: u64,
    last_price: Option<f64>,
    next_order_id: u64,
}

impl Strategy {
    fn on_market_data(&mut self, md: &MarketData) -> Option<Order> {
        let mut order = None;

        if md.price < self.threshold {
            order = Some(Order {
                id: self.next_order_id,
                symbol: md.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                price: md.price,
                ts: Instant::now(),
            });
            self.next_order_id += 1;
        }

        self.last_price = Some(md.price);
        order
    }
}

fn market_data_producer(tx: Sender<MarketData>, symbol: String) {
    let mut rng = rand::thread_rng();
    let mut price = 100.0;

    loop {
        let delta: f64 = rng.gen_range(-0.8..0.8);
        price = (price + delta).max(1.0);

        let md = MarketData {
            symbol: symbol.clone(),
            price,
            ts: Instant::now(),
        };

        if tx.send(md).is_err() {
            break;
        }

        thread::sleep(Duration::from_millis(10));
    }
}

fn strategy_loop(
    md_rx: Receiver<MarketData>,
    order_tx: Sender<Order>,
    mut strategy: Strategy,
    risk: RiskEngine,
    positions: Sender<Fill>,
    pos_snapshot_rx: Receiver<HashMap<String, Position>>,
) {
    let mut latest_positions: HashMap<String, Position> = HashMap::new();

    loop {
        crossbeam::select! {
            recv(md_rx) -> msg => {
                match msg {
                    Ok(md) => {
                        if let Some(order) = strategy.on_market_data(&md) {
                            let current_pos = latest_positions
                                .get(&order.symbol)
                                .map(|p| p.qty)
                                .unwrap_or(0);

                            if risk.check_order(&order, current_pos) {
                                if order_tx.send(order).is_err() {
                                    break;
                                }
                            }
                        }
                    }
                    Err(_) => break,
                }
            }
            recv(pos_snapshot_rx) -> snapshot => {
                if let Ok(snapshot) = snapshot {
                    latest_positions = snapshot;
                }
            }
            recv(positions) -> _ => {}
        }
    }
}

fn exchange_simulator(order_rx: Receiver<Order>, fill_tx: Sender<Fill>) {
    loop {
        match order_rx.recv() {
            Ok(order) => {
                let fill = Fill {
                    order_id: order.id,
                    symbol: order.symbol,
                    side: order.side,
                    qty: order.qty,
                    price: order.price,
                    ts: Instant::now(),
                };

                if fill_tx.send(fill).is_err() {
                    break;
                }
            }
            Err(_) => break,
        }
    }
}

fn position_keeper(fill_rx: Receiver<Fill>, pos_tx: Sender<HashMap<String, Position>>) {
    let mut positions: HashMap<String, Position> = HashMap::new();

    loop {
        match fill_rx.recv() {
            Ok(fill) => {
                let pos = positions.entry(fill.symbol.clone()).or_default();
                pos.apply_fill(&fill);

                println!(
                    "[FILL] order_id={} symbol={} side={:?} qty={} px={:.2} pos={} avg={:.2} realized_pnl={:.2}",
                    fill.order_id,
                    fill.symbol,
                    fill.side,
                    fill.qty,
                    fill.price,
                    pos.qty,
                    pos.avg_price,
                    pos.realized_pnl
                );

                let _ = pos_tx.send(positions.clone());
            }
            Err(_) => break,
        }
    }
}

fn main() {
    let (md_tx, md_rx) = unbounded::<MarketData>();
    let (order_tx, order_rx) = unbounded::<Order>();
    let (fill_tx, fill_rx) = unbounded::<Fill>();
    let (pos_tx, pos_rx) = unbounded::<HashMap<String, Position>>();

    let symbol = "FOO".to_string();

    let strategy = Strategy {
        threshold: 99.5,
        order_qty: 10,
        last_price: None,
        next_order_id: 1,
    };

    let risk = RiskEngine {
        max_order_qty: 100,
        max_position_abs: 200,
    };

    let md_handle = {
        let tx = md_tx.clone();
        let symbol = symbol.clone();
        thread::spawn(move || market_data_producer(tx, symbol))
    };

    let exchange_handle = {
        let rx = order_rx;
        let tx = fill_tx.clone();
        thread::spawn(move || exchange_simulator(rx, tx))
    };

    let positions_handle = {
        let rx = fill_rx;
        let tx = pos_tx.clone();
        thread::spawn(move || position_keeper(rx, tx))
    };

    let strategy_handle = {
        let rx = md_rx;
        let tx = order_tx.clone();
        let pos_rx = pos_rx;
        thread::spawn(move || {
            strategy_loop(
                rx,
                tx,
                strategy,
                risk,
                fill_tx,
                pos_rx,
            )
        })
    };

    thread::sleep(Duration::from_secs(10));

    drop(md_tx);
    drop(order_tx);
    drop(pos_tx);

    let _ = md_handle.join();
    let _ = exchange_handle.join();
    let _ = positions_handle.join();
    let _ = strategy_handle.join();
}
```

