    }
}

fn position_keeper(fill_rx: Receiver<Fill>, pos_tx: Sender<HashMap<String, Position>>) {
    let mut positions: HashMap<String, Position> = HashMap::new();

    while let Ok(fill) = fill_rx.recv() {
        let pos = positions.entry(fill.symbol.clone()).or_default();
        pos.apply_fill(&fill);

        println!(
            "[FILL] order_id={} symbol={} side={:?} qty={} px={:.2} pos={} avg={:.2} realized_pnl={:.2}",
            fill.order_id,
            fill.symbol,
            fill.side,
            fill.qty,
            fill.price,
            pos.qty,
            pos.avg_price,
            pos.realized_pnl
        );

        if pos_tx.send(positions.clone()).is_err() {
            break;
        }
    }
}

fn main() {
    let (md_tx, md_rx) = unbounded::<MarketData>();
    let (order_tx, order_rx) = unbounded::<Order>();
    let (fill_tx, fill_rx) = unbounded::<Fill>();
    let (pos_tx, pos_rx) = unbounded::<HashMap<String, Position>>();

    let symbol = "FOO".to_string();

    let strategy = Strategy {
        threshold: 99.5,
        order_qty: 10,
        next_order_id: 1,
    };

    let risk = RiskEngine {
        max_order_qty: 100,
        max_position_abs: 200,
    };

    let md_handle = {
        let tx = md_tx.clone();
        let symbol = symbol.clone();
        thread::spawn(move || market_data_producer(tx, symbol))
    };

    let exchange_handle = {
        let rx = order_rx;
        let tx = fill_tx.clone();
        thread::spawn(move || exchange_simulator(rx, tx))
    };

    let positions_handle = {
        let rx = fill_rx;
        let tx = pos_tx.clone();
        thread::spawn(move || position_keeper(rx, tx))
    };

    let strategy_handle = {
        let md_rx = md_rx;
        let pos_rx = pos_rx;
        let order_tx = order_tx.clone();
        thread::spawn(move || strategy_loop(md_rx, pos_rx, order_tx, strategy, risk))
    };

    thread::sleep(Duration::from_secs(10));

    drop(md_tx);
    drop(order_tx);
    drop(fill_tx);
    drop(pos_tx);

    let _ = md_handle.join();
    let _ = exchange_handle.join();
    let _ = positions_handle.join();
    let _ = strategy_handle.join();
}
