```rust
use std::collections::{HashMap, VecDeque};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use tokio::sync::{broadcast, mpsc};
use tokio::time::{self, Instant};

#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
    size: u64,
    ts_millis: u128,
}

#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    window_secs: u64,
    tick_count: usize,
    total_volume: u64,
    vwap: f64,
    min_price: f64,
    max_price: f64,
    last_price: f64,
    ts_millis: u128,
}

#[derive(Debug, Clone)]
struct TimedTick {
    instant: Instant,
    tick: Tick,
}

struct SymbolWindow {
    ticks: VecDeque<TimedTick>,
}

impl SymbolWindow {
    fn new() -> Self {
        Self {
            ticks: VecDeque::new(),
        }
    }

    fn push(&mut self, timed_tick: TimedTick) {
        self.ticks.push_back(timed_tick);
    }

    fn evict_old(&mut self, now: Instant, window: Duration) {
        while let Some(front) = self.ticks.front() {
            if now.duration_since(front.instant) > window {
                self.ticks.pop_front();
            } else {
                break;
            }
        }
    }

    fn compute_aggregate(&self, symbol: &str, window_secs: u64) -> Option<Aggregate> {
        if self.ticks.is_empty() {
            return None;
        }

        let mut tick_count = 0usize;
        let mut total_volume = 0u64;
        let mut total_px_sz = 0.0f64;
        let mut min_price = f64::INFINITY;
        let mut max_price = f64::NEG_INFINITY;
        let mut last_price = 0.0f64;
        let mut ts_millis = 0u128;

        for tt in &self.ticks {
            let t = &tt.tick;
            tick_count += 1;
            total_volume += t.size;
            total_px_sz += t.price * t.size as f64;
            min_price = min_price.min(t.price);
            max_price = max_price.max(t.price);
            last_price = t.price;
            ts_millis = t.ts_millis;
        }

        let vwap = if total_volume > 0 {
            total_px_sz / total_volume as f64
        } else {
            last_price
        };

        Some(Aggregate {
            symbol: symbol.to_string(),
            window_secs,
            tick_count,
            total_volume,
            vwap,
            min_price,
            max_price,
            last_price,
            ts_millis,
        })
    }
}

struct Processor {
    rx: mpsc::Receiver<Tick>,
    tx: broadcast::Sender<Aggregate>,
    windows: HashMap<String, SymbolWindow>,
    window: Duration,
    publish_interval: Duration,
}

impl Processor {
    fn new(
        rx: mpsc::Receiver<Tick>,
        tx: broadcast::Sender<Aggregate>,
        window: Duration,
        publish_interval: Duration,
    ) -> Self {
        Self {
            rx,
            tx,
            windows: HashMap::new(),
            window,
            publish_interval,
        }
    }

    async fn run(mut self) {
        let mut ticker = time::interval(self.publish_interval);

        loop {
            tokio::select! {
                Some(tick) = self.rx.recv() => {
                    let now = Instant::now();
                    let symbol = tick.symbol.clone();

                    let window = self.windows
                        .entry(symbol)
                        .or_insert_with(SymbolWindow::new);

                    window.push(TimedTick { instant: now, tick });
                    window.evict_old(now, self.window);
                }

                _ = ticker.tick() => {
                    let now = Instant::now();
                    let window_secs = self.window.as_secs();

                    let mut dead_symbols = Vec::new();

                    for (symbol, win) in self.windows.iter_mut() {
                        win.evict_old(now, self.window);

                        if let Some(agg) = win.compute_aggregate(symbol, window_secs) {
                            let _ = self.tx.send(agg);
                        } else {
                            dead_symbols.push(symbol.clone());
                        }
                    }

                    for symbol in dead_symbols {
                        self.windows.remove(&symbol);
                    }
                }
            }
        }
    }
}

fn now_millis() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis()
}

#[tokio::main]
async fn main() {
    let (tick_tx, tick_rx) = mpsc::channel::<Tick>(10_000);
    let (agg_tx, _) = broadcast::channel::<Aggregate>(10_000);

    let processor = Processor::new(
        tick_rx,
        agg_tx.clone(),
        Duration::from_secs(5),
        Duration::from_millis(500),
    );

    tokio::spawn(processor.run());

    // Subscriber 1
    let mut sub1 = agg_tx.subscribe();
    tokio::spawn(async move {
        while let Ok(agg) = sub1.recv().await {
            println!(
                "[SUB1] {} window={}s count={} vol={} vwap={:.4} min={:.4} max={:.4} last={:.4}",
                agg.symbol,
                agg.window_secs,
                agg.tick_count,
                agg.total_volume,
                agg.vwap,
                agg.min_price,
                agg.max_price,
                agg.last_price
            );
        }
    });

    // Subscriber 2
    let mut sub2 = agg_tx.subscribe();
    tokio::spawn(async move {
        while let Ok(agg) = sub2.recv().await {
            if agg.symbol == "AAPL" {
                println!("[SUB2] AAPL update: {:?}", agg);
            }
        }
    });

    // Simulated market data feed
    tokio::spawn(async move {
        let symbols = ["AAPL", "MSFT", "GOOG"];
        let mut px = HashMap::from([
            ("AAPL".to_string(), 190.0f64),
            ("MSFT".to_string(), 410.0f64),
            ("GOOG".to_string(), 175.0f64),
        ]);

        let mut interval = time::interval(Duration::from_millis(100));
        let mut i = 0u64;

        loop {
            interval.tick().await;

            let sym = symbols[(i as usize) % symbols.len()].to_string();
            let p = px.get_mut(&sym).unwrap();

            let delta = match i % 5 {
                0 => -0.15,
                1 => 0.05,
                2 => 0.20,
                3 => -0.10,
                _ => 0.08,
            };

            *p += delta;

            let tick = Tick {
                symbol: sym,
                price: *p,
                size: 100 + (i % 10) * 10,
                ts_millis: now_millis(),
            };

            if tick_tx.send(tick).await.is_err() {
                break;
            }

            i += 1;
        }
    });

    // Keep process alive
    loop {
        time::sleep(Duration::from_secs(60)).await;
    }
}
