```go
package main

import (
	"context"
	"encoding/json"
	"log"
	"math/rand"
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

type Trade struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Size      float64   `json:"size"`
	Timestamp time.Time `json:"timestamp"`
}

type Aggregate struct {
	Symbol        string    `json:"symbol"`
	LastPrice     float64   `json:"last_price"`
	Count         int64     `json:"count"`
	Volume        float64   `json:"volume"`
	VWAP          float64   `json:"vwap"`
	High          float64   `json:"high"`
	Low           float64   `json:"low"`
	WindowStart   time.Time `json:"window_start"`
	LastUpdated   time.Time `json:"last_updated"`
	NotionalTotal float64   `json:"notional_total"`
}

type aggregateState struct {
	lastPrice     float64
	count         int64
	volume        float64
	notionalTotal float64
	high          float64
	low           float64
	windowStart   time.Time
	lastUpdated   time.Time
	initialized   bool
}

func (s *aggregateState) applyTrade(t Trade) Aggregate {
	if !s.initialized {
		s.high = t.Price
		s.low = t.Price
		s.windowStart = t.Timestamp.Truncate(time.Minute)
		s.initialized = true
	}
	if t.Price > s.high {
		s.high = t.Price
	}
	if t.Price < s.low {
		s.low = t.Price
	}
	s.lastPrice = t.Price
	s.count++
	s.volume += t.Size
	s.notionalTotal += t.Price * t.Size
	s.lastUpdated = t.Timestamp

	vwap := 0.0
	if s.volume > 0 {
		vwap = s.notionalTotal / s.volume
	}

	return Aggregate{
		Symbol:        t.Symbol,
		LastPrice:     s.lastPrice,
		Count:         s.count,
		Volume:        s.volume,
		VWAP:          vwap,
		High:          s.high,
		Low:           s.low,
		WindowStart:   s.windowStart,
		LastUpdated:   s.lastUpdated,
		NotionalTotal: s.notionalTotal,
	}
}

type Processor struct {
	mu          sync.RWMutex
	states      map[string]*aggregateState
	subscribers map[chan Aggregate]struct{}
	input       chan Trade
}

func NewProcessor(buffer int) *Processor {
	return &Processor{
		states:      make(map[string]*aggregateState),
		subscribers: make(map[chan Aggregate]struct{}),
		input:       make(chan Trade, buffer),
	}
}

func (p *Processor) PublishTrade(t Trade) {
	select {
	case p.input <- t:
	default:
		log.Printf("dropping trade due to full input buffer: %+v", t)
	}
}

func (p *Processor) Subscribe(buffer int) (<-chan Aggregate, func()) {
	ch := make(chan Aggregate, buffer)

	p.mu.Lock()
	p.subscribers[ch] = struct{}{}
	p.mu.Unlock()

	cancel := func() {
		p.mu.Lock()
		if _, ok := p.subscribers[ch]; ok {
			delete(p.subscribers, ch)
			close(ch)
		}
		p.mu.Unlock()
	}

	return ch, cancel
}

func (p *Processor) broadcast(agg Aggregate) {
	p.mu.RLock()
	defer p.mu.RUnlock()

	for ch := range p.subscribers {
		select {
		case ch <- agg:
		default:
			// Slow subscriber: drop update instead of blocking processor.
		}
	}
}

func (p *Processor) Run(ctx context.Context) {
	for {
		select {
		case <-ctx.Done():
			return
		case t := <-p.input:
			p.mu.Lock()
			state, ok := p.states[t.Symbol]
			if !ok {
				state = &aggregateState{}
				p.states[t.Symbol] = state
			}
			agg := state.applyTrade(t)
			p.mu.Unlock()

			p.broadcast(agg)
		}
	}
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

func serveWebSocket(processor *Processor) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		conn, err := upgrader.Upgrade(w, r, nil)
		if err != nil {
			log.Printf("websocket upgrade failed: %v", err)
			return
		}
		defer conn.Close()

		sub, cancel := processor.Subscribe(256)
		defer cancel()

		for agg := range sub {
			if err := conn.WriteJSON(agg); err != nil {
				log.Printf("websocket write failed: %v", err)
				return
			}
		}
	}
}

func servePublish(processor *Processor) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var t Trade
		if err := json.NewDecoder(r.Body).Decode(&t); err != nil {
			http.Error(w, "invalid json", http.StatusBadRequest)
			return
		}
		if t.Timestamp.IsZero() {
			t.Timestamp = time.Now().UTC()
		}

		processor.PublishTrade(t)
		w.WriteHeader(http.StatusAccepted)
	}
}

func simulateTrades(ctx context.Context, processor *Processor) {
	symbols := []string{"AAPL", "MSFT", "GOOG", "TSLA", "NVDA"}
	base := map[string]float64{
		"AAPL": 185.0,
		"MSFT": 420.0,
		"GOOG": 175.0,
		"TSLA": 240.0,
		"NVDA": 120.0,
	}

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case now := <-ticker.C:
			s := symbols[rand.Intn(len(symbols))]
			move := (rand.Float64() - 0.5) * 2.0
			base[s] += move
			if base[s] < 1 {
				base[s] = 1
			}

			trade := Trade{
				Symbol:    s,
				Price:     base[s],
				Size:      float64(rand.Intn(900)+100) / 10.0,
				Timestamp: now.UTC(),
			}
			processor.PublishTrade(trade)
		}
	}
}

func main() {
	rand.Seed(time.Now().UnixNano())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	processor := NewProcessor(4096)

	go processor.Run(ctx)
	go simulateTrades(ctx, processor)

	http.HandleFunc("/ws", serveWebSocket(processor))
	http.HandleFunc("/trade", servePublish(processor))
	http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	})

	log.Println("server listening on :8080")
	log.Println("websocket stream: ws://localhost:8080/ws")
	log.Println("publish trade: POST http://localhost:8080/trade")

	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}
