```go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"strings"
	"sync"
	"time"
)

type Tick struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Volume    float64   `json:"volume"`
	Timestamp time.Time `json:"timestamp"`
}

type Aggregate struct {
	Symbol        string    `json:"symbol"`
	Count         int64     `json:"count"`
	SumPrice      float64   `json:"sumPrice"`
	AvgPrice      float64   `json:"avgPrice"`
	MinPrice      float64   `json:"minPrice"`
	MaxPrice      float64   `json:"maxPrice"`
	TotalVolume   float64   `json:"totalVolume"`
	VolumePrice   float64   `json:"volumePrice"`
	VWAP          float64   `json:"vwap"`
	LastPrice     float64   `json:"lastPrice"`
	LastUpdatedAt time.Time `json:"lastUpdatedAt"`
}

type Aggregator struct {
	mu         sync.RWMutex
	aggregates map[string]*Aggregate
}

func NewAggregator() *Aggregator {
	return &Aggregator{
		aggregates: make(map[string]*Aggregate),
	}
}

func (a *Aggregator) Update(t Tick) Aggregate {
	a.mu.Lock()
	defer a.mu.Unlock()

	agg, exists := a.aggregates[t.Symbol]
	if !exists {
		agg = &Aggregate{
			Symbol:      t.Symbol,
			MinPrice:    math.MaxFloat64,
			MaxPrice:    -math.MaxFloat64,
			LastUpdatedAt: t.Timestamp,
		}
		a.aggregates[t.Symbol] = agg
	}

	agg.Count++
	agg.SumPrice += t.Price
	agg.AvgPrice = agg.SumPrice / float64(agg.Count)
	if t.Price < agg.MinPrice {
		agg.MinPrice = t.Price
	}
	if t.Price > agg.MaxPrice {
		agg.MaxPrice = t.Price
	}
	agg.TotalVolume += t.Volume
	agg.VolumePrice += t.Price * t.Volume
	if agg.TotalVolume > 0 {
		agg.VWAP = agg.VolumePrice / agg.TotalVolume
	}
	agg.LastPrice = t.Price
	agg.LastUpdatedAt = t.Timestamp

	return *agg
}

func (a *Aggregator) Get(symbol string) (Aggregate, bool) {
	a.mu.RLock()
	defer a.mu.RUnlock()

	agg, ok := a.aggregates[symbol]
	if !ok {
		return Aggregate{}, false
	}
	return *agg, true
}

func (a *Aggregator) GetAll() []Aggregate {
	a.mu.RLock()
	defer a.mu.RUnlock()

	out := make([]Aggregate, 0, len(a.aggregates))
	for _, agg := range a.aggregates {
		out = append(out, *agg)
	}
	return out
}

type Subscriber struct {
	id      string
	symbol  string
	updates chan Aggregate
}

type Broker struct {
	mu          sync.RWMutex
	subscribers map[string]*Subscriber
}

func NewBroker() *Broker {
	return &Broker{
		subscribers: make(map[string]*Subscriber),
	}
}

func (b *Broker) Subscribe(symbol string) *Subscriber {
	id := fmt.Sprintf("%d", time.Now().UnixNano())
	sub := &Subscriber{
		id:      id,
		symbol:  strings.ToUpper(symbol),
		updates: make(chan Aggregate, 128),
	}

	b.mu.Lock()
	b.subscribers[id] = sub
	b.mu.Unlock()

	return sub
}

func (b *Broker) Unsubscribe(id string) {
	b.mu.Lock()
	defer b.mu.Unlock()

	if sub, ok := b.subscribers[id]; ok {
		close(sub.updates)
		delete(b.subscribers, id)
	}
}

func (b *Broker) Publish(agg Aggregate) {
	b.mu.RLock()
	defer b.mu.RUnlock()

	for _, sub := range b.subscribers {
		if sub.symbol == "" || sub.symbol == agg.Symbol {
			select {
			case sub.updates <- agg:
			default:
				// Drop if subscriber is too slow.
			}
		}
	}
}

type Processor struct {
	aggregator *Aggregator
	broker     *Broker
	input      chan Tick
}

func NewProcessor(buffer int) *Processor {
	return &Processor{
		aggregator: NewAggregator(),
		broker:     NewBroker(),
		input:      make(chan Tick, buffer),
	}
}

func (p *Processor) Start(ctx context.Context) {
	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case tick := <-p.input:
				agg := p.aggregator.Update(tick)
				p.broker.Publish(agg)
			}
		}
	}()
}

func (p *Processor) Submit(t Tick) error {
	select {
	case p.input <- t:
		return nil
	default:
		return fmt.Errorf("processor input buffer full")
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	processor := NewProcessor(10000)
	processor.Start(ctx)

	mux := http.NewServeMux()

	// POST /ticks
	mux.HandleFunc("/ticks", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var tick Tick
		if err := json.NewDecoder(r.Body).Decode(&tick); err != nil {
			http.Error(w, "invalid json", http.StatusBadRequest)
			return
		}

		tick.Symbol = strings.ToUpper(strings.TrimSpace(tick.Symbol))
		if tick.Symbol == "" {
			http.Error(w, "symbol is required", http.StatusBadRequest)
			return
		}
		if tick.Timestamp.IsZero() {
			tick.Timestamp = time.Now().UTC()
		}

		if err := processor.Submit(tick); err != nil {
			http.Error(w, err.Error(), http.StatusServiceUnavailable)
			return
		}

		w.WriteHeader(http.StatusAccepted)
	})

	// GET /aggregates
	mux.HandleFunc("/aggregates", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(processor.aggregator.GetAll())
	})

	// GET /aggregates/{symbol}
	mux.HandleFunc("/aggregates/", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		symbol := strings.TrimPrefix(r.URL.Path, "/aggregates/")
		symbol = strings.ToUpper(strings.TrimSpace(symbol))
		if symbol == "" {
			http.Error(w, "symbol is required", http.StatusBadRequest)
			return
		}

		agg, ok := processor.aggregator.Get(symbol)
		if !ok {
			http.Error(w, "not found", http.StatusNotFound)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(agg)
	})

	// GET /stream?symbol=AAPL
	mux.HandleFunc("/stream", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		flusher, ok := w.(http.Flusher)
		if !ok {
			http.Error(w, "streaming unsupported", http.StatusInternalServerError)
			return
		}

		symbol := strings.ToUpper(strings.TrimSpace(r.URL.Query().Get("symbol")))
		sub := processor.broker.Subscribe(symbol)
		defer processor.broker.Unsubscribe(sub.id)

		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")

		fmt.Fprintf(w, "event: connected\ndata: %s\n\n", `{"status":"ok"}`)
		flusher.Flush()

		notify := r.Context().Done()

		for {
			select {
			case <-notify:
				return
			case agg, ok := <-sub.updates:
				if !ok {
					return
				}
				payload, err := json.Marshal(agg)
				if err != nil {
					continue
				}
				fmt.Fprintf(w, "event: aggregate\ndata: %s\n\n", payload)
				flusher.Flush()
			}
		}
	})

	server := &http.Server{
		Addr:    ":8080",
		Handler: mux,
	}

	log.Println("market data processor listening on :8080")
	if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatal(err)
	}
}
