```rust
use std::{collections::HashMap, net::SocketAddr, sync::Arc};

use futures::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use tokio::sync::{broadcast, Mutex};
use warp::Filter;

#[derive(Debug, Clone, Deserialize)]
struct Tick {
    symbol: String,
    price: f64,
    ts: u64,
}

#[derive(Debug, Clone, Serialize)]
struct Aggregate {
    symbol: String,
    last_price: f64,
    avg_price: f64,
    high_price: f64,
    low_price: f64,
    count: u64,
    ts: u64,
}

#[derive(Debug, Clone)]
struct AggState {
    last_price: f64,
    sum_price: f64,
    high_price: f64,
    low_price: f64,
    count: u64,
    ts: u64,
}

impl AggState {
    fn new(price: f64, ts: u64) -> Self {
        Self {
            last_price: price,
            sum_price: price,
            high_price: price,
            low_price: price,
            count: 1,
            ts,
        }
    }

    fn update(&mut self, price: f64, ts: u64) {
        self.last_price = price;
        self.sum_price += price;
        self.count += 1;
        self.ts = ts;
        if price > self.high_price {
            self.high_price = price;
        }
        if price < self.low_price {
            self.low_price = price;
        }
    }

    fn to_aggregate(&self, symbol: String) -> Aggregate {
        Aggregate {
            symbol,
            last_price: self.last_price,
            avg_price: self.sum_price / self.count as f64,
            high_price: self.high_price,
            low_price: self.low_price,
            count: self.count,
            ts: self.ts,
        }
    }
}

type SharedState = Arc<Mutex<HashMap<String, AggState>>>;

#[tokio::main]
async fn main() {
    let state: SharedState = Arc::new(Mutex::new(HashMap::new()));
    let (tx, _) = broadcast::channel::<String>(1024);

    let state_filter = warp::any().map({
        let state = state.clone();
        move || state.clone()
    });

    let tx_filter = warp::any().map({
        let tx = tx.clone();
        move || tx.clone()
    });

    // WebSocket endpoint for publishers sending ticks
    // Connect to ws://127.0.0.1:8080/publish
    let publish_route = warp::path("publish")
        .and(warp::ws())
        .and(state_filter.clone())
        .and(tx_filter.clone())
        .map(|ws: warp::ws::Ws, state: SharedState, tx: broadcast::Sender<String>| {
            ws.on_upgrade(move |socket| handle_publisher(socket, state, tx))
        });

    // WebSocket endpoint for subscribers receiving aggregates
    // Connect to ws://127.0.0.1:8080/subscribe
    let subscribe_route = warp::path("subscribe")
        .and(warp::ws())
        .and(tx_filter.clone())
        .map(|ws: warp::ws::Ws, tx: broadcast::Sender<String>| {
            ws.on_upgrade(move |socket| handle_subscriber(socket, tx.subscribe()))
        });

    let routes = publish_route.or(subscribe_route);

    let addr: SocketAddr = ([127, 0, 0, 1], 8080).into();
    println!("Server running on ws://{}", addr);
    println!("Publisher endpoint:  ws://{}/publish", addr);
    println!("Subscriber endpoint: ws://{}/subscribe", addr);

    warp::serve(routes).run(addr).await;
}

async fn handle_publisher(
    ws: warp::ws::WebSocket,
    state: SharedState,
    tx: broadcast::Sender<String>,
) {
    let (_writer, mut reader) = ws.split();

    while let Some(result) = reader.next().await {
        match result {
            Ok(msg) if msg.is_text() => {
                let text = match msg.to_str() {
                    Ok(t) => t,
                    Err(_) => continue,
                };

                let tick: Tick = match serde_json::from_str(text) {
                    Ok(t) => t,
                    Err(err) => {
                        eprintln!("Invalid tick JSON: {err}");
                        continue;
                    }
                };

                let aggregate = {
                    let mut map = state.lock().await;
                    let entry = map
                        .entry(tick.symbol.clone())
                        .or_insert_with(|| AggState::new(tick.price, tick.ts));

                    if entry.count > 1 || entry.last_price != tick.price || entry.ts != tick.ts {
                        if !(entry.count == 1 && entry.sum_price == tick.price) {
                            entry.update(tick.price, tick.ts);
                        }
                    }

                    entry.to_aggregate(tick.symbol.clone())
                };

                match serde_json::to_string(&aggregate) {
                    Ok(payload) => {
                        let _ = tx.send(payload);
                    }
                    Err(err) => {
                        eprintln!("Failed to serialize aggregate: {err}");
                    }
                }
            }
            Ok(_) => {}
            Err(err) => {
                eprintln!("Publisher socket error: {err}");
                break;
            }
        }
    }
}

async fn handle_subscriber(
    ws: warp::ws::WebSocket,
    mut rx: broadcast::Receiver<String>,
) {
    let (mut writer, mut reader) = ws.split();

    // Drain inbound subscriber messages in a background task so the socket stays healthy
    let reader_task = tokio::spawn(async move {
        while let Some(msg) = reader.next().await {
            if msg.is_err() {
                break;
            }
        }
    });

    while let Ok(payload) = rx.recv().await {
        if writer.send(warp::ws::Message::text(payload)).await.is_err() {
            break;
        }
    }

    reader_task.abort();
}
