## Initial Go Implementation

```go
package main

import (
	"encoding/json"
	"log"
	"math"
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

type Tick struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Size      float64   `json:"size"`
	Timestamp time.Time `json:"timestamp"`
}

type Aggregate struct {
	Symbol      string    `json:"symbol"`
	LastPrice   float64   `json:"last_price"`
	AvgPrice    float64   `json:"avg_price"`
	HighPrice   float64   `json:"high_price"`
	LowPrice    float64   `json:"low_price"`
	Count       int64     `json:"count"`
	Volume      float64   `json:"volume"`
	VWAP        float64   `json:"vwap"`
	WindowStart time.Time `json:"window_start"`
	WindowEnd   time.Time `json:"window_end"`
	UpdatedAt   time.Time `json:"updated_at"`
}

type SymbolState struct {
	Symbol      string
	WindowStart time.Time
	WindowEnd   time.Time

	LastPrice float64
	SumPrice  float64
	HighPrice float64
	LowPrice  float64
	Count     int64
	Volume    float64
	PVSum     float64
}

func NewSymbolState(symbol string, now time.Time, windowSize time.Duration) *SymbolState {
	return &SymbolState{
		Symbol:      symbol,
		WindowStart: now.Truncate(windowSize),
		WindowEnd:   now.Truncate(windowSize).Add(windowSize),
		HighPrice:   -math.MaxFloat64,
		LowPrice:    math.MaxFloat64,
	}
}

func (s *SymbolState) Reset(now time.Time, windowSize time.Duration) {
	s.WindowStart = now.Truncate(windowSize)
	s.WindowEnd = s.WindowStart.Add(windowSize)
	s.LastPrice = 0
	s.SumPrice = 0
	s.HighPrice = -math.MaxFloat64
	s.LowPrice = math.MaxFloat64
	s.Count = 0
	s.Volume = 0
	s.PVSum = 0
}

func (s *SymbolState) Apply(t Tick) {
	s.LastPrice = t.Price
	s.SumPrice += t.Price
	if t.Price > s.HighPrice {
		s.HighPrice = t.Price
	}
	if t.Price < s.LowPrice {
		s.LowPrice = t.Price
	}
	s.Count++
	s.Volume += t.Size
	s.PVSum += t.Price * t.Size
}

func (s *SymbolState) Snapshot(now time.Time) Aggregate {
	avg := 0.0
	vwap := 0.0
	high := 0.0
	low := 0.0

	if s.Count > 0 {
		avg = s.SumPrice / float64(s.Count)
		high = s.HighPrice
		low = s.LowPrice
	}
	if s.Volume > 0 {
		vwap = s.PVSum / s.Volume
	}

	return Aggregate{
		Symbol:      s.Symbol,
		LastPrice:   s.LastPrice,
		AvgPrice:    avg,
		HighPrice:   high,
		LowPrice:    low,
		Count:       s.Count,
		Volume:      s.Volume,
		VWAP:        vwap,
		WindowStart: s.WindowStart,
		WindowEnd:   s.WindowEnd,
		UpdatedAt:   now,
	}
}

type Hub struct {
	mu          sync.RWMutex
	subscribers map[string]map[*Client]struct{}
}

func NewHub() *Hub {
	return &Hub{
		subscribers: make(map[string]map[*Client]struct{}),
	}
}

func (h *Hub) Subscribe(symbol string, c *Client) {
	h.mu.Lock()
	defer h.mu.Unlock()

	if h.subscribers[symbol] == nil {
		h.subscribers[symbol] = make(map[*Client]struct{})
	}
	h.subscribers[symbol][c] = struct{}{}
}

func (h *Hub) Unsubscribe(symbol string, c *Client) {
	h.mu.Lock()
	defer h.mu.Unlock()

	if subs, ok := h.subscribers[symbol]; ok {
		delete(subs, c)
		if len(subs) == 0 {
			delete(h.subscribers, symbol)
		}
	}
}

func (h *Hub) RemoveClient(c *Client) {
	h.mu.Lock()
	defer h.mu.Unlock()

	for symbol, subs := range h.subscribers {
		delete(subs, c)
		if len(subs) == 0 {
			delete(h.subscribers, symbol)
		}
	}
}

func (h *Hub) Broadcast(agg Aggregate) {
	h.mu.RLock()
	defer h.mu.RUnlock()

	subs := h.subscribers[agg.Symbol]
	if len(subs) == 0 {
		return
	}

	msg, err := json.Marshal(agg)
	if err != nil {
		return
	}

	for c := range subs {
		select {
		case c.send <- msg:
		default:
			// Drop slow clients
		}
	}
}

type Client struct {
	conn *websocket.Conn
	send chan []byte
	hub  *Hub
}

type SubscribeMessage struct {
	Action string `json:"action"`
	Symbol string `json:"symbol"`
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

func (c *Client) readLoop() {
	defer func() {
		c.hub.RemoveClient(c)
		c.conn.Close()
	}()

	for {
		_, data, err := c.conn.ReadMessage()
		if err != nil {
			return
		}

		var msg SubscribeMessage
		if err := json.Unmarshal(data, &msg); err != nil {
			continue
		}

		switch msg.Action {
		case "subscribe":
			c.hub.Subscribe(msg.Symbol, c)
		case "unsubscribe":
			c.hub.Unsubscribe(msg.Symbol, c)
		}
	}
}

func (c *Client) writeLoop() {
	defer c.conn.Close()

	for msg := range c.send {
		if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
			return
		}
	}
}

type Processor struct {
	windowSize time.Duration
	input      chan Tick
	hub        *Hub

	mu     sync.Mutex
	states map[string]*SymbolState
}

func NewProcessor(windowSize time.Duration, hub *Hub) *Processor {
	return &Processor{
		windowSize: windowSize,
		input:      make(chan Tick, 1024),
		hub:        hub,
		states:     make(map[string]*SymbolState),
	}
}

func (p *Processor) Submit(t Tick) {
	p.input <- t
}

func (p *Processor) Run() {
	ticker := time.NewTicker(200 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case tick := <-p.input:
			p.handleTick(tick)
		case now := <-ticker.C:
			p.flushSnapshots(now)
		}
	}
}

func (p *Processor) handleTick(t Tick) {
	p.mu.Lock()
	defer p.mu.Unlock()

	state, ok := p.states[t.Symbol]
	if !ok {
		state = NewSymbolState(t.Symbol, t.Timestamp, p.windowSize)
		p.states[t.Symbol] = state
	}

	if !t.Timestamp.Before(state.WindowEnd) {
		agg := state.Snapshot(t.Timestamp)
		p.hub.Broadcast(agg)
		state.Reset(t.Timestamp, p.windowSize)
	}

	state.Apply(t)
}

func (p *Processor) flushSnapshots(now time.Time) {
	p.mu.Lock()
	defer p.mu.Unlock()

	for _, state := range p.states {
		if state.Count > 0 {
			agg := state.Snapshot(now)
			p.hub.Broadcast(agg)
		}
	}
}

func wsHandler(hub *Hub) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		conn, err := upgrader.Upgrade(w, r, nil)
		if err != nil {
			return
		}

		client := &Client{
			conn: conn,
			send: make(chan []byte, 256),
			hub:  hub,
		}

		go client.writeLoop()
		go client.readLoop()
	}
}

func ingestHandler(processor *Processor) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var tick Tick
		if err := json.NewDecoder(r.Body).Decode(&tick); err != nil {
			http.Error(w, "invalid json", http.StatusBadRequest)
			return
		}

		if tick.Timestamp.IsZero() {
			tick.Timestamp = time.Now().UTC()
		}

		processor.Submit(tick)
		w.WriteHeader(http.StatusAccepted)
	}
}

func main() {
	hub := NewHub()
	processor := NewProcessor(1*time.Second, hub)

	go processor.Run()

	http.HandleFunc("/ws", wsHandler(hub))
	http.HandleFunc("/tick", ingestHandler(processor))

	log.Println("server listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
```

