use axum::{
    extract::{
        ws::{Message, WebSocket, WebSocketUpgrade},
        State,
    },
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use chrono::{DateTime, Utc};
use futures::{sink::SinkExt, stream::StreamExt};
use serde::{Deserialize, Serialize};
use std::{
    collections::{HashMap, VecDeque},
    net::SocketAddr,
    sync::Arc,
};
use tokio::sync::{broadcast, Mutex};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Tick {
    symbol: String,
    price: f64,
    size: f64,
    ts: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Aggregate {
    symbol: String,
    last_price: f64,
    count: u64,
    sum_price: f64,
    sum_size: f64,
    avg_price: f64,
    vwap: f64,
    high: f64,
    low: f64,
    window_seconds: i64,
    ts: DateTime<Utc>,
}

#[derive(Debug, Clone)]
struct TickWindow {
    ticks: VecDeque<Tick>,
}

impl TickWindow {
    fn new() -> Self {
        Self {
            ticks: VecDeque::new(),
        }
    }

    fn push(&mut self, tick: Tick) {
        self.ticks.push_back(tick);
    }

    fn evict_old(&mut self, now: DateTime<Utc>, window_seconds: i64) {
        while let Some(front) = self.ticks.front() {
            let age = now.signed_duration_since(front.ts).num_seconds();
            if age > window_seconds {
                self.ticks.pop_front();
            } else {
                break;
            }
        }
    }

    fn compute(&self, symbol: &str, now: DateTime<Utc>, window_seconds: i64) -> Option<Aggregate> {
        if self.ticks.is_empty() {
            return None;
        }

        let mut count = 0u64;
        let mut sum_price = 0.0;
        let mut sum_size = 0.0;
        let mut weighted_sum = 0.0;
        let mut high = f64::MIN;
        let mut low = f64::MAX;
        let mut last_price = 0.0;

        for tick in &self.ticks {
            count += 1;
            sum_price += tick.price;
            sum_size += tick.size;
            weighted_sum += tick.price * tick.size;
            if tick.price > high {
                high = tick.price;
            }
            if tick.price < low {
                low = tick.price;
            }
            last_price = tick.price;
        }

        let avg_price = sum_price / count as f64;
        let vwap = if sum_size > 0.0 {
            weighted_sum / sum_size
        } else {
            0.0
        };

        Some(Aggregate {
            symbol: symbol.to_string(),
            last_price,
            count,
            sum_price,
            sum_size,
            avg_price,
            vwap,
            high,
            low,
            window_seconds,
            ts: now,
        })
    }
}

#[derive(Clone)]
struct AppState {
    aggregates: Arc<Mutex<HashMap<String, TickWindow>>>,
    tx: broadcast::Sender<Aggregate>,
    window_seconds: i64,
}

async fn ingest_tick(
    State(state): State<AppState>,
    Json(tick): Json<Tick>,
) -> impl IntoResponse {
    let now = Utc::now();
    let mut map = state.aggregates.lock().await;
    let window = map.entry(tick.symbol.clone()).or_insert_with(TickWindow::new);

    window.push(tick.clone());
    window.evict_old(now, state.window_seconds);

    if let Some(agg) = window.compute(&tick.symbol, now, state.window_seconds) {
        let _ = state.tx.send(agg.clone());
        Json(agg)
    } else {
        Json(Aggregate {
            symbol: tick.symbol,
            last_price: 0.0,
            count: 0,
            sum_price: 0.0,
            sum_size: 0.0,
            avg_price: 0.0,
            vwap: 0.0,
            high: 0.0,
            low: 0.0,
            window_seconds: state.window_seconds,
            ts: now,
        })
    }
}

async fn ws_handler(
    ws: WebSocketUpgrade,
    State(state): State<AppState>,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_socket(socket, state))
}

async fn handle_socket(mut socket: WebSocket, state: AppState) {
    let mut rx = state.tx.subscribe();

    while let Ok(agg) = rx.recv().await {
        let msg = match serde_json::to_string(&agg) {
            Ok(m) => m,
            Err(_) => continue,
        };

        if socket.send(Message::Text(msg)).await.is_err() {
            break;
        }
    }
}

async fn health() -> &'static str {
    "ok"
}

#[tokio::main]
async fn main() {
    let (tx, _) = broadcast::channel(10_000);

    let state = AppState {
        aggregates: Arc::new(Mutex::new(HashMap::new())),
        tx,
        window_seconds: 60,
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/tick", post(ingest_tick))
        .route("/subscribe", get(ws_handler))
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:3000".parse().unwrap();
    println!("listening on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    axum::serve(listener, app).await.unwrap();
}
```

