use axum::{
    extract::{
        ws::{Message, WebSocket, WebSocketUpgrade},
        State,
    },
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use futures::{sink::SinkExt, stream::StreamExt};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::Arc,
};
use tokio::sync::{broadcast, RwLock};
use tower_http::cors::CorsLayer;
use tracing::{error, info};

#[derive(Debug, Clone, Deserialize)]
struct TradeEvent {
    symbol: String,
    price: f64,
    size: f64,
    ts: u64,
}

#[derive(Debug, Clone, Serialize)]
struct AggregateUpdate {
    symbol: String,
    last_price: f64,
    count: u64,
    total_volume: f64,
    notional: f64,
    average_price: f64,
    high: f64,
    low: f64,
    ts: u64,
}

#[derive(Debug, Clone)]
struct SymbolAggregate {
    last_price: f64,
    count: u64,
    total_volume: f64,
    notional: f64,
    high: f64,
    low: f64,
    ts: u64,
}

impl SymbolAggregate {
    fn new(price: f64, size: f64, ts: u64) -> Self {
        Self {
            last_price: price,
            count: 1,
            total_volume: size,
            notional: price * size,
            high: price,
            low: price,
            ts,
        }
    }

    fn update(&mut self, trade: &TradeEvent) {
        self.last_price = trade.price;
        self.count += 1;
        self.total_volume += trade.size;
        self.notional += trade.price * trade.size;
        self.high = self.high.max(trade.price);
        self.low = self.low.min(trade.price);
        self.ts = trade.ts;
    }

    fn to_update(&self, symbol: String) -> AggregateUpdate {
        AggregateUpdate {
            symbol,
            last_price: self.last_price,
            count: self.count,
            total_volume: self.total_volume,
            notional: self.notional,
            average_price: if self.total_volume > 0.0 {
                self.notional / self.total_volume
            } else {
                0.0
            },
            high: self.high,
            low: self.low,
            ts: self.ts,
        }
    }
}

#[derive(Clone)]
struct AppState {
    aggregates: Arc<RwLock<HashMap<String, SymbolAggregate>>>,
    broadcaster: broadcast::Sender<AggregateUpdate>,
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (tx, _) = broadcast::channel(10_000);

    let state = AppState {
        aggregates: Arc::new(RwLock::new(HashMap::new())),
        broadcaster: tx,
    };

    let app = Router::new()
        .route("/ingest", post(ingest_trade))
        .route("/ws", get(ws_handler))
        .route("/health", get(health))
        .layer(CorsLayer::permissive())
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();
    info!("server listening on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

async fn health() -> &'static str {
    "ok"
}

async fn ingest_trade(
    State(state): State<AppState>,
    Json(trade): Json<TradeEvent>,
) -> impl IntoResponse {
    let update = {
        let mut aggregates = state.aggregates.write().await;
        let entry = aggregates
            .entry(trade.symbol.clone())
            .or_insert_with(|| SymbolAggregate::new(trade.price, trade.size, trade.ts));

        if entry.count != 1 || entry.last_price != trade.price || entry.ts != trade.ts {
            entry.update(&trade);
        }

        entry.to_update(trade.symbol.clone())
    };

    let _ = state.broadcaster.send(update.clone());

    Json(update)
}

async fn ws_handler(
    ws: WebSocketUpgrade,
    State(state): State<AppState>,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_socket(socket, state))
}

async fn handle_socket(socket: WebSocket, state: AppState) {
    let (mut sender, mut receiver) = socket.split();
    let mut rx = state.broadcaster.subscribe();

    let send_task = tokio::spawn(async move {
        loop {
            match rx.recv().await {
                Ok(update) => {
                    match serde_json::to_string(&update) {
                        Ok(msg) => {
                            if sender.send(Message::Text(msg)).await.is_err() {
                                break;
                            }
                        }
                        Err(err) => {
                            error!("serialize error: {}", err);
                        }
                    }
                }
                Err(err) => {
                    error!("broadcast receive error: {}", err);
                    break;
                }
            }
        }
    });

    let recv_task = tokio::spawn(async move {
        while let Some(Ok(msg)) = receiver.next().await {
            match msg {
                Message::Text(text) => {
                    info!("client message: {}", text);
                }
                Message::Close(_) => break,
                _ => {}
            }
        }
    });

    tokio::select! {
        _ = send_task => {},
        _ = recv_task => {},
    }
}
