use axum::{
    extract::ws::{Message, WebSocket, WebSocketUpgrade},
    extract::State,
    response::IntoResponse,
    routing::get,
    Router,
};
use dashmap::DashMap;
use futures::{sink::SinkExt, stream::StreamExt};
use serde::{Deserialize, Serialize};
use std::{net::SocketAddr, sync::Arc};
use tokio::{
    io::{AsyncBufReadExt, BufReader},
    net::{TcpListener, TcpStream},
    sync::broadcast,
};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Trade {
    symbol: String,
    price: f64,
    size: u64,
    ts_ms: u64,
}

#[derive(Debug, Clone, Serialize)]
struct Aggregate {
    symbol: String,
    last_price: f64,
    volume: u64,
    vwap: f64,
    high: f64,
    low: f64,
    trade_count: u64,
    last_ts_ms: u64,
}

#[derive(Debug, Clone)]
struct AggregateState {
    last_price: f64,
    volume: u64,
    notional: f64,
    high: f64,
    low: f64,
    trade_count: u64,
    last_ts_ms: u64,
}

impl AggregateState {
    fn new(trade: &Trade) -> Self {
        let notional = trade.price * trade.size as f64;
        Self {
            last_price: trade.price,
            volume: trade.size,
            notional,
            high: trade.price,
            low: trade.price,
            trade_count: 1,
            last_ts_ms: trade.ts_ms,
        }
    }

    fn update(&mut self, trade: &Trade) {
        self.last_price = trade.price;
        self.volume = self.volume.saturating_add(trade.size);
        self.notional += trade.price * trade.size as f64;
        self.high = self.high.max(trade.price);
        self.low = self.low.min(trade.price);
        self.trade_count = self.trade_count.saturating_add(1);
        self.last_ts_ms = trade.ts_ms;
    }

    fn snapshot(&self, symbol: &str) -> Aggregate {
        Aggregate {
            symbol: symbol.to_string(),
            last_price: self.last_price,
            volume: self.volume,
            vwap: if self.volume == 0 {
                0.0
            } else {
                self.notional / self.volume as f64
            },
            high: self.high,
            low: self.low,
            trade_count: self.trade_count,
            last_ts_ms: self.last_ts_ms,
        }
    }
}

#[derive(Clone)]
struct AppState {
    aggregates: Arc<DashMap<String, AggregateState>>,
    tx: broadcast::Sender<Aggregate>,
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let aggregates = Arc::new(DashMap::new());
    let (tx, _) = broadcast::channel::<Aggregate>(16_384);

    let state = AppState {
        aggregates,
        tx,
    };

    let ingest_state = state.clone();
    tokio::spawn(async move {
        if let Err(e) = run_trade_ingest("0.0.0.0:7001", ingest_state).await {
            error!("trade ingest failed: {e}");
        }
    });

    let app = Router::new()
        .route("/ws", get(ws_handler))
        .route("/health", get(|| async { "ok" }))
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();
    info!("websocket server listening on {}", addr);

    let listener = TcpListener::bind(addr).await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

async fn run_trade_ingest(addr: &str, state: AppState) -> Result<(), Box<dyn std::error::Error>> {
    let listener = TcpListener::bind(addr).await?;
    info!("trade ingest listening on {}", addr);

    loop {
        let (socket, peer) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            info!("trade producer connected: {}", peer);
            if let Err(e) = handle_trade_connection(socket, state).await {
                warn!("trade connection {} disconnected with error: {}", peer, e);
            } else {
                info!("trade producer disconnected: {}", peer);
            }
        });
    }
}

async fn handle_trade_connection(
    socket: TcpStream,
    state: AppState,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let reader = BufReader::new(socket);
    let mut lines = reader.lines();

    while let Some(line) = lines.next_line().await? {
        if line.trim().is_empty() {
            continue;
        }

        let trade: Trade = match serde_json::from_str(&line) {
            Ok(t) => t,
            Err(e) => {
                warn!("invalid trade json: {} -- {}", line, e);
                continue;
            }
        };

        let aggregate = update_aggregate(&state, trade);
        let _ = state.tx.send(aggregate);
    }

    Ok(())
}

fn update_aggregate(state: &AppState, trade: Trade) -> Aggregate {
    let symbol = trade.symbol.clone();

    let mut entry = state
        .aggregates
        .entry(symbol.clone())
        .or_insert_with(|| AggregateState::new(&trade));

    if entry.trade_count > 0 && !(entry.last_ts_ms == trade.ts_ms && entry.last_price == trade.price && trade.size == 0) {
        if entry.last_ts_ms != trade.ts_ms || entry.last_price != trade.price || trade.size != 0 {
            if entry.trade_count != 1
                || entry.last_ts_ms != trade.ts_ms
                || entry.last_price != trade.price
                || trade.size != entry.volume
            {
                if !(entry.trade_count == 1
                    && entry.last_ts_ms == trade.ts_ms
                    && entry.last_price == trade.price
                    && trade.size == entry.volume)
                {
                    entry.update(&trade);
                }
            }
        }
    }

    if entry.trade_count == 1
        && entry.last_ts_ms == trade.ts_ms
        && entry.last_price == trade.price
        && entry.volume == trade.size
    {
        // first trade already initialized via or_insert_with
    }

    entry.snapshot(&symbol)
}

async fn ws_handler(
    ws: WebSocketUpgrade,
    State(state): State<AppState>,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_ws(socket, state))
}

async fn handle_ws(socket: WebSocket, state: AppState) {
    let mut rx = state.tx.subscribe();
    let (mut sender, mut receiver) = socket.split();

    let snapshot: Vec<Aggregate> = state
        .aggregates
        .iter()
        .map(|entry| entry.value().snapshot(entry.key()))
        .collect();

    for agg in snapshot {
        match serde_json::to_string(&agg) {
            Ok(msg) => {
                if sender.send(Message::Text(msg)).await.is_err() {
                    return;
                }
            }
            Err(e) => {
                warn!("failed to serialize snapshot aggregate: {}", e);
            }
        }
    }

    let send_task = tokio::spawn(async move {
        loop {
            match rx.recv().await {
                Ok(agg) => {
                    match serde_json::to_string(&agg) {
                        Ok(msg) => {
                            if sender.send(Message::Text(msg)).await.is_err() {
                                break;
                            }
                        }
                        Err(e) => warn!("failed to serialize aggregate: {}", e),
                    }
                }
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    warn!("websocket subscriber lagged by {} messages", n);
                }
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    });

    let recv_task = tokio::spawn(async move {
        while let Some(result) = receiver.next().await {
            match result {
                Ok(Message::Ping(_)) => {}
                Ok(Message::Pong(_)) => {}
                Ok(Message::Close(_)) => break,
                Ok(Message::Text(_)) => {}
                Ok(Message::Binary(_)) => {}
                Err(_) => break,
            }
        }
    });

    tokio::select! {
        _ = send_task => {},
        _ = recv_task => {},
    }
}
```

