## File: `main.go`

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"sync"
	"time"
)

type Tick struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Size      float64   `json:"size"`
	Timestamp time.Time `json:"timestamp"`
}

type Aggregate struct {
	Symbol      string    `json:"symbol"`
	LastPrice   float64   `json:"last_price"`
	AvgPrice    float64   `json:"avg_price"`
	HighPrice   float64   `json:"high_price"`
	LowPrice    float64   `json:"low_price"`
	TotalVolume float64   `json:"total_volume"`
	TickCount   int64     `json:"tick_count"`
	UpdatedAt   time.Time `json:"updated_at"`
}

type SymbolState struct {
	LastPrice   float64
	SumPrice    float64
	HighPrice   float64
	LowPrice    float64
	TotalVolume float64
	TickCount   int64
}

type Hub struct {
	mu          sync.RWMutex
	states      map[string]*SymbolState
	subscribers map[chan Aggregate]struct{}
}

func NewHub() *Hub {
	return &Hub{
		states:      make(map[string]*SymbolState),
		subscribers: make(map[chan Aggregate]struct{}),
	}
}

func (h *Hub) ProcessTick(t Tick) Aggregate {
	h.mu.Lock()
	defer h.mu.Unlock()

	state, ok := h.states[t.Symbol]
	if !ok {
		state = &SymbolState{
			HighPrice: -math.MaxFloat64,
			LowPrice:  math.MaxFloat64,
		}
		h.states[t.Symbol] = state
	}

	state.LastPrice = t.Price
	state.SumPrice += t.Price
	state.TotalVolume += t.Size
	state.TickCount++

	if t.Price > state.HighPrice {
		state.HighPrice = t.Price
	}
	if t.Price < state.LowPrice {
		state.LowPrice = t.Price
	}

	agg := Aggregate{
		Symbol:      t.Symbol,
		LastPrice:   state.LastPrice,
		AvgPrice:    state.SumPrice / float64(state.TickCount),
		HighPrice:   state.HighPrice,
		LowPrice:    state.LowPrice,
		TotalVolume: state.TotalVolume,
		TickCount:   state.TickCount,
		UpdatedAt:   time.Now().UTC(),
	}

	for ch := range h.subscribers {
		select {
		case ch <- agg:
		default:
		}
	}

	return agg
}

func (h *Hub) Subscribe() chan Aggregate {
	ch := make(chan Aggregate, 128)
	h.mu.Lock()
	h.subscribers[ch] = struct{}{}
	h.mu.Unlock()
	return ch
}

func (h *Hub) Unsubscribe(ch chan Aggregate) {
	h.mu.Lock()
	delete(h.subscribers, ch)
	close(ch)
	h.mu.Unlock()
}

func main() {
	hub := NewHub()

	http.HandleFunc("/tick", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var t Tick
		if err := json.NewDecoder(r.Body).Decode(&t); err != nil {
			http.Error(w, "invalid json", http.StatusBadRequest)
			return
		}
		if t.Symbol == "" || t.Price <= 0 {
			http.Error(w, "invalid tick fields", http.StatusBadRequest)
			return
		}
		if t.Timestamp.IsZero() {
			t.Timestamp = time.Now().UTC()
		}

		agg := hub.ProcessTick(t)

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(agg)
	})

	http.HandleFunc("/stream", func(w http.ResponseWriter, r *http.Request) {
		flusher, ok := w.(http.Flusher)
		if !ok {
			http.Error(w, "streaming unsupported", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")

		ch := hub.Subscribe()
		defer hub.Unsubscribe(ch)

		ctx := r.Context()
		for {
			select {
			case agg := <-ch:
				data, _ := json.Marshal(agg)
				fmt.Fprintf(w, "data: %s\n\n", data)
				flusher.Flush()
			case <-ctx.Done():
				return
			}
		}
	})

	log.Println("server listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
