package main

import (
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"sync"
	"time"
)

type Tick struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Timestamp time.Time `json:"timestamp"`
}

type Aggregate struct {
	Symbol     string    `json:"symbol"`
	Last       float64   `json:"last"`
	Count      int64     `json:"count"`
	Sum        float64   `json:"sum"`
	Avg        float64   `json:"avg"`
	High       float64   `json:"high"`
	Low        float64   `json:"low"`
	UpdatedAt  time.Time `json:"updated_at"`
}

type Hub struct {
	mu          sync.RWMutex
	aggregates  map[string]*Aggregate
	subscribers map[string]map[chan Aggregate]struct{}
}

func NewHub() *Hub {
	return &Hub{
		aggregates:  make(map[string]*Aggregate),
		subscribers: make(map[string]map[chan Aggregate]struct{}),
	}
}

func (h *Hub) ProcessTick(t Tick) Aggregate {
	h.mu.Lock()
	defer h.mu.Unlock()

	agg, ok := h.aggregates[t.Symbol]
	if !ok {
		agg = &Aggregate{
			Symbol: t.Symbol,
			High:   -math.MaxFloat64,
			Low:    math.MaxFloat64,
		}
		h.aggregates[t.Symbol] = agg
	}

	agg.Last = t.Price
	agg.Count++
	agg.Sum += t.Price
	agg.Avg = agg.Sum / float64(agg.Count)
	if t.Price > agg.High {
		agg.High = t.Price
	}
	if t.Price < agg.Low {
		agg.Low = t.Price
	}
	agg.UpdatedAt = time.Now().UTC()

	result := *agg

	for ch := range h.subscribers[t.Symbol] {
		select {
		case ch <- result:
		default:
		}
	}

	return result
}

func (h *Hub) Subscribe(symbol string) chan Aggregate {
	h.mu.Lock()
	defer h.mu.Unlock()

	ch := make(chan Aggregate, 16)
	if _, ok := h.subscribers[symbol]; !ok {
		h.subscribers[symbol] = make(map[chan Aggregate]struct{})
	}
	h.subscribers[symbol][ch] = struct{}{}

	if agg, ok := h.aggregates[symbol]; ok {
		ch <- *agg
	}

	return ch
}

func (h *Hub) Unsubscribe(symbol string, ch chan Aggregate) {
	h.mu.Lock()
	defer h.mu.Unlock()

	if subs, ok := h.subscribers[symbol]; ok {
		delete(subs, ch)
		if len(subs) == 0 {
			delete(h.subscribers, symbol)
		}
	}
	close(ch)
}

func main() {
	hub := NewHub()

	http.HandleFunc("/tick", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var t Tick
		if err := json.NewDecoder(r.Body).Decode(&t); err != nil {
			http.Error(w, "invalid json", http.StatusBadRequest)
			return
		}

		if t.Symbol == "" || t.Price <= 0 {
			http.Error(w, "symbol and positive price required", http.StatusBadRequest)
			return
		}

		if t.Timestamp.IsZero() {
			t.Timestamp = time.Now().UTC()
		}

		agg := hub.ProcessTick(t)

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(agg)
	})

	http.HandleFunc("/stream", func(w http.ResponseWriter, r *http.Request) {
		symbol := r.URL.Query().Get("symbol")
		if symbol == "" {
			http.Error(w, "symbol required", http.StatusBadRequest)
			return
		}

		flusher, ok := w.(http.Flusher)
		if !ok {
			http.Error(w, "streaming unsupported", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")

		ch := hub.Subscribe(symbol)
		defer hub.Unsubscribe(symbol, ch)

		ctx := r.Context()
		for {
			select {
			case agg := <-ch:
				data, _ := json.Marshal(agg)
				fmt.Fprintf(w, "data: %s\n\n", data)
				flusher.Flush()
			case <-ctx.Done():
				return
			}
		}
	})

	http.HandleFunc("/aggregate", func(w http.ResponseWriter, r *http.Request) {
		symbol := r.URL.Query().Get("symbol")
		if symbol == "" {
			http.Error(w, "symbol required", http.StatusBadRequest)
			return
		}

		hub.mu.RLock()
		agg, ok := hub.aggregates[symbol]
		hub.mu.RUnlock()

		if !ok {
			http.Error(w, "symbol not found", http.StatusNotFound)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(agg)
	})

	log.Println("market data processor listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
