## `main.go`

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"sync"
	"time"
)

type Tick struct {
	Symbol string  `json:"symbol"`
	Price  float64 `json:"price"`
	Size   float64 `json:"size"`
	Ts     int64   `json:"ts,omitempty"`
}

type Aggregate struct {
	Symbol    string  `json:"symbol"`
	LastPrice float64 `json:"last_price"`
	Count     int64   `json:"count"`
	Volume    float64 `json:"volume"`
	VWAP      float64 `json:"vwap"`
	High      float64 `json:"high"`
	Low       float64 `json:"low"`
	UpdatedAt int64   `json:"updated_at"`
}

type symbolState struct {
	agg       Aggregate
	notional  float64
	initiated bool
}

type hub struct {
	mu          sync.RWMutex
	states      map[string]*symbolState
	subscribers map[string]map[chan Aggregate]struct{}
}

func newHub() *hub {
	return &hub{
		states:      make(map[string]*symbolState),
		subscribers: make(map[string]map[chan Aggregate]struct{}),
	}
}

func (h *hub) processTick(t Tick) Aggregate {
	h.mu.Lock()
	defer h.mu.Unlock()

	if t.Ts == 0 {
		t.Ts = time.Now().UnixMilli()
	}

	st, ok := h.states[t.Symbol]
	if !ok {
		st = &symbolState{
			agg: Aggregate{
				Symbol: t.Symbol,
				High:   -math.MaxFloat64,
				Low:    math.MaxFloat64,
			},
		}
		h.states[t.Symbol] = st
	}

	st.agg.Symbol = t.Symbol
	st.agg.LastPrice = t.Price
	st.agg.Count++
	st.agg.Volume += t.Size
	st.notional += t.Price * t.Size
	if st.agg.Volume > 0 {
		st.agg.VWAP = st.notional / st.agg.Volume
	}
	if t.Price > st.agg.High {
		st.agg.High = t.Price
	}
	if t.Price < st.agg.Low {
		st.agg.Low = t.Price
	}
	st.agg.UpdatedAt = t.Ts

	agg := st.agg
	h.broadcastLocked(t.Symbol, agg)
	return agg
}

func (h *hub) broadcastLocked(symbol string, agg Aggregate) {
	for ch := range h.subscribers[symbol] {
		select {
		case ch <- agg:
		default:
		}
	}
}

func (h *hub) subscribe(symbol string) (chan Aggregate, func()) {
	ch := make(chan Aggregate, 16)

	h.mu.Lock()
	if _, ok := h.subscribers[symbol]; !ok {
		h.subscribers[symbol] = make(map[chan Aggregate]struct{})
	}
	h.subscribers[symbol][ch] = struct{}{}

	var snapshot *Aggregate
	if st, ok := h.states[symbol]; ok {
		a := st.agg
		snapshot = &a
	}
	h.mu.Unlock()

	if snapshot != nil {
		ch <- *snapshot
	}

	cancel := func() {
		h.mu.Lock()
		defer h.mu.Unlock()
		if subs, ok := h.subscribers[symbol]; ok {
			delete(subs, ch)
			if len(subs) == 0 {
				delete(h.subscribers, symbol)
			}
		}
		close(ch)
	}

	return ch, cancel
}

func (h *hub) getAggregate(symbol string) (Aggregate, bool) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	st, ok := h.states[symbol]
	if !ok {
		return Aggregate{}, false
	}
	return st.agg, true
}

func postTickHandler(h *hub) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var t Tick
		if err := json.NewDecoder(r.Body).Decode(&t); err != nil {
			http.Error(w, "invalid json", http.StatusBadRequest)
			return
		}
		if t.Symbol == "" || t.Price <= 0 || t.Size <= 0 {
			http.Error(w, "symbol, price, size are required and must be > 0", http.StatusBadRequest)
			return
		}

		agg := h.processTick(t)

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(agg)
	}
}

func getAggregateHandler(h *hub) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		symbol := r.URL.Query().Get("symbol")
		if symbol == "" {
			http.Error(w, "missing symbol", http.StatusBadRequest)
			return
		}

		agg, ok := h.getAggregate(symbol)
		if !ok {
			http.Error(w, "symbol not found", http.StatusNotFound)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(agg)
	}
}

func streamHandler(h *hub) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		symbol := r.URL.Query().Get("symbol")
		if symbol == "" {
			http.Error(w, "missing symbol", http.StatusBadRequest)
			return
		}

		flusher, ok := w.(http.Flusher)
		if !ok {
			http.Error(w, "streaming unsupported", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")

		ch, cancel := h.subscribe(symbol)
		defer cancel()

		ctx := r.Context()
		for {
			select {
			case <-ctx.Done():
				return
			case agg, ok := <-ch:
				if !ok {
					return
				}
				data, _ := json.Marshal(agg)
				fmt.Fprintf(w, "event: aggregate\n")
				fmt.Fprintf(w, "data: %s\n\n", data)
				flusher.Flush()
			case <-time.After(15 * time.Second):
				fmt.Fprintf(w, ": keepalive\n\n")
				flusher.Flush()
			}
		}
	}
}

func main() {
	h := newHub()

	http.HandleFunc("/tick", postTickHandler(h))
	http.HandleFunc("/aggregate", getAggregateHandler(h))
	http.HandleFunc("/stream", streamHandler(h))

	addr := ":8080"
	log.Printf("market data processor listening on %s", addr)
	log.Fatal(http.ListenAndServe(addr, nil))
}
