use axum::{
    extract::{
        ws::{Message, WebSocket, WebSocketUpgrade},
        State,
    },
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use futures::{sink::SinkExt, stream::StreamExt};
use serde::{Deserialize, Serialize};
use std::{collections::HashMap, net::SocketAddr, sync::Arc};
use tokio::sync::{broadcast, Mutex};
use tower_http::cors::CorsLayer;

#[derive(Debug, Clone, Deserialize)]
struct Tick {
    symbol: String,
    price: f64,
}

#[derive(Debug, Clone, Serialize)]
struct Aggregate {
    symbol: String,
    count: u64,
    last: f64,
    sum: f64,
    avg: f64,
    min: f64,
    max: f64,
}

#[derive(Debug, Default)]
struct AggregateState {
    count: u64,
    last: f64,
    sum: f64,
    min: f64,
    max: f64,
}

impl AggregateState {
    fn update(&mut self, price: f64) {
        self.count += 1;
        self.last = price;
        self.sum += price;

        if self.count == 1 {
            self.min = price;
            self.max = price;
        } else {
            if price < self.min {
                self.min = price;
            }
            if price > self.max {
                self.max = price;
            }
        }
    }

    fn to_aggregate(&self, symbol: String) -> Aggregate {
        Aggregate {
            symbol,
            count: self.count,
            last: self.last,
            sum: self.sum,
            avg: self.sum / self.count as f64,
            min: self.min,
            max: self.max,
        }
    }
}

#[derive(Clone)]
struct AppState {
    aggregates: Arc<Mutex<HashMap<String, AggregateState>>>,
    tx: broadcast::Sender<Aggregate>,
}

#[tokio::main]
async fn main() {
    let (tx, _) = broadcast::channel(1024);

    let state = AppState {
        aggregates: Arc::new(Mutex::new(HashMap::new())),
        tx,
    };

    let app = Router::new()
        .route("/tick", post(post_tick))
        .route("/ws", get(ws_handler))
        .layer(CorsLayer::permissive())
        .with_state(state);

    let addr: SocketAddr = "0.0.0.0:3000".parse().unwrap();
    println!("listening on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

async fn post_tick(
    State(state): State<AppState>,
    Json(tick): Json<Tick>,
) -> Result<Json<Aggregate>, (axum::http::StatusCode, String)> {
    if tick.symbol.trim().is_empty() {
        return Err((axum::http::StatusCode::BAD_REQUEST, "symbol is required".into()));
    }

    let aggregate = {
        let mut map = state.aggregates.lock().await;
        let entry = map.entry(tick.symbol.clone()).or_default();
        entry.update(tick.price);
        entry.to_aggregate(tick.symbol.clone())
    };

    let _ = state.tx.send(aggregate.clone());

    Ok(Json(aggregate))
}

async fn ws_handler(
    ws: WebSocketUpgrade,
    State(state): State<AppState>,
) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_socket(socket, state))
}

async fn handle_socket(socket: WebSocket, state: AppState) {
    let (mut sender, mut receiver) = socket.split();
    let mut rx = state.tx.subscribe();

    let send_task = tokio::spawn(async move {
        while let Ok(aggregate) = rx.recv().await {
            let msg = match serde_json::to_string(&aggregate) {
                Ok(s) => s,
                Err(_) => continue,
            };

            if sender.send(Message::Text(msg)).await.is_err() {
                break;
            }
        }
    });

    let recv_task = tokio::spawn(async move {
        while let Some(Ok(msg)) = receiver.next().await {
            match msg {
                Message::Close(_) => break,
                Message::Ping(_) | Message::Pong(_) | Message::Text(_) | Message::Binary(_) => {}
            }
        }
    });

    let _ = tokio::join!(send_task, recv_task);
}
