Below is a **minimal high-performance prototype** in <language>Rust</language>, since that was my top recommendation.

It demonstrates:
- multi-producer message ingress
- routing by key
- per-message latency measurement
- atomic counters for throughput
- periodic metrics reporting

It is **not yet production-complete**, but it is a strong starting point for a high-frequency messaging system.

```rust
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use crossbeam_channel::{bounded, Receiver, Sender};
use rand::Rng;

#[derive(Clone, Debug)]
struct Message {
    route_key: u64,
    created_ns: u128,
    payload: [u8; 64],
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(actual) => current = actual,
            }
        }
    }
}

fn now_ns() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

fn producer(tx: Sender<Message>, metrics: Arc<Metrics>, producer_id: usize) {
    let mut rng = rand::thread_rng();

    loop {
        let msg = Message {
            route_key: rng.gen_range(0..16),
            created_ns: now_ns(),
            payload: [producer_id as u8; 64],
        };

        metrics.received.fetch_add(1, Ordering::Relaxed);

        if tx.try_send(msg).is_err() {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn router(rx: Receiver<Message>, worker_txs: Vec<Sender<Message>>, metrics: Arc<Metrics>) {
    while let Ok(msg) = rx.recv() {
        let idx = (msg.route_key as usize) % worker_txs.len();
        if worker_txs[idx].try_send(msg).is_ok() {
            metrics.routed.fetch_add(1, Ordering::Relaxed);
        } else {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn worker(rx: Receiver<Message>, metrics: Arc<Metrics>, _worker_id: usize) {
    while let Ok(msg) = rx.recv() {
        let latency_ns = (now_ns() - msg.created_ns) as u64;
        metrics.record_latency(latency_ns);

        let _payload_checksum = msg.payload.iter().fold(0u8, |acc, b| acc ^ b);
    }
}

fn reporter(metrics: Arc<Metrics>) {
    let mut last_received = 0;
    let mut last_routed = 0;
    let mut last_dropped = 0;

    loop {
        thread::sleep(Duration::from_secs(1));

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);
        let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);
        let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

        let delta_received = received - last_received;
        let delta_routed = routed - last_routed;
        let delta_dropped = dropped - last_dropped;

        let avg_latency = if routed > 0 {
            total_latency / routed
        } else {
            0
        };

        println!(
            "throughput_in={} msg/s throughput_routed={} msg/s dropped={} msg/s avg_latency={} ns max_latency={} ns total_received={} total_routed={}",
            delta_received,
            delta_routed,
            delta_dropped,
            avg_latency,
            max_latency,
            received,
            routed
        );

        last_received = received;
        last_routed = routed;
        last_dropped = dropped;
    }
}

fn main() {
    let metrics = Arc::new(Metrics::new());

    let (ingress_tx, ingress_rx) = bounded::<Message>(1_000_000);

    let worker_count = 8;
    let mut worker_txs = Vec::with_capacity(worker_count);

    for worker_id in 0..worker_count {
        let (tx, rx) = bounded::<Message>(100_000);
        worker_txs.push(tx);

        let m = metrics.clone();
        thread::spawn(move || worker(rx, m, worker_id));
    }

    {
        let m = metrics.clone();
        let txs = worker_txs.clone();
        thread::spawn(move || router(ingress_rx, txs, m));
    }

    for producer_id in 0..4 {
        let tx = ingress_tx.clone();
        let m = metrics.clone();
        thread::spawn(move || producer(tx, m, producer_id));
    }

    {
        let m = metrics.clone();
        thread::spawn(move || reporter(m));
    }

    loop {
        thread::park();
    }
}
