use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

use tokio::sync::mpsc;
use tokio::time;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    created: Instant,
    topic: u16,
    payload: [u8; 128],
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }
}

async fn producer(tx: mpsc::Sender<Message>, metrics: Arc<Metrics>, producer_id: u64) {
    let mut counter = 0u64;
    loop {
        let msg = Message {
            id: (producer_id << 48) | counter,
            created: Instant::now(),
            topic: (counter % 8) as u16,
            payload: [0u8; 128],
        };
        counter += 1;

        metrics.received.fetch_add(1, Ordering::Relaxed);

        if tx.send(msg).await.is_err() {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
            break;
        }
    }
}

async fn router(
    mut ingress: mpsc::Receiver<Message>,
    worker_txs: Vec<mpsc::Sender<Message>>,
    metrics: Arc<Metrics>,
) {
    while let Some(msg) = ingress.recv().await {
        let idx = (msg.topic as usize) % worker_txs.len();
        if worker_txs[idx].send(msg).await.is_ok() {
            metrics.routed.fetch_add(1, Ordering::Relaxed);
        } else {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

async fn worker(mut rx: mpsc::Receiver<Message>, metrics: Arc<Metrics>, _worker_id: usize) {
    while let Some(msg) = rx.recv().await {
        let latency = msg.created.elapsed().as_nanos() as u64;
        metrics.record_latency(latency);

        // Simulated processing
        std::hint::black_box(msg.id);
        std::hint::black_box(msg.payload);
    }
}

async fn reporter(metrics: Arc<Metrics>) {
    let mut interval = time::interval(Duration::from_secs(1));

    let mut last_received = 0;
    let mut last_routed = 0;
    let mut last_dropped = 0;
    let mut last_total_latency = 0;

    loop {
        interval.tick().await;

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);
        let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);
        let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

        let delta_received = received - last_received;
        let delta_routed = routed - last_routed;
        let delta_dropped = dropped - last_dropped;
        let delta_latency = total_latency - last_total_latency;

        let avg_latency_ns = if delta_routed > 0 {
            delta_latency / delta_routed
        } else {
            0
        };

        println!(
            "recv/s={} routed/s={} dropped/s={} avg_latency={}ns max_latency={}ns",
            delta_received, delta_routed, delta_dropped, avg_latency_ns, max_latency
        );

        last_received = received;
        last_routed = routed;
        last_dropped = dropped;
        last_total_latency = total_latency;
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() {
    let metrics = Arc::new(Metrics::new());

    let (ingress_tx, ingress_rx) = mpsc::channel::<Message>(100_000);

    let worker_count = 8;
    let mut worker_txs = Vec::with_capacity(worker_count);

    for i in 0..worker_count {
        let (tx, rx) = mpsc::channel::<Message>(100_000);
        worker_txs.push(tx);
        let m = metrics.clone();
        tokio::spawn(worker(rx, m, i));
    }

    tokio::spawn(router(ingress_rx, worker_txs, metrics.clone()));
    tokio::spawn(reporter(metrics.clone()));

    for producer_id in 0..4 {
        let tx = ingress_tx.clone();
        let m = metrics.clone();
        tokio::spawn(producer(tx, m, producer_id));
    }

    loop {
        time::sleep(Duration::from_secs(60)).await;
    }
}
