## <language>Rust</language>

```rust
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use crossbeam_channel::{bounded, Receiver, Sender};

const NUM_SHARDS: usize = 8;
const NUM_PRODUCERS: usize = 4;
const CHANNEL_CAPACITY: usize = 262_144;
const RUN_SECONDS: u64 = 10;

#[derive(Clone, Copy)]
struct Message {
    key: u64,
    created_ns: u64,
    payload: [u8; 32],
}

struct Metrics {
    routed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.routed.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns
            .fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    fn record_drop(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }
}

fn now_ns() -> u64 {
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0));
    dur.as_nanos() as u64
}

fn route_shard(key: u64) -> usize {
    (key as usize) % NUM_SHARDS
}

fn producer_thread(id: usize, shards: Arc<Vec<Sender<Message>>>, metrics: Arc<Metrics>, end: Instant) {
    let mut seq = id as u64 * 1_000_000_000;

    while Instant::now() < end {
        let msg = Message {
            key: seq,
            created_ns: now_ns(),
            payload: [id as u8; 32],
        };

        let shard_idx = route_shard(msg.key);
        if shards[shard_idx].try_send(msg).is_err() {
            metrics.record_drop();
        }

        seq = seq.wrapping_add(1);
    }
}

fn worker_thread(_id: usize, rx: Receiver<Message>, metrics: Arc<Metrics>) {
    while let Ok(msg) = rx.recv() {
        let latency_ns = now_ns().saturating_sub(msg.created_ns);

        // Simulated routing/processing:
        let _sink = msg.payload[0] ^ ((msg.key & 0xFF) as u8);

        metrics.record_latency(latency_ns);

        let _ = _sink;
    }
}

fn metrics_thread(metrics: Arc<Metrics>, end: Instant) {
    let mut last_routed = 0;
    let mut last_dropped = 0;

    while Instant::now() < end {
        thread::sleep(Duration::from_secs(1));

        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);
        let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);
        let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

        let delta_routed = routed - last_routed;
        let delta_dropped = dropped - last_dropped;
        let avg_latency = if routed > 0 {
            total_latency as f64 / routed as f64
        } else {
            0.0
        };

        println!(
            "throughput={} msg/s dropped={} msg/s total_routed={} total_dropped={} avg_latency_ns={:.0} max_latency_ns={}",
            delta_routed,
            delta_dropped,
            routed,
            dropped,
            avg_latency,
            max_latency
        );

        last_routed = routed;
        last_dropped = dropped;
    }
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let end = Instant::now() + Duration::from_secs(RUN_SECONDS);

    let mut txs = Vec::with_capacity(NUM_SHARDS);
    let mut worker_handles = Vec::with_capacity(NUM_SHARDS);

    for shard_id in 0..NUM_SHARDS {
        let (tx, rx) = bounded::<Message>(CHANNEL_CAPACITY);
        txs.push(tx);

        let m = Arc::clone(&metrics);
        worker_handles.push(thread::spawn(move || {
            worker_thread(shard_id, rx, m);
        }));
    }

    let shard_senders = Arc::new(txs);

    let mut producer_handles = Vec::with_capacity(NUM_PRODUCERS);
    for producer_id in 0..NUM_PRODUCERS {
        let senders = Arc::clone(&shard_senders);
        let m = Arc::clone(&metrics);
        producer_handles.push(thread::spawn(move || {
            producer_thread(producer_id, senders, m, end);
        }));
    }

    let metrics_handle = {
        let m = Arc::clone(&metrics);
        thread::spawn(move || metrics_thread(m, end))
    };

    for h in producer_handles {
        let _ = h.join();
    }

    drop(shard_senders);

    for h in worker_handles {
        let _ = h.join();
    }

    let _ = metrics_handle.join();

    let routed = metrics.routed.load(Ordering::Relaxed);
    let dropped = metrics.dropped.load(Ordering::Relaxed);
    let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);
    let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

    let avg_latency = if routed > 0 {
        total_latency as f64 / routed as f64
    } else {
        0.0
    };

    println!("\nFinal:");
    println!("  routed: {}", routed);
    println!("  dropped: {}", dropped);
    println!("  avg latency ns: {:.0}", avg_latency);
    println!("  max latency ns: {}", max_latency);
}
