use std::sync::{
    atomic::{AtomicU64, AtomicUsize, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use crossbeam_channel::{bounded, Receiver, Sender};

const WORKERS: usize = 4;
const QUEUE_SIZE: usize = 1_000_000;

#[derive(Clone, Debug)]
struct Message {
    route_key: u64,
    created_at_nanos: u64,
    payload: Vec<u8>,
}

struct Metrics {
    total_messages: AtomicU64,
    total_latency_nanos: AtomicU64,
    max_latency_nanos: AtomicU64,
    dropped_messages: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            total_messages: AtomicU64::new(0),
            total_latency_nanos: AtomicU64::new(0),
            max_latency_nanos: AtomicU64::new(0),
            dropped_messages: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency: u64) {
        self.total_messages.fetch_add(1, Ordering::Relaxed);
        self.total_latency_nanos
            .fetch_add(latency, Ordering::Relaxed);

        let mut current = self.max_latency_nanos.load(Ordering::Relaxed);
        while latency > current {
            match self.max_latency_nanos.compare_exchange_weak(
                current,
                latency,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    fn record_drop(&self) {
        self.dropped_messages.fetch_add(1, Ordering::Relaxed);
    }

    fn snapshot(&self) -> (u64, u64, u64, u64) {
        (
            self.total_messages.load(Ordering::Relaxed),
            self.total_latency_nanos.load(Ordering::Relaxed),
            self.max_latency_nanos.load(Ordering::Relaxed),
            self.dropped_messages.load(Ordering::Relaxed),
        )
    }
}

fn now_nanos() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

struct Router {
    worker_senders: Vec<Sender<Message>>,
    next_worker: AtomicUsize,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(worker_senders: Vec<Sender<Message>>, metrics: Arc<Metrics>) -> Self {
        Self {
            worker_senders,
            next_worker: AtomicUsize::new(0),
            metrics,
        }
    }

    fn route(&self, msg: Message) {
        let idx = (msg.route_key as usize) % self.worker_senders.len();
        if self.worker_senders[idx].try_send(msg).is_err() {
            self.metrics.record_drop();
        }
    }

    #[allow(dead_code)]
    fn route_round_robin(&self, msg: Message) {
        let idx = self.next_worker.fetch_add(1, Ordering::Relaxed) % self.worker_senders.len();
        if self.worker_senders[idx].try_send(msg).is_err() {
            self.metrics.record_drop();
        }
    }
}

fn worker_loop(id: usize, rx: Receiver<Message>, metrics: Arc<Metrics>) {
    while let Ok(msg) = rx.recv() {
        let now = now_nanos();
        let latency = now.saturating_sub(msg.created_at_nanos);

        // Simulated processing
        let _ = black_box_process(&msg.payload);

        metrics.record_latency(latency);

        if metrics.total_messages.load(Ordering::Relaxed) % 1_000_000 == 0 {
            println!("worker {} processed milestone", id);
        }
    }
}

fn black_box_process(payload: &[u8]) -> u64 {
    let mut acc = 0u64;
    for b in payload {
        acc = acc.wrapping_mul(31).wrapping_add(*b as u64);
    }
    acc
}

fn start_reporter(metrics: Arc<Metrics>) {
    thread::spawn(move || {
        let mut last_total = 0u64;

        loop {
            thread::sleep(Duration::from_secs(1));
            let (total, total_latency, max_latency, dropped) = metrics.snapshot();
            let delta = total.saturating_sub(last_total);
            last_total = total;

            let avg_latency = if total > 0 {
                total_latency / total
            } else {
                0
            };

            println!(
                "throughput={} msg/s total={} avg_latency={} ns max_latency={} ns dropped={}",
                delta, total, avg_latency, max_latency, dropped
            );
        }
    });
}

fn main() {
    let metrics = Arc::new(Metrics::new());

    let mut senders = Vec::with_capacity(WORKERS);

    for id in 0..WORKERS {
        let (tx, rx) = bounded::<Message>(QUEUE_SIZE);
        senders.push(tx);

        let metrics_clone = Arc::clone(&metrics);
        thread::spawn(move || worker_loop(id, rx, metrics_clone));
    }

    start_reporter(Arc::clone(&metrics));

    let router = Router::new(senders, Arc::clone(&metrics));

    let payload = vec![42u8; 128];

    loop {
        let msg = Message {
            route_key: rand::random::<u64>(),
            created_at_nanos: now_nanos(),
            payload: payload.clone(),
        };

        router.route(msg);
    }
}
