    uint64_t created_ns;
    char topic[MAX_TOPIC_LEN];
    char payload[PAYLOAD_SIZE];
};

static inline uint32_t hash_topic(const char* topic) {
    uint32_t h = 2166136261u;
    for (size_t i = 0; i < MAX_TOPIC_LEN && topic[i] != '\0'; ++i) {
        h ^= static_cast<uint8_t>(topic[i]);
        h *= 16777619u;
    }
    return h;
}

// Single-producer single-consumer ring queue
template<typename T, size_t Size>
class SPSCRingQueue {
    static_assert((Size & (Size - 1)) == 0, "Size must be power of 2");
public:
    bool push(const T& item) {
        const auto tail = tail_.load(std::memory_order_relaxed);
        const auto next = (tail + 1) & (Size - 1);
        if (next == head_.load(std::memory_order_acquire)) {
            return false; // full
        }
        buffer_[tail] = item;
        tail_.store(next, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        const auto head = head_.load(std::memory_order_relaxed);
        if (head == tail_.load(std::memory_order_acquire)) {
            return false; // empty
        }
        item = buffer_[head];
        head_.store((head + 1) & (Size - 1), std::memory_order_release);
        return true;
    }

private:
    alignas(64) std::array<T, Size> buffer_;
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
};

struct WorkerStats {
    std::atomic<uint64_t> processed{0};
    std::atomic<uint64_t> dropped{0};
    std::atomic<uint64_t> total_latency_ns{0};
    std::atomic<uint64_t> max_latency_ns{0};
};

struct LatencyCollector {
    std::vector<uint64_t> samples;
    std::atomic<uint64_t> sample_index{0};

    explicit LatencyCollector(size_t cap) : samples(cap, 0) {}

    void record(uint64_t ns) {
        uint64_t idx = sample_index.fetch_add(1, std::memory_order_relaxed);
        if (idx < samples.size()) {
            samples[idx] = ns;
        }
    }

    void report() {
        size_t count = std::min<uint64_t>(sample_index.load(), samples.size());
        if (count == 0) {
            std::cout << "No latency samples collected\n";
            return;
        }

        std::vector<uint64_t> copy(samples.begin(), samples.begin() + count);
        std::sort(copy.begin(), copy.end());

        auto pct = [&](double p) -> uint64_t {
            size_t idx = static_cast<size_t>(p * (count - 1));
            return copy[idx];
        };

        uint64_t sum = 0;
        for (auto v : copy) sum += v;

        std::cout << "Latency report:\n";
        std::cout << "  count: " << count << "\n";
        std::cout << "  avg:   " << (sum / count) << " ns\n";
        std::cout << "  p50:   " << pct(0.50) << " ns\n";
        std::cout << "  p90:   " << pct(0.90) << " ns\n";
        std::cout << "  p99:   " << pct(0.99) << " ns\n";
        std::cout << "  p999:  " << pct(0.999) << " ns\n";
        std::cout << "  max:   " << copy.back() << " ns\n";
    }
};

struct Router {
    std::array<std::unique_ptr<SPSCRingQueue<Message, QUEUE_SIZE>>, NUM_WORKERS> queues;
    std::array<WorkerStats, NUM_WORKERS> stats;
    LatencyCollector& latency;

    explicit Router(LatencyCollector& lc) : latency(lc) {
        for (auto& q : queues) {
            q = std::make_unique<SPSCRingQueue<Message, QUEUE_SIZE>>();
        }
    }

    bool route(const Message& msg) {
        uint32_t h = hash_topic(msg.topic);
        size_t worker = h % NUM_WORKERS;
        bool ok = queues[worker]->push(msg);
        if (!ok) {
            stats[worker].dropped.fetch_add(1, std::memory_order_relaxed);
        }
        return ok;
    }
};

int main() {
    LatencyCollector latencyCollector(1'000'000);
    Router router(latencyCollector);

    std::atomic<bool> start{false};
    std::atomic<bool> done{false};

    std::vector<std::thread> workers;
    workers.reserve(NUM_WORKERS);

    for (size_t i = 0; i < NUM_WORKERS; ++i) {
        workers.emplace_back([&, i]() {
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            Message msg{};
            while (!done.load(std::memory_order_acquire) || router.queues[i]->pop(msg)) {
                if (router.queues[i]->pop(msg)) {
                    uint64_t latency_ns = now_ns() - msg.created_ns;

                    router.stats[i].processed.fetch_add(1, std::memory_order_relaxed);
                    router.stats[i].total_latency_ns.fetch_add(latency_ns, std::memory_order_relaxed);

                    uint64_t prev_max = router.stats[i].max_latency_ns.load(std::memory_order_relaxed);
                    while (latency_ns > prev_max &&
                           !router.stats[i].max_latency_ns.compare_exchange_weak(
                               prev_max, latency_ns, std::memory_order_relaxed)) {
                    }

                    // Sample some latencies. In production, use a better histogram.
                    if ((msg.id & 0x3F) == 0) {
                        latencyCollector.record(latency_ns);
                    }

                    // Simulated processing
                    asm volatile("" ::: "memory");
                } else {
                    std::this_thread::yield();
                }
            }
        });
    }

    std::vector<std::thread> producers;
    producers.reserve(NUM_PRODUCERS);

    uint64_t benchmark_start_ns = 0;
    uint64_t benchmark_end_ns = 0;

    for (size_t p = 0; p < NUM_PRODUCERS; ++p) {
        producers.emplace_back([&, p]() {
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            const char* topics[] = {"orders", "trades", "quotes", "risk"};
            for (uint64_t i = 0; i < MESSAGES_PER_PRODUCER; ++i) {
                Message msg{};
                msg.id = (p * MESSAGES_PER_PRODUCER) + i;
                msg.created_ns = now_ns();
                std::strncpy(msg.topic, topics[i % 4], MAX_TOPIC_LEN - 1);
                std::memset(msg.payload, static_cast<int>(i & 0xFF), PAYLOAD_SIZE);

                while (!router.route(msg)) {
                    // Backpressure spin
                    std::this_thread::yield();
                }
            }
        });
    }

    benchmark_start_ns = now_ns();
    start.store(true, std::memory_order_release);

    for (auto& t : producers) {
        t.join();
    }

    done.store(true, std::memory_order_release);

    for (auto& t : workers) {
        t.join();
    }

    benchmark_end_ns = now_ns();

    uint64_t total_processed = 0;
    uint64_t total_dropped = 0;
    uint64_t total_latency = 0;
    uint64_t max_latency = 0;

    for (size_t i = 0; i < NUM_WORKERS; ++i) {
        total_processed += router.stats[i].processed.load();
        total_dropped += router.stats[i].dropped.load();
        total_latency += router.stats[i].total_latency_ns.load();
        max_latency = std::max(max_latency, router.stats[i].max_latency_ns.load());
    }

    double seconds = static_cast<double>(benchmark_end_ns - benchmark_start_ns) / 1e9;
    double throughput = total_processed / seconds;
    uint64_t avg_latency = total_processed ? (total_latency / total_processed) : 0;

    std::cout << "=== Benchmark Results ===\n";
    std::cout << "Processed:   " << total_processed << "\n";
    std::cout << "Dropped:     " << total_dropped << "\n";
    std::cout << "Duration:    " << seconds << " s\n";
    std::cout << "Throughput:  " << throughput << " msg/s\n";
    std::cout << "Avg latency: " << avg_latency << " ns\n";
    std::cout << "Max latency: " << max_latency << " ns\n";

    latencyCollector.report();

    return 0;
}
```

