use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use rand::Rng;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_WORKERS: usize = 8;
const QUEUE_CAPACITY: usize = 100_000;
const RUN_SECONDS: u64 = 10;
const PRODUCER_THREADS: usize = 4;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    route_key: u64,
    created_at: Instant,
    payload: [u8; 64],
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processing_errors: AtomicU64,
    latency_hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            processing_errors: AtomicU64::new(0),
            latency_hist: Mutex::new(
                Histogram::<u64>::new_with_bounds(1, 60_000_000, 3)
                    .expect("failed to create histogram"),
            ),
        }
    }

    fn record_latency_micros(&self, latency_us: u64) {
        if let Ok(mut hist) = self.latency_hist.lock() {
            let _ = hist.record(latency_us);
        }
    }
}

fn route(route_key: u64) -> usize {
    (route_key as usize) % NUM_WORKERS
}

fn worker_loop(worker_id: usize, rx: Receiver<Message>, metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let now = Instant::now();
                let latency = now.duration_since(msg.created_at).as_micros() as u64;

                // Simulated processing
                let _checksum = msg.payload.iter().fold(0u8, |acc, b| acc ^ b);

                metrics.routed.fetch_add(1, Ordering::Relaxed);
                metrics.record_latency_micros(latency);

                if worker_id == usize::MAX {
                    metrics.processing_errors.fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(_) => {}
        }
    }
}

fn producer_loop(
    producer_id: usize,
    txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
    id_counter: Arc<AtomicU64>,
) {
    let mut rng = rand::thread_rng();

    while running.load(Ordering::Relaxed) {
        let id = id_counter.fetch_add(1, Ordering::Relaxed);
        let route_key = rng.gen::<u64>();
        let shard = route(route_key);

        let msg = Message {
            id,
            route_key,
            created_at: Instant::now(),
            payload: [producer_id as u8; 64],
        };

        metrics.received.fetch_add(1, Ordering::Relaxed);

        if txs[shard].try_send(msg).is_err() {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn metrics_loop(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    let mut last_received = 0;
    let mut last_routed = 0;
    let mut last_dropped = 0;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);

        let delta_received = received - last_received;
        let delta_routed = routed - last_routed;
        let delta_dropped = dropped - last_dropped;

        last_received = received;
        last_routed = routed;
        last_dropped = dropped;

        let (p50, p95, p99, max) = {
            let hist = metrics.latency_hist.lock().unwrap();
            (
                hist.value_at_quantile(0.50),
                hist.value_at_quantile(0.95),
                hist.value_at_quantile(0.99),
                hist.max(),
            )
        };

        println!(
            "rate recv/s={} routed/s={} dropped/s={} total_recv={} total_routed={} total_dropped={} latency_us p50={} p95={} p99={} max={}",
            delta_received,
            delta_routed,
            delta_dropped,
            received,
            routed,
            dropped,
            p50,
            p95,
            p99,
            max
        );
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::new());
    let id_counter = Arc::new(AtomicU64::new(0));

    let mut txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_handles = Vec::with_capacity(NUM_WORKERS);

    for worker_id in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        txs.push(tx);

        let metrics_clone = Arc::clone(&metrics);
        let running_clone = Arc::clone(&running);

        let handle = thread::spawn(move || {
            worker_loop(worker_id, rx, metrics_clone, running_clone);
        });

        worker_handles.push(handle);
    }

    let metrics_thread = {
        let metrics_clone = Arc::clone(&metrics);
        let running_clone = Arc::clone(&running);
        thread::spawn(move || metrics_loop(metrics_clone, running_clone))
    };

    let mut producer_handles = Vec::with_capacity(PRODUCER_THREADS);
    for producer_id in 0..PRODUCER_THREADS {
        let txs_clone = txs.clone();
        let metrics_clone = Arc::clone(&metrics);
        let running_clone = Arc::clone(&running);
        let id_counter_clone = Arc::clone(&id_counter);

        let handle = thread::spawn(move || {
            producer_loop(
                producer_id,
                txs_clone,
                metrics_clone,
                running_clone,
                id_counter_clone,
            );
        });

        producer_handles.push(handle);
    }

    thread::sleep(Duration::from_secs(RUN_SECONDS));
    running.store(false, Ordering::Relaxed);

    for handle in producer_handles {
        let _ = handle.join();
    }

    for handle in worker_handles {
        let _ = handle.join();
    }

    let _ = metrics_thread.join();

    let received = metrics.received.load(Ordering::Relaxed);
    let routed = metrics.routed.load(Ordering::Relaxed);
    let dropped = metrics.dropped.load(Ordering::Relaxed);

    let hist = metrics.latency_hist.lock().unwrap();
    println!("--- final summary ---");
    println!("received: {}", received);
    println!("routed:   {}", routed);
    println!("dropped:  {}", dropped);
    println!("latency_us p50: {}", hist.value_at_quantile(0.50));
    println!("latency_us p95: {}", hist.value_at_quantile(0.95));
    println!("latency_us p99: {}", hist.value_at_quantile(0.99));
    println!("latency_us max: {}", hist.max());
}
