use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use rand::{distributions::Alphanumeric, Rng};
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use tokio::signal;

const QUEUE_CAPACITY: usize = 262_144;
const MESSAGE_PAYLOAD_SIZE: usize = 64;
const NUM_SHARDS: usize = 8;
const REPORT_INTERVAL_SECS: u64 = 1;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: String,
    payload: Vec<u8>,
    created_at_nanos: u128,
}

impl Message {
    fn new(id: u64, topic: String, payload: Vec<u8>) -> Self {
        Self {
            id,
            topic,
            payload,
            created_at_nanos: now_nanos(),
        }
    }
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,

    // Simple latency buckets in microseconds
    lat_le_10us: AtomicU64,
    lat_le_50us: AtomicU64,
    lat_le_100us: AtomicU64,
    lat_le_500us: AtomicU64,
    lat_le_1ms: AtomicU64,
    lat_gt_1ms: AtomicU64,
}

impl Metrics {
    fn record_receive(&self) {
        self.received.fetch_add(1, Ordering::Relaxed);
    }

    fn record_routed(&self) {
        self.routed.fetch_add(1, Ordering::Relaxed);
    }

    fn record_drop(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }

    fn record_processed(&self, latency_ns: u64) {
        self.processed.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }

        let us = latency_ns / 1_000;
        if us <= 10 {
            self.lat_le_10us.fetch_add(1, Ordering::Relaxed);
        } else if us <= 50 {
            self.lat_le_50us.fetch_add(1, Ordering::Relaxed);
        } else if us <= 100 {
            self.lat_le_100us.fetch_add(1, Ordering::Relaxed);
        } else if us <= 500 {
            self.lat_le_500us.fetch_add(1, Ordering::Relaxed);
        } else if us <= 1_000 {
            self.lat_le_1ms.fetch_add(1, Ordering::Relaxed);
        } else {
            self.lat_gt_1ms.fetch_add(1, Ordering::Relaxed);
        }
    }

    fn snapshot(&self) -> MetricsSnapshot {
        MetricsSnapshot {
            received: self.received.load(Ordering::Relaxed),
            routed: self.routed.load(Ordering::Relaxed),
            dropped: self.dropped.load(Ordering::Relaxed),
            processed: self.processed.load(Ordering::Relaxed),
            total_latency_ns: self.total_latency_ns.load(Ordering::Relaxed),
            max_latency_ns: self.max_latency_ns.load(Ordering::Relaxed),
            lat_le_10us: self.lat_le_10us.load(Ordering::Relaxed),
            lat_le_50us: self.lat_le_50us.load(Ordering::Relaxed),
            lat_le_100us: self.lat_le_100us.load(Ordering::Relaxed),
            lat_le_500us: self.lat_le_500us.load(Ordering::Relaxed),
            lat_le_1ms: self.lat_le_1ms.load(Ordering::Relaxed),
            lat_gt_1ms: self.lat_gt_1ms.load(Ordering::Relaxed),
        }
    }
}

#[derive(Clone, Copy)]
struct MetricsSnapshot {
    received: u64,
    routed: u64,
    dropped: u64,
    processed: u64,
    total_latency_ns: u64,
    max_latency_ns: u64,
    lat_le_10us: u64,
    lat_le_50us: u64,
    lat_le_100us: u64,
    lat_le_500us: u64,
    lat_le_1ms: u64,
    lat_gt_1ms: u64,
}

fn now_nanos() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

fn latency_since(created_at_nanos: u128) -> u64 {
    let now = now_nanos();
    now.saturating_sub(created_at_nanos) as u64
}

fn shard_for_topic(topic: &str, num_shards: usize) -> usize {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    topic.hash(&mut hasher);
    (hasher.finish() as usize) % num_shards
}

fn generate_payload(len: usize) -> Vec<u8> {
    rand::thread_rng()
        .sample_iter(&Alphanumeric)
        .take(len)
        .map(|c| c as u8)
        .collect()
}

fn start_worker(
    shard_id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) || !rx.is_empty() {
            match rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    let latency_ns = latency_since(msg.created_at_nanos);

                    // Simulated processing path:
                    let _checksum = msg.payload.iter().fold(0u64, |acc, b| acc + (*b as u64));

                    metrics.record_processed(latency_ns);

                    if msg.id % 1_000_000 == 0 {
                        println!("worker={} processed milestone message={}", shard_id, msg.id);
                    }
                }
                Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
                Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
            }
        }
    })
}

fn start_reporter(metrics: Arc<Metrics>, running: Arc<AtomicBool>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut last = metrics.snapshot();

        while running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(REPORT_INTERVAL_SECS));
            let current = metrics.snapshot();

            let delta_received = current.received.saturating_sub(last.received);
            let delta_routed = current.routed.saturating_sub(last.routed);
            let delta_dropped = current.dropped.saturating_sub(last.dropped);
            let delta_processed = current.processed.saturating_sub(last.processed);
            let delta_latency_ns = current
                .total_latency_ns
                .saturating_sub(last.total_latency_ns);

            let avg_latency_us = if delta_processed > 0 {
                (delta_latency_ns / delta_processed) as f64 / 1_000.0
            } else {
                0.0
            };

            println!(
                concat!(
                    "[metrics] recv/s={} routed/s={} processed/s={} dropped/s={} ",
                    "avg_lat_us={:.2} max_lat_us={:.2} ",
                    "buckets(us): <=10={} <=50={} <=100={} <=500={} <=1000={} >1000={}"
                ),
                delta_received,
                delta_routed,
                delta_processed,
                delta_dropped,
                avg_latency_us,
                current.max_latency_ns as f64 / 1_000.0,
                current.lat_le_10us,
                current.lat_le_50us,
                current.lat_le_100us,
                current.lat_le_500us,
                current.lat_le_1ms,
                current.lat_gt_1ms,
            );

            last = current;
        }
    })
}

fn start_router(
    ingress_rx: Receiver<Message>,
    shard_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while running.load(Ordering::Relaxed) || !ingress_rx.is_empty() {
            match ingress_rx.recv_timeout(Duration::from_millis(10)) {
                Ok(msg) => {
                    metrics.record_receive();

                    let shard = shard_for_topic(&msg.topic, shard_txs.len());
                    match shard_txs[shard].try_send(msg) {
                        Ok(_) => metrics.record_routed(),
                        Err(TrySendError::Full(_msg)) => {
                            metrics.record_drop();
                        }
                        Err(TrySendError::Disconnected(_msg)) => {
                            metrics.record_drop();
                        }
                    }
                }
                Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
                Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
            }
        }
    })
}

fn build_topic_map() -> Vec<String> {
    vec![
        "orders.new".to_string(),
        "orders.cancel".to_string(),
        "trades.executed".to_string(),
        "quotes.equity".to_string(),
        "quotes.options".to_string(),
        "risk.update".to_string(),
        "alerts".to_string(),
        "system.events".to_string(),
    ]
}

fn start_producer(
    ingress_tx: Sender<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let topics = build_topic_map();
        let mut id = 0u64;
        let mut rng = rand::thread_rng();

        while running.load(Ordering::Relaxed) {
            let topic = topics[rng.gen_range(0..topics.len())].clone();
            let payload = generate_payload(MESSAGE_PAYLOAD_SIZE);
            let msg = Message::new(id, topic, payload);

            match ingress_tx.try_send(msg) {
                Ok(_) => {}
                Err(TrySendError::Full(_)) => {
                    metrics.record_drop();
                }
                Err(TrySendError::Disconnected(_)) => break,
            }

            id = id.wrapping_add(1);
        }
    })
}

#[tokio::main]
async fn main() {
    println!(
        "starting hf-router with shards={} queue_capacity={} cpus={}",
        NUM_SHARDS,
        QUEUE_CAPACITY,
        num_cpus::get()
    );

    let metrics = Arc::new(Metrics::default());
    let running = Arc::new(AtomicBool::new(true));

    let (ingress_tx, ingress_rx) = bounded::<Message>(QUEUE_CAPACITY);

    let mut shard_txs = Vec::with_capacity(NUM_SHARDS);
    let mut worker_handles = Vec::with_capacity(NUM_SHARDS);

    for shard in 0..NUM_SHARDS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        shard_txs.push(tx);

        let handle = start_worker(shard, rx, metrics.clone(), running.clone());
        worker_handles.push(handle);
    }

    let router_handle = start_router(
        ingress_rx,
        shard_txs,
        metrics.clone(),
        running.clone(),
    );

    let reporter_handle = start_reporter(metrics.clone(), running.clone());

    let producer_handle = start_producer(
        ingress_tx,
        metrics.clone(),
        running.clone(),
    );

    println!("system running; press Ctrl+C to stop");
    signal::ctrl_c().await.unwrap();

    println!("shutdown signal received...");
    running.store(false, Ordering::Relaxed);

    producer_handle.join().unwrap();
    router_handle.join().unwrap();

    for h in worker_handles {
        h.join().unwrap();
    }

    reporter_handle.join().unwrap();

    let final_metrics = metrics.snapshot();
    let avg_latency_us = if final_metrics.processed > 0 {
        (final_metrics.total_latency_ns / final_metrics.processed) as f64 / 1_000.0
    } else {
        0.0
    };

    println!("final metrics:");
    println!("  received  = {}", final_metrics.received);
    println!("  routed    = {}", final_metrics.routed);
    println!("  dropped   = {}", final_metrics.dropped);
    println!("  processed = {}", final_metrics.processed);
    println!("  avg_lat_us= {:.2}", avg_latency_us);
    println!(
        "  max_lat_us= {:.2}",
        final_metrics.max_latency_ns as f64 / 1_000.0
    );
}
