use ahash::AHasher;
use bytes::Bytes;
use hdrhistogram::Histogram;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tokio::sync::mpsc;
use tokio::time;

const NUM_SHARDS: usize = 8;
const SHARD_QUEUE_CAPACITY: usize = 100_000;
const DEST_QUEUE_CAPACITY: usize = 100_000;
const DESTINATIONS: [&str; 4] = ["orders", "trades", "quotes", "risk"];

#[derive(Clone, Debug)]
struct Message {
    route_key: u64,
    destination: u8,
    ingress_ns: u64,
    payload: Bytes,
}

#[derive(Default)]
struct Metrics {
    routed: AtomicU64,
    dropped: AtomicU64,
    ingress_failures: AtomicU64,
    hist: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            ingress_failures: AtomicU64::new(0),
            hist: Mutex::new(Histogram::<u64>::new(3).unwrap()),
        }
    }

    fn record_latency_ns(&self, latency_ns: u64) {
        if let Ok(mut h) = self.hist.lock() {
            let _ = h.record(latency_ns);
        }
    }

    fn snapshot_and_reset(&self) -> MetricsSnapshot {
        let routed = self.routed.swap(0, Ordering::Relaxed);
        let dropped = self.dropped.swap(0, Ordering::Relaxed);
        let ingress_failures = self.ingress_failures.swap(0, Ordering::Relaxed);

        let mut p50 = 0;
        let mut p90 = 0;
        let mut p99 = 0;
        let mut max = 0;

        if let Ok(mut h) = self.hist.lock() {
            if h.len() > 0 {
                p50 = h.value_at_quantile(0.50);
                p90 = h.value_at_quantile(0.90);
                p99 = h.value_at_quantile(0.99);
                max = h.max();
            }
            h.reset();
        }

        MetricsSnapshot {
            routed,
            dropped,
            ingress_failures,
            p50,
            p90,
            p99,
            max,
        }
    }
}

struct MetricsSnapshot {
    routed: u64,
    dropped: u64,
    ingress_failures: u64,
    p50: u64,
    p90: u64,
    p99: u64,
    max: u64,
}

fn now_ns() -> u64 {
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0));
    dur.as_nanos() as u64
}

fn shard_for(route_key: u64) -> usize {
    let mut hasher = AHasher::default();
    route_key.hash(&mut hasher);
    (hasher.finish() as usize) % NUM_SHARDS
}

async fn ingress_task(
    shard_senders: Arc<Vec<mpsc::Sender<Message>>>,
    metrics: Arc<Metrics>,
) {
    let mut counter: u64 = 0;

    loop {
        // Simulated producer burst
        for _ in 0..50_000 {
            let destination = (counter % DESTINATIONS.len() as u64) as u8;
            let route_key = counter;
            let msg = Message {
                route_key,
                destination,
                ingress_ns: now_ns(),
                payload: Bytes::from_static(b"abcdefghijklmnopqrstuvwxyz"),
            };

            let shard = shard_for(route_key);
            match shard_senders[shard].try_send(msg) {
                Ok(_) => {}
                Err(_) => {
                    metrics.dropped.fetch_add(1, Ordering::Relaxed);
                }
            }

            counter = counter.wrapping_add(1);
        }

        tokio::task::yield_now().await;
    }
}

async fn router_shard_task(
    shard_id: usize,
    mut rx: mpsc::Receiver<Message>,
    destination_senders: Arc<HashMap<u8, mpsc::Sender<Message>>>,
    metrics: Arc<Metrics>,
) {
    while let Some(msg) = rx.recv().await {
        let sender = match destination_senders.get(&msg.destination) {
            Some(s) => s,
            None => {
                metrics.ingress_failures.fetch_add(1, Ordering::Relaxed);
                continue;
            }
        };

        match sender.try_send(msg.clone()) {
            Ok(_) => {
                metrics.routed.fetch_add(1, Ordering::Relaxed);
                let latency = now_ns().saturating_sub(msg.ingress_ns);
                metrics.record_latency_ns(latency);
            }
            Err(_) => {
                metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    eprintln!("router shard {} stopped", shard_id);
}

async fn egress_task(name: &'static str, mut rx: mpsc::Receiver<Message>) {
    let mut processed: u64 = 0;
    while let Some(_msg) = rx.recv().await {
        processed = processed.wrapping_add(1);

        if processed % 1_000_000 == 0 {
            println!("egress [{}] processed={}", name, processed);
        }
    }
}

async fn metrics_task(metrics: Arc<Metrics>) {
    let mut interval = time::interval(Duration::from_secs(1));

    loop {
        interval.tick().await;
        let snap = metrics.snapshot_and_reset();

        println!(
            "metrics routed={} dropped={} ingress_failures={} latency_ns p50={} p90={} p99={} max={}",
            snap.routed, snap.dropped, snap.ingress_failures, snap.p50, snap.p90, snap.p99, snap.max
        );
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() {
    let metrics = Arc::new(Metrics::new());

    let mut shard_senders = Vec::with_capacity(NUM_SHARDS);
    let mut shard_receivers = Vec::with_capacity(NUM_SHARDS);

    for _ in 0..NUM_SHARDS {
        let (tx, rx) = mpsc::channel::<Message>(SHARD_QUEUE_CAPACITY);
        shard_senders.push(tx);
        shard_receivers.push(rx);
    }

    let mut destination_receivers = Vec::new();
    let mut destination_senders_map = HashMap::new();

    for (i, name) in DESTINATIONS.iter().enumerate() {
        let (tx, rx) = mpsc::channel::<Message>(DEST_QUEUE_CAPACITY);
        destination_senders_map.insert(i as u8, tx);
        destination_receivers.push((*name, rx));
    }

    let shard_senders = Arc::new(shard_senders);
    let destination_senders = Arc::new(destination_senders_map);

    tokio::spawn(ingress_task(shard_senders.clone(), metrics.clone()));

    for (shard_id, rx) in shard_receivers.into_iter().enumerate() {
        tokio::spawn(router_shard_task(
            shard_id,
            rx,
            destination_senders.clone(),
            metrics.clone(),
        ));
    }

    for (name, rx) in destination_receivers {
        tokio::spawn(egress_task(name, rx));
    }

    tokio::spawn(metrics_task(metrics.clone()));

    loop {
        time::sleep(Duration::from_secs(3600)).await;
    }
}
