```rust
use crossbeam::channel::{bounded, Receiver, Sender};
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_PRODUCERS: usize = 4;
const NUM_WORKERS: usize = 4;
const INPUT_BUFFER: usize = 100_000;
const WORKER_BUFFER: usize = 100_000;
const RUN_SECONDS: u64 = 10;

#[derive(Clone, Copy)]
struct Message {
    id: u64,
    created_at: Instant,
    key: u64,
}

struct Metrics {
    routed: AtomicU64,
    processed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            processed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let (input_tx, input_rx) = bounded::<Message>(INPUT_BUFFER);

    let mut worker_txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_rxs = Vec::with_capacity(NUM_WORKERS);

    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(WORKER_BUFFER);
        worker_txs.push(tx);
        worker_rxs.push(rx);
    }

    let start = Instant::now();
    let end_time = start + Duration::from_secs(RUN_SECONDS);

    // Producers
    let mut handles = vec![];
    for producer_id in 0..NUM_PRODUCERS {
        let tx = input_tx.clone();
        handles.push(thread::spawn(move || {
            let mut msg_id = producer_id as u64 * 1_000_000_000;
            while Instant::now() < end_time {
                let msg = Message {
                    id: msg_id,
                    created_at: Instant::now(),
                    key: msg_id,
                };
                if tx.send(msg).is_err() {
                    break;
                }
                msg_id += 1;
            }
        }));
    }
    drop(input_tx);

    // Router
    let router_metrics = Arc::clone(&metrics);
    let router_workers = worker_txs.clone();
    let router_handle = thread::spawn(move || {
        while let Ok(msg) = input_rx.recv() {
            let idx = (msg.key as usize) % router_workers.len();
            if router_workers[idx].try_send(msg).is_ok() {
                router_metrics.routed.fetch_add(1, Ordering::Relaxed);
            } else {
                router_metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    });

    // Workers
    for rx in worker_rxs {
        let worker_metrics = Arc::clone(&metrics);
        handles.push(thread::spawn(move || worker_loop(rx, worker_metrics)));
    }

    // Metrics reporter
    let report_metrics = Arc::clone(&metrics);
    let reporter = thread::spawn(move || {
        let mut last_processed = 0;
        let mut last_routed = 0;
        let mut last_dropped = 0;

        for sec in 1..=RUN_SECONDS {
            thread::sleep(Duration::from_secs(1));

            let routed = report_metrics.routed.load(Ordering::Relaxed);
            let processed = report_metrics.processed.load(Ordering::Relaxed);
            let dropped = report_metrics.dropped.load(Ordering::Relaxed);
            let total_latency_ns = report_metrics.total_latency_ns.load(Ordering::Relaxed);
            let max_latency_ns = report_metrics.max_latency_ns.load(Ordering::Relaxed);

            let routed_delta = routed - last_routed;
            let processed_delta = processed - last_processed;
            let dropped_delta = dropped - last_dropped;

            let avg_latency_ns = if processed > 0 {
                total_latency_ns / processed
            } else {
                0
            };

            println!(
                "[{}s] routed/s={} processed/s={} dropped/s={} total_processed={} avg_latency_us={:.2} max_latency_us={:.2}",
                sec,
                routed_delta,
                processed_delta,
                dropped_delta,
                processed,
                avg_latency_ns as f64 / 1_000.0,
                max_latency_ns as f64 / 1_000.0
            );

            last_routed = routed;
            last_processed = processed;
            last_dropped = dropped;
        }
    });

    for h in handles {
        let _ = h.join();
    }

    let _ = router_handle.join();
    let _ = reporter.join();

    let processed = metrics.processed.load(Ordering::Relaxed);
    let routed = metrics.routed.load(Ordering::Relaxed);
    let dropped = metrics.dropped.load(Ordering::Relaxed);
    let avg_latency_ns = if processed > 0 {
        metrics.total_latency_ns.load(Ordering::Relaxed) / processed
    } else {
        0
    };

    println!("\nFinal Results:");
    println!("Routed: {}", routed);
    println!("Processed: {}", processed);
    println!("Dropped: {}", dropped);
    println!("Average latency: {:.2} us", avg_latency_ns as f64 / 1_000.0);
    println!(
        "Max latency: {:.2} us",
        metrics.max_latency_ns.load(Ordering::Relaxed) as f64 / 1_000.0
    );
}

fn worker_loop(rx: Receiver<Message>, metrics: Arc<Metrics>) {
    while let Ok(msg) = rx.recv() {
        let _ = msg.id; // Simulated processing hook

        let latency = msg.created_at.elapsed().as_nanos() as u64;
        metrics.record_latency(latency);
        metrics.processed.fetch_add(1, Ordering::Relaxed);
    }
}
