#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <thread>
#include <vector>

using Clock = std::chrono::steady_clock;
using ns = std::chrono::nanoseconds;

static inline uint64_t now_ns() {
    return std::chrono::duration_cast<ns>(Clock::now().time_since_epoch()).count();
}

struct Message {
    uint64_t id;
    uint64_t created_ns;
    char payload[64];
};

template <typename T, size_t Size>
class SPSCQueue {
    static_assert((Size & (Size - 1)) == 0, "Size must be power of two");

public:
    bool push(const T& item) {
        const size_t head = head_.load(std::memory_order_relaxed);
        const size_t next = (head + 1) & (Size - 1);

        if (next == tail_.load(std::memory_order_acquire)) {
            return false; // full
        }

        buffer_[head] = item;
        head_.store(next, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        const size_t tail = tail_.load(std::memory_order_relaxed);

        if (tail == head_.load(std::memory_order_acquire)) {
            return false; // empty
        }

        item = buffer_[tail];
        tail_.store((tail + 1) & (Size - 1), std::memory_order_release);
        return true;
    }

private:
    alignas(64) T buffer_[Size];
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
};

struct Metrics {
    std::atomic<uint64_t> processed{0};
    std::atomic<uint64_t> total_latency_ns{0};
    std::atomic<uint64_t> max_latency_ns{0};

    void record(uint64_t latency_ns) {
        processed.fetch_add(1, std::memory_order_relaxed);
        total_latency_ns.fetch_add(latency_ns, std::memory_order_relaxed);

        uint64_t prev = max_latency_ns.load(std::memory_order_relaxed);
        while (latency_ns > prev &&
               !max_latency_ns.compare_exchange_weak(
                   prev, latency_ns, std::memory_order_relaxed)) {
        }
    }
};

int main() {
    constexpr size_t QUEUE_SIZE = 1 << 20; // 1,048,576
    SPSCQueue<Message, QUEUE_SIZE> queue;

    std::atomic<bool> running{true};
    Metrics metrics;

    // Producer thread
    std::thread producer([&]() {
        uint64_t id = 0;
        Message msg{};

        while (running.load(std::memory_order_relaxed)) {
            msg.id = id++;
            msg.created_ns = now_ns();
            std::memcpy(msg.payload, "test-message", 13);

            while (!queue.push(msg)) {
                // busy spin when full
            }
        }
    });

    // Router/consumer thread
    std::thread consumer([&]() {
        Message msg;
        while (running.load(std::memory_order_relaxed)) {
            if (queue.pop(msg)) {
                uint64_t latency = now_ns() - msg.created_ns;

                // Simulate route decision / forwarding
                // In a real system, you'd inspect the message and send to destination
                metrics.record(latency);
            }
        }

        // Drain remaining messages before exit
        while (queue.pop(msg)) {
            uint64_t latency = now_ns() - msg.created_ns;
            metrics.record(latency);
        }
    });

    // Metrics thread
    std::thread reporter([&]() {
        uint64_t last_processed = 0;
        auto last_time = Clock::now();

        for (int i = 0; i < 10; ++i) {
            std::this_thread::sleep_for(std::chrono::seconds(1));

            uint64_t current_processed = metrics.processed.load(std::memory_order_relaxed);
            uint64_t total_latency = metrics.total_latency_ns.load(std::memory_order_relaxed);
            uint64_t max_latency = metrics.max_latency_ns.load(std::memory_order_relaxed);

            auto now = Clock::now();
            double elapsed = std::chrono::duration<double>(now - last_time).count();

            uint64_t delta = current_processed - last_processed;
            double throughput = delta / elapsed;
            double avg_latency = current_processed == 0 ? 0.0
                : static_cast<double>(total_latency) / current_processed;

            std::cout << "processed=" << current_processed
                      << " throughput=" << std::fixed << std::setprecision(2)
                      << throughput << " msg/s"
                      << " avg_latency=" << avg_latency << " ns"
                      << " max_latency=" << max_latency << " ns"
                      << std::endl;

            last_processed = current_processed;
            last_time = now;
        }

        running.store(false, std::memory_order_relaxed);
    });

    reporter.join();
    producer.join();
    consumer.join();

    return 0;
}
