use crossbeam::channel::{bounded, Receiver, Sender};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const PRODUCERS: usize = 4;
const ROUTES: usize = 8;
const CHANNEL_CAPACITY: usize = 1024 * 256;
const RUN_SECONDS: u64 = 10;

#[derive(Clone, Copy)]
struct Message {
    id: u64,
    route_key: u64,
    created_at: Instant,
}

struct Metrics {
    routed: AtomicU64,
    dropped: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency_ns: u64) {
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }
}

fn producer_thread(
    producer_id: usize,
    tx: Sender<Message>,
    running: Arc<AtomicBool>,
    dropped: Arc<AtomicU64>,
) {
    let mut local_id = producer_id as u64 * 1_000_000_000;

    while running.load(Ordering::Relaxed) {
        let msg = Message {
            id: local_id,
            route_key: local_id % ROUTES as u64,
            created_at: Instant::now(),
        };

        if tx.try_send(msg).is_err() {
            dropped.fetch_add(1, Ordering::Relaxed);
        }

        local_id += 1;
    }
}

fn router_thread(
    rx: Receiver<Message>,
    route_txs: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(1)) {
            Ok(msg) => {
                let route_index = (msg.route_key as usize) % route_txs.len();

                if route_txs[route_index].try_send(msg).is_err() {
                    metrics.dropped.fetch_add(1, Ordering::Relaxed);
                } else {
                    metrics.routed.fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(_) => {}
        }
    }
}

fn consumer_thread(rx: Receiver<Message>, metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        match rx.recv_timeout(Duration::from_millis(1)) {
            Ok(msg) => {
                let _id_use = msg.id;
                let latency = msg.created_at.elapsed().as_nanos() as u64;
                metrics.record_latency(latency);
            }
            Err(_) => {}
        }
    }
}

fn reporter_thread(metrics: Arc<Metrics>, producer_drops: Arc<AtomicU64>, running: Arc<AtomicBool>) {
    let mut last_routed = 0u64;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped_router = metrics.dropped.load(Ordering::Relaxed);
        let dropped_producer = producer_drops.load(Ordering::Relaxed);
        let total_latency_ns = metrics.total_latency_ns.load(Ordering::Relaxed);
        let max_latency_ns = metrics.max_latency_ns.load(Ordering::Relaxed);

        let delta = routed - last_routed;
        last_routed = routed;

        let avg_latency_ns = if routed > 0 {
            total_latency_ns / routed
        } else {
            0
        };

        println!(
            "throughput={} msg/s total_routed={} producer_dropped={} router_dropped={} avg_latency={} ns max_latency={} ns",
            delta, routed, dropped_producer, dropped_router, avg_latency_ns, max_latency_ns
        );
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let metrics = Arc::new(Metrics::new());
    let producer_drops = Arc::new(AtomicU64::new(0));

    let (ingress_tx, ingress_rx) = bounded::<Message>(CHANNEL_CAPACITY);

    let mut route_txs = Vec::with_capacity(ROUTES);
    let mut route_rxs = Vec::with_capacity(ROUTES);

    for _ in 0..ROUTES {
        let (tx, rx) = bounded::<Message>(CHANNEL_CAPACITY / ROUTES);
        route_txs.push(tx);
        route_rxs.push(rx);
    }

    let mut handles = Vec::new();

    for i in 0..PRODUCERS {
        let tx = ingress_tx.clone();
        let run = running.clone();
        let drops = producer_drops.clone();
        handles.push(thread::spawn(move || producer_thread(i, tx, run, drops)));
    }

    {
        let rx = ingress_rx;
        let txs = route_txs.clone();
        let m = metrics.clone();
        let run = running.clone();
        handles.push(thread::spawn(move || router_thread(rx, txs, m, run)));
    }

    for rx in route_rxs {
        let m = metrics.clone();
        let run = running.clone();
        handles.push(thread::spawn(move || consumer_thread(rx, m, run)));
    }

    {
        let m = metrics.clone();
        let drops = producer_drops.clone();
        let run = running.clone();
        handles.push(thread::spawn(move || reporter_thread(m, drops, run)));
    }

    thread::sleep(Duration::from_secs(RUN_SECONDS));
    running.store(false, Ordering::Relaxed);

    for h in handles {
        let _ = h.join();
    }

    let routed = metrics.routed.load(Ordering::Relaxed);
    let dropped_router = metrics.dropped.load(Ordering::Relaxed);
    let dropped_producer = producer_drops.load(Ordering::Relaxed);
    let total_latency_ns = metrics.total_latency_ns.load(Ordering::Relaxed);
    let max_latency_ns = metrics.max_latency_ns.load(Ordering::Relaxed);

    let avg_latency_ns = if routed > 0 {
        total_latency_ns / routed
    } else {
        0
    };

    println!("\nFinal report:");
    println!("routed={}", routed);
    println!("producer_dropped={}", dropped_producer);
    println!("router_dropped={}", dropped_router);
    println!("avg_latency_ns={}", avg_latency_ns);
    println!("max_latency_ns={}", max_latency_ns);
}
