```rust
use ahash::AHasher;
use std::hash::{Hash, Hasher};
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;

const WORKERS: usize = 4;
const CHANNEL_CAPACITY: usize = 100_000;

#[derive(Debug)]
struct Message {
    key: String,
    payload: String,
    ingress_ns: u128,
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
    total_latency_us: AtomicU64,
    max_latency_us: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            processed: AtomicU64::new(0),
            total_latency_us: AtomicU64::new(0),
            max_latency_us: AtomicU64::new(0),
        }
    }

    fn record_latency(&self, latency_us: u64) {
        self.total_latency_us.fetch_add(latency_us, Ordering::Relaxed);

        let mut current = self.max_latency_us.load(Ordering::Relaxed);
        while latency_us > current {
            match self.max_latency_us.compare_exchange_weak(
                current,
                latency_us,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }
}

fn now_ns() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

fn hash_key(key: &str) -> usize {
    let mut hasher = AHasher::default();
    key.hash(&mut hasher);
    hasher.finish() as usize
}

async fn handle_connection(
    socket: TcpStream,
    worker_senders: Arc<Vec<mpsc::Sender<Message>>>,
    metrics: Arc<Metrics>,
) {
    let (reader, mut writer) = socket.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::with_capacity(256);

    loop {
        line.clear();
        let bytes_read = match reader.read_line(&mut line).await {
            Ok(0) => break,
            Ok(n) => n,
            Err(_) => break,
        };

        if bytes_read == 0 {
            break;
        }

        metrics.received.fetch_add(1, Ordering::Relaxed);

        let trimmed = line.trim_end();
        if trimmed.is_empty() {
            continue;
        }

        // Message format: key|payload
        let mut parts = trimmed.splitn(2, '|');
        let key = parts.next().unwrap_or("").to_string();
        let payload = parts.next().unwrap_or("").to_string();

        let msg = Message {
            key: key.clone(),
            payload,
            ingress_ns: now_ns(),
        };

        let idx = hash_key(&key) % worker_senders.len();

        match worker_senders[idx].try_send(msg) {
            Ok(_) => {
                metrics.routed.fetch_add(1, Ordering::Relaxed);
                // tiny ack; remove in benchmark mode if needed
                let _ = writer.write_all(b"OK\n").await;
            }
            Err(_) => {
                metrics.dropped.fetch_add(1, Ordering::Relaxed);
                let _ = writer.write_all(b"DROP\n").await;
            }
        }
    }
}

async fn worker_loop(mut rx: mpsc::Receiver<Message>, metrics: Arc<Metrics>, worker_id: usize) {
    while let Some(msg) = rx.recv().await {
        // Simulated routing/processing
        let _ = msg.payload.len() + worker_id;

        let latency_us = ((now_ns() - msg.ingress_ns) / 1_000) as u64;
        metrics.processed.fetch_add(1, Ordering::Relaxed);
        metrics.record_latency(latency_us);
    }
}

async fn stats_loop(metrics: Arc<Metrics>) {
    let mut last_received = 0;
    let mut last_processed = 0;

    loop {
        tokio::time::sleep(Duration::from_secs(1)).await;

        let received = metrics.received.load(Ordering::Relaxed);
        let routed = metrics.routed.load(Ordering::Relaxed);
        let dropped = metrics.dropped.load(Ordering::Relaxed);
        let processed = metrics.processed.load(Ordering::Relaxed);
        let total_latency = metrics.total_latency_us.load(Ordering::Relaxed);
        let max_latency = metrics.max_latency_us.load(Ordering::Relaxed);

        let rps = received.saturating_sub(last_received);
        let pps = processed.saturating_sub(last_processed);

        let avg_latency = if processed > 0 {
            total_latency / processed
        } else {
            0
        };

        println!(
            "recv/s={} proc/s={} total_recv={} routed={} dropped={} processed={} avg_latency_us={} max_latency_us={}",
            rps,
            pps,
            received,
            routed,
            dropped,
            processed,
            avg_latency,
            max_latency
        );

        last_received = received;
        last_processed = processed;
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let listener = TcpListener::bind("0.0.0.0:7000").await?;
    println!("listening on 0.0.0.0:7000");

    let metrics = Arc::new(Metrics::new());

    let mut senders = Vec::with_capacity(WORKERS);
    for worker_id in 0..WORKERS {
        let (tx, rx) = mpsc::channel(CHANNEL_CAPACITY);
        senders.push(tx);

        let metrics_clone = metrics.clone();
        tokio::spawn(worker_loop(rx, metrics_clone, worker_id));
    }

    let worker_senders = Arc::new(senders);

    {
        let metrics_clone = metrics.clone();
        tokio::spawn(stats_loop(metrics_clone));
    }

    loop {
        let (socket, addr) = listener.accept().await?;
        println!("accepted connection from {}", addr);

        let senders_clone = worker_senders.clone();
        let metrics_clone = metrics.clone();

        tokio::spawn(async move {
            handle_connection(socket, senders_clone, metrics_clone).await;
        });
    }
}
```

