use std::net::UdpSocket;
use std::io;

fn main() -> io::Result<()> {
    let listen = UdpSocket::bind("127.0.0.1:9000")?;
    let upstream = UdpSocket::bind("127.0.0.1:0")?;
    upstream.connect("127.0.0.1:9001")?;

    let mut buf = [0u8; 2048];

    loop {
        let (n, src) = listen.recv_from(&mut buf)?;

        if n == 0 {
            continue;
        }

        // Example safe filter: only relay ASCII payloads under 1 KB
        if n <= 1024 && buf[..n].iter().all(|b| b.is_ascii()) {
            upstream.send(&buf[..n])?;

            let resp_len = upstream.recv(&mut buf)?;
            listen.send_to(&buf[..resp_len], src)?;
        }
    }
}
