use anyhow::{Context, Result};
use clap::Parser;
use etherparse::{NetSlice, SlicedPacket, TransportSlice};
use pcap_file::pcap::{PcapHeader, PcapPacket, PcapReader, PcapWriter};
use serde::{Deserialize, Serialize};
use std::fs::File;
use std::io::{BufReader, BufWriter};
use std::net::Ipv4Addr;
use std::path::PathBuf;
use std::time::Instant;

#[derive(Parser, Debug)]
#[command(name = "ultra_filter")]
struct Args {
    /// Input PCAP file
    #[arg(short, long)]
    input: PathBuf,

    /// Optional output PCAP for allowed packets
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Optional JSON policy file
    #[arg(short, long)]
    policy: Option<PathBuf>,

    /// Print per-packet decision
    #[arg(long, default_value_t = false)]
    verbose: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Policy {
    default_action: Action,
    rules: Vec<Rule>,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Action {
    Allow,
    Deny,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Rule {
    action: Action,
    src_ipv4: Option<String>,
    dst_ipv4: Option<String>,
    protocol: Option<String>, // "tcp" | "udp" | "icmp"
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

#[derive(Debug, Default)]
struct Stats {
    total: u64,
    parsed: u64,
    allowed: u64,
    denied: u64,
    malformed: u64,
}

#[derive(Debug)]
struct PacketMeta {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    protocol: Option<Protocol>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Protocol {
    Tcp,
    Udp,
    Icmp,
    Other,
}

fn main() -> Result<()> {
    let args = Args::parse();

    let policy = load_policy(args.policy.as_ref())?;
    let input = File::open(&args.input)
        .with_context(|| format!("failed to open input {:?}", args.input))?;
    let mut reader = PcapReader::new(BufReader::new(input))?;

    let mut writer = if let Some(out) = &args.output {
        let file = File::create(out).with_context(|| format!("failed to create output {:?}", out))?;
        Some(PcapWriter::with_header(
            BufWriter::new(file),
            PcapHeader::default(),
        )?)
    } else {
        None
    };

    let start = Instant::now();
    let mut stats = Stats::default();

    while let Some(pkt) = reader.next_packet() {
        let pkt = pkt?;
        stats.total += 1;

        match extract_meta(pkt.data.as_ref()) {
            Ok(meta) => {
                stats.parsed += 1;
                let decision = evaluate(&policy, &meta);

                if args.verbose {
                    println!(
                        "#{:06} {:?} src={:?}:{:?} dst={:?}:{:?}",
                        stats.total,
                        decision,
                        meta.src_ip,
                        meta.src_port,
                        meta.dst_ip,
                        meta.dst_port
                    );
                }

                match decision {
                    Action::Allow => {
                        stats.allowed += 1;
                        if let Some(w) = writer.as_mut() {
                            let out_pkt = PcapPacket::new(pkt.timestamp, pkt.orig_len, pkt.data.into_owned());
                            w.write_packet(&out_pkt)?;
                        }
                    }
                    Action::Deny => {
                        stats.denied += 1;
                    }
                }
            }
            Err(_) => {
                stats.malformed += 1;
            }
        }
    }

    let elapsed = start.elapsed();
    println!("--- summary ---");
    println!("total      : {}", stats.total);
    println!("parsed     : {}", stats.parsed);
    println!("allowed    : {}", stats.allowed);
    println!("denied     : {}", stats.denied);
    println!("malformed  : {}", stats.malformed);
    println!("elapsed_ms : {}", elapsed.as_millis());

    Ok(())
}

fn load_policy(path: Option<&PathBuf>) -> Result<Policy> {
    if let Some(path) = path {
        let data = std::fs::read_to_string(path)
            .with_context(|| format!("failed to read policy {:?}", path))?;
        let policy: Policy = serde_json::from_str(&data)?;
        Ok(policy)
    } else {
        Ok(Policy {
            default_action: Action::Deny,
            rules: vec![
                Rule {
                    action: Action::Allow,
                    src_ipv4: None,
                    dst_ipv4: None,
                    protocol: Some("udp".into()),
                    src_port: None,
                    dst_port: Some(53),
                },
                Rule {
                    action: Action::Allow,
                    src_ipv4: None,
                    dst_ipv4: None,
                    protocol: Some("tcp".into()),
                    src_port: None,
                    dst_port: Some(443),
                },
            ],
        })
    }
}

fn extract_meta(data: &[u8]) -> Result<PacketMeta> {
    let sliced = SlicedPacket::from_ethernet(data)?;

    let mut meta = PacketMeta {
        src_ip: None,
        dst_ip: None,
        protocol: None,
        src_port: None,
        dst_port: None,
    };

    if let Some(net) = sliced.net {
        if let NetSlice::Ipv4(ipv4) = net {
            meta.src_ip = Some(Ipv4Addr::from(ipv4.header().source()));
            meta.dst_ip = Some(Ipv4Addr::from(ipv4.header().destination()));
        }
    }

    if let Some(transport) = sliced.transport {
        match transport {
            TransportSlice::Tcp(tcp) => {
                meta.protocol = Some(Protocol::Tcp);
                meta.src_port = Some(tcp.source_port());
                meta.dst_port = Some(tcp.destination_port());
            }
            TransportSlice::Udp(udp) => {
                meta.protocol = Some(Protocol::Udp);
                meta.src_port = Some(udp.source_port());
                meta.dst_port = Some(udp.destination_port());
            }
            TransportSlice::Icmpv4(_) => {
                meta.protocol = Some(Protocol::Icmp);
            }
            _ => {
                meta.protocol = Some(Protocol::Other);
            }
        }
    }

    Ok(meta)
}

fn evaluate(policy: &Policy, meta: &PacketMeta) -> Action {
    for rule in &policy.rules {
        if rule_matches(rule, meta) {
            return rule.action;
        }
    }
    policy.default_action
}

fn rule_matches(rule: &Rule, meta: &PacketMeta) -> bool {
    if let Some(ref src) = rule.src_ipv4 {
        match meta.src_ip {
            Some(ip) if ip.to_string() == *src => {}
            _ => return false,
        }
    }

    if let Some(ref dst) = rule.dst_ipv4 {
        match meta.dst_ip {
            Some(ip) if ip.to_string() == *dst => {}
            _ => return false,
        }
    }

    if let Some(ref proto) = rule.protocol {
        let p = match meta.protocol {
            Some(Protocol::Tcp) => "tcp",
            Some(Protocol::Udp) => "udp",
            Some(Protocol::Icmp) => "icmp",
            _ => "other",
        };
        if p != proto {
            return false;
        }
    }

    if let Some(port) = rule.src_port {
        if meta.src_port != Some(port) {
            return false;
        }
    }

    if let Some(port) = rule.dst_port {
        if meta.dst_port != Some(port) {
            return false;
        }
    }

    true
}
```

