# 1) XDP packet filter: `xdp_filter_kern.c`

```c
// xdp_filter_kern.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>

char LICENSE[] SEC("license") = "GPL";

struct filter_rule {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 dst_port;
    __u8  protocol; // IPPROTO_TCP or IPPROTO_UDP
    __u8  action;   // 0 = pass, 1 = drop
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct filter_rule);
} rules_map SEC(".maps");

static __always_inline int parse_ipv4(void *data, void *data_end, struct iphdr **iphdr_out) {
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return -1;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return -1;

    if (iph->ihl < 5)
        return -1;

    if ((void *)iph + iph->ihl * 4 > data_end)
        return -1;

    *iphdr_out = iph;
    return 0;
}

SEC("xdp")
int xdp_packet_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct iphdr *iph;
    if (parse_ipv4(data, data_end, &iph) < 0) {
        return XDP_PASS;
    }

    __u32 key = 0;
    struct filter_rule *rule = bpf_map_lookup_elem(&rules_map, &key);
    if (!rule) {
        return XDP_PASS;
    }

    if (rule->protocol && iph->protocol != rule->protocol) {
        return XDP_PASS;
    }

    if (rule->src_ip && iph->saddr != rule->src_ip) {
        return XDP_PASS;
    }

    if (rule->dst_ip && iph->daddr != rule->dst_ip) {
        return XDP_PASS;
    }

    if (rule->dst_port) {
        if (iph->protocol == IPPROTO_UDP) {
            struct udphdr *udph = (void *)iph + iph->ihl * 4;
            if ((void *)(udph + 1) > data_end)
                return XDP_DROP;
            if (udph->dest != bpf_htons(rule->dst_port))
                return XDP_PASS;
        } else if (iph->protocol == IPPROTO_TCP) {
            struct tcphdr *tcph = (void *)iph + iph->ihl * 4;
            if ((void *)(tcph + 1) > data_end)
                return XDP_DROP;
            if (tcph->dest != bpf_htons(rule->dst_port))
                return XDP_PASS;
        } else {
            return XDP_PASS;
        }
    }

    if (rule->action == 1)
        return XDP_DROP;

    return XDP_PASS;
}
```

