# 2) User-space loader for XDP program: `xdp_loader.c`

```c
// xdp_loader.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>
#include <linux/if_link.h>
#include <unistd.h>

struct filter_rule {
    __u32 src_ip;
    __u32 dst_ip;
    __u16 dst_port;
    __u8  protocol;
    __u8  action;
};

static int ifindex_from_name(const char *ifname) {
    int idx = if_nametoindex(ifname);
    if (!idx) {
        fprintf(stderr, "if_nametoindex(%s) failed\n", ifname);
        exit(1);
    }
    return idx;
}

int main(int argc, char **argv) {
    if (argc < 7) {
        fprintf(stderr,
            "Usage: %s <ifname> <src_ip|0> <dst_ip|0> <dst_port|0> <proto:tcp|udp|0> <action:pass|drop>\n",
            argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    const char *src_ip_str = argv[2];
    const char *dst_ip_str = argv[3];
    const char *dst_port_str = argv[4];
    const char *proto_str = argv[5];
    const char *action_str = argv[6];

    struct bpf_object *obj = NULL;
    int prog_fd, map_fd, ifindex, err;
    struct bpf_program *prog;
    struct filter_rule rule = {0};
    __u32 key = 0;

    obj = bpf_object__open_file("xdp_filter_kern.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object: %d\n", err);
        return 1;
    }

    prog = bpf_object__find_program_by_name(obj, "xdp_packet_filter");
    if (!prog) {
        fprintf(stderr, "Failed to find BPF program\n");
        return 1;
    }

    prog_fd = bpf_program__fd(prog);
    if (prog_fd < 0) {
        fprintf(stderr, "Failed to get program fd\n");
        return 1;
    }

    map_fd = bpf_object__find_map_fd_by_name(obj, "rules_map");
    if (map_fd < 0) {
        fprintf(stderr, "Failed to get rules_map fd\n");
        return 1;
    }

    if (strcmp(src_ip_str, "0") != 0) {
        if (inet_pton(AF_INET, src_ip_str, &rule.src_ip) != 1) {
            fprintf(stderr, "Invalid src IP\n");
            return 1;
        }
    }

    if (strcmp(dst_ip_str, "0") != 0) {
        if (inet_pton(AF_INET, dst_ip_str, &rule.dst_ip) != 1) {
            fprintf(stderr, "Invalid dst IP\n");
            return 1;
        }
    }

    rule.dst_port = (uint16_t)atoi(dst_port_str);

    if (strcmp(proto_str, "tcp") == 0)
        rule.protocol = IPPROTO_TCP;
    else if (strcmp(proto_str, "udp") == 0)
        rule.protocol = IPPROTO_UDP;
    else
        rule.protocol = 0;

    if (strcmp(action_str, "drop") == 0)
        rule.action = 1;
    else
        rule.action = 0;

    err = bpf_map_update_elem(map_fd, &key, &rule, BPF_ANY);
    if (err) {
        fprintf(stderr, "Failed to update map: %s\n", strerror(errno));
        return 1;
    }

    ifindex = ifindex_from_name(ifname);
    err = bpf_set_link_xdp_fd(ifindex, prog_fd, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to attach XDP to %s: %d\n", ifname, err);
        return 1;
    }

    printf("XDP filter attached to %s\n", ifname);
    printf("Press Ctrl+C to exit; detach manually if needed.\n");

    while (1) {
        sleep(1000);
    }

    bpf_set_link_xdp_fd(ifindex, -1, 0);
    bpf_object__close(obj);
    return 0;
}
