# 3) Simple packet forwarder: `forwarder.c`

```c
// forwarder.c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <netinet/ip.h>

static volatile int running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int get_ifindex(const char *ifname) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, IFNAMSIZ, "%s", ifname);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        close(fd);
        return -1;
    }

    close(fd);
    return ifr.ifr_ifindex;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];

    int in_ifindex = get_ifindex(in_if);
    int out_ifindex = get_ifindex(out_if);

    if (in_ifindex < 0 || out_ifindex < 0) {
        fprintf(stderr, "Failed to get interface indices\n");
        return 1;
    }

    int rx_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_IP));
    if (rx_fd < 0) {
        perror("socket rx");
        return 1;
    }

    int tx_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx_fd < 0) {
        perror("socket tx");
        close(rx_fd);
        return 1;
    }

    struct sockaddr_ll rx_addr = {0};
    rx_addr.sll_family = AF_PACKET;
    rx_addr.sll_protocol = htons(ETH_P_IP);
    rx_addr.sll_ifindex = in_ifindex;

    if (bind(rx_fd, (struct sockaddr *)&rx_addr, sizeof(rx_addr)) < 0) {
        perror("bind rx");
        close(rx_fd);
        close(tx_fd);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned char buf[2048];

    while (running) {
        ssize_t n = recvfrom(rx_fd, buf, sizeof(buf), 0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        struct sockaddr_ll tx_addr = {0};
        tx_addr.sll_family = AF_PACKET;
        tx_addr.sll_ifindex = out_ifindex;
        tx_addr.sll_halen = ETH_ALEN;

        // NOTE:
        // This initial version assumes L2 frame can be emitted as-is.
        // In real forwarding, you would rewrite Ethernet headers
        // based on routing/ARP/neighbor resolution.

        ssize_t sent = sendto(tx_fd, buf, n, 0,
                              (struct sockaddr *)&tx_addr, sizeof(tx_addr));
        if (sent < 0) {
            perror("sendto");
        }
    }

    close(rx_fd);
    close(tx_fd);
    return 0;
}
```

