## Safe initial architecture
Build these components:

1. **RX input adapter**
   - reads from a pcap file, AF_PACKET mirror, or a synthetic generator
   - not directly attached to a forwarding path

2. **Parser**
   - Ethernet
   - IPv4/IPv6
   - UDP/TCP basic header extraction

3. **Filter engine**
   - stateless allow/deny rules
   - counters
   - fast-path match tables

4. **Decision engine**
   - `Allow`
   - `Drop`
   - `Mirror`
   - `Sample`

5. **TX/output adapter**
   - writes accepted packets to:
     - a ring buffer
     - a log
     - a pcap output
     - an analysis callback
   - not raw reinjection to network by default

6. **Metrics**
   - packets/s
   - drops
   - parse failures
   - rule hits
   - latency histograms

## Safe Rust starter implementation
This example:
- parses Ethernet + IPv4 + UDP/TCP
- applies simple packet filters
- makes forwarding decisions
- sends “allowed” packets to a user-space sink callback rather than onto the wire

```rust
use std::net::Ipv4Addr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Instant;

#[derive(Debug, Clone, Copy)]
enum L4Proto {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
struct PacketMeta {
    ethertype: u16,
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    proto: Option<L4Proto>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    len: usize,
}

#[derive(Debug, Clone, Copy)]
enum Action {
    Allow,
    Drop,
    Mirror,
    Sample,
}

#[derive(Debug, Clone)]
struct Rule {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    proto: Option<L4Proto>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    action: Action,
}

impl Rule {
    fn matches(&self, p: &PacketMeta) -> bool {
        if let Some(ip) = self.src_ip {
            if p.src_ip != Some(ip) {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if p.dst_ip != Some(ip) {
                return false;
            }
        }
        if let Some(proto) = self.proto {
            match (proto, p.proto) {
                (L4Proto::Tcp, Some(L4Proto::Tcp)) => {}
                (L4Proto::Udp, Some(L4Proto::Udp)) => {}
                (L4Proto::Other(a), Some(L4Proto::Other(b))) if a == b => {}
                _ => return false,
            }
        }
        if let Some(port) = self.src_port {
            if p.src_port != Some(port) {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if p.dst_port != Some(port) {
                return false;
            }
        }
        true
    }
}

struct Metrics {
    seen: AtomicU64,
    allowed: AtomicU64,
    dropped: AtomicU64,
    mirrored: AtomicU64,
    sampled: AtomicU64,
    parse_fail: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            seen: AtomicU64::new(0),
            allowed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            mirrored: AtomicU64::new(0),
            sampled: AtomicU64::new(0),
            parse_fail: AtomicU64::new(0),
        }
    }
}

trait OutputSink: Send + Sync {
    fn handle_allowed(&self, packet: &[u8], meta: PacketMeta);
    fn handle_mirror(&self, packet: &[u8], meta: PacketMeta);
    fn handle_sample(&self, packet: &[u8], meta: PacketMeta);
}

struct NullSink;

impl OutputSink for NullSink {
    fn handle_allowed(&self, _packet: &[u8], _meta: PacketMeta) {}
    fn handle_mirror(&self, _packet: &[u8], _meta: PacketMeta) {}
    fn handle_sample(&self, _packet: &[u8], _meta: PacketMeta) {}
}

struct Engine<S: OutputSink> {
    rules: Vec<Rule>,
    default_action: Action,
    sink: Arc<S>,
    metrics: Arc<Metrics>,
}

impl<S: OutputSink> Engine<S> {
    fn new(rules: Vec<Rule>, default_action: Action, sink: Arc<S>, metrics: Arc<Metrics>) -> Self {
        Self {
            rules,
            default_action,
            sink,
            metrics,
        }
    }

    fn process(&self, packet: &[u8]) {
        self.metrics.seen.fetch_add(1, Ordering::Relaxed);

        let meta = match parse_packet(packet) {
            Some(m) => m,
            None => {
                self.metrics.parse_fail.fetch_add(1, Ordering::Relaxed);
                return;
            }
        };

        let action = self.rules
            .iter()
            .find(|r| r.matches(&meta))
            .map(|r| r.action)
            .unwrap_or(self.default_action);

        match action {
            Action::Allow => {
                self.metrics.allowed.fetch_add(1, Ordering::Relaxed);
                self.sink.handle_allowed(packet, meta);
            }
            Action::Drop => {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
            Action::Mirror => {
                self.metrics.mirrored.fetch_add(1, Ordering::Relaxed);
                self.sink.handle_mirror(packet, meta);
            }
            Action::Sample => {
                self.metrics.sampled.fetch_add(1, Ordering::Relaxed);
                self.sink.handle_sample(packet, meta);
            }
        }
    }
}

fn parse_packet(packet: &[u8]) -> Option<PacketMeta> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    let mut meta = PacketMeta {
        ethertype,
        src_ip: None,
        dst_ip: None,
        proto: None,
        src_port: None,
        dst_port: None,
        len: packet.len(),
    };

    if ethertype != 0x0800 {
        return Some(meta);
    }

    if packet.len() < 34 {
        return None;
    }

    let ihl = (packet[14] & 0x0f) as usize * 4;
    if packet.len() < 14 + ihl || ihl < 20 {
        return None;
    }

    let proto = packet[23];
    meta.src_ip = Some(Ipv4Addr::new(packet[26], packet[27], packet[28], packet[29]));
    meta.dst_ip = Some(Ipv4Addr::new(packet[30], packet[31], packet[32], packet[33]));
    meta.proto = Some(match proto {
        6 => L4Proto::Tcp,
        17 => L4Proto::Udp,
        other => L4Proto::Other(other),
    });

    let l4 = 14 + ihl;
    match proto {
        6 | 17 => {
            if packet.len() < l4 + 4 {
                return None;
            }
            meta.src_port = Some(u16::from_be_bytes([packet[l4], packet[l4 + 1]]));
            meta.dst_port = Some(u16::from_be_bytes([packet[l4 + 2], packet[l4 + 3]]));
        }
        _ => {}
    }

    Some(meta)
}

struct CountingSink {
    forwarded_bytes: AtomicU64,
}

impl CountingSink {
    fn new() -> Self {
        Self {
            forwarded_bytes: AtomicU64::new(0),
        }
    }
}

impl OutputSink for CountingSink {
    fn handle_allowed(&self, packet: &[u8], _meta: PacketMeta) {
        self.forwarded_bytes
            .fetch_add(packet.len() as u64, Ordering::Relaxed);
    }

    fn handle_mirror(&self, packet: &[u8], _meta: PacketMeta) {
        self.forwarded_bytes
            .fetch_add(packet.len() as u64, Ordering::Relaxed);
    }

    fn handle_sample(&self, packet: &[u8], _meta: PacketMeta) {
        self.forwarded_bytes
            .fetch_add(packet.len() as u64, Ordering::Relaxed);
    }
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let sink = Arc::new(CountingSink::new());

    let rules = vec![
        Rule {
            src_ip: None,
            dst_ip: None,
            proto: Some(L4Proto::Udp),
            src_port: None,
            dst_port: Some(53),
            action: Action::Mirror,
        },
        Rule {
            src_ip: None,
            dst_ip: Some("10.0.0.10".parse().unwrap()),
            proto: Some(L4Proto::Tcp),
            src_port: None,
            dst_port: Some(22),
            action: Action::Drop,
        },
    ];

    let engine = Engine::new(rules, Action::Allow, sink.clone(), metrics.clone());

    let synthetic_packet = build_test_ipv4_udp_packet(
        [192, 168, 1, 10],
        [8, 8, 8, 8],
        50000,
        53,
        b"hello",
    );

    let start = Instant::now();
    for _ in 0..1_000_000 {
        engine.process(&synthetic_packet);
    }
    let elapsed = start.elapsed();

    println!("seen={}", metrics.seen.load(Ordering::Relaxed));
    println!("allowed={}", metrics.allowed.load(Ordering::Relaxed));
    println!("dropped={}", metrics.dropped.load(Ordering::Relaxed));
    println!("mirrored={}", metrics.mirrored.load(Ordering::Relaxed));
    println!("sampled={}", metrics.sampled.load(Ordering::Relaxed));
    println!("parse_fail={}", metrics.parse_fail.load(Ordering::Relaxed));
    println!("elapsed_ms={}", elapsed.as_millis());
    println!(
        "forwarded_bytes={}",
        sink.forwarded_bytes.load(Ordering::Relaxed)
    );
}

fn build_test_ipv4_udp_packet(
    src_ip: [u8; 4],
    dst_ip: [u8; 4],
    src_port: u16,
    dst_port: u16,
    payload: &[u8],
) -> Vec<u8> {
    let eth_len = 14;
    let ip_len = 20;
    let udp_len = 8;
    let total_len = eth_len + ip_len + udp_len + payload.len();

    let mut pkt = vec![0u8; total_len];

    pkt[12] = 0x08;
    pkt[13] = 0x00;

    pkt[14] = 0x45;
    pkt[15] = 0x00;
    let ip_total = (ip_len + udp_len + payload.len()) as u16;
    pkt[16..18].copy_from_slice(&ip_total.to_be_bytes());
    pkt[22] = 64;
    pkt[23] = 17;
    pkt[26..30].copy_from_slice(&src_ip);
    pkt[30..34].copy_from_slice(&dst_ip);

    let l4 = 14 + ip_len;
    pkt[l4..l4 + 2].copy_from_slice(&src_port.to_be_bytes());
    pkt[l4 + 2..l4 + 4].copy_from_slice(&dst_port.to_be_bytes());
    let udp_total = (udp_len + payload.len()) as u16;
    pkt[l4 + 4..l4 + 6].copy_from_slice(&udp_total.to_be_bytes());

    let payload_off = l4 + udp_len;
    pkt[payload_off..payload_off + payload.len()].copy_from_slice(payload);

    pkt
}
