## 2. User-space packet processor: `xdp_forward_user.c`

```c
// xdp_forward_user.c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_link.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/if_xdp.h>
#include <net/if.h>
#include <netpacket/packet.h>
#include <poll.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>
#include <bpf/bpf.h>
#include <bpf/libbpf.h>
#include <xdp/xsk.h>

#define NUM_FRAMES 4096
#define FRAME_SIZE XSK_UMEM__DEFAULT_FRAME_SIZE
#define UMEM_SIZE (NUM_FRAMES * FRAME_SIZE)
#define BATCH_SIZE 64

struct xsk_umem_info {
    struct xsk_umem *umem;
    void *buffer;
    struct xsk_ring_prod fq;
    struct xsk_ring_cons cq;
};

struct xsk_socket_info {
    struct xsk_socket *xsk;
    struct xsk_ring_cons rx;
    struct xsk_ring_prod tx;
    struct xsk_umem_info *umem;
    uint32_t outstanding_tx;
    int ifindex;
    int raw_fd;
};

static int raw_socket_open(const char *ifname)
{
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket(AF_PACKET)");
        return -1;
    }

    struct sockaddr_ll sll = {
        .sll_family = AF_PACKET,
        .sll_protocol = htons(ETH_P_ALL),
        .sll_ifindex = if_nametoindex(ifname),
    };

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind(AF_PACKET)");
        close(fd);
        return -1;
    }

    return fd;
}

static bool packet_allowed(void *data, uint32_t len)
{
    if (len < sizeof(struct ethhdr))
        return false;

    struct ethhdr *eth = data;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return false;

    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr))
        return false;

    struct iphdr *ip = (struct iphdr *)(eth + 1);

    // Example filter:
    // Drop UDP dst port 12345, allow everything else.
    if (ip->protocol == IPPROTO_UDP) {
        uint32_t ip_hdr_len = ip->ihl * 4;
        if (len < sizeof(struct ethhdr) + ip_hdr_len + sizeof(struct udphdr))
            return false;

        struct udphdr *udp = (struct udphdr *)((uint8_t *)ip + ip_hdr_len);
        if (ntohs(udp->dest) == 12345)
            return false;
    }

    return true;
}

static int forward_packet(int raw_fd, void *data, uint32_t len)
{
    ssize_t ret = send(raw_fd, data, len, 0);
    if (ret < 0) {
        perror("send(raw)");
        return -1;
    }
    return 0;
}

static int process_packets(struct xsk_socket_info *xsk)
{
    unsigned int rcvd, idx_rx = 0;
    rcvd = xsk_ring_cons__peek(&xsk->rx, BATCH_SIZE, &idx_rx);
    if (!rcvd)
        return 0;

    for (unsigned int i = 0; i < rcvd; i++) {
        struct xdp_desc *desc = xsk_ring_cons__rx_desc(&xsk->rx, idx_rx + i);
        uint64_t addr = desc->addr;
        uint32_t len = desc->len;

        void *pkt = xsk_umem__get_data(xsk->umem->buffer, addr);

        if (packet_allowed(pkt, len)) {
            forward_packet(xsk->raw_fd, pkt, len);
        }

        unsigned int idx_fq;
        while (xsk_ring_prod__reserve(&xsk->umem->fq, 1, &idx_fq) != 1) {
            // busy-spin for low latency
        }
        *xsk_ring_prod__fill_addr(&xsk->umem->fq, idx_fq) = addr;
        xsk_ring_prod__submit(&xsk->umem->fq, 1);
    }

    xsk_ring_cons__release(&xsk->rx, rcvd);
    return rcvd;
}

static int configure_umem(struct xsk_umem_info *umem)
{
    int ret;
    void *bufs;

    ret = posix_memalign(&bufs, getpagesize(), UMEM_SIZE);
    if (ret) {
        fprintf(stderr, "posix_memalign failed\n");
        return -1;
    }

    memset(bufs, 0, UMEM_SIZE);
    umem->buffer = bufs;

    struct xsk_umem_config cfg = {
        .fill_size = NUM_FRAMES,
        .comp_size = NUM_FRAMES,
        .frame_size = FRAME_SIZE,
        .frame_headroom = 0,
        .flags = 0,
    };

    ret = xsk_umem__create(&umem->umem, umem->buffer, UMEM_SIZE,
                           &umem->fq, &umem->cq, &cfg);
    if (ret) {
        fprintf(stderr, "xsk_umem__create failed: %d\n", ret);
        return -1;
    }

    unsigned int idx;
    ret = xsk_ring_prod__reserve(&umem->fq, NUM_FRAMES, &idx);
    if (ret != NUM_FRAMES) {
        fprintf(stderr, "fq reserve failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_FRAMES; i++)
        *xsk_ring_prod__fill_addr(&umem->fq, idx + i) = i * FRAME_SIZE;

    xsk_ring_prod__submit(&umem->fq, NUM_FRAMES);
    return 0;
}

static int configure_xsk(struct xsk_socket_info *xsk, const char *ifname, uint32_t queue_id)
{
    xsk->ifindex = if_nametoindex(ifname);
    if (!xsk->ifindex) {
        perror("if_nametoindex");
        return -1;
    }

    struct xsk_socket_config cfg = {
        .rx_size = NUM_FRAMES,
        .tx_size = NUM_FRAMES,
        .libbpf_flags = 0,
        .xdp_flags = 0,
        .bind_flags = XDP_USE_NEED_WAKEUP,
    };

    int ret = xsk_socket__create(&xsk->xsk, ifname, queue_id,
                                 xsk->umem->umem, &xsk->rx, &xsk->tx, &cfg);
    if (ret) {
        fprintf(stderr, "xsk_socket__create failed: %d\n", ret);
        return -1;
    }

    return 0;
}

static int load_bpf_and_xdp(const char *ifname, uint32_t queue_id, int xsks_map_fd)
{
    struct bpf_object *obj;
    int prog_fd;
    int ifindex = if_nametoindex(ifname);

    obj = bpf_object__open_file("xdp_redirect_kern.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "bpf_object__open_file failed\n");
        return -1;
    }

    if (bpf_object__load(obj)) {
        fprintf(stderr, "bpf_object__load failed\n");
        return -1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_sock_prog");
    if (!prog) {
        fprintf(stderr, "program not found\n");
        return -1;
    }

    prog_fd = bpf_program__fd(prog);

    if (bpf_xdp_attach(ifindex, prog_fd, 0, NULL)) {
        fprintf(stderr, "bpf_xdp_attach failed\n");
        return -1;
    }

    int map_fd = bpf_object__find_map_fd_by_name(obj, "xsks_map");
    if (map_fd < 0) {
        fprintf(stderr, "xsks_map not found\n");
        return -1;
    }

    int xsk_fd = xsk_socket__fd(((struct xsk_socket_info *)0)->xsk); // placeholder avoided below
    (void)xsk_fd;
    (void)xsks_map_fd;

    // Caller should update the map directly after socket creation.
    return map_fd;
}

int main(int argc, char **argv)
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <in-iface> <out-iface>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];
    uint32_t queue_id = 0;

    struct xsk_umem_info umem = {0};
    struct xsk_socket_info xsk = {0};

    if (configure_umem(&umem) < 0)
        return 1;

    xsk.umem = &umem;
    xsk.raw_fd = raw_socket_open(out_if);
    if (xsk.raw_fd < 0)
        return 1;

    if (configure_xsk(&xsk, in_if, queue_id) < 0)
        return 1;

    struct bpf_object *obj = bpf_object__open_file("xdp_redirect_kern.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "failed to reopen BPF object\n");
        return 1;
    }

    if (bpf_object__load(obj)) {
        fprintf(stderr, "failed to load BPF object\n");
        return 1;
    }

    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_sock_prog");
    if (!prog) {
        fprintf(stderr, "failed to find XDP program\n");
        return 1;
    }

    int ifindex = if_nametoindex(in_if);
    if (bpf_xdp_attach(ifindex, bpf_program__fd(prog), 0, NULL)) {
        fprintf(stderr, "failed to attach XDP program\n");
        return 1;
    }

    int xsks_map_fd = bpf_object__find_map_fd_by_name(obj, "xsks_map");
    if (xsks_map_fd < 0) {
        fprintf(stderr, "failed to find xsks_map\n");
        return 1;
    }

    int xsk_fd = xsk_socket__fd(xsk.xsk);
    if (bpf_map_update_elem(xsks_map_fd, &queue_id, &xsk_fd, 0) != 0) {
        perror("bpf_map_update_elem");
        return 1;
    }

    printf("Forwarding started: %s -> %s\n", in_if, out_if);

    while (1) {
        int ret = process_packets(&xsk);
        if (ret == 0) {
            // busy poll or optionally use poll()
            cpu_relax();
        }
    }

    return 0;
}
