#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#define BUF_SIZE 2048

static int ifindex_from_name(int sock, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, IFNAMSIZ, "%s", ifname);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
        perror("SIOCGIFINDEX");
        return -1;
    }
    return ifr.ifr_ifindex;
}

static int bind_raw_socket_to_if(int sock, int ifindex) {
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex;
    if (bind(sock, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return -1;
    }
    return 0;
}

static int is_matching_udp_port(const unsigned char *buf, ssize_t len, uint16_t match_port) {
    if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr)))
        return 0;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return 0;

    const struct iphdr *ip = (const struct iphdr *)(buf + sizeof(struct ethhdr));
    if (ip->protocol != IPPROTO_UDP)
        return 0;

    int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < (int)sizeof(struct iphdr))
        return 0;

    if (len < (ssize_t)(sizeof(struct ethhdr) + ip_hdr_len + sizeof(struct udphdr)))
        return 0;

    const struct udphdr *udp = (const struct udphdr *)(buf + sizeof(struct ethhdr) + ip_hdr_len);
    return ntohs(udp->dest) == match_port;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <ingress_if> <egress_if> <udp_dest_port>\n", argv[0]);
        return 1;
    }

    const char *ingress_if = argv[1];
    const char *egress_if = argv[2];
    uint16_t match_port = (uint16_t)atoi(argv[3]);

    int rx_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (rx_sock < 0) {
        perror("socket rx");
        return 1;
    }

    int tx_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx_sock < 0) {
        perror("socket tx");
        close(rx_sock);
        return 1;
    }

    int ingress_ifindex = ifindex_from_name(rx_sock, ingress_if);
    int egress_ifindex = ifindex_from_name(tx_sock, egress_if);
    if (ingress_ifindex < 0 || egress_ifindex < 0) {
        close(rx_sock);
        close(tx_sock);
        return 1;
    }

    if (bind_raw_socket_to_if(rx_sock, ingress_ifindex) < 0) {
        close(rx_sock);
        close(tx_sock);
        return 1;
    }

    struct sockaddr_ll tx_addr;
    memset(&tx_addr, 0, sizeof(tx_addr));
    tx_addr.sll_family = AF_PACKET;
    tx_addr.sll_ifindex = egress_ifindex;
    tx_addr.sll_protocol = htons(ETH_P_ALL);
    tx_addr.sll_halen = ETH_ALEN;

    unsigned char buf[BUF_SIZE];

    while (1) {
        ssize_t n = recvfrom(rx_sock, buf, sizeof(buf), 0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        if (!is_matching_udp_port(buf, n, match_port)) {
            continue;
        }

        const struct ethhdr *eth = (const struct ethhdr *)buf;
        memcpy(tx_addr.sll_addr, eth->h_dest, ETH_ALEN);

        ssize_t sent = sendto(tx_sock, buf, n, 0, (struct sockaddr *)&tx_addr, sizeof(tx_addr));
        if (sent < 0) {
            perror("sendto");
        }
    }

    close(rx_sock);
    close(tx_sock);
    return 0;
}
```

