use std::io;
use std::net::{SocketAddr, UdpSocket};
use std::time::Duration;

const LISTEN_ADDR: &str = "127.0.0.1:4000";
const FORWARD_ADDR: &str = "127.0.0.1:5000";
const MAX_PACKET: usize = 2048;

// Very simple demo policy:
// - drop empty packets
// - drop packets larger than 1400 bytes
// - allow packets beginning with b"OK:"
fn allowed(buf: &[u8]) -> bool {
    !buf.is_empty() && buf.len() <= 1400 && buf.starts_with(b"OK:")
}

fn main() -> io::Result<()> {
    let in_sock = UdpSocket::bind(LISTEN_ADDR)?;
    let out_sock = UdpSocket::bind("127.0.0.1:0")?;
    let forward_addr: SocketAddr = FORWARD_ADDR.parse().unwrap();

    in_sock.set_nonblocking(false)?;
    in_sock.set_read_timeout(Some(Duration::from_millis(500)))?;

    println!("listening on {}", LISTEN_ADDR);
    println!("forwarding allowed packets to {}", FORWARD_ADDR);

    let mut buf = [0u8; MAX_PACKET];

    loop {
        match in_sock.recv_from(&mut buf) {
            Ok((n, src)) => {
                let pkt = &buf[..n];
                if allowed(pkt) {
                    let sent = out_sock.send_to(pkt, forward_addr)?;
                    println!("allow src={} bytes={} forwarded={}", src, n, sent);
                } else {
                    println!("drop src={} bytes={}", src, n);
                }
            }
            Err(e)
                if e.kind() == io::ErrorKind::WouldBlock
                    || e.kind() == io::ErrorKind::TimedOut =>
            {
                continue;
            }
            Err(e) => return Err(e),
        }
    }
}
```

