# Files

## 1) `xdp_fw_kern.c`
```c
// xdp_fw_kern.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>

char LICENSE[] SEC("license") = "GPL";

/*
 * Minimal XDP packet filter:
 * - If packet is IPv4 + UDP and dst port == 9999 => DROP
 * - Otherwise => PASS
 *
 * This is ultra-low-latency because it runs at the XDP hook
 * before the normal kernel network stack.
 */

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx)
{
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // Parse Ethernet
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    // Parse IPv4
    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    // Variable-length IPv4 header
    int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(*ip))
        return XDP_PASS;

    struct udphdr *udp = (void *)ip + ip_hdr_len;
    if ((void *)(udp + 1) > data_end)
        return XDP_PASS;

    // Drop UDP packets destined to port 9999
    if (bpf_ntohs(udp->dest) == 9999)
        return XDP_DROP;

    return XDP_PASS;
}
```

