## 2) `loader.c`
```c
// loader.c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <net/if.h>
#include <unistd.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

static void usage(const char *prog)
{
    fprintf(stderr, "Usage: %s <ifname>\n", prog);
}

int main(int argc, char **argv)
{
    struct bpf_object *obj = NULL;
    struct bpf_program *prog;
    int prog_fd;
    int ifindex;
    int err;

    if (argc != 2) {
        usage(argv[0]);
        return 1;
    }

    ifindex = if_nametoindex(argv[1]);
    if (!ifindex) {
        fprintf(stderr, "Invalid interface %s\n", argv[1]);
        return 1;
    }

    obj = bpf_object__open_file("xdp_fw_kern.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object: %d\n", err);
        bpf_object__close(obj);
        return 1;
    }

    prog = bpf_object__find_program_by_name(obj, "xdp_filter_forward");
    if (!prog) {
        fprintf(stderr, "Program not found\n");
        bpf_object__close(obj);
        return 1;
    }

    prog_fd = bpf_program__fd(prog);
    if (prog_fd < 0) {
        fprintf(stderr, "Invalid program fd\n");
        bpf_object__close(obj);
        return 1;
    }

    err = bpf_set_link_xdp_fd(ifindex, prog_fd, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to attach XDP program to %s: %s\n",
                argv[1], strerror(-err));
        bpf_object__close(obj);
        return 1;
    }

    printf("XDP program attached to %s\n", argv[1]);
    printf("Dropping UDP dst port 9999. Press Ctrl+C to exit.\n");

    while (1)
        sleep(1);

    bpf_set_link_xdp_fd(ifindex, -1, 0);
    bpf_object__close(obj);
    return 0;
}
```

