Below is a minimal working example in <language>C</language> using Linux raw packet sockets (AF_PACKET). It is not the absolute lowest-latency approach compared with DPDK/XDP/AF_XDP, but it is small, buildable, and demonstrates packet-level filtering and forwarding clearly.

It:
- receives Ethernet frames on one interface
- filters IPv4 UDP packets to a chosen destination port
- forwards matching packets out another interface
- drops everything else

Code:

```c
// ull_forwarder.c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/if.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <net/ethernet.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#define BUF_SIZE 2048

static int get_ifindex(int fd, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("SIOCGIFINDEX");
        return -1;
    }
    return ifr.ifr_ifindex;
}

static int bind_raw_socket(const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int ifindex = get_ifindex(fd, ifname);
    if (ifindex < 0) {
        close(fd);
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    return fd;
}

static int send_frame(int fd, const char *out_ifname, const unsigned char *buf, ssize_t len) {
    int ifindex = get_ifindex(fd, out_ifname);
    if (ifindex < 0) {
        return -1;
    }

    struct sockaddr_ll addr;
    memset(&addr, 0, sizeof(addr));
    addr.sll_family = AF_PACKET;
    addr.sll_ifindex = ifindex;
    addr.sll_halen = ETH_ALEN;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    memcpy(addr.sll_addr, eth->h_dest, ETH_ALEN);

    if (sendto(fd, buf, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        return -1;
    }

    return 0;
}

static int should_forward(const unsigned char *buf, ssize_t len, uint16_t udp_dport) {
    if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) {
        return 0;
    }

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP) {
        return 0;
    }

    const struct iphdr *ip = (const struct iphdr *)(buf + sizeof(struct ethhdr));
    if (ip->protocol != IPPROTO_UDP) {
        return 0;
    }

    size_t ip_hdr_len = ip->ihl * 4;
    if (len < (ssize_t)(sizeof(struct ethhdr) + ip_hdr_len + sizeof(struct udphdr))) {
        return 0;
    }

    const struct udphdr *udp = (const struct udphdr *)(buf + sizeof(struct ethhdr) + ip_hdr_len);
    if (ntohs(udp->dest) != udp_dport) {
        return 0;
    }

    return 1;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <in_if> <out_if> <udp_dest_port>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];
    uint16_t udp_dport = (uint16_t)atoi(argv[3]);

    int rx_fd = bind_raw_socket(in_if);
    if (rx_fd < 0) {
        return 1;
    }

    int tx_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx_fd < 0) {
        perror("socket tx");
        close(rx_fd);
        return 1;
    }

    unsigned char buf[BUF_SIZE];

    while (1) {
        ssize_t n = recvfrom(rx_fd, buf, sizeof(buf), 0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        if (!should_forward(buf, n, udp_dport)) {
            continue;
        }

        if (send_frame(tx_fd, out_if, buf, n) < 0) {
            fprintf(stderr, "failed to forward packet\n");
        }
    }

    close(tx_fd);
    close(rx_fd);
    return 0;
}
```

