## 1) Kernel XDP program: `xdp_fw_kern.c`

```c
// xdp_fw_kern.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#include <linux/if_ether.h>
#include <linux/ip.h>

char LICENSE[] SEC("license") = "GPL";

// devmap: key 0 -> egress ifindex
struct {
    __uint(type, BPF_MAP_TYPE_DEVMAP);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, __u32);
} tx_port SEC(".maps");

// array map holding blocked IPv4 address in network byte order at key 0
struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, __u32);
} blocked_ip SEC(".maps");

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx)
{
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_ABORTED;

    if (bpf_ntohs(eth->h_proto) != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_ABORTED;

    __u32 key = 0;
    __u32 *blocked = bpf_map_lookup_elem(&blocked_ip, &key);
    if (blocked && iph->saddr == *blocked) {
        return XDP_DROP;
    }

    // forward to interface stored in tx_port[0]
    return bpf_redirect_map(&tx_port, 0, XDP_PASS);
}
```

