## 2) User-space loader: `xdp_fw_user.c`

This program:

- loads the BPF object
- finds interfaces by name
- sets `tx_port[0] = <egress ifindex>`
- sets `blocked_ip[0] = <blocked src IPv4>`
- attaches XDP program to ingress interface

```c
// xdp_fw_user.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <signal.h>

#include <bpf/libbpf.h>
#include <bpf/bpf.h>

static int ifindex_in = -1;
static int prog_fd = -1;
static int xdp_flags = XDP_FLAGS_DRV_MODE;

static void cleanup(int sig)
{
    if (ifindex_in >= 0 && prog_fd >= 0) {
        bpf_set_link_xdp_fd(ifindex_in, -1, xdp_flags);
    }
    exit(0);
}

static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s <ingress_ifname> <egress_ifname> <blocked_src_ip>\n"
        "Example: %s eth0 eth1 10.0.0.1\n",
        prog, prog);
}

int main(int argc, char **argv)
{
    struct bpf_object *obj = NULL;
    struct bpf_program *prog = NULL;
    int map_fd_tx = -1, map_fd_block = -1;
    int ifindex_out;
    __u32 key = 0;
    __u32 blocked_addr;
    int err;

    if (argc != 4) {
        usage(argv[0]);
        return 1;
    }

    const char *ingress_if = argv[1];
    const char *egress_if = argv[2];
    const char *blocked_ip_str = argv[3];

    ifindex_in = if_nametoindex(ingress_if);
    ifindex_out = if_nametoindex(egress_if);

    if (!ifindex_in) {
        fprintf(stderr, "Unknown ingress interface: %s\n", ingress_if);
        return 1;
    }
    if (!ifindex_out) {
        fprintf(stderr, "Unknown egress interface: %s\n", egress_if);
        return 1;
    }

    if (inet_pton(AF_INET, blocked_ip_str, &blocked_addr) != 1) {
        fprintf(stderr, "Invalid IPv4 address: %s\n", blocked_ip_str);
        return 1;
    }

    obj = bpf_object__open_file("xdp_fw_kern.o", NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Failed to open BPF object\n");
        return 1;
    }

    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object: %d\n", err);
        return 1;
    }

    prog = bpf_object__find_program_by_name(obj, "xdp_filter_forward");
    if (!prog) {
        fprintf(stderr, "Failed to find BPF program\n");
        return 1;
    }

    prog_fd = bpf_program__fd(prog);
    if (prog_fd < 0) {
        fprintf(stderr, "Failed to get program fd\n");
        return 1;
    }

    map_fd_tx = bpf_object__find_map_fd_by_name(obj, "tx_port");
    if (map_fd_tx < 0) {
        fprintf(stderr, "Failed to find tx_port map\n");
        return 1;
    }

    map_fd_block = bpf_object__find_map_fd_by_name(obj, "blocked_ip");
    if (map_fd_block < 0) {
        fprintf(stderr, "Failed to find blocked_ip map\n");
        return 1;
    }

    err = bpf_map_update_elem(map_fd_tx, &key, &ifindex_out, BPF_ANY);
    if (err) {
        fprintf(stderr, "Failed to update tx_port: %s\n", strerror(errno));
        return 1;
    }

    err = bpf_map_update_elem(map_fd_block, &key, &blocked_addr, BPF_ANY);
    if (err) {
        fprintf(stderr, "Failed to update blocked_ip: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    err = bpf_set_link_xdp_fd(ifindex_in, prog_fd, xdp_flags);
    if (err) {
        fprintf(stderr,
                "Failed to attach XDP program in driver mode: %s\n",
                strerror(-err));
        fprintf(stderr, "Try generic mode if your NIC driver does not support native XDP.\n");
        return 1;
    }

    printf("XDP program attached.\n");
    printf("Ingress: %s (ifindex %d)\n", ingress_if, ifindex_in);
    printf("Egress : %s (ifindex %d)\n", egress_if, ifindex_out);
    printf("Blocked source IP: %s\n", blocked_ip_str);
    printf("Press Ctrl-C to detach and exit.\n");

    while (1) {
        pause();
    }

    return 0;
}
