```rust
use std::env;
use std::fs::File;
use std::io::{self, BufReader, Read};

const BUFFER_SIZE: usize = 1024 * 1024; // 1 MiB

#[derive(Default, Debug)]
struct Stats {
    records: u64,
    bytes: u64,
    sum: u64,
}

/// Parses ASCII lines containing unsigned integers, one per line.
/// Example input:
/// 123
/// 456
/// 789
///
/// This is implemented as a streaming parser:
/// - reads chunks into a reusable buffer
/// - handles records split across chunk boundaries
/// - avoids per-line allocation
fn process_stream<R: Read>(mut reader: R) -> io::Result<Stats> {
    let mut stats = Stats::default();

    let mut buf = vec![0u8; BUFFER_SIZE];
    let mut carry = Vec::<u8>::with_capacity(128);

    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }

        stats.bytes += n as u64;
        let chunk = &buf[..n];

        let mut start = 0usize;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if carry.is_empty() {
                    parse_line(&chunk[start..i], &mut stats);
                } else {
                    carry.extend_from_slice(&chunk[start..i]);
                    parse_line(&carry, &mut stats);
                    carry.clear();
                }
                start = i + 1;
            }
        }

        if start < chunk.len() {
            carry.extend_from_slice(&chunk[start..]);
        }
    }

    if !carry.is_empty() {
        parse_line(&carry, &mut stats);
    }

    Ok(stats)
}

#[inline]
fn parse_line(line: &[u8], stats: &mut Stats) {
    if line.is_empty() {
        return;
    }

    let mut value: u64 = 0;
    for &b in line {
        if b >= b'0' && b <= b'9' {
            value = value.saturating_mul(10).saturating_add((b - b'0') as u64);
        } else {
            return;
        }
    }

    stats.records += 1;
    stats.sum += value;
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    let stats = if args.len() > 1 {
        let file = File::open(&args[1])?;
        let reader = BufReader::with_capacity(BUFFER_SIZE, file);
        process_stream(reader)?
    } else {
        let stdin = io::stdin();
        let reader = stdin.lock();
        process_stream(reader)?
    };

    eprintln!("records={}", stats.records);
    eprintln!("bytes={}", stats.bytes);
    eprintln!("sum={}", stats.sum);

    Ok(())
}
```

### Why this is memory-efficient

- Uses a single reusable read buffer
- Does not load the full input into memory
- Only keeps a small `carry` buffer for records split across read boundaries
- Avoids creating `String`s for every line
- Parses directly from raw bytes

