```rust
use std::env;
use std::fs::File;
use std::io::{self, BufReader, Read};

const BUF_SIZE: usize = 64 * 1024;

#[derive(Default, Debug)]
struct Stats {
    records: u64,
    parse_errors: u64,
    value_sum: i64,
}

fn process_record(record: &[u8], stats: &mut Stats) {
    if record.is_empty() {
        return;
    }

    let Some(comma_pos) = record.iter().position(|&b| b == b',') else {
        stats.parse_errors += 1;
        return;
    };

    let _key = &record[..comma_pos];
    let value_bytes = &record[comma_pos + 1..];

    match std::str::from_utf8(value_bytes)
        .ok()
        .and_then(|s| s.trim().parse::<i64>().ok())
    {
        Some(value) => {
            stats.records += 1;
            stats.value_sum += value;
        }
        None => {
            stats.parse_errors += 1;
        }
    }
}

fn parse_stream<R: Read>(reader: R) -> io::Result<Stats> {
    let mut reader = BufReader::with_capacity(BUF_SIZE, reader);
    let mut buf = [0u8; BUF_SIZE];
    let mut carry = Vec::<u8>::with_capacity(1024);
    let mut stats = Stats::default();

    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }

        let chunk = &buf[..n];
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if carry.is_empty() {
                    let mut line = &chunk[start..i];
                    if line.ends_with(b"\r") {
                        line = &line[..line.len() - 1];
                    }
                    process_record(line, &mut stats);
                } else {
                    carry.extend_from_slice(&chunk[start..i]);
                    if carry.ends_with(b"\r") {
                        carry.pop();
                    }
                    process_record(&carry, &mut stats);
                    carry.clear();
                }
                start = i + 1;
            }
        }

        if start < chunk.len() {
            carry.extend_from_slice(&chunk[start..]);
        }
    }

    if !carry.is_empty() {
        if carry.ends_with(b"\r") {
            carry.pop();
        }
        process_record(&carry, &mut stats);
    }

    Ok(stats)
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    let stats = if args.len() > 1 {
        let file = File::open(&args[1])?;
        parse_stream(file)?
    } else {
        let stdin = io::stdin();
        parse_stream(stdin.lock())?
    };

    println!("records={}", stats.records);
    println!("parse_errors={}", stats.parse_errors);
    println!("value_sum={}", stats.value_sum);

    Ok(())
}
