## Rust implementation

```rust
use std::env;
use std::fs::File;
use std::io::{self, BufReader, Read};

const BUF_SIZE: usize = 1024 * 1024; // 1 MiB read buffer

#[derive(Debug)]
struct Record<'a> {
    timestamp: u64,
    user_id: u64,
    event_type: &'a [u8],
    value: i64,
}

#[derive(Default, Debug)]
struct Stats {
    records: u64,
    bytes: u64,
    parse_errors: u64,
    value_sum: i128,
}

fn parse_u64(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return None;
    }
    let mut n = 0u64;
    for &b in bytes {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?;
        n = n.checked_add((b - b'0') as u64)?;
    }
    Some(n)
}

fn parse_i64(bytes: &[u8]) -> Option<i64> {
    if bytes.is_empty() {
        return None;
    }

    let (neg, digits) = if bytes[0] == b'-' {
        if bytes.len() == 1 {
            return None;
        }
        (true, &bytes[1..])
    } else {
        (false, bytes)
    };

    let mut n = 0i64;
    for &b in digits {
        if !(b'0'..=b'9').contains(&b) {
            return None;
        }
        n = n.checked_mul(10)?;
        n = n.checked_add((b - b'0') as i64)?;
    }

    if neg {
        n.checked_neg()
    } else {
        Some(n)
    }
}

fn parse_record(line: &[u8]) -> Option<Record<'_>> {
    let mut fields = [0usize; 3];
    let mut count = 0usize;

    for (i, &b) in line.iter().enumerate() {
        if b == b',' {
            if count < 3 {
                fields[count] = i;
            }
            count += 1;
        }
    }

    if count != 3 {
        return None;
    }

    let c1 = fields[0];
    let c2 = fields[1];
    let c3 = fields[2];

    let timestamp = parse_u64(&line[..c1])?;
    let user_id = parse_u64(&line[c1 + 1..c2])?;
    let event_type = &line[c2 + 1..c3];
    let value = parse_i64(&line[c3 + 1..])?;

    Some(Record {
        timestamp,
        user_id,
        event_type,
        value,
    })
}

fn process_record(record: Record<'_>, stats: &mut Stats) {
    // Replace this with your real logic.
    // This example just accumulates stats.
    let _ = record.timestamp;
    let _ = record.user_id;
    let _ = record.event_type;
    stats.records += 1;
    stats.value_sum += record.value as i128;
}

fn process_chunk(buffer: &[u8], stats: &mut Stats) {
    let mut start = 0usize;

    for (i, &b) in buffer.iter().enumerate() {
        if b == b'\n' {
            let mut line = &buffer[start..i];

            if let Some(&b'\r') = line.last() {
                line = &line[..line.len() - 1];
            }

            if !line.is_empty() {
                match parse_record(line) {
                    Some(record) => process_record(record, stats),
                    None => stats.parse_errors += 1,
                }
            }

            start = i + 1;
        }
    }
}

fn run<R: Read>(reader: R) -> io::Result<Stats> {
    let mut reader = BufReader::with_capacity(BUF_SIZE, reader);
    let mut stats = Stats::default();

    let mut read_buf = vec![0u8; BUF_SIZE];
    let mut carry = Vec::<u8>::with_capacity(1024);

    loop {
        let n = reader.read(&mut read_buf)?;
        if n == 0 {
            break;
        }

        stats.bytes += n as u64;

        let chunk = &read_buf[..n];

        if carry.is_empty() {
            if let Some(last_nl) = chunk.iter().rposition(|&b| b == b'\n') {
                process_chunk(&chunk[..=last_nl], &mut stats);
                carry.extend_from_slice(&chunk[last_nl + 1..]);
            } else {
                carry.extend_from_slice(chunk);
            }
        } else {
            let mut merged = Vec::with_capacity(carry.len() + chunk.len());
            merged.extend_from_slice(&carry);
            merged.extend_from_slice(chunk);

            if let Some(last_nl) = merged.iter().rposition(|&b| b == b'\n') {
                process_chunk(&merged[..=last_nl], &mut stats);
                carry.clear();
                carry.extend_from_slice(&merged[last_nl + 1..]);
            } else {
                carry.clear();
                carry.extend_from_slice(&merged);
            }
        }
    }

    if !carry.is_empty() {
        let mut line = carry.as_slice();
        if let Some(&b'\r') = line.last() {
            line = &line[..line.len() - 1];
        }

        if !line.is_empty() {
            match parse_record(line) {
                Some(record) => process_record(record, &mut stats),
                None => stats.parse_errors += 1,
            }
        }
    }

    Ok(stats)
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    let stats = if args.len() > 1 {
        let file = File::open(&args[1])?;
        run(file)?
    } else {
        let stdin = io::stdin();
        run(stdin.lock())?
    };

    eprintln!("records      : {}", stats.records);
    eprintln!("bytes         : {}", stats.bytes);
