```rust
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;

/// Configuration for the streaming parser.
#[derive(Debug, Clone, Copy)]
pub struct ParserConfig {
    /// Size of the reusable read buffer.
    pub read_buffer_size: usize,
    /// Maximum allowed record size before returning an error.
    pub max_record_size: usize,
    /// Whether to strip trailing '\r' before emitting a line.
    pub trim_cr: bool,
}

impl Default for ParserConfig {
    fn default() -> Self {
        Self {
            // Large enough for throughput, small enough for cache/memory sanity.
            read_buffer_size: 256 * 1024,
            // Safety limit for pathological input.
            max_record_size: 16 * 1024 * 1024,
            trim_cr: true,
        }
    }
}

/// Errors produced by the parser.
#[derive(Debug)]
pub enum ParseError {
    Io(io::Error),
    RecordTooLarge { size: usize, max: usize },
    Callback(String),
}

impl From<io::Error> for ParseError {
    fn from(err: io::Error) -> Self {
        ParseError::Io(err)
    }
}

/// A high-throughput streaming line parser.
///
/// It processes records separated by '\n'. If a record spans multiple chunks,
/// it is assembled into an internal reusable buffer.
pub struct StreamingParser {
    config: ParserConfig,
    carry: Vec<u8>,
}

impl StreamingParser {
    pub fn new(config: ParserConfig) -> Self {
        Self {
            config,
            carry: Vec::with_capacity(1024),
        }
    }

    /// Parse from any `Read` source.
    ///
    /// `on_record` receives each logical record as a byte slice.
    /// The slice is only valid for the duration of the callback.
    pub fn parse_reader<R, F>(&mut self, mut reader: R, mut on_record: F) -> Result<(), ParseError>
    where
        R: Read,
        F: FnMut(&[u8]) -> Result<(), ParseError>,
    {
        let mut buf = vec![0u8; self.config.read_buffer_size];

        loop {
            let n = reader.read(&mut buf)?;
            if n == 0 {
                break;
            }

            self.process_chunk(&buf[..n], &mut on_record)?;
        }

        // Emit final unterminated record if present.
        if !self.carry.is_empty() {
            let record = if self.config.trim_cr && self.carry.last() == Some(&b'\r') {
                &self.carry[..self.carry.len() - 1]
            } else {
                &self.carry
            };
            on_record(record)?;
            self.carry.clear();
        }

        Ok(())
    }

    /// Parse from a file path using a buffered file reader.
    pub fn parse_file<P, F>(&mut self, path: P, on_record: F) -> Result<(), ParseError>
    where
        P: AsRef<Path>,
        F: FnMut(&[u8]) -> Result<(), ParseError>,
    {
        let file = File::open(path)?;
        let reader = BufReader::with_capacity(self.config.read_buffer_size, file);
        self.parse_reader(reader, on_record)
    }

    fn process_chunk<F>(&mut self, chunk: &[u8], on_record: &mut F) -> Result<(), ParseError>
    where
        F: FnMut(&[u8]) -> Result<(), ParseError>,
    {
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if self.carry.is_empty() {
                    // Fast path: record entirely inside the current chunk.
                    let mut record = &chunk[start..i];
                    if self.config.trim_cr && record.last() == Some(&b'\r') {
                        record = &record[..record.len() - 1];
                    }
                    on_record(record)?;
                } else {
                    // Slow path: record spans multiple chunks.
                    self.carry.extend_from_slice(&chunk[start..i]);

                    if self.carry.len() > self.config.max_record_size {
                        return Err(ParseError::RecordTooLarge {
                            size: self.carry.len(),
                            max: self.config.max_record_size,
                        });
                    }

                    let record = if self.config.trim_cr && self.carry.last() == Some(&b'\r') {
                        &self.carry[..self.carry.len() - 1]
                    } else {
                        &self.carry
                    };
                    on_record(record)?;
                    self.carry.clear();
                }

                start = i + 1;
            }
        }

        // Save trailing partial record.
        if start < chunk.len() {
            let remain = &chunk[start..];
            let new_len = self.carry.len() + remain.len();

            if new_len > self.config.max_record_size {
                return Err(ParseError::RecordTooLarge {
                    size: new_len,
                    max: self.config.max_record_size,
                });
            }

            self.carry.extend_from_slice(remain);
        }

        Ok(())
    }
}
