## Rust implementation

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// A zero-copy view of a parsed record.
/// Each field borrows from the line buffer currently being processed.
#[derive(Debug)]
pub struct Record<'a> {
    pub fields: Vec<&'a [u8]>,
}

/// Streaming parser configuration.
#[derive(Debug, Clone)]
pub struct ParserConfig {
    /// Maximum line size allowed before rejecting input.
    pub max_record_len: usize,
    /// Field delimiter, e.g. b',' for CSV-like input.
    pub delimiter: u8,
}

impl Default for ParserConfig {
    fn default() -> Self {
        Self {
            max_record_len: 8 * 1024 * 1024, // 8 MiB safety cap per record
            delimiter: b',',
        }
    }
}

/// Streaming parser with reusable allocation buffers.
pub struct StreamingParser {
    config: ParserConfig,
    line_buf: Vec<u8>,
    field_indices: Vec<(usize, usize)>,
}

impl StreamingParser {
    pub fn new(config: ParserConfig) -> Self {
        Self {
            config,
            line_buf: Vec::with_capacity(64 * 1024),
            field_indices: Vec::with_capacity(32),
        }
    }

    /// Parse records from any BufRead source.
    ///
    /// The callback receives each parsed record as borrowed slices.
    /// The record is only valid for the duration of the callback.
    pub fn parse_reader<R, F>(&mut self, mut reader: R, mut on_record: F) -> io::Result<()>
    where
        R: BufRead,
        F: FnMut(Record<'_>) -> io::Result<()>,
    {
        loop {
            self.line_buf.clear();

            let bytes_read = reader.read_until(b'\n', &mut self.line_buf)?;
            if bytes_read == 0 {
                break;
            }

            if self.line_buf.len() > self.config.max_record_len {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "record exceeds max_record_len",
                ));
            }

            // Trim trailing '\n' and optional '\r'
            if self.line_buf.last() == Some(&b'\n') {
                self.line_buf.pop();
            }
            if self.line_buf.last() == Some(&b'\r') {
                self.line_buf.pop();
            }

            self.field_indices.clear();
            self.split_fields();

            let fields = self
                .field_indices
                .iter()
                .map(|(start, end)| &self.line_buf[*start..*end])
                .collect::<Vec<_>>();

            let record = Record { fields };
            on_record(record)?;
        }

        Ok(())
    }

    fn split_fields(&mut self) {
        let mut start = 0;
        for (i, &b) in self.line_buf.iter().enumerate() {
            if b == self.config.delimiter {
                self.field_indices.push((start, i));
                start = i + 1;
            }
        }
        self.field_indices.push((start, self.line_buf.len()));
    }
}

/// Example processing function:
/// counts records and total bytes in first field without allocating strings.
fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: parser <input-file>");

    let file = File::open(Path::new(&path))?;
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let config = ParserConfig {
        max_record_len: 8 * 1024 * 1024,
        delimiter: b',',
    };

    let mut parser = StreamingParser::new(config);

    let mut record_count: u64 = 0;
    let mut first_field_bytes: u64 = 0;

    parser.parse_reader(reader, |record| {
        record_count += 1;
        if let Some(first) = record.fields.get(0) {
            first_field_bytes += first.len() as u64;
        }

        // Example: do real processing here
        // Avoid converting to String unless necessary.

        Ok(())
    })?;

    println!("records={}", record_count);
    println!("first_field_bytes={}", first_field_bytes);

    Ok(())
}
