```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// A callback-based streaming parser.
/// It reads gigabyte-scale input incrementally and calls `on_record`
/// for each newline-delimited record without storing the full dataset.
///
/// This implementation is optimized for:
/// - low memory overhead
/// - reusable buffering
/// - streaming operation
///
/// It supports records split across internal buffer boundaries.
pub struct StreamParser<R: BufRead> {
    reader: R,
    carry: Vec<u8>, // reused only when a line spans multiple buffer fills
}

impl<R: BufRead> StreamParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            carry: Vec::with_capacity(1024),
        }
    }

    /// Parse newline-delimited records.
    ///
    /// `on_record` receives each record as raw bytes excluding the trailing '\n'.
    /// This avoids UTF-8 assumptions and allows binary-safe parsing.
    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            let buf = self.reader.fill_buf()?;
            if buf.is_empty() {
                if !self.carry.is_empty() {
                    on_record(&self.carry);
                    self.carry.clear();
                }
                return Ok(());
            }

            let mut start = 0;
            for i in 0..buf.len() {
                if buf[i] == b'\n' {
                    if self.carry.is_empty() {
                        // Fast path: record fits entirely in current buffer
                        let line = &buf[start..i];
                        on_record(line);
                    } else {
                        // Slow path: record spans multiple fills
                        self.carry.extend_from_slice(&buf[start..i]);
                        on_record(&self.carry);
                        self.carry.clear();
                    }
                    start = i + 1;
                }
            }

            if start < buf.len() {
                // Save remaining partial record for next fill
                self.carry.extend_from_slice(&buf[start..]);
            }

            let consumed = buf.len();
            self.reader.consume(consumed);
        }
    }
}

/// Example record processor:
/// Parses lines like:
/// timestamp,level,message
///
/// This is a zero-copy field splitter over each record.
fn process_csv_like_record(record: &[u8]) {
    let mut fields = record.split(|&b| b == b',');

    let ts = fields.next().unwrap_or(b"");
    let level = fields.next().unwrap_or(b"");
    let message = fields.next().unwrap_or(b"");

    // For demonstration: avoid allocating Strings unless necessary.
    // In a real system, you'd likely parse integers/timestamps directly from bytes.
    println!(
        "ts={:?}, level={:?}, message={:?}",
        String::from_utf8_lossy(ts),
        String::from_utf8_lossy(level),
        String::from_utf8_lossy(message)
    );
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: parser <input-file>");

    let file = File::open(Path::new(&path))?;

    // Large read buffer helps throughput for gigabyte-scale inputs.
    let reader = BufReader::with_capacity(1024 * 1024, file);

    let mut parser = StreamParser::new(reader);
    parser.parse(process_csv_like_record)?;

    Ok(())
}
```

