impl<R: BufRead> StreamParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            carry: Vec::with_capacity(1024),
        }
    }

    pub fn parse<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        loop {
            let buf = self.reader.fill_buf()?;
            if buf.is_empty() {
                if !self.carry.is_empty() {
                    on_record(&self.carry);
                    self.carry.clear();
                }
                return Ok(());
            }

            let mut start = 0;
            for i in memchr_iter(b'\n', buf) {
                if self.carry.is_empty() {
                    on_record(&buf[start..i]);
                } else {
                    self.carry.extend_from_slice(&buf[start..i]);
                    on_record(&self.carry);
                    self.carry.clear();
                }
                start = i + 1;
            }

            if start < buf.len() {
                self.carry.extend_from_slice(&buf[start..]);
            }

            let consumed = buf.len();
            self.reader.consume(consumed);
        }
    }
}

fn main() -> io::Result<()> {
    let file = File::open("input.txt")?;
    let reader = BufReader::with_capacity(1024 * 1024, file);
    let mut parser = StreamParser::new(reader);

    parser.parse(|record| {
        // Hot path: keep this lightweight
        let _ = record;
    })?;

    Ok(())
}
