use std::env;
use std::fs::File;
use std::io::{self, BufReader, Read};

const READ_BUF_SIZE: usize = 1024 * 1024; // 1 MiB

/// Example parser output stats.
/// Replace this with your real processing logic.
#[derive(Default, Debug)]
struct Stats {
    records: u64,
    bytes: u64,
}

/// Process one complete record.
/// This version treats each record as a raw byte slice.
/// Replace with your domain-specific parsing logic.
#[inline(always)]
fn process_record(record: &[u8], stats: &mut Stats) {
    stats.records += 1;
    stats.bytes += record.len() as u64;

    // Example lightweight parsing:
    // - skip empty lines
    // - optionally inspect fields without allocating
    if record.is_empty() {
        return;
    }

    // Example: touch first byte so compiler doesn't optimize away logic
    let _first = record[0];
}

/// Streaming parser for newline-delimited input.
/// Handles records spanning multiple read chunks.
fn parse_stream<R: Read>(reader: R) -> io::Result<Stats> {
    let mut reader = BufReader::with_capacity(READ_BUF_SIZE, reader);
    let mut read_buf = vec![0u8; READ_BUF_SIZE];
    let mut carry = Vec::<u8>::with_capacity(1024);
    let mut stats = Stats::default();

    loop {
        let n = reader.read(&mut read_buf)?;
        if n == 0 {
            break;
        }

        let chunk = &read_buf[..n];
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                if carry.is_empty() {
                    let mut record = &chunk[start..i];
                    if record.last() == Some(&b'\r') {
                        record = &record[..record.len() - 1];
                    }
                    process_record(record, &mut stats);
                } else {
                    carry.extend_from_slice(&chunk[start..i]);
                    if carry.last() == Some(&b'\r') {
                        carry.pop();
                    }
                    process_record(&carry, &mut stats);
                    carry.clear();
                }
                start = i + 1;
            }
        }

        if start < chunk.len() {
            carry.extend_from_slice(&chunk[start..]);
        }
    }

    // Final record if file does not end with newline
    if !carry.is_empty() {
        if carry.last() == Some(&b'\r') {
            carry.pop();
        }
        process_record(&carry, &mut stats);
    }

    Ok(stats)
}

fn main() -> io::Result<()> {
    let mut args = env::args();
    let _program = args.next();

    let stats = if let Some(path) = args.next() {
        let file = File::open(path)?;
        parse_stream(file)?
    } else {
        let stdin = io::stdin();
        let locked = stdin.lock();
        parse_stream(locked)?
    };

    eprintln!("records={} bytes={}", stats.records, stats.bytes);
    Ok(())
}
