## Minimal working Rust parser

```rust
use std::io::{self, BufRead};

#[derive(Default, Debug)]
struct Stats {
    records: u64,
    malformed: u64,
    value_sum: u64,
}

fn parse_line(line: &str, stats: &mut Stats) {
    let mut parts = line.trim_end().split(',');

    let ts = parts.next();
    let user_id = parts.next();
    let value = parts.next();

    // Ensure exactly 3 fields
    if ts.is_none() || user_id.is_none() || value.is_none() || parts.next().is_some() {
        stats.malformed += 1;
        return;
    }

    // Parse fields with minimal overhead
    let ts_ok = ts.unwrap().parse::<u64>().is_ok();
    let user_ok = user_id.unwrap().parse::<u64>().is_ok();
    let value_parsed = value.unwrap().parse::<u64>();

    match (ts_ok, user_ok, value_parsed) {
        (true, true, Ok(v)) => {
            stats.records += 1;
            stats.value_sum += v;
        }
        _ => {
            stats.malformed += 1;
        }
    }
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let reader = stdin.lock();

    let mut stats = Stats::default();
    let mut buf = String::with_capacity(64 * 1024);

    let mut lines = reader.lines();

    while let Some(line_result) = lines.next() {
        buf.clear();
        match line_result {
            Ok(line) => {
                buf.push_str(&line);
                parse_line(&buf, &mut stats);
            }
            Err(_) => {
                stats.malformed += 1;
            }
        }
    }

    println!("records={}", stats.records);
    println!("malformed={}", stats.malformed);
    println!("value_sum={}", stats.value_sum);

    Ok(())
}
```

