use std::io::{self, BufRead};

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut reader = io::BufReader::with_capacity(1024 * 1024, stdin.lock());

    let mut buf = Vec::with_capacity(1024 * 1024);
    let mut carry = Vec::new();

    let mut total_bytes: u64 = 0;
    let mut total_records: u64 = 0;
    let mut total_fields: u64 = 0;

    loop {
        buf.clear();
        let bytes_read = reader.read_until(b'\n', &mut buf)?;

        if bytes_read == 0 {
            if !carry.is_empty() {
                total_records += 1;
                total_fields += count_fields(&carry) as u64;
                total_bytes += carry.len() as u64;
                carry.clear();
            }
            break;
        }

        if carry.is_empty() {
            if buf.ends_with(b"\n") {
                total_records += 1;
                total_fields += count_fields(trim_newline(&buf)) as u64;
                total_bytes += buf.len() as u64;
            } else {
                carry.extend_from_slice(&buf);
            }
        } else {
            carry.extend_from_slice(&buf);
            if carry.ends_with(b"\n") {
                total_records += 1;
                total_fields += count_fields(trim_newline(&carry)) as u64;
                total_bytes += carry.len() as u64;
                carry.clear();
            }
        }
    }

    eprintln!("records: {}", total_records);
    eprintln!("bytes: {}", total_bytes);
    eprintln!("fields: {}", total_fields);

    Ok(())
}

fn trim_newline(line: &[u8]) -> &[u8] {
    if line.ends_with(b"\r\n") {
        &line[..line.len() - 2]
    } else if line.ends_with(b"\n") {
        &line[..line.len() - 1]
    } else {
        line
    }
}

fn count_fields(line: &[u8]) -> usize {
    if line.is_empty() {
        return 0;
    }

    let mut fields = 1;
    for &b in line {
        if b == b',' {
            fields += 1;
        }
    }
    fields
}
