use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader};

#[derive(Default, Debug)]
struct Stats {
    records: u64,
    bad_records: u64,
    total_value: i64,
}

fn parse_line(line: &str) -> Option<(u64, u64, i64)> {
    let mut parts = line.trim_end().split(',');

    let ts = parts.next()?.parse::<u64>().ok()?;
    let user_id = parts.next()?.parse::<u64>().ok()?;
    let value = parts.next()?.parse::<i64>().ok()?;

    // Reject extra columns
    if parts.next().is_some() {
        return None;
    }

    Some((ts, user_id, value))
}

fn process_reader<R: BufRead>(reader: R) -> io::Result<Stats> {
    let mut stats = Stats::default();
    let mut buf = String::with_capacity(1024);

    let mut reader = reader;
    loop {
        buf.clear();
        let n = reader.read_line(&mut buf)?;
        if n == 0 {
            break;
        }

        match parse_line(&buf) {
            Some((_ts, _user_id, value)) => {
                stats.records += 1;
                stats.total_value += value;
            }
            None => {
                stats.bad_records += 1;
            }
        }
    }

    Ok(stats)
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    let stats = if args.len() > 1 {
        let file = File::open(&args[1])?;
        let reader = BufReader::with_capacity(1024 * 1024, file); // 1 MiB buffer
        process_reader(reader)?
    } else {
        let stdin = io::stdin();
        let reader = stdin.lock();
        let reader = BufReader::with_capacity(1024 * 1024, reader);
        process_reader(reader)?
    };

    println!("records={}", stats.records);
    println!("bad_records={}", stats.bad_records);
    println!("total_value={}", stats.total_value);

    Ok(())
}
