    let stdin = io::stdin();
    let mut reader = BufReader::with_capacity(BUF_SIZE, stdin.lock());

    let mut buf = [0u8; BUF_SIZE];
    let mut carry = Vec::<u8>::with_capacity(1024);

    let mut total_bytes: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut lines_with_a: u64 = 0;

    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }

        total_bytes += n as u64;

        let chunk = &buf[..n];
        let mut start = 0;

        for i in 0..chunk.len() {
            if chunk[i] == b'\n' {
                total_lines += 1;

                let line_has_a = if carry.is_empty() {
                    chunk[start..i].contains(&b'a')
                } else {
                    carry.extend_from_slice(&chunk[start..i]);
                    let has_a = carry.contains(&b'a');
                    carry.clear();
                    has_a
                };

                if line_has_a {
                    lines_with_a += 1;
                }

                start = i + 1;
            }
        }

        if start < chunk.len() {
            carry.extend_from_slice(&chunk[start..]);
        }
    }

    if !carry.is_empty() {
        total_lines += 1;
        if carry.contains(&b'a') {
            lines_with_a += 1;
        }
    }

    println!("total_bytes={}", total_bytes);
    println!("total_lines={}", total_lines);
    println!("lines_with_a={}", lines_with_a);

    Ok(())
}
```

