```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <limits.h>
#include <errno.h>
#include <signal.h>

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int rotate_logs(const char *log_path, int max_files) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    for (int i = max_files - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", log_path, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", log_path, i + 1);

        if (i == max_files - 1 && file_exists(old_path)) {
            if (unlink(old_path) != 0) {
                perror("unlink");
                return -1;
            }
        }

        if (file_exists(old_path)) {
            if (rename(old_path, new_path) != 0) {
                perror("rename");
                return -1;
            }
        }
    }

    snprintf(new_path, sizeof(new_path), "%s.1", log_path);
    if (file_exists(log_path)) {
        if (rename(log_path, new_path) != 0) {
            perror("rename current log");
            return -1;
        }
    }

    FILE *fp = fopen(log_path, "a");
    if (!fp) {
        perror("fopen new log");
        return -1;
    }
    fclose(fp);
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(0);

    if (chdir("/") != 0) return -1;

    fclose(stdin);
    fclose(stdout);
    fclose(stderr);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <log_path> <max_size_bytes> <max_rotated_files> <poll_seconds> [--daemon]\n",
        prog);
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    off_t max_size = atoll(argv[2]);
    int max_files = atoi(argv[3]);
    int poll_seconds = atoi(argv[4]);
    int run_as_daemon = (argc > 5 && strcmp(argv[5], "--daemon") == 0);

    if (max_size <= 0 || max_files <= 0 || poll_seconds <= 0) {
        usage(argv[0]);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (run_as_daemon) {
        if (daemonize() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (running) {
        off_t sz = file_size(log_path);
        if (sz >= 0 && sz >= max_size) {
            if (rotate_logs(log_path, max_files) != 0) {
                sleep(poll_seconds);
                continue;
            }
        }
        sleep(poll_seconds);
    }

    return 0;
}
```

