## Example: minimal Rust log rotator

```rust
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

#[derive(Debug, Clone)]
struct Config {
    log_path: PathBuf,
    max_size_bytes: u64,
    keep_files: usize,
    poll_interval: Duration,
}

fn rotate_logs(path: &Path, keep_files: usize) -> io::Result<()> {
    let base = path.to_string_lossy().to_string();

    let oldest = format!("{}.{}", base, keep_files);
    if Path::new(&oldest).exists() {
        let _ = fs::remove_file(&oldest);
    }

    for i in (1..keep_files).rev() {
        let src = format!("{}.{}", base, i);
        let dst = format!("{}.{}", base, i + 1);
        if Path::new(&src).exists() {
            let _ = fs::rename(&src, &dst);
        }
    }

    if path.exists() {
        let first = format!("{}.1", base);
        fs::rename(path, first)?;
        let _ = fs::File::create(path)?;
    }

    Ok(())
}

fn maybe_rotate(cfg: &Config) -> io::Result<()> {
    if !cfg.log_path.exists() {
        let _ = fs::File::create(&cfg.log_path)?;
        return Ok(());
    }

    let metadata = fs::metadata(&cfg.log_path)?;
    if metadata.len() >= cfg.max_size_bytes {
        rotate_logs(&cfg.log_path, cfg.keep_files)?;
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let cfg = Config {
        log_path: PathBuf::from("/var/log/myapp.log"),
        max_size_bytes: 10 * 1024 * 1024,
        keep_files: 5,
        poll_interval: Duration::from_secs(5),
    };

    loop {
        if let Err(e) = maybe_rotate(&cfg) {
            eprintln!("log rotation error: {e}");
        }
        thread::sleep(cfg.poll_interval);
    }
}
```

