Below is a minimal, single-file <language>C</language> implementation of a memory-constrained log rotation daemon. It:

- Watches one log file path
- Periodically checks size
- Rotates when size exceeds a threshold
- Keeps a fixed number of rotated files
- Uses low, predictable memory
- Can optionally set strict address-space and data-segment limits via `setrlimit`
- Avoids dynamic allocation in the main path

If you want, I can also provide a safer <language>Rust</language> version afterward.

```c
/*
 * memlogd.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Features:
 * - Polls a target log file periodically
 * - Rotates when file size exceeds max_bytes
 * - Keeps rotate_count archives: logfile.1 ... logfile.N
 * - Optionally daemonizes
 * - Optionally enforces memory limits with setrlimit()
 * - Uses fixed-size buffers, no heap allocation in normal operation
 *
 * Build:
 *   cc -O2 -std=c11 -Wall -Wextra -pedantic -o memlogd memlogd.c
 *
 * Example:
 *   ./memlogd -f /var/log/myapp.log -s 10485760 -n 5 -i 2 -m 16777216 -d
 *
 * Notes:
 * - This is intended for Unix-like systems.
 * - Rotation is done by rename(); writers must reopen the log file if they
 *   don't keep appending to the old inode.
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_terminate = 0;

static void on_signal(int signo) {
    (void)signo;
    g_terminate = 1;
}

typedef struct {
    char logfile[PATH_MAX];
    off_t max_bytes;
    int rotate_count;
    unsigned interval_sec;
    int daemonize;
    rlim_t mem_limit_bytes; /* 0 = disabled */
} config_t;

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int parse_ll(const char *s, long long *out) {
    char *end = NULL;
    errno = 0;
    long long v = strtoll(s, &end, 10);
    if (errno || !end || *end != '\0') return -1;
    *out = v;
    return 0;
}

static int parse_ull(const char *s, unsigned long long *out) {
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno || !end || *end != '\0') return -1;
    *out = v;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f LOGFILE -s MAX_BYTES [-n ROTATIONS] [-i INTERVAL_SEC] [-m MEM_BYTES] [-d]\n"
        "  -f LOGFILE        Path to log file\n"
        "  -s MAX_BYTES      Rotate when file size exceeds this value\n"
        "  -n ROTATIONS      Number of rotated files to keep (default: 5)\n"
        "  -i INTERVAL_SEC   Poll interval in seconds (default: 5)\n"
        "  -m MEM_BYTES      Set RLIMIT_AS and RLIMIT_DATA to this value\n"
        "  -d                Daemonize\n",
        prog
    );
}

static int parse_args(int argc, char **argv, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->rotate_count = 5;
    cfg->interval_sec = 5;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:m:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg->logfile, sizeof(cfg->logfile), "%s", optarg) >= (int)sizeof(cfg->logfile)) {
                    log_stderr("log file path too long");
                    return -1;
                }
                break;
            case 's': {
                long long v;
                if (parse_ll(optarg, &v) != 0 || v <= 0) {
                    log_stderr("invalid max size");
                    return -1;
                }
                cfg->max_bytes = (off_t)v;
                break;
            }
            case 'n': {
                long long v;
                if (parse_ll(optarg, &v) != 0 || v < 1 || v > 1000) {
                    log_stderr("invalid rotation count");
                    return -1;
                }
                cfg->rotate_count = (int)v;
                break;
            }
            case 'i': {
                unsigned long long v;
                if (parse_ull(optarg, &v) != 0 || v == 0 || v > 86400ULL) {
                    log_stderr("invalid interval");
                    return -1;
                }
                cfg->interval_sec = (unsigned)v;
                break;
            }
            case 'm': {
                unsigned long long v;
                if (parse_ull(optarg, &v) != 0 || v < 1024 * 1024ULL) {
                    log_stderr("invalid memory limit");
                    return -1;
                }
                cfg->mem_limit_bytes = (rlim_t)v;
                break;
            }
            case 'd':
                cfg->daemonize = 1;
                break;
            default:
                usage(argv[0]);
                return -1;
        }
    }

    if (cfg->logfile[0] == '\0' || cfg->max_bytes <= 0) {
        usage(argv[0]);
        return -1;
    }

    return 0;
}

static int apply_memory_limit(rlim_t bytes) {
    if (bytes == 0) return 0;

    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;

    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        perror("setrlimit(RLIMIT_AS)");
        return -1;
    }
#ifdef RLIMIT_DATA
    if (setrlimit(RLIMIT_DATA, &rl) != 0) {
        perror("setrlimit(RLIMIT_DATA)");
        return -1;
    }
#endif
    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int build_rotated_path(const char *base, int idx, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, idx);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_logfile_exists(const char *path) {
    int fd = open(path, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->rotate_count > 0) {
        if (build_rotated_path(cfg->logfile, cfg->rotate_count, oldp, sizeof(oldp)) != 0)
            return -1;
        (void)unlink(oldp);
    }

    for (int i = cfg->rotate_count - 1; i >= 1; --i) {
        if (build_rotated_path(cfg->logfile, i, oldp, sizeof(oldp)) != 0)
            return -1;
        if (build_rotated_path(cfg->logfile, i + 1, newp, sizeof(newp)) != 0)
            return -1;

        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) return -1;
        }
    }

    if (build_rotated_path(cfg->logfile, 1, newp, sizeof(newp)) != 0)
        return -1;

    if (rename(cfg->logfile, newp) != 0) {
        if (errno != ENOENT) return -1;
    }

    if (ensure_logfile_exists(cfg->logfile) != 0)
        return -1;

    return 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) != 0) return -1;
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;

    if (parse_args(argc, argv, &cfg) != 0)
        return 2;

    if (install_signals() != 0) {
        perror("sigaction");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_self() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    if (apply_memory_limit(cfg.mem_limit_bytes) != 0)
        return 1;

    if (ensure_logfile_exists(cfg.logfile) != 0) {
        perror("ensure_logfile_exists");
        return 1;
    }

    while (!g_terminate) {
        off_t sz = 0;
        if (file_size(cfg.logfile, &sz) == 0) {
            if (sz >= cfg.max_bytes) {
                if (rotate_logs(&cfg) != 0) {
                    /* In daemon mode stderr may go to /dev/null; intentional minimalism */
                    perror("rotate_logs");
                }
            }
        } else {
            perror("stat");
        }

        struct timespec ts;
        ts.tv_sec = cfg.interval_sec;
        ts.tv_nsec = 0;

        while (!g_terminate && nanosleep(&ts, &ts) != 0) {
            if (errno != EINTR) break;
        }
    }

    return 0;
}
```

