}

static int ensure_log_exists(const struct config *cfg) {
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_rotations > 0) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->max_rotations) == 0) {
            unlink(oldp);
        }
    }

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) != 0) {
            return -1;
        }
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) != 0) {
            return -1;
        }
        if (rename(oldp, newp) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (cfg->max_rotations > 0) {
        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) != 0) {
            return -1;
        }
        if (rename(cfg->log_path, newp) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    } else {
        if (unlink(cfg->log_path) != 0 && errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int should_rotate(const struct config *cfg, int *result) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            *result = 0;
            return 0;
        }
        return -1;
    }

    *result = (st.st_size >= cfg->max_size) ? 1 : 0;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    memset(&cfg, 0, sizeof(cfg));

    cfg.max_size = DEFAULT_MAX_SIZE_BYTES;
    cfg.max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg.check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg.create_mode = 0644;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:i:m:")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    fprintf(stderr, "log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_off_t(optarg, &cfg.max_size) != 0) {
                    fprintf(stderr, "invalid max size: %s\n", optarg);
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.max_rotations) != 0 || cfg.max_rotations < 0) {
                    fprintf(stderr, "invalid max rotations: %s\n", optarg);
                    return 1;
                }
                break;
            case 'i': {
                int v;
                if (parse_int(optarg, &v) != 0 || v <= 0) {
                    fprintf(stderr, "invalid interval: %s\n", optarg);
                    return 1;
                }
                cfg.check_interval_sec = (unsigned int)v;
                break;
            }
            case 'm': {
                char *end = NULL;
                errno = 0;
                long v = strtol(optarg, &end, 8);
                if (errno != 0 || end == optarg || *end != '\0' || v < 0 || v > 0777) {
                    fprintf(stderr, "invalid mode: %s\n", optarg);
                    return 1;
                }
                cfg.create_mode = (int)v;
                break;
            }
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    install_signal_handlers();

    if (ensure_log_exists(&cfg) != 0) {
        perror("ensure_log_exists");
        return 1;
    }

    while (!g_stop) {
        int rotate = 0;
        if (should_rotate(&cfg, &rotate) != 0) {
            perror("stat");
        } else if (rotate) {
            if (rotate_logs(&cfg) != 0) {
                perror("rotate_logs");
            }
        }

        struct timespec ts;
        ts.tv_sec = cfg.check_interval_sec;
        ts.tv_nsec = 0;

        while (!g_stop && nanosleep(&ts, &ts) != 0) {
            if (errno != EINTR) {
                break;
            }
        }
    }

    return 0;
}
