# Source: `minilogd.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_ROTATIONS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)
#define DEFAULT_UMASK 022

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int max_rotations;
    unsigned int check_interval_sec;
    int daemonize;
    rlim_t memory_limit_bytes;
};

static int g_use_syslog = 0;

static void log_msg(int priority, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);

    if (g_use_syslog) {
        vsyslog(priority, fmt, ap);
    } else {
        FILE *out = (priority <= LOG_ERR) ? stderr : stdout;
        vfprintf(out, fmt, ap);
        fputc('\n', out);
        fflush(out);
    }

    va_end(ap);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s --log PATH [options]\n"
        "Options:\n"
        "  --log PATH               Log file to monitor\n"
        "  --max-size BYTES         Rotate when file size exceeds BYTES\n"
        "  --rotations N            Number of rotated files to keep\n"
        "  --interval SEC           Poll interval in seconds\n"
        "  --daemon                 Run as a daemon\n"
        "  --mem-limit BYTES        Set RLIMIT_AS to BYTES\n"
        "  --help                   Show this help\n",
        prog);
}

static int parse_long_long(const char *s, long long *out) {
    char *end = NULL;
    errno = 0;
    long long v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') {
        return -1;
    }
    *out = v;
    return 0;
}

static int set_memory_limit(rlim_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    if (setrlimit(RLIMIT_AS, &rl) != 0) {
        return -1;
    }
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;
    umask(DEFAULT_UMASK);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int build_rotated_path(char *dst, size_t dst_sz, const char *base, int index) {
    int n = snprintf(dst, dst_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    if (cfg->max_rotations <= 0) {
        return 0;
    }

    if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) != 0) {
        return -1;
    }

    (void)unlink(old_path);

    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_rotated_path(old_path, sizeof(old_path), cfg->log_path, i) != 0) {
            return -1;
        }
        if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, i + 1) != 0) {
            return -1;
        }

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) {
                log_msg(LOG_ERR, "rename(%s -> %s) failed: %s",
                        old_path, new_path, strerror(errno));
                return -1;
            }
        }
    }

    if (build_rotated_path(new_path, sizeof(new_path), cfg->log_path, 1) != 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        log_msg(LOG_ERR, "rename(%s -> %s) failed: %s",
                cfg->log_path, new_path, strerror(errno));
        return -1;
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        log_msg(LOG_ERR, "failed to create new log file %s: %s",
                cfg->log_path, strerror(errno));
        return -1;
    }

    close(fd);
    log_msg(LOG_INFO, "rotated log: %s", cfg->log_path);
    return 0;
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        log_msg(LOG_ERR, "stat(%s) failed: %s", cfg->log_path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg(LOG_ERR, "%s is not a regular file", cfg->log_path);
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->max_size = DEFAULT_MAX_SIZE;
    cfg->max_rotations = DEFAULT_MAX_ROTATIONS;
    cfg->check_interval_sec = DEFAULT_CHECK_INTERVAL_SEC;
    cfg->daemonize = 0;
    cfg->memory_limit_bytes = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--log") == 0) {
            if (++i >= argc) return -1;
            if (snprintf(cfg->log_path, sizeof(cfg->log_path), "%s", argv[i]) >= (int)sizeof(cfg->log_path)) {
                errno = ENAMETOOLONG;
                return -1;
            }
        } else if (strcmp(argv[i], "--max-size") == 0) {
            long long v;
            if (++i >= argc || parse_long_long(argv[i], &v) != 0 || v <= 0) return -1;
            cfg->max_size = (off_t)v;
        } else if (strcmp(argv[i], "--rotations") == 0) {
            long long v;
            if (++i >= argc || parse_long_long(argv[i], &v) != 0 || v < 0 || v > 1000) return -1;
            cfg->max_rotations = (int)v;
        } else if (strcmp(argv[i], "--interval") == 0) {
            long long v;
            if (++i >= argc || parse_long_long(argv[i], &v) != 0 || v <= 0 || v > 86400) return -1;
            cfg->check_interval_sec = (unsigned int)v;
        } else if (strcmp(argv[i], "--daemon") == 0) {
            cfg->daemonize = 1;
        } else if (strcmp(argv[i], "--mem-limit") == 0) {
            long long v;
            if (++i >= argc || parse_long_long(argv[i], &v) != 0 || v <= 0) return -1;
            cfg->memory_limit_bytes = (rlim_t)v;
        } else if (strcmp(argv[i], "--help") == 0) {
            usage(argv[0]);
            exit(0);
        } else {
            return -1;
        }
    }

    if (cfg->log_path[0] == '\0') {
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 2;
    }

    if (cfg.memory_limit_bytes > 0) {
        if (set_memory_limit(cfg.memory_limit_bytes) != 0) {
            fprintf(stderr, "failed to set memory limit: %s\n", strerror(errno));
            return 1;
        }
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            fprintf(stderr, "failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
        openlog("minilogd", LOG_PID | LOG_NDELAY, LOG_DAEMON);
        g_use_syslog = 1;
    }

    log_msg(LOG_INFO,
            "starting: log=%s max_size=%lld rotations=%d interval=%u mem_limit=%llu",
            cfg.log_path,
            (long long)cfg.max_size,
            cfg.max_rotations,
            cfg.check_interval_sec,
            (unsigned long long)cfg.memory_limit_bytes);

    for (;;) {
        if (check_and_rotate(&cfg) != 0) {
            /* Keep running; transient failures may resolve */
        }
        sleep(cfg.check_interval_sec);
    }

    return 0;
}
