#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_POLL_SECONDS 5
#define DEFAULT_ROTATIONS 5
#define DEFAULT_MODE 0640

static volatile sig_atomic_t g_terminate = 0;

static void on_signal(int signo) {
    (void)signo;
    g_terminate = 1;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

typedef struct Config {
    char log_path[PATH_MAX];
    off_t max_size;
    int rotations;
    int poll_seconds;
    mode_t create_mode;
    bool daemonize;
} Config;

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> -s <max_bytes> [-n rotations] [-p poll_seconds] [-m octal_mode] [-d]\n"
        "  -f <logfile>      Path to active log file\n"
        "  -s <max_bytes>    Rotate when file size >= this value\n"
        "  -n <rotations>    Number of rotated files to keep (default: %d)\n"
        "  -p <seconds>      Poll interval in seconds (default: %d)\n"
        "  -m <octal_mode>   Mode for new log file (default: 0640)\n"
        "  -d                Daemonize\n",
        prog, DEFAULT_ROTATIONS, DEFAULT_POLL_SECONDS
    );
}

static int parse_octal_mode(const char *s, mode_t *out) {
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 8);
    if (errno != 0 || end == s || *end != '\0' || v > 07777UL) {
        return -1;
    }
    *out = (mode_t)v;
    return 0;
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v < 0 || v > INT32_MAX) {
        return -1;
    }
    *out = (int)v;
    return 0;
}

static int parse_off_t(const char *s, off_t *out) {
    char *end = NULL;
    errno = 0;
    long long v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v < 0) {
        return -1;
    }
    *out = (off_t)v;
    return 0;
}

static int make_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int rc = snprintf(out, out_sz, "%s.%d", base, index);
    if (rc < 0 || (size_t)rc >= out_sz) {
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const Config *cfg) {
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const Config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    for (int i = cfg->rotations - 1; i >= 1; --i) {
        if (make_rotated_path(cfg->log_path, i, old_path, sizeof(old_path)) != 0 ||
            make_rotated_path(cfg->log_path, i + 1, new_path, sizeof(new_path)) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    }

    if (cfg->rotations >= 1) {
        if (make_rotated_path(cfg->log_path, 1, new_path, sizeof(new_path)) != 0) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (rename(cfg->log_path, new_path) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    } else {
        if (unlink(cfg->log_path) != 0 && errno != ENOENT) {
            return -1;
        }
    }

    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int maybe_rotate(const Config *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) != 0) {
        if (errno == ENOENT) {
            return ensure_log_exists(cfg);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") != 0) {
        return -1;
    }

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    if (dup2(fd, STDIN_FILENO) < 0 ||
        dup2(fd, STDOUT_FILENO) < 0 ||
        dup2(fd, STDERR_FILENO) < 0) {
        close(fd);
        return -1;
    }

    if (fd > STDERR_FILENO) {
        close(fd);
    }

    return 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) != 0) return -1;
    return 0;
}

int main(int argc, char **argv) {
    Config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.rotations = DEFAULT_ROTATIONS;
    cfg.poll_seconds = DEFAULT_POLL_SECONDS;
    cfg.create_mode = DEFAULT_MODE;
    cfg.daemonize = false;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:n:p:m:d")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    log_stderr("log path too long");
                    return 1;
                }
                break;
            case 's':
                if (parse_off_t(optarg, &cfg.max_size) != 0 || cfg.max_size <= 0) {
                    log_stderr("invalid max size: %s", optarg);
                    return 1;
                }
                break;
            case 'n':
                if (parse_int(optarg, &cfg.rotations) != 0 || cfg.rotations < 0 || cfg.rotations > 1000) {
                    log_stderr("invalid rotations: %s", optarg);
                    return 1;
                }
                break;
            case 'p':
                if (parse_int(optarg, &cfg.poll_seconds) != 0 || cfg.poll_seconds <= 0 || cfg.poll_seconds > 86400) {
                    log_stderr("invalid poll interval: %s", optarg);
                    return 1;
                }
                break;
            case 'm':
                if (parse_octal_mode(optarg, &cfg.create_mode) != 0) {
                    log_stderr("invalid mode: %s", optarg);
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = true;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0' || cfg.max_size <= 0) {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() != 0) {
        log_stderr("failed to install signal handlers: %s", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() != 0) {
            log_stderr("failed to daemonize: %s", strerror(errno));
            return 1;
        }
    }

    if (ensure_log_exists(&cfg) != 0) {
        log_stderr("failed to create log file %s: %s", cfg.log_path, strerror(errno));
        return 1;
    }

    while (!g_terminate) {
        if (maybe_rotate(&cfg) != 0) {
            log_stderr("rotation check failed for %s: %s", cfg.log_path, strerror(errno));
        }

        for (int i = 0; i < cfg.poll_seconds && !g_terminate; ++i) {
            sleep(1);
        }
    }

    return 0;
}
