## Source: `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_BACKUPS 16
#define DEFAULT_SLEEP_SECS 5

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    off_t rotate_size;
    int max_backups;
    unsigned sleep_secs;
    int daemonize;
    mode_t create_mode;
};

static void on_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static void die(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
    exit(1);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> -s <rotate_size_bytes> [-n backups] [-t sleep_secs] [-d] [-m octal_mode]\n"
        "  -f logfile            Path to log file\n"
        "  -s rotate_size_bytes  Rotate when file size >= this value\n"
        "  -n backups            Number of rotated files to keep (default: 5, max: %d)\n"
        "  -t sleep_secs         Poll interval in seconds (default: %d)\n"
        "  -d                    Daemonize\n"
        "  -m octal_mode         Mode for newly created log file (default: 0644)\n",
        prog, MAX_BACKUPS, DEFAULT_SLEEP_SECS);
}

static int parse_octal_mode(const char *s, mode_t *out) {
    char *end = NULL;
    unsigned long v = strtoul(s, &end, 8);
    if (!s[0] || (end && *end != '\0') || v > 0777) {
        return -1;
    }
    *out = (mode_t)v;
    return 0;
}

static int path_with_suffix(char *dst, size_t dstsz, const char *base, int suffix) {
    int n = snprintf(dst, dstsz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= dstsz) {
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const struct config *cfg) {
    int fd = open(cfg->log_path, O_CREAT | O_APPEND | O_WRONLY, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->max_backups > 0) {
        if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, cfg->max_backups) != 0) {
            return -1;
        }
        unlink(oldp);

        for (int i = cfg->max_backups - 1; i >= 1; --i) {
            if (path_with_suffix(oldp, sizeof(oldp), cfg->log_path, i) != 0) {
                return -1;
            }
            if (path_with_suffix(newp, sizeof(newp), cfg->log_path, i + 1) != 0) {
                return -1;
            }
            if (rename(oldp, newp) != 0) {
                if (errno != ENOENT) {
                    return -1;
                }
            }
        }

        if (path_with_suffix(newp, sizeof(newp), cfg->log_path, 1) != 0) {
            return -1;
        }
        if (rename(cfg->log_path, newp) != 0) {
            if (errno != ENOENT) {
                return -1;
            }
        }
    } else {
        if (unlink(cfg->log_path) != 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (ensure_log_exists(cfg) != 0) {
        return -1;
    }

    return 0;
}

static int daemonize_self(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int parse_args(int argc, char **argv, struct config *cfg) {
    int opt;

    memset(cfg, 0, sizeof(*cfg));
    cfg->max_backups = 5;
    cfg->sleep_secs = DEFAULT_SLEEP_SECS;
    cfg->create_mode = 0644;

    while ((opt = getopt(argc, argv, "f:s:n:t:dm:")) != -1) {
        switch (opt) {
            case 'f':
                if (strlen(optarg) >= sizeof(cfg->log_path)) {
                    return -1;
                }
                strcpy(cfg->log_path, optarg);
                break;
            case 's': {
                char *end = NULL;
                long long v = strtoll(optarg, &end, 10);
                if (!optarg[0] || (end && *end != '\0') || v <= 0) {
                    return -1;
                }
                cfg->rotate_size = (off_t)v;
                break;
            }
            case 'n': {
                char *end = NULL;
                long v = strtol(optarg, &end, 10);
                if (!optarg[0] || (end && *end != '\0') || v < 0 || v > MAX_BACKUPS) {
                    return -1;
                }
                cfg->max_backups = (int)v;
                break;
            }
            case 't': {
                char *end = NULL;
                unsigned long v = strtoul(optarg, &end, 10);
                if (!optarg[0] || (end && *end != '\0') || v == 0) {
                    return -1;
                }
                cfg->sleep_secs = (unsigned)v;
                break;
            }
            case 'd':
                cfg->daemonize = 1;
                break;
            case 'm':
                if (parse_octal_mode(optarg, &cfg->create_mode) != 0) {
                    return -1;
                }
                break;
            default:
                return -1;
        }
    }

    if (cfg->log_path[0] == '\0' || cfg->rotate_size <= 0) {
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    struct sigaction sa;
    off_t sz;

    if (parse_args(argc, argv, &cfg) != 0) {
        usage(argv[0]);
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (ensure_log_exists(&cfg) != 0) {
        die("failed to create/open log file '%s': %s", cfg.log_path, strerror(errno));
    }

    if (cfg.daemonize) {
        if (daemonize_self() != 0) {
            die("failed to daemonize: %s", strerror(errno));
        }
    }

    while (g_running) {
        if (file_size(cfg.log_path, &sz) == 0) {
            if (sz >= cfg.rotate_size) {
                if (rotate_logs(&cfg) != 0) {
                    /* In a stricter production daemon, send to syslog instead. */
                }
            }
        } else {
            if (errno == ENOENT) {
                ensure_log_exists(&cfg);
            }
        }

        sleep(cfg.sleep_secs);
    }

    return 0;
}
