```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define DEFAULT_MAX_BYTES (10 * 1024 * 1024)
#define DEFAULT_KEEP 5
#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_PIDFILE "/tmp/logrotated.pid"

static volatile sig_atomic_t g_terminate = 0;

typedef struct {
    char log_path[PATH_MAX];
    char pidfile[PATH_MAX];
    off_t max_bytes;
    int keep;
    int interval_sec;
    int daemonize;
    int verbose;
    mode_t create_mode;
} config_t;

static void on_signal(int signo) {
    (void)signo;
    g_terminate = 1;
}

static void log_msg(int verbose, const char *fmt, ...) {
    if (!verbose) return;

    va_list ap;
    va_start(ap, fmt);

    char buf[512];
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);

    if (n > 0) {
        if (n >= (int)sizeof(buf)) {
            buf[sizeof(buf) - 2] = '\n';
            buf[sizeof(buf) - 1] = '\0';
        }
        write(STDERR_FILENO, buf, strnlen(buf, sizeof(buf)));
    }
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s -f LOG_PATH [options]\n"
        "Options:\n"
        "  -f PATH   Log file path (required)\n"
        "  -s BYTES  Rotate when file size exceeds BYTES (default: %d)\n"
        "  -k COUNT  Number of rotated files to keep (default: %d)\n"
        "  -i SEC    Poll interval in seconds (default: %d)\n"
        "  -p PATH   Pidfile path (default: %s)\n"
        "  -m OCTAL  Mode for newly created log file (default: 0644)\n"
        "  -d        Daemonize\n"
        "  -v        Verbose logging\n",
        prog, DEFAULT_MAX_BYTES, DEFAULT_KEEP, DEFAULT_INTERVAL_SEC, DEFAULT_PIDFILE);
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v < INT32_MIN || v > INT32_MAX) return -1;
    *out = (int)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v < 0) return -1;
    *out = (off_t)v;
    return 0;
}

static int parse_octal_mode(const char *s, mode_t *out) {
    char *end = NULL;
    unsigned long v = strtoul(s, &end, 8);
    if (!s || *s == '\0' || !end || *end != '\0') return -1;
    if (v > 0777) return -1;
    *out = (mode_t)v;
    return 0;
}

static int write_pidfile(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;

    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%ld\n", (long)getpid());
    if (len < 0 || len >= (int)sizeof(buf)) {
        close(fd);
        return -1;
    }

    ssize_t wr = write(fd, buf, (size_t)len);
    close(fd);
    return (wr == len) ? 0 : -1;
}

static void remove_pidfile(const char *path) {
    unlink(path);
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int build_rotated_path(const char *base, int index, char *out, size_t out_sz) {
    int n = snprintf(out, out_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= out_sz) return -1;
    return 0;
}

static int ensure_log_exists(const char *path, mode_t mode, int verbose) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, mode);
    if (fd < 0) {
        log_msg(verbose, "failed to create/open log file %s: %s\n", path, strerror(errno));
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];

    if (cfg->keep > 0) {
        if (build_rotated_path(cfg->log_path, cfg->keep, oldp, sizeof(oldp)) < 0) {
            log_msg(cfg->verbose, "path too long during rotation\n");
            return -1;
        }
        unlink(oldp);

        for (int i = cfg->keep - 1; i >= 1; --i) {
            if (build_rotated_path(cfg->log_path, i, oldp, sizeof(oldp)) < 0) return -1;
            if (build_rotated_path(cfg->log_path, i + 1, newp, sizeof(newp)) < 0) return -1;

            if (rename(oldp, newp) < 0 && errno != ENOENT) {
                log_msg(cfg->verbose, "rename %s -> %s failed: %s\n", oldp, newp, strerror(errno));
                return -1;
            }
        }

        if (build_rotated_path(cfg->log_path, 1, newp, sizeof(newp)) < 0) return -1;
        if (rename(cfg->log_path, newp) < 0) {
            if (errno != ENOENT) {
                log_msg(cfg->verbose, "rename %s -> %s failed: %s\n",
                        cfg->log_path, newp, strerror(errno));
                return -1;
            }
        }
    } else {
        if (unlink(cfg->log_path) < 0 && errno != ENOENT) {
            log_msg(cfg->verbose, "unlink %s failed: %s\n", cfg->log_path, strerror(errno));
            return -1;
        }
    }

    if (ensure_log_exists(cfg->log_path, cfg->create_mode, cfg->verbose) < 0) {
        return -1;
    }

    log_msg(cfg->verbose, "rotated log: %s\n", cfg->log_path);
    return 0;
}

static int maybe_rotate(const config_t *cfg) {
    struct stat st;
    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_log_exists(cfg->log_path, cfg->create_mode, cfg->verbose);
        }
        log_msg(cfg->verbose, "stat failed on %s: %s\n", cfg->log_path, strerror(errno));
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        log_msg(cfg->verbose, "%s is not a regular file\n", cfg->log_path);
        return -1;
    }

    if (st.st_size >= cfg->max_bytes) {
        return rotate_logs(cfg);
    }

    return 0;
}

static int install_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    signal(SIGPIPE, SIG_IGN);
    return 0;
}

int main(int argc, char **argv) {
    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    cfg.max_bytes = DEFAULT_MAX_BYTES;
    cfg.keep = DEFAULT_KEEP;
    cfg.interval_sec = DEFAULT_INTERVAL_SEC;
    cfg.daemonize = 0;
    cfg.verbose = 0;
    cfg.create_mode = 0644;

    {
        int n = snprintf(cfg.pidfile, sizeof(cfg.pidfile), "%s", DEFAULT_PIDFILE);
        if (n < 0 || n >= (int)sizeof(cfg.pidfile)) {
            dprintf(STDERR_FILENO, "pidfile path too long\n");
            return 1;
        }
    }

    int opt;
    while ((opt = getopt(argc, argv, "f:s:k:i:p:m:dv")) != -1) {
        switch (opt) {
            case 'f':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    dprintf(STDERR_FILENO, "log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_offt(optarg, &cfg.max_bytes) < 0 || cfg.max_bytes <= 0) {
                    dprintf(STDERR_FILENO, "invalid size: %s\n", optarg);
                    return 1;
                }
                break;
            case 'k':
                if (parse_int(optarg, &cfg.keep) < 0 || cfg.keep < 0 || cfg.keep > 1000) {
                    dprintf(STDERR_FILENO, "invalid keep count: %s\n", optarg);
                    return 1;
                }
                break;
            case 'i':
                if (parse_int(optarg, &cfg.interval_sec) < 0 || cfg.interval_sec <= 0) {
                    dprintf(STDERR_FILENO, "invalid interval: %s\n", optarg);
                    return 1;
                }
                break;
            case 'p':
                if (snprintf(cfg.pidfile, sizeof(cfg.pidfile), "%s", optarg) >= (int)sizeof(cfg.pidfile)) {
                    dprintf(STDERR_FILENO, "pidfile path too long\n");
                    return 1;
                }
                break;
            case 'm':
                if (parse_octal_mode(optarg, &cfg.create_mode) < 0) {
                    dprintf(STDERR_FILENO, "invalid mode: %s\n", optarg);
                    return 1;
                }
                break;
            case 'd':
                cfg.daemonize = 1;
                break;
            case 'v':
                cfg.verbose = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0') {
        usage(argv[0]);
        return 1;
    }

    if (install_signals() < 0) {
        dprintf(STDERR_FILENO, "failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            dprintf(STDERR_FILENO, "failed to daemonize: %s\n", strerror(errno));
            return 1;
        }
    }

    if (write_pidfile(cfg.pidfile) < 0) {
        log_msg(1, "failed to write pidfile %s: %s\n", cfg.pidfile, strerror(errno));
        return 1;
    }

    if (ensure_log_exists(cfg.log_path, cfg.create_mode, cfg.verbose) < 0) {
        remove_pidfile(cfg.pidfile);
        return 1;
    }

    while (!g_terminate) {
        if (maybe_rotate(&cfg) < 0) {
            /* keep running; transient errors should not kill daemon */
        }

        struct timespec ts;
        ts.tv_sec = cfg.interval_sec;
        ts.tv_nsec = 0;

        while (!g_terminate && nanosleep(&ts, &ts) < 0 && errno == EINTR) {
        }
    }

    remove_pidfile(cfg.pidfile);
    return 0;
}
