Below is a minimal working log rotation daemon in <language>C</language>, chosen because it gives the smallest, most predictable memory footprint and direct control over Unix syscalls.

It:
- runs in the foreground by default
- polls a target log file periodically
- rotates when size exceeds a limit
- keeps only a fixed number of old files
- uses very little heap memory
- can optionally set strict address-space limits with `setrlimit`

## Features
- Monitors one file, e.g. `/var/log/myapp.log`
- When size >= threshold:
  - removes oldest archive
  - shifts `.N` to `.N+1`
  - renames current log to `.1`
  - creates a fresh empty log file
- Uses fixed-size stack buffers only
- No dynamic allocation required in normal operation

---

## Minimal C implementation

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int set_memory_limit_mb(rlim_t mb) {
    struct rlimit rl;
    rl.rlim_cur = mb * 1024 * 1024;
    rl.rlim_max = mb * 1024 * 1024;
    return setrlimit(RLIMIT_AS, &rl);
}

static int file_size(const char *path, off_t *size_out, mode_t *mode_out, uid_t *uid_out, gid_t *gid_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = st.st_size;
    if (mode_out) *mode_out = st.st_mode & 0777;
    if (uid_out) *uid_out = st.st_uid;
    if (gid_out) *gid_out = st.st_gid;
    return 0;
}

static int make_path(char *buf, size_t buflen, const char *base, int index) {
    int n = snprintf(buf, buflen, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= buflen) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_new_log(const char *path, mode_t mode, uid_t uid, gid_t gid) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (fd < 0) {
        return -1;
    }
    (void)fchown(fd, uid, gid); /* ignore failure if not privileged */
    if (close(fd) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_log(const char *path, int keep) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    off_t sz;
    mode_t mode = 0644;
    uid_t uid = getuid();
    gid_t gid = getgid();

    if (file_size(path, &sz, &mode, &uid, &gid) != 0) {
        return -1;
    }

    if (keep < 1) {
        errno = EINVAL;
        return -1;
    }

    if (make_path(oldp, sizeof(oldp), path, keep) != 0) {
        return -1;
    }
    unlink(oldp);

    for (int i = keep - 1; i >= 1; --i) {
        if (make_path(oldp, sizeof(oldp), path, i) != 0) {
            return -1;
        }
        if (make_path(newp, sizeof(newp), path, i + 1) != 0) {
            return -1;
        }
        if (rename(oldp, newp) != 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (make_path(newp, sizeof(newp), path, 1) != 0) {
        return -1;
    }

    if (rename(path, newp) != 0) {
        return -1;
    }

    if (ensure_new_log(path, mode, uid, gid) != 0) {
        return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> -s <bytes> [-k keep] [-i seconds] [-m mem_mb]\n"
        "  -f <logfile>   Path to log file\n"
        "  -s <bytes>     Rotate when file size >= bytes\n"
        "  -k <keep>      Number of rotated files to keep (default: 5)\n"
        "  -i <seconds>   Poll interval in seconds (default: 5)\n"
        "  -m <mem_mb>    Set RLIMIT_AS memory limit in MB\n",
        prog);
}

int main(int argc, char **argv) {
    const char *logfile = NULL;
    off_t max_size = 0;
    int keep = 5;
    int interval = 5;
    long mem_mb = 0;
    int opt;

    while ((opt = getopt(argc, argv, "f:s:k:i:m:")) != -1) {
        switch (opt) {
            case 'f':
                logfile = optarg;
                break;
            case 's':
                max_size = (off_t)atoll(optarg);
                break;
            case 'k':
                keep = atoi(optarg);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'm':
                mem_mb = atol(optarg);
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (!logfile || max_size <= 0 || keep < 1 || interval < 1) {
        usage(argv[0]);
        return 1;
    }

    if (mem_mb > 0) {
        if (set_memory_limit_mb((rlim_t)mem_mb) != 0) {
            perror("setrlimit");
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!g_stop) {
        off_t sz;
        if (file_size(logfile, &sz, NULL, NULL, NULL) == 0) {
            if (sz >= max_size) {
                if (rotate_log(logfile, keep) != 0) {
                    perror("rotate_log");
                }
            }
        } else {
            if (errno != ENOENT) {
                perror("stat");
            }
        }

        struct timespec ts;
        ts.tv_sec = interval;
        ts.tv_nsec = 0;
        while (nanosleep(&ts, &ts) != 0 && errno == EINTR) {
            if (g_stop) break;
        }
    }

    return 0;
}
