# Minimal C implementation

```c
/*
 * minimal_logrotate_daemon.c
 *
 * A minimal memory-constrained log rotation daemon.
 *
 * Features:
 * - Daemonizes itself
 * - Monitors one log file
 * - Rotates when file exceeds a size threshold
 * - Keeps N rotated files
 * - Uses fixed-size stack buffers, no malloc in steady state
 *
 * Build:
 *   cc -O2 -Wall -Wextra -std=c11 -o minimal_logrotate_daemon minimal_logrotate_daemon.c
 *
 * Run:
 *   ./minimal_logrotate_daemon /tmp/app.log 1048576 5 5
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = rotate size in bytes
 *   argv[3] = number of rotated files to keep
 *   argv[4] = poll interval in seconds
 *
 * Example:
 *   ./minimal_logrotate_daemon /var/log/myapp.log 1048576 4 2
 */

#define _POSIX_C_SOURCE 200809L

#include <sys/stat.h>
#include <sys/types.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <signal.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int signo) {
    (void)signo;
    g_running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT,  &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP,  &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    umask(027);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static int apply_memory_limit(void) {
    /*
     * Strict-ish example limit: 8 MiB address space.
     * Adjust as needed. For a tiny daemon, this is plenty.
     */
    struct rlimit rl;
    rl.rlim_cur = 8 * 1024 * 1024;
    rl.rlim_max = 8 * 1024 * 1024;

    if (setrlimit(RLIMIT_AS, &rl) < 0) {
        return -1;
    }

    return 0;
}

static int file_size_exceeds(const char *path, off_t limit) {
    struct stat st;
    if (stat(path, &st) < 0) {
        if (errno == ENOENT) return 0; /* no file yet */
        return -1;
    }

    return st.st_size >= limit ? 1 : 0;
}

static int build_rotated_name(char *dst, size_t dst_sz, const char *base, int index) {
    int n = snprintf(dst, dst_sz, "%s.%d", base, index);
    if (n < 0 || (size_t)n >= dst_sz) return -1;
    return 0;
}

static int rotate_logs(const char *path, int keep_count) {
    char oldname[PATH_MAX];
    char newname[PATH_MAX];

    if (keep_count < 1) {
        /* No archives requested: just truncate current log */
        int fd = open(path, O_WRONLY | O_TRUNC);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    /*
     * Rename from highest to lowest:
     * path.(N-1) -> path.N
     * ...
     * path.1 -> path.2
     * path -> path.1
     */
    for (int i = keep_count - 1; i >= 1; --i) {
        if (build_rotated_name(oldname, sizeof(oldname), path, i) < 0) return -1;
        if (build_rotated_name(newname, sizeof(newname), path, i + 1) < 0) return -1;

        /*
         * Ignore errors if oldname does not exist.
         */
        if (rename(oldname, newname) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (build_rotated_name(newname, sizeof(newname), path, 1) < 0) return -1;
    if (rename(path, newname) < 0) {
        if (errno != ENOENT) return -1;
    }

    /*
     * Recreate the active log file.
     */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0640);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int ensure_log_exists(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0640);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int parse_long(const char *s, long *out) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    *out = v;
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <log_path> <rotate_size_bytes> <keep_count> <poll_seconds>\n", argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    long rotate_size_long = 0;
    long keep_count_long = 0;
    long poll_seconds_long = 0;

    if (parse_long(argv[2], &rotate_size_long) < 0 || rotate_size_long <= 0) {
        fprintf(stderr, "Invalid rotate_size_bytes\n");
        return 1;
    }

    if (parse_long(argv[3], &keep_count_long) < 0 || keep_count_long < 0 || keep_count_long > 1000) {
        fprintf(stderr, "Invalid keep_count\n");
        return 1;
    }

    if (parse_long(argv[4], &poll_seconds_long) < 0 || poll_seconds_long <= 0 || poll_seconds_long > 86400) {
        fprintf(stderr, "Invalid poll_seconds\n");
        return 1;
    }

    if (strlen(log_path) >= PATH_MAX - 16) {
        fprintf(stderr, "Log path too long\n");
        return 1;
    }

    if (apply_memory_limit() < 0) {
        fprintf(stderr, "Failed to apply memory limit: %s\n", strerror(errno));
        return 1;
    }

    if (setup_signal_handlers() < 0) {
        fprintf(stderr, "Failed to setup signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (ensure_log_exists(log_path) < 0) {
        fprintf(stderr, "Failed to create log file: %s\n", strerror(errno));
        return 1;
    }

    if (daemonize_process() < 0) {
        fprintf(stderr, "Failed to daemonize: %s\n", strerror(errno));
        return 1;
    }

    const off_t rotate_size = (off_t)rotate_size_long;
    const int keep_count = (int)keep_count_long;
    const unsigned int poll_seconds = (unsigned int)poll_seconds_long;

    while (g_running) {
        int rc = file_size_exceeds(log_path, rotate_size);
        if (rc > 0) {
            (void)rotate_logs(log_path, keep_count);
        }

        sleep(poll_seconds);
    }

    return 0;
}
