## Code

```c
/*
 * minimal_logrotate_daemon.c
 *
 * A minimal memory-constrained log rotation daemon.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -pedantic -std=c11 -o minimal_logrotate_daemon minimal_logrotate_daemon.c
 *
 * Run:
 *   ./minimal_logrotate_daemon /tmp/app.log 1048576 5 5
 *
 * Arguments:
 *   argv[1] = log file path
 *   argv[2] = max size in bytes before rotation
 *   argv[3] = number of rotated files to keep
 *   argv[4] = poll interval in seconds
 *
 * Optional environment:
 *   MEM_LIMIT_MB=16    # set virtual memory limit in MB
 *   NO_DAEMON=1        # do not daemonize, stay in foreground
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

static int set_memory_limit_mb(unsigned long mb) {
    struct rlimit rl;
    rl.rlim_cur = (rlim_t)mb * 1024UL * 1024UL;
    rl.rlim_max = (rlim_t)mb * 1024UL * 1024UL;
    return setrlimit(RLIMIT_AS, &rl);
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") < 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    if (dup2(fd, STDIN_FILENO) < 0) return -1;
    if (dup2(fd, STDOUT_FILENO) < 0) return -1;
    if (dup2(fd, STDERR_FILENO) < 0) return -1;

    if (fd > STDERR_FILENO) close(fd);
    return 0;
}

static int file_size_over_limit(const char *path, off_t max_size) {
    struct stat st;
    if (stat(path, &st) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }
    return st.st_size >= max_size ? 1 : 0;
}

static int recreate_log_file(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_logs(const char *path, int keep_count) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    int i;

    if (keep_count < 1) return 0;

    /* Delete the oldest destination implicitly by renaming over it later if supported,
       otherwise unlink it first. */
    snprintf(old_path, sizeof(old_path), "%s.%d", path, keep_count);
    unlink(old_path);

    for (i = keep_count - 1; i >= 1; --i) {
        int n1 = snprintf(old_path, sizeof(old_path), "%s.%d", path, i);
        int n2 = snprintf(new_path, sizeof(new_path), "%s.%d", path, i + 1);
        if (n1 < 0 || n2 < 0 || n1 >= (int)sizeof(old_path) || n2 >= (int)sizeof(new_path)) {
            return -1;
        }
        (void)rename(old_path, new_path);
    }

    int n = snprintf(new_path, sizeof(new_path), "%s.1", path);
    if (n < 0 || n >= (int)sizeof(new_path)) return -1;

    if (rename(path, new_path) < 0) {
        if (errno == ENOENT) return 0;
        return -1;
    }

    return recreate_log_file(path);
}

static long parse_long(const char *s, const char *name) {
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0' || v <= 0) {
        fprintf(stderr, "invalid %s: %s\n", name, s);
        exit(1);
    }
    return v;
}

int main(int argc, char **argv) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <keep_count> <interval_sec>\n", argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    long max_size_l = parse_long(argv[2], "max_size_bytes");
    long keep_count_l = parse_long(argv[3], "keep_count");
    long interval_l = parse_long(argv[4], "interval_sec");

    if (strlen(log_path) >= PATH_MAX - 16) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }

    const char *mem_limit_env = getenv("MEM_LIMIT_MB");
    if (mem_limit_env && *mem_limit_env) {
        long mb = parse_long(mem_limit_env, "MEM_LIMIT_MB");
        if (set_memory_limit_mb((unsigned long)mb) < 0) {
            perror("setrlimit(RLIMIT_AS)");
            return 1;
        }
    }

    if (setup_signals() < 0) {
        perror("setup_signals");
        return 1;
    }

    if (recreate_log_file(log_path) < 0) {
        perror("create log file");
        return 1;
    }

    const char *no_daemon = getenv("NO_DAEMON");
    if (!(no_daemon && strcmp(no_daemon, "1") == 0)) {
        if (daemonize_process() < 0) {
            perror("daemonize");
            return 1;
        }
    }

    while (g_running) {
        int rc = file_size_over_limit(log_path, (off_t)max_size_l);
        if (rc < 0) {
            /* Ignore transient stat errors; keep looping */
        } else if (rc > 0) {
            if (rotate_logs(log_path, (int)keep_count_l) < 0) {
                /* Ignore transient rotate errors in this minimal version */
            }
        }

        sleep((unsigned int)interval_l);
    }

    return 0;
}
