## Minimal C implementation

```c
// logrotate_daemon.c
#define _POSIX_C_SOURCE 200809L

#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_PATH_LEN 256
#define CHECK_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    return st.st_size;
}

static int rotate_logs(const char *log_path, int max_rotations) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];
    int i;

    // Delete the oldest rotation if it exists
    snprintf(old_path, sizeof(old_path), "%s.%d", log_path, max_rotations);
    unlink(old_path);

    // Shift rotations upward: .(n-1) -> .n
    for (i = max_rotations - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", log_path, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", log_path, i + 1);
        rename(old_path, new_path);
    }

    // Rotate current log to .1
    snprintf(new_path, sizeof(new_path), "%s.1", log_path);
    if (rename(log_path, new_path) != 0) {
        return -1;
    }

    // Recreate the log file
    int fd = open(log_path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <max_rotations>\n", argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    off_t max_size = (off_t)atoll(argv[2]);
    int max_rotations = atoi(argv[3]);

    if (strlen(log_path) >= MAX_PATH_LEN) {
        fprintf(stderr, "Error: log path too long\n");
        return 1;
    }

    if (max_size <= 0 || max_rotations <= 0) {
        fprintf(stderr, "Error: invalid max_size or max_rotations\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (daemonize() != 0) {
        fprintf(stderr, "Failed to daemonize: %s\n", strerror(errno));
        return 1;
    }

    while (g_running) {
        if (file_exists(log_path)) {
            off_t size = file_size(log_path);
            if (size >= 0 && size >= max_size) {
                rotate_logs(log_path, max_rotations);
            }
        } else {
            int fd = open(log_path, O_CREAT | O_WRONLY, 0644);
            if (fd >= 0) close(fd);
        }

        sleep(CHECK_INTERVAL_SEC);
    }

    return 0;
}
