## Code: `mini_logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_running = 1;

struct config {
    char log_path[PATH_MAX];
    off_t max_size;
    int keep_count;
    unsigned int interval_sec;
    mode_t create_mode;
    int foreground;
};

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void safe_log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

static int daemonize_if_needed(int foreground) {
    pid_t pid;

    if (foreground) {
        return 0;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (setsid() < 0) {
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        return -1;
    }
    if (pid > 0) {
        _exit(0);
    }

    if (chdir("/") < 0) {
        return -1;
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        if (fd != STDIN_FILENO) dup2(fd, STDIN_FILENO);
        if (fd != STDOUT_FILENO) dup2(fd, STDOUT_FILENO);
        if (fd != STDERR_FILENO) dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }

    return 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;

    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;

    return 0;
}

static int path_with_suffix(char *out, size_t out_sz, const char *base, int suffix) {
    int n = snprintf(out, out_sz, "%s.%d", base, suffix);
    if (n < 0 || (size_t)n >= out_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int ensure_log_exists(const struct config *cfg) {
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT, cfg->create_mode);
    if (fd < 0) {
        return -1;
    }
    close(fd);
    return 0;
}

static int rotate_logs(const struct config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];
    int i;

    if (cfg->keep_count < 1) {
        int fd = open(cfg->log_path, O_WRONLY | O_TRUNC | O_CREAT, cfg->create_mode);
        if (fd < 0) {
            return -1;
        }
        close(fd);
        return 0;
    }

    if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, cfg->keep_count) < 0) {
        return -1;
    }
    unlink(old_path);

    for (i = cfg->keep_count - 1; i >= 1; --i) {
        if (path_with_suffix(old_path, sizeof(old_path), cfg->log_path, i) < 0) {
            return -1;
        }
        if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, i + 1) < 0) {
            return -1;
        }
        rename(old_path, new_path);
    }

    if (path_with_suffix(new_path, sizeof(new_path), cfg->log_path, 1) < 0) {
        return -1;
    }

    if (rename(cfg->log_path, new_path) < 0) {
        if (errno != ENOENT) {
            return -1;
        }
    }

    return ensure_log_exists(cfg);
}

static int check_and_rotate(const struct config *cfg) {
    struct stat st;

    if (stat(cfg->log_path, &st) < 0) {
        if (errno == ENOENT) {
            return ensure_log_exists(cfg);
        }
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }

    if (st.st_size >= cfg->max_size) {
        return rotate_logs(cfg);
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -p LOG_PATH -s MAX_SIZE -k KEEP -i INTERVAL [-m MODE] [-f]\n"
        "  -p LOG_PATH   Path to log file\n"
        "  -s MAX_SIZE   Rotate when size >= MAX_SIZE bytes\n"
        "  -k KEEP       Number of rotated files to keep\n"
        "  -i INTERVAL   Poll interval in seconds\n"
        "  -m MODE       Octal mode for created log file (default 0644)\n"
        "  -f            Run in foreground\n",
        prog);
}

static int parse_int(const char *s, int *out) {
    char *end = NULL;
    long v;

    errno = 0;
    v = strtol(s, &end, 10);
    if (errno || end == s || *end != '\0') {
        return -1;
    }
    if (v < 0 || v > 1000000) {
        errno = ERANGE;
        return -1;
    }
    *out = (int)v;
    return 0;
}

static int parse_uint(const char *s, unsigned int *out) {
    char *end = NULL;
    unsigned long v;

    errno = 0;
    v = strtoul(s, &end, 10);
    if (errno || end == s || *end != '\0') {
        return -1;
    }
    if (v > 1000000UL) {
        errno = ERANGE;
        return -1;
    }
    *out = (unsigned int)v;
    return 0;
}

static int parse_offt(const char *s, off_t *out) {
    char *end = NULL;
    long long v;

    errno = 0;
    v = strtoll(s, &end, 10);
    if (errno || end == s || *end != '\0') {
        return -1;
    }
    if (v < 0) {
        errno = ERANGE;
        return -1;
    }
    *out = (off_t)v;
    return 0;
}

static int parse_mode(const char *s, mode_t *out) {
    char *end = NULL;
    unsigned long v;

    errno = 0;
    v = strtoul(s, &end, 8);
    if (errno || end == s || *end != '\0') {
        return -1;
    }
    if (v > 0777UL) {
        errno = ERANGE;
        return -1;
    }
    *out = (mode_t)v;
    return 0;
}

int main(int argc, char **argv) {
    struct config cfg;
    int opt;

    memset(&cfg, 0, sizeof(cfg));
    cfg.create_mode = 0644;
    cfg.interval_sec = 5;
    cfg.keep_count = 3;

    while ((opt = getopt(argc, argv, "p:s:k:i:m:f")) != -1) {
        switch (opt) {
            case 'p':
                if (snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", optarg) >= (int)sizeof(cfg.log_path)) {
                    safe_log_stderr("log path too long\n");
                    return 1;
                }
                break;
            case 's':
                if (parse_offt(optarg, &cfg.max_size) < 0) {
                    safe_log_stderr("invalid max size\n");
                    return 1;
                }
                break;
            case 'k':
                if (parse_int(optarg, &cfg.keep_count) < 0) {
                    safe_log_stderr("invalid keep count\n");
                    return 1;
                }
                break;
            case 'i':
                if (parse_uint(optarg, &cfg.interval_sec) < 0) {
                    safe_log_stderr("invalid interval\n");
                    return 1;
                }
                break;
            case 'm':
                if (parse_mode(optarg, &cfg.create_mode) < 0) {
                    safe_log_stderr("invalid mode\n");
                    return 1;
                }
                break;
            case 'f':
                cfg.foreground = 1;
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (cfg.log_path[0] == '\0' || cfg.max_size <= 0 || cfg.interval_sec == 0) {
        usage(argv[0]);
        return 1;
    }

    if (install_signal_handlers() < 0) {
        perror("sigaction");
        return 1;
    }

    if (daemonize_if_needed(cfg.foreground) < 0) {
        perror("daemonize");
        return 1;
    }

    while (g_running) {
        if (check_and_rotate(&cfg) < 0 && cfg.foreground) {
            perror("check_and_rotate");
        }
        sleep(cfg.interval_sec);
    }

    return 0;
}
