use chrono::{DateTime, Utc};
use serde::Serialize;
use std::time::Duration;
use sysinfo::{CpuRefreshKind, Disks, MemoryRefreshKind, RefreshKind, System};
use tokio::signal;
use tokio::time;

#[derive(Serialize)]
struct Sample {
    timestamp: DateTime<Utc>,
    cpu_usage_percent: f32,
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    total_swap_bytes: u64,
    used_swap_bytes: u64,
    disks: Vec<DiskSample>,
    top_processes: Vec<ProcessSample>,
}

#[derive(Serialize)]
struct DiskSample {
    name: String,
    mount_point: String,
    total_space_bytes: u64,
    available_space_bytes: u64,
}

#[derive(Serialize)]
struct ProcessSample {
    pid: u32,
    name: String,
    cpu_usage_percent: f32,
    memory_bytes: u64,
}

#[tokio::main]
async fn main() {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );
    let mut disks = Disks::new_with_refreshed_list();

    let mut ticker = time::interval(Duration::from_secs(1));

    eprintln!("safe-monitor-daemon starting");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                sys.refresh_cpu();
                sys.refresh_memory();
                sys.refresh_processes();
                disks.refresh();

                let cpu = sys.global_cpu_info().cpu_usage();

                let mut top: Vec<ProcessSample> = sys.processes()
                    .iter()
                    .map(|(pid, p)| ProcessSample {
                        pid: pid.as_u32(),
                        name: p.name().to_string(),
                        cpu_usage_percent: p.cpu_usage(),
                        memory_bytes: p.memory(),
                    })
                    .collect();

                top.sort_by(|a, b| b.cpu_usage_percent.partial_cmp(&a.cpu_usage_percent).unwrap());
                top.truncate(10);

                let disk_samples = disks.list().iter().map(|d| DiskSample {
                    name: d.name().to_string_lossy().to_string(),
                    mount_point: d.mount_point().to_string_lossy().to_string(),
                    total_space_bytes: d.total_space(),
                    available_space_bytes: d.available_space(),
                }).collect();

                let sample = Sample {
                    timestamp: Utc::now(),
                    cpu_usage_percent: cpu,
                    total_memory_bytes: sys.total_memory(),
                    used_memory_bytes: sys.used_memory(),
                    total_swap_bytes: sys.total_swap(),
                    used_swap_bytes: sys.used_swap(),
                    disks: disk_samples,
                    top_processes: top,
                };

                match serde_json::to_string(&sample) {
                    Ok(line) => println!("{line}"),
                    Err(e) => eprintln!("serialize error: {e}"),
                }
            }
            _ = signal::ctrl_c() => {
                eprintln!("safe-monitor-daemon shutting down");
                break;
            }
        }
    }
}
