```rust
use anyhow::Result;
use axum::{
    extract::State,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde::Serialize;
use std::{
    cmp::Ordering,
    net::SocketAddr,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{Disks, Pid, System};
use tokio::{
    net::TcpListener,
    signal,
    sync::RwLock,
    time,
};
use tracing::{error, info};

#[derive(Debug, Clone, Serialize)]
struct CpuInfo {
    usage_percent: f32,
    core_count: usize,
}

#[derive(Debug, Clone, Serialize)]
struct MemoryInfo {
    total_bytes: u64,
    used_bytes: u64,
    free_bytes: u64,
    used_percent: f64,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_bytes: u64,
    used_percent: f64,
    is_removable: bool,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
}

#[derive(Debug, Clone, Serialize)]
struct MetricsSnapshot {
    timestamp_unix: u64,
    cpu: CpuInfo,
    memory: MemoryInfo,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Clone)]
struct AppState {
    snapshot: Arc<RwLock<MetricsSnapshot>>,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .json()
        .init();

    let initial = MetricsSnapshot {
        timestamp_unix: now_unix(),
        cpu: CpuInfo {
            usage_percent: 0.0,
            core_count: 0,
        },
        memory: MemoryInfo {
            total_bytes: 0,
            used_bytes: 0,
            free_bytes: 0,
            used_percent: 0.0,
        },
        disks: Vec::new(),
        top_processes: Vec::new(),
    };

    let state = AppState {
        snapshot: Arc::new(RwLock::new(initial)),
    };

    let collector_state = state.clone();
    tokio::spawn(async move {
        if let Err(e) = collector_loop(collector_state).await {
            error!(error = %e, "collector loop exited");
        }
    });

    let app = Router::new()
        .route("/health", get(health))
        .route("/metrics", get(metrics))
        .with_state(state);

    let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;
    info!(address = %addr, "sysmon daemon listening");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    info!("shutdown complete");
    Ok(())
}

async fn health() -> impl IntoResponse {
    Json(serde_json::json!({
        "status": "ok"
    }))
}

async fn metrics(State(state): State<AppState>) -> impl IntoResponse {
    let snapshot = state.snapshot.read().await;
    Json(snapshot.clone())
}

async fn collector_loop(state: AppState) -> Result<()> {
    let mut system = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    // First refresh helps sysinfo compute CPU deltas more accurately on subsequent reads.
    system.refresh_all();

    let mut interval = time::interval(Duration::from_secs(2));
    interval.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    loop {
        interval.tick().await;

        system.refresh_cpu_usage();
        system.refresh_memory();
        system.refresh_processes();
        disks.refresh();

        let snapshot = build_snapshot(&system, &disks);
        {
            let mut guard = state.snapshot.write().await;
            *guard = snapshot;
        }
    }
}

fn build_snapshot(system: &System, disks: &Disks) -> MetricsSnapshot {
    let total_mem = system.total_memory() * 1024;
    let used_mem = system.used_memory() * 1024;
    let free_mem = total_mem.saturating_sub(used_mem);

    let memory_used_percent = if total_mem > 0 {
        (used_mem as f64 / total_mem as f64) * 100.0
    } else {
        0.0
    };

    let cpu = CpuInfo {
        usage_percent: system.global_cpu_usage(),
        core_count: system.cpus().len(),
    };

    let memory = MemoryInfo {
        total_bytes: total_mem,
        used_bytes: used_mem,
        free_bytes: free_mem,
        used_percent: memory_used_percent,
    };

    let disk_infos = disks
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);
            let used_percent = if total > 0 {
                (used as f64 / total as f64) * 100.0
            } else {
                0.0
            };

            DiskInfo {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_bytes: total,
                available_bytes: avail,
                used_bytes: used,
                used_percent,
                is_removable: d.is_removable(),
            }
        })
        .collect::<Vec<_>>();

    let mut processes = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessInfo {
            pid: pid_to_u32(*pid),
            name: proc_.name().to_string_lossy().to_string(),
            cpu_percent: proc_.cpu_usage(),
            memory_bytes: proc_.memory() * 1024,
        })
        .collect::<Vec<_>>();

    processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(Ordering::Equal)
            .then_with(|| b.memory_bytes.cmp(&a.memory_bytes))
    });
    processes.truncate(10);

    MetricsSnapshot {
        timestamp_unix: now_unix(),
        cpu,
        memory,
        disks: disk_infos,
        top_processes: processes,
    }
}

fn pid_to_u32(pid: Pid) -> u32 {
    pid.as_u32()
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm =
            signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("shutdown signal received");
}
