use tracing::{error, info, warn};

const DEFAULT_SOCKET_PATH: &str = "/tmp/sysmond.sock";
const DEFAULT_INTERVAL_SECS: u64 = 2;
const MAX_TOP_PROCESSES: usize = 10;

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_percent: f32,
    memory_bytes: u64,
    virtual_memory_bytes: u64,
    status: String,
}

#[derive(Debug, Clone, Serialize)]
struct DiskInfo {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_bytes: u64,
    file_system: String,
}

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp_unix: u64,
    uptime_secs: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    cpu_usage_percent: f32,
    memory_total_bytes: u64,
    memory_used_bytes: u64,
    memory_available_bytes: u64,
    swap_total_bytes: u64,
    swap_used_bytes: u64,
    disks: Vec<DiskInfo>,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone)]
struct Config {
    poll_interval: Duration,
}

#[derive(Debug)]
struct AppState {
    snapshot: RwLock<SystemSnapshot>,
    config: RwLock<Config>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    Ping,
    GetStatus,
    SetInterval { secs: u64 },
    Shutdown,
}

#[derive(Debug, Serialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum Response {
    Ok {
        message: String,
    },
    Pong {
        message: String,
        timestamp_unix: u64,
    },
    Status {
        snapshot: SystemSnapshot,
    },
    Updated {
        poll_interval_secs: u64,
    },
    Error {
        error: String,
    },
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn empty_snapshot() -> SystemSnapshot {
    SystemSnapshot {
        timestamp_unix: now_unix(),
        uptime_secs: 0,
        load_avg_one: 0.0,
        load_avg_five: 0.0,
        load_avg_fifteen: 0.0,
        cpu_usage_percent: 0.0,
        memory_total_bytes: 0,
        memory_used_bytes: 0,
        memory_available_bytes: 0,
        swap_total_bytes: 0,
        swap_used_bytes: 0,
        disks: vec![],
        top_processes: vec![],
    }
}

fn collect_snapshot(sys: &mut System) -> SystemSnapshot {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_disks_list();
    sys.refresh_disks();
    sys.refresh_processes();

    let load: LoadAvg = System::load_average();

    let cpu_usage = if sys.cpus().is_empty() {
        0.0
    } else {
        let total: f32 = sys.cpus().iter().map(|c| c.cpu_usage()).sum();
        total / sys.cpus().len() as f32
    };

    let mut top_processes: Vec<ProcessInfo> = sys
        .processes()
        .values()
        .map(|p| ProcessInfo {
            pid: p.pid().as_u32(),
            name: p.name().to_string(),
            cpu_percent: p.cpu_usage(),
            memory_bytes: p.memory() * 1024,
            virtual_memory_bytes: p.virtual_memory() * 1024,
            status: format!("{:?}", p.status()),
        })
        .collect();

    top_processes.sort_by(|a, b| {
        b.cpu_percent
            .partial_cmp(&a.cpu_percent)
            .unwrap_or(Ordering::Equal)
    });
    top_processes.truncate(MAX_TOP_PROCESSES);

    let disks = sys
        .disks()
        .iter()
        .map(|d| {
            let total = d.total_space();
            let avail = d.available_space();
            let used = total.saturating_sub(avail);

            DiskInfo {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_bytes: total,
                available_bytes: avail,
                used_bytes: used,
                file_system: String::from_utf8_lossy(d.file_system()).to_string(),
            }
        })
        .collect();

    SystemSnapshot {
        timestamp_unix: now_unix(),
        uptime_secs: sys.uptime(),
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        cpu_usage_percent: cpu_usage,
        memory_total_bytes: sys.total_memory() * 1024,
        memory_used_bytes: sys.used_memory() * 1024,
        memory_available_bytes: sys.available_memory() * 1024,
        swap_total_bytes: sys.total_swap() * 1024,
        swap_used_bytes: sys.used_swap() * 1024,
        disks,
        top_processes,
    }
}

async fn metrics_loop(
    state: Arc<AppState>,
    mut shutdown_rx: watch::Receiver<bool>,
) -> Result<()> {
    let mut sys = System::new_all();

    // Warm-up refresh for more accurate CPU/process values.
    sys.refresh_all();
    time::sleep(Duration::from_millis(300)).await;

    loop {
        if *shutdown_rx.borrow() {
            info!("metrics loop shutting down");
            break;
        }

        let snapshot = collect_snapshot(&mut sys);
        {
            let mut guard = state.snapshot.write().await;
            *guard = snapshot;
        }

        let interval = {
            let guard = state.config.read().await;
            guard.poll_interval
        };

        tokio::select! {
            _ = time::sleep(interval) => {}
            changed = shutdown_rx.changed() => {
                if changed.is_ok() && *shutdown_rx.borrow() {
                    info!("metrics loop received shutdown");
                    break;
                }
            }
        }
    }

    Ok(())
}

async fn handle_command(
    cmd: Command,
    state: Arc<AppState>,
    shutdown_tx: watch::Sender<bool>,
) -> Response {
    match cmd {
        Command::Ping => Response::Pong {
            message: "sysmond alive".to_string(),
            timestamp_unix: now_unix(),
        },
        Command::GetStatus => {
            let snapshot = state.snapshot.read().await.clone();
            Response::Status { snapshot }
        }
        Command::SetInterval { secs } => {
            if secs == 0 || secs > 3600 {
                return Response::Error {
                    error: "secs must be between 1 and 3600".to_string(),
                };
            }

            {
                let mut cfg = state.config.write().await;
                cfg.poll_interval = Duration::from_secs(secs);
            }

            Response::Updated {
                poll_interval_secs: secs,
            }
        }
        Command::Shutdown => {
            let _ = shutdown_tx.send(true);
            Response::Ok {
                message: "shutdown initiated".to_string(),
            }
        }
    }
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<AppState>,
    shutdown_tx: watch::Sender<bool>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let bytes = reader
        .read_line(&mut line)
        .await
        .context("failed to read client request")?;

    if bytes == 0 {
        return Ok(());
    }

    let response = match serde_json::from_str::<Command>(&line) {
        Ok(cmd) => handle_command(cmd, state, shutdown_tx).await,
        Err(e) => Response::Error {
            error: format!("invalid request: {e}"),
        },
    };

    let payload = serde_json::to_vec(&response)?;
    writer.write_all(&payload).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;

    Ok(())
}

async fn server_loop(
    socket_path: &str,
    state: Arc<AppState>,
    shutdown_tx: watch::Sender<bool>,
    mut shutdown_rx: watch::Receiver<bool>,
) -> Result<()> {
    if Path::new(socket_path).exists() {
        std::fs::remove_file(socket_path)
            .with_context(|| format!("failed to remove old socket at {socket_path}"))?;
    }

    let listener = UnixListener::bind(socket_path)
        .with_context(|| format!("failed to bind unix socket at {socket_path}"))?;

    info!("listening on {}", socket_path);

    loop {
        tokio::select! {
            accept_res = listener.accept() => {
                match accept_res {
                    Ok((stream, _addr)) => {
                        let state_cloned = Arc::clone(&state);
                        let shutdown_tx_cloned = shutdown_tx.clone();
                        tokio::spawn(async move {
                            if let Err(e) = handle_client(stream, state_cloned, shutdown_tx_cloned).await {
                                warn!("client error: {:?}", e);
                            }
                        });
                    }
                    Err(e) => {
                        error!("accept error: {:?}", e);
                    }
                }
            }
            changed = shutdown_rx.changed() => {
                if changed.is_ok() && *shutdown_rx.borrow() {
                    info!("server loop shutting down");
                    break;
                }
            }
        }
    }

    if Path::new(socket_path).exists() {
        if let Err(e) = std::fs::remove_file(socket_path) {
            warn!("failed to remove socket during shutdown: {:?}", e);
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let socket_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| DEFAULT_SOCKET_PATH.to_string());

    let state = Arc::new(AppState {
        snapshot: RwLock::new(empty_snapshot()),
        config: RwLock::new(Config {
            poll_interval: Duration::from_secs(DEFAULT_INTERVAL_SECS),
        }),
    });

    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let metrics_task = tokio::spawn(metrics_loop(Arc::clone(&state), shutdown_rx.clone()));
    let server_task = tokio::spawn(server_loop(
        &socket_path,
        Arc::clone(&state),
        shutdown_tx.clone(),
        shutdown_rx.clone(),
    ));

    tokio::select! {
        res = metrics_task => {
            match res {
                Ok(inner) => inner?,
                Err(e) => return Err(anyhow::anyhow!("metrics task join error: {e}")),
            }
        }
        res = server_task => {
            match res {
                Ok(inner) => inner?,
                Err(e) => return Err(anyhow::anyhow!("server task join error: {e}")),
            }
        }
        _ = tokio::signal::ctrl_c() => {
            info!("ctrl-c received, shutting down");
            let _ = shutdown_tx.send(true);
        }
    }

    Ok(())
}
