```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::VecDeque,
    fs,
    path::Path,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::RwLock,
    time::sleep,
};

const SOCKET_PATH: &str = "/tmp/sysdaemon.sock";
const DEFAULT_INTERVAL_SECS: u64 = 2;
const HISTORY_SIZE: usize = 60;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MetricsSnapshot {
    timestamp: u64,
    cpu_usage_percent: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
    loadavg_1m: f64,
    loadavg_5m: f64,
    loadavg_15m: f64,
    process_count: usize,
    disk_reads_completed: u64,
    disk_writes_completed: u64,
}

#[derive(Debug)]
struct SharedState {
    latest: Option<MetricsSnapshot>,
    history: VecDeque<MetricsSnapshot>,
    interval_secs: u64,
    prev_cpu_total: u64,
    prev_cpu_idle: u64,
    prev_disk_reads: u64,
    prev_disk_writes: u64,
}

impl SharedState {
    fn new() -> Self {
        Self {
            latest: None,
            history: VecDeque::with_capacity(HISTORY_SIZE),
            interval_secs: DEFAULT_INTERVAL_SECS,
            prev_cpu_total: 0,
            prev_cpu_idle: 0,
            prev_disk_reads: 0,
            prev_disk_writes: 0,
        }
    }
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "kebab-case")]
enum Command {
    Status,
    Metrics,
    SetInterval { secs: u64 },
}

#[derive(Debug, Serialize)]
struct Response<T> {
    ok: bool,
    data: Option<T>,
    error: Option<String>,
}

impl<T> Response<T> {
    fn ok(data: T) -> Self {
        Self {
            ok: true,
            data: Some(data),
            error: None,
        }
    }

    fn err(msg: impl Into<String>) -> Self {
        Self {
            ok: false,
            data: None,
            error: Some(msg.into()),
        }
    }
}

#[derive(Debug, Serialize)]
struct StatusResponse {
    running: bool,
    interval_secs: u64,
    socket_path: String,
    history_len: usize,
}

#[tokio::main]
async fn main() -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let state = Arc::new(RwLock::new(SharedState::new()));

    let collector_state = Arc::clone(&state);
    tokio::spawn(async move {
        if let Err(e) = collector_loop(collector_state).await {
            eprintln!("collector loop error: {e:#}");
        }
    });

    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket at {}", SOCKET_PATH))?;

    println!("sysdaemon listening on {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                eprintln!("client handler error: {e:#}");
            }
        });
    }
}

async fn collector_loop(state: Arc<RwLock<SharedState>>) -> Result<()> {
    loop {
        let interval;
        {
            let mut s = state.write().await;
            let snapshot = collect_metrics(&mut s)
                .context("collecting metrics failed")?;
            s.latest = Some(snapshot.clone());
            if s.history.len() == HISTORY_SIZE {
                s.history.pop_front();
            }
            s.history.push_back(snapshot);
            interval = s.interval_secs;
        }

        sleep(Duration::from_secs(interval)).await;
    }
}

fn collect_metrics(state: &mut SharedState) -> Result<MetricsSnapshot> {
    let (cpu_total, cpu_idle) = read_cpu_stats()?;
    let cpu_usage_percent = if state.prev_cpu_total == 0 {
        0.0
    } else {
        let total_delta = cpu_total.saturating_sub(state.prev_cpu_total);
        let idle_delta = cpu_idle.saturating_sub(state.prev_cpu_idle);
        if total_delta == 0 {
            0.0
        } else {
            100.0 * (1.0 - (idle_delta as f64 / total_delta as f64))
        }
    };
    state.prev_cpu_total = cpu_total;
    state.prev_cpu_idle = cpu_idle;

    let (mem_total_kb, mem_available_kb) = read_meminfo()?;
    let mem_used_kb = mem_total_kb.saturating_sub(mem_available_kb);

    let (loadavg_1m, loadavg_5m, loadavg_15m) = read_loadavg()?;
    let process_count = count_processes()?;

    let (disk_reads, disk_writes) = read_diskstats()?;
    let disk_reads_completed = if state.prev_disk_reads == 0 {
        0
    } else {
        disk_reads.saturating_sub(state.prev_disk_reads)
    };
    let disk_writes_completed = if state.prev_disk_writes == 0 {
        0
    } else {
        disk_writes.saturating_sub(state.prev_disk_writes)
    };
    state.prev_disk_reads = disk_reads;
    state.prev_disk_writes = disk_writes;

    Ok(MetricsSnapshot {
        timestamp: now_unix_secs(),
        cpu_usage_percent,
        mem_total_kb,
        mem_available_kb,
        mem_used_kb,
        loadavg_1m,
        loadavg_5m,
        loadavg_15m,
        process_count,
        disk_reads_completed,
        disk_writes_completed,
    })
}

fn read_cpu_stats() -> Result<(u64, u64)> {
    let content = fs::read_to_string("/proc/stat")?;
    let line = content
        .lines()
        .next()
        .context("missing cpu line in /proc/stat")?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        anyhow::bail!("unexpected /proc/stat cpu format");
    }

    let user: u64 = parts[1].parse()?;
    let nice: u64 = parts[2].parse()?;
    let system: u64 = parts[3].parse()?;
    let idle: u64 = parts[4].parse()?;
    let iowait: u64 = parts.get(5).and_then(|s| s.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|s| s.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|s| s.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|s| s.parse().ok()).unwrap_or(0);

    let total = user + nice + system + idle + iowait + irq + softirq + steal;
    Ok((total, idle + iowait))
}

fn read_meminfo() -> Result<(u64, u64)> {
    let content = fs::read_to_string("/proc/meminfo")?;
    let mut total = None;
    let mut available = None;

    for line in content.lines() {
        if line.starts_with("MemTotal:") {
            total = line.split_whitespace().nth(1).and_then(|v| v.parse().ok());
        } else if line.starts_with("MemAvailable:") {
            available = line.split_whitespace().nth(1).and_then(|v| v.parse().ok());
        }
    }

    Ok((
        total.context("MemTotal not found")?,
        available.context("MemAvailable not found")?,
    ))
}

fn read_loadavg() -> Result<(f64, f64, f64)> {
    let content = fs::read_to_string("/proc/loadavg")?;
    let parts: Vec<&str> = content.split_whitespace().collect();
    if parts.len() < 3 {
        anyhow::bail!("unexpected /proc/loadavg format");
    }

    Ok((parts[0].parse()?, parts[1].parse()?, parts[2].parse()?))
}

fn count_processes() -> Result<usize> {
    let mut count = 0usize;
    for entry in fs::read_dir("/proc")? {
        let entry = entry?;
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name.chars().all(|c| c.is_ascii_digit()) {
            count += 1;
        }
    }
    Ok(count)
}

fn read_diskstats() -> Result<(u64, u64)> {
    let content = fs::read_to_string("/proc/diskstats")?;
    let mut reads = 0u64;
    let mut writes = 0u64;

    for line in content.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 14 {
            continue;
        }

        let dev_name = parts[2];
        if dev_name.starts_with("loop") || dev_name.starts_with("ram") {
            continue;
        }

        let reads_completed: u64 = parts[3].parse().unwrap_or(0);
        let writes_completed: u64 = parts[7].parse().unwrap_or(0);

        reads += reads_completed;
        writes += writes_completed;
    }

    Ok((reads, writes))
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: Command = match serde_json::from_str(line.trim()) {
        Ok(c) => c,
        Err(e) => {
            let resp = serde_json::to_string(&Response::<()>::err(format!("invalid command: {e}")))?;
            writer.write_all(resp.as_bytes()).await?;
            writer.write_all(b"\n").await?;
            return Ok(());
        }
    };

    match cmd {
        Command::Status => {
            let s = state.read().await;
            let resp = Response::ok(StatusResponse {
                running: true,
                interval_secs: s.interval_secs,
                socket_path: SOCKET_PATH.to_string(),
                history_len: s.history.len(),
            });
            write_json(&mut writer, &resp).await?;
        }
        Command::Metrics => {
            let s = state.read().await;
            let resp = Response::ok(s.latest.clone());
            write_json(&mut writer, &resp).await?;
        }
        Command::SetInterval { secs } => {
            if secs == 0 || secs > 3600 {
                let resp = Response::<()>::err("secs must be between 1 and 3600");
                write_json(&mut writer, &resp).await?;
            } else {
                let mut s = state.write().await;
                s.interval_secs = secs;
                let resp = Response::ok(StatusResponse {
                    running: true,
                    interval_secs: s.interval_secs,
                    socket_path: SOCKET_PATH.to_string(),
                    history_len: s.history.len(),
                });
                write_json(&mut writer, &resp).await?;
            }
        }
    }

    Ok(())
}

async fn write_json<T: Serialize>(
    writer: &mut tokio::net::unix::OwnedWriteHalf,
    value: &T,
) -> Result<()> {
    let s = serde_json::to_string(value)?;
    writer.write_all(s.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    Ok(())
}

fn now_unix_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
