```rust
use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use serde::{Deserialize, Serialize};
use std::fs::{self, File};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

const SOCKET_PATH: &str = "/tmp/sysdaemon.sock";
const SAMPLE_INTERVAL: Duration = Duration::from_secs(2);

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    cpu_warn_percent: f64,
    mem_warn_percent: f64,
    load_warn_per_cpu: f64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            cpu_warn_percent: 90.0,
            mem_warn_percent: 90.0,
            load_warn_per_cpu: 2.0,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Metrics {
    cpu_percent: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_percent: f64,
    load1: f64,
    load5: f64,
    load15: f64,
    cpu_count: usize,
    timestamp_unix_ms: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Status {
    running: bool,
    uptime_secs: u64,
    metrics: Metrics,
    config: Config,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum Command {
    Status,
    SetConfig {
        cpu_warn_percent: Option<f64>,
        mem_warn_percent: Option<f64>,
        load_warn_per_cpu: Option<f64>,
    },
    KillPid {
        pid: i32,
        signal: Option<i32>,
    },
    Shutdown,
}

#[derive(Debug, Serialize, Deserialize)]
struct Response<T> {
    ok: bool,
    message: String,
    data: Option<T>,
}

#[derive(Debug, Clone, Copy)]
struct CpuTimes {
    idle: u64,
    total: u64,
}

struct DaemonState {
    start: Instant,
    config: Mutex<Config>,
    last_metrics: Mutex<Metrics>,
    running: AtomicBool,
}

fn main() -> Result<()> {
    let state = Arc::new(DaemonState {
        start: Instant::now(),
        config: Mutex::new(Config::default()),
        last_metrics: Mutex::new(initial_metrics()?),
        running: AtomicBool::new(true),
    });

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    {
        let state = Arc::clone(&state);
        ctrlc_like_install(state)?;
    }

    let monitor_handle = {
        let state = Arc::clone(&state);
        thread::spawn(move || monitor_loop(state))
    };

    let server_handle = {
        let state = Arc::clone(&state);
        thread::spawn(move || command_server_loop(state))
    };

    monitor_handle
        .join()
        .map_err(|_| anyhow::anyhow!("monitor thread panicked"))??;
    server_handle
        .join()
        .map_err(|_| anyhow::anyhow!("server thread panicked"))??;

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    Ok(())
}

fn ctrlc_like_install(state: Arc<DaemonState>) -> Result<()> {
    use nix::sys::signal;
    extern "C" fn handle_sigint(_: i32) {}

    unsafe {
        signal::signal(signal::Signal::SIGINT, signal::SigHandler::Handler(handle_sigint))
            .context("failed to install SIGINT handler")?;
        signal::signal(signal::Signal::SIGTERM, signal::SigHandler::Handler(handle_sigint))
            .context("failed to install SIGTERM handler")?;
    }

    thread::spawn(move || {
        loop {
            thread::sleep(Duration::from_millis(200));
            // In a real daemon you'd use signalfd/self-pipe/eventfd for proper signal handling.
            // This placeholder keeps structure simple for initial implementation.
            if !state.running.load(Ordering::Relaxed) {
                break;
            }
        }
    });

    Ok(())
}

fn initial_metrics() -> Result<Metrics> {
    Ok(Metrics {
        cpu_percent: 0.0,
        mem_total_kb: 0,
        mem_available_kb: 0,
        mem_used_percent: 0.0,
        load1: 0.0,
        load5: 0.0,
        load15: 0.0,
        cpu_count: cpu_count()?,
        timestamp_unix_ms: now_unix_ms(),
    })
}

fn monitor_loop(state: Arc<DaemonState>) -> Result<()> {
    let mut prev_cpu = read_cpu_times().context("failed to read initial CPU times")?;

    while state.running.load(Ordering::Relaxed) {
        thread::sleep(SAMPLE_INTERVAL);

        let current_cpu = read_cpu_times().context("failed to read CPU times")?;
        let cpu_percent = compute_cpu_percent(prev_cpu, current_cpu);
        prev_cpu = current_cpu;

        let (mem_total_kb, mem_available_kb, mem_used_percent) =
            read_memory().context("failed to read memory info")?;

        let (load1, load5, load15) = read_loadavg().context("failed to read loadavg")?;
        let cpu_count = cpu_count().context("failed to count CPUs")?;

        let metrics = Metrics {
            cpu_percent,
            mem_total_kb,
            mem_available_kb,
            mem_used_percent,
            load1,
            load5,
            load15,
            cpu_count,
            timestamp_unix_ms: now_unix_ms(),
        };

        {
            let mut guard = state.last_metrics.lock().unwrap();
            *guard = metrics.clone();
        }

        evaluate_policy(&state, &metrics)?;
    }

    Ok(())
}

fn evaluate_policy(state: &Arc<DaemonState>, metrics: &Metrics) -> Result<()> {
    let cfg = state.config.lock().unwrap().clone();

    if metrics.cpu_percent >= cfg.cpu_warn_percent {
        eprintln!(
            "[WARN] high CPU usage: {:.2}% >= {:.2}%",
            metrics.cpu_percent, cfg.cpu_warn_percent
        );
    }

    if metrics.mem_used_percent >= cfg.mem_warn_percent {
        eprintln!(
            "[WARN] high memory usage: {:.2}% >= {:.2}%",
            metrics.mem_used_percent, cfg.mem_warn_percent
        );
    }

    let normalized_load = if metrics.cpu_count > 0 {
        metrics.load1 / metrics.cpu_count as f64
    } else {
        0.0
    };

    if normalized_load >= cfg.load_warn_per_cpu {
        eprintln!(
            "[WARN] high load average: load1/cpu = {:.2} >= {:.2}",
            normalized_load, cfg.load_warn_per_cpu
        );
    }

    Ok(())
}

fn command_server_loop(state: Arc<DaemonState>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH).context("failed to bind Unix socket")?;
    listener
        .set_nonblocking(true)
        .context("failed to set nonblocking listener")?;

    while state.running.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let state = Arc::clone(&state);
                thread::spawn(move || {
                    if let Err(err) = handle_client(stream, state) {
                        eprintln!("[ERROR] client handling failed: {err:#}");
                    }
                });
            }
            Err(err) if err.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(err) => {
                eprintln!("[ERROR] accept failed: {err}");
                thread::sleep(Duration::from_millis(200));
            }
        }
    }

    Ok(())
}

fn handle_client(mut stream: UnixStream, state: Arc<DaemonState>) -> Result<()> {
    let mut buf = String::new();
    stream
        .read_to_string(&mut buf)
        .context("failed to read command")?;

    let cmd: Command = serde_json::from_str(&buf).context("failed to parse command JSON")?;
    let resp = process_command(cmd, state);

    let encoded = serde_json::to_vec(&resp).context("failed to encode response JSON")?;
    stream
        .write_all(&encoded)
        .context("failed to write response")?;

    Ok(())
}

fn process_command(cmd: Command, state: Arc<DaemonState>) -> Response<serde_json::Value> {
    match cmd {
        Command::Status => {
            let metrics = state.last_metrics.lock().unwrap().clone();
            let config = state.config.lock().unwrap().clone();
            let status = Status {
                running: state.running.load(Ordering::Relaxed),
                uptime_secs: state.start.elapsed().as_secs(),
                metrics,
                config,
            };

            match serde_json::to_value(status) {
                Ok(v) => Response {
                    ok: true,
                    message: "status".into(),
                    data: Some(v),
                },
                Err(e) => Response {
                    ok: false,
                    message: format!("failed to serialize status: {e}"),
                    data: None,
                },
            }
        }
        Command::SetConfig {
            cpu_warn_percent,
            mem_warn_percent,
            load_warn_per_cpu,
        } => {
            let mut cfg = state.config.lock().unwrap();
            if let Some(v) = cpu_warn_percent {
                cfg.cpu_warn_percent = v;
            }
            if let Some(v) = mem_warn_percent {
                cfg.mem_warn_percent = v;
            }
            if let Some(v) = load_warn_per_cpu {
                cfg.load_warn_per_cpu = v;
            }

            match serde_json::to_value(cfg.clone()) {
                Ok(v) => Response {
                    ok: true,
                    message: "config updated".into(),
                    data: Some(v),
                },
                Err(e) => Response {
                    ok: false,
                    message: format!("failed to serialize config: {e}"),
                    data: None,
                },
            }
        }
        Command::KillPid { pid, signal } => {
            let sig = match signal.unwrap_or(libc::SIGTERM) {
                libc::SIGKILL => Signal::SIGKILL,
                libc::SIGINT => Signal::SIGINT,
                libc::SIGTERM => Signal::SIGTERM,
                libc::SIGHUP => Signal::SIGHUP,
                _ => {
                    return Response {
                        ok: false,
                        message: "unsupported signal".into(),
                        data: None,
                    }
                }
            };

            match kill(Pid::from_raw(pid), sig) {
                Ok(_) => Response {
                    ok: true,
                    message: format!("signal {:?} sent to pid {}", sig, pid),
                    data: None,
                },
                Err(e) => Response {
                    ok: false,
                    message: format!("failed to signal pid {}: {}", pid, e),
                    data: None,
                },
            }
        }
        Command::Shutdown => {
            state.running.store(false, Ordering::Relaxed);
            Response {
                ok: true,
                message: "shutdown initiated".into(),
                data: None,
            }
        }
    }
}

fn read_cpu_times() -> Result<CpuTimes> {
    let file = File::open("/proc/stat").context("open /proc/stat failed")?;
    let mut reader = BufReader::new(file);
    let mut line = String::new();
    reader.read_line(&mut line).context("read /proc/stat failed")?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        anyhow::bail!("unexpected /proc/stat format");
    }

    let user: u64 = parts[1].parse()?;
    let nice: u64 = parts[2].parse()?;
    let system: u64 = parts[3].parse()?;
    let idle: u64 = parts[4].parse()?;
    let iowait: u64 = parts.get(5).and_then(|v| v.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|v| v.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|v| v.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|v| v.parse().ok()).unwrap_or(0);

    let idle_all = idle + iowait;
    let total = user + nice + system + idle + iowait + irq + softirq + steal;

    Ok(CpuTimes {
        idle: idle_all,
        total,
    })
}

fn compute_cpu_percent(prev: CpuTimes, current: CpuTimes) -> f64 {
    let totald = current.total.saturating_sub(prev.total);
    let idled = current.idle.saturating_sub(prev.idle);

    if totald == 0 {
        return 0.0;
    }

    ((totald - idled) as f64 / totald as f64) * 100.0
}

fn read_memory() -> Result<(u64, u64, f64)> {
    let contents = fs::read_to_string("/proc/meminfo").context("read /proc/meminfo failed")?;

    let mut total_kb = None;
    let mut avail_kb = None;

    for line in contents.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line.split_whitespace().nth(1).and_then(|v| v.parse().ok());
        } else if line.starts_with("MemAvailable:") {
            avail_kb = line.split_whitespace().nth(1).and_then(|v| v.parse().ok());
        }
    }

    let total = total_kb.context("MemTotal missing")?;
    let avail = avail_kb.context("MemAvailable missing")?;
    let used_percent = if total == 0 {
        0.0
    } else {
        ((total - avail) as f64 / total as f64) * 100.0
    };

    Ok((total, avail, used_percent))
}

fn read_loadavg() -> Result<(f64, f64, f64)> {
    let contents = fs::read_to_string("/proc/loadavg").context("read /proc/loadavg failed")?;
    let parts: Vec<&str> = contents.split_whitespace().collect();
    if parts.len() < 3 {
        anyhow::bail!("unexpected /proc/loadavg format");
    }

    let l1 = parts[0].parse()?;
    let l5 = parts[1].parse()?;
    let l15 = parts[2].parse()?;
    Ok((l1, l5, l15))
}

fn cpu_count() -> Result<usize> {
    let contents = fs::read_to_string("/proc/stat").context("read /proc/stat failed")?;
    let count = contents
        .lines()
        .filter(|line| {
            if let Some(rest) = line.strip_prefix("cpu") {
                !rest.is_empty() && rest.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false)
            } else {
                false
            }
        })
        .count();

    Ok(count.max(1))
}

fn now_unix_ms() -> u128 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}
