use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::path::Path;
use std::sync::Arc;
use std::time::Duration;
use tokio::fs;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::RwLock;
use tokio::time::sleep;

const SOCKET_PATH: &str = "/tmp/sysmond.sock";
const DEFAULT_POLL_INTERVAL_SECS: u64 = 2;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    poll_interval_secs: u64,
    memory_limit_mb: u64,
    cpu_limit_pct: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_secs: DEFAULT_POLL_INTERVAL_SECS,
            memory_limit_mb: 4096,
            cpu_limit_pct: 90,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct Metrics {
    cpu_usage_pct: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
    load1: f64,
    load5: f64,
    load15: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct State {
    config: Config,
    metrics: Metrics,
}

impl Default for State {
    fn default() -> Self {
        Self {
            config: Config::default(),
            metrics: Metrics::default(),
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct CpuSample {
    total: u64,
    idle: u64,
}

#[tokio::main]
async fn main() -> Result<()> {
    let state = Arc::new(RwLock::new(State::default()));

    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH).await;
    }

    let monitor_state = state.clone();
    let control_state = state.clone();

    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitoring_loop(monitor_state).await {
            eprintln!("monitoring loop failed: {e:#}");
        }
    });

    let control_task = tokio::spawn(async move {
        if let Err(e) = control_server(control_state).await {
            eprintln!("control server failed: {e:#}");
        }
    });

    let _ = tokio::join!(monitor_task, control_task);

    Ok(())
}

async fn monitoring_loop(state: Arc<RwLock<State>>) -> Result<()> {
    let mut prev_cpu = read_cpu_sample().await?;

    loop {
        let poll_interval = {
            let s = state.read().await;
            s.config.poll_interval_secs
        };

        sleep(Duration::from_secs(poll_interval)).await;

        let current_cpu = read_cpu_sample().await?;
        let mem = read_meminfo().await?;
        let load = read_loadavg().await?;

        let cpu_usage_pct = calculate_cpu_usage(prev_cpu, current_cpu);
        prev_cpu = current_cpu;

        {
            let mut s = state.write().await;
            s.metrics.cpu_usage_pct = cpu_usage_pct;
            s.metrics.mem_total_kb = mem.mem_total_kb;
            s.metrics.mem_available_kb = mem.mem_available_kb;
            s.metrics.mem_used_kb = mem.mem_used_kb;
            s.metrics.load1 = load.0;
            s.metrics.load5 = load.1;
            s.metrics.load15 = load.2;

            apply_policy(&mut s);
        }
    }
}

fn apply_policy(state: &mut State) {
    if state.metrics.mem_used_kb > state.config.memory_limit_mb * 1024 {
        eprintln!(
            "warning: memory usage exceeded limit: used={}KB limit={}MB",
            state.metrics.mem_used_kb,
            state.config.memory_limit_mb
        );
    }

    if state.metrics.cpu_usage_pct > state.config.cpu_limit_pct as f64 {
        eprintln!(
            "warning: cpu usage exceeded limit: used={:.2}% limit={}%",
            state.metrics.cpu_usage_pct,
            state.config.cpu_limit_pct
        );
    }
}

async fn control_server(state: Arc<RwLock<State>>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)
        .with_context(|| format!("failed to bind unix socket at {}", SOCKET_PATH))?;

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                eprintln!("client handling error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<RwLock<State>>) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer
        .write_all(b"sysmond ready\n")
        .await
        .context("failed to write greeting")?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let response = process_command(line.trim(), state.clone()).await;
        writer.write_all(response.as_bytes()).await?;
        writer.write_all(b"\n").await?;
    }

    Ok(())
}

async fn process_command(cmd: &str, state: Arc<RwLock<State>>) -> String {
    let parts: Vec<&str> = cmd.split_whitespace().collect();

    if parts.is_empty() {
        return "error: empty command".to_string();
    }

    match parts[0] {
        "status" => {
            let s = state.read().await;
            match serde_json::to_string(&*s) {
                Ok(json) => json,
                Err(e) => format!("error: failed to serialize state: {e}"),
            }
        }
        "set" => {
            if parts.len() != 3 {
                return "error: usage: set <memory_limit_mb|cpu_limit_pct> <value>".to_string();
            }

            let key = parts[1];
            let value = match parts[2].parse::<u64>() {
                Ok(v) => v,
                Err(_) => return "error: value must be an integer".to_string(),
            };

            let mut s = state.write().await;
            match key {
                "memory_limit_mb" => {
                    s.config.memory_limit_mb = value;
                    "ok".to_string()
                }
                "cpu_limit_pct" => {
                    s.config.cpu_limit_pct = value;
                    "ok".to_string()
                }
                _ => "error: unknown config key".to_string(),
            }
        }
        "help" => {
            "commands: status | set memory_limit_mb <n> | set cpu_limit_pct <n> | help"
                .to_string()
        }
        _ => "error: unknown command".to_string(),
    }
}

async fn read_file(path: &str) -> Result<String> {
    let content = fs::read_to_string(path)
        .await
        .with_context(|| format!("failed to read {}", path))?;
    Ok(content)
}

async fn read_cpu_sample() -> Result<CpuSample> {
    let stat = read_file("/proc/stat").await?;
    let first_line = stat
        .lines()
        .next()
        .context("missing cpu line in /proc/stat")?;

    let fields: Vec<&str> = first_line.split_whitespace().collect();
    if fields.len() < 5 || fields[0] != "cpu" {
        anyhow::bail!("unexpected /proc/stat format");
    }

    let mut values = Vec::new();
    for field in fields.iter().skip(1) {
        values.push(field.parse::<u64>()?);
    }

    let idle = values.get(3).copied().unwrap_or(0) + values.get(4).copied().unwrap_or(0);
    let total: u64 = values.iter().sum();

    Ok(CpuSample { total, idle })
}

fn calculate_cpu_usage(prev: CpuSample, current: CpuSample) -> f64 {
    let total_delta = current.total.saturating_sub(prev.total);
    let idle_delta = current.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    let used = total_delta.saturating_sub(idle_delta);
    (used as f64 / total_delta as f64) * 100.0
}

struct MemInfo {
    mem_total_kb: u64,
    mem_available_kb: u64,
    mem_used_kb: u64,
}

async fn read_meminfo() -> Result<MemInfo> {
    let meminfo = read_file("/proc/meminfo").await?;
    let mut mem_total_kb = None;
    let mut mem_available_kb = None;

    for line in meminfo.lines() {
        if let Some(value) = line.strip_prefix("MemTotal:") {
            mem_total_kb = extract_kb(value);
        } else if let Some(value) = line.strip_prefix("MemAvailable:") {
            mem_available_kb = extract_kb(value);
        }
    }

    let mem_total_kb = mem_total_kb.context("MemTotal missing")?;
    let mem_available_kb = mem_available_kb.context("MemAvailable missing")?;
    let mem_used_kb = mem_total_kb.saturating_sub(mem_available_kb);

    Ok(MemInfo {
        mem_total_kb,
        mem_available_kb,
        mem_used_kb,
    })
}

fn extract_kb(s: &str) -> Option<u64> {
    s.split_whitespace().next()?.parse().ok()
}

async fn read_loadavg() -> Result<(f64, f64, f64)> {
    let loadavg = read_file("/proc/loadavg").await?;
    let fields: Vec<&str> = loadavg.split_whitespace().collect();

    if fields.len() < 3 {
        anyhow::bail!("unexpected /proc/loadavg format");
    }

    let load1 = fields[0].parse::<f64>()?;
    let load5 = fields[1].parse::<f64>()?;
    let load15 = fields[2].parse::<f64>()?;

    Ok((load1, load5, load15))
}
