```rust
use anyhow::{Context, Result};
use daemonize::Daemonize;
use log::{error, info, warn};
use nix::sys::signal;
use nix::sys::signal::{SigHandler, Signal};
use std::fs::File;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use std::time::Duration;
use sysinfo::{Disks, LoadAvg, System};

static RUNNING: AtomicBool = AtomicBool::new(true);

extern "C" fn handle_signal(_: i32) {
    RUNNING.store(false, Ordering::SeqCst);
}

fn install_signal_handlers() -> Result<()> {
    unsafe {
        signal::signal(Signal::SIGTERM, SigHandler::Handler(handle_signal))
            .context("failed to install SIGTERM handler")?;
        signal::signal(Signal::SIGINT, SigHandler::Handler(handle_signal))
            .context("failed to install SIGINT handler")?;
    }
    Ok(())
}

fn setup_logging(daemon_mode: bool) -> Result<()> {
    if daemon_mode {
        let log_file = File::create("/tmp/sysmond.log")
            .context("failed to create log file /tmp/sysmond.log")?;
        simplelog::WriteLogger::init(
            log::LevelFilter::Info,
            simplelog::Config::default(),
            log_file,
        )
        .context("failed to initialize file logger")?;
    } else {
        simplelog::TermLogger::init(
            log::LevelFilter::Info,
            simplelog::Config::default(),
            simplelog::TerminalMode::Mixed,
            simplelog::ColorChoice::Auto,
        )
        .or_else(|_| {
            simplelog::SimpleLogger::init(
                log::LevelFilter::Info,
                simplelog::Config::default(),
            )
        })
        .context("failed to initialize logger")?;
    }
    Ok(())
}

fn daemonize_process() -> Result<()> {
    let stdout = File::create("/tmp/sysmond.out").context("failed to create stdout log")?;
    let stderr = File::create("/tmp/sysmond.err").context("failed to create stderr log")?;

    Daemonize::new()
        .pid_file("/tmp/sysmond.pid")
        .working_directory("/")
        .stdout(stdout)
        .stderr(stderr)
        .start()
        .context("failed to daemonize")?;
    Ok(())
}

fn check_resources(sys: &mut System, disks: &mut Disks) {
    sys.refresh_memory();
    sys.refresh_cpu();
    disks.refresh();

    let LoadAvg { one, five, fifteen } = System::load_average();

    let total_mem = sys.total_memory();
    let avail_mem = sys.available_memory();
    let used_mem = total_mem.saturating_sub(avail_mem);

    info!(
        "loadavg: {:.2} {:.2} {:.2}, memory: used={} MiB avail={} MiB total={} MiB",
        one,
        five,
        fifteen,
        used_mem / 1024 / 1024,
        avail_mem / 1024 / 1024,
        total_mem / 1024 / 1024
    );

    if total_mem > 0 {
        let avail_pct = (avail_mem as f64 / total_mem as f64) * 100.0;
        if avail_pct < 10.0 {
            warn!("low available memory: {:.2}% remaining", avail_pct);
        }
    }

    for disk in disks.list() {
        let mount = disk.mount_point().to_string_lossy();
        let total = disk.total_space();
        let avail = disk.available_space();
        let used = total.saturating_sub(avail);
        let used_pct = if total > 0 {
            (used as f64 / total as f64) * 100.0
        } else {
            0.0
        };

        info!(
            "disk mount={} used={} MiB avail={} MiB total={} MiB used_pct={:.2}",
            mount,
            used / 1024 / 1024,
            avail / 1024 / 1024,
            total / 1024 / 1024,
            used_pct
        );

        if mount == "/" && used_pct > 90.0 {
            warn!("root filesystem usage high: {:.2}%", used_pct);
        }
    }
}

fn main() -> Result<()> {
    let daemon_mode = std::env::args().any(|a| a == "--daemon");

    if daemon_mode {
        daemonize_process()?;
    }

    setup_logging(daemon_mode)?;
    install_signal_handlers()?;

    info!("sysmond starting");

    let mut sys = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    while RUNNING.load(Ordering::SeqCst) {
        check_resources(&mut sys, &mut disks);
        thread::sleep(Duration::from_secs(5));
    }

    info!("sysmond shutting down");
    Ok(())
}
```

