use std::fs;
use std::io;
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::Duration;

#[derive(Debug, Clone, Copy)]
struct CpuTimes {
    total: u64,
    idle: u64,
}

fn read_to_string<P: AsRef<Path>>(path: P) -> io::Result<String> {
    fs::read_to_string(path)
}

fn read_cpu_times() -> io::Result<CpuTimes> {
    let content = read_to_string("/proc/stat")?;
    let first_line = content
        .lines()
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "missing /proc/stat data"))?;

    let mut parts = first_line.split_whitespace();
    let label = parts
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "invalid /proc/stat format"))?;

    if label != "cpu" {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "first line of /proc/stat is not cpu",
        ));
    }

    let values: Vec<u64> = parts
        .map(|p| {
            p.parse::<u64>()
                .map_err(|_| io::Error::new(io::ErrorKind::Other, "invalid cpu number"))
        })
        .collect::<io::Result<Vec<_>>>()?;

    if values.len() < 4 {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "not enough cpu fields",
        ));
    }

    let idle = values[3] + values.get(4).copied().unwrap_or(0);
    let total: u64 = values.iter().sum();

    Ok(CpuTimes { total, idle })
}

fn cpu_usage_percent(prev: CpuTimes, curr: CpuTimes) -> f64 {
    let total_delta = curr.total.saturating_sub(prev.total);
    let idle_delta = curr.idle.saturating_sub(prev.idle);

    if total_delta == 0 {
        return 0.0;
    }

    100.0 * (total_delta - idle_delta) as f64 / total_delta as f64
}

fn read_meminfo() -> io::Result<(u64, u64)> {
    let content = read_to_string("/proc/meminfo")?;
    let mut total_kb = None;
    let mut available_kb = None;

    for line in content.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line
                .split_whitespace()
                .nth(1)
                .and_then(|v| v.parse::<u64>().ok());
        } else if line.starts_with("MemAvailable:") {
            available_kb = line
                .split_whitespace()
                .nth(1)
                .and_then(|v| v.parse::<u64>().ok());
        }
    }

    match (total_kb, available_kb) {
        (Some(total), Some(avail)) => Ok((total, avail)),
        _ => Err(io::Error::new(
            io::ErrorKind::Other,
            "failed to parse /proc/meminfo",
        )),
    }
}

fn read_loadavg() -> io::Result<(f64, f64, f64)> {
    let content = read_to_string("/proc/loadavg")?;
    let mut parts = content.split_whitespace();

    let one = parts
        .next()
        .and_then(|v| v.parse::<f64>().ok())
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "invalid loadavg 1m"))?;
    let five = parts
        .next()
        .and_then(|v| v.parse::<f64>().ok())
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "invalid loadavg 5m"))?;
    let fifteen = parts
        .next()
        .and_then(|v| v.parse::<f64>().ok())
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "invalid loadavg 15m"))?;

    Ok((one, five, fifteen))
}

fn read_disk_free_percent() -> io::Result<f64> {
    let output = std::process::Command::new("df")
        .args(["-P", "/"])
        .output()?;

    if !output.status.success() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "df command failed",
        ));
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let line = stdout
        .lines()
        .nth(1)
        .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "missing df output line"))?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 6 {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "unexpected df output",
        ));
    }

    let used_percent_str = parts[4].trim_end_matches('%');
    let used_percent: f64 = used_percent_str
        .parse()
        .map_err(|_| io::Error::new(io::ErrorKind::Other, "invalid disk usage percent"))?;

    Ok(100.0 - used_percent)
}

fn log_info(msg: &str) {
    eprintln!("[INFO] {}", msg);
}

fn log_warn(msg: &str) {
    eprintln!("[WARN] {}", msg);
}

fn log_error(msg: &str) {
    eprintln!("[ERROR] {}", msg);
}

fn main() -> io::Result<()> {
    let running = Arc::new(AtomicBool::new(true));
    let signal_flag = Arc::clone(&running);

    ctrlc::set_handler(move || {
        signal_flag.store(false, Ordering::SeqCst);
    })
    .map_err(|e| io::Error::new(io::ErrorKind::Other, format!("signal handler error: {e}")))?;

    log_info("sysmon-daemon starting");

    let mut prev_cpu = read_cpu_times()?;
    thread::sleep(Duration::from_secs(1));

    while running.load(Ordering::SeqCst) {
        let curr_cpu = match read_cpu_times() {
            Ok(v) => v,
            Err(e) => {
                log_error(&format!("failed to read cpu stats: {e}"));
                thread::sleep(Duration::from_secs(2));
                continue;
            }
        };

        let cpu = cpu_usage_percent(prev_cpu, curr_cpu);
        prev_cpu = curr_cpu;

        let (mem_total, mem_avail) = match read_meminfo() {
            Ok(v) => v,
            Err(e) => {
                log_error(&format!("failed to read memory stats: {e}"));
                thread::sleep(Duration::from_secs(2));
                continue;
            }
        };

        let mem_used_percent = if mem_total == 0 {
            0.0
        } else {
            100.0 * (mem_total - mem_avail) as f64 / mem_total as f64
        };

        let (load1, load5, load15) = match read_loadavg() {
            Ok(v) => v,
            Err(e) => {
                log_error(&format!("failed to read load average: {e}"));
                thread::sleep(Duration::from_secs(2));
                continue;
            }
        };

        let disk_free = match read_disk_free_percent() {
            Ok(v) => v,
            Err(e) => {
                log_error(&format!("failed to read disk free space: {e}"));
                thread::sleep(Duration::from_secs(2));
                continue;
            }
        };

        log_info(&format!(
            "cpu={:.1}% mem_used={:.1}% load=({:.2},{:.2},{:.2}) disk_free={:.1}%",
            cpu, mem_used_percent, load1, load5, load15, disk_free
        ));

        if mem_used_percent > 90.0 {
            log_warn("memory usage above 90%");
        }

        if disk_free < 10.0 {
            log_warn("disk free space below 10%");
        }

        thread::sleep(Duration::from_secs(5));
    }

    log_info("sysmon-daemon shutting down");
    Ok(())
}
```

