### `src/main.rs`
```rust
use std::fs;
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::Duration;

const SOCKET_PATH: &str = "/tmp/sysmond.sock";

#[derive(Debug, Clone)]
struct State {
    cpu_usage_percent: f64,
    mem_usage_percent: f64,
    mem_threshold_percent: f64,
}

impl State {
    fn new() -> Self {
        Self {
            cpu_usage_percent: 0.0,
            mem_usage_percent: 0.0,
            mem_threshold_percent: 80.0,
        }
    }
}

#[derive(Debug, Copy, Clone)]
struct CpuSample {
    idle: u64,
    total: u64,
}

fn read_cpu_sample() -> std::io::Result<CpuSample> {
    let content = fs::read_to_string("/proc/stat")?;
    let first = content
        .lines()
        .next()
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::Other, "missing /proc/stat data"))?;

    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "unexpected /proc/stat format",
        ));
    }

    let user: u64 = parts[1].parse().unwrap_or(0);
    let nice: u64 = parts[2].parse().unwrap_or(0);
    let system: u64 = parts[3].parse().unwrap_or(0);
    let idle: u64 = parts[4].parse().unwrap_or(0);
    let iowait: u64 = parts.get(5).and_then(|v| v.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|v| v.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|v| v.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|v| v.parse().ok()).unwrap_or(0);

    let idle_all = idle + iowait;
    let total = user + nice + system + idle + iowait + irq + softirq + steal;

    Ok(CpuSample {
        idle: idle_all,
        total,
    })
}

fn cpu_usage(prev: CpuSample, curr: CpuSample) -> f64 {
    let totald = curr.total.saturating_sub(prev.total) as f64;
    let idled = curr.idle.saturating_sub(prev.idle) as f64;

    if totald <= 0.0 {
        0.0
    } else {
        ((totald - idled) / totald) * 100.0
    }
}

fn memory_usage_percent() -> std::io::Result<f64> {
    let content = fs::read_to_string("/proc/meminfo")?;
    let mut total_kb = 0.0;
    let mut available_kb = 0.0;

    for line in content.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line
                .split_whitespace()
                .nth(1)
                .and_then(|v| v.parse::<f64>().ok())
                .unwrap_or(0.0);
        } else if line.starts_with("MemAvailable:") {
            available_kb = line
                .split_whitespace()
                .nth(1)
                .and_then(|v| v.parse::<f64>().ok())
                .unwrap_or(0.0);
        }
    }

    if total_kb <= 0.0 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "invalid MemTotal",
        ));
    }

    let used = total_kb - available_kb;
    Ok((used / total_kb) * 100.0)
}

fn handle_client(
    mut stream: UnixStream,
    state: Arc<Mutex<State>>,
    running: Arc<AtomicBool>,
) -> std::io::Result<()> {
    let mut line = String::new();
    {
        let mut reader = BufReader::new(&stream);
        reader.read_line(&mut line)?;
    }

    let cmd = line.trim();
    let response = if cmd == "status" {
        let st = state.lock().unwrap().clone();
        format!(
            "cpu={:.2}% mem={:.2}% threshold={:.2}%\n",
            st.cpu_usage_percent, st.mem_usage_percent, st.mem_threshold_percent
        )
    } else if let Some(value) = cmd.strip_prefix("set-threshold ") {
        match value.parse::<f64>() {
            Ok(v) if (0.0..=100.0).contains(&v) => {
                let mut st = state.lock().unwrap();
                st.mem_threshold_percent = v;
                format!("ok threshold={:.2}%\n", v)
            }
            _ => "error invalid threshold\n".to_string(),
        }
    } else if cmd == "quit" {
        running.store(false, Ordering::SeqCst);
        "shutting down\n".to_string()
    } else {
        "error unknown command\n".to_string()
    };

    stream.write_all(response.as_bytes())?;
    stream.flush()?;
    Ok(())
}

fn start_socket_server(
    state: Arc<Mutex<State>>,
    running: Arc<AtomicBool>,
) -> std::io::Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;
    listener.set_nonblocking(true)?;

    eprintln!("socket listening at {}", SOCKET_PATH);

    while running.load(Ordering::SeqCst) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let st = Arc::clone(&state);
                let run = Arc::clone(&running);
                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, st, run) {
                        eprintln!("client error: {}", e);
                    }
                });
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(e) => {
                eprintln!("socket accept error: {}", e);
                thread::sleep(Duration::from_millis(200));
            }
        }
    }

    let _ = fs::remove_file(SOCKET_PATH);
    Ok(())
}

fn start_monitor(state: Arc<Mutex<State>>, running: Arc<AtomicBool>) -> std::io::Result<()> {
    let mut prev = read_cpu_sample()?;

    while running.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_secs(1));

        let curr = match read_cpu_sample() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("cpu read error: {}", e);
                continue;
            }
        };

        let cpu = cpu_usage(prev, curr);
        prev = curr;

        let mem = match memory_usage_percent() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("memory read error: {}", e);
                continue;
            }
        };

        let mut st = state.lock().unwrap();
        st.cpu_usage_percent = cpu;
        st.mem_usage_percent = mem;

        if st.mem_usage_percent >= st.mem_threshold_percent {
            eprintln!(
                "warning: memory usage {:.2}% exceeded threshold {:.2}%",
                st.mem_usage_percent, st.mem_threshold_percent
            );
        }

        println!(
            "cpu={:.2}% mem={:.2}% threshold={:.2}%",
            st.cpu_usage_percent, st.mem_usage_percent, st.mem_threshold_percent
        );
    }

    Ok(())
}

fn main() -> std::io::Result<()> {
    let state = Arc::new(Mutex::new(State::new()));
    let running = Arc::new(AtomicBool::new(true));

    let monitor_state = Arc::clone(&state);
    let monitor_running = Arc::clone(&running);
    let monitor_thread = thread::spawn(move || start_monitor(monitor_state, monitor_running));

    let server_result = start_socket_server(Arc::clone(&state), Arc::clone(&running));

    running.store(false, Ordering::SeqCst);

    let monitor_result = monitor_thread
        .join()
        .unwrap_or_else(|_| Err(std::io::Error::new(std::io::ErrorKind::Other, "monitor thread panicked")));

    server_result?;
    monitor_result?;

    eprintln!("daemon exited");
    Ok(())
}
