use std::{
    fs::OpenOptions,
    io::Write,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    thread,
    time::Duration,
};

use sysinfo::System;

fn log_line(msg: &str) {
    let path = "/tmp/sys_daemon.log";
    if let Ok(mut file) = OpenOptions::new().create(true).append(true).open(path) {
        let _ = writeln!(file, "{}", msg);
    }
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let r = Arc::clone(&running);

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    })
    .expect("failed to set signal handler");

    log_line("sys_daemon starting");

    let mut sys = System::new_all();

    while running.load(Ordering::SeqCst) {
        sys.refresh_memory();
        sys.refresh_cpu();

        let total_mem = sys.total_memory();
        let used_mem = sys.used_memory();
        let mem_percent = if total_mem > 0 {
            (used_mem as f64 / total_mem as f64) * 100.0
        } else {
            0.0
        };

        let cpu_percent = sys.global_cpu_info().cpu_usage();

        let line = format!(
            "cpu={:.2}% mem={:.2}% used_mem={} total_mem={}",
            cpu_percent, mem_percent, used_mem, total_mem
        );
        log_line(&line);

        if mem_percent > 90.0 {
            log_line("warning: high memory usage detected");
            // Minimal "management" action:
            // In a real daemon, this could trigger alerts, reclaim caches,
            // restart a managed service, or apply policy-based throttling.
        }

        thread::sleep(Duration::from_secs(2));
    }

    log_line("sys_daemon shutting down");
}
