use nix::sys::signal::{kill, Signal};
use nix::unistd::{daemon, getpid, Pid};
use std::fs::{remove_file, File, OpenOptions};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::Duration;

const PID_FILE: &str = "/tmp/sysmon_daemon.pid";
const SOCK_FILE: &str = "/tmp/sysmon_daemon.sock";

#[derive(Debug, Clone)]
struct State {
    interval_secs: u64,
    last_cpu_percent: f64,
    mem_total_kb: u64,
    mem_available_kb: u64,
}

impl State {
    fn new() -> Self {
        Self {
            interval_secs: 2,
            last_cpu_percent: 0.0,
            mem_total_kb: 0,
            mem_available_kb: 0,
        }
    }
}

fn write_pid_file() -> std::io::Result<()> {
    let mut f = File::create(PID_FILE)?;
    writeln!(f, "{}", getpid())?;
    Ok(())
}

fn remove_pid_file() {
    let _ = remove_file(PID_FILE);
}

fn read_cpu_times() -> std::io::Result<(u64, u64)> {
    let mut s = String::new();
    File::open("/proc/stat")?.read_to_string(&mut s)?;
    let first = s.lines().next().unwrap_or("");
    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(std::io::Error::new(std::io::ErrorKind::Other, "invalid /proc/stat"));
    }

    let user: u64 = parts[1].parse().unwrap_or(0);
    let nice: u64 = parts[2].parse().unwrap_or(0);
    let system: u64 = parts[3].parse().unwrap_or(0);
    let idle: u64 = parts[4].parse().unwrap_or(0);
    let iowait: u64 = parts.get(5).and_then(|v| v.parse().ok()).unwrap_or(0);
    let irq: u64 = parts.get(6).and_then(|v| v.parse().ok()).unwrap_or(0);
    let softirq: u64 = parts.get(7).and_then(|v| v.parse().ok()).unwrap_or(0);
    let steal: u64 = parts.get(8).and_then(|v| v.parse().ok()).unwrap_or(0);

    let idle_all = idle + iowait;
    let total = user + nice + system + idle + iowait + irq + softirq + steal;
    Ok((idle_all, total))
}

fn read_mem_info() -> std::io::Result<(u64, u64)> {
    let file = File::open("/proc/meminfo")?;
    let reader = BufReader::new(file);

    let mut total = 0;
    let mut available = 0;

    for line in reader.lines() {
        let line = line?;
        if line.starts_with("MemTotal:") {
            total = line.split_whitespace().nth(1).and_then(|v| v.parse().ok()).unwrap_or(0);
        } else if line.starts_with("MemAvailable:") {
            available = line.split_whitespace().nth(1).and_then(|v| v.parse().ok()).unwrap_or(0);
        }
    }

    Ok((total, available))
}

fn handle_client(mut stream: UnixStream, state: Arc<Mutex<State>>, running: Arc<AtomicBool>) {
    let mut buf = String::new();
    let _ = stream.read_to_string(&mut buf);
    let cmd = buf.trim();

    let response = if cmd == "status" {
        let st = state.lock().unwrap().clone();
        format!(
            "ok cpu={:.2}% mem_total_kb={} mem_available_kb={} interval_secs={}\n",
            st.last_cpu_percent, st.mem_total_kb, st.mem_available_kb, st.interval_secs
        )
    } else if let Some(rest) = cmd.strip_prefix("set interval ") {
        match rest.trim().parse::<u64>() {
            Ok(v) if v > 0 => {
                let mut st = state.lock().unwrap();
                st.interval_secs = v;
                format!("ok interval_secs={}\n", v)
            }
            _ => "error invalid interval\n".to_string(),
        }
    } else if cmd == "quit" {
        running.store(false, Ordering::SeqCst);
        "ok shutting down\n".to_string()
    } else {
        "error unknown command\n".to_string()
    };

    let _ = stream.write_all(response.as_bytes());
}

fn start_socket_server(state: Arc<Mutex<State>>, running: Arc<AtomicBool>) -> std::io::Result<()> {
    if Path::new(SOCK_FILE).exists() {
        let _ = remove_file(SOCK_FILE);
    }

    let listener = UnixListener::bind(SOCK_FILE)?;
    listener.set_nonblocking(true)?;

    while running.load(Ordering::SeqCst) {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let s = Arc::clone(&state);
                let r = Arc::clone(&running);
                thread::spawn(move || handle_client(stream, s, r));
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(100));
            }
            Err(e) => {
                eprintln!("socket accept error: {}", e);
                break;
            }
        }
    }

    let _ = remove_file(SOCK_FILE);
    Ok(())
}

fn monitor_loop(state: Arc<Mutex<State>>, running: Arc<AtomicBool>) {
    let mut prev = match read_cpu_times() {
        Ok(v) => v,
        Err(e) => {
            eprintln!("failed to read cpu times: {}", e);
            return;
        }
    };

    while running.load(Ordering::SeqCst) {
        let interval = {
            let st = state.lock().unwrap();
            st.interval_secs
        };

        thread::sleep(Duration::from_secs(interval));

        let curr = match read_cpu_times() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("failed to read cpu times: {}", e);
                continue;
            }
        };

        let (prev_idle, prev_total) = prev;
        let (curr_idle, curr_total) = curr;

        let totald = curr_total.saturating_sub(prev_total);
        let idled = curr_idle.saturating_sub(prev_idle);
        let cpu_percent = if totald > 0 {
            100.0 * (totald - idled) as f64 / totald as f64
        } else {
            0.0
        };

        let (mem_total, mem_avail) = match read_mem_info() {
            Ok(v) => v,
            Err(e) => {
                eprintln!("failed to read mem info: {}", e);
                (0, 0)
            }
        };

        {
            let mut st = state.lock().unwrap();
            st.last_cpu_percent = cpu_percent;
            st.mem_total_kb = mem_total;
            st.mem_available_kb = mem_avail;
        }

        println!(
            "sample cpu={:.2}% mem_total_kb={} mem_available_kb={}",
            cpu_percent, mem_total, mem_avail
        );

        prev = curr;
    }
}

fn stop_existing_instance_if_any() {
    if let Ok(pid_str) = std::fs::read_to_string(PID_FILE) {
        if let Ok(pid_num) = pid_str.trim().parse::<i32>() {
            let pid = Pid::from_raw(pid_num);
            if kill(pid, None).is_ok() {
                eprintln!("daemon already running with pid {}", pid_num);
                std::process::exit(1);
            } else {
                let _ = remove_file(PID_FILE);
            }
        }
    }
}

fn main() -> std::io::Result<()> {
    stop_existing_instance_if_any();

    daemon(false, false).expect("failed to daemonize");
    write_pid_file()?;

    let running = Arc::new(AtomicBool::new(true));
    let state = Arc::new(Mutex::new(State::new()));

    let monitor_running = Arc::clone(&running);
    let monitor_state = Arc::clone(&state);
    let monitor_thread = thread::spawn(move || {
        monitor_loop(monitor_state, monitor_running);
    });

    let socket_result = start_socket_server(Arc::clone(&state), Arc::clone(&running));

    running.store(false, Ordering::SeqCst);
    let _ = monitor_thread.join();

    remove_pid_file();
    socket_result
}
```

