```rust
use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::fs::File;
use std::io::{BufRead, BufReader};

#[derive(Debug, Clone)]
struct FlowRecord {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    protocol: String,
    packets: u64,
    bytes: u64,
}

fn parse_line(line: &str) -> Option<FlowRecord> {
    let parts: Vec<&str> = line.split(',').map(|s| s.trim()).collect();
    if parts.len() != 7 {
        return None;
    }

    Some(FlowRecord {
        src_ip: parts[0].to_string(),
        dst_ip: parts[1].to_string(),
        src_port: parts[2].parse().ok()?,
        dst_port: parts[3].parse().ok()?,
        protocol: parts[4].to_string(),
        packets: parts[5].parse().ok()?,
        bytes: parts[6].parse().ok()?,
    })
}

fn print_top_n(title: &str, map: &HashMap<String, u64>, n: usize) {
    let mut items: Vec<(&String, &u64)> = map.iter().collect();
    items.sort_by(|a, b| b.1.cmp(a.1));

    println!("\n{title}");
    for (k, v) in items.into_iter().take(n) {
        println!("{k:20} {v}");
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <flows.csv>", args[0]);
        eprintln!("CSV format: src_ip,dst_ip,src_port,dst_port,protocol,packets,bytes");
        std::process::exit(1);
    }

    let file = File::open(&args[1])?;
    let reader = BufReader::new(file);

    let mut total_flows = 0u64;
    let mut total_packets = 0u64;
    let mut total_bytes = 0u64;

    let mut bytes_by_src: HashMap<String, u64> = HashMap::new();
    let mut bytes_by_dst: HashMap<String, u64> = HashMap::new();
    let mut bytes_by_proto: HashMap<String, u64> = HashMap::new();
    let mut bytes_by_service: HashMap<String, u64> = HashMap::new();

    for (idx, line) in reader.lines().enumerate() {
        let line = line?;
        if idx == 0 && line.contains("src_ip") {
            continue;
        }

        let Some(flow) = parse_line(&line) else {
            eprintln!("Skipping malformed line {}: {}", idx + 1, line);
            continue;
        };

        total_flows += 1;
        total_packets += flow.packets;
        total_bytes += flow.bytes;

        *bytes_by_src.entry(flow.src_ip.clone()).or_insert(0) += flow.bytes;
        *bytes_by_dst.entry(flow.dst_ip.clone()).or_insert(0) += flow.bytes;
        *bytes_by_proto.entry(flow.protocol.clone()).or_insert(0) += flow.bytes;

        let service = format!("{}/{}", flow.protocol, flow.dst_port);
        *bytes_by_service.entry(service).or_insert(0) += flow.bytes;
    }

    println!("Total flows:   {}", total_flows);
    println!("Total packets: {}", total_packets);
    println!("Total bytes:   {}", total_bytes);

    print_top_n("Top source IPs by bytes", &bytes_by_src, 10);
    print_top_n("Top destination IPs by bytes", &bytes_by_dst, 10);
    print_top_n("Top protocols by bytes", &bytes_by_proto, 10);
    print_top_n("Top services by bytes", &bytes_by_service, 10);

    Ok(())
}
```

