Below is a compact, high-level skeleton in <language>C</language> suitable for a high-performance network flow analyzer. It captures packets via AF_PACKET/TPACKET_V3, parses Ethernet/IPv4/TCP/UDP, maintains a sharded flow table, and prints periodic stats. It is not production-complete, but it is a solid starting point for gigabit-scale monitoring.

```c
// flowmon.c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <pthread.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/poll.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef TPACKET_V3
#define TPACKET_V3 2
#endif

#define RX_BLOCKS       64
#define RX_BLOCK_SIZE   (1 << 20)   // 1 MiB
#define RX_FRAME_SIZE   2048
#define FLOW_SHARDS     64
#define FLOW_BUCKETS    (1 << 20)   // per shard
#define FLOW_TIMEOUT_S  60

static volatile sig_atomic_t g_stop = 0;

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t last_seen_sec;
    struct flow_entry *next;
} flow_entry_t;

typedef struct {
    pthread_mutex_t lock;
    flow_entry_t **buckets;
} flow_shard_t;

typedef struct {
    atomic_uint_fast64_t pkts;
    atomic_uint_fast64_t bytes;
    atomic_uint_fast64_t ipv4;
    atomic_uint_fast64_t tcp;
    atomic_uint_fast64_t udp;
    atomic_uint_fast64_t other;
    atomic_uint_fast64_t drops;
} stats_t;

static flow_shard_t g_shards[FLOW_SHARDS];
static stats_t g_stats;

static uint64_t now_sec(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec;
}

static uint64_t hash_flow(const flow_key_t *k) {
    uint64_t x = 1469598103934665603ull;
    const unsigned char *p = (const unsigned char *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        x ^= p[i];
        x *= 1099511628211ull;
    }
    return x;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static void flow_update(const flow_key_t *key, uint32_t len) {
    uint64_t h = hash_flow(key);
    uint32_t shard_id = h % FLOW_SHARDS;
    uint32_t bucket_id = (h / FLOW_SHARDS) & (FLOW_BUCKETS - 1);

    flow_shard_t *sh = &g_shards[shard_id];
    pthread_mutex_lock(&sh->lock);

    flow_entry_t *e = sh->buckets[bucket_id];
    while (e) {
        if (flow_equal(&e->key, key)) {
            e->packets++;
            e->bytes += len;
            e->last_seen_sec = now_sec();
            pthread_mutex_unlock(&sh->lock);
            return;
        }
        e = e->next;
    }

    e = calloc(1, sizeof(*e));
    if (e) {
        e->key = *key;
        e->packets = 1;
        e->bytes = len;
        e->last_seen_sec = now_sec();
        e->next = sh->buckets[bucket_id];
        sh->buckets[bucket_id] = e;
    }

    pthread_mutex_unlock(&sh->lock);
}

static void expire_flows(void) {
    uint64_t t = now_sec();
    for (uint32_t s = 0; s < FLOW_SHARDS; s++) {
        flow_shard_t *sh = &g_shards[s];
        pthread_mutex_lock(&sh->lock);
        for (uint32_t b = 0; b < FLOW_BUCKETS; b++) {
            flow_entry_t **pp = &sh->buckets[b];
            while (*pp) {
                flow_entry_t *e = *pp;
                if (t - e->last_seen_sec > FLOW_TIMEOUT_S) {
                    *pp = e->next;
                    free(e);
                } else {
                    pp = &e->next;
                }
            }
        }
        pthread_mutex_unlock(&sh->lock);
    }
}

static void parse_packet(const uint8_t *buf, uint32_t len) {
    atomic_fetch_add_explicit(&g_stats.pkts, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&g_stats.bytes, len, memory_order_relaxed);

    if (len < sizeof(struct ethhdr)) return;
    const struct ethhdr *eth = (const struct ethhdr *)buf;

    if (ntohs(eth->h_proto) != ETH_P_IP) {
        atomic_fetch_add_explicit(&g_stats.other, 1, memory_order_relaxed);
        return;
    }

    const uint8_t *ipbuf = buf + sizeof(struct ethhdr);
    uint32_t iplen = len - sizeof(struct ethhdr);
    if (iplen < sizeof(struct iphdr)) return;

    const struct iphdr *ip = (const struct iphdr *)ipbuf;
    if (ip->version != 4) return;
    uint32_t ihl = ip->ihl * 4;
    if (ihl < sizeof(struct iphdr) || iplen < ihl) return;

    atomic_fetch_add_explicit(&g_stats.ipv4, 1, memory_order_relaxed);

    flow_key_t key = {0};
    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto  = ip->protocol;

    const uint8_t *l4 = ipbuf + ihl;
    uint32_t l4len = iplen - ihl;

    if (ip->protocol == IPPROTO_TCP) {
        if (l4len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
        atomic_fetch_add_explicit(&g_stats.tcp, 1, memory_order_relaxed);
    } else if (ip->protocol == IPPROTO_UDP) {
        if (l4len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
        atomic_fetch_add_explicit(&g_stats.udp, 1, memory_order_relaxed);
    } else {
        atomic_fetch_add_explicit(&g_stats.other, 1, memory_order_relaxed);
    }

    flow_update(&key, len);
}

typedef struct {
    int fd;
    void *ring;
    size_t ring_sz;
} rx_ring_t;

static int setup_socket(const char *ifname, rx_ring_t *rx) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int ver = TPACKET_V3;
    if (setsockopt(fd, SOL_PACKET, PACKET_VERSION, &ver, sizeof(ver)) < 0) {
        perror("PACKET_VERSION");
        close(fd);
        return -1;
    }

    struct tpacket_req3 req = {0};
    req.tp_block_size = RX_BLOCK_SIZE;
    req.tp_frame_size = RX_FRAME_SIZE;
    req.tp_block_nr   = RX_BLOCKS;
    req.tp_frame_nr   = (RX_BLOCK_SIZE * RX_BLOCKS) / RX_FRAME_SIZE;
    req.tp_retire_blk_tov = 60;

    if (setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
        perror("PACKET_RX_RING");
        close(fd);
        return -1;
    }

    rx->ring_sz = req.tp_block_size * req.tp_block_nr;
    rx->ring = mmap(NULL, rx->ring_sz, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, fd, 0);
    if (rx->ring == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return -1;
    }

    struct sockaddr_ll sll = {0};
    sll.sll_family   = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex  = if_nametoindex(ifname);

    if (!sll.sll_ifindex) {
        perror("if_nametoindex");
        munmap(rx->ring, rx->ring_sz);
        close(fd);
        return -1;
    }

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        munmap(rx->ring, rx->ring_sz);
        close(fd);
        return -1;
    }

    rx->fd = fd;
    return 0;
}

static void process_ring(rx_ring_t *rx) {
    struct pollfd pfd = {.fd = rx->fd, .events = POLLIN};
    uint32_t block_num = 0;

    while (!g_stop) {
        uint8_t *base = (uint8_t *)rx->ring;
        struct tpacket_block_desc *bd =
            (struct tpacket_block_desc *)(base + (block_num * RX_BLOCK_SIZE));

        if (!(bd->hdr.bh1.block_status & TP_STATUS_USER)) {
            poll(&pfd, 1, 100);
            continue;
        }

        uint32_t num_pkts = bd->hdr.bh1.num_pkts;
        uint32_t offset = bd->hdr.bh1.offset_to_first_pkt;

        for (uint32_t i = 0; i < num_pkts; i++) {
            struct tpacket3_hdr *ppd = (struct tpacket3_hdr *)((uint8_t *)bd + offset);
            const uint8_t *pkt = (const uint8_t *)ppd + ppd->tp_mac;
            parse_packet(pkt, ppd->tp_snaplen);
            offset += ppd->tp_next_offset;
        }

        bd->hdr.bh1.block_status = TP_STATUS_KERNEL;
        block_num = (block_num + 1) % RX_BLOCKS;
    }
}

static void *stats_thread(void *arg) {
    (void)arg;
    while (!g_stop) {
        sleep(1);
        uint64_t pkts  = atomic_load_explicit(&g_stats.pkts, memory_order_relaxed);
        uint64_t bytes = atomic_load_explicit(&g_stats.bytes, memory_order_relaxed);
        uint64_t ipv4  = atomic_load_explicit(&g_stats.ipv4, memory_order_relaxed);
        uint64_t tcp   = atomic_load_explicit(&g_stats.tcp, memory_order_relaxed);
        uint64_t udp   = atomic_load_explicit(&g_stats.udp, memory_order_relaxed);
        fprintf(stderr,
                "pkts=%lu bytes=%lu ipv4=%lu tcp=%lu udp=%lu\n",
                pkts, bytes, ipv4, tcp, udp);
        expire_flows();
    }
    return NULL;
}

static void on_sigint(int signo) {
    (void)signo;
    g_stop = 1;
}

static int init_flow_table(void) {
    for (uint32_t i = 0; i < FLOW_SHARDS; i++) {
        if (pthread_mutex_init(&g_shards[i].lock, NULL) != 0) return -1;
        g_shards[i].buckets = calloc(FLOW_BUCKETS, sizeof(flow_entry_t *));
        if (!g_shards[i].buckets) return -1;
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <interface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    if (init_flow_table() != 0) {
        fprintf(stderr, "flow table init failed\n");
        return 1;
    }

    rx_ring_t rx = {0};
    if (setup_socket(argv[1], &rx) != 0) {
        return 1;
    }

    pthread_t stid;
    pthread_create(&stid, NULL, stats_thread, NULL);

    process_ring(&rx);

    pthread_join(stid, NULL);
    munmap(rx.ring, rx.ring_sz);
    close(rx.fd);
    return 0;
}
