```rust
use std::{
    collections::HashMap,
    io,
    net::{SocketAddr, UdpSocket},
    sync::{Arc, Mutex},
    thread,
    time::{Duration, Instant},
};

#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Default, Clone, Copy)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_unix_s: u64,
    last_seen_unix_s: u64,
}

fn parse_record(buf: &[u8]) -> Option<(FlowKey, FlowStats)> {
    if buf.len() < 29 {
        return None;
    }

    let src_ip = u32::from_be_bytes(buf[0..4].try_into().ok()?);
    let dst_ip = u32::from_be_bytes(buf[4..8].try_into().ok()?);
    let src_port = u16::from_be_bytes(buf[8..10].try_into().ok()?);
    let dst_port = u16::from_be_bytes(buf[10..12].try_into().ok()?);
    let proto = buf[12];
    let packets = u64::from_be_bytes(buf[13..21].try_into().ok()?);
    let bytes = u64::from_be_bytes(buf[21..29].try_into().ok()?);

    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()?
        .as_secs();

    Some((
        FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        FlowStats {
            packets,
            bytes,
            first_seen_unix_s: now,
            last_seen_unix_s: now,
        },
    ))
}

fn ip_to_string(ip: u32) -> String {
    let b = ip.to_be_bytes();
    format!("{}.{}.{}.{}", b[0], b[1], b[2], b[3])
}

fn worker(sock: UdpSocket, table: Arc<Mutex<HashMap<FlowKey, FlowStats>>>) -> io::Result<()> {
    let mut buf = [0u8; 2048];

    loop {
        let (n, _peer): (usize, SocketAddr) = sock.recv_from(&mut buf)?;
        if let Some((key, incoming)) = parse_record(&buf[..n]) {
            let mut map = table.lock().unwrap();
            let entry = map.entry(key).or_insert(FlowStats {
                packets: 0,
                bytes: 0,
                first_seen_unix_s: incoming.first_seen_unix_s,
                last_seen_unix_s: incoming.last_seen_unix_s,
            });
            entry.packets = entry.packets.saturating_add(incoming.packets);
            entry.bytes = entry.bytes.saturating_add(incoming.bytes);
            entry.last_seen_unix_s = incoming.last_seen_unix_s;
        }
    }
}

fn reporter(table: Arc<Mutex<HashMap<FlowKey, FlowStats>>>) {
    let mut last = Instant::now();

    loop {
        thread::sleep(Duration::from_secs(5));
        let elapsed = last.elapsed().as_secs_f64();
        last = Instant::now();

        let snapshot = {
            let map = table.lock().unwrap();
            map.iter()
                .map(|(k, v)| (*k, *v))
                .collect::<Vec<(FlowKey, FlowStats)>>()
        };

        let total_bytes: u64 = snapshot.iter().map(|(_, s)| s.bytes).sum();
        let total_packets: u64 = snapshot.iter().map(|(_, s)| s.packets).sum();
        let bps = if elapsed > 0.0 {
            (total_bytes as f64 * 8.0) / elapsed
        } else {
            0.0
        };

        println!(
            "flows={} packets={} bytes={} throughput_bps={:.0}",
            snapshot.len(),
            total_packets,
            total_bytes,
            bps
        );

        let mut top = snapshot;
        top.sort_by_key(|(_, s)| std::cmp::Reverse(s.bytes));

        for (k, s) in top.into_iter().take(10) {
            println!(
                "{}:{} -> {}:{} proto={} packets={} bytes={}",
                ip_to_string(k.src_ip),
                k.src_port,
                ip_to_string(k.dst_ip),
                k.dst_port,
                k.proto,
                s.packets,
                s.bytes
            );
        }

        println!("---");
    }
}

fn main() -> io::Result<()> {
    let bind_addr = "0.0.0.0:2055";
    let sock = UdpSocket::bind(bind_addr)?;
    sock.set_nonblocking(false)?;

    let table = Arc::new(Mutex::new(HashMap::<FlowKey, FlowStats>::with_capacity(1 << 20)));

    let workers = thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4);

    for _ in 0..workers {
        let wsock = sock.try_clone()?;
        let wtable = Arc::clone(&table);
        thread::spawn(move || {
            if let Err(e) = worker(wsock, wtable) {
                eprintln!("worker error: {e}");
            }
        });
    }

    reporter(table);
    Ok(())
}
