```rust
use std::collections::HashMap;
use std::net::{IpAddr, Ipv4Addr};
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq)]
struct FlowKey {
    src: IpAddr,
    dst: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

#[derive(Debug, Clone, Copy)]
struct SyntheticPacket {
    key: FlowKey,
    size_bytes: u16,
    timestamp: Instant,
}

struct FlowTable {
    flows: HashMap<FlowKey, FlowStats>,
    idle_timeout: Duration,
}

impl FlowTable {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::new(),
            idle_timeout,
        }
    }

    fn process_packet(&mut self, pkt: SyntheticPacket) {
        let entry = self.flows.entry(pkt.key).or_insert(FlowStats {
            packets: 0,
            bytes: 0,
            first_seen: pkt.timestamp,
            last_seen: pkt.timestamp,
        });

        entry.packets += 1;
        entry.bytes += pkt.size_bytes as u64;
        entry.last_seen = pkt.timestamp;
    }

    fn expire_idle(&mut self, now: Instant) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();
        self.flows.retain(|k, v| {
            if now.duration_since(v.last_seen) > self.idle_timeout {
                expired.push((*k, FlowStats {
                    packets: v.packets,
                    bytes: v.bytes,
                    first_seen: v.first_seen,
                    last_seen: v.last_seen,
                }));
                false
            } else {
                true
            }
        });
        expired
    }
}

fn main() {
    let base = Instant::now();
    let mut table = FlowTable::new(Duration::from_secs(30));

    let packets = vec![
        SyntheticPacket {
            key: FlowKey {
                src: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 1)),
                dst: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 2)),
                src_port: 12345,
                dst_port: 443,
                proto: 6,
            },
            size_bytes: 1200,
            timestamp: base,
        },
        SyntheticPacket {
            key: FlowKey {
                src: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 1)),
                dst: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 2)),
                src_port: 12345,
                dst_port: 443,
                proto: 6,
            },
            size_bytes: 900,
            timestamp: base + Duration::from_secs(1),
        },
        SyntheticPacket {
            key: FlowKey {
                src: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 3)),
                dst: IpAddr::V4(Ipv4Addr::new(10, 0, 0, 4)),
                src_port: 5353,
                dst_port: 5353,
                proto: 17,
            },
            size_bytes: 300,
            timestamp: base + Duration::from_secs(2),
        },
    ];

    for pkt in packets {
        table.process_packet(pkt);
    }

    for (k, v) in &table.flows {
        println!(
            "{:?} => packets={}, bytes={}",
            k, v.packets, v.bytes
        );
    }

    let expired = table.expire_idle(base + Duration::from_secs(31));
    println!("expired_flows={}", expired.len());
}
