#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <time.h>
#include <unistd.h>

#ifndef likely
#define likely(x)   __builtin_expect(!!(x), 1)
#endif
#ifndef unlikely
#define unlikely(x) __builtin_expect(!!(x), 0)
#endif

#define BLOCK_SIZE      (1 << 20)   // 1 MB
#define BLOCK_NR        64
#define FRAME_SIZE      2048
#define FLOW_TABLE_SIZE (1 << 20)   // 1M buckets
#define SNAP_LEN        2048
#define POLL_TIMEOUT_MS 1000
#define FLOW_TIMEOUT_SEC 30

static volatile sig_atomic_t g_stop = 0;

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_sec;
    uint64_t last_seen_sec;
    struct flow_entry *next;
} flow_entry_t;

typedef struct {
    flow_entry_t **buckets;
    size_t size;
} flow_table_t;

typedef struct {
    int fd;
    void *ring;
    size_t ring_size;
    struct tpacket_req req;
    unsigned ifindex;
    flow_table_t flows;
} capture_ctx_t;

static void on_sigint(int sig) {
    (void)sig;
    g_stop = 1;
}

static uint64_t now_sec(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec;
}

static uint32_t flow_hash(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h = (h ^ k->src_ip) * 16777619u;
    h = (h ^ k->dst_ip) * 16777619u;
    h = (h ^ k->src_port) * 16777619u;
    h = (h ^ k->dst_port) * 16777619u;
    h = (h ^ k->proto) * 16777619u;
    return h;
}

static int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip   == b->src_ip &&
           a->dst_ip   == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto    == b->proto;
}

static void flow_table_init(flow_table_t *ft, size_t size) {
    ft->size = size;
    ft->buckets = calloc(size, sizeof(flow_entry_t *));
    if (!ft->buckets) {
        perror("calloc flow table");
        exit(EXIT_FAILURE);
    }
}

static void flow_table_destroy(flow_table_t *ft) {
    for (size_t i = 0; i < ft->size; i++) {
        flow_entry_t *e = ft->buckets[i];
        while (e) {
            flow_entry_t *n = e->next;
            free(e);
            e = n;
        }
    }
    free(ft->buckets);
}

static void flow_table_update(flow_table_t *ft, const flow_key_t *key, uint32_t pkt_len, uint64_t ts_sec) {
    uint32_t idx = flow_hash(key) & (ft->size - 1);
    flow_entry_t *e = ft->buckets[idx];

    while (e) {
        if (likely(flow_key_equal(&e->key, key))) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen_sec = ts_sec;
            return;
        }
        e = e->next;
    }

    e = calloc(1, sizeof(*e));
    if (unlikely(!e)) {
        return;
    }

    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->first_seen_sec = ts_sec;
    e->last_seen_sec = ts_sec;
    e->next = ft->buckets[idx];
    ft->buckets[idx] = e;
}

static void print_ip(uint32_t ip_be, char *buf, size_t len) {
    struct in_addr a;
    a.s_addr = ip_be;
    inet_ntop(AF_INET, &a, buf, len);
}

static void flow_table_expire_and_print(flow_table_t *ft, uint64_t current_sec) {
    for (size_t i = 0; i < ft->size; i++) {
        flow_entry_t **pp = &ft->buckets[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if ((current_sec - e->last_seen_sec) >= FLOW_TIMEOUT_SEC) {
                char src[INET_ADDRSTRLEN];
                char dst[INET_ADDRSTRLEN];
                print_ip(e->key.src_ip, src, sizeof(src));
                print_ip(e->key.dst_ip, dst, sizeof(dst));

                printf("%s:%u -> %s:%u proto=%u packets=%lu bytes=%lu duration=%lus\n",
                       src, ntohs(e->key.src_port),
                       dst, ntohs(e->key.dst_port),
                       e->key.proto,
                       (unsigned long)e->packets,
                       (unsigned long)e->bytes,
                       (unsigned long)(e->last_seen_sec - e->first_seen_sec));

                *pp = e->next;
                free(e);
            } else {
                pp = &(*pp)->next;
            }
        }
    }
}

static int parse_packet(const uint8_t *pkt, uint32_t caplen, flow_key_t *key) {
    if (caplen < sizeof(struct ethhdr))
        return -1;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return -1;

    pkt += sizeof(struct ethhdr);
    caplen -= sizeof(struct ethhdr);

    if (caplen < sizeof(struct iphdr))
        return -1;

    const struct iphdr *ip = (const struct iphdr *)pkt;
    if (ip->version != 4)
        return -1;

    uint32_t iphdr_len = ip->ihl * 4;
    if (iphdr_len < sizeof(struct iphdr) || caplen < iphdr_len)
        return -1;

    key->src_ip = ip->saddr;
    key->dst_ip = ip->daddr;
    key->proto = ip->protocol;
    key->src_port = 0;
    key->dst_port = 0;

    pkt += iphdr_len;
    caplen -= iphdr_len;

    if (ip->protocol == IPPROTO_TCP) {
        if (caplen < sizeof(struct tcphdr))
            return 0;
        const struct tcphdr *tcp = (const struct tcphdr *)pkt;
        key->src_port = tcp->source;
        key->dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (caplen < sizeof(struct udphdr))
            return 0;
        const struct udphdr *udp = (const struct udphdr *)pkt;
        key->src_port = udp->source;
        key->dst_port = udp->dest;
    }

    return 0;
}

static int get_ifindex(int fd, const char *ifname, unsigned *ifindex) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("SIOCGIFINDEX");
        return -1;
    }

    *ifindex = ifr.ifr_ifindex;
    return 0;
}

static int setup_socket(capture_ctx_t *ctx, const char *ifname) {
    ctx->fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (ctx->fd < 0) {
        perror("socket(AF_PACKET)");
        return -1;
    }

    int ver = TPACKET_V1;
    if (setsockopt(ctx->fd, SOL_PACKET, PACKET_VERSION, &ver, sizeof(ver)) < 0) {
        perror("setsockopt(PACKET_VERSION)");
        return -1;
    }

    if (get_ifindex(ctx->fd, ifname, &ctx->ifindex) < 0)
        return -1;

    memset(&ctx->req, 0, sizeof(ctx->req));
    ctx->req.tp_block_size = BLOCK_SIZE;
    ctx->req.tp_block_nr = BLOCK_NR;
    ctx->req.tp_frame_size = FRAME_SIZE;
    ctx->req.tp_frame_nr = (BLOCK_SIZE * BLOCK_NR) / FRAME_SIZE;

    if (setsockopt(ctx->fd, SOL_PACKET, PACKET_RX_RING, &ctx->req, sizeof(ctx->req)) < 0) {
        perror("setsockopt(PACKET_RX_RING)");
        return -1;
    }

    ctx->ring_size = ctx->req.tp_block_size * ctx->req.tp_block_nr;
    ctx->ring = mmap(NULL, ctx->ring_size, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, 0);
    if (ctx->ring == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ctx->ifindex;

    if (bind(ctx->fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind(AF_PACKET)");
        return -1;
    }

    return 0;
}

static void cleanup_socket(capture_ctx_t *ctx) {
    if (ctx->ring && ctx->ring != MAP_FAILED)
        munmap(ctx->ring, ctx->ring_size);
    if (ctx->fd >= 0)
        close(ctx->fd);
}

static void capture_loop(capture_ctx_t *ctx) {
    struct pollfd pfd = {
        .fd = ctx->fd,
        .events = POLLIN
    };

    unsigned frame_num = ctx->req.tp_frame_nr;
    unsigned idx = 0;
    uint64_t last_expire = now_sec();

    while (!g_stop) {
        struct tpacket_hdr *hdr = (struct tpacket_hdr *)((uint8_t *)ctx->ring + (idx * ctx->req.tp_frame_size));

        if (!(hdr->tp_status & TP_STATUS_USER)) {
            int ret = poll(&pfd, 1, POLL_TIMEOUT_MS);
            if (ret < 0) {
                if (errno == EINTR)
                    continue;
                perror("poll");
                break;
            }

            uint64_t cur = now_sec();
            if (cur != last_expire) {
                flow_table_expire_and_print(&ctx->flows, cur);
                last_expire = cur;
            }
            continue;
        }

        uint8_t *pkt = (uint8_t *)hdr + hdr->tp_mac;
        uint32_t caplen = hdr->tp_snaplen;

        flow_key_t key;
        if (likely(parse_packet(pkt, caplen, &key) == 0)) {
            flow_table_update(&ctx->flows, &key, hdr->tp_len, hdr->tp_sec);
        }

        hdr->tp_status = TP_STATUS_KERNEL;
        idx = (idx + 1) % frame_num;

        uint64_t cur = now_sec();
        if (unlikely(cur != last_expire)) {
            flow_table_expire_and_print(&ctx->flows, cur);
            last_expire = cur;
        }
    }

    flow_table_expire_and_print(&ctx->flows, now_sec() + FLOW_TIMEOUT_SEC);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    capture_ctx_t ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.fd = -1;

    flow_table_init(&ctx.flows, FLOW_TABLE_SIZE);

    if (setup_socket(&ctx, argv[1]) < 0) {
        cleanup_socket(&ctx);
        flow_table_destroy(&ctx.flows);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Starting capture on interface %s\n", argv[1]);
    capture_loop(&ctx);

    cleanup_socket(&ctx);
    flow_table_destroy(&ctx.flows);
    return EXIT_SUCCESS;
}
