#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef TPACKET_V3
#define TPACKET_V3 2
#endif

#define BLOCK_SIZE      (1 << 22)   // 4 MiB
#define BLOCK_NR        64
#define FRAME_SIZE      2048
#define RETIRE_TOV_MS   60

#define FLOW_TABLE_SIZE (1 << 20)   // 1M buckets
#define FLOW_IDLE_SEC   30
#define MAX_PRINT_BATCH 10000

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    struct flow_entry *next;
} flow_entry_t;

typedef struct {
    flow_entry_t *buckets[FLOW_TABLE_SIZE];
} flow_table_t;

typedef struct {
    int fd;
    void *ring;
    size_t ring_size;
    struct tpacket_req3 req;
} capture_t;

static inline uint64_t ts_to_ns(uint32_t sec, uint32_t nsec) {
    return ((uint64_t)sec * 1000000000ULL) + nsec;
}

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ((uint64_t)ts.tv_sec * 1000000000ULL) + ts.tv_nsec;
}

static inline uint32_t flow_hash(const flow_key_t *k) {
    uint64_t x = 0;
    x ^= k->src_ip * 0x9e3779b1u;
    x ^= k->dst_ip * 0x85ebca6bu;
    x ^= ((uint32_t)k->src_port << 16) | k->dst_port;
    x ^= ((uint32_t)k->proto << 24);
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return (uint32_t)x & (FLOW_TABLE_SIZE - 1);
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static flow_entry_t *flow_lookup_or_create(flow_table_t *ft, const flow_key_t *key, uint64_t ts_ns) {
    uint32_t idx = flow_hash(key);
    flow_entry_t *e = ft->buckets[idx];
    while (e) {
        if (flow_equal(&e->key, key)) return e;
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;

    e->key = *key;
    e->first_seen_ns = ts_ns;
    e->last_seen_ns = ts_ns;
    e->next = ft->buckets[idx];
    ft->buckets[idx] = e;
    return e;
}

static void print_ip(uint32_t ip_be, char *buf, size_t buflen) {
    struct in_addr a;
    a.s_addr = ip_be;
    inet_ntop(AF_INET, &a, buf, buflen);
}

static void dump_flow(flow_entry_t *e) {
    char src[INET_ADDRSTRLEN];
    char dst[INET_ADDRSTRLEN];
    print_ip(e->key.src_ip, src, sizeof(src));
    print_ip(e->key.dst_ip, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu first_ns=%llu last_ns=%llu\n",
           src, ntohs(e->key.src_port),
           dst, ntohs(e->key.dst_port),
           e->key.proto,
           (unsigned long long)e->packets,
           (unsigned long long)e->bytes,
           (unsigned long long)e->first_seen_ns,
           (unsigned long long)e->last_seen_ns);
}

static void expire_flows(flow_table_t *ft, uint64_t now, int force_all) {
    uint64_t idle_ns = (uint64_t)FLOW_IDLE_SEC * 1000000000ULL;
    int printed = 0;

    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t **pp = &ft->buckets[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            int expired = force_all || (now - e->last_seen_ns >= idle_ns);
            if (expired) {
                dump_flow(e);
                *pp = e->next;
                free(e);
                printed++;
                if (printed >= MAX_PRINT_BATCH && !force_all) return;
            } else {
                pp = &e->next;
            }
        }
    }
}

static int setup_capture(capture_t *cap, const char *ifname) {
    memset(cap, 0, sizeof(*cap));

    cap->fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (cap->fd < 0) {
        perror("socket(AF_PACKET)");
        return -1;
    }

    int version = TPACKET_V3;
    if (setsockopt(cap->fd, SOL_PACKET, PACKET_VERSION, &version, sizeof(version)) < 0) {
        perror("setsockopt(PACKET_VERSION)");
        close(cap->fd);
        return -1;
    }

    memset(&cap->req, 0, sizeof(cap->req));
    cap->req.tp_block_size = BLOCK_SIZE;
    cap->req.tp_frame_size = FRAME_SIZE;
    cap->req.tp_block_nr   = BLOCK_NR;
    cap->req.tp_frame_nr   = (BLOCK_SIZE * BLOCK_NR) / FRAME_SIZE;
    cap->req.tp_retire_blk_tov = RETIRE_TOV_MS;

    if (setsockopt(cap->fd, SOL_PACKET, PACKET_RX_RING, &cap->req, sizeof(cap->req)) < 0) {
        perror("setsockopt(PACKET_RX_RING)");
        close(cap->fd);
        return -1;
    }

    cap->ring_size = (size_t)cap->req.tp_block_size * cap->req.tp_block_nr;
    cap->ring = mmap(NULL, cap->ring_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, cap->fd, 0);
    if (cap->ring == MAP_FAILED) {
        perror("mmap");
        close(cap->fd);
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = if_nametoindex(ifname);
    if (sll.sll_ifindex == 0) {
        perror("if_nametoindex");
        munmap(cap->ring, cap->ring_size);
        close(cap->fd);
        return -1;
    }

    if (bind(cap->fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        munmap(cap->ring, cap->ring_size);
        close(cap->fd);
        return -1;
    }

    return 0;
}

static void cleanup_capture(capture_t *cap) {
    if (cap->ring && cap->ring != MAP_FAILED) {
        munmap(cap->ring, cap->ring_size);
    }
    if (cap->fd >= 0) close(cap->fd);
}

static inline void process_ipv4_packet(flow_table_t *ft, const uint8_t *pkt, size_t len, uint64_t ts_ns) {
    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) return;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP) return;

    const uint8_t *ip_ptr = pkt + sizeof(struct ethhdr);
    size_t ip_len_avail = len - sizeof(struct ethhdr);

    const struct iphdr *ip = (const struct iphdr *)ip_ptr;
    if (ip_len_avail < sizeof(struct iphdr)) return;
    if (ip->version != 4) return;

    size_t ihl = ip->ihl * 4;
    if (ihl < sizeof(struct iphdr) || ip_len_avail < ihl) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto  = ip->protocol;

    const uint8_t *l4 = ip_ptr + ihl;
    size_t l4_len = ip_len_avail - ihl;

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    flow_entry_t *e = flow_lookup_or_create(ft, &key, ts_ns);
    if (!e) return;

    e->packets++;
    e->bytes += len;
    e->last_seen_ns = ts_ns;
}

static void run_capture_loop(capture_t *cap, flow_table_t *ft) {
    struct pollfd pfd;
    pfd.fd = cap->fd;
    pfd.events = POLLIN;

    uint32_t block_num = 0;
    uint64_t last_expire = now_ns();

    while (!g_stop) {
        struct tpacket_block_desc *block =
            (struct tpacket_block_desc *)((uint8_t *)cap->ring + (block_num * cap->req.tp_block_size));

        if (!(block->hdr.bh1.block_status & TP_STATUS_USER)) {
            int rc = poll(&pfd, 1, 100);
            if (rc < 0 && errno != EINTR) {
                perror("poll");
                break;
            }

            uint64_t n = now_ns();
            if (n - last_expire > 1000000000ULL) {
                expire_flows(ft, n, 0);
                last_expire = n;
            }
            continue;
        }

        uint32_t num_pkts = block->hdr.bh1.num_pkts;
        uint32_t offset = block->hdr.bh1.offset_to_first_pkt;

        for (uint32_t i = 0; i < num_pkts; i++) {
            struct tpacket3_hdr *ppd = (struct tpacket3_hdr *)((uint8_t *)block + offset);
            const uint8_t *pkt = (const uint8_t *)ppd + ppd->tp_mac;
            size_t len = ppd->tp_snaplen;
            uint64_t ts_ns = ts_to_ns(ppd->tp_sec, ppd->tp_nsec);

            process_ipv4_packet(ft, pkt, len, ts_ns);
            offset += ppd->tp_next_offset;
        }

        __sync_synchronize();
        block->hdr.bh1.block_status = TP_STATUS_KERNEL;

        block_num = (block_num + 1) % cap->req.tp_block_nr;

        uint64_t n = now_ns();
        if (n - last_expire > 1000000000ULL) {
            expire_flows(ft, n, 0);
            last_expire = n;
        }
    }

    expire_flows(ft, now_ns(), 1);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    capture_t cap;
    flow_table_t *ft = calloc(1, sizeof(flow_table_t));
    if (!ft) {
        perror("calloc(flow_table)");
        return 1;
    }

    if (setup_capture(&cap, argv[1]) != 0) {
        free(ft);
        return 1;
    }

    fprintf(stderr, "Capturing on interface %s...\n", argv[1]);
    run_capture_loop(&cap, ft);

    cleanup_capture(&cap);
    free(ft);
    return 0;
}
