#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <inttypes.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/if.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <net/ethernet.h>
#include <netinet/in.h>
#include <poll.h>
#include <sched.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef TPACKET_V3
#define TPACKET_V3 2
#endif

#define BLOCK_SIZE      (1 << 20)   // 1 MB
#define BLOCK_NR        64
#define FRAME_SIZE      2048
#define RETIRE_TOV_MS   60
#define POLL_TIMEOUT_MS 1000

#define FLOW_TABLE_SIZE (1 << 20)   // 1M buckets
#define FLOW_PRINT_TOP  20

static volatile sig_atomic_t g_stop = 0;

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    struct flow_entry *next;
} flow_entry_t;

typedef struct flow_table {
    flow_entry_t **buckets;
    size_t size;
} flow_table_t;

static void on_signal(int signo) {
    (void)signo;
    g_stop = 1;
}

static inline uint64_t ts_to_ns(const struct timespec *ts) {
    return (uint64_t)ts->tv_sec * 1000000000ULL + (uint64_t)ts->tv_nsec;
}

static inline uint64_t packet_ts_ns(const struct tpacket3_hdr *hdr) {
    return (uint64_t)hdr->tp_sec * 1000000000ULL + (uint64_t)hdr->tp_nsec;
}

static inline uint32_t flow_hash(const flow_key_t *k) {
    // Simple high-speed mixing
    uint32_t h = 2166136261u;
    h ^= k->src_ip;   h *= 16777619u;
    h ^= k->dst_ip;   h *= 16777619u;
    h ^= ((uint32_t)k->src_port << 16) | k->dst_port; h *= 16777619u;
    h ^= k->proto;    h *= 16777619u;
    return h;
}

static flow_table_t *flow_table_create(size_t size) {
    flow_table_t *ft = calloc(1, sizeof(*ft));
    if (!ft) return NULL;
    ft->buckets = calloc(size, sizeof(flow_entry_t *));
    if (!ft->buckets) {
        free(ft);
        return NULL;
    }
    ft->size = size;
    return ft;
}

static void flow_table_destroy(flow_table_t *ft) {
    if (!ft) return;
    for (size_t i = 0; i < ft->size; i++) {
        flow_entry_t *e = ft->buckets[i];
        while (e) {
            flow_entry_t *n = e->next;
            free(e);
            e = n;
        }
    }
    free(ft->buckets);
    free(ft);
}

static inline bool flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip   == b->src_ip &&
           a->dst_ip   == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto    == b->proto;
}

static inline void flow_table_update(flow_table_t *ft, const flow_key_t *key,
                                     uint32_t pkt_len, uint64_t ts_ns) {
    uint32_t idx = flow_hash(key) & (ft->size - 1);
    flow_entry_t *e = ft->buckets[idx];
    while (e) {
        if (flow_key_equal(&e->key, key)) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen_ns = ts_ns;
            return;
        }
        e = e->next;
    }

    e = calloc(1, sizeof(*e));
    if (!e) return;
    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->first_seen_ns = ts_ns;
    e->last_seen_ns = ts_ns;
    e->next = ft->buckets[idx];
    ft->buckets[idx] = e;
}

static void ip_to_str(uint32_t ip_be, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip_be;
    inet_ntop(AF_INET, &addr, buf, len);
}

typedef struct top_flow {
    flow_entry_t *entry;
} top_flow_t;

static int cmp_top_flows(const void *a, const void *b) {
    const top_flow_t *fa = a;
    const top_flow_t *fb = b;
    if (fa->entry->bytes < fb->entry->bytes) return 1;
    if (fa->entry->bytes > fb->entry->bytes) return -1;
    return 0;
}

static void print_top_flows(flow_table_t *ft) {
    size_t cap = 1024;
    size_t count = 0;
    top_flow_t *arr = malloc(cap * sizeof(*arr));
    if (!arr) return;

    for (size_t i = 0; i < ft->size; i++) {
        for (flow_entry_t *e = ft->buckets[i]; e; e = e->next) {
            if (count == cap) {
                cap *= 2;
                top_flow_t *tmp = realloc(arr, cap * sizeof(*arr));
                if (!tmp) {
                    free(arr);
                    return;
                }
                arr = tmp;
            }
            arr[count++].entry = e;
        }
    }

    qsort(arr, count, sizeof(*arr), cmp_top_flows);

    printf("\n==== Top %d flows by bytes ====\n", FLOW_PRINT_TOP);
    for (size_t i = 0; i < count && i < FLOW_PRINT_TOP; i++) {
        flow_entry_t *e = arr[i].entry;
        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        ip_to_str(e->key.src_ip, src, sizeof(src));
        ip_to_str(e->key.dst_ip, dst, sizeof(dst));

        printf("%2zu) %s:%u -> %s:%u proto=%u pkts=%" PRIu64 " bytes=%" PRIu64 "\n",
               i + 1,
               src, ntohs(e->key.src_port),
               dst, ntohs(e->key.dst_port),
               e->key.proto,
               e->packets,
               e->bytes);
    }
    free(arr);
}

static int get_ifindex(int fd, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        return -1;
    }
    return ifr.ifr_ifindex;
}

static int setup_socket(const char *ifname, void **ring, size_t *ring_size) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int version = TPACKET_V3;
    if (setsockopt(fd, SOL_PACKET, PACKET_VERSION, &version, sizeof(version)) < 0) {
        perror("setsockopt PACKET_VERSION");
        close(fd);
        return -1;
    }

    struct tpacket_req3 req;
    memset(&req, 0, sizeof(req));
    req.tp_block_size = BLOCK_SIZE;
    req.tp_frame_size = FRAME_SIZE;
    req.tp_block_nr = BLOCK_NR;
    req.tp_frame_nr = (BLOCK_SIZE * BLOCK_NR) / FRAME_SIZE;
    req.tp_retire_blk_tov = RETIRE_TOV_MS;

    if (setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
        perror("setsockopt PACKET_RX_RING");
        close(fd);
        return -1;
    }

    *ring_size = req.tp_block_size * req.tp_block_nr;
    *ring = mmap(NULL, *ring_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, fd, 0);
    if (*ring == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return -1;
    }

    int ifindex = get_ifindex(fd, ifname);
    if (ifindex < 0) {
        perror("get_ifindex");
        munmap(*ring, *ring_size);
        close(fd);
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex;

    if (bind(fd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind");
        munmap(*ring, *ring_size);
        close(fd);
        return -1;
    }

    return fd;
}

static inline void process_packet(const uint8_t *pkt, uint32_t snaplen,
                                  uint32_t wirelen, uint64_t ts_ns,
                                  flow_table_t *ft) {
    (void)snaplen;

    if (wirelen < sizeof(struct ethhdr)) return;
    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP) return;

    const uint8_t *l3 = pkt + sizeof(struct ethhdr);
    uint32_t l3_len = wirelen - sizeof(struct ethhdr);
    if (l3_len < sizeof(struct iphdr)) return;

    const struct iphdr *ip = (const struct iphdr *)l3;
    if (ip->version != 4) return;

    uint32_t ihl = ip->ihl * 4;
    if (ihl < sizeof(struct iphdr) || l3_len < ihl) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto = ip->protocol;

    const uint8_t *l4 = l3 + ihl;
    uint32_t l4_len = l3_len - ihl;

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    flow_table_update(ft, &key, wirelen, ts_ns);
}

static void capture_loop(int fd, void *ring, flow_table_t *ft) {
    struct pollfd pfd = {
        .fd = fd,
        .events = POLLIN
    };

    uint32_t block_idx = 0;
    uint8_t *base = ring;

    time_t last_print = time(NULL);

    while (!g_stop) {
        struct tpacket_block_desc *block =
            (struct tpacket_block_desc *)(base + (block_idx * BLOCK_SIZE));

        if ((block->hdr.bh1.block_status & TP_STATUS_USER) == 0) {
            int ret = poll(&pfd, 1, POLL_TIMEOUT_MS);
            if (ret < 0) {
                if (errno == EINTR) continue;
                perror("poll");
                break;
            }
            if (ret == 0) {
                time_t now = time(NULL);
                if (now - last_print >= 5) {
                    print_top_flows(ft);
                    last_print = now;
                }
                continue;
            }
            continue;
        }

        uint32_t num_pkts = block->hdr.bh1.num_pkts;
        uint32_t offset = block->hdr.bh1.offset_to_first_pkt;

        for (uint32_t i = 0; i < num_pkts; i++) {
            struct tpacket3_hdr *ppd = (struct tpacket3_hdr *)((uint8_t *)block + offset);

            const uint8_t *pkt = (const uint8_t *)ppd + ppd->tp_mac;
            uint32_t snaplen = ppd->tp_snaplen;
            uint32_t wirelen = ppd->tp_len;
            uint64_t ts_ns = packet_ts_ns(ppd);

            process_packet(pkt, snaplen, wirelen, ts_ns, ft);

            offset += ppd->tp_next_offset;
        }

        block->hdr.bh1.block_status = TP_STATUS_KERNEL;
        block_idx = (block_idx + 1) % BLOCK_NR;

        time_t now = time(NULL);
        if (now - last_print >= 5) {
            print_top_flows(ft);
            last_print = now;
        }
    }
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <interface>\n", prog);
    fprintf(stderr, "Example: %s eth0\n", prog);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        usage(argv[0]);
        return 1;
    }

    const char *ifname = argv[1];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    flow_table_t *ft = flow_table_create(FLOW_TABLE_SIZE);
    if (!ft) {
        fprintf(stderr, "failed to allocate flow table\n");
        return 1;
    }

    void *ring = NULL;
    size_t ring_sz = 0;
    int fd = setup_socket(ifname, &ring, &ring_sz);
    if (fd < 0) {
        flow_table_destroy(ft);
        return 1;
    }

    printf("Capturing on interface %s...\n", ifname);
    capture_loop(fd, ring, ft);

    print_top_flows(ft);

    munmap(ring, ring_sz);
    close(fd);
    flow_table_destroy(ft);
    return 0;
}
