# 3. Main implementation

```rust
use ahash::AHashMap;
use libc::{
    bind, c_void, close, if_nametoindex, mmap, munmap, poll, recvfrom, setsockopt, sockaddr,
    sockaddr_ll, socket, socklen_t, AF_PACKET, ETH_P_ALL, MAP_FAILED, MAP_LOCKED, MAP_SHARED,
    PACKET_RX_RING, POLLIN, PROT_READ, PROT_WRITE, SOCK_RAW, SOL_PACKET,
};
use std::convert::TryInto;
use std::ffi::CString;
use std::io;
use std::mem::{size_of, zeroed};
use std::os::fd::RawFd;
use std::ptr;
use std::slice;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const ETH_HDR_LEN: usize = 14;
const IPV4_MIN_HDR_LEN: usize = 20;
const TCP_MIN_HDR_LEN: usize = 20;
const UDP_HDR_LEN: usize = 8;

// TPACKET_V3 constants
const PACKET_VERSION: i32 = 10;
const TPACKET_V3: u32 = 2;

#[repr(C)]
#[derive(Clone, Copy)]
struct TpacketReq3 {
    tp_block_size: u32,
    tp_block_nr: u32,
    tp_frame_size: u32,
    tp_frame_nr: u32,
    tp_retire_blk_tov: u32,
    tp_sizeof_priv: u32,
    tp_feature_req_word: u32,
}

#[repr(C)]
struct TpacketBlockDesc {
    version: u32,
    offset_to_priv: u32,
    hdr: TpacketHdrV1,
}

#[repr(C)]
struct TpacketHdrV1 {
    block_status: u32,
    num_pkts: u32,
    offset_to_first_pkt: u32,
    blk_len: u32,
    seq_num: u64,
    ts_first_pkt: Ts,
    ts_last_pkt: Ts,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct Ts {
    ts_sec: u32,
    ts_nsec: u32,
}

#[repr(C)]
struct Tpacket3Hdr {
    tp_next_offset: u32,
    tp_sec: u32,
    tp_nsec: u32,
    tp_snaplen: u32,
    tp_len: u32,
    tp_status: u32,
    tp_mac: u16,
    tp_net: u16,
}

const TP_STATUS_USER: u32 = 1;
const TP_STATUS_KERNEL: u32 = 0;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Clone, Copy)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_sec: u64,
    last_seen_sec: u64,
}

fn now_sec() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn io_err(msg: &str) -> io::Error {
    io::Error::new(io::ErrorKind::Other, msg)
}

struct AfPacketRing {
    fd: RawFd,
    map_ptr: *mut u8,
    map_len: usize,
    block_num: usize,
    block_size: usize,
}

impl Drop for AfPacketRing {
    fn drop(&mut self) {
        unsafe {
            munmap(self.map_ptr as *mut c_void, self.map_len);
            close(self.fd);
        }
    }
}

impl AfPacketRing {
    fn new(interface: &str) -> io::Result<Self> {
        unsafe {
            let fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL as u16) as i32);
            if fd < 0 {
                return Err(io::Error::last_os_error());
            }

            let version: u32 = TPACKET_V3;
            let rc = setsockopt(
                fd,
                SOL_PACKET,
                PACKET_VERSION,
                &version as *const _ as *const c_void,
                size_of::<u32>() as socklen_t,
            );
            if rc < 0 {
                close(fd);
                return Err(io::Error::last_os_error());
            }

            let block_size: u32 = 1 << 22; // 4 MiB
            let block_nr: u32 = 64;
            let frame_size: u32 = 2048;
            let frame_nr: u32 = (block_size * block_nr) / frame_size;

            let req = TpacketReq3 {
                tp_block_size: block_size,
                tp_block_nr: block_nr,
                tp_frame_size: frame_size,
                tp_frame_nr: frame_nr,
                tp_retire_blk_tov: 60,
                tp_sizeof_priv: 0,
                tp_feature_req_word: 0,
            };

            let rc = setsockopt(
                fd,
                SOL_PACKET,
                PACKET_RX_RING,
                &req as *const _ as *const c_void,
                size_of::<TpacketReq3>() as socklen_t,
            );
            if rc < 0 {
                close(fd);
                return Err(io::Error::last_os_error());
            }

            let ifname = CString::new(interface).unwrap();
            let if_index = if_nametoindex(ifname.as_ptr());
            if if_index == 0 {
                close(fd);
                return Err(io::Error::last_os_error());
            }

            let mut sll: sockaddr_ll = zeroed();
            sll.sll_family = AF_PACKET as u16;
            sll.sll_protocol = htons(ETH_P_ALL as u16);
            sll.sll_ifindex = if_index as i32;

            let rc = bind(
                fd,
                &sll as *const _ as *const sockaddr,
                size_of::<sockaddr_ll>() as socklen_t,
            );
            if rc < 0 {
                close(fd);
                return Err(io::Error::last_os_error());
            }

            let map_len = (block_size * block_nr) as usize;
            let map_ptr = mmap(
                ptr::null_mut(),
                map_len,
                PROT_READ | PROT_WRITE,
                MAP_SHARED | MAP_LOCKED,
                fd,
                0,
            );

            if map_ptr == MAP_FAILED {
                close(fd);
                return Err(io::Error::last_os_error());
            }

            Ok(Self {
                fd,
                map_ptr: map_ptr as *mut u8,
                map_len,
                block_num: block_nr as usize,
                block_size: block_size as usize,
            })
        }
    }
}

fn parse_ipv4_flow(packet: &[u8]) -> Option<(FlowKey, usize)> {
    if packet.len() < ETH_HDR_LEN + IPV4_MIN_HDR_LEN {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ip = &packet[ETH_HDR_LEN..];
    let version = ip[0] >> 4;
    if version != 4 {
        return None;
    }

    let ihl = ((ip[0] & 0x0f) as usize) * 4;
    if ihl < IPV4_MIN_HDR_LEN || ip.len() < ihl {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes(ip[12..16].try_into().ok()?);
    let dst_ip = u32::from_be_bytes(ip[16..20].try_into().ok()?);

    let l4 = &ip[ihl..];
    let (src_port, dst_port) = match proto {
        6 => {
            if l4.len() < TCP_MIN_HDR_LEN {
                return None;
            }
            (
                u16::from_be_bytes([l4[0], l4[1]]),
                u16::from_be_bytes([l4[2], l4[3]]),
            )
        }
        17 => {
            if l4.len() < UDP_HDR_LEN {
                return None;
            }
            (
                u16::from_be_bytes([l4[0], l4[1]]),
                u16::from_be_bytes([l4[2], l4[3]]),
            )
        }
        _ => {
            return None;
        }
    };

    Some((
        FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        },
        packet.len(),
    ))
}

fn format_ipv4(ip: u32) -> String {
    let b = ip.to_be_bytes();
    format!("{}.{}.{}.{}", b[0], b[1], b[2], b[3])
}

fn export_expired_flows(table: &mut AHashMap<FlowKey, FlowStats>, active_timeout: u64, idle_timeout: u64) {
    let now = now_sec();
    let mut expired = Vec::new();

    for (k, v) in table.iter() {
        let idle = now.saturating_sub(v.last_seen_sec);
        let age = now.saturating_sub(v.first_seen_sec);
        if idle >= idle_timeout || age >= active_timeout {
            expired.push((*k, *v));
        }
    }

    for (k, v) in expired {
        println!(
            "{},{},{},{},{},{},{},{},{}",
            format_ipv4(k.src_ip),
            format_ipv4(k.dst_ip),
            k.src_port,
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes,
            v.first_seen_sec,
            v.last_seen_sec
        );
        table.remove(&k);
    }
}

fn main() -> io::Result<()> {
    let interface = std::env::args()
        .nth(1)
        .ok_or_else(|| io_err("usage: flow_analyser <interface>"))?;

    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::Relaxed);
    })
    .map_err(|e| io::Error::new(io::ErrorKind::Other, e.to_string()))?;

    let ring = AfPacketRing::new(&interface)?;
    let mut flow_table: AHashMap<FlowKey, FlowStats> = AHashMap::with_capacity(1 << 20);

    let active_timeout = 300;
    let idle_timeout = 30;

    let mut block_idx = 0usize;
    let mut last_export = now_sec();

    while running.load(Ordering::Relaxed) {
        let block_ptr = unsafe { ring.map_ptr.add(block_idx * ring.block_size) };
        let block = unsafe { &mut *(block_ptr as *mut TpacketBlockDesc) };

        if block.hdr.block_status & TP_STATUS_USER == 0 {
            unsafe {
                let mut pfd = libc::pollfd {
                    fd: ring.fd,
                    events: POLLIN as i16,
                    revents: 0,
                };
                poll(&mut pfd, 1, 50);
            }
        } else {
            let num_pkts = block.hdr.num_pkts;
            let mut offset = block.hdr.offset_to_first_pkt as usize;

            for _ in 0..num_pkts {
                let pkt_hdr_ptr = unsafe { block_ptr.add(offset) as *const Tpacket3Hdr };
                let pkt_hdr = unsafe { &*pkt_hdr_ptr };

                let pkt_start = unsafe { (pkt_hdr_ptr as *const u8).add(pkt_hdr.tp_mac as usize) };
                let pkt = unsafe { slice::from_raw_parts(pkt_start, pkt_hdr.tp_snaplen as usize) };

                if let Some((key, bytes)) = parse_ipv4_flow(pkt) {
                    let sec = pkt_hdr.tp_sec as u64;
                    let entry = flow_table.entry(key).or_insert(FlowStats {
                        packets: 0,
                        bytes: 0,
                        first_seen_sec: sec,
                        last_seen_sec: sec,
                    });
                    entry.packets += 1;
                    entry.bytes += bytes as u64;
                    entry.last_seen_sec = sec;
                }

                if pkt_hdr.tp_next_offset == 0 {
                    break;
                }
                offset += pkt_hdr.tp_next_offset as usize;
            }

            block.hdr.block_status = TP_STATUS_KERNEL;
            block_idx = (block_idx + 1) % ring.block_num;
        }

        let now = now_sec();
        if now.saturating_sub(last_export) >= 1 {
            export_expired_flows(&mut flow_table, active_timeout, idle_timeout);
            last_export = now;
        }
    }

    export_expired_flows(&mut flow_table, 0, 0);
    Ok(())
}
```

