```rust
use ahash::AHashMap;
use clap::Parser;
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Active, Capture, Device};
use std::fmt;
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant, SystemTime};

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Interface to capture from, e.g. eth0
    #[arg(short, long)]
    iface: Option<String>,

    /// BPF filter, e.g. "ip and (tcp or udp)"
    #[arg(short, long, default_value = "ip")]
    filter: String,

    /// Report interval in seconds
    #[arg(short, long, default_value_t = 5)]
    report_interval: u64,

    /// Max packets to process (0 = unlimited)
    #[arg(short = 'n', long, default_value_t = 0)]
    max_packets: u64,
}

#[derive(Clone, Copy, Debug, Hash, Eq, PartialEq)]
enum Proto {
    Tcp,
    Udp,
    Other(u8),
}

impl fmt::Display for Proto {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Proto::Tcp => write!(f, "TCP"),
            Proto::Udp => write!(f, "UDP"),
            Proto::Other(v) => write!(f, "{}", v),
        }
    }
}

#[derive(Clone, Copy, Debug, Hash, Eq, PartialEq)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: Proto,
}

#[derive(Clone, Copy, Debug, Hash, Eq, PartialEq)]
struct CanonicalFlowKey {
    a_ip: IpAddr,
    b_ip: IpAddr,
    a_port: u16,
    b_port: u16,
    proto: Proto,
}

impl From<FlowKey> for CanonicalFlowKey {
    fn from(k: FlowKey) -> Self {
        let left = (k.src_ip, k.src_port);
        let right = (k.dst_ip, k.dst_port);
        if left <= right {
            CanonicalFlowKey {
                a_ip: k.src_ip,
                b_ip: k.dst_ip,
                a_port: k.src_port,
                b_port: k.dst_port,
                proto: k.proto,
            }
        } else {
            CanonicalFlowKey {
                a_ip: k.dst_ip,
                b_ip: k.src_ip,
                a_port: k.dst_port,
                b_port: k.src_port,
                proto: k.proto,
            }
        }
    }
}

#[derive(Debug, Default, Clone)]
struct FlowStats {
    packets_ab: u64,
    bytes_ab: u64,
    packets_ba: u64,
    bytes_ba: u64,
    tcp_syn: u64,
    tcp_fin: u64,
    tcp_rst: u64,
    first_seen: Option<SystemTime>,
    last_seen: Option<SystemTime>,
}

impl FlowStats {
    fn update(
        &mut self,
        canonical: CanonicalFlowKey,
        pkt: &ParsedPacket,
        original: FlowKey,
        now: SystemTime,
    ) {
        let dir_ab = original.src_ip == canonical.a_ip
            && original.src_port == canonical.a_port
            && original.dst_ip == canonical.b_ip
            && original.dst_port == canonical.b_port;

        if dir_ab {
            self.packets_ab += 1;
            self.bytes_ab += pkt.length as u64;
        } else {
            self.packets_ba += 1;
            self.bytes_ba += pkt.length as u64;
        }

        if let Some(flags) = pkt.tcp_flags {
            if flags.syn {
                self.tcp_syn += 1;
            }
            if flags.fin {
                self.tcp_fin += 1;
            }
            if flags.rst {
                self.tcp_rst += 1;
            }
        }

        if self.first_seen.is_none() {
            self.first_seen = Some(now);
        }
        self.last_seen = Some(now);
    }

    fn total_packets(&self) -> u64 {
        self.packets_ab + self.packets_ba
    }

    fn total_bytes(&self) -> u64 {
        self.bytes_ab + self.bytes_ba
    }
}

#[derive(Clone, Copy, Debug)]
struct TcpFlags {
    syn: bool,
    fin: bool,
    rst: bool,
}

#[derive(Clone, Copy, Debug)]
struct ParsedPacket {
    flow: FlowKey,
    tcp_flags: Option<TcpFlags>,
    length: usize,
}

fn parse_packet(data: &[u8]) -> Option<ParsedPacket> {
    let sliced = SlicedPacket::from_ethernet(data).ok()?;

    let (src_ip, dst_ip, proto) = match sliced.net {
        Some(InternetSlice::Ipv4(header, _)) => {
            let src = IpAddr::V4(Ipv4Addr::from(header.source()));
            let dst = IpAddr::V4(Ipv4Addr::from(header.destination()));
            let proto = header.protocol().0;
            (src, dst, proto)
        }
        Some(InternetSlice::Ipv6(header, _)) => {
            let src = IpAddr::V6(Ipv6Addr::from(header.source()));
            let dst = IpAddr::V6(Ipv6Addr::from(header.destination()));
            let proto = header.next_header().0;
            (src, dst, proto)
        }
        _ => return None,
    };

    match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => {
            let flow = FlowKey {
                src_ip,
                dst_ip,
                src_port: tcp.source_port(),
                dst_port: tcp.destination_port(),
                proto: Proto::Tcp,
            };
            Some(ParsedPacket {
                flow,
                tcp_flags: Some(TcpFlags {
                    syn: tcp.syn(),
                    fin: tcp.fin(),
                    rst: tcp.rst(),
                }),
                length: data.len(),
            })
        }
        Some(TransportSlice::Udp(udp)) => {
            let flow = FlowKey {
                src_ip,
                dst_ip,
                src_port: udp.source_port(),
                dst_port: udp.destination_port(),
                proto: Proto::Udp,
            };
            Some(ParsedPacket {
                flow,
                tcp_flags: None,
                length: data.len(),
            })
        }
        _ => {
            let flow = FlowKey {
                src_ip,
                dst_ip,
                src_port: 0,
                dst_port: 0,
                proto: Proto::Other(proto),
            };
            Some(ParsedPacket {
                flow,
                tcp_flags: None,
                length: data.len(),
            })
        }
    }
}

fn print_report(flow_table: &AHashMap<CanonicalFlowKey, FlowStats>) {
    println!("==== active flows: {} ====", flow_table.len());

    let mut entries: Vec<_> = flow_table.iter().collect();
    entries.sort_by_key(|(_, stats)| std::cmp::Reverse(stats.total_bytes()));

    for (key, stats) in entries.iter().take(50) {
        println!(
            "{}:{} <-> {}:{} proto={} pkts={}/{} bytes={}/{} total_bytes={} syn={} fin={} rst={}",
            key.a_ip,
            key.a_port,
            key.b_ip,
            key.b_port,
            key.proto,
            stats.packets_ab,
            stats.packets_ba,
            stats.bytes_ab,
            stats.bytes_ba,
            stats.total_bytes(),
            stats.tcp_syn,
            stats.tcp_fin,
            stats.tcp_rst
        );
    }
}

fn open_capture(args: &Args) -> Result<Capture<Active>, Box<dyn std::error::Error>> {
    let device = if let Some(ref iface) = args.iface {
        let devices = Device::list()?;
        devices
            .into_iter()
            .find(|d| d.name == *iface)
            .ok_or_else(|| format!("interface '{}' not found", iface))?
    } else {
        Device::lookup()?.ok_or("no default device found")?
    };

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .buffer_size(8 * 1024 * 1024)
        .snaplen(65535)
        .open()?;

    cap.filter(&args.filter, true)?;
    Ok(cap)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    let running = Arc::new(AtomicBool::new(true));
    let running_flag = running.clone();

    ctrlc::set_handler(move || {
        running_flag.store(false, Ordering::Relaxed);
    })?;

    let mut cap = open_capture(&args)?;
    let mut flow_table: AHashMap<CanonicalFlowKey, FlowStats> = AHashMap::new();

    let start = Instant::now();
    let mut last_report = Instant::now();
    let mut processed_packets: u64 = 0;
    let mut processed_bytes: u64 = 0;

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                processed_packets += 1;
                processed_bytes += packet.data.len() as u64;

                if let Some(parsed) = parse_packet(packet.data) {
                    let canonical = CanonicalFlowKey::from(parsed.flow);
                    let now = SystemTime::now();

                    flow_table
                        .entry(canonical)
                        .or_default()
                        .update(canonical, &parsed, parsed.flow, now);
                }

                if args.max_packets > 0 && processed_packets >= args.max_packets {
                    break;
                }
            }
            Err(pcap::Error::TimeoutExpired) => {}
            Err(e) => {
                eprintln!("capture error: {}", e);
                break;
            }
        }

        if last_report.elapsed() >= Duration::from_secs(args.report_interval) {
            let elapsed = start.elapsed().as_secs_f64();
            println!(
                "\n[stats] packets={} bytes={} pps={:.0} Mbps={:.2}",
                processed_packets,
                processed_bytes,
                processed_packets as f64 / elapsed,
                (processed_bytes as f64 * 8.0) / elapsed / 1_000_000.0
            );
            print_report(&flow_table);
            last_report = Instant::now();
        }
    }

    println!("\nFinal report:");
    let elapsed = start.elapsed().as_secs_f64();
    println!(
        "[stats] packets={} bytes={} pps={:.0} Mbps={:.2}",
        processed_packets,
        processed_bytes,
        processed_packets as f64 / elapsed.max(0.0001),
        (processed_bytes as f64 * 8.0) / elapsed.max(0.0001) / 1_000_000.0
    );
    print_report(&flow_table);

    Ok(())
}
