## `flow_analyzer.c`
```c
#include <pcap.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define FLOW_TABLE_SIZE 65536

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct timeval first_ts;
    struct timeval last_ts;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[FLOW_TABLE_SIZE];

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h = (h ^ k->src_ip) * 16777619;
    h = (h ^ k->dst_ip) * 16777619;
    h = (h ^ k->src_port) * 16777619;
    h = (h ^ k->dst_port) * 16777619;
    h = (h ^ k->proto) * 16777619;
    return h % FLOW_TABLE_SIZE;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static void update_flow(const flow_key_t *key, uint32_t pkt_len, const struct timeval *ts) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_equal(&e->key, key)) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_ts = *ts;
            return;
        }
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) {
        perror("calloc");
        exit(1);
    }

    e->key = *key;
    e->packets = 1;
    e->bytes = pkt_len;
    e->first_ts = *ts;
    e->last_ts = *ts;
    e->next = flow_table[idx];
    flow_table[idx] = e;
}

/* Ethernet header is 14 bytes */
#define ETH_HDR_LEN 14

static void process_packet(const struct pcap_pkthdr *hdr, const uint8_t *packet) {
    if (hdr->caplen < ETH_HDR_LEN + 20) return;

    const uint8_t *ip = packet + ETH_HDR_LEN;
    uint8_t version_ihl = ip[0];
    uint8_t version = version_ihl >> 4;
    uint8_t ihl = (version_ihl & 0x0F) * 4;

    if (version != 4) return;
    if (ihl < 20) return;
    if (hdr->caplen < ETH_HDR_LEN + ihl) return;

    uint8_t proto = ip[9];
    uint32_t src_ip, dst_ip;
    memcpy(&src_ip, ip + 12, 4);
    memcpy(&dst_ip, ip + 16, 4);

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.proto = proto;

    const uint8_t *l4 = ip + ihl;

    if (proto == 6 || proto == 17) { /* TCP or UDP */
        if (hdr->caplen < (uint32_t)(ETH_HDR_LEN + ihl + 4)) return;
        memcpy(&key.src_port, l4, 2);
        memcpy(&key.dst_port, l4 + 2, 2);
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    update_flow(&key, hdr->len, &hdr->ts);
}

static void print_ip(uint32_t ip) {
    struct in_addr addr;
    addr.s_addr = ip;
    printf("%s", inet_ntoa(addr));
}

static void print_flows(void) {
    printf("%-16s %-16s %-7s %-7s %-6s %-10s %-10s %-20s %-20s\n",
           "SRC_IP", "DST_IP", "SPORT", "DPORT", "PROTO", "PACKETS", "BYTES", "FIRST_TS", "LAST_TS");

    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            print_ip(e->key.src_ip);
            printf(" ");
            int pad1 = 16 - (int)strlen(inet_ntoa(*(struct in_addr *)&e->key.src_ip));
            for (int j = 0; j < pad1; j++) printf(" ");

            print_ip(e->key.dst_ip);
            printf(" ");
            int pad2 = 16 - (int)strlen(inet_ntoa(*(struct in_addr *)&e->key.dst_ip));
            for (int j = 0; j < pad2; j++) printf(" ");

            printf("%-7u %-7u %-6u %-10llu %-10llu %ld.%06ld %10s %ld.%06ld\n",
                   ntohs(e->key.src_port),
                   ntohs(e->key.dst_port),
                   e->key.proto,
                   (unsigned long long)e->packets,
                   (unsigned long long)e->bytes,
                   (long)e->first_ts.tv_sec,
                   (long)e->first_ts.tv_usec,
                   "",
                   (long)e->last_ts.tv_sec,
                   (long)e->last_ts.tv_usec);

            e = e->next;
        }
    }
}

static void free_flows(void) {
    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            flow_entry_t *next = e->next;
            free(e);
            e = next;
        }
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file.pcap>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *pcap = pcap_open_offline(argv[1], errbuf);
    if (!pcap) {
        fprintf(stderr, "pcap_open_offline failed: %s\n", errbuf);
        return 1;
    }

    const uint8_t *packet;
    struct pcap_pkthdr *hdr;
    int ret;

    while ((ret = pcap_next_ex(pcap, &hdr, &packet)) >= 0) {
        if (ret == 0) continue;
        process_packet(hdr, packet);
    }

    if (ret == -1) {
        fprintf(stderr, "pcap_next_ex failed: %s\n", pcap_geterr(pcap));
        pcap_close(pcap);
        free_flows();
        return 1;
    }

    print_flows();
    free_flows();
    pcap_close(pcap);
    return 0;
}
```

