## Source: `flow_analyzer.c`

```c
#include <pcap.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#define SNAPLEN 65535
#define PROMISC 1
#define READ_TIMEOUT_MS 1000

#define FLOW_TABLE_SIZE 262144

static volatile int running = 1;

struct eth_header {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
} __attribute__((packed));

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct {
    int used;
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t last_seen;
} flow_entry_t;

static flow_entry_t flow_table[FLOW_TABLE_SIZE];

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(flow_key_t); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h;
}

static int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static flow_entry_t *get_or_create_flow(const flow_key_t *key) {
    uint32_t idx = hash_flow(key) % FLOW_TABLE_SIZE;
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        uint32_t pos = (idx + i) % FLOW_TABLE_SIZE;
        if (!flow_table[pos].used) {
            flow_table[pos].used = 1;
            flow_table[pos].key = *key;
            flow_table[pos].packets = 0;
            flow_table[pos].bytes = 0;
            flow_table[pos].last_seen = time(NULL);
            return &flow_table[pos];
        }
        if (flow_equal(&flow_table[pos].key, key)) {
            return &flow_table[pos];
        }
    }
    return NULL;
}

static void print_flow(const flow_entry_t *f) {
    char src[INET_ADDRSTRLEN];
    char dst[INET_ADDRSTRLEN];

    struct in_addr saddr = { .s_addr = f->key.src_ip };
    struct in_addr daddr = { .s_addr = f->key.dst_ip };

    inet_ntop(AF_INET, &saddr, src, sizeof(src));
    inet_ntop(AF_INET, &daddr, dst, sizeof(dst));

    printf("%s:%u -> %s:%u proto=%u packets=%lu bytes=%lu last_seen=%ld\n",
           src, ntohs(f->key.src_port),
           dst, ntohs(f->key.dst_port),
           f->key.proto,
           (unsigned long)f->packets,
           (unsigned long)f->bytes,
           (long)f->last_seen);
}

static void print_all_flows(void) {
    printf("==== active flows ====\n");
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        if (flow_table[i].used) {
            print_flow(&flow_table[i]);
        }
    }
    printf("======================\n");
}

static void process_packet(const struct pcap_pkthdr *pkthdr, const uint8_t *packet) {
    if (pkthdr->caplen < sizeof(struct eth_header)) return;

    const struct eth_header *eth = (const struct eth_header *)packet;
    if (ntohs(eth->ethertype) != 0x0800) return; // IPv4 only

    const uint8_t *ip_ptr = packet + sizeof(struct eth_header);
    size_t ip_len_avail = pkthdr->caplen - sizeof(struct eth_header);
    if (ip_len_avail < sizeof(struct ip)) return;

    const struct ip *iph = (const struct ip *)ip_ptr;
    if (iph->ip_v != 4) return;

    size_t ip_header_len = iph->ip_hl * 4;
    if (ip_header_len < sizeof(struct ip) || ip_len_avail < ip_header_len) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const uint8_t *l4_ptr = ip_ptr + ip_header_len;
    size_t l4_len_avail = ip_len_avail - ip_header_len;

    if (iph->ip_p == IPPROTO_TCP) {
        if (l4_len_avail < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcph = (const struct tcphdr *)l4_ptr;
        key.src_port = tcph->th_sport;
        key.dst_port = tcph->th_dport;
    } else if (iph->ip_p == IPPROTO_UDP) {
        if (l4_len_avail < sizeof(struct udphdr)) return;
        const struct udphdr *udph = (const struct udphdr *)l4_ptr;
        key.src_port = udph->uh_sport;
        key.dst_port = udph->uh_dport;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    flow_entry_t *entry = get_or_create_flow(&key);
    if (!entry) return;

    entry->packets++;
    entry->bytes += pkthdr->len;
    entry->last_seen = time(NULL);
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    const char *dev;
    time_t last_print = time(NULL);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }
    dev = argv[1];

    signal(SIGINT, handle_sigint);

    handle = pcap_open_live(dev, SNAPLEN, PROMISC, READ_TIMEOUT_MS, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    if (pcap_datalink(handle) != DLT_EN10MB) {
        fprintf(stderr, "Unsupported datalink type; only Ethernet is supported.\n");
        pcap_close(handle);
        return 1;
    }

    while (running) {
        struct pcap_pkthdr *header;
        const uint8_t *packet;
        int rc = pcap_next_ex(handle, &header, &packet);

        if (rc == 1) {
            process_packet(header, packet);
        } else if (rc == 0) {
            // timeout
        } else if (rc == -1) {
            fprintf(stderr, "pcap_next_ex error: %s\n", pcap_geterr(handle));
            break;
        } else if (rc == -2) {
            break;
        }

        time_t now = time(NULL);
        if (now != last_print) {
            print_all_flows();
            last_print = now;
        }
    }

    print_all_flows();
    pcap_close(handle);
    return 0;
}
