## File: `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/if.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define SNAPLEN 2048
#define FLOW_TABLE_SIZE 262144
#define PRINT_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct timeval first_seen;
    struct timeval last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[FLOW_TABLE_SIZE];

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static uint32_t flow_hash(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h ^= k->src_ip;   h *= 16777619u;
    h ^= k->dst_ip;   h *= 16777619u;
    h ^= k->src_port; h *= 16777619u;
    h ^= k->dst_port; h *= 16777619u;
    h ^= k->proto;    h *= 16777619u;
    return h % FLOW_TABLE_SIZE;
}

static int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, const struct timeval *ts) {
    uint32_t idx = flow_hash(key);
    flow_entry_t *cur = flow_table[idx];

    while (cur) {
        if (flow_key_equal(&cur->key, key)) {
            return cur;
        }
        cur = cur->next;
    }

    flow_entry_t *entry = calloc(1, sizeof(flow_entry_t));
    if (!entry) {
        perror("calloc");
        return NULL;
    }

    entry->key = *key;
    entry->first_seen = *ts;
    entry->last_seen = *ts;
    entry->next = flow_table[idx];
    flow_table[idx] = entry;

    return entry;
}

static void update_flow(const flow_key_t *key, size_t pkt_len, const struct timeval *ts) {
    flow_entry_t *entry = flow_lookup_or_create(key, ts);
    if (!entry) {
        return;
    }

    entry->packets++;
    entry->bytes += pkt_len;
    entry->last_seen = *ts;
}

static void print_ip(uint32_t ip_net_order, char *buf, size_t len) {
    struct in_addr addr;
    addr.s_addr = ip_net_order;
    inet_ntop(AF_INET, &addr, buf, len);
}

static void print_summary(void) {
    uint64_t total_flows = 0;
    uint64_t total_packets = 0;
    uint64_t total_bytes = 0;

    printf("\n=== Flow Summary ===\n");

    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *cur = flow_table[i];
        while (cur) {
            total_flows++;
            total_packets += cur->packets;
            total_bytes += cur->bytes;
            cur = cur->next;
        }
    }

    printf("Total flows:   %lu\n", total_flows);
    printf("Total packets: %lu\n", total_packets);
    printf("Total bytes:   %lu\n", total_bytes);

    size_t shown = 0;
    for (size_t i = 0; i < FLOW_TABLE_SIZE && shown < 20; i++) {
        flow_entry_t *cur = flow_table[i];
        while (cur && shown < 20) {
            char src[INET_ADDRSTRLEN];
            char dst[INET_ADDRSTRLEN];
            print_ip(cur->key.src_ip, src, sizeof(src));
            print_ip(cur->key.dst_ip, dst, sizeof(dst));

            printf("%s:%u -> %s:%u proto=%u packets=%lu bytes=%lu\n",
                   src, ntohs(cur->key.src_port),
                   dst, ntohs(cur->key.dst_port),
                   cur->key.proto,
                   cur->packets,
                   cur->bytes);

            shown++;
            cur = cur->next;
        }
    }

    fflush(stdout);
}

static int bind_to_interface(int sockfd, const char *ifname) {
    struct sockaddr_ll sll;
    struct ifreq ifr;

    memset(&ifr, 0, sizeof(ifr));
    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", ifname);

    if (ioctl(sockfd, SIOCGIFINDEX, &ifr) < 0) {
        perror("SIOCGIFINDEX");
        return -1;
    }

    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifr.ifr_ifindex;

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return -1;
    }

    return 0;
}

static void process_packet(const uint8_t *buf, ssize_t len, const struct timeval *ts) {
    if (len < (ssize_t)sizeof(struct ethhdr)) {
        return;
    }

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP) {
        return;
    }

    const uint8_t *ip_ptr = buf + sizeof(struct ethhdr);
    ssize_t ip_len = len - sizeof(struct ethhdr);
    if (ip_len < (ssize_t)sizeof(struct iphdr)) {
        return;
    }

    const struct iphdr *ip = (const struct iphdr *)ip_ptr;
    if (ip->version != 4) {
        return;
    }

    size_t ihl = ip->ihl * 4;
    if (ihl < sizeof(struct iphdr) || ip_len < (ssize_t)ihl) {
        return;
    }

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto = ip->protocol;

    const uint8_t *l4_ptr = ip_ptr + ihl;
    ssize_t l4_len = ip_len - ihl;

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < (ssize_t)sizeof(struct tcphdr)) {
            return;
        }
        const struct tcphdr *tcp = (const struct tcphdr *)l4_ptr;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < (ssize_t)sizeof(struct udphdr)) {
            return;
        }
        const struct udphdr *udp = (const struct udphdr *)l4_ptr;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        key.src_port = 0;
        key.dst_port = 0;
    }

    update_flow(&key, (size_t)len, ts);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    if (bind_to_interface(sockfd, ifname) < 0) {
        close(sockfd);
        return 1;
    }

    uint8_t buffer[SNAPLEN];
    time_t last_print = time(NULL);

    while (keep_running) {
        struct sockaddr_ll addr;
        socklen_t addrlen = sizeof(addr);
        struct timeval ts;

        ssize_t n = recvfrom(sockfd, buffer, sizeof(buffer), 0,
                             (struct sockaddr *)&addr, &addrlen);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("recvfrom");
            break;
        }

        gettimeofday(&ts, NULL);
        process_packet(buffer, n, &ts);

        time_t now = time(NULL);
        if (now - last_print >= PRINT_INTERVAL_SEC) {
            print_summary();
            last_print = now;
        }
    }

    print_summary();
    close(sockfd);
    return 0;
}
```

