## Source code: `flow_analyzer.c`

```c
#include <pcap.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>

#define SNAPLEN 128
#define PROMISC 1
#define READ_TIMEOUT_MS 1

#define FLOW_TABLE_SIZE (1 << 20)   // 1M slots
#define REPORT_INTERVAL_SEC 5

#define ETHER_TYPE_IPV4 0x0800
#define IPPROTO_TCP 6
#define IPPROTO_UDP 17

static volatile sig_atomic_t keep_running = 1;

typedef struct __attribute__((packed)) {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
} eth_hdr_t;

typedef struct __attribute__((packed)) {
    uint8_t version_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t hdr_checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
} ipv4_hdr_t;

typedef struct __attribute__((packed)) {
    uint16_t src_port;
    uint16_t dst_port;
} l4_ports_t;

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint8_t pad[3];
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_sec;
    uint64_t last_seen_sec;
    uint8_t used;
} flow_entry_t;

static flow_entry_t *flow_table = NULL;
static uint64_t total_packets = 0;
static uint64_t total_bytes = 0;
static uint64_t dropped_packets = 0;

static inline uint32_t hash_flow(const flow_key_t *k) {
    // Simple fast mixing hash
    uint32_t h = 2166136261u;
    h ^= k->src_ip;    h *= 16777619u;
    h ^= k->dst_ip;    h *= 16777619u;
    h ^= ((uint32_t)k->src_port << 16) | k->dst_port; h *= 16777619u;
    h ^= k->protocol;  h *= 16777619u;
    return h & (FLOW_TABLE_SIZE - 1);
}

static inline int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip   == b->src_ip &&
           a->dst_ip   == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->protocol == b->protocol;
}

static inline void update_flow(const flow_key_t *key, uint32_t pkt_len, uint64_t ts_sec) {
    uint32_t idx = hash_flow(key);

    for (uint32_t i = 0; i < 32; i++) { // bounded linear probing
        flow_entry_t *e = &flow_table[(idx + i) & (FLOW_TABLE_SIZE - 1)];

        if (!e->used) {
            e->used = 1;
            e->key = *key;
            e->packets = 1;
            e->bytes = pkt_len;
            e->first_seen_sec = ts_sec;
            e->last_seen_sec = ts_sec;
            return;
        }

        if (flow_key_equal(&e->key, key)) {
            e->packets++;
            e->bytes += pkt_len;
            e->last_seen_sec = ts_sec;
            return;
        }
    }

    // Table/probe overflow: drop accounting for this flow
    dropped_packets++;
}

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static void print_ip(uint32_t ip_be, char *buf, size_t buflen) {
    struct in_addr addr;
    addr.s_addr = ip_be;
    inet_ntop(AF_INET, &addr, buf, buflen);
}

static void report_stats(void) {
    uint64_t active_flows = 0;
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        if (flow_table[i].used) active_flows++;
    }

    printf("=== Flow Report ===\n");
    printf("Total packets: %llu\n", (unsigned long long)total_packets);
    printf("Total bytes:   %llu\n", (unsigned long long)total_bytes);
    printf("Active flows:  %llu\n", (unsigned long long)active_flows);
    printf("Flow drops:    %llu\n", (unsigned long long)dropped_packets);

    int printed = 0;
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE && printed < 20; i++) {
        if (!flow_table[i].used) continue;

        char src[INET_ADDRSTRLEN];
        char dst[INET_ADDRSTRLEN];
        print_ip(flow_table[i].key.src_ip, src, sizeof(src));
        print_ip(flow_table[i].key.dst_ip, dst, sizeof(dst));

        printf("%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu\n",
               src,
               ntohs(flow_table[i].key.src_port),
               dst,
               ntohs(flow_table[i].key.dst_port),
               flow_table[i].key.protocol,
               (unsigned long long)flow_table[i].packets,
               (unsigned long long)flow_table[i].bytes);
        printed++;
    }
    printf("\n");
    fflush(stdout);
}

static void packet_handler(u_char *user,
                           const struct pcap_pkthdr *pkthdr,
                           const u_char *packet) {
    (void)user;

    total_packets++;
    total_bytes += pkthdr->len;

    if (pkthdr->caplen < sizeof(eth_hdr_t)) return;

    const eth_hdr_t *eth = (const eth_hdr_t *)packet;
    if (ntohs(eth->ethertype) != ETHER_TYPE_IPV4) return;

    const u_char *ip_ptr = packet + sizeof(eth_hdr_t);
    if (pkthdr->caplen < sizeof(eth_hdr_t) + sizeof(ipv4_hdr_t)) return;

    const ipv4_hdr_t *ip = (const ipv4_hdr_t *)ip_ptr;
    uint8_t version = ip->version_ihl >> 4;
    uint8_t ihl = (ip->version_ihl & 0x0F) * 4;

    if (version != 4) return;
    if (ihl < 20) return;
    if (pkthdr->caplen < sizeof(eth_hdr_t) + ihl) return;

    if (ip->protocol != IPPROTO_TCP && ip->protocol != IPPROTO_UDP) return;

    const u_char *l4_ptr = ip_ptr + ihl;
    if (pkthdr->caplen < (uint32_t)(l4_ptr - packet) + sizeof(l4_ports_t)) return;

    const l4_ports_t *ports = (const l4_ports_t *)l4_ptr;

    flow_key_t key;
    key.src_ip = ip->src_ip;
    key.dst_ip = ip->dst_ip;
    key.src_port = ports->src_port;
    key.dst_port = ports->dst_port;
    key.protocol = ip->protocol;
    key.pad[0] = key.pad[1] = key.pad[2] = 0;

    update_flow(&key, pkthdr->len, pkthdr->ts.tv_sec);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface> [bpf-filter]\n", argv[0]);
        return 1;
    }

    const char *dev = argv[1];
    const char *filter_exp = (argc >= 3) ? argv[2] : "ip and (tcp or udp)";

    flow_table = calloc(FLOW_TABLE_SIZE, sizeof(flow_entry_t));
    if (!flow_table) {
        perror("calloc");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(dev, SNAPLEN, PROMISC, READ_TIMEOUT_MS, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        free(flow_table);
        return 1;
    }

    if (pcap_datalink(handle) != DLT_EN10MB) {
        fprintf(stderr, "Unsupported link type: only Ethernet is supported in this minimal version.\n");
        pcap_close(handle);
        free(flow_table);
        return 1;
    }

    struct bpf_program fp;
    bpf_u_int32 net = 0, mask = 0;
    if (pcap_compile(handle, &fp, filter_exp, 1, net) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        free(flow_table);
        return 1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        free(flow_table);
        return 1;
    }
    pcap_freecode(&fp);

    time_t last_report = time(NULL);

    while (keep_running) {
        int rc = pcap_dispatch(handle, 256, packet_handler, NULL);

        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch failed: %s\n", pcap_geterr(handle));
            break;
        }

        time_t now = time(NULL);
        if (now - last_report >= REPORT_INTERVAL_SEC) {
            report_stats();
            last_report = now;
        }
    }

    report_stats();

    pcap_close(handle);
    free(flow_table);
    return 0;
}
