## `src/main.rs`

```rust
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Capture, Device};
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src_ip: [u8; 4],
    dst_ip: [u8; 4],
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Default, Clone, Copy)]
struct FlowStats {
    packets: u64,
    bytes: u64,
}

fn format_ipv4(ip: [u8; 4]) -> String {
    Ipv4Addr::from(ip).to_string()
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let running = Arc::new(AtomicBool::new(true));
    {
        let running = running.clone();
        ctrlc::set_handler(move || {
            running.store(false, Ordering::SeqCst);
        })?;
    }

    let device = Device::lookup()?
        .ok_or("No default capture device found")?;

    println!("Capturing on interface: {}", device.name);

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .timeout(100)
        .open()?;

    // Minimal BPF to reduce parsing load.
    cap.filter("ip and (tcp or udp)", true)?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(65536);
    let mut last_report = Instant::now();
    let report_interval = Duration::from_secs(1);

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                let data = packet.data;
                let pkt_len = packet.header.len as u64;

                if let Ok(sliced) = SlicedPacket::from_ethernet(data) {
                    let (src_ip, dst_ip, proto) = match sliced.net {
                        Some(InternetSlice::Ipv4(ipv4, _)) => {
                            let header = ipv4.header();
                            (
                                header.source(),
                                header.destination(),
                                header.protocol().0,
                            )
                        }
                        _ => continue,
                    };

                    let (src_port, dst_port) = match sliced.transport {
                        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
                        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
                        _ => continue,
                    };

                    let key = FlowKey {
                        src_ip,
                        dst_ip,
                        src_port,
                        dst_port,
                        proto,
                    };

                    let entry = flows.entry(key).or_default();
                    entry.packets += 1;
                    entry.bytes += pkt_len;
                }
            }
            Err(pcap::Error::TimeoutExpired) => {}
            Err(e) => {
                eprintln!("Capture error: {}", e);
                break;
            }
        }

        if last_report.elapsed() >= report_interval {
            println!("--- flow snapshot: {} active flows ---", flows.len());
            for (k, v) in flows.iter().take(20) {
                println!(
                    "{}:{} -> {}:{} proto={} packets={} bytes={}",
                    format_ipv4(k.src_ip),
                    k.src_port,
                    format_ipv4(k.dst_ip),
                    k.dst_port,
                    k.proto,
                    v.packets,
                    v.bytes
                );
            }
            if flows.len() > 20 {
                println!("... truncated ...");
            }
            last_report = Instant::now();
        }
    }

    println!("Final flow table: {} flows", flows.len());
    for (k, v) in &flows {
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={}",
            format_ipv4(k.src_ip),
            k.src_port,
            format_ipv4(k.dst_ip),
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes
        );
    }

    Ok(())
}
```

