```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>

#define ADC_MAX_COUNTS      4095.0f
#define ADC_REF_VOLTAGE     3.3f
#define FILTER_WINDOW       8
#define SENSOR_MIN_VOLTAGE  0.2f
#define SENSOR_MAX_VOLTAGE  3.0f

static uint16_t sample_buffer[FILTER_WINDOW];
static uint32_t sample_sum = 0;
static uint8_t sample_index = 0;
static bool buffer_full = false;

/* Hardware-specific stubs: replace with MCU HAL/SDK implementations */
void adc_init(void);
uint16_t adc_read(void);
void uart_init(void);
void uart_write(const char *msg);
void delay_ms(uint32_t ms);

static float counts_to_voltage(uint16_t counts) {
    return (counts * ADC_REF_VOLTAGE) / ADC_MAX_COUNTS;
}

static float moving_average_update(uint16_t new_sample) {
    sample_sum -= sample_buffer[sample_index];
    sample_buffer[sample_index] = new_sample;
    sample_sum += new_sample;

    sample_index++;
    if (sample_index >= FILTER_WINDOW) {
        sample_index = 0;
        buffer_full = true;
    }

    uint8_t divisor = buffer_full ? FILTER_WINDOW : sample_index;
    if (divisor == 0) divisor = 1;

    return (float)sample_sum / divisor;
}

static void process_sensor_sample(uint16_t raw) {
    float filtered_counts = moving_average_update(raw);
    float voltage = counts_to_voltage((uint16_t)filtered_counts);

    char msg[128];
    bool fault = (voltage < SENSOR_MIN_VOLTAGE || voltage > SENSOR_MAX_VOLTAGE);

    snprintf(msg, sizeof(msg),
             "raw=%u filtered=%.2f voltage=%.3fV status=%s\r\n",
             raw,
             filtered_counts,
             voltage,
             fault ? "FAULT" : "OK");

    uart_write(msg);
}

int main(void) {
    adc_init();
    uart_init();

    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        sample_buffer[i] = 0;
    }

    while (1) {
        uint16_t raw = adc_read();
        process_sensor_sample(raw);
        delay_ms(100);
    }

    return 0;
}

