#include <stdint.h>
#include <stdbool.h>

/*
 * Generic example firmware for a microcontroller reading sensor data.
 * Replace ADC/GPIO/UART register definitions with your MCU's actual SDK/HAL.
 */

/* ---------------- Config ---------------- */
#define ADC_MAX_COUNTS         4095.0f     // 12-bit ADC
#define ADC_REF_MV             3300.0f     // 3.3V reference
#define NUM_SAMPLES            16
#define FILTER_ALPHA           0.2f        // low-pass filter coefficient
#define ALERT_THRESHOLD_C      50.0f

/* Example sensor model:
 * LM35-like temperature sensor:
 * 10 mV / °C, 0 mV at 0 °C
 */
#define SENSOR_MV_PER_C        10.0f

/* ---------------- Mock hardware layer ---------------- */
static void clock_init(void);
static void gpio_init(void);
static void adc_init(void);
static void uart_init(void);
static uint16_t adc_read_blocking(uint8_t channel);
static void led_set(bool on);
static void uart_send_string(const char *s);
static void delay_ms(uint32_t ms);

/* ---------------- Utility ---------------- */
static float low_pass_filter(float previous, float input, float alpha) {
    return previous + alpha * (input - previous);
}

static uint16_t read_sensor_average(uint8_t channel, uint8_t samples) {
    uint32_t sum = 0;
    for (uint8_t i = 0; i < samples; i++) {
        sum += adc_read_blocking(channel);
    }
    return (uint16_t)(sum / samples);
}

static float adc_counts_to_mv(uint16_t counts) {
    return ((float)counts * ADC_REF_MV) / ADC_MAX_COUNTS;
}

static float sensor_mv_to_temperature_c(float mv) {
    return mv / SENSOR_MV_PER_C;
}

/* Minimal integer-to-string helpers to avoid stdio on tiny MCUs */
static void u32_to_str(uint32_t value, char *buf) {
    char tmp[11];
    int i = 0, j = 0;

    if (value == 0) {
        buf[0] = '0';
        buf[1] = '\0';
        return;
    }

    while (value > 0) {
        tmp[i++] = '0' + (value % 10);
        value /= 10;
    }

    while (i > 0) {
        buf[j++] = tmp[--i];
    }
    buf[j] = '\0';
}

static void format_status(char *buf, uint16_t raw, uint32_t mv, uint32_t temp_c_x10, bool alert) {
    char raw_str[12], mv_str[12], temp_int_str[12], temp_frac_str[2];
    u32_to_str(raw, raw_str);
    u32_to_str(mv, mv_str);
    u32_to_str(temp_c_x10 / 10, temp_int_str);
    temp_frac_str[0] = '0' + (temp_c_x10 % 10);
    temp_frac_str[1] = '\0';

    // Simple handcrafted formatting
    char *p = buf;
    const char *s1 = "RAW=";
    while (*s1) *p++ = *s1++;
    const char *s = raw_str;
    while (*s) *p++ = *s++;

    const char *s2 = " MV=";
    while (*s2) *p++ = *s2++;
    s = mv_str;
    while (*s) *p++ = *s++;
    *p++ = 'm'; *p++ = 'V';

    const char *s3 = " TEMP=";
    while (*s3) *p++ = *s3++;
    s = temp_int_str;
    while (*s) *p++ = *s++;
    *p++ = '.';
    *p++ = temp_frac_str[0];
    *p++ = 'C';

    const char *s4 = alert ? " ALERT\r\n" : " OK\r\n";
    while (*s4) *p++ = *s4++;
    *p = '\0';
}

