Below is a simple example in <language>C</language> showing typical microcontroller firmware structure for reading a sensor via ADC, filtering the readings with a moving average, and converting them into engineering units.

```c
#include <stdint.h>
#include <stdbool.h>

#define ADC_MAX_COUNTS     4095.0f
#define VREF_VOLTS         3.3f
#define FILTER_WINDOW      8

static uint16_t sample_buffer[FILTER_WINDOW];
static uint32_t sample_sum = 0;
static uint8_t sample_index = 0;
static bool buffer_full = false;

void adc_init(void);
uint16_t adc_read(uint8_t channel);
void uart_init(void);
void uart_send_float(float value);

static float process_sensor_reading(uint16_t raw_adc)
{
    float voltage = ((float)raw_adc / ADC_MAX_COUNTS) * VREF_VOLTS;

    // Example conversion: temperature sensor with 10 mV/°C and 500 mV offset
    float temperature_c = (voltage - 0.5f) * 100.0f;

    return temperature_c;
}

static float filter_sensor_reading(uint16_t raw_adc)
{
    sample_sum -= sample_buffer[sample_index];
    sample_buffer[sample_index] = raw_adc;
    sample_sum += raw_adc;

    sample_index++;
    if (sample_index >= FILTER_WINDOW) {
        sample_index = 0;
        buffer_full = true;
    }

    uint8_t divisor = buffer_full ? FILTER_WINDOW : sample_index;
    if (divisor == 0) {
        divisor = 1;
    }

    float average_adc = (float)sample_sum / divisor;
    return process_sensor_reading((uint16_t)average_adc);
}

int main(void)
{
    adc_init();
    uart_init();

    while (1) {
        uint16_t raw = adc_read(0);
        float filtered_temperature = filter_sensor_reading(raw);

        uart_send_float(filtered_temperature);

        for (volatile uint32_t i = 0; i < 100000; i++) {
            // simple delay
        }
    }

    return 0;
}
