static uint16_t low_pass_filter_u16(uint16_t previous, uint16_t input) {
    /* filtered = previous + alpha * (input - previous) */
    int32_t delta = (int32_t)input - (int32_t)previous;
    int32_t step = (delta * FILTER_ALPHA_NUM) / FILTER_ALPHA_DEN;
    int32_t result = (int32_t)previous + step;

    if (result < 0) {
        result = 0;
    }
    if (result > 65535) {
        result = 65535;
    }

    return (uint16_t)result;
}

