        g_sensor.fault = true;
        hal_log_fault();
        return;
    }

    if (g_sensor.filtered == 0) {
        g_sensor.filtered = raw;
    } else {
        g_sensor.filtered = low_pass_filter_u16(g_sensor.filtered, raw);
    }

    g_sensor.valid = sensor_value_valid(raw);
    g_sensor.fault = !g_sensor.valid;

