#include <stdbool.h>

/*
 * Generic firmware skeleton for sensor acquisition and processing.
 *
 * Features:
 * - Periodic sensor sampling
 * - Moving average filter
 * - Threshold detection
 * - Simple fault/status flags
 *
 * Replace the HAL_* functions with MCU-specific implementations.
 */

/* =========================
 * Configuration
 * ========================= */
#define ADC_MAX_COUNTS           4095.0f     // 12-bit ADC
#define ADC_REF_VOLTAGE          3.3f
#define SENSOR_SAMPLE_PERIOD_MS  10U
#define FILTER_WINDOW_SIZE       16U

#define SENSOR_HIGH_THRESHOLD_V  2.50f
#define SENSOR_LOW_THRESHOLD_V   0.50f

/* =========================
 * Types
 * ========================= */
typedef struct
{
    uint16_t raw_adc;
    float voltage;
    float filtered_voltage;
    bool above_high_threshold;
    bool below_low_threshold;
    bool sensor_fault;
} SensorData_t;

typedef struct
{
    float buffer[FILTER_WINDOW_SIZE];
    uint32_t index;
    uint32_t count;
    float sum;
} MovingAverageFilter_t;

/* =========================
 * Global state
 * ========================= */
static SensorData_t g_sensor_data;
static MovingAverageFilter_t g_filter;

/* =========================
 * HAL function prototypes
 * Replace with MCU-specific code
 * ========================= */
void HAL_SystemInit(void);
void HAL_ADC_Init(void);
uint16_t HAL_ADC_ReadChannel(uint8_t channel);
void HAL_GPIO_Init(void);
void HAL_SetAlarmPin(bool state);
void HAL_DelayMs(uint32_t ms);
uint32_t HAL_GetTickMs(void);

/* =========================
 * Filter functions
 * ========================= */
static void Filter_Init(MovingAverageFilter_t *filter)
{
    uint32_t i;
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0f;

    for (i = 0; i < FILTER_WINDOW_SIZE; i++)
    {
        filter->buffer[i] = 0.0f;
    }
}

static float Filter_Update(MovingAverageFilter_t *filter, float sample)
{
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = sample;
    filter->sum += sample;

    filter->index = (filter->index + 1U) % FILTER_WINDOW_SIZE;

    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->count++;
    }

    return filter->sum / (float)filter->count;
}

/* =========================
 * Sensor processing
 * ========================= */
static float ADC_CountsToVoltage(uint16_t adc_counts)
{
    return ((float)adc_counts / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static bool Sensor_CheckFault(uint16_t adc_counts)
{
    /* Example simple fault heuristic:
     * consider sensor faulty if stuck at rails
     */
    if (adc_counts == 0U || adc_counts >= (uint16_t)ADC_MAX_COUNTS)
    {
        return true;
    }
    return false;
}

static void Sensor_ReadAndProcess(void)
{
    const uint8_t sensor_adc_channel = 0U;

    g_sensor_data.raw_adc = HAL_ADC_ReadChannel(sensor_adc_channel);
    g_sensor_data.voltage = ADC_CountsToVoltage(g_sensor_data.raw_adc);
    g_sensor_data.filtered_voltage = Filter_Update(&g_filter, g_sensor_data.voltage);

    g_sensor_data.sensor_fault = Sensor_CheckFault(g_sensor_data.raw_adc);
    g_sensor_data.above_high_threshold = (g_sensor_data.filtered_voltage > SENSOR_HIGH_THRESHOLD_V);
    g_sensor_data.below_low_threshold = (g_sensor_data.filtered_voltage < SENSOR_LOW_THRESHOLD_V);
}

static void Application_Update(void)
{
    /* Example application behavior:
     * turn on alarm/output if out of range or faulty
     */
    bool alarm = false;

    if (g_sensor_data.sensor_fault)
    {
        alarm = true;
    }

    if (g_sensor_data.above_high_threshold || g_sensor_data.below_low_threshold)
    {
        alarm = true;
    }

    HAL_SetAlarmPin(alarm);
}

/* =========================
 * Main
 * ========================= */
int main(void)
{
    uint32_t last_sample_time = 0U;

    HAL_SystemInit();
    HAL_GPIO_Init();
    HAL_ADC_Init();
    Filter_Init(&g_filter);

    while (1)
    {
        uint32_t now = HAL_GetTickMs();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS)
        {
            last_sample_time = now;

            Sensor_ReadAndProcess();
            Application_Update();
        }

        /* Optional low-power wait or background work here */
    }

    return 0;
}

