};

class ComplementaryFilter {
public:
    RobotState update(const IMUData& imu, const EncoderData& enc, double dt) {
        // Example tilt estimate from accelerometer
        double accel_angle = std::atan2(imu.accel_x, imu.accel_y);

        // Fuse gyro integration with accel angle
        angle_rad_ = alpha_ * (angle_rad_ + imu.gyro_z_rad_s * dt)
                   + (1.0 - alpha_) * accel_angle;

        RobotState state;
        state.angle_rad = angle_rad_;
        state.angular_velocity_rad_s = imu.gyro_z_rad_s;
        state.wheel_position_rad = enc.wheel_position_rad;
        state.wheel_velocity_rad_s = enc.wheel_velocity_rad_s;
        return state;
    }

private:
    double alpha_ = 0.98;
    double angle_rad_ = 0.0;
};

class PID {
public:
    PID(double kp, double ki, double kd)
        : kp_(kp), ki_(ki), kd_(kd) {}

    double update(double target, double measurement, double dt) {
        double error = target - measurement;
        integral_ += error * dt;

        // Basic anti-windup clamp
        integral_ = std::clamp(integral_, -integral_limit_, integral_limit_);

        double derivative = (dt > 0.0) ? (error - prev_error_) / dt : 0.0;
        prev_error_ = error;

        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_;
    double ki_;
    double kd_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
    double integral_limit_ = 10.0;
};

int main() {
    IMU imu;
    Encoder encoder;
    MotorDriver motor;
    ComplementaryFilter fusion;

    // Example: stabilize angle around 0 rad
    PID balance_pid(15.0, 1.0, 0.5);

    constexpr double loop_hz = 200.0;
    constexpr double dt = 1.0 / loop_hz;
    const auto period = std::chrono::duration<double>(dt);

    std::atomic<bool> running{true};

    auto next_time = Clock::now();

    while (running.load()) {
        next_time += std::chrono::duration_cast<Clock::duration>(period);

        // 1. Read sensors
        IMUData imu_data = imu.read();
        EncoderData enc_data = encoder.read();

        // 2. Estimate state
        RobotState state = fusion.update(imu_data, enc_data, dt);

        // 3. Control law
        double target_angle = 0.0;
        double command = balance_pid.update(target_angle, state.angle_rad, dt);

        // Optional damping from angular velocity / wheel velocity
        command -= 0.1 * state.angular_velocity_rad_s;
        command -= 0.05 * state.wheel_velocity_rad_s;

        // 4. Safety checks
        if (std::abs(state.angle_rad) > 0.7) { // ~40 deg
            std::cerr << "Safety stop: tilt exceeded\n";
            motor.stop();
            balance_pid.reset();
            break;
        }

        // 5. Actuate motors
        motor.set_torque_command(command);

        // 6. Sleep until next cycle
        std::this_thread::sleep_until(next_time);
    }

    motor.stop();
    return 0;
}
