```c
#include <stdio.h>
#include <stdint.h>
#include <math.h>
#include <stdbool.h>
#include <time.h>

#define DT_SEC 0.01f           // 10 ms control loop
#define ALPHA  0.98f           // complementary filter coefficient
#define MAX_PWM 1000.0f
#define MIN_PWM 0.0f

typedef struct {
    float gyro_z;      // rad/s
    float accel_angle; // rad
    float wheel_speed_left;   // rad/s
    float wheel_speed_right;  // rad/s
} SensorData;

typedef struct {
    float heading;     // fused heading estimate
    float angular_rate;
    float velocity;
} RobotState;

typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
} PIDController;

typedef struct {
    float left_pwm;
    float right_pwm;
} MotorCommand;

// Mock sensor read
static SensorData read_sensors(void) {
    SensorData s;
    s.gyro_z = 0.02f;
    s.accel_angle = 0.10f;
    s.wheel_speed_left = 5.0f;
    s.wheel_speed_right = 5.2f;
    return s;
}

// Complementary filter for heading
static void sensor_fusion(const SensorData *s, RobotState *state) {
    float gyro_integrated = state->heading + s->gyro_z * DT_SEC;
    state->heading = ALPHA * gyro_integrated + (1.0f - ALPHA) * s->accel_angle;
    state->angular_rate = s->gyro_z;
    state->velocity = (s->wheel_speed_left + s->wheel_speed_right) * 0.5f;
}

static float pid_update(PIDController *pid, float setpoint, float measurement) {
    float error = setpoint - measurement;
    pid->integral += error * DT_SEC;
    float derivative = (error - pid->prev_error) / DT_SEC;
    pid->prev_error = error;
    return pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
}

static float clamp(float x, float min_val, float max_val) {
    if (x < min_val) return min_val;
    if (x > max_val) return max_val;
    return x;
}

// Differential drive motor command
static MotorCommand compute_motor_command(float velocity_cmd,
                                          float heading_cmd,
                                          const RobotState *state,
                                          PIDController *vel_pid,
                                          PIDController *heading_pid) {
    MotorCommand cmd;

    float vel_output = pid_update(vel_pid, velocity_cmd, state->velocity);
    float heading_output = pid_update(heading_pid, heading_cmd, state->heading);

    cmd.left_pwm  = clamp(vel_output - heading_output, MIN_PWM, MAX_PWM);
    cmd.right_pwm = clamp(vel_output + heading_output, MIN_PWM, MAX_PWM);

    return cmd;
}

// Mock motor write
static void apply_motor_command(const MotorCommand *cmd) {
    printf("Left PWM: %.2f, Right PWM: %.2f\n", cmd->left_pwm, cmd->right_pwm);
}

// Simple timing helper
static void sleep_until_next_cycle(clock_t start_time) {
    clock_t target = start_time + (clock_t)(DT_SEC * CLOCKS_PER_SEC);
    while (clock() < target) {
        // busy wait for simplicity
    }
}

int main(void) {
    RobotState state = {0};
    PIDController vel_pid = {.kp = 50.0f, .ki = 10.0f, .kd = 1.0f};
    PIDController heading_pid = {.kp = 100.0f, .ki = 5.0f, .kd = 2.0f};

    float target_velocity = 5.0f; // rad/s
    float target_heading = 0.0f;  // rad

    while (true) {
        clock_t cycle_start = clock();

        // 1. Read sensors
        SensorData sensors = read_sensors();

        // 2. Fuse sensor data into state estimate
        sensor_fusion(&sensors, &state);

        // 3. Compute control output
        MotorCommand cmd = compute_motor_command(
            target_velocity,
            target_heading,
            &state,
            &vel_pid,
            &heading_pid
        );

        // 4. Apply motor commands
        apply_motor_command(&cmd);

        // 5. Wait for next control cycle
        sleep_until_next_cycle(cycle_start);
    }

    return 0;
}
```

