```cpp
#include <chrono>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <thread>
#include <atomic>
#include <mutex>
#include <algorithm>

using Clock = std::chrono::steady_clock;

// =========================
// Data structures
// =========================

struct IMUSample {
    double accel_x = 0.0;   // m/s^2
    double accel_y = 0.0;   // m/s^2
    double gyro_z  = 0.0;   // rad/s
    double dt      = 0.01;  // seconds
};

struct EncoderSample {
    double left_velocity  = 0.0; // m/s
    double right_velocity = 0.0; // m/s
    double dt             = 0.01;
};

struct RobotState {
    double x = 0.0;         // meters
    double y = 0.0;         // meters
    double theta = 0.0;     // radians
    double linear_vel = 0.0; 
    double angular_vel = 0.0;
};

// =========================
// Utility
// =========================

static double clamp(double value, double min_v, double max_v) {
    return std::max(min_v, std::min(value, max_v));
}

static double wrapAngle(double angle) {
    while (angle > M_PI) angle -= 2.0 * M_PI;
    while (angle < -M_PI) angle += 2.0 * M_PI;
    return angle;
}

// =========================
// PID controller
// =========================

class PID {
public:
    PID(double kp, double ki, double kd, double min_out, double max_out)
        : kp_(kp), ki_(ki), kd_(kd), min_out_(min_out), max_out_(max_out) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = (dt > 1e-9) ? (error - prev_error_) / dt : 0.0;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = clamp(output, min_out_, max_out_);

        prev_error_ = error;
        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_;
    double ki_;
    double kd_;
    double min_out_;
    double max_out_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
};

// =========================
// Sensor fusion
// Simple complementary fusion between gyro heading and wheel odometry
// =========================

class SensorFusion {
public:
    explicit SensorFusion(double wheel_base)
        : wheel_base_(wheel_base) {}

    RobotState update(const IMUSample& imu, const EncoderSample& enc) {
        // Differential drive kinematics
        double v = 0.5 * (enc.left_velocity + enc.right_velocity);
        double omega_odom = (enc.right_velocity - enc.left_velocity) / wheel_base_;

        // Complementary fusion for angular velocity
        double alpha = 0.98;
        state_.angular_vel = alpha * imu.gyro_z + (1.0 - alpha) * omega_odom;
        state_.linear_vel = v;

        // Integrate heading
        state_.theta = wrapAngle(state_.theta + state_.angular_vel * imu.dt);

        // Integrate position
        state_.x += state_.linear_vel * std::cos(state_.theta) * imu.dt;
        state_.y += state_.linear_vel * std::sin(state_.theta) * imu.dt;

        return state_;
    }

    const RobotState& state() const {
        return state_;
    }

private:
    double wheel_base_;
    RobotState state_;
};

// =========================
// Motor controller interface
// =========================

class MotorController {
public:
    void setMotorCommands(double left_cmd, double right_cmd) {
        // In real hardware: send PWM/current/velocity command to motor drivers
        left_cmd_ = clamp(left_cmd, -1.0, 1.0);
        right_cmd_ = clamp(right_cmd, -1.0, 1.0);

        std::cout << "[Motor] left=" << left_cmd_ 
                  << " right=" << right_cmd_ << "\n";
    }

    double leftCommand() const { return left_cmd_; }
    double rightCommand() const { return right_cmd_; }

private:
    double left_cmd_ = 0.0;
    double right_cmd_ = 0.0;
};

// =========================
// Mock sensors
// =========================

class MockSensors {
public:
    IMUSample readIMU(double dt, double commanded_angular_vel) {
        IMUSample imu;
        imu.dt = dt;
        imu.gyro_z = commanded_angular_vel; // simplistic simulation
        imu.accel_x = 0.0;
        imu.accel_y = 0.0;
        return imu;
    }

    EncoderSample readEncoders(double dt, double left_vel, double right_vel) {
        EncoderSample enc;
        enc.dt = dt;
        enc.left_velocity = left_vel;
        enc.right_velocity = right_vel;
        return enc;
    }
};

// =========================
// Robot control loop
// =========================

class RobotControlLoop {
public:
    RobotControlLoop(double wheel_base, double control_hz)
        : fusion_(wheel_base),
          left_pid_(2.0, 0.2, 0.01, -1.0, 1.0),
          right_pid_(2.0, 0.2, 0.01, -1.0, 1.0),
          wheel_base_(wheel_base),
          control_period_(1.0 / control_hz) {}

    void setTarget(double linear_velocity, double angular_velocity) {
        std::lock_guard<std::mutex> lock(target_mutex_);
        target_linear_ = linear_velocity;
        target_angular_ = angular_velocity;
    }

    void run(std::atomic<bool>& running) {
        auto next_tick = Clock::now();

        // Simulated current wheel velocities
        double measured_left_vel = 0.0;
        double measured_right_vel = 0.0;

        while (running.load()) {
            auto start = Clock::now();

            double target_linear;
            double target_angular;
            {
                std::lock_guard<std::mutex> lock(target_mutex_);
                target_linear = target_linear_;
                target_angular = target_angular_;
            }

            // Convert body velocity targets to wheel targets
            double target_left_vel =
                target_linear - 0.5 * wheel_base_ * target_angular;
            double target_right_vel =
                target_linear + 0.5 * wheel_base_ * target_angular;

            // Read sensors
            IMUSample imu = sensors_.readIMU(control_period_, target_angular);
            EncoderSample enc = sensors_.readEncoders(
                control_period_, measured_left_vel, measured_right_vel);

            // Fuse state
            RobotState state = fusion_.update(imu, enc);

            // Wheel PID control
            double left_cmd = left_pid_.update(
                target_left_vel, enc.left_velocity, control_period_);
            double right_cmd = right_pid_.update(
                target_right_vel, enc.right_velocity, control_period_);

            // Send motor commands
            motors_.setMotorCommands(left_cmd, right_cmd);

            // Very simple plant simulation so values change over time
            measured_left_vel += 0.2 * (left_cmd - measured_left_vel);
            measured_right_vel += 0.2 * (right_cmd - measured_right_vel);

            // Debug output
            std::cout << "[State] x=" << state.x
                      << " y=" << state.y
                      << " theta=" << state.theta
                      << " v=" << state.linear_vel
                      << " w=" << state.angular_vel
                      << "\n";

            next_tick += std::chrono::duration_cast<Clock::duration>(
                std::chrono::duration<double>(control_period_));
            std::this_thread::sleep_until(next_tick);

            auto end = Clock::now();
            std::chrono::duration<double, std::milli> loop_time = end - start;
            std::cout << "[Loop] " << loop_time.count() << " ms\n";
        }

        motors_.setMotorCommands(0.0, 0.0);
    }

private:
    SensorFusion fusion_;
    PID left_pid_;
    PID right_pid_;
    MotorController motors_;
    MockSensors sensors_;

    double wheel_base_;
    double control_period_;

    std::mutex target_mutex_;
    double target_linear_ = 0.0;
    double target_angular_ = 0.0;
};

// =========================
// Main
// =========================

int main() {
    std::atomic<bool> running{true};

    RobotControlLoop controller(0.4, 100.0); // 0.4m wheel base, 100 Hz loop
    controller.setTarget(0.5, 0.3);          // m/s, rad/s

    std::thread control_thread([&]() {
        controller.run(running);
    });

    std::this_thread::sleep_for(std::chrono::seconds(5));

    controller.setTarget(0.2, -0.5);
    std::this_thread::sleep_for(std::chrono::seconds(5));

    running = false;
    control_thread.join();

    return 0;
}
```

