using Clock = std::chrono::steady_clock;
using namespace std::chrono;

// ------------------------------
// Hardware abstraction interfaces
// ------------------------------

struct IMUData {
    double gyro_z_rad_s;   // angular velocity
    double accel_angle_rad; // estimated tilt angle from accelerometer
    bool valid;
};

struct EncoderData {
    double position_rad;
    double velocity_rad_s;
    bool valid;
};

struct MotorCommand {
    double torque_command; // normalized or Nm depending on driver
};

class IMU {
public:
    IMUData read() {
        // TODO: Replace with real hardware access
        IMUData d{};
        d.gyro_z_rad_s = 0.01;
        d.accel_angle_rad = 0.02;
        d.valid = true;
        return d;
    }
};

class Encoder {
public:
    EncoderData read() {
        // TODO: Replace with real hardware access
        EncoderData d{};
        d.position_rad = 0.1;
        d.velocity_rad_s = 0.0;
        d.valid = true;
        return d;
    }
};

class MotorDriver {
public:
    void write(const MotorCommand& cmd) {
        // TODO: Replace with PWM/CAN/SPI/UART driver write
        // For demo purposes, just print infrequently if desired
        (void)cmd;
    }

    void stop() {
        MotorCommand cmd{};
        cmd.torque_command = 0.0;
        write(cmd);
    }
};

// ------------------------------
// Utility
// ------------------------------

static double clamp(double v, double lo, double hi) {
    return std::max(lo, std::min(v, hi));
}

// ------------------------------
// Sensor fusion: simple complementary filter
// ------------------------------

class AttitudeEstimator {
public:
    void reset(double angle_rad = 0.0) {
        angle_estimate_rad_ = angle_rad;
    }

    double update(const IMUData& imu, double dt) {
        // Complementary filter:
        // angle = alpha * (angle + gyro*dt) + (1-alpha)*accel_angle
        constexpr double alpha = 0.98;

        if (!imu.valid || dt <= 0.0) {
            return angle_estimate_rad_;
        }

        double gyro_integrated = angle_estimate_rad_ + imu.gyro_z_rad_s * dt;
        angle_estimate_rad_ = alpha * gyro_integrated + (1.0 - alpha) * imu.accel_angle_rad;
        return angle_estimate_rad_;
    }

    double angle() const {
        return angle_estimate_rad_;
    }

private:
    double angle_estimate_rad_ = 0.0;
};

// ------------------------------
// PID controller
// ------------------------------

class PID {
public:
    PID(double kp, double ki, double kd, double i_min, double i_max)
        : kp_(kp), ki_(ki), kd_(kd), i_min_(i_min), i_max_(i_max) {}

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
        first_update_ = true;
    }

    double update(double setpoint, double measurement, double dt) {
        if (dt <= 0.0) return 0.0;

        double error = setpoint - measurement;

        integral_ += error * dt;
        integral_ = clamp(integral_, i_min_, i_max_);

        double derivative = 0.0;
        if (!first_update_) {
            derivative = (error - prev_error_) / dt;
        } else {
            first_update_ = false;
        }

        prev_error_ = error;

        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

private:
    double kp_;
    double ki_;
    double kd_;
    double i_min_;
    double i_max_;

    double integral_ = 0.0;
    double prev_error_ = 0.0;
    bool first_update_ = true;
};

// ------------------------------
// Robot controller
// Example: stabilize angle while damping wheel velocity
// ------------------------------

struct RobotState {
    double fused_angle_rad = 0.0;
    double wheel_position_rad = 0.0;
    double wheel_velocity_rad_s = 0.0;
};

class RobotController {
public:
    RobotController()
        : balance_pid_(20.0, 2.0, 0.5, -1.0, 1.0),
          velocity_pid_(1.0, 0.2, 0.0, -1.0, 1.0) {}

    void reset() {
        estimator_.reset(0.0);
        balance_pid_.reset();
        velocity_pid_.reset();
    }

    MotorCommand update(const IMUData& imu, const EncoderData& enc, double dt) {
        RobotState state;

        if (imu.valid) {
            state.fused_angle_rad = estimator_.update(imu, dt);
        } else {
            state.fused_angle_rad = estimator_.angle();
        }

        if (enc.valid) {
            state.wheel_position_rad = enc.position_rad;
            state.wheel_velocity_rad_s = enc.velocity_rad_s;
        }

        // Outer objective: angle stabilization around 0 rad
        double angle_setpoint = 0.0;

        // Optional velocity damping term
        double velocity_correction = velocity_pid_.update(0.0, state.wheel_velocity_rad_s, dt);

        double torque = balance_pid_.update(angle_setpoint, state.fused_angle_rad, dt);
        torque += velocity_correction;

        torque = clamp(torque, -5.0, 5.0);

        MotorCommand cmd{};
        cmd.torque_command = torque;
        last_state_ = state;
        return cmd;
    }

    const RobotState& lastState() const {
        return last_state_;
    }

private:
    AttitudeEstimator estimator_;
    PID balance_pid_;
    PID velocity_pid_;
    RobotState last_state_;
};

// ------------------------------
// Real-time style loop
// ------------------------------

std::atomic<bool> running{true};

int main() {
    IMU imu;
    Encoder encoder;
    MotorDriver motor;
    RobotController controller;

    controller.reset();

    constexpr double loop_hz = 500.0;
    constexpr auto loop_period = microseconds(static_cast<int64_t>(1e6 / loop_hz));

    auto next_wakeup = Clock::now() + loop_period;
    auto last_time = Clock::now();

    std::cout << "Starting control loop at " << loop_hz << " Hz\n";

    while (running.load(std::memory_order_relaxed)) {
        auto now = Clock::now();
        double dt = duration<double>(now - last_time).count();
        last_time = now;

        // Read sensors
        IMUData imu_data = imu.read();
        EncoderData enc_data = encoder.read();

        // Basic sensor validity handling
        if (!imu_data.valid || !enc_data.valid) {
            motor.stop();
            std::cerr << "Sensor invalid, stopping motor\n";
            std::this_thread::sleep_until(next_wakeup);
            next_wakeup += loop_period;
            continue;
        }

        // Control update
        MotorCommand cmd = controller.update(imu_data, enc_data, dt);

        // Safety clamp
        cmd.torque_command = clamp(cmd.torque_command, -5.0, 5.0);

        // Write actuator command
        motor.write(cmd);

        // Optional debug at low rate
        static int counter = 0;
        if (++counter % 100 == 0) {
            const auto& st = controller.lastState();
            std::cout
                << "angle=" << st.fused_angle_rad
                << " vel=" << st.wheel_velocity_rad_s
                << " torque=" << cmd.torque_command
                << " dt=" << dt
                << "\n";
        }

        // Sleep until next cycle
        std::this_thread::sleep_until(next_wakeup);
        next_wakeup += loop_period;

        // Detect significant overrun
        auto after_sleep = Clock::now();
        if (after_sleep > next_wakeup + milliseconds(5)) {
            std::cerr << "Loop overrun detected\n";
        }
    }

    motor.stop();
    return 0;
}
