#include <chrono>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <thread>
#include <atomic>
#include <algorithm>

using Clock = std::chrono::steady_clock;

struct IMUData {
    float gyro_z_rad_s;
    float accel_x_m_s2;
    float accel_y_m_s2;
};

struct EncoderData {
    float wheel_position_rad;
    float wheel_velocity_rad_s;
};

struct FusedState {
    float heading_rad;
    float wheel_position_rad;
    float wheel_velocity_rad_s;
};

struct ControlCommand {
    float target_velocity_rad_s;
};

class PID {
public:
    PID(float kp, float ki, float kd, float min_out, float max_out)
        : kp_(kp), ki_(ki), kd_(kd), min_out_(min_out), max_out_(max_out) {}

    float update(float target, float measured, float dt) {
        float error = target - measured;
        integral_ += error * dt;
        float derivative = dt > 0.0f ? (error - prev_error_) / dt : 0.0f;

        float output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = std::clamp(output, min_out_, max_out_);

        prev_error_ = error;
        return output;
    }

private:
    float kp_;
    float ki_;
    float kd_;
    float min_out_;
    float max_out_;
    float integral_ = 0.0f;
    float prev_error_ = 0.0f;
