class SensorFusion {
public:
    FusedState update(const IMUData& imu, const EncoderData& enc, float dt) {
        // Complementary-style heading integration from gyro.
        heading_rad_ += imu.gyro_z_rad_s * dt;

        // Wheel state directly from encoder for now.
        wheel_position_rad_ = enc.wheel_position_rad;

        // Blend measured encoder velocity with accel-derived estimate placeholder.
        // In a real robot, use EKF / Mahony / Madgwick / invariant filter as appropriate.
        float accel_velocity_est = wheel_velocity_rad_s_ + imu.accel_x_m_s2 * dt * 0.1f;
        wheel_velocity_rad_s_ = alpha_ * enc.wheel_velocity_rad_s +
                                (1.0f - alpha_) * accel_velocity_est;

        return {
            heading_rad_,
            wheel_position_rad_,
            wheel_velocity_rad_s_
        };
    }

private:
    float alpha_ = 0.95f;
    float heading_rad_ = 0.0f;
    float wheel_position_rad_ = 0.0f;
    float wheel_velocity_rad_s_ = 0.0f;
};

