class RoboticsController {
public:
    RoboticsController()
        : velocity_pid_(2.0f, 0.5f, 0.1f, -1.0f, 1.0f) {}

    void setCommand(const ControlCommand& cmd) {
        command_ = cmd;
    }

    void run() {
        constexpr float control_period_s = 0.01f; // 100 Hz
        auto next_tick = Clock::now();

        while (running_) {
            auto start = Clock::now();

            IMUData imu = hw_.readIMU();
            EncoderData enc = hw_.readEncoder();

            FusedState state = fusion_.update(imu, enc, control_period_s);

            float motor_cmd = velocity_pid_.update(
                command_.target_velocity_rad_s,
                state.wheel_velocity_rad_s,
                control_period_s
            );

            hw_.writeMotorCommand(motor_cmd);

            logState(state, motor_cmd);

            next_tick += std::chrono::milliseconds(10);
            std::this_thread::sleep_until(next_tick);

            auto end = Clock::now();
            auto loop_time_us =
                std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

            if (loop_time_us > 10000) {
                std::cerr << "Warning: control loop overrun: "
                          << loop_time_us << " us\n";
            }
        }
    }

    void stop() {
        running_ = false;
    }

private:
    void logState(const FusedState& state, float motor_cmd) {
        std::cout
            << "heading=" << state.heading_rad
            << " pos=" << state.wheel_position_rad
            << " vel=" << state.wheel_velocity_rad_s
            << " target=" << command_.target_velocity_rad_s
            << " cmd=" << motor_cmd
            << "\n";
    }

    std::atomic<bool> running_{true};
    RobotHardware hw_;
    SensorFusion fusion_;
    PID velocity_pid_;
    ControlCommand command_{5.0f};
};

int main() {
    RoboticsController controller;
    controller.setCommand({3.0f});

    std::thread control_thread([&controller]() {
        controller.run();
    });

    std::this_thread::sleep_for(std::chrono::seconds(3));
    controller.stop();

    control_thread.join();
    return 0;
}
