```cpp
#include <chrono>
#include <cmath>
#include <iostream>
#include <thread>
#include <random>
#include <algorithm>

struct IMUData {
    double gyro_rate;   // rad/s
    double accel_angle; // rad
};

struct EncoderData {
    double position;    // rad
    double velocity;    // rad/s
};

class ComplementaryFilter {
public:
    ComplementaryFilter(double alpha) : alpha_(alpha), angle_(0.0) {}

    double update(double gyro_rate, double accel_angle, double dt) {
        angle_ = alpha_ * (angle_ + gyro_rate * dt) + (1.0 - alpha_) * accel_angle;
        return angle_;
    }

private:
    double alpha_;
    double angle_;
};

class PID {
public:
    PID(double kp, double ki, double kd)
        : kp_(kp), ki_(ki), kd_(kd), integral_(0.0), prev_error_(0.0) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = (error - prev_error_) / dt;
        prev_error_ = error;
        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

private:
    double kp_, ki_, kd_;
    double integral_;
    double prev_error_;
};

class RobotSim {
public:
    RobotSim() : angle_(0.0), angular_velocity_(0.0) {}

    void applyMotorCommand(double torque_cmd, double dt) {
        // Very simple 1D rotational dynamics:
        // theta_ddot = torque - damping * theta_dot
        const double damping = 0.2;
        double angular_accel = torque_cmd - damping * angular_velocity_;
        angular_velocity_ += angular_accel * dt;
        angle_ += angular_velocity_ * dt;
    }

    IMUData readIMU() {
        return {
            angular_velocity_ + noise(0.01),
            angle_ + noise(0.02)
        };
    }

    EncoderData readEncoder() {
        return {
            angle_ + noise(0.005),
            angular_velocity_ + noise(0.005)
        };
    }

    double trueAngle() const { return angle_; }

private:
    double angle_;
    double angular_velocity_;

    double noise(double stddev) {
        static std::default_random_engine gen(std::random_device{}());
        std::normal_distribution<double> dist(0.0, stddev);
        return dist(gen);
    }
};

int main() {
    constexpr double dt = 0.01; // 100 Hz control loop
    constexpr int steps = 1000;

    RobotSim robot;
    ComplementaryFilter filter(0.98);
    PID pid(8.0, 0.5, 0.2);

    double target_angle = 1.0; // rad

    for (int i = 0; i < steps; ++i) {
        auto loop_start = std::chrono::steady_clock::now();

        // Read sensors
        IMUData imu = robot.readIMU();
        EncoderData enc = robot.readEncoder();

        // Simple sensor fusion:
        // fuse gyro + accel into an angle estimate
        double fused_angle = filter.update(imu.gyro_rate, imu.accel_angle, dt);

        // Optionally blend with encoder position
        fused_angle = 0.9 * fused_angle + 0.1 * enc.position;

        // Control
        double motor_cmd = pid.update(target_angle, fused_angle, dt);

        // Clamp actuator command
        motor_cmd = std::clamp(motor_cmd, -10.0, 10.0);

        // Apply to plant
        robot.applyMotorCommand(motor_cmd, dt);

        // Print occasionally
        if (i % 50 == 0) {
            std::cout
                << "step=" << i
                << " target=" << target_angle
                << " fused=" << fused_angle
                << " true=" << robot.trueAngle()
                << " cmd=" << motor_cmd
                << "\n";
        }

        // Maintain loop rate
        auto loop_end = std::chrono::steady_clock::now();
        std::chrono::duration<double> elapsed = loop_end - loop_start;
        double sleep_time = dt - elapsed.count();
        if (sleep_time > 0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(sleep_time));
        }
    }

    return 0;
}
