#include <iostream>
#include <chrono>
#include <thread>
#include <random>
#include <cmath>

using Clock = std::chrono::steady_clock;

// Simulated IMU sensor
class IMUSensor {
public:
    IMUSensor() : gen(rd()), noise_dist(0.0, 0.5) {}

    double readAngle(double true_angle) {
        return true_angle + noise_dist(gen);
    }

    double readGyroRate(double true_rate) {
        return true_rate + noise_dist(gen) * 0.1;
    }

private:
    std::random_device rd;
    std::mt19937 gen;
    std::normal_distribution<> noise_dist;
};

// Simple complementary filter for sensor fusion
class ComplementaryFilter {
public:
    ComplementaryFilter(double alpha) : alpha(alpha), estimated_angle(0.0) {}

    double update(double accel_angle, double gyro_rate, double dt) {
        estimated_angle = alpha * (estimated_angle + gyro_rate * dt)
                        + (1.0 - alpha) * accel_angle;
        return estimated_angle;
    }

private:
    double alpha;
    double estimated_angle;
};

// PID controller
class PIDController {
public:
    PIDController(double kp, double ki, double kd)
        : kp(kp), ki(ki), kd(kd), integral(0.0), prev_error(0.0) {}

    double update(double target, double measured, double dt) {
        double error = target - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;
        return kp * error + ki * integral + kd * derivative;
    }

private:
    double kp, ki, kd;
    double integral;
    double prev_error;
};

// Simulated motor
class Motor {
public:
    void setCommand(double cmd) {
        if (cmd > 100.0) cmd = 100.0;
        if (cmd < -100.0) cmd = -100.0;
        command = cmd;
    }

    double getCommand() const {
        return command;
    }

private:
    double command = 0.0;
};

// Simple simulated robot plant
class RobotPlant {
public:
    RobotPlant() : angle(10.0), rate(0.0) {}

    void update(double motor_cmd, double dt) {
        // Very simplified dynamics:
        // motor command pushes angle back toward 0
        double torque = -0.1 * motor_cmd;
        rate += torque * dt;
        angle += rate * dt;

        // small natural drift
        rate += 0.01 * std::sin(angle) * dt;
    }

    double getAngle() const { return angle; }
    double getRate() const { return rate; }

private:
    double angle;
    double rate;
};

int main() {
    IMUSensor imu;
    ComplementaryFilter filter(0.98);
    PIDController pid(8.0, 0.5, 1.5);
    Motor motor;
    RobotPlant robot;

    const double target_angle = 0.0;
    const double dt = 0.01; // 10 ms = 100 Hz loop
    const int iterations = 1000;

    for (int i = 0; i < iterations; ++i) {
        auto loop_start = Clock::now();

        // Simulated true state
        double true_angle = robot.getAngle();
        double true_rate = robot.getRate();

        // Sensor reads
        double accel_angle = imu.readAngle(true_angle);
        double gyro_rate = imu.readGyroRate(true_rate);

        // Sensor fusion
        double estimated_angle = filter.update(accel_angle, gyro_rate, dt);

        // Control
        double motor_cmd = pid.update(target_angle, estimated_angle, dt);
        motor.setCommand(motor_cmd);

        // Apply to plant
        robot.update(motor.getCommand(), dt);

        // Debug output
        std::cout
            << "True angle: " << true_angle
            << " | Estimated angle: " << estimated_angle
            << " | Motor cmd: " << motor.getCommand()
            << std::endl;

        // Maintain loop timing
        std::this_thread::sleep_until(loop_start + std::chrono::milliseconds(10));
    }

    return 0;
}
