#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

struct IMUData {
    double accel_angle;   // radians
    double gyro_rate;     // radians/sec
};

struct EncoderData {
    double wheel_velocity; // rad/sec
};

struct FusedState {
    double angle;          // radians
    double angular_rate;   // radians/sec
    double wheel_velocity; // rad/sec
};

class ComplementaryFilter {
public:
    explicit ComplementaryFilter(double alpha = 0.98)
        : alpha_(alpha), angle_estimate_(0.0) {}

    FusedState update(const IMUData& imu, const EncoderData& enc, double dt) {
        angle_estimate_ = alpha_ * (angle_estimate_ + imu.gyro_rate * dt)
                        + (1.0 - alpha_) * imu.accel_angle;

        FusedState state;
        state.angle = angle_estimate_;
        state.angular_rate = imu.gyro_rate;
        state.wheel_velocity = enc.wheel_velocity;
        return state;
    }

private:
    double alpha_;
    double angle_estimate_;
};

class PIDController {
public:
    PIDController(double kp, double ki, double kd)
        : kp_(kp), ki_(ki), kd_(kd), integral_(0.0), prev_error_(0.0) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = (error - prev_error_) / dt;
        prev_error_ = error;
        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

private:
    double kp_, ki_, kd_;
    double integral_;
    double prev_error_;
};

class Robot {
public:
    Robot()
        : true_angle_(0.1), true_gyro_rate_(0.0), true_wheel_velocity_(0.0), motor_command_(0.0) {}

    IMUData readIMU() {
        IMUData imu;
        imu.accel_angle = true_angle_ + noise(0.01);
        imu.gyro_rate = true_gyro_rate_ + noise(0.005);
        return imu;
    }

    EncoderData readEncoder() {
        EncoderData enc;
        enc.wheel_velocity = true_wheel_velocity_ + noise(0.01);
        return enc;
    }

    void applyMotorCommand(double cmd, double dt) {
        motor_command_ = std::clamp(cmd, -10.0, 10.0);

        true_gyro_rate_ = -2.0 * true_angle_ + 0.5 * motor_command_;
        true_angle_ += true_gyro_rate_ * dt;

        true_wheel_velocity_ = 0.8 * motor_command_;
    }

private:
    double true_angle_;
    double true_gyro_rate_;
    double true_wheel_velocity_;
    double motor_command_;

    double noise(double amplitude) {
        return amplitude * (2.0 * rand() / double(RAND_MAX) - 1.0);
    }
};

int main() {
    Robot robot;
    ComplementaryFilter filter(0.98);
    PIDController pid(15.0, 1.0, 0.5);

    const double dt = 0.01; // 100 Hz
    const double target_angle = 0.0;

    for (int i = 0; i < 500; ++i) {
        auto loop_start = std::chrono::steady_clock::now();

        IMUData imu = robot.readIMU();
        EncoderData enc = robot.readEncoder();

        FusedState state = filter.update(imu, enc, dt);

        double motor_cmd = pid.update(target_angle, state.angle, dt);

        robot.applyMotorCommand(motor_cmd, dt);

        std::cout << "t=" << i * dt
                  << " angle_est=" << state.angle
                  << " gyro=" << state.angular_rate
                  << " wheel_vel=" << state.wheel_velocity
                  << " motor_cmd=" << motor_cmd
                  << std::endl;

        auto loop_end = loop_start + std::chrono::milliseconds(10);
        std::this_thread::sleep_until(loop_end);
    }

    return 0;
}
