    Encoder encoder;
    Motor motor;
    PID pid{2.0, 0.5, 0.1};

    const double dt = 0.01; // 10 ms loop = 100 Hz
    const double targetSpeed = 1.2;

    double fusedAngle = 0.0;

    for (int i = 0; i < 500; ++i) {
        auto loopStart = std::chrono::steady_clock::now();

        // Read sensors
        double gyroRate = imu.readGyroRate();
        double accelAngle = imu.readAccelAngle();
        double speed = encoder.readSpeed();

        // Sensor fusion: complementary filter
        fusedAngle = 0.98 * (fusedAngle + gyroRate * dt) + 0.02 * accelAngle;

        // Control based on speed error
        double control = pid.update(targetSpeed, speed, dt);

        // Simple stabilization compensation using fused angle
        control -= 0.5 * fusedAngle;

        // Send command to motor
        motor.setCommand(control);

        std::cout << "Speed: " << speed
                  << " Fused angle: " << fusedAngle
                  << " Control: " << control << std::endl;

        // Maintain fixed loop rate
        std::this_thread::sleep_until(loopStart + std::chrono::milliseconds(10));
    }

    return 0;
}
