Below is a compact example in <language>C</language>, my top recommendation for embedded sensor pipelines. It shows a typical stream-processing approach:

- read accelerometer samples
- compute acceleration magnitude
- smooth with a moving average
- estimate baseline variance
- flag anomalies when deviation exceeds a threshold for several samples

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 2.5f
#define CONSECUTIVE_LIMIT 3

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
    float sum_sq;
    uint8_t consecutive_anomalies;
} SensorPipeline;

static void pipeline_init(SensorPipeline *p) {
    p->index = 0;
    p->count = 0;
    p->sum = 0.0f;
    p->sum_sq = 0.0f;
    p->consecutive_anomalies = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->mag_window[i] = 0.0f;
    }
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static bool pipeline_process(SensorPipeline *p, AccelSample sample, float *score_out) {
    float mag = accel_magnitude(sample);

    if (p->count == WINDOW_SIZE) {
        float old = p->mag_window[p->index];
        p->sum -= old;
        p->sum_sq -= old * old;
    } else {
        p->count++;
    }

    p->mag_window[p->index] = mag;
    p->sum += mag;
    p->sum_sq += mag * mag;
    p->index = (p->index + 1) % WINDOW_SIZE;

    if (p->count < WINDOW_SIZE) {
        *score_out = 0.0f;
        return false;
    }

    float mean = p->sum / WINDOW_SIZE;
    float variance = (p->sum_sq / WINDOW_SIZE) - (mean * mean);
    if (variance < 1e-6f) variance = 1e-6f;
    float stddev = sqrtf(variance);

    float score = fabsf(mag - mean) / stddev;
    *score_out = score;

    if (score > ANOMALY_THRESHOLD) {
        p->consecutive_anomalies++;
    } else {
        p->consecutive_anomalies = 0;
    }

    return (p->consecutive_anomalies >= CONSECUTIVE_LIMIT);
}

int main(void) {
    SensorPipeline pipeline;
    pipeline_init(&pipeline);

    AccelSample test_data[] = {
        {0.01f, 0.02f, 0.98f}, {0.00f, 0.01f, 1.02f}, {0.03f, 0.02f, 0.99f},
        {0.01f, 0.00f, 1.01f}, {0.02f, 0.01f, 1.00f}, {0.01f, 0.03f, 0.97f},
        {0.02f, 0.02f, 1.01f}, {0.00f, 0.00f, 0.99f}, {0.01f, 0.01f, 1.00f},
        {0.02f, 0.02f, 0.98f}, {0.01f, 0.01f, 1.02f}, {0.00f, 0.03f, 0.99f},
        {0.02f, 0.02f, 1.00f}, {0.01f, 0.01f, 0.98f}, {0.00f, 0.02f, 1.01f},
        {0.01f, 0.01f, 1.00f},

        // anomalous burst
        {1.5f, 1.2f, 2.2f}, {1.7f, 1.4f, 2.0f}, {1.6f, 1.3f, 2.1f}
    };

    size_t n = sizeof(test_data) / sizeof(test_data[0]);
    for (size_t i = 0; i < n; i++) {
        float score;
        bool anomaly = pipeline_process(&pipeline, test_data[i], &score);
        printf("sample %zu score=%.3f anomaly=%s\n",
               i, score, anomaly ? "YES" : "no");
    }

    return 0;
}
```

A few practical embedded notes:

- Replace `test_data` with sensor reads from your accelerometer driver.
- On very small MCUs, you may want fixed-point math instead of `float`/`sqrtf`.
- In real deployments, gravity compensation, high-pass filtering, and per-axis features often improve detection.
- You may also want a cooldown/hysteresis period so one event does not retrigger repeatedly.

