Below is a compact example in <language>C</language>, the top recommendation for embedded work. It implements a simple pipeline:

- calibration / bias estimate
- low-pass gravity estimate
- high-pass dynamic acceleration
- magnitude calculation
- rolling mean/variance
- z-score anomaly detection
- refractory period to avoid repeated triggers

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} RunningStats;

typedef struct {
    float gravity_x;
    float gravity_y;
    float gravity_z;

    float bias_x;
    float bias_y;
    float bias_z;

    RunningStats mag_stats;

    float alpha_gravity;       // low-pass coefficient, e.g. 0.9
    float z_threshold;         // e.g. 3.5
    uint32_t warmup_samples;   // e.g. 100
    uint32_t refractory_ticks; // e.g. 20

    uint32_t tick;
    uint32_t last_anomaly_tick;
} AnomalyDetector;

static void running_stats_init(RunningStats *s) {
    s->mean = 0.0f;
    s->m2 = 0.0f;
    s->count = 0;
}

static void running_stats_update(RunningStats *s, float x) {
    s->count++;
    float delta = x - s->mean;
    s->mean += delta / (float)s->count;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float running_stats_variance(const RunningStats *s) {
    if (s->count < 2) return 0.0f;
    return s->m2 / (float)(s->count - 1);
}

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

void anomaly_detector_init(AnomalyDetector *d,
                           float alpha_gravity,
                           float z_threshold,
                           uint32_t warmup_samples,
                           uint32_t refractory_ticks) {
    d->gravity_x = 0.0f;
    d->gravity_y = 0.0f;
    d->gravity_z = 0.0f;

    d->bias_x = 0.0f;
    d->bias_y = 0.0f;
    d->bias_z = 0.0f;

    running_stats_init(&d->mag_stats);

    d->alpha_gravity = alpha_gravity;
    d->z_threshold = z_threshold;
    d->warmup_samples = warmup_samples;
    d->refractory_ticks = refractory_ticks;

    d->tick = 0;
    d->last_anomaly_tick = 0;
}

void anomaly_detector_set_bias(AnomalyDetector *d, float bx, float by, float bz) {
    d->bias_x = bx;
    d->bias_y = by;
    d->bias_z = bz;
}

bool anomaly_detector_process(AnomalyDetector *d, AccelSample raw, float *out_score) {
    d->tick++;

    // 1) Bias correction
    float x = raw.x - d->bias_x;
    float y = raw.y - d->bias_y;
    float z = raw.z - d->bias_z;

    // 2) Estimate gravity with low-pass filter
    d->gravity_x = d->alpha_gravity * d->gravity_x + (1.0f - d->alpha_gravity) * x;
    d->gravity_y = d->alpha_gravity * d->gravity_y + (1.0f - d->alpha_gravity) * y;
    d->gravity_z = d->alpha_gravity * d->gravity_z + (1.0f - d->alpha_gravity) * z;

    // 3) Dynamic acceleration = high-pass component
    float dx = x - d->gravity_x;
    float dy = y - d->gravity_y;
    float dz = z - d->gravity_z;

    // 4) Magnitude of dynamic motion
    float mag = fast_sqrtf(dx * dx + dy * dy + dz * dz);

    // 5) Warmup/statistics update
    if (d->mag_stats.count < d->warmup_samples) {
        running_stats_update(&d->mag_stats, mag);
        if (out_score) *out_score = 0.0f;
        return false;
    }

    float variance = running_stats_variance(&d->mag_stats);
    float stddev = variance > 1e-8f ? fast_sqrtf(variance) : 1e-4f;
    float zscore = (mag - d->mag_stats.mean) / stddev;

    if (out_score) *out_score = zscore;

    // Update baseline after computing score
    running_stats_update(&d->mag_stats, mag);

    // 6) Refractory period
    bool in_refractory = (d->tick - d->last_anomaly_tick) < d->refractory_ticks;
    bool is_anomaly = (!in_refractory) && (zscore > d->z_threshold);

    if (is_anomaly) {
        d->last_anomaly_tick = d->tick;
    }

    return is_anomaly;
}
```

