It includes:

- sample ingestion for `x, y, z`
- magnitude calculation
- low-pass baseline tracking
- residual/anomaly score
- adaptive noise estimate
- threshold-based anomaly detection
- simple debounce so one spike does not flood alerts

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <stdio.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float baseline;
    float noise;
    float alpha_baseline;   // low-pass for expected magnitude
    float alpha_noise;      // low-pass for residual magnitude
    float threshold_k;      // anomaly threshold multiplier
    uint32_t cooldown;      // samples to suppress repeated alerts
    uint32_t cooldown_left;
    bool initialized;
} AnomalyDetector;

typedef struct {
    float magnitude;
    float residual;
    float score;
    bool anomaly;
} DetectorResult;

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

void anomaly_detector_init(
    AnomalyDetector *det,
    float alpha_baseline,
    float alpha_noise,
    float threshold_k,
    uint32_t cooldown)
{
    det->baseline = 0.0f;
    det->noise = 0.01f;
    det->alpha_baseline = alpha_baseline;
    det->alpha_noise = alpha_noise;
    det->threshold_k = threshold_k;
    det->cooldown = cooldown;
    det->cooldown_left = 0;
    det->initialized = false;
}

DetectorResult anomaly_detector_process(AnomalyDetector *det, AccelSample sample) {
    DetectorResult result = {0};

    float mag = accel_magnitude(sample);
    result.magnitude = mag;

    if (!det->initialized) {
        det->baseline = mag;
        det->noise = 0.01f;
        det->initialized = true;
        result.residual = 0.0f;
        result.score = 0.0f;
        result.anomaly = false;
        return result;
    }

    // Residual relative to slowly changing baseline
    float residual = fabsf(mag - det->baseline);
    result.residual = residual;

    // Update baseline slowly
    det->baseline = (1.0f - det->alpha_baseline) * det->baseline
                  + det->alpha_baseline * mag;

    // Update noise estimate from residuals
    det->noise = (1.0f - det->alpha_noise) * det->noise
               + det->alpha_noise * residual;

    float threshold = det->threshold_k * (det->noise + 1e-6f);
    result.score = residual / (det->noise + 1e-6f);

    bool raw_anomaly = residual > threshold;

    if (det->cooldown_left > 0) {
        det->cooldown_left--;
        result.anomaly = false;
    } else if (raw_anomaly) {
        result.anomaly = true;
        det->cooldown_left = det->cooldown;
    } else {
        result.anomaly = false;
    }

    return result;
}

// Example hook for embedded alerting/logging
static void handle_anomaly(const DetectorResult *r) {
    printf("ANOMALY: mag=%.3f residual=%.3f score=%.3f\n",
           r->magnitude, r->residual, r->score);
}

int main(void) {
    AnomalyDetector detector;
    anomaly_detector_init(&detector,
                          0.01f,  // baseline adapts slowly
                          0.05f,  // noise adapts moderately
                          6.0f,   // threshold multiplier
                          10);    // cooldown samples

    // Simulated accelerometer stream
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.98f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.03f, 0.99f},
        {0.02f, 0.02f, 3.50f}, // anomaly spike
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.02f, 0.97f},
        {0.01f, 0.01f, 1.02f}
    };

    size_t n = sizeof(stream) / sizeof(stream[0]);
    for (size_t i = 0; i < n; i++) {
        DetectorResult r = anomaly_detector_process(&detector, stream[i]);
        printf("sample %zu: mag=%.3f residual=%.3f score=%.3f anomaly=%d\n",
               i, r.magnitude, r.residual, r.score, r.anomaly ? 1 : 0);

        if (r.anomaly) {
            handle_anomaly(&r);
        }
    }

    return 0;
}
```

