```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE 64
#define ALPHA 0.2f
#define ANOMALY_Z_THRESHOLD 3.5f
#define EPSILON 1e-6f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;

    float mag_buffer[WINDOW_SIZE];
    uint32_t index;
    uint32_t count;

    float sum;
    float sum_sq;
} AnomalyPipeline;

typedef struct {
    float magnitude;
    float mean;
    float stddev;
    float zscore;
    bool anomaly;
} AnomalyResult;

static void pipeline_init(AnomalyPipeline *p) {
    p->filtered_x = 0.0f;
    p->filtered_y = 0.0f;
    p->filtered_z = 0.0f;
    p->index = 0;
    p->count = 0;
    p->sum = 0.0f;
    p->sum_sq = 0.0f;

    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        p->mag_buffer[i] = 0.0f;
    }
}

static float low_pass(float prev, float input) {
    return ALPHA * input + (1.0f - ALPHA) * prev;
}

static float accel_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static AnomalyResult pipeline_process(AnomalyPipeline *p, AccelSample s) {
    AnomalyResult result = {0};

    p->filtered_x = low_pass(p->filtered_x, s.x);
    p->filtered_y = low_pass(p->filtered_y, s.y);
    p->filtered_z = low_pass(p->filtered_z, s.z);

    float mag = accel_magnitude(p->filtered_x, p->filtered_y, p->filtered_z);
    result.magnitude = mag;

    if (p->count == WINDOW_SIZE) {
        float old = p->mag_buffer[p->index];
        p->sum -= old;
        p->sum_sq -= old * old;
    } else {
        p->count++;
    }

    p->mag_buffer[p->index] = mag;
    p->sum += mag;
    p->sum_sq += mag * mag;
    p->index = (p->index + 1) % WINDOW_SIZE;

    result.mean = p->sum / (float)p->count;
    float variance = (p->sum_sq / (float)p->count) - (result.mean * result.mean);
    if (variance < 0.0f) variance = 0.0f;

    result.stddev = sqrtf(variance);
    result.zscore = (mag - result.mean) / (result.stddev + EPSILON);
    result.anomaly = (p->count >= 8) && (result.zscore > ANOMALY_Z_THRESHOLD);

    return result;
}
