```c
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <math.h>

/*
 * Simple embedded accelerometer anomaly detection pipeline
 *
 * Pipeline:
 *   1. Read x,y,z accelerometer sample
 *   2. Compute magnitude
 *   3. Estimate slow-moving baseline with EMA
 *   4. Compute residual = magnitude - baseline
 *   5. Estimate rolling residual energy/variance with EMA
 *   6. Raise anomaly if residual exceeds dynamic threshold
 *
 * Notes:
 * - This is a lightweight starting point suitable for MCUs.
 * - In production, consider fixed-point math if FPU is unavailable.
 * - Tune alpha/beta/threshold for your sensor, sample rate, and noise profile.
 */

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float baseline_mag;     // Low-pass estimate of "normal" magnitude
    float residual_mean;    // Optional EMA of residual mean
    float residual_var;     // EMA estimate of residual variance
    float alpha_baseline;   // EMA coefficient for baseline
    float alpha_mean;       // EMA coefficient for residual mean
    float alpha_var;        // EMA coefficient for residual variance
    float threshold_k;      // Number of stddevs for anomaly
    float min_stddev;       // Prevent divide-by-zero / too-tight thresholds
    bool initialized;
} anomaly_detector_t;

typedef struct {
    float magnitude;
    float baseline;
    float residual;
    float residual_stddev;
    float score;       // normalized anomaly score
    bool anomaly;
} anomaly_result_t;

/* Optional clamp helper */
static float clampf(float v, float lo, float hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static void anomaly_detector_init(anomaly_detector_t *det) {
    if (!det) return;

    det->baseline_mag   = 0.0f;
    det->residual_mean  = 0.0f;
    det->residual_var   = 0.0f;

    /*
     * Example tuning:
     * - alpha_baseline: low-pass speed for normal background magnitude
     * - alpha_mean: drift tracking of residual mean
     * - alpha_var: variance adaptation speed
     */
    det->alpha_baseline = 0.01f;
    det->alpha_mean     = 0.02f;
    det->alpha_var      = 0.02f;

    /*
     * threshold_k:
     *   anomaly if |residual - residual_mean| / stddev > threshold_k
     */
    det->threshold_k    = 4.0f;
    det->min_stddev     = 0.02f;
    det->initialized    = false;
}

static float accel_magnitude(const accel_sample_t *s) {
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static anomaly_result_t anomaly_detector_update(anomaly_detector_t *det,
                                                const accel_sample_t *sample) {
    anomaly_result_t out = {0};

    if (!det || !sample) {
        return out;
    }

    const float mag = accel_magnitude(sample);
    out.magnitude = mag;

    if (!det->initialized) {
        det->baseline_mag = mag;
        det->residual_mean = 0.0f;
        det->residual_var = 0.0f;
        det->initialized = true;

        out.baseline = det->baseline_mag;
        out.residual = 0.0f;
        out.residual_stddev = det->min_stddev;
        out.score = 0.0f;
        out.anomaly = false;
        return out;
    }

    /* Step 1: update baseline magnitude */
    det->baseline_mag =
        (1.0f - det->alpha_baseline) * det->baseline_mag +
        det->alpha_baseline * mag;

    /* Step 2: compute residual from baseline */
    const float residual = mag - det->baseline_mag;

    /* Step 3: track residual mean */
    det->residual_mean =
        (1.0f - det->alpha_mean) * det->residual_mean +
        det->alpha_mean * residual;

    /* Step 4: track residual variance using EMA */
    const float centered = residual - det->residual_mean;
    const float inst_var = centered * centered;

    det->residual_var =
        (1.0f - det->alpha_var) * det->residual_var +
        det->alpha_var * inst_var;

    const float stddev = fmaxf(sqrtf(det->residual_var), det->min_stddev);
    const float score = fabsf(centered) / stddev;

    out.baseline = det->baseline_mag;
    out.residual = residual;
    out.residual_stddev = stddev;
    out.score = score;
    out.anomaly = (score > det->threshold_k);

    return out;
}

/*
 * Replace this with your actual hardware sensor read function.
 * For now this is just a tiny synthetic test source.
 */
