## Initial C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 *
 * Assumptions:
 * - samples arrive at fixed rate, e.g. 100 Hz
 * - accelerometer values are already converted to g or mg units
 * - no dynamic memory
 */

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Baseline estimate (gravity / slow drift)
    float bx;
    float by;
    float bz;

    // EMA coefficient for baseline tracking
    float baseline_alpha;

    // Rolling statistics using Welford-style online updates
    float mean;
    float m2;
    uint32_t count;

    // Detection threshold
    float z_threshold;

    // Require anomaly persistence
    uint32_t consecutive_limit;
    uint32_t consecutive_count;

    // Warmup period before detection
    uint32_t warmup_samples;

    // Last computed values for inspection/debug
    float last_motion_x;
    float last_motion_y;
    float last_motion_z;
    float last_magnitude;
    float last_zscore;

    bool anomaly;
} AnomalyDetector;

/*
 * Initialize detector
 *
 * baseline_alpha:
 *   smaller = slower baseline adaptation
 *   e.g. 0.01 for slow gravity/drift tracking
 *
 * z_threshold:
 *   common starting point: 3.0 to 5.0
 *
 * consecutive_limit:
 *   e.g. 3 samples in a row
 *
 * warmup_samples:
 *   e.g. first 50-100 samples ignored for stable statistics
 */
void anomaly_detector_init(AnomalyDetector *det,
                           float baseline_alpha,
                           float z_threshold,
                           uint32_t consecutive_limit,
                           uint32_t warmup_samples)
{
    det->bx = 0.0f;
    det->by = 0.0f;
    det->bz = 0.0f;

    det->baseline_alpha = baseline_alpha;

    det->mean = 0.0f;
    det->m2 = 0.0f;
    det->count = 0;

    det->z_threshold = z_threshold;
    det->consecutive_limit = consecutive_limit;
    det->consecutive_count = 0;
    det->warmup_samples = warmup_samples;

    det->last_motion_x = 0.0f;
    det->last_motion_y = 0.0f;
    det->last_motion_z = 0.0f;
    det->last_magnitude = 0.0f;
    det->last_zscore = 0.0f;

    det->anomaly = false;
}

/*
 * Fast absolute value helper
 */
static inline float f_abs(float x)
{
    return (x < 0.0f) ? -x : x;
}

/*
 * Lightweight magnitude approximation:
 * |x| + |y| + |z|
 *
 * For many anomaly applications this is enough and cheaper than sqrt.
 * If preferred, replace with sqrtf(x*x + y*y + z*z).
 */
static inline float motion_magnitude_approx(float x, float y, float z)
{
    return f_abs(x) + f_abs(y) + f_abs(z);
}

/*
 * Update rolling statistics using Welford's algorithm
 */
static void update_stats(AnomalyDetector *det, float value)
{
    det->count++;
    float delta = value - det->mean;
    det->mean += delta / (float)det->count;
    float delta2 = value - det->mean;
    det->m2 += delta * delta2;
}

/*
 * Variance estimate
 */
static float get_variance(const AnomalyDetector *det)
{
    if (det->count < 2) {
        return 0.0f;
    }
    return det->m2 / (float)(det->count - 1);
}

/*
 * Standard deviation estimate
 */
static float get_stddev(const AnomalyDetector *det)
{
    float var = get_variance(det);
    if (var <= 0.0f) {
        return 0.0f;
    }
    return sqrtf(var);
}

/*
 * Process one accelerometer sample.
 *
 * Returns true if anomaly is detected on this update.
 */
bool anomaly_detector_process(AnomalyDetector *det, AccelSample s)
{
    // 1. Update slow baseline estimate
    det->bx += det->baseline_alpha * (s.x - det->bx);
    det->by += det->baseline_alpha * (s.y - det->by);
    det->bz += det->baseline_alpha * (s.z - det->bz);

    // 2. Remove baseline (high-pass behavior)
    float mx = s.x - det->bx;
    float my = s.y - det->by;
    float mz = s.z - det->bz;

    det->last_motion_x = mx;
    det->last_motion_y = my;
    det->last_motion_z = mz;

    // 3. Compute motion magnitude
    float mag = motion_magnitude_approx(mx, my, mz);
    det->last_magnitude = mag;

    // 4. Update rolling stats
    update_stats(det, mag);

    // Not enough data yet
    if (det->count <= det->warmup_samples || det->count < 2) {
        det->last_zscore = 0.0f;
        det->consecutive_count = 0;
        det->anomaly = false;
        return false;
    }

    // 5. Compute z-score
    float stddev = get_stddev(det);

    // Guard against divide-by-near-zero
    if (stddev < 1e-6f) {
        det->last_zscore = 0.0f;
        det->consecutive_count = 0;
        det->anomaly = false;
        return false;
    }

    float z = (mag - det->mean) / stddev;
    det->last_zscore = z;

    // 6. Persistence logic
    if (z > det->z_threshold) {
        det->consecutive_count++;
    } else {
        det->consecutive_count = 0;
    }

    if (det->consecutive_count >= det->consecutive_limit) {
        det->anomaly = true;
        return true;
    }

    det->anomaly = false;
    return false;
}
