## Improved version with rolling window
Here is a better embedded version using a fixed-size ring buffer so statistics adapt over time.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define DETECTOR_WINDOW 64

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float bx, by, bz;
    float baseline_alpha;

    float window[DETECTOR_WINDOW];
    uint32_t index;
    uint32_t size;

    float sum;
    float sumsq;

    float z_threshold;
    uint32_t consecutive_limit;
    uint32_t consecutive_count;
    uint32_t warmup_samples;
    uint32_t total_samples;

    uint32_t cooldown_samples;
    uint32_t cooldown_remaining;

    float last_magnitude;
    float last_zscore;
    bool anomaly;
} RollingAnomalyDetector;

void rolling_detector_init(RollingAnomalyDetector *det,
                           float baseline_alpha,
                           float z_threshold,
                           uint32_t consecutive_limit,
                           uint32_t warmup_samples,
                           uint32_t cooldown_samples)
{
    det->bx = det->by = det->bz = 0.0f;
    det->baseline_alpha = baseline_alpha;

    for (uint32_t i = 0; i < DETECTOR_WINDOW; i++) {
        det->window[i] = 0.0f;
    }

    det->index = 0;
    det->size = 0;
    det->sum = 0.0f;
    det->sumsq = 0.0f;

    det->z_threshold = z_threshold;
    det->consecutive_limit = consecutive_limit;
    det->consecutive_count = 0;
    det->warmup_samples = warmup_samples;
    det->total_samples = 0;

    det->cooldown_samples = cooldown_samples;
    det->cooldown_remaining = 0;

    det->last_magnitude = 0.0f;
    det->last_zscore = 0.0f;
    det->anomaly = false;
}

static inline float absf_local(float x)
{
    return x < 0.0f ? -x : x;
}

static inline float mag3(float x, float y, float z)
{
    return absf_local(x) + absf_local(y) + absf_local(z);
}

static void rolling_push(RollingAnomalyDetector *det, float v)
{
    if (det->size < DETECTOR_WINDOW) {
        det->window[det->index] = v;
        det->sum += v;
        det->sumsq += v * v;
        det->size++;
    } else {
        float old = det->window[det->index];
        det->window[det->index] = v;
        det->sum += v - old;
        det->sumsq += v * v - old * old;
    }

    det->index = (det->index + 1) % DETECTOR_WINDOW;
}

static float rolling_mean(const RollingAnomalyDetector *det)
{
    if (det->size == 0) return 0.0f;
    return det->sum / (float)det->size;
}

static float rolling_stddev(const RollingAnomalyDetector *det)
{
    if (det->size < 2) return 0.0f;

    float n = (float)det->size;
    float mean = det->sum / n;
    float var = (det->sumsq / n) - (mean * mean);

    if (var < 0.0f) var = 0.0f;
    return sqrtf(var);
}

bool rolling_detector_process(RollingAnomalyDetector *det, AccelSample s)
{
    det->total_samples++;

    det->bx += det->baseline_alpha * (s.x - det->bx);
    det->by += det->baseline_alpha * (s.y - det->by);
    det->bz += det->baseline_alpha * (s.z - det->bz);

    float mx = s.x - det->bx;
    float my = s.y - det->by;
    float mz = s.z - det->bz;

    float mag = mag3(mx, my, mz);
    det->last_magnitude = mag;

    rolling_push(det, mag);

    if (det->total_samples <= det->warmup_samples || det->size < 8) {
        det->last_zscore = 0.0f;
        det->anomaly = false;
        return false;
    }

    float mean = rolling_mean(det);
    float stddev = rolling_stddev(det);

    if (stddev < 1e-6f) {
        det->last_zscore = 0.0f;
        det->anomaly = false;
        return false;
    }

    float z = (mag - mean) / stddev;
    det->last_zscore = z;

    if (det->cooldown_remaining > 0) {
        det->cooldown_remaining--;
        det->consecutive_count = 0;
        det->anomaly = false;
        return false;
    }

    if (z > det->z_threshold) {
        det->consecutive_count++;
    } else {
        det->consecutive_count = 0;
    }

    if (det->consecutive_count >= det->consecutive_limit) {
        det->anomaly = true;
        det->cooldown_remaining = det->cooldown_samples;
        det->consecutive_count = 0;
        return true;
    }

    det->anomaly = false;
    return false;
}
```

