```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <stdio.h>

#define SAMPLE_RATE_HZ              100.0f
#define HP_ALPHA                    0.98f
#define BASELINE_ALPHA              0.01f
#define DEVIATION_ALPHA             0.01f

#define ANOMALY_Z_THRESHOLD         4.0f
#define ANOMALY_MIN_ABS_MAG         0.15f
#define ANOMALY_COOLDOWN_SAMPLES    20

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float gravity_x;
    float gravity_y;
    float gravity_z;

    float baseline_mag;
    float baseline_dev;

    uint32_t sample_count;
    int cooldown;

    bool initialized;
} AnomalyDetector;

typedef struct {
    float raw_mag;
    float hp_x;
    float hp_y;
    float hp_z;
    float hp_mag;
    float score;
    bool anomaly;
} DetectionResult;

static float fast_abs(float v) {
    return v < 0.0f ? -v : v;
}

static float vec_mag(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

void anomaly_detector_init(AnomalyDetector *det) {
    det->gravity_x = 0.0f;
    det->gravity_y = 0.0f;
    det->gravity_z = 0.0f;
    det->baseline_mag = 0.0f;
    det->baseline_dev = 0.01f;
    det->sample_count = 0;
    det->cooldown = 0;
    det->initialized = false;
}

DetectionResult anomaly_detector_process(AnomalyDetector *det, AccelSample s) {
    DetectionResult out = {0};

    out.raw_mag = vec_mag(s.x, s.y, s.z);

    if (!det->initialized) {
        det->gravity_x = s.x;
        det->gravity_y = s.y;
        det->gravity_z = s.z;
        det->baseline_mag = 0.0f;
        det->baseline_dev = 0.01f;
        det->initialized = true;
    }

    det->gravity_x = HP_ALPHA * det->gravity_x + (1.0f - HP_ALPHA) * s.x;
    det->gravity_y = HP_ALPHA * det->gravity_y + (1.0f - HP_ALPHA) * s.y;
    det->gravity_z = HP_ALPHA * det->gravity_z + (1.0f - HP_ALPHA) * s.z;

    out.hp_x = s.x - det->gravity_x;
    out.hp_y = s.y - det->gravity_y;
    out.hp_z = s.z - det->gravity_z;

    out.hp_mag = vec_mag(out.hp_x, out.hp_y, out.hp_z);

    det->baseline_mag =
        (1.0f - BASELINE_ALPHA) * det->baseline_mag +
        BASELINE_ALPHA * out.hp_mag;

    float abs_dev = fast_abs(out.hp_mag - det->baseline_mag);
    det->baseline_dev =
        (1.0f - DEVIATION_ALPHA) * det->baseline_dev +
        DEVIATION_ALPHA * abs_dev;

    if (det->baseline_dev < 0.001f) {
        det->baseline_dev = 0.001f;
    }

    out.score = abs_dev / det->baseline_dev;

    bool threshold_hit =
        (out.score >= ANOMALY_Z_THRESHOLD) &&
        (out.hp_mag >= ANOMALY_MIN_ABS_MAG);

    if (det->cooldown > 0) {
        det->cooldown--;
        out.anomaly = false;
    } else if (threshold_hit) {
        out.anomaly = true;
        det->cooldown = ANOMALY_COOLDOWN_SAMPLES;
    } else {
        out.anomaly = false;
    }

    det->sample_count++;
    return out;
}

/* Example platform hook */
void handle_anomaly(const DetectionResult *r) {
    printf("ANOMALY: hp_mag=%.3f score=%.3f\n", r->hp_mag, r->score);
}

/* Example main loop */
int main(void) {
    AnomalyDetector detector;
    anomaly_detector_init(&detector);

    AccelSample test_data[] = {
        {0.01f, 0.00f, 0.98f},
        {0.02f, 0.01f, 1.00f},
        {0.01f, 0.00f, 0.99f},
        {0.03f, 0.01f, 1.01f},
        {0.80f, 0.70f, 1.60f},
        {0.02f, 0.00f, 1.00f},
        {0.01f, 0.01f, 0.99f},
    };

    size_t n = sizeof(test_data) / sizeof(test_data[0]);
    for (size_t i = 0; i < n; i++) {
        DetectionResult r = anomaly_detector_process(&detector, test_data[i]);

        printf("sample=%zu raw=%.3f hp=%.3f score=%.3f anomaly=%d\n",
               i, r.raw_mag, r.hp_mag, r.score, r.anomaly ? 1 : 0);

        if (r.anomaly) {
            handle_anomaly(&r);
        }
    }

    return 0;
}
