Below is a compact, practical starting point in <language>C</language>, since that’s the top recommendation for embedded sensor processing.

It implements:
- accelerometer sample ingestion,
- magnitude approximation,
- low-pass baseline tracking,
- residual-based anomaly score,
- adaptive noise estimate,
- threshold detection with cooldown,
- fixed-size ring buffer,
- no dynamic allocation.

## High-level design

Pipeline:
1. Read raw accelerometer `(x, y, z)`
2. Compute motion signal magnitude
3. Smooth into a baseline
4. Compute deviation from baseline
5. Track typical deviation level
6. Flag anomaly if deviation exceeds threshold for enough samples

This is suitable as a first-pass detector for:
- impacts,
- vibrations,
- sudden movement changes,
- mechanical faults.

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>

#define ACCEL_RING_SIZE             64
#define ANOMALY_COOLDOWN_SAMPLES    20
#define ANOMALY_CONFIRM_SAMPLES     3

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_sample_t;

typedef struct {
    accel_sample_t buffer[ACCEL_RING_SIZE];
    uint16_t head;
    uint16_t count;

    // Signal tracking
    float baseline_mag;
    float noise_est;
    float last_score;

    // Detection state
    uint16_t cooldown;
    uint8_t consecutive_hits;
    bool initialized;
} anomaly_detector_t;

typedef struct {
    bool anomaly;
    float magnitude;
    float residual;
    float score;
} detector_result_t;

/*
 * Fast absolute value for float
 */
static float f_abs(float v) {
    return (v < 0.0f) ? -v : v;
}

/*
 * Approximate magnitude without sqrt:
 * |x| + |y| + |z|
 *
 * For many anomaly tasks this is sufficient and cheaper than sqrt(x^2+y^2+z^2).
 */
static float accel_magnitude_l1(const accel_sample_t *s) {
    return (float)((s->x < 0 ? -s->x : s->x) +
                   (s->y < 0 ? -s->y : s->y) +
                   (s->z < 0 ? -s->z : s->z));
}

void anomaly_detector_init(anomaly_detector_t *det) {
    det->head = 0;
    det->count = 0;
    det->baseline_mag = 0.0f;
    det->noise_est = 1.0f;     // avoid divide-by-zero
    det->last_score = 0.0f;
    det->cooldown = 0;
    det->consecutive_hits = 0;
    det->initialized = false;
}

/*
 * Tunable parameters:
 *
 * baseline_alpha:
 *   Lower = slower baseline adaptation
 *   Higher = faster reaction to normal changes
 *
 * noise_alpha:
 *   Lower = more stable noise estimate
 *   Higher = more responsive threshold adaptation
 *
 * threshold_sigma:
 *   Number of "noise units" required to count as anomalous
 */
detector_result_t anomaly_detector_process(
    anomaly_detector_t *det,
    accel_sample_t sample,
    float baseline_alpha,
    float noise_alpha,
    float threshold_sigma)
{
    detector_result_t result = {0};

    // Store sample in ring buffer
    det->buffer[det->head] = sample;
    det->head = (det->head + 1) % ACCEL_RING_SIZE;
    if (det->count < ACCEL_RING_SIZE) {
        det->count++;
    }

    float mag = accel_magnitude_l1(&sample);

    if (!det->initialized) {
        det->baseline_mag = mag;
        det->noise_est = 1.0f;
        det->last_score = 0.0f;
        det->initialized = true;

        result.magnitude = mag;
        result.residual = 0.0f;
        result.score = 0.0f;
        result.anomaly = false;
        return result;
    }

    // Low-pass baseline estimate
    det->baseline_mag =
        (1.0f - baseline_alpha) * det->baseline_mag +
        baseline_alpha * mag;

    // Residual from baseline
    float residual = f_abs(mag - det->baseline_mag);

    // Adaptive noise estimate from residual
    det->noise_est =
        (1.0f - noise_alpha) * det->noise_est +
        noise_alpha * residual;

    if (det->noise_est < 1.0f) {
        det->noise_est = 1.0f;
    }

    // Score = residual normalized by expected noise
    float score = residual / det->noise_est;
    det->last_score = score;

    // Cooldown handling
    if (det->cooldown > 0) {
        det->cooldown--;
    }

    bool hit = (score > threshold_sigma);

    if (hit && det->cooldown == 0) {
        if (det->consecutive_hits < 255) {
            det->consecutive_hits++;
        }
    } else {
        det->consecutive_hits = 0;
    }

    bool anomaly = false;
    if (det->consecutive_hits >= ANOMALY_CONFIRM_SAMPLES) {
        anomaly = true;
        det->cooldown = ANOMALY_COOLDOWN_SAMPLES;
        det->consecutive_hits = 0;
    }

    result.magnitude = mag;
    result.residual = residual;
    result.score = score;
    result.anomaly = anomaly;

    return result;
}
```

