Below is a practical **initial embedded implementation** in <language>C</language>, since it’s usually the best first choice for MCU-based accelerometer pipelines.

It includes a simple real-time pipeline:

1. Read accelerometer samples `(x, y, z)`
2. Remove gravity/baseline with a low-pass estimate
3. Compute motion magnitude
4. Smooth with a moving average
5. Track running mean and variance
6. Flag anomaly when signal deviates beyond a threshold

This is designed as a **small, portable starting point** for microcontrollers.

---

## <language>C</language> initial implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 *
 * Pipeline:
 *   raw xyz
 *   -> low-pass baseline estimate
 *   -> high-pass residual
 *   -> residual magnitude
 *   -> moving average smoothing
 *   -> online mean/variance
 *   -> z-score threshold anomaly detection
 *
 * Notes:
 * - Uses float for simplicity. On very small MCUs, fixed-point may be better.
 * - Assumes samples arrive at a roughly constant rate.
 * - Intended as a starting point, not production-hardened code.
 */

#ifndef ABSF
#define ABSF(x) ((x) < 0.0f ? -(x) : (x))
#endif

#define MA_WINDOW              8
#define MIN_SAMPLES_FOR_ALERT  32
#define DEFAULT_Z_THRESHOLD    3.5f
#define DEFAULT_EPSILON        1e-6f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    bool anomaly;
    float raw_magnitude;
    float filtered_magnitude;
    float mean;
    float stddev;
    float zscore;
} detector_result_t;

typedef struct {
    /* Low-pass baseline estimate for each axis */
    float baseline_x;
    float baseline_y;
    float baseline_z;

    /* Smoothing buffer */
    float ma_buffer[MA_WINDOW];
    uint32_t ma_index;
    uint32_t ma_count;
    float ma_sum;

    /* Online stats over filtered magnitude */
    uint32_t sample_count;
    float mean;
    float m2;

    /* Config */
    float baseline_alpha;   /* e.g. 0.01 to 0.1 */
    float z_threshold;
} anomaly_detector_t;

static void anomaly_detector_init(anomaly_detector_t *det,
                                  float baseline_alpha,
                                  float z_threshold)
{
    uint32_t i;
    det->baseline_x = 0.0f;
    det->baseline_y = 0.0f;
    det->baseline_z = 0.0f;

    for (i = 0; i < MA_WINDOW; i++) {
        det->ma_buffer[i] = 0.0f;
    }

    det->ma_index = 0;
    det->ma_count = 0;
    det->ma_sum = 0.0f;

    det->sample_count = 0;
    det->mean = 0.0f;
    det->m2 = 0.0f;

    det->baseline_alpha = baseline_alpha;
    det->z_threshold = z_threshold;
}

static float fast_magnitude3(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static float moving_average_update(anomaly_detector_t *det, float value)
{
    if (det->ma_count < MA_WINDOW) {
        det->ma_buffer[det->ma_index] = value;
        det->ma_sum += value;
        det->ma_count++;
    } else {
        det->ma_sum -= det->ma_buffer[det->ma_index];
        det->ma_buffer[det->ma_index] = value;
        det->ma_sum += value;
    }

    det->ma_index = (det->ma_index + 1U) % MA_WINDOW;
    return det->ma_sum / (float)det->ma_count;
}

static void online_stats_update(anomaly_detector_t *det, float x)
{
    det->sample_count++;
    float delta = x - det->mean;
    det->mean += delta / (float)det->sample_count;
    float delta2 = x - det->mean;
    det->m2 += delta * delta2;
}

static float online_stats_variance(const anomaly_detector_t *det)
{
    if (det->sample_count < 2) {
        return 0.0f;
    }
    return det->m2 / (float)(det->sample_count - 1U);
}

static detector_result_t anomaly_detector_process(anomaly_detector_t *det,
                                                  accel_sample_t s)
{
    detector_result_t result;
    float ax_hp, ay_hp, az_hp;
    float raw_mag, hp_mag, smooth_mag;
    float variance, stddev, zscore;
    float a = det->baseline_alpha;

    /* Update low-pass baseline estimate */
    det->baseline_x = (1.0f - a) * det->baseline_x + a * s.x;
    det->baseline_y = (1.0f - a) * det->baseline_y + a * s.y;
    det->baseline_z = (1.0f - a) * det->baseline_z + a * s.z;

    /* High-pass residual (remove slowly changing baseline/gravity component) */
    ax_hp = s.x - det->baseline_x;
    ay_hp = s.y - det->baseline_y;
    az_hp = s.z - det->baseline_z;

    /* Signal features */
    raw_mag = fast_magnitude3(s.x, s.y, s.z);
    hp_mag = fast_magnitude3(ax_hp, ay_hp, az_hp);
    smooth_mag = moving_average_update(det, hp_mag);

    /* Compute anomaly against pre-update statistics */
    variance = online_stats_variance(det);
    stddev = sqrtf(variance + DEFAULT_EPSILON);

    if (det->sample_count >= MIN_SAMPLES_FOR_ALERT) {
        zscore = ABSF((smooth_mag - det->mean) / stddev);
        result.anomaly = (zscore >= det->z_threshold);
    } else {
        zscore = 0.0f;
        result.anomaly = false;
    }

    /* Update statistics after evaluation */
    online_stats_update(det, smooth_mag);

    result.raw_magnitude = raw_mag;
    result.filtered_magnitude = smooth_mag;
    result.mean = det->mean;
    result.stddev = stddev;
    result.zscore = zscore;

    return result;
}
```

