Below is a minimal working embedded-style pipeline in <language>C</language> that:

- ingests 3-axis accelerometer samples
- computes acceleration magnitude
- applies simple smoothing
- estimates a baseline
- flags anomalies when deviation exceeds a threshold

It is written to be portable and easy to move onto a microcontroller.

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float alpha_smooth;     // smoothing factor for signal
    float alpha_baseline;   // smoothing factor for baseline
    float threshold;        // anomaly threshold
    bool initialized;
    float smoothed_mag;
    float baseline_mag;
} AnomalyDetector;

// Compute vector magnitude
static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// Initialize detector
static void detector_init(AnomalyDetector *d,
                          float alpha_smooth,
                          float alpha_baseline,
                          float threshold) {
    d->alpha_smooth = alpha_smooth;
    d->alpha_baseline = alpha_baseline;
    d->threshold = threshold;
    d->initialized = false;
    d->smoothed_mag = 0.0f;
    d->baseline_mag = 0.0f;
}

// Process one sample, return true if anomaly detected
static bool detector_process(AnomalyDetector *d, AccelSample s, float *score_out) {
    float mag = accel_magnitude(s);

    if (!d->initialized) {
        d->smoothed_mag = mag;
        d->baseline_mag = mag;
        d->initialized = true;
    } else {
        d->smoothed_mag =
            d->alpha_smooth * mag +
            (1.0f - d->alpha_smooth) * d->smoothed_mag;

        d->baseline_mag =
            d->alpha_baseline * d->smoothed_mag +
            (1.0f - d->alpha_baseline) * d->baseline_mag;
    }

    float score = fabsf(d->smoothed_mag - d->baseline_mag);
    if (score_out) {
        *score_out = score;
    }

    return score > d->threshold;
}

int main(void) {
    AnomalyDetector detector;
    detector_init(&detector, 0.2f, 0.01f, 2.0f);

    // Example accelerometer stream
    AccelSample samples[] = {
        {0.0f, 0.0f, 1.0f},
        {0.1f, 0.0f, 0.98f},
        {0.05f, 0.02f, 1.01f},
        {0.0f, -0.1f, 1.02f},
        {3.5f, 2.0f, 0.5f},   // anomaly
        {0.0f, 0.0f, 1.0f},
        {0.02f, 0.01f, 0.99f}
    };

    int count = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < count; i++) {
        float score;
        bool anomaly = detector_process(&detector, samples[i], &score);

        printf("sample %d: mag=%.3f score=%.3f %s\n",
               i,
               accel_magnitude(samples[i]),
               score,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
```

How it works:
1. Magnitude converts x/y/z into one scalar.
2. Smoothing reduces sample noise.
3. Baseline tracks normal behavior slowly.
4. Score is the absolute difference between current smoothed signal and baseline.
5. If score exceeds the threshold, it reports an anomaly.

