Below is a minimal working example in <language>C</language>, since it’s the top recommendation for embedded sensor pipelines.

It simulates an accelerometer stream, computes acceleration magnitude, applies a simple moving average baseline, and flags anomalies when the current sample deviates too far from that baseline.

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 8
#define THRESHOLD 3.0f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} MovingAverage;

void ma_init(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0.0f;
    }
}

float ma_update(MovingAverage *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->buffer[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
        ma->buffer[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    return ma->sum / ma->count;
}

float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

bool detect_anomaly(float current, float baseline) {
    return fabsf(current - baseline) > THRESHOLD;
}

int main(void) {
    AccelSample samples[] = {
        {0.0f, 0.1f, 1.0f},
