Below is a minimal working embedded-style pipeline in <language>C</language> that:

- reads accelerometer samples
- removes gravity / DC bias with a simple low-pass filter
- computes motion magnitude
- maintains a rolling baseline
- flags anomalies when motion exceeds a threshold

This is suitable as a starting point for microcontrollers and can be adapted to real sensor drivers.

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float lp_x;
    float lp_y;
    float lp_z;
    float baseline;
    bool initialized;
} PipelineState;

typedef struct {
    float hp_x;
    float hp_y;
    float hp_z;
    float magnitude;
    float score;
    bool anomaly;
} PipelineOutput;

/* Tunable parameters */
#define LP_ALPHA            0.90f   /* low-pass for gravity/DC estimate */
#define BASELINE_ALPHA      0.95f   /* rolling average of normal motion */
#define ANOMALY_MULTIPLIER  3.0f    /* detection threshold */

/* Simulated accelerometer input */
static AccelSample test_data[] = {
    {0.01f, 0.02f, 0.98f},
    {0.02f, 0.01f, 1.01f},
    {0.00f, 0.03f, 0.99f},
    {0.01f,-0.01f, 1.00f},
    {0.03f, 0.02f, 0.97f},
    {1.20f, 1.10f, 2.50f}, /* anomaly */
    {0.02f, 0.01f, 1.00f},
    {0.01f, 0.00f, 0.99f},
};

static void pipeline_init(PipelineState *s) {
    s->lp_x = 0.0f;
    s->lp_y = 0.0f;
    s->lp_z = 0.0f;
    s->baseline = 0.0f;
    s->initialized = false;
}

static PipelineOutput pipeline_process(PipelineState *s, AccelSample in) {
    PipelineOutput out = {0};

    if (!s->initialized) {
        s->lp_x = in.x;
        s->lp_y = in.y;
        s->lp_z = in.z;
        s->baseline = 0.01f;
        s->initialized = true;
    }

    /* Low-pass estimate of gravity / bias */
    s->lp_x = LP_ALPHA * s->lp_x + (1.0f - LP_ALPHA) * in.x;
    s->lp_y = LP_ALPHA * s->lp_y + (1.0f - LP_ALPHA) * in.y;
    s->lp_z = LP_ALPHA * s->lp_z + (1.0f - LP_ALPHA) * in.z;

    /* High-pass motion component */
    out.hp_x = in.x - s->lp_x;
    out.hp_y = in.y - s->lp_y;
    out.hp_z = in.z - s->lp_z;

    /* Magnitude of motion */
    out.magnitude = sqrtf(out.hp_x * out.hp_x +
                          out.hp_y * out.hp_y +
                          out.hp_z * out.hp_z);

    /* Rolling baseline */
    s->baseline = BASELINE_ALPHA * s->baseline +
                  (1.0f - BASELINE_ALPHA) * out.magnitude;

    if (s->baseline < 0.001f) {
        s->baseline = 0.001f;
    }

    out.score = out.magnitude / s->baseline;
    out.anomaly = (out.score > ANOMALY_MULTIPLIER);

    return out;
}

int main(void) {
    PipelineState state;
    pipeline_init(&state);

    int count = sizeof(test_data) / sizeof(test_data[0]);

    for (int i = 0; i < count; i++) {
        PipelineOutput out = pipeline_process(&state, test_data[i]);

        printf("sample=%d raw=(%.2f, %.2f, %.2f) mag=%.4f baseline=%.4f score=%.2f %s\n",
               i,
               test_data[i].x, test_data[i].y, test_data[i].z,
               out.magnitude,
               state.baseline,
               out.score,
               out.anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
```

How it works:
1. Low-pass filter estimates gravity and slow drift.
2. Subtracting that gives the high-pass motion signal.
3. Motion magnitude is calculated from x, y, z.
4. A rolling baseline tracks typical motion.
5. If current motion is much larger than baseline, it is flagged as an anomaly.

