```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float baseline;
    float alpha;       // low-pass filter coefficient
    float threshold;   // anomaly threshold
    bool initialized;
} AnomalyDetector;

float compute_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

void detector_init(AnomalyDetector *det, float alpha, float threshold) {
    det->baseline = 0.0f;
    det->alpha = alpha;
    det->threshold = threshold;
    det->initialized = false;
}

bool detector_process(AnomalyDetector *det, AccelSample sample, float *mag_out, float *deviation_out) {
    float mag = compute_magnitude(sample);

    if (!det->initialized) {
        det->baseline = mag;
        det->initialized = true;
    } else {
        det->baseline = det->alpha * mag + (1.0f - det->alpha) * det->baseline;
    }

    float deviation = fabsf(mag - det->baseline);

    if (mag_out) *mag_out = mag;
    if (deviation_out) *deviation_out = deviation;

    return deviation > det->threshold;
}

int main(void) {
    AnomalyDetector detector;
    detector_init(&detector, 0.1f, 2.0f);

    // Simulated accelerometer stream
    AccelSample samples[] = {
        {0.0f, 0.1f, 1.0f},
        {0.1f, 0.0f, 0.98f},
        {-0.1f, 0.05f, 1.02f},
        {0.0f, -0.1f, 1.01f},
        {3.5f, 2.0f, 4.0f},   // anomaly
        {0.0f, 0.0f, 1.0f},
        {0.05f, -0.02f, 0.99f}
    };

    int num_samples = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < num_samples; i++) {
        float mag, deviation;
        bool anomaly = detector_process(&detector, samples[i], &mag, &deviation);

        printf("sample %d: mag=%.3f baseline=%.3f deviation=%.3f %s\n",
               i,
               mag,
               detector.baseline,
               deviation,
               anomaly ? "<-- ANOMALY" : "");
    }

    return 0;
}
