#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define MA_WINDOW 8
#define BASELINE_SAMPLES 32
#define THRESHOLD 0.80f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float buffer[MA_WINDOW];
    int index;
    int count;
    float sum;
} MovingAverage;

static void ma_init(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < MA_WINDOW; i++) {
        ma->buffer[i] = 0.0f;
    }
}

static float ma_update(MovingAverage *ma, float value) {
    if (ma->count < MA_WINDOW) {
        ma->buffer[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
        ma->buffer[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % MA_WINDOW;
    return ma->sum / ma->count;
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

int main(void) {
    AccelSample samples[] = {
        {0.01f, 0.02f, 0.98f},
        {0.00f, 0.01f, 1.01f},
        {0.02f, 0.00f, 0.99f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 1.02f},
        {0.01f, 0.01f, 0.97f},
        {0.03f, 0.02f, 1.00f},
        {0.01f, 0.00f, 0.99f},
        {0.02f, 0.01f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.98f},
        {0.02f, 0.02f, 1.00f},
        {0.01f, 0.00f, 0.99f},
        {0.00f, 0.02f, 1.01f},
        {0.01f, 0.01f, 1.00f},
        {0.02f, 0.00f, 0.98f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 1.01f},
        {0.02f, 0.01f, 0.99f},
        {0.01f, 0.00f, 1.00f},
        {0.00f, 0.01f, 0.98f},
        {0.01f, 0.02f, 1.01f},
        {0.02f, 0.00f, 1.00f},
        {0.01f, 0.01f, 0.99f},
        {0.00f, 0.02f, 1.00f},
        {0.02f, 0.01f, 1.01f},
        {0.01f, 0.00f, 0.98f},
        {0.00f, 0.01f, 1.00f},
        {0.01f, 0.02f, 0.99f},
        {0.02f, 0.01f, 1.02f},
        {0.00f, 0.00f, 1.00f},
        {0.01f, 0.01f, 0.99f},

        {0.02f, 0.01f, 1.00f},
        {0.00f, 0.02f, 0.98f},
        {1.50f, 1.20f, 2.20f},
        {0.01f, 0.00f, 1.00f},
        {0.02f, 0.01f, 0.99f},
    };

    int sample_count = sizeof(samples) / sizeof(samples[0]);
    MovingAverage ma;
    ma_init(&ma);

    float baseline_sum = 0.0f;
    float baseline_mean = 0.0f;
    bool baseline_ready = false;

    for (int i = 0; i < sample_count; i++) {
        float mag = accel_magnitude(samples[i]);
        float smooth_mag = ma_update(&ma, mag);

        if (i < BASELINE_SAMPLES) {
            baseline_sum += smooth_mag;
            if (i == BASELINE_SAMPLES - 1) {
                baseline_mean = baseline_sum / BASELINE_SAMPLES;
                baseline_ready = true;
                printf("Baseline learned: %.3f\n", baseline_mean);
            }
            printf("Sample %d: mag=%.3f smooth=%.3f learning\n", i, mag, smooth_mag);
            continue;
        }

        if (baseline_ready) {
            float deviation = fabsf(smooth_mag - baseline_mean);
            bool anomaly = deviation > THRESHOLD;

            printf("Sample %d: mag=%.3f smooth=%.3f deviation=%.3f %s\n",
                   i, mag, smooth_mag, deviation,
                   anomaly ? "ANOMALY" : "normal");
        }
    }

    return 0;
}
