#define ACTUATOR_COUNT          2

#define FILTER_SHIFT            3   /* alpha = 1/8 */
#define SENSOR_MIN_VALID        0
#define SENSOR_MAX_VALID        4095

#define TEMP_ON_THRESHOLD       3000
#define TEMP_OFF_THRESHOLD      2800

#define PRESS_ON_THRESHOLD      2500
#define PRESS_OFF_THRESHOLD     2300

typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool initialized;
    bool fault;
} SensorState;

typedef struct {
    bool enabled;
} ActuatorState;

