    if (channel >= SENSOR_COUNT) {
        return 0;
    }

    /* Simulate small variation */
    fake_values[channel] += (channel == 0) ? 7 : 5;
    if (fake_values[channel] > 3200) fake_values[channel] = (channel == 0) ? 2850 : 2200;

    return fake_values[channel];
}

static void platform_set_gpio(uint8_t actuator_id, bool on) {
    (void)actuator_id;
    (void)on;
    /* Replace with actual GPIO write */
}

static void platform_delay_ms(uint32_t ms) {
    (void)ms;
    /* Replace with actual delay/timer scheduling */
}

/* ---- Core logic ---- */

static bool sensor_value_valid(uint16_t v) {
    return (v >= SENSOR_MIN_VALID) && (v <= SENSOR_MAX_VALID);
}

static void sensor_update(uint8_t id) {
    uint16_t raw;

    if (id >= SENSOR_COUNT) {
        return;
    }

    raw = platform_read_adc(id);
    sensors[id].raw = raw;

    if (!sensor_value_valid(raw)) {
        sensors[id].fault = true;
        return;
    }

    sensors[id].fault = false;

    if (!sensors[id].initialized) {
        sensors[id].filtered = raw;
        sensors[id].initialized = true;
    } else {
        /* Integer IIR filter:
         * filtered = filtered + (raw - filtered)/8
         */
        int32_t delta = (int32_t)raw - (int32_t)sensors[id].filtered;
        sensors[id].filtered = (uint16_t)((int32_t)sensors[id].filtered + (delta >> FILTER_SHIFT));
    }
}

static void actuator_set(uint8_t id, bool on) {
    if (id >= ACTUATOR_COUNT) {
        return;
    }

    actuators[id].enabled = on;
    platform_set_gpio(id, on);
}

static void control_temperature_actuator(void) {
    uint16_t value = sensors[0].filtered;

    if (sensors[0].fault || !sensors[0].initialized) {
        actuator_set(0, false);
        return;
    }

    if (!actuators[0].enabled && value >= TEMP_ON_THRESHOLD) {
        actuator_set(0, true);
    } else if (actuators[0].enabled && value <= TEMP_OFF_THRESHOLD) {
        actuator_set(0, false);
    }
}

static void control_pressure_actuator(void) {
    uint16_t value = sensors[1].filtered;

    if (sensors[1].fault || !sensors[1].initialized) {
        actuator_set(1, false);
        return;
    }

    if (!actuators[1].enabled && value >= PRESS_ON_THRESHOLD) {
        actuator_set(1, true);
    } else if (actuators[1].enabled && value <= PRESS_OFF_THRESHOLD) {
        actuator_set(1, false);
    }
}

static void system_init(void) {
    uint8_t i;

    for (i = 0; i < SENSOR_COUNT; i++) {
        sensors[i].raw = 0;
        sensors[i].filtered = 0;
        sensors[i].initialized = false;
        sensors[i].fault = false;
    }

    for (i = 0; i < ACTUATOR_COUNT; i++) {
        actuators[i].enabled = false;
        platform_set_gpio(i, false);
    }
}

static void system_step(void) {
    uint8_t i;

    for (i = 0; i < SENSOR_COUNT; i++) {
        sensor_update(i);
    }

    control_temperature_actuator();
    control_pressure_actuator();
}

int main(void) {
    system_init();

    while (1) {
        system_step();
        platform_delay_ms(50); /* 20 Hz control loop */
    }

    return 0;
}
