    uint32_t sum;
    uint8_t index;
    bool filled;
} MovingAverageFilter;

typedef struct {
    bool actuator_on;
    MovingAverageFilter filter;
} SystemState;

static void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->filled = false;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    f->sum -= f->samples[f->index];
    f->samples[f->index] = sample;
    f->sum += sample;

    f->index++;
    if (f->index >= FILTER_WINDOW) {
        f->index = 0;
        f->filled = true;
    }

    uint8_t count = f->filled ? FILTER_WINDOW : f->index;
    if (count == 0) return sample;

    return (uint16_t)(f->sum / count);
}

