#define FILTER_WINDOW_SIZE 8

#define SENSOR_MIN_VALID   0
#define SENSOR_MAX_VALID   4095

#define ACTUATOR_ON_THRESHOLD   2500
#define ACTUATOR_OFF_THRESHOLD  2200

typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

typedef struct {
    bool actuator_on;
    bool sensor_fault;
    uint16_t raw_value;
    uint16_t filtered_value;
