        2100, 2200, 2300, 2600, 2700, 2550, 2400, 2150,
        2050, 2800, 2900, 3000, 2100, 2000
    };
    static uint8_t idx = 0;
    uint16_t value = mock_data[idx];
    idx = (idx + 1) % (sizeof(mock_data)/sizeof(mock_data[0]));
    return value;
}

/* Replace with GPIO/PWM control */
static void actuator_set(bool on) {
    if (on) {
        printf("ACTUATOR: ON\n");
    } else {
        printf("ACTUATOR: OFF\n");
    }
}

/* Optional diagnostics/logging */
static void report_status(const SystemState *state) {
    printf("RAW=%u FILTERED=%u FAULT=%s ACT=%s\n",
           state->raw_value,
           state->filtered_value,
           state->sensor_fault ? "YES" : "NO",
           state->actuator_on ? "ON" : "OFF");
}

/* ---------------- Control Logic ---------------- */

static bool sensor_value_valid(uint16_t value) {
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

static void process_cycle(MovingAverageFilter *filter, SystemState *state) {
    uint16_t raw = read_sensor_raw();
    state->raw_value = raw;

    if (!sensor_value_valid(raw)) {
        state->sensor_fault = true;
        state->actuator_on = false;
        actuator_set(false);
        return;
