        sys->actuator = ACTUATOR_OFF;
        hal_set_actuator(false);
        return;
    }

    if (sys->actuator == ACTUATOR_OFF) {
        if (sys->filtered >= ACTUATOR_ON_THRESHOLD) {
            sys->actuator = ACTUATOR_ON;
            hal_set_actuator(true);
        }
    } else {
        if (sys->filtered <= ACTUATOR_OFF_THRESHOLD) {
            sys->actuator = ACTUATOR_OFF;
            hal_set_actuator(false);
        }
    }
}

static void edge_system_init(edge_system_t *sys) {
    sys->raw = 0;
    sys->filtered = 0;
    sys->initialized = 0;
    sys->fault_count = 0;
    sys->sensor_fault = false;
    sys->actuator = ACTUATOR_OFF;

    hal_set_actuator(false);
    hal_signal_fault(false);
}

static void edge_system_step(edge_system_t *sys) {
    uint16_t sample = hal_read_sensor();
    sys->raw = sample;

    if (!sensor_value_valid(sample)) {
        if (sys->fault_count < 255) {
            sys->fault_count++;
        }

        if (sys->fault_count >= FAULT_COUNT_LIMIT) {
            sys->sensor_fault = true;
            hal_signal_fault(true);
        }

        actuator_update(sys);
        return;
    }

    sys->fault_count = 0;
    sys->sensor_fault = false;
    hal_signal_fault(false);

    if (!sys->initialized) {
        sys->filtered = sample;
        sys->initialized = 1;
    } else {
        sys->filtered = low_pass_filter(sys->filtered, sample);
    }

    actuator_update(sys);
}

/*========================
  Main loop
========================*/

int main(void) {
    edge_system_t system;

    edge_system_init(&system);

