```c
#include <stdint.h>
#include <stdbool.h>

/*=========================================================
 * Configuration
 *=========================================================*/

#define SENSOR_MIN_VALID        0u
#define SENSOR_MAX_VALID        4095u      /* Example: 12-bit ADC */

#define FILTER_WINDOW_SIZE      8u         /* Keep small for low RAM */
#define ACTUATOR_ON_THRESHOLD   2500u
#define ACTUATOR_OFF_THRESHOLD  2300u      /* Hysteresis */

#define SENSOR_FAULT_LIMIT      5u         /* Consecutive bad reads before fault */
#define LOOP_PERIOD_MS          10u

/*=========================================================
 * Types
 *=========================================================*/

typedef enum
{
    SYSTEM_OK = 0,
    SYSTEM_SENSOR_FAULT
} system_status_t;

typedef struct
{
    uint16_t samples[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} moving_average_filter_t;

typedef struct
{
    system_status_t status;
    uint16_t raw_sensor;
    uint16_t filtered_sensor;
    bool actuator_on;
    uint8_t consecutive_faults;
} edge_system_t;

/*=========================================================
 * Hardware abstraction layer (replace with real drivers)
 *=========================================================*/

/* Simulated sensor input source */
static uint16_t mock_sensor_sequence[] =
{
    2100, 2200, 2400, 2550, 2600, 2700, 2650, 2500,
    2450, 2350, 2250, 2200, 5000, 5001, 5002, 2200,
    2100, 2050, 2600, 2750
};

static uint32_t mock_sensor_index = 0;
static bool hw_actuator_state = false;

/* Read sensor value */
static uint16_t hw_read_sensor(void)
{
    uint16_t value =
        mock_sensor_sequence[mock_sensor_index %
                             (sizeof(mock_sensor_sequence) / sizeof(mock_sensor_sequence[0]))];
    mock_sensor_index++;
    return value;
}

/* Write actuator output */
static void hw_set_actuator(bool on)
{
    hw_actuator_state = on;
}

/* Optional placeholder for diagnostics/log output */
static void hw_report_status(const edge_system_t *sys)
{
    (void)sys;
    /* In real firmware, this could write to UART, CAN, etc. */
}

/*=========================================================
 * Filter logic
 *=========================================================*/

static void filter_init(moving_average_filter_t *filter)
{
    uint8_t i;
    filter->sum = 0u;
    filter->index = 0u;
    filter->count = 0u;

    for (i = 0u; i < FILTER_WINDOW_SIZE; i++)
    {
        filter->samples[i] = 0u;
    }
}

static uint16_t filter_update(moving_average_filter_t *filter, uint16_t new_sample)
{
    if (filter->count < FILTER_WINDOW_SIZE)
    {
        filter->samples[filter->index] = new_sample;
        filter->sum += new_sample;
        filter->count++;
    }
    else
    {
        filter->sum -= filter->samples[filter->index];
        filter->samples[filter->index] = new_sample;
        filter->sum += new_sample;
    }

    filter->index++;
    if (filter->index >= FILTER_WINDOW_SIZE)
    {
        filter->index = 0u;
    }

    return (uint16_t)(filter->sum / filter->count);
}

/*=========================================================
 * Validation and control
 *=========================================================*/

static bool sensor_value_is_valid(uint16_t value)
{
    return (value >= SENSOR_MIN_VALID) && (value <= SENSOR_MAX_VALID);
}

static void actuator_control_update(edge_system_t *sys)
{
    if (sys->status != SYSTEM_OK)
    {
        sys->actuator_on = false;
        hw_set_actuator(false);
        return;
    }

    if (!sys->actuator_on)
    {
        if (sys->filtered_sensor >= ACTUATOR_ON_THRESHOLD)
        {
            sys->actuator_on = true;
        }
    }
    else
    {
        if (sys->filtered_sensor <= ACTUATOR_OFF_THRESHOLD)
        {
            sys->actuator_on = false;
        }
    }

    hw_set_actuator(sys->actuator_on);
}

/*=========================================================
 * Application logic
 *=========================================================*/

static void edge_system_init(edge_system_t *sys, moving_average_filter_t *filter)
{
    sys->status = SYSTEM_OK;
    sys->raw_sensor = 0u;
    sys->filtered_sensor = 0u;
    sys->actuator_on = false;
    sys->consecutive_faults = 0u;

    filter_init(filter);
    hw_set_actuator(false);
}

static void edge_system_step(edge_system_t *sys, moving_average_filter_t *filter)
{
    uint16_t raw = hw_read_sensor();

    sys->raw_sensor = raw;

    if (sensor_value_is_valid(raw))
    {
        sys->consecutive_faults = 0u;
        sys->status = SYSTEM_OK;
        sys->filtered_sensor = filter_update(filter, raw);
    }
    else
    {
        if (sys->consecutive_faults < 255u)
        {
            sys->consecutive_faults++;
        }

        if (sys->consecutive_faults >= SENSOR_FAULT_LIMIT)
        {
            sys->status = SYSTEM_SENSOR_FAULT;
        }
    }

    actuator_control_update(sys);
    hw_report_status(sys);
}

/*=========================================================
 * Main loop
 *=========================================================*/

int main(void)
{
    edge_system_t system;
    moving_average_filter_t filter;

    edge_system_init(&system, &filter);

    for (;;)
    {
        edge_system_step(&system, &filter);

        /* Replace with a real timer wait, RTOS delay, or low-power sleep */
        /* delay_ms(LOOP_PERIOD_MS); */
    }

    return 0;
}
