#include <stdint.h>

#define FILTER_WINDOW 4
#define ACTUATOR_ON_THRESHOLD  70
#define ACTUATOR_OFF_THRESHOLD 60

static uint16_t sensor_buffer[FILTER_WINDOW] = {0};
