    static uint8_t idx = 0;
    uint16_t value = test_data[idx];
    idx = (idx + 1) % (sizeof(test_data)/sizeof(test_data[0]));
    return value;
}

// Simple moving average filter
uint16_t filter_sensor(uint16_t new_value) {
    sensor_sum -= sensor_buffer[buffer_index];
    sensor_buffer[buffer_index] = new_value;
    sensor_sum += new_value;

    buffer_index = (buffer_index + 1) % FILTER_WINDOW;

    if (samples_collected < FILTER_WINDOW) {
        samples_collected++;
    }

    return (uint16_t)(sensor_sum / samples_collected);
}

// Actuator control with hysteresis
void update_actuator(uint16_t filtered_value) {
    if (!actuator_state && filtered_value >= ACTUATOR_ON_THRESHOLD) {
        actuator_state = 1;
        printf("Actuator ON\n");
    } else if (actuator_state && filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        actuator_state = 0;
        printf("Actuator OFF\n");
    }
}

int main(void) {
    for (int i = 0; i < 20; i++) {
        uint16_t raw = read_sensor();
        uint16_t filtered = filter_sensor(raw);

        printf("Raw: %u, Filtered: %u, Actuator: %s\n",
               raw, filtered, actuator_state ? "ON" : "OFF");

        update_actuator(filtered);
    }

    return 0;
}
