#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/*
 Minimal edge system:
 - reads sensor samples
 - filters them with a fixed-point low-pass filter
 - drives an actuator based on threshold

 This version is portable C for demonstration.
 Replace read_sensor() and set_actuator() with hardware-specific code.
*/

#define FILTER_SHIFT 3          // alpha = 1/8
#define ACTUATION_THRESHOLD 600 // threshold in sensor units

static uint16_t simulated_samples[] = {
    420, 430, 415, 700, 710, 690, 500, 480, 470, 650, 640, 430
};
static size_t sample_index = 0;
static bool actuator_state = false;

/* Simulated sensor read */
static uint16_t read_sensor(void) {
    uint16_t value = simulated_samples[sample_index];
    sample_index = (sample_index + 1) % (sizeof(simulated_samples) / sizeof(simulated_samples[0]));
    return value;
}

/* Simulated actuator write */
static void set_actuator(bool on) {
    if (actuator_state != on) {
        actuator_state = on;
        printf("Actuator: %s\n", on ? "ON" : "OFF");
    }
}

/*
 Fixed-point low-pass filter:
 filtered = filtered + (new_sample - filtered) / 8
*/
static uint16_t low_pass_filter(uint16_t sample, uint16_t prev_filtered) {
    int32_t delta = (int32_t)sample - (int32_t)prev_filtered;
    return (uint16_t)(prev_filtered + (delta >> FILTER_SHIFT));
}

int main(void) {
    uint16_t filtered = 0;
    bool initialized = false;

    for (int i = 0; i < 24; i++) {
        uint16_t raw = read_sensor();

        if (!initialized) {
            filtered = raw;
            initialized = true;
        } else {
            filtered = low_pass_filter(raw, filtered);
        }

        if (filtered >= ACTUATION_THRESHOLD) {
            set_actuator(true);
        } else {
            set_actuator(false);
        }

        printf("Raw: %u, Filtered: %u, Threshold: %u\n",
               raw, filtered, ACTUATION_THRESHOLD);
    }

    return 0;
}
