    int sum;
    int index;
    int count;
} MovingAverageFilter;

void filter_init(MovingAverageFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (int i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

int filter_update(MovingAverageFilter *f, int new_value) {
    if (f->count < FILTER_WINDOW) {
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
    }

    f->buffer[f->index] = new_value;
    f->sum += new_value;
    f->index = (f->index + 1) % FILTER_WINDOW;

    return f->sum / f->count;
}

int read_sensor(void) {
