    static int idx = 0;
    int value = sample_data[idx];
    idx = (idx + 1) % (sizeof(sample_data) / sizeof(sample_data[0]));
    return value;
}

void actuator_set(Actuator *a, int new_state) {
    if (a->state != new_state) {
        a->state = new_state;
        printf("Actuator %s\n", a->state ? "ON" : "OFF");
    }
}

void process_sensor_and_control(Actuator *actuator, MovingAverageFilter *filter) {
