        printf("Actuator %s\n", on ? "ON" : "OFF");
    }
}

uint16_t filter_sensor(uint16_t new_sample) {
    running_sum -= sensor_buffer[buffer_index];
    sensor_buffer[buffer_index] = new_sample;
    running_sum += new_sample;

    buffer_index++;
    if (buffer_index >= FILTER_WINDOW) {
        buffer_index = 0;
    }

    return (uint16_t)(running_sum / FILTER_WINDOW);
}

void control_actuator(uint16_t filtered_value) {
    if (!actuator_on && filtered_value >= ACTUATOR_THRESHOLD_ON) {
        set_actuator(true);
    } else if (actuator_on && filtered_value <= ACTUATOR_THRESHOLD_OFF) {
        set_actuator(false);
    }
}

int main(void) {
    for (int i = 0; i < FILTER_WINDOW; i++) {
        uint16_t s = read_sensor();
        sensor_buffer[i] = s;
        running_sum += s;
    }

    while (1) {
        uint16_t raw = read_sensor();
        uint16_t filtered = filter_sensor(raw);

        printf("Raw: %u, Filtered: %u\n", raw, filtered);

        control_actuator(filtered);

        /* Replace with platform delay or scheduler tick */
        /* On embedded hardware, avoid busy waiting if possible */
    }

    return 0;
}
```

How it works:
- `read_sensor()` simulates sensor input.
- `filter_sensor()` applies a moving average over 4 samples.
- `control_actuator()` uses hysteresis:
  - turn on at `>= 700`
  - turn off at `<= 650`
- `set_actuator()` simulates actuator control.

Why this is suitable for constrained edge systems:
- fixed-size memory only
- no dynamic allocation
- simple integer math
- low CPU overhead
- straightforward to port to bare metal or RTOS

For real hardware, you would replace:
- `read_sensor()` with ADC/I2C/SPI sensor code
- `set_actuator()` with GPIO/PWM/relay control
- `printf()` with UART logging or remove it entirely
- the empty loop timing with a timer interrupt or RTOS task delay

