# 1) PlayerController2D.cs

Attach this to your **Player** GameObject.

**Player GameObject recommended components:**
- `Rigidbody2D`
- `CapsuleCollider2D` or `BoxCollider2D`
- `SpriteRenderer`
- `Animator`
- Optional empty child `GroundCheck`

```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D))]
[RequireComponent(typeof(Collider2D))]
[RequireComponent(typeof(SpriteRenderer))]
public class PlayerController2D : MonoBehaviour
{
    [Header("Movement")]
    public float maxMoveSpeed = 8f;
    public float groundAcceleration = 60f;
    public float airAcceleration = 35f;
    public float groundDeceleration = 70f;
    public float airDeceleration = 30f;

    [Header("Jump")]
    public float jumpForce = 14f;
    public float coyoteTime = 0.1f;
    public float jumpBufferTime = 0.12f;
    public float fallGravityMultiplier = 2.2f;
    public float lowJumpGravityMultiplier = 1.8f;
    public float maxFallSpeed = -22f;

    [Header("Ground Check")]
    public Transform groundCheck;
    public float groundCheckRadius = 0.15f;
    public LayerMask groundLayer;

    [Header("Animation")]
    public Animator animator;

    private Rigidbody2D rb;
    private SpriteRenderer spriteRenderer;

    private float moveInput;
    private bool jumpPressed;
    private bool jumpReleased;

    private bool isGrounded;
    private float coyoteCounter;
    private float jumpBufferCounter;

    private Vector3 spawnPoint;

    public bool IsGrounded => isGrounded;

    private void Awake()
    {
        rb = GetComponent<Rigidbody2D>();
        spriteRenderer = GetComponent<SpriteRenderer>();

        if (animator == null)
            animator = GetComponent<Animator>();

        spawnPoint = transform.position;
    }

    private void Update()
    {
        moveInput = Input.GetAxisRaw("Horizontal");

        if (Input.GetButtonDown("Jump"))
        {
            jumpPressed = true;
            jumpBufferCounter = jumpBufferTime;
        }

        if (Input.GetButtonUp("Jump"))
        {
            jumpReleased = true;
        }

        UpdateGroundCheck();
        UpdateTimers();
        UpdateAnimations();
        FlipSprite();
    }

    private void FixedUpdate()
    {
        HandleMovement();
        HandleJump();
        ApplyBetterJumpGravity();

        jumpPressed = false;
        jumpReleased = false;
    }

    private void UpdateGroundCheck()
    {
        if (groundCheck != null)
        {
            isGrounded = Physics2D.OverlapCircle(groundCheck.position, groundCheckRadius, groundLayer);
        }
        else
        {
            Collider2D col = GetComponent<Collider2D>();
            Vector2 origin = new Vector2(col.bounds.center.x, col.bounds.min.y - 0.05f);
            Vector2 size = new Vector2(col.bounds.size.x * 0.9f, 0.1f);
            isGrounded = Physics2D.OverlapBox(origin, size, 0f, groundLayer);
        }

        if (isGrounded)
            coyoteCounter = coyoteTime;
    }

    private void UpdateTimers()
    {
        if (!isGrounded)
            coyoteCounter -= Time.deltaTime;

        jumpBufferCounter -= Time.deltaTime;
    }

    private void HandleMovement()
    {
        float targetSpeed = moveInput * maxMoveSpeed;
        float accelRate = 0f;

        if (Mathf.Abs(targetSpeed) > 0.01f)
            accelRate = isGrounded ? groundAcceleration : airAcceleration;
        else
            accelRate = isGrounded ? groundDeceleration : airDeceleration;

        float speedDiff = targetSpeed - rb.velocity.x;
        float movement = speedDiff * accelRate;

        rb.AddForce(Vector2.right * movement);

        if (Mathf.Abs(rb.velocity.x) > maxMoveSpeed)
        {
            rb.velocity = new Vector2(Mathf.Sign(rb.velocity.x) * maxMoveSpeed, rb.velocity.y);
        }
    }

    private void HandleJump()
    {
        if (jumpBufferCounter > 0f && coyoteCounter > 0f)
        {
            rb.velocity = new Vector2(rb.velocity.x, 0f);
            rb.AddForce(Vector2.up * jumpForce, ForceMode2D.Impulse);

            jumpBufferCounter = 0f;
            coyoteCounter = 0f;
        }
    }

    private void ApplyBetterJumpGravity()
    {
        if (rb.velocity.y < 0f)
        {
            rb.gravityScale = fallGravityMultiplier;
        }
        else if (rb.velocity.y > 0f && jumpReleased)
        {
            rb.gravityScale = lowJumpGravityMultiplier;
        }
        else
        {
            rb.gravityScale = 1f;
        }

        if (rb.velocity.y < maxFallSpeed)
        {
            rb.velocity = new Vector2(rb.velocity.x, maxFallSpeed);
        }
    }

    private void FlipSprite()
    {
        if (moveInput > 0.01f)
            spriteRenderer.flipX = false;
        else if (moveInput < -0.01f)
            spriteRenderer.flipX = true;
    }

    private void UpdateAnimations()
    {
        if (animator == null) return;

        animator.SetFloat("Speed", Mathf.Abs(rb.velocity.x));
        animator.SetFloat("VerticalVelocity", rb.velocity.y);
        animator.SetBool("Grounded", isGrounded);
    }

    public void Respawn()
    {
        rb.velocity = Vector2.zero;
        transform.position = spawnPoint;
    }

    public void SetSpawnPoint(Vector3 newSpawnPoint)
    {
        spawnPoint = newSpawnPoint;
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;

        if (groundCheck != null)
        {
            Gizmos.DrawWireSphere(groundCheck.position, groundCheckRadius);
        }
        else
        {
            Collider2D col = GetComponent<Collider2D>();
            if (col != null)
            {
                Vector2 origin = new Vector2(col.bounds.center.x, col.bounds.min.y - 0.05f);
                Vector2 size = new Vector2(col.bounds.size.x * 0.9f, 0.1f);
                Gizmos.DrawWireCube(origin, size);
            }
        }
    }
}
```

