# 3) MovingPlatform2D.cs

Attach to a platform with:
- `Rigidbody2D` set to **Kinematic**
- `BoxCollider2D`

```csharp
using UnityEngine;

public class MovingPlatform2D : MonoBehaviour
{
    public Transform pointA;
    public Transform pointB;
    public float speed = 2f;
    public bool startFromA = true;

    private Vector3 target;

    private void Start()
    {
        if (pointA == null || pointB == null) return;

        transform.position = startFromA ? pointA.position : pointB.position;
        target = startFromA ? pointB.position : pointA.position;
    }

    private void Update()
    {
        if (pointA == null || pointB == null) return;

        transform.position = Vector3.MoveTowards(transform.position, target, speed * Time.deltaTime);

        if (Vector3.Distance(transform.position, target) < 0.01f)
        {
            target = target == pointA.position ? pointB.position : pointA.position;
        }
    }

    private void OnCollisionEnter2D(Collision2D collision)
    {
        if (collision.transform.CompareTag("Player"))
        {
            collision.transform.SetParent(transform);
        }
    }

    private void OnCollisionExit2D(Collision2D collision)
    {
        if (collision.transform.CompareTag("Player"))
        {
            collision.transform.SetParent(null);
        }
    }
}
