</head>
<body>
  <div class="hud">Move: ← → or A D &nbsp; Jump: Space / W / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const WIDTH = canvas.width;
    const HEIGHT = canvas.height;
    const TILE = 48;

    const keys = {};
    addEventListener("keydown", e => { keys[e.key.toLowerCase()] = true; });
    addEventListener("keyup", e => { keys[e.key.toLowerCase()] = false; });

    function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
    function rectsOverlap(a, b) {
      return a.x < b.x + b.w &&
             a.x + a.w > b.x &&
             a.y < b.y + b.h &&
             a.y + a.h > b.y;
    }

    function createPlayerSpriteSheet() {
      const off = document.createElement("canvas");
      off.width = 96;   // 3 frames * 32
      off.height = 32;
      const g = off.getContext("2d");

      function drawFrame(x, legOffset, armOffset, bodyColor) {
        // head
        g.fillStyle = "#ffd6a5";
        g.fillRect(x + 10, 2, 12, 10);

        // body
        g.fillStyle = bodyColor;
        g.fillRect(x + 9, 12, 14, 10);

        // arms
        g.fillStyle = "#ffd6a5";
        g.fillRect(x + 5, 13 + armOffset, 4, 10);
        g.fillRect(x + 23, 13 - armOffset, 4, 10);

        // legs
        g.fillStyle = "#264653";
        g.fillRect(x + 10, 22, 4, 8 + legOffset);
        g.fillRect(x + 18, 22, 4, 8 - legOffset);

        // eyes
        g.fillStyle = "#222";
        g.fillRect(x + 13, 5, 2, 2);
        g.fillRect(x + 17, 5, 2, 2);
      }

      drawFrame(0,  2,  1, "#e76f51");
      drawFrame(32, 0,  0, "#2a9d8f");
      drawFrame(64,-2, -1, "#e76f51");

      return off;
    }

    const playerSheet = createPlayerSpriteSheet();

    const world = {
      width: 3200,
      height: 1200,
      spawn: { x: 100, y: 100 },
      goal: { x: 2900, y: 280, w: 40, h: 80 },
      platforms: [
        { x: 0, y: 500, w: 800, h: 120 },
        { x: 860, y: 450, w: 240, h: 40 },
        { x: 1180, y: 390, w: 220, h: 40 },
        { x: 1460, y: 340, w: 220, h: 40 },
        { x: 1720, y: 440, w: 240, h: 40 },
        { x: 2050, y: 380, w: 180, h: 40 },
        { x: 2310, y: 330, w: 200, h: 40 },
        { x: 2600, y: 500, w: 600, h: 120 },

        { x: 450, y: 380, w: 140, h: 30 },
        { x: 620, y: 300, w: 140, h: 30 },
        { x: 900, y: 260, w: 100, h: 30 },
      ]
    };

    const player = {
      x: world.spawn.x,
      y: world.spawn.y,
      w: 28,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 0.65,
      maxSpeed: 6,
      jumpPower: 14,
      gravity: 0.75,
      friction: 0.82,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 1,
      won: false
    };

    const camera = { x: 0, y: 0 };

    function respawn() {
      player.x = world.spawn.x;
      player.y = world.spawn.y;
      player.vx = 0;
      player.vy = 0;
      player.onGround = false;
      player.won = false;
    }

    function update(dt) {
      if (player.won) {
        if (keys["r"]) respawn();
        return;
      }

      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (!left && !right && player.onGround) {
        player.vx *= player.friction;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      player.vx = clamp(player.vx, -player.maxSpeed, player.maxSpeed);

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vy += player.gravity;
      player.vy = clamp(player.vy, -30, 20);

      // Horizontal move + collision
      player.x += player.vx;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical move + collision
      player.y += player.vy;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Fall off world
      if (player.y > world.height) {
        respawn();
      }

      // Goal
      if (rectsOverlap(player, world.goal)) {
        player.won = true;
      }

      // Animation
      if (!player.onGround) {
        player.frame = 1;
      } else if (Math.abs(player.vx) > 0.3) {
        player.animTime += dt;
        if (player.animTime > 120) {
          player.animTime = 0;
          player.frame = (player.frame + 1) % 3;
        }
      } else {
        player.frame = 1;
        player.animTime = 0;
      }

      // Camera follows player
      camera.x = clamp(player.x - WIDTH / 2 + player.w / 2, 0, world.width - WIDTH);
      camera.y = clamp(player.y - HEIGHT / 2 + player.h / 2, 0, world.height - HEIGHT);
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#6b8e23";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#8fbc46";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 10);

      ctx.strokeStyle = "rgba(0,0,0,0.2)";
      ctx.strokeRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
    }

    function drawGoal(goal) {
      const x = goal.x - camera.x;
      const y = goal.y - camera.y;
      ctx.fillStyle = "#6d6875";
      ctx.fillRect(x + 6, y, 6, goal.h);
      ctx.fillStyle = "#ff006e";
      ctx.beginPath();
      ctx.moveTo(x + 12, y);
      ctx.lineTo(x + 40, y + 12);
      ctx.lineTo(x + 12, y + 24);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      const px = Math.round(player.x - camera.x);
      const py = Math.round(player.y - camera.y);

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(px + player.w, py);
        ctx.scale(-1, 1);
        ctx.drawImage(playerSheet, player.frame * 32, 0, 32, 32, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(playerSheet, player.frame * 32, 0, 32, 32, px, py, player.w, player.h);
      }
      ctx.restore();
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#bde0fe";
      for (let i = 0; i < 8; i++) {
        const x = (i * 450) - (camera.x * 0.2 % 450);
        ctx.beginPath();
        ctx.arc(x, 480, 180, Math.PI, 2 * Math.PI);
        ctx.fill();
      }

      ctx.fillStyle = "#95d5b2";
      for (let i = 0; i < 10; i++) {
        const x = (i * 350) - (camera.x * 0.35 % 350);
        ctx.beginPath();
        ctx.arc(x, 520, 120, Math.PI, 2 * Math.PI);
        ctx.fill();
      }
    }

    function drawGrid() {
      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      for (let x = -camera.x % TILE; x < WIDTH; x += TILE) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, HEIGHT);
        ctx.stroke();
      }
      for (let y = -camera.y % TILE; y < HEIGHT; y += TILE) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(WIDTH, y);
        ctx.stroke();
      }
    }

    function render() {
      ctx.clearRect(0, 0, WIDTH, HEIGHT);

      drawBackground();
      drawGrid();

      for (const p of world.platforms) drawPlatform(p);
      drawGoal(world.goal);
      drawPlayer();

      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, HEIGHT - 42, 230, 32);
      ctx.fillStyle = "#fff";
      ctx.font = "16px sans-serif";
      ctx.fillText(`x:${player.x.toFixed(1)} y:${player.y.toFixed(1)} vy:${player.vy.toFixed(1)}`, 20, HEIGHT - 20);

      if (player.won) {
        ctx.fillStyle = "rgba(0,0,0,0.6)";
        ctx.fillRect(0, 0, WIDTH, HEIGHT);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 42px sans-serif";
        ctx.fillText("You Win!", WIDTH / 2 - 90, HEIGHT / 2 - 10);
        ctx.font = "20px sans-serif";
        ctx.fillText("Press R to restart", WIDTH / 2 - 80, HEIGHT / 2 + 30);
      }
    }

    let last = performance.now();
    function loop(now) {
      const dt = now - last;
      last = now;
      update(dt);
      render();
      requestAnimationFrame(loop);
    }

    respawn();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

