Below is a **minimal working 2D platformer** using **<language>JavaScript</language> + HTML5 Canvas**. It includes:

- Gravity and simple physics
- Collision with platforms and walls
- Left/right movement and jumping
- Basic “sprite animation” via frame-based drawing
- A complete runnable example in one file

Save this as **`index.html`** and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    body {
      margin: 0;
      background: #1e1e2f;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      overflow: hidden;
      font-family: sans-serif;
    }
    canvas {
      border: 2px solid #fff;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
  </style>
</head>
<body>
  <canvas id="game" width="800" height="450"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const GRAVITY = 0.6;
    const FRICTION = 0.8;
    const MOVE_SPEED = 0.8;
    const MAX_SPEED = 5;
    const JUMP_FORCE = -12;

    const keys = {};
    window.addEventListener("keydown", e => keys[e.code] = true);
    window.addEventListener("keyup", e => keys[e.code] = false);

    const platforms = [
      { x: 0, y: 400, w: 800, h: 50 },
      { x: 150, y: 320, w: 120, h: 20 },
      { x: 350, y: 250, w: 140, h: 20 },
      { x: 560, y: 180, w: 120, h: 20 }
    ];

    const player = {
      x: 50,
      y: 300,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTimer: 0,
      animFrame: 0
    };

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      // Input
      if (keys["ArrowLeft"] || keys["KeyA"]) {
        player.vx -= MOVE_SPEED;
        player.facing = -1;
      }
      if (keys["ArrowRight"] || keys["KeyD"]) {
        player.vx += MOVE_SPEED;
        player.facing = 1;
      }
      if ((keys["ArrowUp"] || keys["Space"] || keys["KeyW"]) && player.onGround) {
        player.vy = JUMP_FORCE;
        player.onGround = false;
      }

      // Clamp horizontal speed
      player.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, player.vx));

      // Apply gravity
      player.vy += GRAVITY;

      // Horizontal movement
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > canvas.width) {
        player.x = canvas.width - player.w;
        player.vx = 0;
      }
      if (player.y > canvas.height) {
        // Respawn if fallen
        player.x = 50;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Friction
      if (player.onGround) {
        player.vx *= FRICTION;
      } else {
        player.vx *= 0.98;
      }

      // Animation
      player.animTimer++;
      const moving = Math.abs(player.vx) > 0.5;
      if (!player.onGround) {
        player.animFrame = 2; // jump frame
      } else if (moving) {
        if (player.animTimer > 8) {
          player.animFrame = (player.animFrame + 1) % 2; // walk frames 0,1
          player.animTimer = 0;
        }
      } else {
        player.animFrame = 0; // idle-ish
      }
    }

    function drawPlayer() {
      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);

      // Body color changes by frame to simulate simple sprite animation
      let bodyColor = "#ffcc66";
      if (player.animFrame === 1) bodyColor = "#ffb347";
      if (player.animFrame === 2) bodyColor = "#ffa07a";

      // Head
      ctx.fillStyle = "#f5d7b2";
      ctx.fillRect(-10, -20, 20, 16);

      // Body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(-10, -4, 20, 20);

      // Legs/arms vary slightly by animation frame
      ctx.strokeStyle = "#222";
      ctx.lineWidth = 3;
      ctx.beginPath();

      if (player.animFrame === 1) {
        // walking pose A
        ctx.moveTo(-6, 16); ctx.lineTo(-10, 24);
        ctx.moveTo(6, 16); ctx.lineTo(10, 24);
        ctx.moveTo(-10, 2); ctx.lineTo(-16, 8);
        ctx.moveTo(10, 2); ctx.lineTo(14, 8);
      } else if (player.animFrame === 2) {
        // jump pose
        ctx.moveTo(-6, 16); ctx.lineTo(-4, 24);
        ctx.moveTo(6, 16); ctx.lineTo(4, 24);
        ctx.moveTo(-10, 2); ctx.lineTo(-15, 0);
        ctx.moveTo(10, 2); ctx.lineTo(15, 0);
      } else {
        // idle/walk pose B
        ctx.moveTo(-6, 16); ctx.lineTo(-4, 24);
        ctx.moveTo(6, 16); ctx.lineTo(4, 24);
        ctx.moveTo(-10, 2); ctx.lineTo(-14, 8);
        ctx.moveTo(10, 2); ctx.lineTo(16, 8);
      }

      ctx.stroke();

      // Eye
      ctx.fillStyle = "#222";
      ctx.fillRect(2, -14, 3, 3);

      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#4c956c";
        ctx.fillRect(p.x, p.y, p.w, p.h);

        ctx.fillStyle = "#2f5233";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }
    }

    function drawBackground() {
      // Simple hills
      ctx.fillStyle = "#bde0a8";
      ctx.beginPath();
      ctx.arc(120, 430, 120, Math.PI, 2 * Math.PI);
      ctx.arc(320, 430, 100, Math.PI, 2 * Math.PI);
      ctx.arc(580, 430, 140, Math.PI, 2 * Math.PI);
      ctx.arc(760, 430, 90, Math.PI, 2 * Math.PI);
      ctx.fill();

      ctx.fillStyle = "#9ccc65";
      ctx.beginPath();
      ctx.arc(80, 450, 100, Math.PI, 2 * Math.PI);
      ctx.arc(260, 450, 120, Math.PI, 2 * Math.PI);
      ctx.arc(500, 450, 110, Math.PI, 2 * Math.PI);
      ctx.arc(700, 450, 130, Math.PI, 2 * Math.PI);
      ctx.fill();
    }

    function drawHUD() {
      ctx.fillStyle = "#111";
      ctx.font = "16px sans-serif";
      ctx.fillText("Move: A/D or ←/→   Jump: W / ↑ / Space", 20, 30);
    }

    function update() {
      updatePlayer();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawPlayer();
      drawHUD();
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
