        glGetShaderInfoLog(shader, 512, nullptr, infoLog);
        std::cerr << "Shader compilation failed:\n" << infoLog << std::endl;
    }
    return shader;
}

unsigned int createShaderProgram(const char* vsSource, const char* fsSource)
{
    unsigned int vertexShader = compileShader(GL_VERTEX_SHADER, vsSource);
    unsigned int fragmentShader = compileShader(GL_FRAGMENT_SHADER, fsSource);

    unsigned int shaderProgram = glCreateProgram();
    glAttachShader(shaderProgram, vertexShader);
    glAttachShader(shaderProgram, fragmentShader);
    glLinkProgram(shaderProgram);

    int success;
    char infoLog[512];
    glGetProgramiv(shaderProgram, GL_LINK_STATUS, &success);
    if (!success)
    {
        glGetProgramInfoLog(shaderProgram, 512, nullptr, infoLog);
        std::cerr << "Shader linking failed:\n" << infoLog << std::endl;
    }

    glDeleteShader(vertexShader);
    glDeleteShader(fragmentShader);

    return shaderProgram;
}

void mat4Identity(float* m)
{
    for (int i = 0; i < 16; ++i) m[i] = 0.0f;
    m[0] = m[5] = m[10] = m[15] = 1.0f;
}

void mat4Perspective(float* m, float fovRadians, float aspect, float nearZ, float farZ)
{
    float tanHalfFov = tanf(fovRadians / 2.0f);
    for (int i = 0; i < 16; ++i) m[i] = 0.0f;
    m[0] = 1.0f / (aspect * tanHalfFov);
    m[5] = 1.0f / tanHalfFov;
    m[10] = -(farZ + nearZ) / (farZ - nearZ);
    m[11] = -1.0f;
    m[12] = 0.0f;
    m[13] = 0.0f;
    m[14] = -(2.0f * farZ * nearZ) / (farZ - nearZ);
}

void mat4Translate(float* m, float x, float y, float z)
{
    mat4Identity(m);
    m[12] = x;
    m[13] = y;
    m[14] = z;
}

void mat4Scale(float* m, float sx, float sy, float sz)
{
    mat4Identity(m);
    m[0] = sx;
    m[5] = sy;
    m[10] = sz;
}

void mat4RotateY(float* m, float angle)
{
    mat4Identity(m);
    m[0] = cosf(angle);
    m[2] = sinf(angle);
    m[8] = -sinf(angle);
    m[10] = cosf(angle);
}

void mat4Multiply(float* result, const float* a, const float* b)
{
    float temp[16];
    for (int row = 0; row < 4; ++row)
    {
        for (int col = 0; col < 4; ++col)
        {
            temp[col + row * 4] =
                a[0 + row * 4] * b[col + 0 * 4] +
                a[1 + row * 4] * b[col + 1 * 4] +
                a[2 + row * 4] * b[col + 2 * 4] +
                a[3 + row * 4] * b[col + 3 * 4];
        }
    }
    for (int i = 0; i < 16; ++i) result[i] = temp[i];
}

void mat4LookAt(float* m,
                float eyeX, float eyeY, float eyeZ,
                float centerX, float centerY, float centerZ,
                float upX, float upY, float upZ)
{
    float fx = centerX - eyeX;
    float fy = centerY - eyeY;
    float fz = centerZ - eyeZ;
    float fl = std::sqrt(fx*fx + fy*fy + fz*fz);
    fx /= fl; fy /= fl; fz /= fl;

    float upLen = std::sqrt(upX*upX + upY*upY + upZ*upZ);
    upX /= upLen; upY /= upLen; upZ /= upLen;

    float sx = fy * upZ - fz * upY;
    float sy = fz * upX - fx * upZ;
    float sz = fx * upY - fy * upX;
    float sl = std::sqrt(sx*sx + sy*sy + sz*sz);
    sx /= sl; sy /= sl; sz /= sl;

    float ux = sy * fz - sz * fy;
    float uy = sz * fx - sx * fz;
    float uz = sx * fy - sy * fx;

    mat4Identity(m);
    m[0] = sx;  m[4] = sy;  m[8] = sz;
    m[1] = ux;  m[5] = uy;  m[9] = uz;
    m[2] = -fx; m[6] = -fy; m[10] = -fz;
    m[12] = -(sx * eyeX + sy * eyeY + sz * eyeZ);
    m[13] = -(ux * eyeX + uy * eyeY + uz * eyeZ);
    m[14] = fx * eyeX + fy * eyeY + fz * eyeZ;
}

