// Minimal 4x4 matrix utilities
struct Mat4 {
    float v[16];
};

Mat4 identity() {
    Mat4 m = {};
    m.v[0] = m.v[5] = m.v[10] = m.v[15] = 1.0f;
    return m;
}

Mat4 perspective(float fovRadians, float aspect, float nearZ, float farZ) {
    Mat4 m = {};
    float tanHalfFov = tanf(fovRadians / 2.0f);

    m.v[0] = 1.0f / (aspect * tanHalfFov);
    m.v[5] = 1.0f / tanHalfFov;
    m.v[10] = -(farZ + nearZ) / (farZ - nearZ);
    m.v[11] = -1.0f;
    m.v[14] = -(2.0f * farZ * nearZ) / (farZ - nearZ);
    return m;
}

Mat4 translate(float x, float y, float z) {
    Mat4 m = identity();
    m.v[12] = x;
    m.v[13] = y;
    m.v[14] = z;
    return m;
}

Mat4 rotateY(float angle) {
    Mat4 m = identity();
    m.v[0] = cosf(angle);
    m.v[2] = sinf(angle);
    m.v[8] = -sinf(angle);
    m.v[10] = cosf(angle);
    return m;
}

Mat4 multiply(const Mat4& a, const Mat4& b) {
    Mat4 r = {};
    for (int row = 0; row < 4; ++row) {
        for (int col = 0; col < 4; ++col) {
            r.v[col + row * 4] =
                a.v[0 + row * 4] * b.v[col + 0 * 4] +
                a.v[1 + row * 4] * b.v[col + 1 * 4] +
                a.v[2 + row * 4] * b.v[col + 2 * 4] +
                a.v[3 + row * 4] * b.v[col + 3 * 4];
        }
    }
    return r;
}

Mat4 lookAt(float eyeX, float eyeY, float eyeZ,
            float centerX, float centerY, float centerZ,
            float upX, float upY, float upZ) {
    float fx = centerX - eyeX;
    float fy = centerY - eyeY;
    float fz = centerZ - eyeZ;
    float fl = sqrtf(fx*fx + fy*fy + fz*fz);
    fx /= fl; fy /= fl; fz /= fl;

    float upLen = sqrtf(upX*upX + upY*upY + upZ*upZ);
    upX /= upLen; upY /= upLen; upZ /= upLen;

    float sx = fy * upZ - fz * upY;
    float sy = fz * upX - fx * upZ;
    float sz = fx * upY - fy * upX;
    float sl = sqrtf(sx*sx + sy*sy + sz*sz);
    sx /= sl; sy /= sl; sz /= sl;

    float ux = sy * fz - sz * fy;
    float uy = sz * fx - sx * fz;
    float uz = sx * fy - sy * fx;

    Mat4 m = identity();
    m.v[0] = sx; m.v[4] = sy; m.v[8]  = sz;
    m.v[1] = ux; m.v[5] = uy; m.v[9]  = uz;
    m.v[2] = -fx; m.v[6] = -fy; m.v[10] = -fz;
    m.v[12] = -(sx * eyeX + sy * eyeY + sz * eyeZ);
    m.v[13] = -(ux * eyeX + uy * eyeY + uz * eyeZ);
    m.v[14] =  fx * eyeX + fy * eyeY + fz * eyeZ;
    return m;
}

static void framebuffer_size_callback(GLFWwindow* window, int width, int height) {
