        cameraRadius -= 2.0f * deltaTime;
    if (glfwGetKey(window, GLFW_KEY_DOWN) == GLFW_PRESS)
        cameraRadius += 2.0f * deltaTime;

    if (cameraRadius < 2.0f) cameraRadius = 2.0f;
    if (cameraRadius > 20.0f) cameraRadius = 20.0f;
}

std::string loadFile(const char* path) {
    FILE* file = fopen(path, "rb");
    if (!file) {
        std::cerr << "Failed to open file: " << path << std::endl;
        return "";
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    std::string content;
    content.resize(size);
    fread(content.data(), 1, size, file);
    fclose(file);
    return content;
}

GLuint compileShader(GLenum type, const char* source) {
    GLuint shader = glCreateShader(type);
    glShaderSource(shader, 1, &source, nullptr);
    glCompileShader(shader);

    int success;
    char infoLog[512];
    glGetShaderiv(shader, GL_COMPILE_STATUS, &success);
    if (!success) {
        glGetShaderInfoLog(shader, 512, nullptr, infoLog);
        std::cerr << "Shader compilation error:\n" << infoLog << std::endl;
    }

    return shader;
}

GLuint createShaderProgram(const char* vertPath, const char* fragPath) {
    std::string vertCode = loadFile(vertPath);
    std::string fragCode = loadFile(fragPath);

    GLuint vertShader = compileShader(GL_VERTEX_SHADER, vertCode.c_str());
    GLuint fragShader = compileShader(GL_FRAGMENT_SHADER, fragCode.c_str());

    GLuint program = glCreateProgram();
    glAttachShader(program, vertShader);
    glAttachShader(program, fragShader);
    glLinkProgram(program);

    int success;
    char infoLog[512];
    glGetProgramiv(program, GL_LINK_STATUS, &success);
    if (!success) {
        glGetProgramInfoLog(program, 512, nullptr, infoLog);
        std::cerr << "Program linking error:\n" << infoLog << std::endl;
    }

    glDeleteShader(vertShader);
    glDeleteShader(fragShader);
    return program;
}

