# 2) Implementation

```cpp
// custom_physics_plugin.cpp
#include "custom_physics_plugin.h"

#include <unordered_map>
#include <memory>
#include <mutex>
#include <cmath>

namespace cp {

static constexpr float kEpsilon = 1e-6f;

struct Vec3 {
    float x, y, z;

    Vec3 operator+(const Vec3& r) const { return {x + r.x, y + r.y, z + r.z}; }
    Vec3 operator-(const Vec3& r) const { return {x - r.x, y - r.y, z - r.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
};

struct Quat {
    float x, y, z, w;
};

static Vec3 ToVec3(CPVec3 v) { return {v.x, v.y, v.z}; }
static CPVec3 ToCPVec3(Vec3 v) { return {v.x, v.y, v.z}; }
static Quat ToQuat(CPQuat q) { return {q.x, q.y, q.z, q.w}; }
static CPQuat ToCPQuat(Quat q) { return {q.x, q.y, q.z, q.w}; }

struct RigidBody {
    float mass = 1.0f;
    float invMass = 1.0f;
    bool isStatic = false;

    Vec3 position {0,0,0};
    Quat rotation {0,0,0,1};

    Vec3 linearVelocity {0,0,0};
    Vec3 angularVelocity {0,0,0};

    Vec3 accumulatedForce {0,0,0};
};

class PhysicsWorld {
public:
    explicit PhysicsWorld(Vec3 g) : gravity(g) {}

    CPBodyHandle CreateBody(const CPRigidBodyDesc& desc) {
        std::lock_guard<std::mutex> lock(mutex);

        CPBodyHandle id = ++nextBodyId;
        auto body = std::make_unique<RigidBody>();

        body->mass = desc.mass <= kEpsilon ? 1.0f : desc.mass;
        body->invMass = 1.0f / body->mass;
        body->isStatic = desc.isStatic != 0;

        if (body->isStatic) {
            body->mass = 0.0f;
            body->invMass = 0.0f;
        }

        body->position = ToVec3(desc.position);
        body->rotation = ToQuat(desc.rotation);
        body->linearVelocity = ToVec3(desc.linearVelocity);
        body->angularVelocity = ToVec3(desc.angularVelocity);

        bodies[id] = std::move(body);
        return id;
    }

    void DestroyBody(CPBodyHandle id) {
        std::lock_guard<std::mutex> lock(mutex);
        bodies.erase(id);
    }

    void ApplyForce(CPBodyHandle id, Vec3 force) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = bodies.find(id);
        if (it == bodies.end()) return;
        if (it->second->isStatic) return;
        it->second->accumulatedForce += force;
    }

    void SetLinearVelocity(CPBodyHandle id, Vec3 v) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = bodies.find(id);
        if (it == bodies.end()) return;
        it->second->linearVelocity = v;
    }

    Vec3 GetLinearVelocity(CPBodyHandle id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = bodies.find(id);
        if (it == bodies.end()) return {0,0,0};
        return it->second->linearVelocity;
    }

    CPTransform GetTransform(CPBodyHandle id) {
        std::lock_guard<std::mutex> lock(mutex);
        CPTransform t {};
        auto it = bodies.find(id);
        if (it == bodies.end()) {
            t.position = {0,0,0};
            t.rotation = {0,0,0,1};
            return t;
        }
        t.position = ToCPVec3(it->second->position);
        t.rotation = ToCPQuat(it->second->rotation);
        return t;
    }

    void SetTransform(CPBodyHandle id, CPTransform t) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = bodies.find(id);
        if (it == bodies.end()) return;
        it->second->position = ToVec3(t.position);
        it->second->rotation = ToQuat(t.rotation);
    }

    void Step(float dt) {
        std::lock_guard<std::mutex> lock(mutex);

        if (dt <= 0.0f) return;

        for (auto& [id, body] : bodies) {
            if (body->isStatic) continue;

            Vec3 accel = gravity + (body->accumulatedForce * body->invMass);

            body->linearVelocity += accel * dt;
            body->position += body->linearVelocity * dt;

            // Simple ground plane at y = 0
            if (body->position.y < 0.0f) {
                body->position.y = 0.0f;
                if (body->linearVelocity.y < 0.0f) {
                    body->linearVelocity.y *= -0.35f; // restitution
                }
                body->linearVelocity.x *= 0.98f; // basic friction
                body->linearVelocity.z *= 0.98f;
            }

            body->accumulatedForce = {0,0,0};
        }
    }

private:
    std::mutex mutex;
    Vec3 gravity {0.0f, -9.81f, 0.0f};
    std::unordered_map<CPBodyHandle, std::unique_ptr<RigidBody>> bodies;
    CPBodyHandle nextBodyId = 0;
};

static std::unordered_map<CPWorldHandle, std::unique_ptr<PhysicsWorld>> g_worlds;
static std::mutex g_worldsMutex;
static CPWorldHandle g_nextWorldId = 0;
static bool g_initialized = false;

static PhysicsWorld* GetWorld(CPWorldHandle handle) {
    auto it = g_worlds.find(handle);
    if (it == g_worlds.end()) return nullptr;
    return it->second.get();
}

} // namespace cp

CPPluginVersion CP_GetVersion(void) {
    return {1, 0, 0};
}

int CP_Initialize(void) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::g_initialized = true;
    return 1;
}

void CP_Shutdown(void) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::g_worlds.clear();
    cp::g_initialized = false;
}

CPWorldHandle CP_CreateWorld(CPVec3 gravity) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    if (!cp::g_initialized) return 0;

    CPWorldHandle id = ++cp::g_nextWorldId;
    cp::g_worlds[id] = std::make_unique<cp::PhysicsWorld>(cp::ToVec3(gravity));
    return id;
}

void CP_DestroyWorld(CPWorldHandle world) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::g_worlds.erase(world);
}

void CP_StepWorld(CPWorldHandle world, float deltaTime) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) return;
    w->Step(deltaTime);
}

CPBodyHandle CP_CreateRigidBody(CPWorldHandle world, CPRigidBodyDesc desc) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) return 0;
    return w->CreateBody(desc);
}

void CP_DestroyRigidBody(CPWorldHandle world, CPBodyHandle body) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) return;
    w->DestroyBody(body);
}

void CP_ApplyForce(CPWorldHandle world, CPBodyHandle body, CPVec3 force) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) return;
    w->ApplyForce(body, cp::ToVec3(force));
}

void CP_SetLinearVelocity(CPWorldHandle world, CPBodyHandle body, CPVec3 velocity) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) return;
    w->SetLinearVelocity(body, cp::ToVec3(velocity));
}

CPVec3 CP_GetLinearVelocity(CPWorldHandle world, CPBodyHandle body) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) return {0,0,0};
    return cp::ToCPVec3(w->GetLinearVelocity(body));
}

CPTransform CP_GetTransform(CPWorldHandle world, CPBodyHandle body) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) {
        CPTransform t {};
        t.position = {0,0,0};
        t.rotation = {0,0,0,1};
        return t;
    }
    return w->GetTransform(body);
}

void CP_SetTransform(CPWorldHandle world, CPBodyHandle body, CPTransform t) {
    std::lock_guard<std::mutex> lock(cp::g_worldsMutex);
    cp::PhysicsWorld* w = cp::GetWorld(world);
    if (!w) return;
    w->SetTransform(body, t);
}
