#include "CustomPhysicsPlugin.h"

#include <unordered_map>
#include <vector>
#include <cmath>
#include <mutex>
#include <algorithm>

namespace
{
    struct Vec3
    {
        float x, y, z;

        Vec3 operator+(const Vec3& rhs) const { return {x + rhs.x, y + rhs.y, z + rhs.z}; }
        Vec3 operator-(const Vec3& rhs) const { return {x - rhs.x, y - rhs.y, z - rhs.z}; }
        Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
        Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
    };

    static float Dot(const Vec3& a, const Vec3& b)
    {
        return a.x * b.x + a.y * b.y + a.z * b.z;
    }

    static float LengthSq(const Vec3& v)
    {
        return Dot(v, v);
    }

    static float Length(const Vec3& v)
    {
        return std::sqrt(LengthSq(v));
    }

    static Vec3 Normalize(const Vec3& v)
    {
        float len = Length(v);
        if (len <= 1e-6f) return {0.0f, 1.0f, 0.0f};
        return {v.x / len, v.y / len, v.z / len};
    }

    static Vec3 ToVec3(CPVec3 v)
    {
        return {v.x, v.y, v.z};
    }

    static CPVec3 ToCPVec3(Vec3 v)
    {
        return {v.x, v.y, v.z};
    }

    struct Body
    {
        CPBodyHandle handle = 0;
        float mass = 1.0f;
        float invMass = 1.0f;
        float restitution = 0.5f;
        float friction = 0.5f;

        float radius = 0.5f;

        Vec3 position{0,0,0};
        Vec3 velocity{0,0,0};

        bool dynamic = true;
    };

    struct World
    {
        CPWorldHandle handle = 0;
        Vec3 gravity{0.0f, -9.81f, 0.0f};
        std::unordered_map<CPBodyHandle, Body> bodies;
        CPBodyHandle nextBodyHandle = 1;
    };

    std::unordered_map<CPWorldHandle, World> g_worlds;
    CPWorldHandle g_nextWorldHandle = 1;
    std::mutex g_mutex;
    bool g_initialized = false;

    static Body* GetBody(World& world, CPBodyHandle handle)
    {
        auto it = world.bodies.find(handle);
        if (it == world.bodies.end())
            return nullptr;
        return &it->second;
    }

    static void ResolveSphereSphere(Body& a, Body& b)
    {
        Vec3 delta = b.position - a.position;
        float distSq = LengthSq(delta);
        float radiusSum = a.radius + b.radius;

        if (distSq > radiusSum * radiusSum)
            return;

        float dist = std::sqrt(std::max(distSq, 1e-8f));
        Vec3 normal = (dist > 1e-6f) ? delta * (1.0f / dist) : Vec3{0.0f, 1.0f, 0.0f};

        float penetration = radiusSum - dist;
        if (penetration > 0.0f)
        {
            float totalInvMass = a.invMass + b.invMass;
            if (totalInvMass > 0.0f)
            {
                Vec3 correction = normal * (penetration / totalInvMass);
                if (a.dynamic)
                    a.position += correction * (-a.invMass);
                if (b.dynamic)
                    b.position += correction * ( b.invMass);
            }
        }

        Vec3 relativeVelocity = b.velocity - a.velocity;
        float velAlongNormal = Dot(relativeVelocity, normal);

        if (velAlongNormal > 0.0f)
            return;

        float restitution = std::min(a.restitution, b.restitution);
        float totalInvMass = a.invMass + b.invMass;
        if (totalInvMass <= 0.0f)
            return;

        float j = -(1.0f + restitution) * velAlongNormal;
        j /= totalInvMass;

        Vec3 impulse = normal * j;

        if (a.dynamic)
            a.velocity += impulse * (-a.invMass);
        if (b.dynamic)
            b.velocity += impulse * ( b.invMass);
    }
}

extern "C"
{

CUSTOM_PHYSICS_API bool CP_Initialize()
{
    std::lock_guard<std::mutex> lock(g_mutex);
    if (g_initialized)
        return true;

    g_initialized = true;
    return true;
}

CUSTOM_PHYSICS_API void CP_Shutdown()
{
    std::lock_guard<std::mutex> lock(g_mutex);
    g_worlds.clear();
    g_nextWorldHandle = 1;
    g_initialized = false;
}

CUSTOM_PHYSICS_API CPWorldHandle CP_CreateWorld()
{
    std::lock_guard<std::mutex> lock(g_mutex);
    if (!g_initialized)
        return 0;

    CPWorldHandle handle = g_nextWorldHandle++;
    World world;
    world.handle = handle;
    g_worlds.emplace(handle, std::move(world));
    return handle;
}

CUSTOM_PHYSICS_API void CP_DestroyWorld(CPWorldHandle worldHandle)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    g_worlds.erase(worldHandle);
}

CUSTOM_PHYSICS_API void CP_SetGravity(CPWorldHandle worldHandle, CPVec3 gravity)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto it = g_worlds.find(worldHandle);
    if (it == g_worlds.end())
        return;

    it->second.gravity = ToVec3(gravity);
}

CUSTOM_PHYSICS_API CP_StepSimulation(CPWorldHandle worldHandle, float dt)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto it = g_worlds.find(worldHandle);
    if (it == g_worlds.end() || dt <= 0.0f)
        return;

    World& world = it->second;

    for (auto& kv : world.bodies)
    {
        Body& b = kv.second;
        if (!b.dynamic)
            continue;

        b.velocity += world.gravity * dt;
        b.position += b.velocity * dt;
    }

    std::vector<CPBodyHandle> handles;
    handles.reserve(world.bodies.size());
    for (auto& kv : world.bodies)
        handles.push_back(kv.first);

    for (size_t i = 0; i < handles.size(); ++i)
    {
        for (size_t j = i + 1; j < handles.size(); ++j)
        {
            Body* a = GetBody(world, handles[i]);
            Body* b = GetBody(world, handles[j]);
            if (!a || !b)
                continue;

            ResolveSphereSphere(*a, *b);
        }
    }

    for (auto& kv : world.bodies)
    {
        Body& b = kv.second;
        float floorY = 0.0f;
        if (b.position.y - b.radius < floorY)
        {
            b.position.y = floorY + b.radius;
            if (b.velocity.y < 0.0f)
                b.velocity.y = -b.velocity.y * b.restitution;
        }
    }
}

CUSTOM_PHYSICS_API CPBodyHandle CP_CreateBody(CPWorldHandle worldHandle, const CPBodyDesc* desc)
{
    if (!desc)
        return 0;

    std::lock_guard<std::mutex> lock(g_mutex);
    auto it = g_worlds.find(worldHandle);
    if (it == g_worlds.end())
        return 0;

    World& world = it->second;

    CPBodyHandle handle = world.nextBodyHandle++;

    Body body;
    body.handle = handle;
    body.mass = desc->mass <= 0.0f ? 0.0f : desc->mass;
    body.invMass = body.mass > 0.0f ? 1.0f / body.mass : 0.0f;
    body.dynamic = body.mass > 0.0f;
    body.restitution = desc->restitution;
    body.friction = desc->friction;
    body.position = ToVec3(desc->position);
    body.velocity = ToVec3(desc->velocity);

    if (desc->shapeType == CP_SHAPE_SPHERE)
        body.radius = std::max(desc->sphere.radius, 0.001f);

    world.bodies.emplace(handle, body);
    return handle;
}

CUSTOM_PHYSICS_API void CP_DestroyBody(CPWorldHandle worldHandle, CPBodyHandle bodyHandle)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto it = g_worlds.find(worldHandle);
    if (it == g_worlds.end())
        return;

    it->second.bodies.erase(bodyHandle);
}

CUSTOM_PHYSICS_API void CP_SetBodyPosition(CPWorldHandle worldHandle, CPBodyHandle bodyHandle, CPVec3 position)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto wit = g_worlds.find(worldHandle);
    if (wit == g_worlds.end())
        return;

    Body* body = GetBody(wit->second, bodyHandle);
    if (!body)
        return;

    body->position = ToVec3(position);
}

CUSTOM_PHYSICS_API CPVec3 CP_GetBodyPosition(CPWorldHandle worldHandle, CPBodyHandle bodyHandle)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto wit = g_worlds.find(worldHandle);
    if (wit == g_worlds.end())
        return {0,0,0};

    Body* body = GetBody(wit->second, bodyHandle);
    if (!body)
        return {0,0,0};

    return ToCPVec3(body->position);
}

CUSTOM_PHYSICS_API void CP_SetBodyVelocity(CPWorldHandle worldHandle, CPBodyHandle bodyHandle, CPVec3 velocity)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto wit = g_worlds.find(worldHandle);
    if (wit == g_worlds.end())
        return;

    Body* body = GetBody(wit->second, bodyHandle);
    if (!body)
        return;

    body->velocity = ToVec3(velocity);
}

CUSTOM_PHYSICS_API CPVec3 CP_GetBodyVelocity(CPWorldHandle worldHandle, CPBodyHandle bodyHandle)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto wit = g_worlds.find(worldHandle);
    if (wit == g_worlds.end())
        return {0,0,0};

    Body* body = GetBody(wit->second, bodyHandle);
    if (!body)
        return {0,0,0};

    return ToCPVec3(body->velocity);
}

