# 2) Implementation

## `src/custom_physics_plugin.cpp`

```cpp
#include "custom_physics_plugin.h"

#include <vector>
#include <algorithm>
#include <new>
#include <cmath>

struct Body
{
    float mass = 1.0f;
    float invMass = 1.0f;
    CPP_Vec3 position {0.0f, 0.0f, 0.0f};
    CPP_Vec3 velocity {0.0f, 0.0f, 0.0f};
    CPP_Vec3 accumulatedForce {0.0f, 0.0f, 0.0f};
    bool isStatic = false;
};

struct World
{
    CPP_Vec3 gravity {0.0f, -9.81f, 0.0f};
    std::vector<Body*> bodies;
    float fixedTimeStep = 1.0f / 60.0f;
    float accumulator = 0.0f;
};

struct CPP_WorldHandle_t
{
    World* world;
};

struct CPP_BodyHandle_t
{
    Body* body;
};

static inline CPP_Vec3 Vec3Add(CPP_Vec3 a, CPP_Vec3 b)
{
    return { a.x + b.x, a.y + b.y, a.z + b.z };
}

static inline CPP_Vec3 Vec3Sub(CPP_Vec3 a, CPP_Vec3 b)
{
    return { a.x - b.x, a.y - b.y, a.z - b.z };
}

static inline CPP_Vec3 Vec3Scale(CPP_Vec3 v, float s)
{
    return { v.x * s, v.y * s, v.z * s };
}

static inline CPP_Vec3 Vec3Zero()
{
    return { 0.0f, 0.0f, 0.0f };
}

static void IntegrateBody(Body* body, CPP_Vec3 gravity, float dt)
{
    if (!body || body->isStatic)
        return;

    CPP_Vec3 gravityForce = Vec3Scale(gravity, body->mass);
    CPP_Vec3 totalForce = Vec3Add(body->accumulatedForce, gravityForce);
    CPP_Vec3 acceleration = Vec3Scale(totalForce, body->invMass);

    body->velocity = Vec3Add(body->velocity, Vec3Scale(acceleration, dt));
    body->position = Vec3Add(body->position, Vec3Scale(body->velocity, dt));

    body->accumulatedForce = Vec3Zero();
}

extern "C"
{

CPP_API int CPP_Initialize(void)
{
    return 1;
}

CPP_API void CPP_Shutdown(void)
{
}

CPP_API CPP_WorldHandle CPP_CreateWorld(void)
{
    World* w = new (std::nothrow) World();
    if (!w)
        return nullptr;

    CPP_WorldHandle_t* handle = new (std::nothrow) CPP_WorldHandle_t();
    if (!handle)
    {
        delete w;
        return nullptr;
    }

    handle->world = w;
    return handle;
}

CPP_API void CPP_DestroyWorld(CPP_WorldHandle world)
{
    if (!world || !world->world)
        return;

    for (Body* body : world->world->bodies)
        delete body;

    world->world->bodies.clear();
    delete world->world;
    world->world = nullptr;
    delete world;
}

CPP_API void CPP_SetGravity(CPP_WorldHandle world, CPP_Vec3 gravity)
{
    if (!world || !world->world)
        return;

    world->world->gravity = gravity;
}

CPP_API void CPP_StepWorld(CPP_WorldHandle world, float deltaTime)
{
    if (!world || !world->world || deltaTime <= 0.0f)
        return;

    World* w = world->world;
    w->accumulator += deltaTime;

    while (w->accumulator >= w->fixedTimeStep)
    {
        for (Body* body : w->bodies)
            IntegrateBody(body, w->gravity, w->fixedTimeStep);

        w->accumulator -= w->fixedTimeStep;
    }
}

CPP_API CPP_BodyHandle CPP_CreateBody(CPP_WorldHandle world, const CPP_BodyDesc* desc)
{
    if (!world || !world->world || !desc)
        return nullptr;

    Body* body = new (std::nothrow) Body();
    if (!body)
        return nullptr;

    body->mass = (desc->mass <= 0.0f) ? 1.0f : desc->mass;
    body->invMass = 1.0f / body->mass;
    body->position = desc->position;
    body->velocity = desc->velocity;
    body->isStatic = (desc->isStatic != 0);

    if (body->isStatic)
    {
        body->mass = 0.0f;
        body->invMass = 0.0f;
    }

    world->world->bodies.push_back(body);

    CPP_BodyHandle_t* handle = new (std::nothrow) CPP_BodyHandle_t();
    if (!handle)
    {
        auto& bodies = world->world->bodies;
        bodies.erase(std::remove(bodies.begin(), bodies.end(), body), bodies.end());
        delete body;
        return nullptr;
    }

    handle->body = body;
    return handle;
}

CPP_API void CPP_DestroyBody(CPP_WorldHandle world, CPP_BodyHandle body)
{
    if (!world || !world->world || !body || !body->body)
        return;

    Body* rawBody = body->body;
    auto& bodies = world->world->bodies;
    bodies.erase(std::remove(bodies.begin(), bodies.end(), rawBody), bodies.end());
    delete rawBody;
    body->body = nullptr;
    delete body;
}

CPP_API void CPP_ApplyForce(CPP_WorldHandle world, CPP_BodyHandle body, CPP_Vec3 force)
{
    if (!world || !world->world || !body || !body->body)
        return;

    Body* b = body->body;
    if (b->isStatic)
        return;

    b->accumulatedForce = Vec3Add(b->accumulatedForce, force);
}

CPP_API void CPP_SetPosition(CPP_WorldHandle world, CPP_BodyHandle body, CPP_Vec3 position)
{
    (void)world;
    if (!body || !body->body)
        return;

    body->body->position = position;
}

CPP_API void CPP_SetVelocity(CPP_WorldHandle world, CPP_BodyHandle body, CPP_Vec3 velocity)
{
    (void)world;
    if (!body || !body->body)
        return;

    body->body->velocity = velocity;
}

CPP_API CPP_Vec3 CPP_GetPosition(CPP_WorldHandle world, CPP_BodyHandle body)
{
    (void)world;
    if (!body || !body->body)
        return CPP_Vec3{0.0f, 0.0f, 0.0f};

    return body->body->position;
}

CPP_API CPP_Vec3 CPP_GetVelocity(CPP_WorldHandle world, CPP_BodyHandle body)
{
    (void)world;
    if (!body || !body->body)
        return CPP_Vec3{0.0f, 0.0f, 0.0f};

    return body->body->velocity;
}

} /* extern "C" */
