# 3. Source: `CustomPhysicsPlugin.cpp`

```cpp
#include "CustomPhysicsPlugin.h"

#include <vector>
#include <algorithm>
#include <memory>
#include <mutex>

namespace
{
    struct Vec3
    {
        float x = 0.0f;
        float y = 0.0f;
        float z = 0.0f;

        Vec3 operator+(const Vec3& rhs) const
        {
            return { x + rhs.x, y + rhs.y, z + rhs.z };
        }

        Vec3 operator-(const Vec3& rhs) const
        {
            return { x - rhs.x, y - rhs.y, z - rhs.z };
        }

        Vec3 operator*(float s) const
        {
            return { x * s, y * s, z * s };
        }

        Vec3& operator+=(const Vec3& rhs)
        {
            x += rhs.x;
            y += rhs.y;
            z += rhs.z;
            return *this;
        }
    };

    static Vec3 ToInternal(CPVec3 v)
    {
        return { v.x, v.y, v.z };
    }

    static CPVec3 ToExternal(const Vec3& v)
    {
        return { v.x, v.y, v.z };
    }

    struct Transform
    {
        Vec3 position;
        Vec3 rotationEuler;
    };

    static Transform ToInternal(CPTransform t)
    {
        return { ToInternal(t.position), ToInternal(t.rotationEuler) };
    }

    static CPTransform ToExternal(const Transform& t)
    {
        CPTransform out;
        out.position = ToExternal(t.position);
        out.rotationEuler = ToExternal(t.rotationEuler);
        return out;
    }

    class RigidBody
    {
    public:
        CPBodyType type = CP_BODY_STATIC;
        float mass = 1.0f;
        float inverseMass = 1.0f;
        Transform transform;
        Vec3 velocity;
        Vec3 accumulatedForce;

        explicit RigidBody(const CPBodyDesc& desc)
        {
            type = desc.type;
            mass = desc.mass <= 0.0f ? 1.0f : desc.mass;
            inverseMass = (type == CP_BODY_DYNAMIC) ? (1.0f / mass) : 0.0f;
            transform = ToInternal(desc.transform);
            velocity = ToInternal(desc.initialVelocity);
            accumulatedForce = {0.0f, 0.0f, 0.0f};
        }

        void ApplyForce(const Vec3& force)
        {
            if (type == CP_BODY_DYNAMIC)
            {
                accumulatedForce += force;
            }
        }

        void Integrate(const Vec3& gravity, float dt)
        {
            if (type != CP_BODY_DYNAMIC || dt <= 0.0f)
                return;

            Vec3 acceleration = gravity + (accumulatedForce * inverseMass);
            velocity += acceleration * dt;
            transform.position += velocity * dt;

            accumulatedForce = {0.0f, 0.0f, 0.0f};
        }
    };

    class PhysicsWorld
    {
    public:
        explicit PhysicsWorld(const Vec3& g)
            : gravity(g)
        {
        }

        RigidBody* CreateBody(const CPBodyDesc& desc)
        {
            std::lock_guard<std::mutex> lock(mutex);
            bodies.push_back(std::make_unique<RigidBody>(desc));
            return bodies.back().get();
        }

        void DestroyBody(RigidBody* body)
        {
            std::lock_guard<std::mutex> lock(mutex);
            bodies.erase(
                std::remove_if(
                    bodies.begin(),
                    bodies.end(),
                    [body](const std::unique_ptr<RigidBody>& ptr)
                    {
                        return ptr.get() == body;
                    }),
                bodies.end());
        }

        void Step(float dt)
        {
            std::lock_guard<std::mutex> lock(mutex);
            for (auto& body : bodies)
            {
                body->Integrate(gravity, dt);
            }
        }

    private:
        Vec3 gravity;
        std::vector<std::unique_ptr<RigidBody>> bodies;
        std::mutex mutex;
    };

    bool g_initialized = false;
}

PHYSICS_PLUGIN_EXPORT bool CP_Initialize()
{
    g_initialized = true;
    return true;
}

PHYSICS_PLUGIN_EXPORT void CP_Shutdown()
{
    g_initialized = false;
}

PHYSICS_PLUGIN_EXPORT CPWorldHandle CP_CreateWorld(CPVec3 gravity)
{
    if (!g_initialized)
        return nullptr;

    PhysicsWorld* world = new PhysicsWorld(ToInternal(gravity));
    return reinterpret_cast<CPWorldHandle>(world);
}

PHYSICS_PLUGIN_EXPORT void CP_DestroyWorld(CPWorldHandle world)
{
    auto* physicsWorld = reinterpret_cast<PhysicsWorld*>(world);
    delete physicsWorld;
}

PHYSICS_PLUGIN_EXPORT void CP_StepWorld(CPWorldHandle world, float deltaTime)
{
    auto* physicsWorld = reinterpret_cast<PhysicsWorld*>(world);
    if (!physicsWorld)
        return;

    physicsWorld->Step(deltaTime);
}

PHYSICS_PLUGIN_EXPORT CPBodyHandle CP_CreateBody(CPWorldHandle world, const CPBodyDesc* desc)
{
    auto* physicsWorld = reinterpret_cast<PhysicsWorld*>(world);
    if (!physicsWorld || !desc)
        return nullptr;

    RigidBody* body = physicsWorld->CreateBody(*desc);
    return reinterpret_cast<CPBodyHandle>(body);
}

PHYSICS_PLUGIN_EXPORT void CP_DestroyBody(CPWorldHandle world, CPBodyHandle body)
{
    auto* physicsWorld = reinterpret_cast<PhysicsWorld*>(world);
    auto* rigidBody = reinterpret_cast<RigidBody*>(body);

    if (!physicsWorld || !rigidBody)
        return;

    physicsWorld->DestroyBody(rigidBody);
}

PHYSICS_PLUGIN_EXPORT void CP_ApplyForce(CPBodyHandle body, CPVec3 force)
{
    auto* rigidBody = reinterpret_cast<RigidBody*>(body);
    if (!rigidBody)
        return;

    rigidBody->ApplyForce(ToInternal(force));
}

PHYSICS_PLUGIN_EXPORT void CP_SetVelocity(CPBodyHandle body, CPVec3 velocity)
{
    auto* rigidBody = reinterpret_cast<RigidBody*>(body);
    if (!rigidBody)
        return;

    rigidBody->velocity = ToInternal(velocity);
}

PHYSICS_PLUGIN_EXPORT CPVec3 CP_GetVelocity(CPBodyHandle body)
{
    auto* rigidBody = reinterpret_cast<RigidBody*>(body);
    if (!rigidBody)
        return {0.0f, 0.0f, 0.0f};

    return ToExternal(rigidBody->velocity);
}

PHYSICS_PLUGIN_EXPORT CPTransform CP_GetTransform(CPBodyHandle body)
{
    auto* rigidBody = reinterpret_cast<RigidBody*>(body);
    if (!rigidBody)
    {
        CPTransform t{};
        t.position = {0.0f, 0.0f, 0.0f};
        t.rotationEuler = {0.0f, 0.0f, 0.0f};
        return t;
    }

    return ToExternal(rigidBody->transform);
}

PHYSICS_PLUGIN_EXPORT void CP_SetTransform(CPBodyHandle body, CPTransform transform)
{
    auto* rigidBody = reinterpret_cast<RigidBody*>(body);
    if (!rigidBody)
        return;

    rigidBody->transform = ToInternal(transform);
}
