# 9. Physics world implementation

## `Source/CustomPhysicsPlugin/Private/PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"

UPhysicsWorld::UPhysicsWorld()
{
    Gravity = FVector(0.0f, 0.0f, -980.0f);
}

int32 UPhysicsWorld::RegisterBody(const FSimplePhysicsBody& Body)
{
    FSimplePhysicsBody Copy = Body;
    Copy.BodyId = Bodies.Num();
    Bodies.Add(Copy);
    return Copy.BodyId;
}

void UPhysicsWorld::RemoveBody(int32 BodyId)
{
    if (!Bodies.IsValidIndex(BodyId))
    {
        return;
    }

    Bodies[BodyId].bSimulate = false;
}

void UPhysicsWorld::ApplyForce(int32 BodyId, FVector Force)
{
    if (!Bodies.IsValidIndex(BodyId))
    {
        return;
    }

    Bodies[BodyId].AccumulatedForce += Force;
}

bool UPhysicsWorld::GetBody(int32 BodyId, FSimplePhysicsBody& OutBody) const
{
    if (!Bodies.IsValidIndex(BodyId))
    {
        return false;
    }

    OutBody = Bodies[BodyId];
    return true;
}

void UPhysicsWorld::SetGravity(FVector InGravity)
{
    Gravity = InGravity;
}

void UPhysicsWorld::StepSimulation(float DeltaTime)
{
    for (FSimplePhysicsBody& Body : Bodies)
    {
        if (!Body.bSimulate || Body.Mass <= KINDA_SMALL_NUMBER)
        {
            continue;
        }

        Integrate(Body, DeltaTime);
        SolvePlaneCollision(Body);
    }
}

void UPhysicsWorld::Integrate(FSimplePhysicsBody& Body, float DeltaTime)
{
    const FVector Acceleration = Gravity + (Body.AccumulatedForce / Body.Mass);
    Body.Velocity += Acceleration * DeltaTime;
    Body.Position += Body.Velocity * DeltaTime;
    Body.AccumulatedForce = FVector::ZeroVector;
}

void UPhysicsWorld::SolvePlaneCollision(FSimplePhysicsBody& Body)
{
    const float GroundPlaneZ = 0.0f;
    const float MinZ = GroundPlaneZ + Body.Radius;

    if (Body.Position.Z < MinZ)
    {
        Body.Position.Z = MinZ;

        if (Body.Velocity.Z < 0.0f)
        {
            Body.Velocity.Z = -Body.Velocity.Z * Body.Restitution;
        }
    }
}
