# 11. Engine-facing body component implementation

## `Source/CustomPhysicsPlugin/Private/PhysicsBodyComponent.cpp`

```cpp
#include "PhysicsBodyComponent.h"
#include "GameFramework/Actor.h"
#include "Engine/World.h"

UPhysicsBodyComponent::UPhysicsBodyComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UPhysicsBodyComponent::BeginPlay()
{
    Super::BeginPlay();

    UWorld* World = GetWorld();
    if (!World)
    {
        return;
    }

    PhysicsWorld = GetOrCreatePhysicsWorld(World);
    if (!PhysicsWorld)
    {
        return;
    }

    FSimplePhysicsBody Body;
    Body.Position = GetOwner()->GetActorLocation();
    Body.Velocity = FVector::ZeroVector;
    Body.Mass = Mass;
    Body.Radius = Radius;
    Body.Restitution = Restitution;
    Body.bSimulate = bSimulate;

    BodyId = PhysicsWorld->RegisterBody(Body);
}

void UPhysicsBodyComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (PhysicsWorld && BodyId != INDEX_NONE)
    {
        PhysicsWorld->RemoveBody(BodyId);
    }

    Super::EndPlay(EndPlayReason);
}

void UPhysicsBodyComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!PhysicsWorld || BodyId == INDEX_NONE)
    {
        return;
    }

    PhysicsWorld->StepSimulation(DeltaTime);

    FSimplePhysicsBody Body;
    if (PhysicsWorld->GetBody(BodyId, Body))
    {
        GetOwner()->SetActorLocation(Body.Position);
    }
}

void UPhysicsBodyComponent::AddForce(FVector Force)
{
    if (PhysicsWorld && BodyId != INDEX_NONE)
    {
        PhysicsWorld->ApplyForce(BodyId, Force);
    }
}

UPhysicsWorld* UPhysicsBodyComponent::GetOrCreatePhysicsWorld(UWorld* World)
{
    static UPhysicsWorld* SingletonWorld = nullptr;

    if (!SingletonWorld)
    {
        SingletonWorld = NewObject<UPhysicsWorld>(World, UPhysicsWorld::StaticClass());
        SingletonWorld->AddToRoot();
    }

    return SingletonWorld;
}
```

