#include "CustomPhysicsBPLibrary.h"
#include "Components/PrimitiveComponent.h"

void UCustomPhysicsBPLibrary::ApplyCustomGravity(
    UPrimitiveComponent* Component,
    FVector Gravity,
    float DeltaTime)
{
    if (!Component)
    {
        return;
    }

    if (!Component->IsSimulatingPhysics())
    {
        return;
    }

    const FVector DeltaVelocity = Gravity * DeltaTime;

    Component->SetPhysicsLinearVelocity(
        Component->GetPhysicsLinearVelocity() + DeltaVelocity
    );
}
```

