# 6) Physics component implementation

## `Source/SimplePhysicsPlugin/Private/SimplePhysicsComponent.cpp`

```cpp
#include "SimplePhysicsComponent.h"
#include "GameFramework/Actor.h"

USimplePhysicsComponent::USimplePhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void USimplePhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void USimplePhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bSimulate)
    {
        return;
    }

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    FVector Position = Owner->GetActorLocation();

    // Integrate velocity
    Velocity += Gravity * DeltaTime;

    // Integrate position
    Position += Velocity * DeltaTime;

    // Simple collision against ground plane Z=0
    if (Position.Z < 0.0f)
    {
        Position.Z = 0.0f;

        if (Velocity.Z < 0.0f)
        {
            Velocity.Z = -Velocity.Z * Bounciness;
        }
    }

    Owner->SetActorLocation(Position);
}
```

