## 6) Custom physics component implementation

### `Source/MinimalPhysicsPlugin/Private/MinimalPhysicsComponent.cpp`

```cpp
#include "MinimalPhysicsComponent.h"
#include "GameFramework/Actor.h"

UMinimalPhysicsComponent::UMinimalPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UMinimalPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UMinimalPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bSimulate)
    {
        return;
    }

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    // Integrate velocity
    Velocity += Gravity * DeltaTime;

    // Apply simple damping
    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    Velocity *= DampingFactor;

    // Integrate position
    FVector NewLocation = Owner->GetActorLocation() + Velocity * DeltaTime;

    // Very simple floor collision
    if (NewLocation.Z < FloorZ)
    {
        NewLocation.Z = FloorZ;

        if (Velocity.Z < 0.0f)
        {
            Velocity.Z = -Velocity.Z * Bounce;
        }
    }

    Owner->SetActorLocation(NewLocation);
}
```

