#include <cmath>
#include <iostream>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& r) const { return Vec3(x + r.x, y + r.y, z + r.z); }
    Vec3 operator-(const Vec3& r) const { return Vec3(x - r.x, y - r.y, z - r.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
    Vec3& operator-=(const Vec3& r) { x -= r.x; y -= r.y; z -= r.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& r) const { return x * r.x + y * r.y + z * r.z; }

    Vec3 cross(const Vec3& r) const {
        return Vec3(
            y * r.z - z * r.y,
            z * r.x - x * r.z,
            x * r.y - y * r.x
        );
    }

    float length() const { return std::sqrt(dot(*this)); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec3();
        return *this / len;
    }
};

struct Mat3 {
    float m[3][3];

    static Mat3 identity() {
        Mat3 r{};
        r.m[0][0] = 1; r.m[0][1] = 0; r.m[0][2] = 0;
        r.m[1][0] = 0; r.m[1][1] = 1; r.m[1][2] = 0;
        r.m[2][0] = 0; r.m[2][1] = 0; r.m[2][2] = 1;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0] * v.x + m[0][1] * v.y + m[0][2] * v.z,
            m[1][0] * v.x + m[1][1] * v.y + m[1][2] * v.z,
            m[2][0] * v.x + m[2][1] * v.y + m[2][2] * v.z
        );
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator+(const Quat& r) const {
        return Quat(w + r.w, x + r.x, y + r.y, z + r.z);
    }

    Quat operator*(float s) const {
        return Quat(w * s, x * s, y * s, z * s);
    }

    Quat operator*(const Quat& r) const {
        return Quat(
            w * r.w - x * r.x - y * r.y - z * r.z,
            w * r.x + x * r.w + y * r.z - z * r.y,
            w * r.y - x * r.z + y * r.w + z * r.x,
            w * r.z + x * r.y - y * r.x + z * r.w
        );
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-6f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    Mat3 toMat3() const {
        Mat3 r{};
        float xx = x * x, yy = y * y, zz = z * z;
        float xy = x * y, xz = x * z, yz = y * z;
        float wx = w * x, wy = w * y, wz = w * z;

        r.m[0][0] = 1.0f - 2.0f * (yy + zz);
        r.m[0][1] = 2.0f * (xy - wz);
        r.m[0][2] = 2.0f * (xz + wy);

        r.m[1][0] = 2.0f * (xy + wz);
        r.m[1][1] = 1.0f - 2.0f * (xx + zz);
        r.m[1][2] = 2.0f * (yz - wx);

        r.m[2][0] = 2.0f * (xz - wy);
        r.m[2][1] = 2.0f * (yz + wx);
        r.m[2][2] = 1.0f - 2.0f * (xx + yy);
        return r;
    }
};

struct RigidBody {
    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float radius = 0.5f;

    Vec3 position;
    Vec3 velocity;
    Vec3 force;

    Quat orientation;
    Vec3 angularVelocity;
    Vec3 torque;

    float restitution = 0.5f;
    float linearDamping = 0.999f;
    float angularDamping = 0.995f;

    void integrateForces(float dt, const Vec3& gravity) {
        if (invMass == 0.0f) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void integrateVelocity(float dt) {
        if (invMass == 0.0f) return;

        position += velocity * dt;

        Quat omega(0, angularVelocity.x, angularVelocity.y, angularVelocity.z);
        Quat dq = omega * orientation;
        orientation = orientation + dq * (0.5f * dt);
        orientation.normalize();

        velocity *= linearDamping;
        angularVelocity *= angularDamping;

        force = Vec3(0, 0, 0);
        torque = Vec3(0, 0, 0);
    }
};

void resolveGroundCollision(RigidBody& body, float groundY = 0.0f) {
    float penetration = (groundY + body.radius) - body.position.y;
    if (penetration > 0.0f) {
        body.position.y += penetration;

        Vec3 normal(0, 1, 0);
        float vn = body.velocity.dot(normal);

        if (vn < 0.0f) {
            float j = -(1.0f + body.restitution) * vn;
            j /= body.invMass;

            Vec3 impulse = normal * j;
            body.velocity += impulse * body.invMass;
        }

        body.velocity.x *= 0.98f;
        body.velocity.z *= 0.98f;
        body.angularVelocity *= 0.98f;
    }
}

int main() {
    RigidBody body;
    body.mass = 2.0f;
    body.invMass = 1.0f / body.mass;
    body.inertia = 0.4f * body.mass * body.radius * body.radius; // sphere approximation
    body.invInertia = 1.0f / body.inertia;

    body.position = Vec3(0.0f, 8.0f, 0.0f);
    body.velocity = Vec3(2.0f, 0.0f, 0.0f);
    body.angularVelocity = Vec3(0.0f, 0.0f, 4.0f);

    Vec3 gravity(0.0f, -9.81f, 0.0f);

    constexpr float fixedDt = 1.0f / 120.0f;
    constexpr float maxFrameTime = 0.25f;

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();
    float accumulator = 0.0f;

    double simTime = 0.0;
    const double totalRunTime = 5.0;

    while (simTime < totalRunTime) {
        auto current = clock::now();
        std::chrono::duration<float> elapsed = current - previous;
        previous = current;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            body.integrateForces(fixedDt, gravity);
            body.integrateVelocity(fixedDt);
            resolveGroundCollision(body);

            accumulator -= fixedDt;
            simTime += fixedDt;
        }

        std::cout
            << "t=" << simTime
            << " pos=(" << body.position.x << ", " << body.position.y << ", " << body.position.z << ")"
            << " vel=(" << body.velocity.x << ", " << body.velocity.y << ", " << body.velocity.z << ")"
            << " angVel=(" << body.angularVelocity.x << ", " << body.angularVelocity.y << ", " << body.angularVelocity.z << ")"
            << "\n";

        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
