```cpp
#include <SFML/Graphics.hpp>
#include <cmath>
#include <vector>
#include <algorithm>

static constexpr float PI = 3.14159265359f;

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator-=(const Vec2& other) { x -= other.x; y -= other.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

static float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

static Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len < 1e-6f) return Vec2(0, 0);
    return v / len;
}

static float cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

static Vec2 cross(float s, const Vec2& v) {
    return Vec2(-s * v.y, s * v.x);
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float angle = 0.0f;
    float angularVelocity = 0.0f;
    float torque = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float width = 50.0f;
    float height = 30.0f;

    float restitution = 0.4f;
    float friction = 0.8f;

    bool isStatic = false;

    void setMass(float m) {
        mass = m;
        if (mass <= 0.0f || isStatic) {
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            invMass = 1.0f / mass;
            inertia = (mass * (width * width + height * height)) / 12.0f;
            invInertia = 1.0f / inertia;
        }
    }

    void applyForce(const Vec2& f) {
        if (!isStatic) force += f;
    }

    void applyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += invInertia * cross(contactVector, impulse);
    }

    void integrateForces(float dt, const Vec2& gravity) {
        if (isStatic) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void integrateVelocity(float dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;
    }

    void clearAccumulators() {
        force = Vec2(0, 0);
        torque = 0.0f;
    }

    std::vector<Vec2> getVertices() const {
        float c = std::cos(angle);
        float s = std::sin(angle);

        Vec2 half(width * 0.5f, height * 0.5f);

        std::vector<Vec2> local = {
            Vec2(-half.x, -half.y),
            Vec2( half.x, -half.y),
            Vec2( half.x,  half.y),
            Vec2(-half.x,  half.y)
        };

        std::vector<Vec2> world;
        world.reserve(4);

        for (const auto& p : local) {
            Vec2 rotated(
                p.x * c - p.y * s,
                p.x * s + p.y * c
            );
            world.push_back(position + rotated);
        }

        return world;
    }
};

struct Contact {
    Vec2 point;
    Vec2 normal;
    float penetration = 0.0f;
    bool hit = false;
};

static Contact collideWithGround(const RigidBody& body, float groundY) {
    Contact contact;
    auto vertices = body.getVertices();

    float deepest = -1e9f;
    Vec2 contactPoint;

    for (const auto& v : vertices) {
        float penetration = v.y - groundY;
        if (penetration > deepest) {
            deepest = penetration;
            contactPoint = v;
        }
    }

    if (deepest > 0.0f) {
        contact.hit = true;
        contact.penetration = deepest;
        contact.normal = Vec2(0.0f, -1.0f);
        contact.point = contactPoint;
    }

    return contact;
}

static void resolveGroundCollision(RigidBody& body, const Contact& c) {
    if (!c.hit || body.isStatic) return;

    Vec2 r = c.point - body.position;
    Vec2 contactVel = body.velocity + cross(body.angularVelocity, r);

    float velAlongNormal = dot(contactVel, c.normal);

    if (velAlongNormal > 0.0f) return;

    float e = body.restitution;

    float rnCrossN = cross(r, c.normal);
    float denom = body.invMass + (rnCrossN * rnCrossN) * body.invInertia;

    float j = -(1.0f + e) * velAlongNormal;
    j /= denom;

    Vec2 impulse = c.normal * j;
    body.applyImpulse(impulse, r);

    Vec2 tangent = contactVel - c.normal * dot(contactVel, c.normal);
    if (length(tangent) > 1e-6f) {
        tangent = normalize(tangent);

        float rtCrossT = cross(r, tangent);
        float frictionDenom = body.invMass + (rtCrossT * rtCrossT) * body.invInertia;

        float jt = -dot(contactVel, tangent);
        jt /= frictionDenom;

        float mu = body.friction;
        jt = std::clamp(jt, -j * mu, j * mu);

        Vec2 frictionImpulse = tangent * jt;
        body.applyImpulse(frictionImpulse, r);
    }

    const float percent = 0.8f;
    const float slop = 0.01f;
    float correctionMag = std::max(c.penetration - slop, 0.0f) * percent;
    body.position += c.normal * (-correctionMag);
}

int main() {
    sf::RenderWindow window(sf::VideoMode(1000, 700), "Rigid Body Simulation");
    window.setFramerateLimit(144);

    const float fixedDt = 1.0f / 120.0f;
    const float maxFrameTime = 0.25f;
    float accumulator = 0.0f;

    sf::Clock clock;

    const Vec2 gravity(0.0f, 980.0f);
    const float groundY = 620.0f;

    std::vector<RigidBody> bodies;

    {
        RigidBody b;
        b.position = Vec2(300.0f, 120.0f);
        b.velocity = Vec2(80.0f, 0.0f);
        b.angle = 0.3f;
        b.angularVelocity = 1.4f;
        b.width = 90.0f;
        b.height = 40.0f;
        b.restitution = 0.35f;
        b.friction = 0.7f;
        b.setMass(3.0f);
        bodies.push_back(b);
    }

    {
        RigidBody b;
        b.position = Vec2(520.0f, 80.0f);
        b.velocity = Vec2(-30.0f, 0.0f);
        b.angle = -0.2f;
        b.angularVelocity = -2.1f;
        b.width = 60.0f;
        b.height = 60.0f;
        b.restitution = 0.25f;
        b.friction = 0.9f;
        b.setMass(4.0f);
        bodies.push_back(b);
    }

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }
        }

        float frameTime = clock.restart().asSeconds();
        frameTime = std::min(frameTime, maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            for (auto& body : bodies) {
                body.integrateForces(fixedDt, gravity);
            }

            for (auto& body : bodies) {
                body.integrateVelocity(fixedDt);
            }

            for (auto& body : bodies) {
                Contact c = collideWithGround(body, groundY);
                if (c.hit) {
                    resolveGroundCollision(body, c);
                }
                body.clearAccumulators();
            }

            accumulator -= fixedDt;
        }

        window.clear(sf::Color(30, 30, 35));

        sf::RectangleShape ground(sf::Vector2f(1000.0f, 5.0f));
        ground.setPosition(0.0f, groundY);
        ground.setFillColor(sf::Color::White);
        window.draw(ground);

        for (const auto& body : bodies) {
            sf::RectangleShape rect(sf::Vector2f(body.width, body.height));
            rect.setOrigin(body.width * 0.5f, body.height * 0.5f);
            rect.setPosition(body.position.x, body.position.y);
            rect.setRotation(body.angle * 180.0f / PI);
            rect.setFillColor(sf::Color(100, 180, 250));
            rect.setOutlineThickness(1.5f);
            rect.setOutlineColor(sf::Color::Black);
            window.draw(rect);
        }

        window.display();
    }

    return 0;
}
