```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& other) {
        x += other.x;
        y += other.y;
        return *this;
    }

    Vec2& operator*=(float s) {
        x *= s;
        y *= s;
        return *this;
    }
};

static inline float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float angle = 0.0f;
    float angularVelocity = 0.0f;
    float torque = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float radius = 0.5f;
    float restitution = 0.7f;

    bool isStatic = false;

    RigidBody(Vec2 pos, float m, float r, bool isStatic_ = false)
        : position(pos), mass(m), radius(r), isStatic(isStatic_) {
        if (isStatic || m <= 0.0f) {
            mass = 0.0f;
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
        } else {
            invMass = 1.0f / mass;
            inertia = 0.5f * mass * radius * radius; // solid disk
            invInertia = 1.0f / inertia;
        }
    }

    void applyForce(const Vec2& f) {
        if (!isStatic) force += f;
    }

    void applyTorque(float t) {
        if (!isStatic) torque += t;
    }

    void integrate(float dt) {
        if (isStatic) return;

        Vec2 acceleration = force * invMass;
        float angularAcceleration = torque * invInertia;

        velocity += acceleration * dt;
        angularVelocity += angularAcceleration * dt;

        position += velocity * dt;
        angle += angularVelocity * dt;

        force = {0.0f, 0.0f};
        torque = 0.0f;
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0f, -9.81f};
    float groundY = 0.0f;

    void step(float dt) {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        for (auto& body : bodies) {
            body.integrate(dt);
            solveGroundCollision(body);
        }
    }

private:
    void solveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        float minY = body.position.y - body.radius;
        if (minY < groundY) {
            body.position.y = groundY + body.radius;

            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;

                float friction = 0.98f;
                body.velocity.x *= friction;
                body.angularVelocity *= friction;
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec2{0.0f, 10.0f}, 1.0f, 0.5f);
    world.bodies.emplace_back(Vec2{2.0f, 15.0f}, 2.0f, 0.7f);

    world.bodies[0].velocity = {1.5f, 0.0f};
    world.bodies[0].angularVelocity = 2.0f;

    world.bodies[1].velocity = {-0.5f, 0.0f};
    world.bodies[1].angularVelocity = -1.0f;

    using clock = std::chrono::high_resolution_clock;
    const float fixedDt = 1.0f / 60.0f;
    const float maxFrameTime = 0.25f;

    auto previous = clock::now();
    float accumulator = 0.0f;

    const int targetFPS = 60;
    const auto targetFrameDuration = std::chrono::microseconds(1000000 / targetFPS);

    for (int frame = 0; frame < 600; ++frame) {
        auto frameStart = clock::now();
        std::chrono::duration<float> elapsed = frameStart - previous;
        previous = frameStart;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout
                << " Body " << i
                << " Pos(" << b.position.x << ", " << b.position.y << ")"
                << " Vel(" << b.velocity.x << ", " << b.velocity.y << ")"
                << " Angle(" << b.angle << ")"
                << " AngVel(" << b.angularVelocity << ")\n";
        }
        std::cout << "----\n";

        auto frameEnd = clock::now();
        auto frameDuration = std::chrono::duration_cast<std::chrono::microseconds>(frameEnd - frameStart);

        if (frameDuration < targetFrameDuration) {
            std::this_thread::sleep_for(targetFrameDuration - frameDuration);
        }
    }

    return 0;
}
