#include <cmath>
#include <chrono>
#include <iostream>
#include <thread>
#include <vector>
#include <algorithm>

struct Vec2 {
    double x = 0.0;
    double y = 0.0;

    Vec2() = default;
    Vec2(double x_, double y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(double s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(double s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& other) {
        x += other.x;
        y += other.y;
        return *this;
    }

    Vec2& operator-=(const Vec2& other) {
        x -= other.x;
        y -= other.y;
        return *this;
    }

    Vec2& operator*=(double s) {
        x *= s;
        y *= s;
        return *this;
    }
};

static inline double dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline double length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec2 normalize(const Vec2& v) {
    double len = length(v);
    if (len < 1e-8) return Vec2(0, 0);
    return v / len;
}

// 2D cross products
static inline double cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

static inline Vec2 cross(const Vec2& v, double s) {
    return Vec2(s * v.y, -s * v.x);
}

static inline Vec2 cross(double s, const Vec2& v) {
    return Vec2(-s * v.y, s * v.x);
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    double angle = 0.0;
    double angularVelocity = 0.0;
    double torque = 0.0;

    double mass = 1.0;
    double invMass = 1.0;

    double inertia = 1.0;
    double invInertia = 1.0;

    double radius = 0.5;       // simple circle collider
    double restitution = 0.6;  // bounciness
    double linearDamping = 0.999;
    double angularDamping = 0.999;

    bool isStatic = false;

    void applyForce(const Vec2& f) {
        if (isStatic) return;
        force += f;
    }

    void applyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += invInertia * cross(contactVector, impulse);
    }

    void integrateForces(double dt, const Vec2& gravity) {
        if (isStatic) return;
        velocity += (gravity + force * invMass) * dt;
        angularVelocity += torque * invInertia * dt;
    }

    void integrateVelocity(double dt) {
        if (isStatic) return;
        position += velocity * dt;
        angle += angularVelocity * dt;

        velocity *= linearDamping;
        angularVelocity *= angularDamping;

        force = Vec2(0, 0);
        torque = 0.0;
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec2 gravity = Vec2(0.0, -9.81);
    double groundY = 0.0;

    void step(double dt) {
        for (auto& body : bodies) {
            body.integrateForces(dt, gravity);
        }

        for (auto& body : bodies) {
            body.integrateVelocity(dt);
            solveGroundCollision(body);
        }
    }

    void solveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        double penetration = groundY - (body.position.y - body.radius);
        if (penetration > 0.0) {
            // Positional correction
            body.position.y += penetration;

            Vec2 normal(0.0, 1.0);
            Vec2 contactPoint(body.position.x, body.position.y - body.radius);
            Vec2 r = contactPoint - body.position;

            Vec2 contactVelocity = body.velocity + cross(body.angularVelocity, r);
            double velAlongNormal = dot(contactVelocity, normal);

            if (velAlongNormal < 0.0) {
                double e = body.restitution;

                double rCrossN = cross(r, normal);
                double denom = body.invMass + (rCrossN * rCrossN) * body.invInertia;

                double j = -(1.0 + e) * velAlongNormal;
                j /= denom;

                Vec2 impulse = normal * j;
                body.applyImpulse(impulse, r);

                // Simple friction
                contactVelocity = body.velocity + cross(body.angularVelocity, r);
                Vec2 tangent = contactVelocity - normal * dot(contactVelocity, normal);
                tangent = normalize(tangent);

                double jt = -dot(contactVelocity, tangent);
                jt /= denom;

                double mu = 0.4;
                Vec2 frictionImpulse;
                if (std::abs(jt) < j * mu) {
                    frictionImpulse = tangent * jt;
                } else {
                    frictionImpulse = tangent * (-j * mu);
                }

                body.applyImpulse(frictionImpulse, r);
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    RigidBody ball;
    ball.position = Vec2(0.0, 8.0);
    ball.velocity = Vec2(3.0, 0.0);
    ball.mass = 2.0;
    ball.invMass = 1.0 / ball.mass;
    ball.radius = 0.5;
    ball.restitution = 0.75;

    // Moment of inertia for a solid disk in 2D: 1/2 * m * r^2
    ball.inertia = 0.5 * ball.mass * ball.radius * ball.radius;
    ball.invInertia = 1.0 / ball.inertia;
    ball.angularVelocity = 4.0;

    world.bodies.push_back(ball);

    using clock = std::chrono::steady_clock;
    auto previous = clock::now();

    const double fixedDt = 1.0 / 120.0;   // simulation at 120 Hz
    const double maxFrameTime = 0.25;     // clamp huge frame stalls
    double accumulator = 0.0;

    const int targetRenderFPS = 60;
    const auto renderFrameDuration = std::chrono::milliseconds(1000 / targetRenderFPS);

    double simTime = 0.0;
    int frameCount = 0;

    while (simTime < 10.0) {
        auto current = clock::now();
        std::chrono::duration<double> elapsed = current - previous;
        previous = current;

        double frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            simTime += fixedDt;
        }

        const auto& b = world.bodies[0];
        std::cout
            << "frame=" << frameCount++
            << " time=" << simTime
            << " pos=(" << b.position.x << ", " << b.position.y << ")"
            << " vel=(" << b.velocity.x << ", " << b.velocity.y << ")"
            << " angle=" << b.angle
            << " angVel=" << b.angularVelocity
            << "\n";

        std::this_thread::sleep_for(renderFrameDuration);
    }

    return 0;
}
```

### Why this structure works well for real-time simulation

- **Fixed timestep** (`fixedDt`) keeps physics stable and deterministic relative to variable render timing.
- **Accumulator loop** allows rendering at one rate and simulation at another.
- **Frame-time clamp** prevents giant frame stalls from causing too many catch-up updates.
- **Impulse-based collision response** is standard for simple rigid-body dynamics.

