## <language>C++</language> initial implementation

```cpp
#include <cmath>
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <algorithm>

constexpr float FIXED_DT = 1.0f / 120.0f;   // simulation step
constexpr float MAX_FRAME_TIME = 0.25f;     // avoid spiral of death
constexpr int MAX_SUBSTEPS = 8;
constexpr float GRAVITY_Y = -9.81f;

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& b) const { return Vec3(x + b.x, y + b.y, z + b.z); }
    Vec3 operator-(const Vec3& b) const { return Vec3(x - b.x, y - b.y, z - b.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& b) { x += b.x; y += b.y; z += b.z; return *this; }
    Vec3& operator-=(const Vec3& b) { x -= b.x; y -= b.y; z -= b.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& b) const { return x * b.x + y * b.y + z * b.z; }

    Vec3 cross(const Vec3& b) const {
        return Vec3(
            y * b.z - z * b.y,
            z * b.x - x * b.z,
            x * b.y - y * b.x
        );
    }

    float length() const { return std::sqrt(dot(*this)); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec3(0, 0, 0);
        return *this / len;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;

    Vec3 angularVelocity;
    Vec3 torque;

    float mass;
    float invMass;
    float radius;

    float restitution;
    float linearDamping;
    float angularDamping;

    bool isStatic;

    RigidBody(Vec3 pos, float m, float r, bool makeStatic = false)
        : position(pos),
          velocity(0, 0, 0),
          force(0, 0, 0),
          angularVelocity(0, 0, 0),
          torque(0, 0, 0),
          mass(m),
          invMass(makeStatic || m <= 0.0f ? 0.0f : 1.0f / m),
          radius(r),
          restitution(0.5f),
          linearDamping(0.999f),
          angularDamping(0.999f),
          isStatic(makeStatic) {}

    void applyForce(const Vec3& f) {
        if (!isStatic) force += f;
    }

    void applyImpulse(const Vec3& impulse) {
        if (!isStatic) velocity += impulse * invMass;
    }

    void integrate(float dt) {
        if (isStatic) return;

        Vec3 acceleration = force * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        velocity *= std::pow(linearDamping, dt * 60.0f);
        angularVelocity *= std::pow(angularDamping, dt * 60.0f);

        force = Vec3(0, 0, 0);
        torque = Vec3(0, 0, 0);
    }
};

struct Contact {
    int a;
    int b;
    Vec3 normal;
    float penetration;
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;

    void step(float dt) {
        applyGlobalForces();
        integrateBodies(dt);
        auto contacts = detectCollisions();
        resolveCollisions(contacts);
        solveGroundContacts();
    }

private:
    void applyGlobalForces() {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(Vec3(0.0f, body.mass * GRAVITY_Y, 0.0f));
            }
        }
    }

    void integrateBodies(float dt) {
        for (auto& body : bodies) {
            body.integrate(dt);
        }
    }

    std::vector<Contact> detectCollisions() {
        std::vector<Contact> contacts;
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                Vec3 delta = b.position - a.position;
                float dist = delta.length();
                float minDist = a.radius + b.radius;

                if (dist < minDist) {
                    Vec3 normal = (dist > 1e-6f) ? delta / dist : Vec3(1, 0, 0);
                    contacts.push_back({static_cast<int>(i), static_cast<int>(j), normal, minDist - dist});
                }
            }
        }
        return contacts;
    }

    void resolveCollisions(const std::vector<Contact>& contacts) {
        for (const auto& c : contacts) {
            RigidBody& a = bodies[c.a];
            RigidBody& b = bodies[c.b];

            float invMassSum = a.invMass + b.invMass;
            if (invMassSum <= 0.0f) continue;

            Vec3 relativeVelocity = b.velocity - a.velocity;
            float velAlongNormal = relativeVelocity.dot(c.normal);

            if (velAlongNormal > 0.0f) continue;

            float e = std::min(a.restitution, b.restitution);
            float j = -(1.0f + e) * velAlongNormal;
            j /= invMassSum;

            Vec3 impulse = c.normal * j;
            a.applyImpulse(impulse * -1.0f);
            b.applyImpulse(impulse);

            // Positional correction
            constexpr float percent = 0.8f;
            constexpr float slop = 0.001f;
            float correctionMag = std::max(c.penetration - slop, 0.0f) / invMassSum * percent;
            Vec3 correction = c.normal * correctionMag;

            if (!a.isStatic) a.position -= correction * a.invMass;
            if (!b.isStatic) b.position += correction * b.invMass;
        }
    }

    void solveGroundContacts() {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float groundY = 0.0f;
            float minY = body.position.y - body.radius;

            if (minY < groundY) {
                body.position.y = groundY + body.radius;

                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }

                // crude friction
                body.velocity.x *= 0.98f;
                body.velocity.z *= 0.98f;
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    world.bodies.emplace_back(Vec3(0, 8, 0), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(0.8f, 12, 0), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(-1.2f, 16, 0), 2.0f, 0.7f);

    world.bodies[0].velocity = Vec3(2.0f, 0.0f, 0.0f);
    world.bodies[1].velocity = Vec3(-1.0f, 0.0f, 0.0f);

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();
    float accumulator = 0.0f;

    int frameCount = 0;
    while (frameCount < 600) { // run ~10 seconds at 60 FPS display
        auto current = clock::now();
        std::chrono::duration<float> elapsed = current - previous;
        previous = current;

        float frameTime = std::min(elapsed.count(), MAX_FRAME_TIME);
        accumulator += frameTime;

        int substeps = 0;
        while (accumulator >= FIXED_DT && substeps < MAX_SUBSTEPS) {
            world.step(FIXED_DT);
            accumulator -= FIXED_DT;
            substeps++;
        }

        // render/debug output at ~60 FPS
        std::cout << "Frame " << frameCount << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")"
                      << "\n";
        }

        std::this_thread::sleep_for(std::chrono::milliseconds(16));
        frameCount++;
    }

    return 0;
}
