#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& other) {
        x += other.x;
        y += other.y;
        return *this;
    }

    Vec2& operator-=(const Vec2& other) {
        x -= other.x;
        y -= other.y;
        return *this;
    }

    Vec2& operator*=(float s) {
        x *= s;
        y *= s;
        return *this;
    }
};

static float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

static Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len < 1e-6f) return Vec2(0.0f, 0.0f);
    return v / len;
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float radius = 0.5f;
    float mass = 1.0f;
    float invMass = 1.0f;
    float restitution = 0.8f;

    bool isStatic = false;

    RigidBody(Vec2 pos, Vec2 vel, float r, float m, float rest, bool staticBody = false)
        : position(pos), velocity(vel), radius(r), mass(m), restitution(rest), isStatic(staticBody) {
        invMass = (isStatic || mass <= 0.0f) ? 0.0f : 1.0f / mass;
    }
};

struct World {
    std::vector<RigidBody> bodies;
    Vec2 gravity = Vec2(0.0f, -9.81f);
    float groundY = 0.0f;

    void applyGravity() {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.force += gravity * body.mass;
            }
        }
    }

    void integrate(float dt) {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            Vec2 acceleration = body.force * body.invMass;
            body.velocity += acceleration * dt;
            body.position += body.velocity * dt;

            body.force = Vec2(0.0f, 0.0f);
        }
    }

    void solveGroundCollisions() {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float minY = body.position.y - body.radius;
            if (minY < groundY) {
                body.position.y = groundY + body.radius;

                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }
            }
        }
    }

    void solveBodyCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                Vec2 delta = b.position - a.position;
                float dist = length(delta);
                float minDist = a.radius + b.radius;

                if (dist >= minDist || dist < 1e-6f) {
                    continue;
                }

                Vec2 normal = delta / dist;
                float penetration = minDist - dist;

                // Positional correction
                const float percent = 0.8f;
                const float slop = 0.01f;
                float denom = a.invMass + b.invMass;
                if (denom > 0.0f) {
                    Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / denom * percent);
                    if (!a.isStatic) a.position -= correction * a.invMass;
                    if (!b.isStatic) b.position += correction * b.invMass;
                }

                // Relative velocity
                Vec2 rv = b.velocity - a.velocity;
                float velAlongNormal = dot(rv, normal);

                if (velAlongNormal > 0.0f) {
                    continue;
                }

                float e = std::min(a.restitution, b.restitution);

                float jImpulse = -(1.0f + e) * velAlongNormal;
                if (denom <= 0.0f) continue;
                jImpulse /= denom;

                Vec2 impulse = normal * jImpulse;

                if (!a.isStatic) a.velocity -= impulse * a.invMass;
                if (!b.isStatic) b.velocity += impulse * b.invMass;
            }
        }
    }

    void step(float dt) {
        applyGravity();
        integrate(dt);
        solveGroundCollisions();
        solveBodyCollisions();
    }
};

static void renderText(const World& world, int frame) {
    std::cout << "Frame " << frame << "\n";
    for (size_t i = 0; i < world.bodies.size(); ++i) {
        const auto& b = world.bodies[i];
        std::cout << " Body " << i
                  << " pos=(" << b.position.x << ", " << b.position.y << ")"
                  << " vel=(" << b.velocity.x << ", " << b.velocity.y << ")\n";
    }
    std::cout << "-------------------------\n";
}

int main() {
    World world;

    world.bodies.emplace_back(Vec2(-1.0f, 8.0f), Vec2(2.0f, 0.0f), 0.5f, 1.0f, 0.8f);
    world.bodies.emplace_back(Vec2(1.0f, 10.0f), Vec2(-1.5f, 0.0f), 0.7f, 2.0f, 0.7f);
    world.bodies.emplace_back(Vec2(0.0f, 14.0f), Vec2(0.5f, -1.0f), 0.6f, 1.5f, 0.6f);

    const float fixedDt = 1.0f / 120.0f; // physics at 120 Hz
    const float maxFrameTime = 0.25f;    // avoid spiral of death
    float accumulator = 0.0f;

    auto previousTime = std::chrono::high_resolution_clock::now();

    int frame = 0;
    while (frame < 600) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        renderText(world, frame);

        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // approx 60 FPS render pacing
        ++frame;
    }

    return 0;
}
