#include <cmath>
#include <iostream>
#include <vector>
#include <algorithm>

static constexpr float FIXED_DT = 1.0f / 60.0f;
static constexpr float GRAVITY = -9.81f;
static constexpr int MAX_STEPS_PER_FRAME = 5;

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const {
        return Vec3(x + other.x, y + other.y, z + other.z);
    }

    Vec3 operator-(const Vec3& other) const {
        return Vec3(x - other.x, y - other.y, z - other.z);
    }

    Vec3 operator*(float s) const {
        return Vec3(x * s, y * s, z * s);
    }

    Vec3 operator/(float s) const {
        return Vec3(x / s, y / s, z / s);
    }

    Vec3& operator+=(const Vec3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }

    Vec3& operator*=(float s) {
        x *= s; y *= s; z *= s;
        return *this;
    }

    float dot(const Vec3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    Vec3 cross(const Vec3& other) const {
        return Vec3(
            y * other.z - z * other.y,
            z * other.x - x * other.z,
            x * other.y - y * other.x
        );
    }

    float length() const {
        return std::sqrt(dot(*this));
    }

    Vec3 normalized() const {
        float len = length();
        if (len <= 1e-6f) return Vec3();
        return *this / len;
    }
};

struct Quaternion {
    float w, x, y, z;

    Quaternion() : w(1), x(0), y(0), z(0) {}
    Quaternion(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quaternion operator*(const Quaternion& q) const {
        return Quaternion(
            w*q.w - x*q.x - y*q.y - z*q.z,
            w*q.x + x*q.w + y*q.z - z*q.y,
            w*q.y - x*q.z + y*q.w + z*q.x,
            w*q.z + x*q.y - y*q.x + z*q.w
        );
    }

    Quaternion operator*(float s) const {
        return Quaternion(w * s, x * s, y * s, z * s);
    }

    Quaternion operator+(const Quaternion& q) const {
        return Quaternion(w + q.w, x + q.x, y + q.y, z + q.z);
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len > 1e-6f) {
            w /= len; x /= len; y /= len; z /= len;
        }
    }

    static Quaternion fromAngularVelocity(const Vec3& omega) {
        return Quaternion(0, omega.x, omega.y, omega.z);
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;

    Quaternion orientation;
    Vec3 angularVelocity;
    Vec3 torque;

    float mass;
    float invMass;

    float radius;
    float restitution;

    bool isStatic;

    RigidBody(const Vec3& pos, float m, float r, bool staticBody = false)
        : position(pos), velocity(), force(),
          orientation(), angularVelocity(), torque(),
          mass(m), invMass((m > 0.0f && !staticBody) ? 1.0f / m : 0.0f),
          radius(r), restitution(0.5f), isStatic(staticBody) {}

    void applyForce(const Vec3& f) {
        if (!isStatic) force += f;
    }

    void integrate(float dt) {
        if (isStatic) return;

        Vec3 acceleration = force * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        Vec3 angularAcceleration = torque * invMass; // simplified inertia
        angularVelocity += angularAcceleration * dt;

        Quaternion omega = Quaternion::fromAngularVelocity(angularVelocity);
        Quaternion dq = omega * orientation;
        orientation = orientation + dq * (0.5f * dt);
        orientation.normalize();

        force = Vec3();
        torque = Vec3();
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, GRAVITY, 0.0f);

    void step(float dt) {
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        for (auto& body : bodies) {
            body.integrate(dt);
            resolveGroundCollision(body);
        }
    }

    void resolveGroundCollision(RigidBody& body) {
        if (body.isStatic) return;

        float groundY = 0.0f;
        float minY = body.position.y - body.radius;

        if (minY < groundY) {
            body.position.y = groundY + body.radius;

            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;

                body.velocity.x *= 0.98f;
                body.velocity.z *= 0.98f;

                if (std::fabs(body.velocity.y) < 0.05f) {
                    body.velocity.y = 0.0f;
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(2.0f, 15.0f, 0.0f), 2.0f, 0.75f);

    float accumulator = 0.0f;
    float frameTime = 1.0f / 144.0f; // pretend render frame time

    for (int frame = 0; frame < 300; ++frame) {
        accumulator += frameTime;

        int steps = 0;
        while (accumulator >= FIXED_DT && steps < MAX_STEPS_PER_FRAME) {
            world.step(FIXED_DT);
            accumulator -= FIXED_DT;
            ++steps;
        }

        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << " Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")"
                      << "\n";
        }
    }

    return 0;
}
