#include <cmath>
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <algorithm>

constexpr float PI = 3.14159265358979323846f;

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& r) const { return Vec3(x + r.x, y + r.y, z + r.z); }
    Vec3 operator-(const Vec3& r) const { return Vec3(x - r.x, y - r.y, z - r.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
    Vec3& operator-=(const Vec3& r) { x -= r.x; y -= r.y; z -= r.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& r) const { return x*r.x + y*r.y + z*r.z; }

    Vec3 cross(const Vec3& r) const {
        return Vec3(
            y*r.z - z*r.y,
            z*r.x - x*r.z,
            x*r.y - y*r.x
        );
    }

    float length() const { return std::sqrt(dot(*this)); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-8f) return Vec3(0,0,0);
        return *this / len;
    }
};

struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator*(const Quat& r) const {
        return Quat(
            w*r.w - x*r.x - y*r.y - z*r.z,
            w*r.x + x*r.w + y*r.z - z*r.y,
            w*r.y - x*r.z + y*r.w + z*r.x,
            w*r.z + x*r.y - y*r.x + z*r.w
        );
    }

    Quat operator*(float s) const {
        return Quat(w*s, x*s, y*s, z*s);
    }

    Quat operator+(const Quat& r) const {
        return Quat(w+r.w, x+r.x, y+r.y, z+r.z);
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-8f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    static Quat fromAngularVelocity(const Vec3& omega) {
        return Quat(0.0f, omega.x, omega.y, omega.z);
    }
};

struct Mat3 {
    float m[3][3];

    static Mat3 identity() {
        Mat3 r{};
        r.m[0][0] = 1; r.m[0][1] = 0; r.m[0][2] = 0;
        r.m[1][0] = 0; r.m[1][1] = 1; r.m[1][2] = 0;
        r.m[2][0] = 0; r.m[2][1] = 0; r.m[2][2] = 1;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    Quat orientation;
    Vec3 angularVelocity;
    Vec3 torqueAccum;

    float mass = 1.0f;
    float invMass = 1.0f;

    float radius = 0.5f;
    float restitution = 0.5f;
    bool isStatic = false;

    // For spheres, inertia tensor is scalar * identity.
    float inertia = 1.0f;
    float invInertia = 1.0f;

    void setMass(float m) {
        mass = m;
        if (m <= 0.0f || isStatic) {
            invMass = 0.0f;
        } else {
            invMass = 1.0f / mass;
        }

        // Solid sphere: I = 2/5 mr^2
        inertia = (2.0f / 5.0f) * mass * radius * radius;
        invInertia = (inertia > 0.0f && !isStatic) ? 1.0f / inertia : 0.0f;
    }

    void applyForce(const Vec3& force) {
        if (!isStatic) forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& worldPoint) {
        if (isStatic) return;
        forceAccum += force;
        Vec3 r = worldPoint - position;
        torqueAccum += r.cross(force);
    }

    void applyImpulse(const Vec3& impulse, const Vec3& contactVector) {
        if (isStatic) return;
        velocity += impulse * invMass;
        angularVelocity += contactVector.cross(impulse) * invInertia;
    }

    void clearAccumulators() {
        forceAccum = Vec3(0,0,0);
        torqueAccum = Vec3(0,0,0);
    }

    void integrate(float dt) {
        if (isStatic || invMass == 0.0f) return;

        // Linear
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        // Angular
        Vec3 angularAcceleration = torqueAccum * invInertia;
        angularVelocity += angularAcceleration * dt;

        Quat omega = Quat::fromAngularVelocity(angularVelocity);
        Quat dq = omega * orientation;
        orientation = orientation + dq * (0.5f * dt);
        orientation.normalize();

        clearAccumulators();
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
    float groundY = 0.0f;

    void step(float dt) {
        applyGlobalForces();
        integrateBodies(dt);
        solveGroundCollisions();
        solveSphereSphereCollisions();
    }

    void applyGlobalForces() {
        for (auto& body : bodies) {
            if (!body.isStatic && body.invMass > 0.0f) {
                body.applyForce(gravity * body.mass);
            }
        }
    }

    void integrateBodies(float dt) {
        for (auto& body : bodies) {
            body.integrate(dt);
        }
    }

    void solveGroundCollisions() {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float minY = body.position.y - body.radius;
            if (minY < groundY) {
                body.position.y = groundY + body.radius;

                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }

                // simple damping
                body.velocity.x *= 0.98f;
                body.velocity.z *= 0.98f;
            }
        }
    }

    void solveSphereSphereCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];
                if (a.isStatic && b.isStatic) continue;

                Vec3 delta = b.position - a.position;
                float dist = delta.length();
                float minDist = a.radius + b.radius;

                if (dist >= minDist || dist < 1e-6f) continue;

                Vec3 normal = delta / dist;
                float penetration = minDist - dist;

                // Positional correction
                float totalInvMass = a.invMass + b.invMass;
                if (totalInvMass > 0.0f) {
                    Vec3 correction = normal * (penetration / totalInvMass);
                    if (!a.isStatic) a.position -= correction * a.invMass;
                    if (!b.isStatic) b.position += correction * b.invMass;
                }

                // Relative velocity
                Vec3 rv = b.velocity - a.velocity;
                float velAlongNormal = rv.dot(normal);

                // Already separating
                if (velAlongNormal > 0.0f) continue;

                float e = std::min(a.restitution, b.restitution);

                float jImpulse = -(1.0f + e) * velAlongNormal;
                if (totalInvMass > 0.0f) jImpulse /= totalInvMass;
                else continue;

                Vec3 impulse = normal * jImpulse;
                if (!a.isStatic) a.velocity -= impulse * a.invMass;
                if (!b.isStatic) b.velocity += impulse * b.invMass;
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    // Static ground could also be represented as a plane, so no body needed here.

    RigidBody b1;
    b1.position = Vec3(0.0f, 5.0f, 0.0f);
    b1.radius = 0.5f;
    b1.restitution = 0.7f;
    b1.setMass(1.0f);

    RigidBody b2;
    b2.position = Vec3(0.6f, 8.0f, 0.0f);
    b2.radius = 0.5f;
    b2.restitution = 0.6f;
    b2.setMass(1.0f);

    world.bodies.push_back(b1);
    world.bodies.push_back(b2);

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();

    const float fixedDt = 1.0f / 120.0f; // physics at 120 Hz
    float accumulator = 0.0f;

    const float targetFrameTime = 1.0f / 60.0f; // render/update budget at 60 FPS

    for (int frame = 0; frame < 600; ++frame) {
        auto current = clock::now();
        std::chrono::duration<float> elapsed = current - previous;
        previous = current;

        float frameTime = elapsed.count();
        frameTime = std::min(frameTime, 0.25f); // avoid spiral of death
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Debug output
        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
        }

        // Frame-rate limiting
        auto frameEnd = clock::now();
        std::chrono::duration<float> workTime = frameEnd - current;
        float sleepTime = targetFrameTime - workTime.count();
        if (sleepTime > 0.0f) {
            std::this_thread::sleep_for(std::chrono::duration<float>(sleepTime));
        }
    }

    return 0;
}
