#include <cmath>
#include <chrono>
#include <iostream>
#include <thread>
#include <vector>
#include <algorithm>

constexpr float PI = 3.14159265358979323846f;

// -----------------------------
// Basic Math Types
// -----------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& v) const { return Vec3(x + v.x, y + v.y, z + v.z); }
    Vec3 operator-(const Vec3& v) const { return Vec3(x - v.x, y - v.y, z - v.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& v) { x += v.x; y += v.y; z += v.z; return *this; }
    Vec3& operator-=(const Vec3& v) { x -= v.x; y -= v.y; z -= v.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

    float dot(const Vec3& v) const { return x * v.x + y * v.y + z * v.z; }

    Vec3 cross(const Vec3& v) const {
        return Vec3(
            y * v.z - z * v.y,
            z * v.x - x * v.z,
            x * v.y - y * v.x
        );
    }

    float length() const { return std::sqrt(dot(*this)); }

    Vec3 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec3();
        return *this / len;
    }
};

inline Vec3 operator*(float s, const Vec3& v) {
    return v * s;
}

// -----------------------------
// Quaternion for orientation
// -----------------------------
struct Quat {
    float w, x, y, z;

    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}

    Quat operator*(const Quat& q) const {
        return Quat(
            w*q.w - x*q.x - y*q.y - z*q.z,
            w*q.x + x*q.w + y*q.z - z*q.y,
            w*q.y - x*q.z + y*q.w + z*q.x,
            w*q.z + x*q.y - y*q.x + z*q.w
        );
    }

    Quat operator*(float s) const {
        return Quat(w * s, x * s, y * s, z * s);
    }

    Quat operator+(const Quat& q) const {
        return Quat(w + q.w, x + q.x, y + q.y, z + q.z);
    }

    void normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len < 1e-6f) {
            w = 1; x = y = z = 0;
            return;
        }
        w /= len; x /= len; y /= len; z /= len;
    }

    static Quat fromAngularVelocity(const Vec3& omega, float dt) {
        float angle = omega.length() * dt;
        if (angle < 1e-6f) return Quat();

        Vec3 axis = omega.normalized();
        float half = angle * 0.5f;
        float s = std::sin(half);

        return Quat(std::cos(half), axis.x * s, axis.y * s, axis.z * s);
    }
};

// -----------------------------
// Simple 3x3 matrix
// -----------------------------
struct Mat3 {
    float m[3][3];

    static Mat3 identity() {
        Mat3 r{};
        r.m[0][0] = 1; r.m[0][1] = 0; r.m[0][2] = 0;
        r.m[1][0] = 0; r.m[1][1] = 1; r.m[1][2] = 0;
        r.m[2][0] = 0; r.m[2][1] = 0; r.m[2][2] = 1;
        return r;
    }

    Vec3 operator*(const Vec3& v) const {
        return Vec3(
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        );
    }
};

// -----------------------------
// Rigid Body
// -----------------------------
struct RigidBody {
    Vec3 position;
    Vec3 velocity;

    Quat orientation;
    Vec3 angularVelocity;

    Vec3 forceAccum;
    Vec3 torqueAccum;

    float mass;
    float invMass;

    float radius; // sphere collision approximation

    float restitution;
    float linearDamping;
    float angularDamping;

    Mat3 inertiaBody;
    Mat3 invInertiaBody;

    bool isStatic;

    RigidBody(float m, float r, const Vec3& pos)
        : position(pos),
          velocity(),
          orientation(),
          angularVelocity(),
          forceAccum(),
          torqueAccum(),
          mass(m),
          invMass(m > 0.0f ? 1.0f / m : 0.0f),
          radius(r),
          restitution(0.5f),
          linearDamping(0.999f),
          angularDamping(0.998f),
          isStatic(m <= 0.0f)
    {
        // Solid sphere inertia tensor: I = 2/5 m r^2
        float I = (2.0f / 5.0f) * mass * radius * radius;
        inertiaBody = Mat3::identity();
        invInertiaBody = Mat3::identity();

        if (!isStatic && I > 1e-6f) {
            inertiaBody.m[0][0] = I;
            inertiaBody.m[1][1] = I;
            inertiaBody.m[2][2] = I;

            invInertiaBody.m[0][0] = 1.0f / I;
            invInertiaBody.m[1][1] = 1.0f / I;
            invInertiaBody.m[2][2] = 1.0f / I;
        } else {
            inertiaBody = Mat3::identity();
            invInertiaBody = Mat3::identity();
        }
    }

    void applyForce(const Vec3& force) {
        if (isStatic) return;
        forceAccum += force;
    }

    void applyForceAtPoint(const Vec3& force, const Vec3& pointWorld) {
        if (isStatic) return;
        forceAccum += force;
        Vec3 r = pointWorld - position;
        torqueAccum += r.cross(force);
    }

    void clearAccumulators() {
        forceAccum = Vec3();
        torqueAccum = Vec3();
    }
};

// -----------------------------
// Physics World
// -----------------------------
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
    float groundY = 0.0f;

    void step(float dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate forces -> velocities
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            Vec3 acceleration = body.forceAccum * body.invMass;
            body.velocity += acceleration * dt;

            Vec3 angularAccel = body.invInertiaBody * body.torqueAccum;
            body.angularVelocity += angularAccel * dt;

            body.velocity *= std::pow(body.linearDamping, dt * 60.0f);
            body.angularVelocity *= std::pow(body.angularDamping, dt * 60.0f);
        }

        // Integrate velocities -> positions/orientations
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            body.position += body.velocity * dt;

            Quat dq = Quat::fromAngularVelocity(body.angularVelocity, dt);
            body.orientation = dq * body.orientation;
            body.orientation.normalize();
        }

        // Collisions
        solveGroundCollisions();

        // Clear accumulators
        for (auto& body : bodies) {
            body.clearAccumulators();
        }
    }

private:
    void solveGroundCollisions() {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            float minY = body.position.y - body.radius;
            if (minY < groundY) {
                // Positional correction
                body.position.y = groundY + body.radius;

                // Bounce on contact
                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }

                // Simple friction/damping on horizontal movement
                body.velocity.x *= 0.85f;
                body.velocity.z *= 0.85f;

                // Dampen spin on contact
                body.angularVelocity *= 0.9f;
            }
        }
    }
};

// -----------------------------
// Main real-time loop
// -----------------------------
int main() {
    PhysicsWorld world;

    // Add a few rigid bodies
    world.bodies.emplace_back(1.0f, 0.5f, Vec3(0.0f, 8.0f, 0.0f));
    world.bodies.emplace_back(2.0f, 0.7f, Vec3(2.0f, 12.0f, 0.0f));
    world.bodies.emplace_back(0.0f, 0.0f, Vec3(0.0f, 0.0f, 0.0f)); // static placeholder if needed

    world.bodies[0].velocity = Vec3(1.5f, 0.0f, 0.0f);
    world.bodies[0].angularVelocity = Vec3(0.0f, 0.0f, 4.0f);

    world.bodies[1].velocity = Vec3(-1.0f, 0.0f, 0.0f);
    world.bodies[1].angularVelocity = Vec3(0.0f, 2.0f, 0.0f);

    constexpr float fixedDt = 1.0f / 120.0f;   // physics simulation rate
    constexpr float maxFrameTime = 0.25f;      // avoid spiral of death
    constexpr int targetRenderFPS = 60;
    constexpr float targetFrameTime = 1.0f / targetRenderFPS;

    using clock = std::chrono::high_resolution_clock;
    auto previousTime = clock::now();

    float accumulator = 0.0f;
    float simulationTime = 0.0f;

    for (int frame = 0; frame < 600; ++frame) { // run ~10 seconds at 60 FPS
        auto currentTime = clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            simulationTime += fixedDt;
        }

        // Render/output state (text-based for demo)
        std::cout << "Frame " << frame << " | t=" << simulationTime << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            if (b.isStatic) continue;

            std::cout
                << "  Body " << i
                << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                << " Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")"
                << " AngVel(" << b.angularVelocity.x << ", " << b.angularVelocity.y << ", " << b.angularVelocity.z << ")"
                << "\n";
        }

        // Frame-rate constraint for this demo loop
        auto frameEnd = clock::now();
        std::chrono::duration<float> workTime = frameEnd - currentTime;
        float sleepTime = targetFrameTime - workTime.count();
        if (sleepTime > 0.0f) {
            std::this_thread::sleep_for(std::chrono::duration<float>(sleepTime));
        }
    }

    return 0;
}
