```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec2 {
    float x, y;

    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& other) {
        x += other.x; y += other.y;
        return *this;
    }
};

static float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

static Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len < 1e-6f) return {0.0f, 0.0f};
    return v / len;
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float radius;
    float mass;
    float restitution;
    bool isStatic;
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0f, 9.8f};
    float groundY = 20.0f;

    void step(float dt) {
        // Integrate
        for (auto& body : bodies) {
            if (body.isStatic) continue;
            body.velocity += gravity * dt;
            body.position += body.velocity * dt;
        }

        // Ground collision
        for (auto& body : bodies) {
            if (body.isStatic) continue;
            if (body.position.y + body.radius > groundY) {
                body.position.y = groundY - body.radius;
                body.velocity.y *= -body.restitution;
            }
        }

        // Circle-circle collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCollision(bodies[i], bodies[j]);
            }
        }
    }

private:
    void resolveCollision(RigidBody& a, RigidBody& b) {
        if (a.isStatic && b.isStatic) return;

        Vec2 delta = b.position - a.position;
        float dist = length(delta);
        float minDist = a.radius + b.radius;

        if (dist >= minDist || dist < 1e-6f) return;

        Vec2 normal = delta / dist;
        float penetration = minDist - dist;

        // Positional correction
        float totalMass = (a.isStatic ? 0.0f : a.mass) + (b.isStatic ? 0.0f : b.mass);
        if (!a.isStatic) a.position += normal * (-penetration * (b.mass / totalMass));
        if (!b.isStatic) b.position += normal * ( penetration * (a.mass / totalMass));

        // Relative velocity
        Vec2 rv = b.velocity - a.velocity;
        float velAlongNormal = dot(rv, normal);

        if (velAlongNormal > 0) return;

        float e = std::min(a.restitution, b.restitution);

        float invMassA = a.isStatic ? 0.0f : 1.0f / a.mass;
        float invMassB = b.isStatic ? 0.0f : 1.0f / b.mass;

        float j = -(1.0f + e) * velAlongNormal;
        j /= invMassA + invMassB;

        Vec2 impulse = normal * j;

        if (!a.isStatic) a.velocity += impulse * (-invMassA);
        if (!b.isStatic) b.velocity += impulse * ( invMassB);
    }
};

void render(const PhysicsWorld& world, int width = 60, int height = 20) {
    std::vector<std::string> screen(height, std::string(width, ' '));

    for (const auto& body : world.bodies) {
        int x = std::clamp(static_cast<int>(body.position.x), 0, width - 1);
        int y = std::clamp(static_cast<int>(body.position.y), 0, height - 1);
        screen[y][x] = 'O';
    }

    for (int x = 0; x < width; ++x)
        screen[height - 1][x] = '-';

    std::cout << "\x1B[2J\x1B[H"; // Clear terminal
    for (const auto& row : screen)
        std::cout << row << "\n";
}

int main() {
    PhysicsWorld world;

    world.bodies.push_back({{20, 2}, {3, 0}, 1.0f, 1.0f, 0.8f, false});
    world.bodies.push_back({{30, 5}, {-2, 0}, 1.0f, 1.0f, 0.8f, false});
    world.bodies.push_back({{40, 8}, {0, 0}, 1.0f, 1.0f, 0.8f, false});

    const float fixedDt = 1.0f / 60.0f;
    auto previous = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto current = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> frameTime = current - previous;
        previous = current;

        accumulator += frameTime.count();

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        render(world);

        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
