## Minimal real-time rigid body simulation in <language>C++</language>

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec2 {
    float x, y;

    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& o) {
        x += o.x; y += o.y;
        return *this;
    }

    Vec2& operator-=(const Vec2& o) {
        x -= o.x; y -= o.y;
        return *this;
    }
};

static float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

static Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len < 1e-6f) return {0.0f, 0.0f};
    return v / len;
}

struct Body {
    Vec2 position;
    Vec2 velocity;
    float radius;
    float mass;
    float invMass;
    float restitution;
    bool isStatic;
};

class PhysicsWorld {
public:
    std::vector<Body> bodies;
    Vec2 gravity{0.0f, 9.8f};

    float width = 80.0f;
    float height = 25.0f;

    void step(float dt) {
        // Integrate motion
        for (auto& b : bodies) {
            if (b.isStatic) continue;
            b.velocity += gravity * dt;
            b.position += b.velocity * dt;
        }

        // Resolve boundary collisions
        for (auto& b : bodies) {
            if (b.isStatic) continue;

            if (b.position.x - b.radius < 0.0f) {
                b.position.x = b.radius;
                b.velocity.x *= -b.restitution;
            }
            if (b.position.x + b.radius > width) {
                b.position.x = width - b.radius;
                b.velocity.x *= -b.restitution;
            }
            if (b.position.y - b.radius < 0.0f) {
                b.position.y = b.radius;
                b.velocity.y *= -b.restitution;
            }
            if (b.position.y + b.radius > height) {
                b.position.y = height - b.radius;
                b.velocity.y *= -b.restitution;
            }
        }

        // Resolve body-body collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCollision(bodies[i], bodies[j]);
            }
        }
    }

private:
    void resolveCollision(Body& a, Body& b) {
        if (a.isStatic && b.isStatic) return;

        Vec2 delta = b.position - a.position;
        float dist = length(delta);
        float minDist = a.radius + b.radius;

        if (dist >= minDist || dist < 1e-6f) return;

        Vec2 normal = delta / dist;
        float penetration = minDist - dist;

        // Positional correction
        float totalInvMass = a.invMass + b.invMass;
        if (totalInvMass > 0.0f) {
            Vec2 correction = normal * (penetration / totalInvMass);
            if (!a.isStatic) a.position -= correction * a.invMass;
            if (!b.isStatic) b.position += correction * b.invMass;
        }

        // Relative velocity
        Vec2 rv = b.velocity - a.velocity;
        float velAlongNormal = dot(rv, normal);

        // Do not resolve if separating
        if (velAlongNormal > 0.0f) return;

        float e = std::min(a.restitution, b.restitution);

        float j = -(1.0f + e) * velAlongNormal;
        if (totalInvMass > 0.0f)
            j /= totalInvMass;
        else
            return;

        Vec2 impulse = normal * j;

        if (!a.isStatic) a.velocity -= impulse * a.invMass;
        if (!b.isStatic) b.velocity += impulse * b.invMass;
    }
};

void render(const PhysicsWorld& world) {
    std::vector<std::string> grid((int)world.height, std::string((int)world.width, ' '));

    for (const auto& b : world.bodies) {
        int x = std::clamp((int)std::round(b.position.x), 0, (int)world.width - 1);
        int y = std::clamp((int)std::round(b.position.y), 0, (int)world.height - 1);
        grid[y][x] = 'O';
    }

    std::cout << "\x1B[2J\x1B[H"; // Clear terminal
    for (int y = 0; y < (int)world.height; ++y) {
        for (int x = 0; x < (int)world.width; ++x) {
            if (y == 0 || y == (int)world.height - 1)
                std::cout << '-';
            else if (x == 0 || x == (int)world.width - 1)
                std::cout << '|';
            else
                std::cout << grid[y][x];
        }
        std::cout << "\n";
    }
}

int main() {
    PhysicsWorld world;

    world.bodies.push_back({
        {20.0f, 5.0f}, {8.0f, 0.0f},
        1.0f, 1.0f, 1.0f, 0.8f, false
    });

    world.bodies.push_back({
        {35.0f, 8.0f}, {-4.0f, 0.0f},
        1.0f, 2.0f, 0.5f, 0.8f, false
    });

    world.bodies.push_back({
        {50.0f, 3.0f}, {-2.0f, 0.0f},
        1.0f, 1.5f, 1.0f / 1.5f, 0.8f, false
    });

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();

    const float fixedDt = 1.0f / 60.0f;
    float accumulator = 0.0f;

    while (true) {
        auto current = clock::now();
        std::chrono::duration<float> frameTime = current - previous;
        previous = current;

        // Avoid spiral-of-death on slow frames
        float dt = std::min(frameTime.count(), 0.25f);
        accumulator += dt;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        render(world);

        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
