## Code

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec2 {
    float x, y;

    Vec2() : x(0), y(0) {}
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& o) const { return Vec2(x + o.x, y + o.y); }
    Vec2 operator-(const Vec2& o) const { return Vec2(x - o.x, y - o.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(const Vec2& o) { x -= o.x; y -= o.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }

    float dot(const Vec2& o) const { return x * o.x + y * o.y; }
    float length() const { return std::sqrt(x * x + y * y); }

    Vec2 normalized() const {
        float len = length();
        if (len < 1e-6f) return Vec2(0, 0);
        return *this / len;
    }
};

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float radius;
    float mass;
    float invMass;
    float restitution;
    bool isStatic;

    RigidBody(Vec2 pos, Vec2 vel, float r, float m, float rest, bool stat = false)
        : position(pos), velocity(vel), radius(r), mass(m), restitution(rest), isStatic(stat)
    {
        invMass = (isStatic || m <= 0.0f) ? 0.0f : 1.0f / m;
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec2 gravity = Vec2(0.0f, -9.81f);
    float groundY = 0.0f;

    void step(float dt) {
        // Integrate forces and velocities
        for (auto& body : bodies) {
            if (body.isStatic) continue;
            body.velocity += gravity * dt;
            body.position += body.velocity * dt;
        }

        // Ground collision
        for (auto& body : bodies) {
            if (body.isStatic) continue;
            float minY = body.position.y - body.radius;
            if (minY < groundY) {
                body.position.y = groundY + body.radius;
                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }
            }
        }

        // Body-body collisions (naive O(n^2))
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCollision(bodies[i], bodies[j]);
            }
        }
    }

    void resolveCollision(RigidBody& a, RigidBody& b) {
        Vec2 delta = b.position - a.position;
        float dist = delta.length();
        float minDist = a.radius + b.radius;

        if (dist <= 0.0f || dist >= minDist) return;

        Vec2 normal = delta / dist;
        float penetration = minDist - dist;

        // Positional correction
        float totalInvMass = a.invMass + b.invMass;
        if (totalInvMass <= 0.0f) return;

        Vec2 correction = normal * (penetration / totalInvMass);
        if (!a.isStatic) a.position -= correction * a.invMass;
        if (!b.isStatic) b.position += correction * b.invMass;

        // Relative velocity
        Vec2 rv = b.velocity - a.velocity;
        float velAlongNormal = rv.dot(normal);

        // Ignore if separating
        if (velAlongNormal > 0.0f) return;

        float e = std::min(a.restitution, b.restitution);

        float j = -(1.0f + e) * velAlongNormal;
        j /= totalInvMass;

        Vec2 impulse = normal * j;
        if (!a.isStatic) a.velocity -= impulse * a.invMass;
        if (!b.isStatic) b.velocity += impulse * b.invMass;
    }
};

int main() {
    PhysicsWorld world;

    world.bodies.emplace_back(Vec2(-1.0f, 8.0f), Vec2(2.0f, 0.0f), 0.5f, 1.0f, 0.8f);
    world.bodies.emplace_back(Vec2(1.0f, 10.0f), Vec2(-1.5f, 0.0f), 0.5f, 1.0f, 0.8f);
    world.bodies.emplace_back(Vec2(0.0f, 14.0f), Vec2(0.0f, -1.0f), 0.7f, 2.0f, 0.6f);

    constexpr float fixedDt = 1.0f / 60.0f;
    constexpr int targetFPS = 60;
    constexpr auto frameDuration = std::chrono::milliseconds(1000 / targetFPS);

    auto previousTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    for (int frame = 0; frame < 600; ++frame) { // run ~10 seconds
        auto frameStart = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> elapsed = frameStart - previousTime;
        previousTime = frameStart;
        accumulator += elapsed.count();

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render/print state
        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ")\n";
        }

        // Frame-rate cap
        auto frameEnd = std::chrono::high_resolution_clock::now();
        auto workTime = std::chrono::duration_cast<std::chrono::milliseconds>(frameEnd - frameStart);
        if (workTime < frameDuration) {
            std::this_thread::sleep_for(frameDuration - workTime);
        }
    }

    return 0;
}
```

