## Minimal C++ Example

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float angle = 0.0f;
    float angularVelocity = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;
    float radius = 0.5f;
    float restitution = 0.7f;

    RigidBody(Vec2 pos, Vec2 vel, float m, float r)
        : position(pos), velocity(vel), mass(m), radius(r) {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;
    }
};

class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = Vec2(0.0f, -9.81f);
    float groundY = 0.0f;

    void step(float dt) {
        for (auto& body : bodies) {
            if (body.invMass == 0.0f) continue;

            // Integrate linear motion
            body.velocity += gravity * dt;
            body.position += body.velocity * dt;

            // Integrate angular motion
            body.angle += body.angularVelocity * dt;

            // Simple collision with ground
            float minY = groundY + body.radius;
            if (body.position.y < minY) {
                body.position.y = minY;

                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // crude damping to reduce endless bouncing
                    if (std::fabs(body.velocity.y) < 0.1f) {
                        body.velocity.y = 0.0f;
                    }
                }

                // simple friction approximation
                body.velocity.x *= 0.98f;
                body.angularVelocity *= 0.98f;
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec2(0.0f, 10.0f), Vec2(2.0f, 0.0f), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec2(-2.0f, 15.0f), Vec2(1.0f, -1.0f), 2.0f, 0.75f);

    const float fixedDt = 1.0f / 60.0f; // 60 Hz simulation
    const float maxFrameTime = 0.25f;    // prevent spiral of death
    float accumulator = 0.0f;

    auto previousTime = std::chrono::high_resolution_clock::now();

    for (int frame = 0; frame < 600; ++frame) { // run ~10 seconds
        auto currentTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> elapsed = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render/debug output
        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout
                << " Body " << i
                << " Pos(" << b.position.x << ", " << b.position.y << ")"
                << " Vel(" << b.velocity.x << ", " << b.velocity.y << ")"
                << " Angle(" << b.angle << ")\n";
        }
        std::cout << "-------------------------\n";

        // Approximate display frame-rate cap at ~60 FPS
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
```

