## Minimal example: `main.cpp`

```cpp
#include <SFML/Graphics.hpp>
#include <box2d/box2d.h>
#include <vector>
#include <memory>

static constexpr float SCALE = 30.0f;          // pixels per meter
static constexpr float TIME_STEP = 1.0f / 60.0f;
static constexpr int VELOCITY_ITERATIONS = 8;
static constexpr int POSITION_ITERATIONS = 3;

struct RenderBody {
    b2Body* body;
    sf::RectangleShape shape;
};

int main() {
    sf::RenderWindow window(sf::VideoMode(1000, 700), "Minimal Real-Time Physics");
    window.setFramerateLimit(144);

    // Box2D world with gravity
    b2World world(b2Vec2(0.0f, 9.8f));

    std::vector<RenderBody> renderBodies;

    // Ground body
    {
        b2BodyDef groundDef;
        groundDef.position.Set(500.0f / SCALE, 650.0f / SCALE);
        b2Body* ground = world.CreateBody(&groundDef);

        b2PolygonShape groundBox;
        groundBox.SetAsBox(400.0f / SCALE, 20.0f / SCALE);

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &groundBox;
        fixtureDef.friction = 0.8f;
        ground->CreateFixture(&fixtureDef);

        sf::RectangleShape shape(sf::Vector2f(800.0f, 40.0f));
        shape.setOrigin(400.0f, 20.0f);
        shape.setFillColor(sf::Color(120, 120, 120));
        renderBodies.push_back({ground, shape});
    }

    // A side wall
    {
        b2BodyDef wallDef;
        wallDef.position.Set(100.0f / SCALE, 400.0f / SCALE);
        b2Body* wall = world.CreateBody(&wallDef);

        b2PolygonShape wallBox;
        wallBox.SetAsBox(20.0f / SCALE, 200.0f / SCALE);

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &wallBox;
        fixtureDef.friction = 0.6f;
        wall->CreateFixture(&fixtureDef);

        sf::RectangleShape shape(sf::Vector2f(40.0f, 400.0f));
        shape.setOrigin(20.0f, 200.0f);
        shape.setFillColor(sf::Color(120, 120, 120));
        renderBodies.push_back({wall, shape});
    }

    auto spawnBox = [&](float xPixels, float yPixels) {
        b2BodyDef bodyDef;
        bodyDef.type = b2_dynamicBody;
        bodyDef.position.Set(xPixels / SCALE, yPixels / SCALE);
        bodyDef.angle = 0.0f;

        b2Body* body = world.CreateBody(&bodyDef);

        b2PolygonShape dynamicBox;
        dynamicBox.SetAsBox(20.0f / SCALE, 20.0f / SCALE);

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &dynamicBox;
        fixtureDef.density = 1.0f;
        fixtureDef.friction = 0.5f;
        fixtureDef.restitution = 0.2f;
        body->CreateFixture(&fixtureDef);

        sf::RectangleShape shape(sf::Vector2f(40.0f, 40.0f));
        shape.setOrigin(20.0f, 20.0f);
        shape.setFillColor(sf::Color::Green);

        renderBodies.push_back({body, shape});
    };

    // Initial stack
    for (int i = 0; i < 5; ++i) {
        spawnBox(500.0f, 100.0f + i * 50.0f);
    }

    sf::Clock clock;
    float accumulator = 0.0f;

    while (window.isOpen()) {
        float frameTime = clock.restart().asSeconds();

        // Avoid spiral-of-death on long stalls
        if (frameTime > 0.25f) {
            frameTime = 0.25f;
        }

        accumulator += frameTime;

        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }

            if (event.type == sf::Event::KeyPressed) {
                if (event.key.code == sf::Keyboard::Escape) {
                    window.close();
                }
                if (event.key.code == sf::Keyboard::Space) {
                    spawnBox(500.0f, 50.0f);
                }
            }

            if (event.type == sf::Event::MouseButtonPressed) {
                if (event.mouseButton.button == sf::Mouse::Left) {
                    spawnBox((float)event.mouseButton.x, (float)event.mouseButton.y);
                }
            }
        }

        // Fixed timestep physics
        while (accumulator >= TIME_STEP) {
            world.Step(TIME_STEP, VELOCITY_ITERATIONS, POSITION_ITERATIONS);
            accumulator -= TIME_STEP;
        }

        window.clear(sf::Color(30, 30, 40));

        // Render bodies
        for (auto& rb : renderBodies) {
            b2Vec2 pos = rb.body->GetPosition();
            float angle = rb.body->GetAngle();

            rb.shape.setPosition(pos.x * SCALE, pos.y * SCALE);
            rb.shape.setRotation(angle * 180.0f / b2_pi);

            window.draw(rb.shape);
        }

        window.display();
    }

    return 0;
}
