package com.example.payments.service;

import com.example.payments.dto.PaymentRequest;
import com.example.payments.model.Payment;
import com.example.payments.model.PaymentStatus;
import com.example.payments.repo.PaymentRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepository;
    private final AuditService auditService;

    public PaymentService(PaymentRepository paymentRepository, AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.auditService = auditService;
    }

    @Transactional
    public Payment submit(PaymentRequest request) {
        return paymentRepository.findByClientPaymentId(request.getClientPaymentId())
                .orElseGet(() -> createNewPayment(request));
    }

    private Payment createNewPayment(PaymentRequest request) {
        validateBusinessRules(request);

        Payment payment = Payment.create(
                request.getDebtorAccountRef(),
                request.getCreditorAccountRef(),
                request.getAmount(),
                request.getCurrency(),
                request.getClientPaymentId(),
                request.getRemittanceInfo()
        );

        // Placeholder decisioning only. Not real sanctions/AML/fraud/payment execution.
        if (payment.getAmount().signum() > 0) {
            payment.setStatus(PaymentStatus.PENDING_REVIEW);
        } else {
            payment.setStatus(PaymentStatus.REJECTED);
        }

        try {
            Payment saved = paymentRepository.save(payment);
            auditService.log("PAYMENT_RECEIVED", saved.getId(), "status=" + saved.getStatus());
            return saved;
        } catch (DataIntegrityViolationException ex) {
            return paymentRepository.findByClientPaymentId(request.getClientPaymentId())
                    .orElseThrow(() -> ex);
        }
    }

    private void validateBusinessRules(PaymentRequest request) {
        if (request.getDebtorAccountRef().equals(request.getCreditorAccountRef())) {
            throw new IllegalArgumentException("debtor and creditor must differ");
        }
    }
}
