```java
package com.example.payments.service;

import com.example.payments.exception.ConflictException;
import com.example.payments.model.Payment;
import com.example.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.Optional;

@Service
public class IdempotencyService {
    private final PaymentRepository paymentRepository;

    public IdempotencyService(PaymentRepository paymentRepository) {
        this.paymentRepository = paymentRepository;
    }

    public Optional<Payment> findExisting(String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey);
    }

    public void validateSameRequest(Payment existing,
                                    String sourceAccountRef,
                                    String destinationAccountRef,
                                    BigDecimal amount,
                                    String currency) {
        boolean matches =
                existing.getSourceAccountRef().equals(sourceAccountRef) &&
                existing.getDestinationAccountRef().equals(destinationAccountRef) &&
                existing.getAmount().compareTo(amount) == 0 &&
                existing.getCurrency().equalsIgnoreCase(currency);

        if (!matches) {
            throw new ConflictException("Idempotency key re-used with different request payload");
        }
    }
}
