# 13) Payment service

```java
package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.NotFoundException;
import com.example.payments.model.Payment;
import com.example.payments.model.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;
    private final PaymentProcessor paymentProcessor;

    public PaymentService(PaymentRepository paymentRepository,
                          IdempotencyService idempotencyService,
                          AuditService auditService,
                          PaymentProcessor paymentProcessor) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.auditService = auditService;
        this.paymentProcessor = paymentProcessor;
    }

    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        var existing = idempotencyService.findExisting(idempotencyKey);
        if (existing.isPresent()) {
            idempotencyService.validateSameRequest(
                    existing.get(),
                    request.getSourceAccountRef(),
                    request.getDestinationAccountRef(),
                    request.getAmount(),
                    request.getCurrency()
            );
            return existing.get();
        }

        Instant now = Instant.now();

        Payment payment = new Payment();
        payment.setId(UUID.randomUUID());
        payment.setClientPaymentId(request.getClientPaymentId());
        payment.setIdempotencyKey(idempotencyKey);
        payment.setSourceAccountRef(request.getSourceAccountRef());
        payment.setDestinationAccountRef(request.getDestinationAccountRef());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency().toUpperCase());
        payment.setStatus(PaymentStatus.RECEIVED);
        payment.setCreatedAt(now);
        payment.setUpdatedAt(now);

        paymentRepository.save(payment);
        auditService.record("PAYMENT_RECEIVED", payment, "Payment request accepted");

        payment.setStatus(PaymentStatus.VALIDATED);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.record("PAYMENT_VALIDATED", payment, "Basic validation completed");

        payment.setStatus(PaymentStatus.PROCESSING);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        auditService.record("PAYMENT_PROCESSING", payment, "Submitting to processor");

        PaymentProcessor.ProcessorResult result = paymentProcessor.authorizeAndCapture(
                payment.getSourceAccountRef(),
                payment.getDestinationAccountRef(),
                payment.getAmount(),
                payment.getCurrency()
        );

        if (result.isApproved()) {
            payment.setStatus(PaymentStatus.APPROVED);
            payment.setProcessorReference(result.getProcessorReference());
            payment.setDeclineReason(null);
            auditService.record("PAYMENT_APPROVED", payment, "Payment approved by processor");
        } else {
            payment.setStatus(PaymentStatus.DECLINED);
            payment.setProcessorReference(result.getProcessorReference());
            payment.setDeclineReason(result.getDeclineReason());
            auditService.record("PAYMENT_DECLINED", payment, result.getDeclineReason());
        }

        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);
        return payment;
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NotFoundException("Payment not found"));
    }
}
```

