public final class PaymentRequest {
    public String sourceAccountId;
    public String destinationAccountId;
    public long amountMinor;
    public String currency;
    public String idempotencyKey;
}

public final class PaymentResult {
    public boolean accepted;
    public String status;
    public String reference;
}

public interface PaymentService {
    PaymentResult submit(PaymentRequest request);
}

public final class BasicValidationPaymentService implements PaymentService {
    @Override
    public PaymentResult submit(PaymentRequest request) {
        if (request == null) throw new IllegalArgumentException("request required");
        if (request.sourceAccountId == null || request.destinationAccountId == null) {
            throw new IllegalArgumentException("account ids required");
        }
        if (request.amountMinor <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        if (request.currency == null || request.currency.length() != 3) {
            throw new IllegalArgumentException("invalid currency");
        }

        PaymentResult result = new PaymentResult();
        result.accepted = true;
        result.status = "RECEIVED_FOR_REVIEW";
        result.reference = "demo-ref";
        return result;
    }
}
