    name = "payments",
    uniqueConstraints = {
        @UniqueConstraint(name = "uk_payments_client_ref", columnNames = {"client_payment_reference"})
    },
    indexes = {
        @Index(name = "idx_payments_status", columnList = "status"),
        @Index(name = "idx_payments_created_at", columnList = "created_at")
    }
)
public class Payment {

    @Id
    private UUID id;

    @Column(name = "client_payment_reference", nullable = false, length = 64)
    private String clientPaymentReference;

    @Column(name = "debtor_account_id", nullable = false, length = 64)
    private String debtorAccountId;

    @Column(name = "creditor_account_id", nullable = false, length = 64)
    private String creditorAccountId;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Enumerated(EnumType.STRING)
    @Column(name = "payment_type", nullable = false, length = 32)
    private PaymentType paymentType;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private PaymentStatus status;

    @Column(name = "remittance_information", length = 256)
    private String remittanceInformation;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    public Payment() {}

    public Payment(UUID id,
                   String clientPaymentReference,
                   String debtorAccountId,
                   String creditorAccountId,
                   BigDecimal amount,
                   String currency,
                   PaymentType paymentType,
                   PaymentStatus status,
                   String remittanceInformation,
                   Instant createdAt,
                   Instant updatedAt) {
        this.id = id;
        this.clientPaymentReference = clientPaymentReference;
        this.debtorAccountId = debtorAccountId;
        this.creditorAccountId = creditorAccountId;
        this.amount = amount;
        this.currency = currency;
        this.paymentType = paymentType;
        this.status = status;
        this.remittanceInformation = remittanceInformation;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

