## `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.OutboxEvent;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.exception.ValidationException;
import com.example.payments.repo.OutboxEventRepository;
import com.example.payments.repo.PaymentRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final OutboxEventRepository outboxEventRepository;
    private final IdempotencyService idempotencyService;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final ObjectMapper objectMapper;

    public PaymentApplicationService(PaymentRepository paymentRepository,
                                     OutboxEventRepository outboxEventRepository,
                                     IdempotencyService idempotencyService,
                                     RiskService riskService,
                                     LedgerService ledgerService,
                                     ObjectMapper objectMapper) {
        this.paymentRepository = paymentRepository;
        this.outboxEventRepository = outboxEventRepository;
        this.idempotencyService = idempotencyService;
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.objectMapper = objectMapper;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request) {
        var existing = idempotencyService.findExisting(request.clientPaymentReference());
        if (existing.isPresent()) {
            return existing.get();
        }

        validateBusinessRules(request);

        Instant now = Instant.now();
        Payment payment = new Payment(
                UUID.randomUUID(),
                request.clientPaymentReference(),
                request.debtorAccountId(),
                request.creditorAccountId(),
                request.amount(),
                request.currency().toUpperCase(),
                request.paymentType(),
                PaymentStatus.RECEIVED,
                request.remittanceInformation(),
                now,
                now
        );

        payment.setStatus(PaymentStatus.VALIDATED);

        boolean passedRisk = riskService.screen(payment);
        if (!passedRisk) {
            payment.setStatus(PaymentStatus.SCREENING_FAILED);
            Payment saved = paymentRepository.save(payment);
            saveOutbox(saved, "PAYMENT_SCREENING_FAILED");
            return saved;
        }

        payment.setStatus(PaymentStatus.APPROVED);
        ledgerService.post(payment);
        payment.setStatus(PaymentStatus.POSTED);

        Payment saved = paymentRepository.save(payment);
        saveOutbox(saved, "PAYMENT_POSTED");
        return saved;
    }

    @Transactional(readOnly = true)
    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new com.example.payments.exception.NotFoundException("Payment not found"));
    }

    private void validateBusinessRules(CreatePaymentRequest request) {
        if (request.debtorAccountId().equals(request.creditorAccountId())) {
            throw new ValidationException("Debtor and creditor accounts must be different");
        }

        if (!request.currency().matches("^[A-Za-z]{3}$")) {
            throw new ValidationException("Currency must be a valid 3-letter ISO code");
        }
    }

    private void saveOutbox(Payment payment, String eventType) {
        try {
            String payload = objectMapper.writeValueAsString(Map.of(
                    "paymentId", payment.getId(),
                    "clientPaymentReference", payment.getClientPaymentReference(),
                    "status", payment.getStatus().name(),
                    "createdAt", payment.getCreatedAt().toString()
            ));

            OutboxEvent event = new OutboxEvent(
                    UUID.randomUUID(),
                    payment.getId(),
                    "Payment",
                    eventType,
                    payload,
                    Instant.now()
            );
            outboxEventRepository.save(event);
        } catch (JsonProcessingException e) {
            throw new RuntimeException("Failed to serialize outbox event", e);
        }
    }
}
```

