import java.util.UUID;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentApplicationService paymentApplicationService;

    public PaymentController(PaymentApplicationService paymentApplicationService) {
        this.paymentApplicationService = paymentApplicationService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public CreatePaymentResponse createPayment(@Valid @RequestBody CreatePaymentRequest request) {
        Payment payment = paymentApplicationService.createPayment(request);
        return new CreatePaymentResponse(
                payment.getId(),
                payment.getClientPaymentReference(),
                payment.getStatus(),
                payment.getCreatedAt()
        );
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getPayment(@PathVariable UUID paymentId) {
        Payment payment = paymentApplicationService.getPayment(paymentId);
        return new PaymentResponse(
                payment.getId(),
                payment.getClientPaymentReference(),
                payment.getDebtorAccountId(),
                payment.getCreditorAccountId(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getPaymentType(),
                payment.getStatus(),
                payment.getRemittanceInformation(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }
}
