package com.example.payments.service;

import com.example.payments.model.PaymentStatus;
import org.springframework.stereotype.Component;

import java.util.Map;
import java.util.Set;

@Component
public class PaymentStateMachine {

    private final Map<PaymentStatus, Set<PaymentStatus>> allowedTransitions = Map.of(
            PaymentStatus.RECEIVED, Set.of(PaymentStatus.VALIDATED, PaymentStatus.REJECTED, PaymentStatus.FAILED),
            PaymentStatus.VALIDATED, Set.of(PaymentStatus.PENDING_REVIEW, PaymentStatus.APPROVED, PaymentStatus.REJECTED, PaymentStatus.FAILED),
            PaymentStatus.PENDING_REVIEW, Set.of(PaymentStatus.APPROVED, PaymentStatus.REJECTED, PaymentStatus.FAILED),
            PaymentStatus.APPROVED, Set.of(PaymentStatus.PROCESSING, PaymentStatus.FAILED),
            PaymentStatus.PROCESSING, Set.of(PaymentStatus.SETTLED, PaymentStatus.FAILED),
            PaymentStatus.SETTLED, Set.of(),
            PaymentStatus.REJECTED, Set.of(),
            PaymentStatus.FAILED, Set.of()
    );

    public boolean canTransition(PaymentStatus from, PaymentStatus to) {
        return allowedTransitions.getOrDefault(from, Set.of()).contains(to);
    }
}
```

