```java
package com.example.payments.service;

import com.example.payments.dto.CreatePaymentRequest;
import com.example.payments.exception.PaymentException;
import com.example.payments.model.AuditEvent;
import com.example.payments.model.Payment;
import com.example.payments.model.PaymentStatus;
import com.example.payments.rail.PaymentRailAdapter;
import com.example.payments.repo.IdempotencyRepository;
import com.example.payments.repo.PaymentRepository;
import org.springframework.stereotype.Service;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRepository idempotencyRepository;
    private final AuditService auditService;
    private final RiskService riskService;
    private final PaymentStateMachine stateMachine;
    private final PaymentRailAdapter paymentRailAdapter;

    public PaymentService(PaymentRepository paymentRepository,
                          IdempotencyRepository idempotencyRepository,
                          AuditService auditService,
                          RiskService riskService,
                          PaymentStateMachine stateMachine,
                          PaymentRailAdapter paymentRailAdapter) {
        this.paymentRepository = paymentRepository;
        this.idempotencyRepository = idempotencyRepository;
        this.auditService = auditService;
        this.riskService = riskService;
        this.stateMachine = stateMachine;
        this.paymentRailAdapter = paymentRailAdapter;
    }

    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            throw new PaymentException("Missing idempotency key");
        }

        var existingPaymentId = idempotencyRepository.findPaymentIdByKey(idempotencyKey);
        if (existingPaymentId.isPresent()) {
            return paymentRepository.findById(existingPaymentId.get())
                    .orElseThrow(() -> new PaymentException("Existing payment not found for idempotency key"));
        }

        Payment payment = new Payment(
                request.getDebtorAccount(),
                request.getCreditorAccount(),
                request.getAmount(),
                request.getCurrency(),
                request.getReference()
        );

        paymentRepository.save(payment);
        idempotencyRepository.save(idempotencyKey, payment.getPaymentId());
        auditService.record(new AuditEvent(payment.getPaymentId(), "PAYMENT_CREATED", "Payment received"));

        transition(payment, PaymentStatus.VALIDATED);

        if (riskService.requiresManualReview(payment)) {
            transition(payment, PaymentStatus.PENDING_REVIEW);
            auditService.record(new AuditEvent(payment.getPaymentId(), "PAYMENT_HELD", "Requires manual review"));
            return paymentRepository.save(payment);
        }

        transition(payment, PaymentStatus.APPROVED);
        transition(payment, PaymentStatus.PROCESSING);

        boolean success = paymentRailAdapter.execute(payment);
        if (success) {
            transition(payment, PaymentStatus.SETTLED);
            auditService.record(new AuditEvent(payment.getPaymentId(), "PAYMENT_SETTLED", "Payment settled successfully"));
        } else {
            transition(payment, PaymentStatus.FAILED);
            auditService.record(new AuditEvent(payment.getPaymentId(), "PAYMENT_FAILED", "Rail execution failed"));
        }

        return paymentRepository.save(payment);
    }

    public Payment getPayment(String paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentException("Payment not found"));
    }

    private void transition(Payment payment, PaymentStatus nextStatus) {
        if (!stateMachine.canTransition(payment.getStatus(), nextStatus)) {
            throw new PaymentException("Invalid status transition from " + payment.getStatus() + " to " + nextStatus);
        }
        PaymentStatus previous = payment.getStatus();
        payment.setStatus(nextStatus);
        paymentRepository.save(payment);
        auditService.record(new AuditEvent(
                payment.getPaymentId(),
                "STATUS_CHANGED",
                "Transitioned from " + previous + " to " + nextStatus
        ));
    }
}
```

