## 4) Application service

### PaymentApplicationService.java
```java
package com.example.payments.application;

import com.example.payments.domain.*;
import com.example.payments.infrastructure.*;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Currency;
import java.util.UUID;

@Service
public class PaymentApplicationService {

    private final IdempotencyStore idempotencyStore;
    private final RiskGateway riskGateway;
    private final ComplianceGateway complianceGateway;
    private final LedgerGateway ledgerGateway;
    private final EventPublisher eventPublisher;
    private final AuditLogger auditLogger;

    public PaymentApplicationService(IdempotencyStore idempotencyStore,
                                     RiskGateway riskGateway,
                                     ComplianceGateway complianceGateway,
                                     LedgerGateway ledgerGateway,
                                     EventPublisher eventPublisher,
                                     AuditLogger auditLogger) {
        this.idempotencyStore = idempotencyStore;
        this.riskGateway = riskGateway;
        this.complianceGateway = complianceGateway;
        this.ledgerGateway = ledgerGateway;
        this.eventPublisher = eventPublisher;
        this.auditLogger = auditLogger;
    }

    public PaymentResult process(String idempotencyKey, PaymentRequest request) {
        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            throw new IllegalArgumentException("Idempotency key is required");
        }

        var existing = idempotencyStore.find(idempotencyKey);
        if (existing.isPresent()) {
            auditLogger.log("PAYMENT_REPLAY", "idempotencyKey=" + idempotencyKey);
            return existing.get();
        }

        validate(request);

        Payment payment = new Payment(
                UUID.randomUUID(),
                request.debtorAccountRef(),
                request.creditorAccountRef(),
                new Money(request.amount(), Currency.getInstance(request.currency())),
                PaymentStatus.RECEIVED,
                Instant.now()
        );

        auditLogger.log("PAYMENT_RECEIVED", "paymentId=" + payment.getPaymentId());
        payment.setStatus(PaymentStatus.VALIDATED);

        if (!complianceGateway.pass(payment)) {
            payment.setStatus(PaymentStatus.DECLINED);
            PaymentResult result = new PaymentResult(payment.getPaymentId(), payment.getStatus(), "Compliance failed");
            idempotencyStore.save(idempotencyKey, result);
            auditLogger.log("PAYMENT_DECLINED", "reason=compliance paymentId=" + payment.getPaymentId());
            eventPublisher.publish("payment.declined", result);
            return result;
        }

        if (!riskGateway.approve(payment)) {
            payment.setStatus(PaymentStatus.PENDING_REVIEW);
            PaymentResult result = new PaymentResult(payment.getPaymentId(), payment.getStatus(), "Pending manual review");
            idempotencyStore.save(idempotencyKey, result);
            auditLogger.log("PAYMENT_REVIEW", "paymentId=" + payment.getPaymentId());
            eventPublisher.publish("payment.pending_review", result);
            return result;
        }

        payment.setStatus(PaymentStatus.APPROVED);

        boolean posted = ledgerGateway.post(payment);
        if (!posted) {
            payment.setStatus(PaymentStatus.FAILED);
            PaymentResult result = new PaymentResult(payment.getPaymentId(), payment.getStatus(), "Ledger posting failed");
            idempotencyStore.save(idempotencyKey, result);
            auditLogger.log("PAYMENT_FAILED", "reason=ledger paymentId=" + payment.getPaymentId());
            eventPublisher.publish("payment.failed", result);
            return result;
        }

        payment.setStatus(PaymentStatus.POSTED);

        PaymentResult result = new PaymentResult(payment.getPaymentId(), payment.getStatus(), "Payment posted successfully");
        idempotencyStore.save(idempotencyKey, result);

        auditLogger.log("PAYMENT_POSTED", "paymentId=" + payment.getPaymentId());
        eventPublisher.publish("payment.posted", result);

        return result;
    }

    private void validate(PaymentRequest request) {
        if (request == null) {
            throw new IllegalArgumentException("Request is required");
        }
        if (request.debtorAccountRef() == null || request.debtorAccountRef().isBlank()) {
            throw new IllegalArgumentException("Debtor account reference is required");
        }
        if (request.creditorAccountRef() == null || request.creditorAccountRef().isBlank()) {
            throw new IllegalArgumentException("Creditor account reference is required");
        }
        if (request.amount() == null || request.amount().signum() <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }
        if (request.currency() == null || request.currency().isBlank()) {
            throw new IllegalArgumentException("Currency is required");
        }
    }
}
