package com.example.payments.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "payments", indexes = {
        @Index(name = "idx_payments_status", columnList = "status")
})
public class Payment {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String debtorAccountId;

    @Column(nullable = false)
    private String creditorAccountId;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Column(nullable = false, length = 140)
    private String reference;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PaymentStatus status;

    @Column(nullable = false, unique = true, length = 128)
    private String idempotencyKey;

    @Column(nullable = false, updatable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    @Version
    private long version;

    @PrePersist
    void onCreate() {
        createdAt = Instant.now();
        updatedAt = createdAt;
    }

    @PreUpdate
    void onUpdate() {
        updatedAt = Instant.now();
    }

    public static Payment create(
            String debtorAccountId,
            String creditorAccountId,
            BigDecimal amount,
            String currency,
            String reference,
            String idempotencyKey
    ) {
        Payment p = new Payment();
        p.id = UUID.randomUUID();
        p.debtorAccountId = debtorAccountId;
        p.creditorAccountId = creditorAccountId;
        p.amount = amount;
        p.currency = currency;
        p.reference = reference;
        p.idempotencyKey = idempotencyKey;
        p.status = PaymentStatus.RECEIVED;
        return p;
    }

    public UUID getId() { return id; }
    public String getDebtorAccountId() { return debtorAccountId; }
    public String getCreditorAccountId() { return creditorAccountId; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public String getReference() { return reference; }
    public PaymentStatus getStatus() { return status; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }

    public void markPendingRiskReview() { this.status = PaymentStatus.PENDING_RISK_REVIEW; }
    public void markApproved() { this.status = PaymentStatus.APPROVED; }
    public void markRejected() { this.status = PaymentStatus.REJECTED; }
    public void markSettled() { this.status = PaymentStatus.SETTLED; }
    public void markFailed() { this.status = PaymentStatus.FAILED; }
}
