## `PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.IdempotencyRecord;
import com.example.payments.domain.OutboxEvent;
import com.example.payments.domain.Payment;
import com.example.payments.exception.NotFoundException;
import com.example.payments.repo.IdempotencyRecordRepository;
import com.example.payments.repo.OutboxRepository;
import com.example.payments.repo.PaymentRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Map;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyRecordRepository idempotencyRecordRepository;
    private final LedgerService ledgerService;
    private final RiskService riskService;
    private final OutboxRepository outboxRepository;
    private final ObjectMapper objectMapper;

    public PaymentService(
            PaymentRepository paymentRepository,
            IdempotencyRecordRepository idempotencyRecordRepository,
            LedgerService ledgerService,
            RiskService riskService,
            OutboxRepository outboxRepository,
            ObjectMapper objectMapper
    ) {
        this.paymentRepository = paymentRepository;
        this.idempotencyRecordRepository = idempotencyRecordRepository;
        this.ledgerService = ledgerService;
        this.riskService = riskService;
        this.outboxRepository = outboxRepository;
        this.objectMapper = objectMapper;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest request, String idempotencyKey) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> createNewPayment(request, idempotencyKey));
    }

    @Transactional
    protected Payment createNewPayment(CreatePaymentRequest request, String idempotencyKey) {
        Payment payment = Payment.create(
                request.getDebtorAccountId(),
                request.getCreditorAccountId(),
                request.getAmount(),
                request.getCurrency(),
                request.getReference(),
                idempotencyKey
        );

        payment.markPendingRiskReview();
        paymentRepository.save(payment);
        idempotencyRecordRepository.save(IdempotencyRecord.of(idempotencyKey, payment.getId()));

        boolean approved = riskService.approve(payment);

        if (!approved) {
            payment.markRejected();
            paymentRepository.save(payment);
            enqueueEvent(payment, "PaymentRejected");
            return payment;
        }

        payment.markApproved();
        paymentRepository.save(payment);

        ledgerService.recordSettlementEntries(payment);

        payment.markSettled();
        paymentRepository.save(payment);

        enqueueEvent(payment, "PaymentSettled");
        return payment;
    }

    @Transactional(readOnly = true)
    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new NotFoundException("Payment not found: " + paymentId));
    }

    private void enqueueEvent(Payment payment, String eventType) {
        try {
            String payload = objectMapper.writeValueAsString(Map.of(
                    "paymentId", payment.getId(),
                    "status", payment.getStatus(),
                    "amount", payment.getAmount(),
                    "currency", payment.getCurrency(),
                    "debtorAccountId", payment.getDebtorAccountId(),
                    "creditorAccountId", payment.getCreditorAccountId(),
                    "reference", payment.getReference()
            ));
            outboxRepository.save(OutboxEvent.of("Payment", payment.getId().toString(), eventType, payload));
        } catch (Exception e) {
            throw new IllegalStateException("Failed to serialize outbox event", e);
        }
    }
}
```

