This stub marks events as published. In production it would publish to Kafka or another event bus.

```java
package com.example.payments.service;

import com.example.payments.domain.OutboxEvent;
import com.example.payments.repo.OutboxRepository;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
public class OutboxPublisherService {

    private final OutboxRepository outboxRepository;

    public OutboxPublisherService(OutboxRepository outboxRepository) {
        this.outboxRepository = outboxRepository;
    }

    @Scheduled(fixedDelay = 5000)
    @Transactional
    public void publishPendingEvents() {
        List<OutboxEvent> events = outboxRepository.findTop100ByPublishedFalseOrderByCreatedAtAsc();

        for (OutboxEvent event : events) {
            // publish to broker here
            event.markPublished();
            outboxRepository.save(event);
        }
    }
}
