package com.example.payments.api;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.api.dto.CreatePaymentResponse;
import com.example.payments.api.dto.PaymentStatusResponse;
import com.example.payments.domain.Payment;
import com.example.payments.service.PaymentService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.util.UUID;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentService paymentService;

    public PaymentController(PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public CreatePaymentResponse createPayment(
            @RequestHeader("Idempotency-Key") String idempotencyKey,
            @Valid @RequestBody CreatePaymentRequest request
    ) {
        Payment payment = paymentService.createPayment(request, idempotencyKey);
        return new CreatePaymentResponse(
                payment.getId(),
                payment.getStatus(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getCreatedAt()
        );
    }

    @GetMapping("/{paymentId}")
    public PaymentStatusResponse getPayment(@PathVariable UUID paymentId) {
        Payment payment = paymentService.getPayment(paymentId);
        return new PaymentStatusResponse(
                payment.getId(),
                payment.getStatus(),
                payment.getDebtorAccountId(),
                payment.getCreditorAccountId(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getReference(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }
}
