## 6.10 `PaymentApplicationService.java`

```java
package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import com.example.payments.support.AuditService;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

import java.time.OffsetDateTime;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class PaymentApplicationService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final AuditService auditService;

    @Transactional
    public Payment createPayment(CreatePaymentRequest request) {
        var existing = idempotencyService.findExisting(request.idempotencyKey());
        if (existing.isPresent()) {
            return existing.get();
        }

        if (request.debtorAccount().equals(request.creditorAccount())) {
            return rejectedPayment(request, "Debtor and creditor accounts must differ");
        }

        var now = OffsetDateTime.now();

        Payment payment = Payment.builder()
                .id(UUID.randomUUID())
                .clientPaymentId(request.clientPaymentId())
                .idempotencyKey(request.idempotencyKey())
                .debtorAccount(request.debtorAccount())
                .creditorAccount(request.creditorAccount())
                .amount(request.amount())
                .currency(request.currency())
                .status(PaymentStatus.RECEIVED)
                .createdAt(now)
                .updatedAt(now)
                .build();

        paymentRepository.save(payment);
        auditService.paymentCreated(payment);

        payment.setStatus(PaymentStatus.VALIDATED);
        payment.setUpdatedAt(OffsetDateTime.now());
        paymentRepository.save(payment);
        auditService.paymentStatusChanged(payment);

        payment.setStatus(PaymentStatus.PROCESSING);
        payment.setUpdatedAt(OffsetDateTime.now());
        paymentRepository.save(payment);
        auditService.paymentStatusChanged(payment);

        payment.setStatus(PaymentStatus.COMPLETED);
        payment.setUpdatedAt(OffsetDateTime.now());
        paymentRepository.save(payment);
        auditService.paymentStatusChanged(payment);

        return payment;
    }

    private Payment rejectedPayment(CreatePaymentRequest request, String reason) {
        var now = OffsetDateTime.now();

        Payment payment = Payment.builder()
                .id(UUID.randomUUID())
                .clientPaymentId(request.clientPaymentId())
                .idempotencyKey(request.idempotencyKey())
                .debtorAccount(request.debtorAccount())
                .creditorAccount(request.creditorAccount())
                .amount(request.amount())
                .currency(request.currency())
                .status(PaymentStatus.REJECTED)
                .statusReason(reason)
                .createdAt(now)
                .updatedAt(now)
                .build();

        paymentRepository.save(payment);
        auditService.paymentCreated(payment);
        auditService.paymentStatusChanged(payment);

        return payment;
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found: " + paymentId));
    }
}
```

