package com.example.payments.service;

import com.example.payments.model.PaymentRecord;
import com.example.payments.model.PaymentRequest;
import com.example.payments.model.PaymentResponse;
import com.example.payments.model.PaymentStatus;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class PaymentService {
    private final Map<String, PaymentRecord> byPaymentId = new ConcurrentHashMap<>();
    private final Map<String, String> byIdempotencyKey = new ConcurrentHashMap<>();

    public PaymentResponse createPayment(String idempotencyKey, PaymentRequest request) {
        if (idempotencyKey != null && byIdempotencyKey.containsKey(idempotencyKey)) {
            String existingId = byIdempotencyKey.get(idempotencyKey);
            PaymentRecord existing = byPaymentId.get(existingId);
            return new PaymentResponse(existing.getPaymentId(), existing.getStatus(), "Duplicate request returned existing result");
        }

        String paymentId = UUID.randomUUID().toString();

        // Mock decision logic only. No real payment execution.
        PaymentStatus status = request.getAmountMinor() <= 1_000_000 ? PaymentStatus.APPROVED : PaymentStatus.DECLINED;

        PaymentRecord record = new PaymentRecord(
                paymentId,
                idempotencyKey,
                request,
                status,
                Instant.now()
        );

        byPaymentId.put(paymentId, record);
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            byIdempotencyKey.put(idempotencyKey, paymentId);
        }

        System.out.printf("AUDIT paymentId=%s status=%s debtor=%s creditor=%s amountMinor=%d currency=%s ref=%s%n",
                paymentId,
                status,
                request.getDebtorAccount(),
                request.getCreditorAccount(),
                request.getAmountMinor(),
                request.getCurrency(),
                request.getReference());

        return new PaymentResponse(paymentId, status, "Mock payment processed");
    }

    public PaymentRecord getPayment(String paymentId) {
        return byPaymentId.get(paymentId);
    }
}
