```java
package com.example.payments.repo;

import com.example.payments.model.Payment;
import org.springframework.stereotype.Repository;

import java.util.Collection;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryPaymentRepository {

    private final Map<String, Payment> paymentsById = new ConcurrentHashMap<>();
    private final Map<String, String> idByIdempotencyKey = new ConcurrentHashMap<>();

    public Optional<Payment> findById(String id) {
        return Optional.ofNullable(paymentsById.get(id));
    }

    public Optional<Payment> findByIdempotencyKey(String key) {
        String id = idByIdempotencyKey.get(key);
        if (id == null) {
            return Optional.empty();
        }
        return findById(id);
    }

    public Payment save(Payment payment) {
        paymentsById.put(payment.getId(), payment);
        if (payment.getIdempotencyKey() != null && !payment.getIdempotencyKey().isBlank()) {
            idByIdempotencyKey.put(payment.getIdempotencyKey(), payment.getId());
        }
        return payment;
    }

    public Collection<Payment> findAll() {
        return paymentsById.values();
    }
}
```

