# 8) `service/PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.model.AuditEvent;
import com.example.payments.model.Payment;
import com.example.payments.model.PaymentRequest;
import com.example.payments.model.PaymentStatus;
import com.example.payments.repo.InMemoryPaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Collection;
import java.util.UUID;

@Service
public class PaymentService {

    private final InMemoryPaymentRepository repository;

    public PaymentService(InMemoryPaymentRepository repository) {
        this.repository = repository;
    }

    public Payment createPayment(PaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = repository.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) {
                return existing.get();
            }
        }

        validateBusinessRules(request);

        Payment payment = new Payment();
        payment.setId(UUID.randomUUID().toString());
        payment.setIdempotencyKey(idempotencyKey);
        payment.setSourceAccount(request.getSourceAccount());
        payment.setDestinationAccount(request.getDestinationAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setReference(request.getReference());
        payment.setCreatedAt(Instant.now());
        payment.setUpdatedAt(Instant.now());

        transition(payment, PaymentStatus.RECEIVED, "Payment request received");
        transition(payment, PaymentStatus.VALIDATED, "Payment request passed validation");
        transition(payment, PaymentStatus.PROCESSING, "Payment queued for processing");

        if (request.getAmount().doubleValue() > 1000000) {
            transition(payment, PaymentStatus.REJECTED, "Amount exceeds demo threshold");
        } else {
            transition(payment, PaymentStatus.APPROVED, "Payment approved in demo processor");
        }

        repository.save(payment);
        return payment;
    }

    public Payment getPayment(String id) {
        return repository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));
    }

    public Collection<Payment> listPayments() {
        return repository.findAll();
    }

    private void validateBusinessRules(PaymentRequest request) {
        if (request.getSourceAccount().equals(request.getDestinationAccount())) {
            throw new IllegalArgumentException("sourceAccount and destinationAccount cannot be the same");
        }
    }

    private void transition(Payment payment, PaymentStatus status, String detail) {
        payment.setStatus(status);
        payment.setUpdatedAt(Instant.now());
        payment.getAuditEvents().add(new AuditEvent(Instant.now(), status.name(), detail));
    }
}
```

