package com.example.payments.repository;

import com.example.payments.model.Payment;
import org.springframework.stereotype.Repository;

import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class PaymentRepository {

    private final Map<UUID, Payment> paymentsById = new ConcurrentHashMap<>();
    private final Map<String, UUID> paymentIdsByIdempotencyKey = new ConcurrentHashMap<>();

    public Optional<Payment> findById(UUID id) {
        return Optional.ofNullable(paymentsById.get(id));
    }

    public Optional<Payment> findByIdempotencyKey(String key) {
        UUID id = paymentIdsByIdempotencyKey.get(key);
        if (id == null) {
            return Optional.empty();
        }
        return findById(id);
    }

    public Payment save(Payment payment) {
        paymentsById.put(payment.getId(), payment);
        if (payment.getIdempotencyKey() != null && !payment.getIdempotencyKey().isBlank()) {
            paymentIdsByIdempotencyKey.put(payment.getIdempotencyKey(), payment.getId());
        }
        return payment;
    }
}
