# 8) `PaymentProcessor.java`

```java
package com.example.payments.service;

import com.example.payments.model.Payment;
import com.example.payments.model.PaymentRequest;
import com.example.payments.model.PaymentStatus;
import com.example.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

@Service
public class PaymentProcessor {

    private static final BigDecimal DEMO_APPROVAL_LIMIT = new BigDecimal("10000.00");

    private final PaymentRepository repository;

    public PaymentProcessor(PaymentRepository repository) {
        this.repository = repository;
    }

    public Payment createPayment(PaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            Optional<Payment> existing = repository.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) {
                return existing.get();
            }
        }

        Payment payment = new Payment();
        payment.setId(UUID.randomUUID());
        payment.setIdempotencyKey(idempotencyKey);
        payment.setSourceAccount(request.getSourceAccount());
        payment.setDestinationAccount(request.getDestinationAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency().toUpperCase());
        payment.setCreatedAt(Instant.now());
        payment.setStatus(PaymentStatus.PENDING);
        payment.setReason("Accepted for processing");

        validateBusinessRules(payment);
        process(payment);

        return repository.save(payment);
    }

    public Optional<Payment> getPayment(UUID id) {
        return repository.findById(id);
    }

    private void validateBusinessRules(Payment payment) {
        if (payment.getSourceAccount().equals(payment.getDestinationAccount())) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setReason("Source and destination accounts must differ");
            return;
        }

        if (payment.getAmount().scale() > 2) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setReason("Amount must have at most 2 decimal places");
        }
    }

    private void process(Payment payment) {
        if (payment.getStatus() == PaymentStatus.REJECTED) {
            return;
        }

        if (payment.getAmount().compareTo(DEMO_APPROVAL_LIMIT) > 0) {
            payment.setStatus(PaymentStatus.REJECTED);
            payment.setReason("Amount exceeds demo approval threshold");
        } else {
            payment.setStatus(PaymentStatus.APPROVED);
            payment.setReason("Payment approved");
        }
    }
}
```

