```java
package com.example.payments.service;

import com.example.payments.api.CreatePaymentRequest;
import com.example.payments.model.Payment;
import com.example.payments.model.PaymentStatus;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class PaymentService {
    private final Map<UUID, Payment> store = new ConcurrentHashMap<>();
    private final Map<String, UUID> idempotencyKeys = new ConcurrentHashMap<>();

    public Payment authorize(CreatePaymentRequest request, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            UUID existingId = idempotencyKeys.get(idempotencyKey);
            if (existingId != null) {
                return store.get(existingId);
            }
        }

        PaymentStatus status = request.getAmount().doubleValue() <= 1000.00
                ? PaymentStatus.AUTHORIZED
                : PaymentStatus.DECLINED;

        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getMerchantId(),
                request.getAmount(),
                request.getCurrency(),
                status,
                Instant.now()
        );

        store.put(payment.getId(), payment);
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            idempotencyKeys.put(idempotencyKey, payment.getId());
        }

        return payment;
    }

    public Payment capture(UUID id) {
        Payment payment = require(id);
        if (payment.getStatus() == PaymentStatus.AUTHORIZED) {
            payment.setStatus(PaymentStatus.CAPTURED);
        }
        return payment;
    }

    public Payment refund(UUID id) {
        Payment payment = require(id);
        if (payment.getStatus() == PaymentStatus.CAPTURED) {
            payment.setStatus(PaymentStatus.REFUNDED);
        }
        return payment;
    }

    public Payment get(UUID id) {
        return require(id);
    }

    private Payment require(UUID id) {
        Payment payment = store.get(id);
        if (payment == null) {
            throw new IllegalArgumentException("payment not found");
        }
        return payment;
    }
}
