package com.example.enterpriseaccountservice.integration;

import com.example.enterpriseaccountservice.config.CorporateSystemsProperties;
import com.example.enterpriseaccountservice.dto.HrEmployeeRecord;
import com.example.enterpriseaccountservice.exception.CorporateIntegrationException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

@Component
public class CorporateHrClient {

    private final RestClient restClient;
    private final CorporateSystemsProperties properties;

    public CorporateHrClient(CorporateSystemsProperties properties) {
        this.properties = properties;
        this.restClient = RestClient.builder()
                .baseUrl(properties.hrBaseUrl())
                .defaultHeader(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE)
                .defaultHeader("X-API-Key", properties.hrApiKey())
                .build();
    }

    public HrEmployeeRecord getEmployeeRecord(String employeeNumber) {
        try {
            return restClient.get()
                    .uri("/employees/{employeeNumber}", employeeNumber)
                    .retrieve()
                    .body(HrEmployeeRecord.class);
        } catch (Exception ex) {
            throw new CorporateIntegrationException("Failed to retrieve employee record from HR system", ex);
        }
    }
}
