# 9) Service layer

## `service/EmployeeAccountService.java`

```java
package com.example.enterpriseaccountservice.service;

import com.example.enterpriseaccountservice.domain.EmployeeAccount;
import com.example.enterpriseaccountservice.dto.CreateEmployeeAccountRequest;
import com.example.enterpriseaccountservice.dto.EmployeeAccountResponse;
import com.example.enterpriseaccountservice.dto.HrEmployeeRecord;
import com.example.enterpriseaccountservice.dto.IdentityProvisionResponse;
import com.example.enterpriseaccountservice.exception.CorporateIntegrationException;
import com.example.enterpriseaccountservice.exception.EmployeeAccountNotFoundException;
import com.example.enterpriseaccountservice.integration.CorporateHrClient;
import com.example.enterpriseaccountservice.integration.CorporateIdentityClient;
import com.example.enterpriseaccountservice.repository.EmployeeAccountRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class EmployeeAccountService {

    private final EmployeeAccountRepository repository;
    private final CorporateHrClient hrClient;
    private final CorporateIdentityClient identityClient;

    public EmployeeAccountService(
            EmployeeAccountRepository repository,
            CorporateHrClient hrClient,
            CorporateIdentityClient identityClient
    ) {
        this.repository = repository;
        this.hrClient = hrClient;
        this.identityClient = identityClient;
    }

    @Transactional
    public EmployeeAccountResponse createEmployeeAccount(CreateEmployeeAccountRequest request) {
        HrEmployeeRecord hrRecord = hrClient.getEmployeeRecord(request.employeeNumber());

        if (hrRecord == null) {
            throw new CorporateIntegrationException("HR system returned no employee record");
        }

        if (!"ACTIVE".equalsIgnoreCase(hrRecord.employmentStatus())) {
            throw new CorporateIntegrationException("Employee is not active in HR system");
        }

        IdentityProvisionResponse identityResponse = identityClient.provisionIdentity(
                request.employeeNumber(),
                hrRecord.fullName(),
                request.email(),
                request.departmentCode()
        );

        if (identityResponse == null || identityResponse.identityAccountId() == null) {
            throw new CorporateIntegrationException("Identity system returned invalid provisioning response");
        }

        EmployeeAccount entity = new EmployeeAccount(
                UUID.randomUUID(),
                request.employeeNumber(),
                hrRecord.fullName(),
                request.email(),
                request.departmentCode(),
                identityResponse.identityAccountId(),
                Instant.now()
        );

        EmployeeAccount saved = repository.save(entity);
        return toResponse(saved);
    }

    public EmployeeAccountResponse getEmployeeAccount(UUID id) {
        EmployeeAccount account = repository.findById(id)
                .orElseThrow(() -> new EmployeeAccountNotFoundException(id));

        return toResponse(account);
    }

    private EmployeeAccountResponse toResponse(EmployeeAccount account) {
        return new EmployeeAccountResponse(
                account.getId(),
                account.getEmployeeNumber(),
                account.getFullName(),
                account.getEmail(),
                account.getDepartmentCode(),
                account.getIdentityAccountId(),
                account.getCreatedAt()
        );
    }
}
```

