package com.example.customerservice.external;

import com.example.customerservice.exception.CorporateSystemException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatusCode;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

@Component
public class CorporateDirectoryClient {

    private final RestClient restClient;

    public CorporateDirectoryClient(
            RestClient.Builder builder,
            @Value("${corporate.directory.base-url}") String baseUrl) {
        this.restClient = builder
                .baseUrl(baseUrl)
                .build();
    }

    public CorporateDirectoryResponse fetchEmployee(String employeeId) {
        try {
            return restClient.get()
                    .uri("/directory/employees/{employeeId}", employeeId)
                    .retrieve()
                    .onStatus(HttpStatusCode::isError, (request, response) -> {
                        throw new CorporateSystemException(
                                "Corporate directory returned status: " + response.getStatusCode());
                    })
                    .body(CorporateDirectoryResponse.class);
        } catch (Exception ex) {
            throw new CorporateSystemException("Failed to call corporate directory: " + ex.getMessage());
        }
    }
}
