```java
package com.example.customerservice.service;

import com.example.customerservice.dto.CreateCustomerRequest;
import com.example.customerservice.dto.CustomerResponse;
import com.example.customerservice.entity.CustomerEntity;
import com.example.customerservice.exception.CustomerNotFoundException;
import com.example.customerservice.external.CorporateDirectoryService;
import com.example.customerservice.repository.CustomerRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.time.OffsetDateTime;
import java.util.UUID;

@Service
public class CustomerService {

    private final CustomerRepository customerRepository;
    private final CorporateDirectoryService corporateDirectoryService;

    public CustomerService(
            CustomerRepository customerRepository,
            CorporateDirectoryService corporateDirectoryService) {
        this.customerRepository = customerRepository;
        this.corporateDirectoryService = corporateDirectoryService;
    }

    @Transactional
    public CustomerResponse createCustomer(CreateCustomerRequest request) {
        if (customerRepository.existsByEmployeeId(request.employeeId())) {
            throw new IllegalArgumentException("Employee ID already exists");
        }

        if (customerRepository.existsByEmail(request.email())) {
            throw new IllegalArgumentException("Email already exists");
        }

        corporateDirectoryService.validateEmployeeIsActive(request.employeeId());

        CustomerEntity entity = new CustomerEntity();
        entity.setEmployeeId(request.employeeId());
        entity.setFirstName(request.firstName());
        entity.setLastName(request.lastName());
        entity.setEmail(request.email());
        entity.setActive(true);
        entity.setCreatedAt(OffsetDateTime.now());

        CustomerEntity saved = customerRepository.save(entity);
        return toResponse(saved);
    }

    public CustomerResponse getCustomer(UUID id) {
        CustomerEntity entity = customerRepository.findById(id)
                .orElseThrow(() -> new CustomerNotFoundException(id));
        return toResponse(entity);
    }

    private CustomerResponse toResponse(CustomerEntity entity) {
        return new CustomerResponse(
                entity.getId(),
                entity.getEmployeeId(),
                entity.getFirstName(),
                entity.getLastName(),
                entity.getEmail(),
                entity.isActive(),
                entity.getCreatedAt()
        );
    }
}
