## `CustomerService.java`

```java
package com.example.customerprofileservice.service;

import com.example.customerprofileservice.domain.CustomerProfile;
import com.example.customerprofileservice.dto.CreateCustomerRequest;
import com.example.customerprofileservice.dto.CustomerProfileResponse;
import com.example.customerprofileservice.exception.CustomerNotFoundException;
import com.example.customerprofileservice.integration.crm.CrmService;
import com.example.customerprofileservice.integration.messaging.CustomerEventPublisher;
import com.example.customerprofileservice.repository.CustomerRepository;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class CustomerService {

    private final CustomerRepository customerRepository;
    private final CrmService crmService;
    private final CustomerEventPublisher customerEventPublisher;

    public CustomerService(
            CustomerRepository customerRepository,
            CrmService crmService,
            CustomerEventPublisher customerEventPublisher) {
        this.customerRepository = customerRepository;
        this.crmService = crmService;
        this.customerEventPublisher = customerEventPublisher;
    }

    @Transactional(readOnly = true)
    public CustomerProfileResponse getByExternalCustomerId(String externalCustomerId) {
        CustomerProfile profile = customerRepository.findByExternalCustomerId(externalCustomerId)
                .orElseThrow(() -> new CustomerNotFoundException(
                        "Customer not found for externalCustomerId=" + externalCustomerId));

        return toResponse(profile);
    }

    @Transactional
    public CustomerProfileResponse create(CreateCustomerRequest request) {
        crmService.validateCustomerExists(request.externalCustomerId());

        Instant now = Instant.now();
        CustomerProfile profile = new CustomerProfile(
                UUID.randomUUID(),
                request.externalCustomerId(),
                request.firstName(),
                request.lastName(),
                request.email(),
                request.status(),
                now,
                now
        );

        CustomerProfile saved = customerRepository.save(profile);
        customerEventPublisher.publishCustomerCreated(saved);

        return toResponse(saved);
    }

    private CustomerProfileResponse toResponse(CustomerProfile profile) {
        return new CustomerProfileResponse(
                profile.getId(),
                profile.getExternalCustomerId(),
                profile.getFirstName(),
                profile.getLastName(),
                profile.getEmail(),
                profile.getStatus(),
                profile.getCreatedAt(),
                profile.getUpdatedAt()
        );
    }
}
