package com.example.customerprofileservice.integration.crm;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.function.client.WebClient;

@Component
public class CrmClient {

    private final WebClient webClient;

    public CrmClient(WebClient webClient,
                     @Value("${integration.crm.base-url}") String crmBaseUrl) {
        this.webClient = webClient.mutate()
                .baseUrl(crmBaseUrl)
                .build();
    }

    public CrmCustomerResponse fetchCustomer(String externalCustomerId) {
        return webClient.get()
                .uri("/customers/{externalCustomerId}", externalCustomerId)
                .retrieve()
                .bodyToMono(CrmCustomerResponse.class)
                .block();
    }
}
