# 9. Service layer

## `service/CustomerAccountService.java`

```java
package com.example.customerservice.service;

import com.example.customerservice.domain.CustomerAccount;
import com.example.customerservice.dto.CreateCustomerAccountRequest;
import com.example.customerservice.dto.CustomerAccountResponse;
import com.example.customerservice.exception.CustomerNotFoundException;
import com.example.customerservice.integration.CorporateCrmClient;
import com.example.customerservice.repository.CustomerAccountRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;

@Service
public class CustomerAccountService {

    private final CustomerAccountRepository repository;
    private final CorporateCrmClient corporateCrmClient;

    public CustomerAccountService(CustomerAccountRepository repository,
                                  CorporateCrmClient corporateCrmClient) {
        this.repository = repository;
        this.corporateCrmClient = corporateCrmClient;
    }

    @Transactional
    public CustomerAccountResponse create(CreateCustomerAccountRequest request) {
        CustomerAccount account = new CustomerAccount(
                request.externalCustomerId(),
                request.fullName(),
                request.email(),
                "ACTIVE"
        );

        CustomerAccount saved = repository.save(account);

        corporateCrmClient.syncCustomer(saved);

        return toResponse(saved);
    }

    @Transactional(readOnly = true)
    public CustomerAccountResponse getById(UUID id) {
        CustomerAccount account = repository.findById(id)
                .orElseThrow(() -> new CustomerNotFoundException(id));
        return toResponse(account);
    }

    @Transactional(readOnly = true)
    public List<CustomerAccountResponse> list() {
        return repository.findAll().stream()
                .map(this::toResponse)
                .toList();
    }

    private CustomerAccountResponse toResponse(CustomerAccount account) {
        return new CustomerAccountResponse(
                account.getId(),
                account.getExternalCustomerId(),
                account.getFullName(),
                account.getEmail(),
                account.getStatus(),
                account.getCreatedAt(),
                account.getUpdatedAt()
        );
    }
}
```

