```java
package com.example.customerservice.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.Objects;
import java.util.UUID;

@Entity
@Table(name = "customers")
public class Customer {

    @Id
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @Column(name = "external_employee_id", nullable = false, unique = true)
    private String externalEmployeeId;

    @Column(name = "full_name", nullable = false)
    private String fullName;

    @Column(name = "email", nullable = false)
    private String email;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private CustomerStatus status;

    protected Customer() {
    }

    public Customer(CustomerId id, String externalEmployeeId, String fullName, String email, CustomerStatus status) {
        this.id = Objects.requireNonNull(id).value();
        this.externalEmployeeId = Objects.requireNonNull(externalEmployeeId);
        this.fullName = Objects.requireNonNull(fullName);
        this.email = Objects.requireNonNull(email);
        this.status = Objects.requireNonNull(status);
    }

    public CustomerId customerId() {
        return new CustomerId(id);
    }

    public String getExternalEmployeeId() {
        return externalEmployeeId;
    }

    public String getFullName() {
        return fullName;
    }

    public String getEmail() {
        return email;
    }

    public CustomerStatus getStatus() {
        return status;
    }

    public void activate() {
        this.status = CustomerStatus.ACTIVE;
    }

    public void suspend() {
        this.status = CustomerStatus.SUSPENDED;
    }

    public void deactivate() {
        this.status = CustomerStatus.INACTIVE;
    }
}
