# 7. Service layer

```java
package com.example.customerservice.service;

import com.example.customerservice.api.CustomerDtos;
import com.example.customerservice.domain.Customer;
import com.example.customerservice.domain.CustomerId;
import com.example.customerservice.domain.CustomerStatus;
import com.example.customerservice.integration.CorporateDirectoryClient;
import com.example.customerservice.integration.CorporateDirectoryResponse;
import com.example.customerservice.integration.CorporateRequestContext;
import com.example.customerservice.repository.CustomerRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

@Service
public class CustomerApplicationService {

    private final CustomerRepository customerRepository;
    private final CorporateDirectoryClient corporateDirectoryClient;

    public CustomerApplicationService(
            CustomerRepository customerRepository,
            CorporateDirectoryClient corporateDirectoryClient
    ) {
        this.customerRepository = customerRepository;
        this.corporateDirectoryClient = corporateDirectoryClient;
    }

    @Transactional
    public CustomerDtos.CustomerResponse createCustomer(
            CustomerDtos.CreateCustomerRequest request,
            CorporateRequestContext requestContext
    ) {
        customerRepository.findByExternalEmployeeId(request.externalEmployeeId())
                .ifPresent(existing -> {
                    throw new IllegalStateException("Customer already exists for employeeId=" + request.externalEmployeeId());
                });

        CorporateDirectoryResponse directoryRecord =
                corporateDirectoryClient.lookupEmployee(request.externalEmployeeId(), requestContext);

        CustomerStatus status = directoryRecord.active()
                ? CustomerStatus.ACTIVE
                : CustomerStatus.INACTIVE;

        Customer customer = new Customer(
                CustomerId.newId(),
                directoryRecord.employeeId(),
                directoryRecord.fullName(),
                directoryRecord.email(),
                status
        );

        Customer saved = customerRepository.save(customer);

        return new CustomerDtos.CustomerResponse(
                saved.customerId().value(),
                saved.getExternalEmployeeId(),
                saved.getFullName(),
                saved.getEmail(),
                saved.getStatus()
        );
    }

    public CustomerDtos.CustomerResponse getCustomerById(String id) {
        Customer customer = customerRepository.findById(CustomerId.fromString(id).value())
                .orElseThrow(() -> new IllegalArgumentException("Customer not found: " + id));

        return new CustomerDtos.CustomerResponse(
                customer.customerId().value(),
                customer.getExternalEmployeeId(),
                customer.getFullName(),
                customer.getEmail(),
                customer.getStatus()
        );
    }
}
```

