# 7. Service layer

```java
package com.example.customerprofileservice.service;

import com.example.customerprofileservice.dto.CreateCustomerRequest;
import com.example.customerprofileservice.dto.CustomerResponse;
import com.example.customerprofileservice.dto.UpdateCustomerRequest;
import com.example.customerprofileservice.entity.Customer;
import com.example.customerprofileservice.exception.CustomerNotFoundException;
import com.example.customerprofileservice.integration.CorporateMasterDataClient;
import com.example.customerprofileservice.repository.CustomerRepository;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.UUID;

@Service
@Transactional
public class CustomerService {

    private final CustomerRepository customerRepository;
    private final CorporateMasterDataClient corporateMasterDataClient;

    public CustomerService(CustomerRepository customerRepository,
                           CorporateMasterDataClient corporateMasterDataClient) {
        this.customerRepository = customerRepository;
        this.corporateMasterDataClient = corporateMasterDataClient;
    }

    public CustomerResponse createCustomer(CreateCustomerRequest request) {
        if (customerRepository.existsByExternalCustomerId(request.externalCustomerId())) {
            throw new IllegalArgumentException("External customer ID already exists");
        }

        if (customerRepository.existsByEmail(request.email())) {
            throw new IllegalArgumentException("Email already exists");
        }

        if (!corporateMasterDataClient.customerExistsInCorporateSystem(request.externalCustomerId())) {
            throw new IllegalArgumentException("Customer does not exist in corporate master data system");
        }

        Customer customer = new Customer();
        customer.setExternalCustomerId(request.externalCustomerId());
        customer.setFirstName(request.firstName());
        customer.setLastName(request.lastName());
        customer.setEmail(request.email());
        customer.setActive(true);

        Customer saved = customerRepository.save(customer);
        return toResponse(saved);
    }

    public CustomerResponse getCustomer(UUID id) {
        Customer customer = customerRepository.findById(id)
                .orElseThrow(() -> new CustomerNotFoundException(id));
        return toResponse(customer);
    }

    public List<CustomerResponse> getAllCustomers() {
        return customerRepository.findAll()
                .stream()
                .map(this::toResponse)
                .toList();
    }

    public CustomerResponse updateCustomer(UUID id, UpdateCustomerRequest request) {
        Customer customer = customerRepository.findById(id)
                .orElseThrow(() -> new CustomerNotFoundException(id));

        customer.setFirstName(request.firstName());
        customer.setLastName(request.lastName());
        customer.setEmail(request.email());
        customer.setActive(request.active());

        Customer saved = customerRepository.save(customer);
        return toResponse(saved);
    }

    public void deleteCustomer(UUID id) {
        if (!customerRepository.existsById(id)) {
            throw new CustomerNotFoundException(id);
        }
        customerRepository.deleteById(id);
    }

    private CustomerResponse toResponse(Customer customer) {
        return new CustomerResponse(
                customer.getId(),
                customer.getExternalCustomerId(),
                customer.getFirstName(),
                customer.getLastName(),
                customer.getEmail(),
                customer.isActive(),
                customer.getCreatedAt(),
                customer.getUpdatedAt()
        );
    }
}
```

