package com.example.customerservice.integration;

import com.example.customerservice.config.CorporateSystemProperties;
import com.example.customerservice.exception.CorporateIntegrationException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientException;

@Component
public class CorporateCustomerClient {

    private final RestClient restClient;
    private final CorporateSystemProperties properties;

    public CorporateCustomerClient(RestClient restClient, CorporateSystemProperties properties) {
        this.restClient = restClient;
        this.properties = properties;
    }

    public CorporateCustomerRecord registerCustomer(String name, String email) {
        try {
            CorporateCustomerResponse response = restClient.post()
                    .uri(properties.baseUrl() + properties.customerEndpoint())
                    .contentType(MediaType.APPLICATION_JSON)
                    .header(HttpHeaders.AUTHORIZATION, "Bearer " + properties.apiKey())
                    .body(new CorporateRegisterRequest(name, email))
                    .retrieve()
                    .body(CorporateCustomerResponse.class);

            if (response == null || response.data() == null) {
                throw new CorporateIntegrationException("Corporate system returned an empty response");
            }

            return response.data();
        } catch (RestClientException ex) {
            throw new CorporateIntegrationException("Failed to register customer with corporate system", ex);
        }
    }

    private record CorporateRegisterRequest(String name, String email) {
    }
}
