## CustomerService.java

```java
package com.example.customerservice.service;

import com.example.customerservice.domain.Customer;
import com.example.customerservice.domain.CustomerStatus;
import com.example.customerservice.dto.CreateCustomerRequest;
import com.example.customerservice.exception.CustomerNotFoundException;
import com.example.customerservice.integration.CorporateCustomerClient;
import com.example.customerservice.integration.CorporateCustomerRecord;
import com.example.customerservice.repository.CustomerRepository;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.UUID;

@Service
public class CustomerService {

    private final CustomerRepository customerRepository;
    private final CorporateCustomerClient corporateCustomerClient;

    public CustomerService(CustomerRepository customerRepository,
                           CorporateCustomerClient corporateCustomerClient) {
        this.customerRepository = customerRepository;
        this.corporateCustomerClient = corporateCustomerClient;
    }

    public Customer createCustomer(CreateCustomerRequest request) {
        CorporateCustomerRecord corporateRecord =
                corporateCustomerClient.registerCustomer(request.name(), request.email());

        CustomerStatus status = mapStatus(corporateRecord.status());

        Customer customer = new Customer(
                UUID.randomUUID(),
                corporateRecord.externalId(),
                request.name(),
                request.email(),
                status
        );

        return customerRepository.save(customer);
    }

    public Customer getCustomer(UUID id) {
        return customerRepository.findById(id)
                .orElseThrow(() -> new CustomerNotFoundException("Customer not found: " + id));
    }

    public List<Customer> getAllCustomers() {
        return customerRepository.findAll().stream().toList();
    }

    private CustomerStatus mapStatus(String status) {
        return switch (status) {
            case "ACTIVE" -> CustomerStatus.ACTIVE;
            case "INACTIVE" -> CustomerStatus.INACTIVE;
            default -> CustomerStatus.PENDING_REVIEW;
        };
    }
}
```

