package com.example.enterprise.client;

import com.example.enterprise.model.CorporateProfile;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

@Component
public class CorporateProfileClient {

    private final RestClient restClient;
    private final String profileBaseUrl;

    public CorporateProfileClient(
            RestClient restClient,
            @Value("${corporate.profile.base-url}") String profileBaseUrl
    ) {
        this.restClient = restClient;
        this.profileBaseUrl = profileBaseUrl;
    }

    public CorporateProfile getProfile(String customerNumber) {
        try {
            return restClient.get()
                    .uri(profileBaseUrl + "/api/profiles/{customerNumber}", customerNumber)
                    .retrieve()
                    .body(CorporateProfile.class);
        } catch (Exception ex) {
            return new CorporateProfile("UNKNOWN", "UNKNOWN", "UNAVAILABLE");
        }
    }
}
