# 6. Service layer

## `service/CustomerService.java`

```java
package com.example.enterprise.service;

import com.example.enterprise.dto.CreateCustomerRequest;
import com.example.enterprise.integration.CorporateDirectoryClient;
import com.example.enterprise.model.Customer;
import org.springframework.stereotype.Service;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class CustomerService {

    private final CorporateDirectoryClient corporateDirectoryClient;
    private final Map<UUID, Customer> customerStore = new ConcurrentHashMap<>();

    public CustomerService(CorporateDirectoryClient corporateDirectoryClient) {
        this.corporateDirectoryClient = corporateDirectoryClient;
    }

    public Customer createCustomer(CreateCustomerRequest request) {
        boolean verified = corporateDirectoryClient.employeeExists(request.employeeId());

        Customer customer = new Customer(
                UUID.randomUUID(),
                request.employeeId(),
                request.firstName(),
                request.lastName(),
                request.email(),
                verified
        );

        customerStore.put(customer.id(), customer);
        return customer;
    }

    public Customer getCustomer(UUID id) {
        Customer customer = customerStore.get(id);
        if (customer == null) {
            throw new IllegalArgumentException("Customer not found: " + id);
        }
        return customer;
    }
}
```

