package com.example.enterprise.controller;

import com.example.enterprise.dto.CreateCustomerRequest;
import com.example.enterprise.dto.CustomerResponse;
import com.example.enterprise.model.Customer;
import com.example.enterprise.service.CustomerService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.util.UUID;

@RestController
@RequestMapping("/api/customers")
public class CustomerController {

    private final CustomerService customerService;

    public CustomerController(CustomerService customerService) {
        this.customerService = customerService;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public CustomerResponse createCustomer(@Valid @RequestBody CreateCustomerRequest request) {
        Customer customer = customerService.createCustomer(request);
        return toResponse(customer);
    }

    @GetMapping("/{id}")
    public CustomerResponse getCustomer(@PathVariable UUID id) {
        Customer customer = customerService.getCustomer(id);
        return toResponse(customer);
    }

    private CustomerResponse toResponse(Customer customer) {
        return new CustomerResponse(
                customer.id(),
                customer.employeeId(),
                customer.firstName(),
                customer.lastName(),
                customer.email(),
                customer.activeDirectoryVerified()
        );
    }
}
