package com.example.enterprise.integration;

import com.example.enterprise.dto.CorporateProfileResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.function.client.WebClient;

@Component
public class CorporateDirectoryClient {

    private final WebClient corporateWebClient;

    public CorporateDirectoryClient(WebClient corporateWebClient) {
        this.corporateWebClient = corporateWebClient;
    }

    public CorporateProfileResponse getCorporateProfile(String customerId) {
        return corporateWebClient.get()
                .uri("/profiles/{customerId}", customerId)
                .retrieve()
                .bodyToMono(CorporateProfileResponse.class)
                .blockOptional()
                .orElse(new CorporateProfileResponse("UNKNOWN", "NOT_FOUND"));
    }
}
```

