## 6) Service layer

### `src/main/java/com/example/enterprise/service/CustomerService.java`

```java
package com.example.enterprise.service;

import com.example.enterprise.dto.CreateCustomerRequest;
import com.example.enterprise.dto.CustomerResponse;
import com.example.enterprise.integration.CorporateDirectoryClient;
import com.example.enterprise.model.Customer;
import org.springframework.stereotype.Service;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class CustomerService {

    private final CorporateDirectoryClient corporateDirectoryClient;
    private final Map<UUID, Customer> customers = new ConcurrentHashMap<>();

    public CustomerService(CorporateDirectoryClient corporateDirectoryClient) {
        this.corporateDirectoryClient = corporateDirectoryClient;
    }

    public CustomerResponse createCustomer(CreateCustomerRequest request) {
        boolean departmentExists = corporateDirectoryClient.departmentExists(request.getDepartmentCode());

        Customer customer = new Customer(
                UUID.randomUUID(),
                request.getName(),
                request.getEmail(),
                request.getDepartmentCode()
        );

        customers.put(customer.getId(), customer);

        return toResponse(customer, departmentExists);
    }

    public Optional<CustomerResponse> getCustomer(UUID id) {
        return Optional.ofNullable(customers.get(id))
                .map(customer -> {
                    boolean departmentExists =
                            corporateDirectoryClient.departmentExists(customer.getDepartmentCode());
                    return toResponse(customer, departmentExists);
                });
    }

    public List<CustomerResponse> getAllCustomers() {
        List<CustomerResponse> responses = new ArrayList<>();
        for (Customer customer : customers.values()) {
            boolean departmentExists =
                    corporateDirectoryClient.departmentExists(customer.getDepartmentCode());
            responses.add(toResponse(customer, departmentExists));
        }
        return responses;
    }

    private CustomerResponse toResponse(Customer customer, boolean departmentExists) {
        return new CustomerResponse(
                customer.getId(),
                customer.getName(),
                customer.getEmail(),
                customer.getDepartmentCode(),
                departmentExists
        );
    }
}
```

