using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _dbContext;

    public OrderService(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<IReadOnlyCollection<OrderResponse>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.Orders
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedUtc)
            .Select(x => new OrderResponse(
                x.Id,
                x.CustomerName,
                x.Amount,
                x.CreatedUtc,
                x.Status))
            .ToListAsync(cancellationToken);
    }

    public async Task<OrderResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Orders
            .AsNoTracking()
            .Where(x => x.Id == id)
            .Select(x => new OrderResponse(
                x.Id,
                x.CustomerName,
                x.Amount,
                x.CreatedUtc,
                x.Status))
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken = default)
    {
        var entity = new Order
        {
            Id = Guid.NewGuid(),
            CustomerName = request.CustomerName,
            Amount = request.Amount,
            CreatedUtc = DateTime.UtcNow,
            Status = "New"
        };

        _dbContext.Orders.Add(entity);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new OrderResponse(
            entity.Id,
            entity.CustomerName,
            entity.Amount,
            entity.CreatedUtc,
            entity.Status);
    }
}
