## Service implementation

```csharp
using EnterpriseBackend.Application.Abstractions;
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Domain.Entities;

namespace EnterpriseBackend.Application.Services;

public class CustomerService : ICustomerService
{
    private readonly ICustomerRepository _repository;

    public CustomerService(ICustomerRepository repository)
    {
        _repository = repository;
    }

    public async Task<IReadOnlyList<CustomerDto>> GetAllAsync(CancellationToken cancellationToken)
    {
        var customers = await _repository.GetAllAsync(cancellationToken);
        return customers
            .Select(c => new CustomerDto(c.Id, c.ExternalId, c.Name, c.Email, c.CreatedUtc))
            .ToList();
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var customer = await _repository.GetByIdAsync(id, cancellationToken);
        return customer is null
            ? null
            : new CustomerDto(customer.Id, customer.ExternalId, customer.Name, customer.Email, customer.CreatedUtc);
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken)
    {
        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            ExternalId = request.ExternalId,
            Name = request.Name,
            Email = request.Email,
            CreatedUtc = DateTimeOffset.UtcNow
        };

        await _repository.AddAsync(customer, cancellationToken);
        await _repository.SaveChangesAsync(cancellationToken);

        return new CustomerDto(customer.Id, customer.ExternalId, customer.Name, customer.Email, customer.CreatedUtc);
    }
}
```

