# 3. Infrastructure layer

## DbContext

```csharp
using EnterpriseBackend.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Data;

public class AppDbContext : DbContext
{
    public DbSet<Customer> Customers => Set<Customer>();

    public AppDbContext(DbContextOptions<AppDbContext> options)
        : base(options)
    {
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var customer = modelBuilder.Entity<Customer>();

        customer.ToTable("Customers");
        customer.HasKey(x => x.Id);

        customer.Property(x => x.ExternalId)
            .IsRequired()
            .HasMaxLength(100);

        customer.Property(x => x.Name)
            .IsRequired()
            .HasMaxLength(200);

        customer.Property(x => x.Email)
            .IsRequired()
            .HasMaxLength(320);

        customer.Property(x => x.CreatedUtc)
            .IsRequired();

        customer.HasIndex(x => x.ExternalId)
            .IsUnique();

        customer.HasIndex(x => x.Email);
    }
}
```

## Repository implementation

```csharp
using EnterpriseBackend.Application.Abstractions;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Repositories;

public class CustomerRepository : ICustomerRepository
{
    private readonly AppDbContext _dbContext;

    public CustomerRepository(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<Customer?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
    }

    public async Task<IReadOnlyList<Customer>> GetAllAsync(CancellationToken cancellationToken)
    {
        return await _dbContext.Customers
            .AsNoTracking()
            .OrderBy(x => x.Name)
            .ToListAsync(cancellationToken);
    }

    public async Task AddAsync(Customer customer, CancellationToken cancellationToken)
    {
        await _dbContext.Customers.AddAsync(customer, cancellationToken);
    }

    public async Task SaveChangesAsync(CancellationToken cancellationToken)
    {
        await _dbContext.SaveChangesAsync(cancellationToken);
    }
}
