    private readonly ILogger<StatusController> _logger;
    private readonly IConfiguration _configuration;

    public StatusController(
        ITimeService timeService,
        ILogger<StatusController> logger,
        IConfiguration configuration)
    {
        _timeService = timeService;
        _logger = logger;
        _configuration = configuration;
    }

    [HttpGet]
    [ProducesResponseType(typeof(StatusResponse), StatusCodes.Status200OK)]
    public ActionResult<StatusResponse> Get()
    {
        _logger.LogInformation("Status endpoint called at {UtcNow}", _timeService.UtcNow);

        var response = new StatusResponse
        {
            Service = _configuration["ServiceSettings:Name"] ?? "EnterpriseBackend",
            Environment = _configuration["ASPNETCORE_ENVIRONMENT"] ?? "Production",
            Status = "OK",
            UtcTime = _timeService.UtcNow,
            MachineName = Environment.MachineName
        };

        return Ok(response);
    }
}
