using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);

// Add services
builder.Services.AddControllers();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddHealthChecks();

// Azure/App Service friendly logging
builder.Logging.ClearProviders();
builder.Logging.AddConsole();

// Optional CORS policy for enterprise frontend integration
builder.Services.AddCors(options =>
{
    options.AddPolicy("DefaultCors", policy =>
    {
        policy
            .AllowAnyOrigin()
            .AllowAnyHeader()
            .AllowAnyMethod();
    });
});

var app = builder.Build();

// Middleware
app.UseHttpsRedirection();
app.UseCors("DefaultCors");

// Minimal auth placeholder using header check
app.Use(async (context, next) =>
{
    // Skip auth for health checks
    if (context.Request.Path.StartsWithSegments("/health"))
    {
        await next();
        return;
    }

    var expectedApiKey = app.Configuration["API_KEY"];

    if (string.IsNullOrWhiteSpace(expectedApiKey))
    {
        context.Response.StatusCode = 500;
        await context.Response.WriteAsJsonAsync(new
        {
            error = "Server API_KEY is not configured."
        });
        return;
    }

    if (!context.Request.Headers.TryGetValue("X-API-Key", out var providedKey) ||
        providedKey != expectedApiKey)
    {
        context.Response.StatusCode = 401;
        await context.Response.WriteAsJsonAsync(new
        {
            error = "Unauthorized"
        });
        return;
    }

    await next();
});

app.MapControllers();
app.MapHealthChecks("/health");

app.Run();
```

