```rust
use axum::{
    extract::State,
    http::{HeaderMap, StatusCode},
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use serde_json::json;
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Duration,
};
use tokio::net::TcpListener;
use tower::ServiceBuilder;
use tower_http::trace::TraceLayer;
use tracing::{info, Level};

#[derive(Clone)]
struct AppState {
    request_count: Arc<AtomicU64>,
    started_at: std::time::Instant,
}

#[tokio::main]
async fn main() {
    init_tracing();

    let worker_threads = num_cpus::get().max(1);
    info!("detected_cpu_threads={}", worker_threads);

    let state = AppState {
        request_count: Arc::new(AtomicU64::new(0)),
        started_at: std::time::Instant::now(),
    };

    let app = Router::new()
        .route("/", get(root))
        .route("/health", get(health))
        .route("/stats", get(stats))
        .with_state(state)
        .layer(
            ServiceBuilder::new()
                .layer(TraceLayer::new_for_http())
                .timeout(Duration::from_secs(10)),
        );

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();
    let listener = TcpListener::bind(addr).await.unwrap();

    info!("server_listening_on={}", addr);

    axum::serve(
        listener,
        app.into_make_service_with_connect_info::<SocketAddr>(),
    )
    .await
    .unwrap();
}

fn init_tracing() {
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info,tower_http=info".into()),
        )
        .init();
}

async fn root(State(state): State<AppState>, headers: HeaderMap) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let user_agent = headers
        .get("user-agent")
        .and_then(|h| h.to_str().ok())
        .unwrap_or("unknown");

    let body = json!({
        "message": "hello",
        "user_agent": user_agent,
    });

    (StatusCode::OK, Json(body))
}

async fn health(State(state): State<AppState>) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    (
        StatusCode::OK,
        Json(json!({
            "status": "ok"
        })),
    )
}

async fn stats(State(state): State<AppState>) -> impl IntoResponse {
    state.request_count.fetch_add(1, Ordering::Relaxed);

    let uptime_secs = state.started_at.elapsed().as_secs();
    let total_requests = state.request_count.load(Ordering::Relaxed);

    (
        StatusCode::OK,
        Json(json!({
            "uptime_seconds": uptime_secs,
            "total_requests": total_requests
        })),
    )
}
```

